thread_local CudaTimingLedger* g_cuda_timing_sink = nullptr;
thread_local bool g_cuda_instrumentation_enabled = true;

struct HostPhaseFrame {
  CudaPhaseTiming* phase = nullptr;
  std::chrono::steady_clock::time_point resumed_at;
};

thread_local std::vector<HostPhaseFrame> g_cuda_host_phase_stack;

