  uint64_t layer_a = 0;
  uint64_t layer_b = 0;
  uint64_t layer_c = 0;
  uint64_t cost = 0;
  uint64_t build_cuda_layer_a_inputs = 0;
  uint64_t build_cost_order = 0;
};

thread_local CudaSolveCallCounters* g_cuda_solve_call_counters = nullptr;
