thread_local bool g_state_update_status_override_consumed = false;

class ScopedStateUpdateStatusOverrideForTesting {
 public:
  explicit ScopedStateUpdateStatusOverrideForTesting(const uint32_t status)
      : previous_status_(g_state_update_status_override_for_testing),
        previous_consumed_(g_state_update_status_override_consumed) {
    g_state_update_status_override_for_testing = status;
    g_state_update_status_override_consumed = false;
  }
  ~ScopedStateUpdateStatusOverrideForTesting() {
    g_state_update_status_override_for_testing = previous_status_;
    g_state_update_status_override_consumed = previous_consumed_;
  }

 private:
  uint32_t previous_status_ = 0;
  bool previous_consumed_ = false;
};

uint64_t SaturatingAdd(uint64_t lhs, uint64_t rhs);

bool ProfileAtLeast(const CudaExecutionProfile value,
                    const CudaExecutionProfile required) noexcept {
  return static_cast<uint8_t>(value) >= static_cast<uint8_t>(required);
}

bool ShouldLaunchMixedDenseSchurKernels(
    const size_t pose_dimension) noexcept {
  return pose_dimension != 0;
}

class TimingLedgerScope {
 public:
  explicit TimingLedgerScope(CudaTimingLedger* ledger)
      : previous_(g_cuda_timing_sink) {
    if (g_cuda_instrumentation_enabled && previous_ == nullptr &&
        ledger != nullptr) {
      g_cuda_timing_sink = ledger;
      owns_ = true;
    }
  }
  ~TimingLedgerScope() {
    if (owns_) g_cuda_timing_sink = previous_;
  }

 private:
  CudaTimingLedger* previous_ = nullptr;
  bool owns_ = false;
};

class InstrumentationControlScope {
 public:
  explicit InstrumentationControlScope(const bool enabled)
      : previous_(g_cuda_instrumentation_enabled) {
    g_cuda_instrumentation_enabled = enabled;
  }
  ~InstrumentationControlScope() {
    g_cuda_instrumentation_enabled = previous_;
  }

 private:
  bool previous_ = true;
};

class SolveCallCounterScope {
 public:
  explicit SolveCallCounterScope(CudaSolveCallCounters* counters)
      : previous_(g_cuda_solve_call_counters) {
    g_cuda_solve_call_counters = counters;
  }
  ~SolveCallCounterScope() { g_cuda_solve_call_counters = previous_; }

 private:
  CudaSolveCallCounters* previous_ = nullptr;
};

class HostPhaseScope {
 public:
  HostPhaseScope(CudaPhaseTiming* phase, const uint64_t bytes = 0)
      : phase_(phase), bytes_(bytes) {
    if (phase_ == nullptr) return;
    const auto now = std::chrono::steady_clock::now();
    if (!g_cuda_host_phase_stack.empty()) {
      HostPhaseFrame& parent = g_cuda_host_phase_stack.back();
      parent.phase->host_wall_milliseconds +=
          std::chrono::duration<double, std::milli>(now - parent.resumed_at)
              .count();
    }
    g_cuda_host_phase_stack.push_back({phase_, now});
    active_ = true;
  }
  ~HostPhaseScope() { Stop(); }

  void Stop() {
    if (!active_) return;
    const auto now = std::chrono::steady_clock::now();
    HostPhaseFrame& current = g_cuda_host_phase_stack.back();
    current.phase->host_wall_milliseconds +=
        std::chrono::duration<double, std::milli>(now - current.resumed_at)
            .count();
    g_cuda_host_phase_stack.pop_back();
    ++phase_->calls;
    phase_->bytes = SaturatingAdd(phase_->bytes, bytes_);
    if (!g_cuda_host_phase_stack.empty()) {
      g_cuda_host_phase_stack.back().resumed_at = now;
    }
    active_ = false;
  }

 private:
  CudaPhaseTiming* phase_ = nullptr;
  uint64_t bytes_ = 0;
  bool active_ = false;
};

class InclusiveCallScope {
 public:
  explicit InclusiveCallScope(CudaPhaseTiming* phase) : phase_(phase) {
    if (phase_ != nullptr) {
      start_ = std::chrono::steady_clock::now();
      active_ = true;
    }
  }
  ~InclusiveCallScope() {
    if (!active_) return;
    phase_->host_wall_milliseconds +=
        std::chrono::duration<double, std::milli>(
            std::chrono::steady_clock::now() - start_)
            .count();
    ++phase_->calls;
  }

 private:
  CudaPhaseTiming* phase_ = nullptr;
  std::chrono::steady_clock::time_point start_;
  bool active_ = false;
};

void RecordCudaEvent(CudaPhaseTiming* phase, const double milliseconds) {
  if (phase != nullptr && std::isfinite(milliseconds)) {
    phase->cuda_event_milliseconds += milliseconds;
    ++phase->calls;
  }
}

void AccumulateCudaEvent(CudaPhaseTiming* phase, const double milliseconds) {
  if (phase != nullptr && std::isfinite(milliseconds)) {
    phase->cuda_event_milliseconds += milliseconds;
  }
}

void RecordExplicitCall(CudaPhaseTiming* phase, const uint64_t bytes = 0) {
  if (phase == nullptr) return;
  ++phase->calls;
  phase->bytes = SaturatingAdd(phase->bytes, bytes);
}

#define CUDA_TIMING_PHASE(name) \
  (g_cuda_timing_sink == nullptr ? nullptr : \
   &g_cuda_timing_sink->name)

enum class CudaSyncSite : uint8_t {
  kLayerAFinal,
  kLayerBFinal,
  kLayerCFactor,
  kLayerCSolver,
  kLayerCFinal,
  kTrialCostFinal,
  kResourceRelease,
};

CudaSyncSiteTiming* SyncSiteTiming(CudaSynchronizationAudit* audit,
                                   const CudaSyncSite site) {
  if (audit == nullptr) return nullptr;
  switch (site) {
    case CudaSyncSite::kLayerAFinal: return &audit->layer_a_final;
    case CudaSyncSite::kLayerBFinal: return &audit->layer_b_final;
    case CudaSyncSite::kLayerCFactor: return &audit->layer_c_factor;
    case CudaSyncSite::kLayerCSolver: return &audit->layer_c_solver;
    case CudaSyncSite::kLayerCFinal: return &audit->layer_c_final;
    case CudaSyncSite::kTrialCostFinal: return &audit->trial_cost_final;
    case CudaSyncSite::kResourceRelease: return &audit->resource_release;
  }
  return nullptr;
}

cudaError_t TimedCudaStreamSynchronize(cudaStream_t stream,
                                       const CudaSyncSite site) {
  if (g_cuda_timing_sink == nullptr) return cudaStreamSynchronize(stream);
  HostPhaseScope phase(&g_cuda_timing_sink->synchronization);
  const auto start = std::chrono::steady_clock::now();
  const cudaError_t status = cudaStreamSynchronize(stream);
  const double elapsed = std::chrono::duration<double, std::milli>(
                             std::chrono::steady_clock::now() - start)
                             .count();
  CudaSynchronizationAudit& audit =
      g_cuda_timing_sink->synchronization_audit;
  ++audit.stream_synchronize_calls;
  audit.stream_host_wait_milliseconds += elapsed;
  CudaSyncSiteTiming* site_timing = SyncSiteTiming(&audit, site);
  if (site_timing != nullptr) {
    ++site_timing->calls;
    site_timing->host_wait_milliseconds += elapsed;
  }
  return status;
}

void HashByte(uint64_t* state, const uint8_t value) {
  *state ^= value;
  *state *= 1099511628211ull;
}

void HashWord(uint64_t* state, const uint64_t value) {
  for (int shift = 0; shift < 64; shift += 8)
    HashByte(state, static_cast<uint8_t>((value >> shift) & 0xffu));
}

void HashDouble(uint64_t* state, const double value) {
  uint64_t bits = 0;
  static_assert(sizeof(bits) == sizeof(value), "FP64 must be IEEE-754 sized");
  std::memcpy(&bits, &value, sizeof(bits));
  HashWord(state, bits);
}

std::string HashHex(const uint64_t value) {
  std::ostringstream stream;
  stream << std::hex << std::setfill('0') << std::setw(16) << value;
  return stream.str();
}

void HashTag(uint64_t* state, const uint64_t tag) { HashWord(state, tag); }

const ImageSnapshot* FindImageLegacy(const Snapshot& snapshot,
                                     const uint32_t id) {
  for (const ImageSnapshot& image : snapshot.images)
    if (image.image_id == id) return &image;
  return nullptr;
}

const PointSnapshot* FindPointLegacy(const Snapshot& snapshot,
                                     const uint64_t id) {
  for (const PointSnapshot& point : snapshot.points)
    if (point.point3D_id == id) return &point;
  return nullptr;
}

const CameraSnapshot* FindCameraLegacy(const Snapshot& snapshot,
                                       const uint32_t id) {
  for (const CameraSnapshot& camera : snapshot.cameras)
    if (camera.camera_id == id) return &camera;
  return nullptr;
}

// Hash parameter blocks in the exact source order. Every scalar is fed as its
// raw IEEE-754 bits; no C++ object layout or padding is included.
std::string LegacyStateHash(const Snapshot& snapshot) {
  uint64_t state = 1469598103934665603ull;
  HashTag(&state, 0x53544154455f5037ull);
  for (const ParameterBlockSnapshot& block :
       snapshot.parameter_blocks_source_order) {
    HashWord(&state, block.source_index);
    HashWord(&state, static_cast<uint64_t>(block.kind));
    HashWord(&state, block.entity_id);
    HashWord(&state, block.ambient_size);
    HashWord(&state, block.tangent_size);
    HashWord(&state, block.constant ? 1u : 0u);
    if (block.kind == ParameterKind::kQuaternion ||
        block.kind == ParameterKind::kTranslation) {
      const ImageSnapshot* image =
          FindImageLegacy(snapshot, static_cast<uint32_t>(block.entity_id));
      if (image != nullptr) {
        if (block.kind == ParameterKind::kQuaternion) {
          for (double value : image->qvec) HashDouble(&state, value);
        } else {
          for (double value : image->tvec) HashDouble(&state, value);
        }
      }
    } else if (block.kind == ParameterKind::kPoint3D) {
      const PointSnapshot* point = FindPointLegacy(snapshot, block.entity_id);
      if (point != nullptr)
        for (double value : point->xyz) HashDouble(&state, value);
    } else if (block.kind == ParameterKind::kCamera) {
      const CameraSnapshot* camera =
          FindCameraLegacy(snapshot, static_cast<uint32_t>(block.entity_id));
      if (camera != nullptr)
        for (double value : camera->params) HashDouble(&state, value);
    }
  }
  return HashHex(state);
}

struct StateHashLayoutEntry {
  uint64_t source_index = 0;
  ParameterKind kind = ParameterKind::kPoint3D;
  uint64_t entity_id = 0;
  uint32_t ambient_size = 0;
  uint32_t tangent_size = 0;
  bool constant = false;
  size_t vector_index = 0;
};

struct StateHashLayout {
  std::vector<StateHashLayoutEntry> blocks;
};

bool BuildStateHashLayout(const Snapshot& snapshot,
                          StateHashLayout* layout,
                          CudaStateHashAudit* audit,
                          std::string* error) {
  if (layout == nullptr || audit == nullptr || error == nullptr) return false;
  const auto start = std::chrono::steady_clock::now();
  HostPhaseScope phase(CUDA_TIMING_PHASE(state_hash));
  layout->blocks.clear();
  std::unordered_map<uint32_t, size_t> images;
  std::unordered_map<uint64_t, size_t> points;
  std::unordered_map<uint32_t, size_t> cameras;
  for (size_t i = 0; i < snapshot.images.size(); ++i) {
    if (!images.emplace(snapshot.images[i].image_id, i).second) {
      *error = "StateHashLayout contains duplicate image id";
      return false;
    }
  }
  for (size_t i = 0; i < snapshot.points.size(); ++i) {
    if (!points.emplace(snapshot.points[i].point3D_id, i).second) {
      *error = "StateHashLayout contains duplicate point id";
      return false;
    }
  }
  for (size_t i = 0; i < snapshot.cameras.size(); ++i) {
    if (!cameras.emplace(snapshot.cameras[i].camera_id, i).second) {
      *error = "StateHashLayout contains duplicate camera id";
      return false;
    }
  }
  std::set<std::pair<uint8_t, uint64_t>> parameter_entities;
  layout->blocks.reserve(snapshot.parameter_blocks_source_order.size());
  for (const ParameterBlockSnapshot& block :
       snapshot.parameter_blocks_source_order) {
    const std::pair<uint8_t, uint64_t> key(
        static_cast<uint8_t>(block.kind), block.entity_id);
    if (!parameter_entities.insert(key).second) {
      *error = "StateHashLayout contains a duplicate parameter entity";
      return false;
    }
    StateHashLayoutEntry entry;
    entry.source_index = block.source_index;
    entry.kind = block.kind;
    entry.entity_id = block.entity_id;
    entry.ambient_size = block.ambient_size;
    entry.tangent_size = block.tangent_size;
    entry.constant = block.constant;
    if (block.kind == ParameterKind::kQuaternion ||
        block.kind == ParameterKind::kTranslation) {
      const auto it = images.find(static_cast<uint32_t>(block.entity_id));
      if (it == images.end()) {
        *error = "StateHashLayout parameter references a missing image";
        return false;
      }
      entry.vector_index = it->second;
    } else if (block.kind == ParameterKind::kPoint3D) {
      const auto it = points.find(block.entity_id);
      if (it == points.end()) {
        *error = "StateHashLayout parameter references a missing point";
        return false;
      }
      entry.vector_index = it->second;
    } else if (block.kind == ParameterKind::kCamera) {
      const auto it = cameras.find(static_cast<uint32_t>(block.entity_id));
      if (it == cameras.end()) {
        *error = "StateHashLayout parameter references a missing camera";
        return false;
      }
      entry.vector_index = it->second;
    } else {
      *error = "StateHashLayout encountered an unsupported parameter kind";
      return false;
    }
    layout->blocks.push_back(entry);
  }
  ++audit->layout_builds;
  audit->layout_blocks += layout->blocks.size();
  audit->layout_host_wall_milliseconds +=
      std::chrono::duration<double, std::milli>(
          std::chrono::steady_clock::now() - start)
          .count();
  return true;
}

bool LinearStateHash(const Snapshot& snapshot,
                     const StateHashLayout& layout,
                     CudaStateHashCounter* counter,
                     std::string* digest,
                     std::string* error) {
  if (counter == nullptr || digest == nullptr || error == nullptr) return false;
  const auto start = std::chrono::steady_clock::now();
  HostPhaseScope phase(CUDA_TIMING_PHASE(state_hash));
  uint64_t state = 1469598103934665603ull;
  HashTag(&state, 0x53544154455f5037ull);
  for (const StateHashLayoutEntry& block : layout.blocks) {
    ++counter->blocks_visited;
    HashWord(&state, block.source_index);
    HashWord(&state, static_cast<uint64_t>(block.kind));
    HashWord(&state, block.entity_id);
    HashWord(&state, block.ambient_size);
    HashWord(&state, block.tangent_size);
    HashWord(&state, block.constant ? 1u : 0u);
    if (block.kind == ParameterKind::kQuaternion ||
        block.kind == ParameterKind::kTranslation) {
      if (block.vector_index >= snapshot.images.size() ||
          snapshot.images[block.vector_index].image_id != block.entity_id) {
        *error = "StateHashLayout image index no longer matches its entity";
        return false;
      }
      const ImageSnapshot& image = snapshot.images[block.vector_index];
      if (block.kind == ParameterKind::kQuaternion) {
        for (double value : image.qvec) {
          HashDouble(&state, value);
          ++counter->scalars_hashed;
        }
      } else {
        for (double value : image.tvec) {
          HashDouble(&state, value);
          ++counter->scalars_hashed;
        }
      }
    } else if (block.kind == ParameterKind::kPoint3D) {
      if (block.vector_index >= snapshot.points.size() ||
          snapshot.points[block.vector_index].point3D_id != block.entity_id) {
        *error = "StateHashLayout point index no longer matches its entity";
        return false;
      }
      for (double value : snapshot.points[block.vector_index].xyz) {
        HashDouble(&state, value);
        ++counter->scalars_hashed;
      }
    } else {
      if (block.vector_index >= snapshot.cameras.size() ||
          snapshot.cameras[block.vector_index].camera_id != block.entity_id) {
        *error = "StateHashLayout camera index no longer matches its entity";
        return false;
      }
      for (double value : snapshot.cameras[block.vector_index].params) {
        HashDouble(&state, value);
        ++counter->scalars_hashed;
      }
    }
  }
  *digest = HashHex(state);
  ++counter->computations;
  counter->host_wall_milliseconds +=
      std::chrono::duration<double, std::milli>(
          std::chrono::steady_clock::now() - start)
          .count();
  return true;
}

class StateHashController {
 public:
  StateHashController(const bool enabled, CudaStateHashAudit* audit)
      : enabled_(enabled), audit_(audit) {}

  bool Initialize(const Snapshot& snapshot, std::string* error) {
    if (!enabled_) return true;
    if (!BuildStateHashLayout(snapshot, &layout_, audit_, error)) return false;
    return Current(snapshot, &current_digest_, error);
  }

  bool Current(const Snapshot& snapshot,
               std::string* digest,
               std::string* error) {
    if (!enabled_) {
      digest->clear();
      return true;
    }
    ++audit_->current.requests;
    if (!current_digest_.empty()) {
      ++audit_->current.cache_hits;
      *digest = current_digest_;
      return true;
    }
    if (!LinearStateHash(snapshot, layout_, &audit_->current,
                         &current_digest_, error)) {
      return false;
    }
    *digest = current_digest_;
    return true;
  }

  bool Trial(const Snapshot& snapshot,
             std::string* digest,
             std::string* error) {
    if (!enabled_) {
      digest->clear();
      return true;
    }
    ++audit_->trial.requests;
    return LinearStateHash(snapshot, layout_, &audit_->trial, digest, error);
  }

  void PromoteTrial(std::string&& trial_digest) noexcept {
    if (enabled_) current_digest_.swap(trial_digest);
  }

 private:
  bool enabled_ = false;
  CudaStateHashAudit* audit_ = nullptr;
  StateHashLayout layout_;
  std::string current_digest_;
};

struct CachedCudaAllocation {
  void* pointer = nullptr;
  size_t bytes = 0;
  CudaMemoryMode mode = CudaMemoryMode::kExplicitDeviceCopy;
  int device = -1;
  uintptr_t context = 0;
};

struct CudaCacheKey {
  int device = -1;
  uintptr_t context = 0;
  bool valid = false;
};

bool SameCudaCacheKey(const CudaCacheKey& lhs, const CudaCacheKey& rhs) {
  return lhs.valid && rhs.valid && lhs.device == rhs.device &&
         lhs.context == rhs.context;
}

uint64_t SaturatingAdd(const uint64_t lhs, const uint64_t rhs) {
  if (rhs > std::numeric_limits<uint64_t>::max() - lhs) {
    return std::numeric_limits<uint64_t>::max();
  }
  return lhs + rhs;
}

uint64_t ResidentPeakBytes(const uint64_t active_bytes,
                           const uint64_t cached_bytes,
                           const uint64_t additional_bytes) {
  return SaturatingAdd(SaturatingAdd(active_bytes, cached_bytes),
                       additional_bytes);
}

bool HasCudaMemoryHeadroom(const uint64_t free_bytes,
                           const uint64_t additional_bytes,
                           const uint64_t reserve_bytes) {
  // cudaMemGetInfo already excludes active and cached device allocations.
  return additional_bytes <= free_bytes &&
         reserve_bytes <= free_bytes - additional_bytes;
}

struct CachedCudaStream {
  cudaStream_t handle = nullptr;
  CudaCacheKey key;
};

struct CachedCudaEvent {
  cudaEvent_t handle = nullptr;
  CudaCacheKey key;
};

struct CachedCudaSolver {
  cusolverDnHandle_t handle = nullptr;
  CudaCacheKey key;
};

struct CachedCudaBlas {
  cublasHandle_t handle = nullptr;
  CudaCacheKey key;
};

