struct CudaResourceOwnershipEntry {
  uintptr_t handle = 0;
  CudaTeardownType type = CudaTeardownType::kAllocation;
  int32_t device = -1;
  uint64_t creation_sequence = 0;
  bool active = false;
  bool quarantined = false;
  bool pool_retained = false;
};

std::array<CudaResourceOwnershipEntry, kCudaResourceRegistryCapacity>
    g_cuda_resource_registry{};
uint64_t g_cuda_resource_registry_count = 0;

bool RegisterCudaResource(const uintptr_t handle,
                          const CudaTeardownType type,
                          const int32_t device) noexcept {
  if (handle == 0) return true;
  for (uint64_t i = 0; i < g_cuda_resource_registry_count; ++i) {
    CudaResourceOwnershipEntry& entry =
        g_cuda_resource_registry[static_cast<size_t>(i)];
    if (entry.handle == handle && entry.type == type && entry.active) {
      return true;
    }
  }
  const uint64_t capacity = g_cuda_active_audit_runtime == nullptr
      ? kCudaResourceRegistryCapacity
      : std::min<uint64_t>(
            g_cuda_active_audit_runtime->resource_registry_capacity,
            g_cuda_resource_registry.size());
  if (g_cuda_resource_registry_count >= capacity) {
    if (g_cuda_active_audit_runtime != nullptr) {
      ++g_cuda_active_audit_runtime->audit_overflow_count;
      if (!g_cuda_active_audit_runtime->has_first_audit_overflow_site) {
        g_cuda_active_audit_runtime->has_first_audit_overflow_site = true;
        g_cuda_active_audit_runtime->first_audit_overflow_site =
            CudaFailureSite::kAuditRuntimeOverflow;
      }
    }
    return false;
  }
  CudaResourceOwnershipEntry& entry = g_cuda_resource_registry[
      static_cast<size_t>(g_cuda_resource_registry_count++)];
  entry.handle = handle;
  entry.type = type;
  entry.device = device;
  entry.creation_sequence = ++g_cuda_resource_creation_sequence;
  entry.active = true;
  entry.quarantined = false;
  entry.pool_retained = false;
  return true;
}

CudaResourceOwnershipEntry* FindCudaResource(
    const uintptr_t handle,
    const CudaTeardownType type) noexcept {
  for (uint64_t i = 0; i < g_cuda_resource_registry_count; ++i) {
    CudaResourceOwnershipEntry& entry =
        g_cuda_resource_registry[static_cast<size_t>(i)];
    if (entry.handle == handle && entry.type == type && entry.active) {
      return &entry;
    }
  }
  return nullptr;
}

bool MarkCudaResourcePoolRetained(const uintptr_t handle,
                                  const CudaTeardownType type) noexcept {
  CudaResourceOwnershipEntry* entry = FindCudaResource(handle, type);
  if (entry == nullptr) return false;
  entry->pool_retained = true;
  return true;
}

bool ShouldInjectCleanupFailure(const CudaTeardownType type) noexcept {
  if (!g_cuda_cleanup_test_injection_active ||
      g_cuda_cleanup_test_injection_consumed ||
      g_cuda_cleanup_test_injection_type != type) {
    return false;
  }
  g_cuda_cleanup_test_injection_consumed = true;
  return true;
}

CudaFailureSite CleanupFailureSite(const CudaTeardownType type) noexcept {
  switch (type) {
    case CudaTeardownType::kGetDevice:
      return CudaFailureSite::kCleanupGetDevice;
    case CudaTeardownType::kSetDevice:
      return CudaFailureSite::kCleanupSetDevice;
    case CudaTeardownType::kSolver:
      return CudaFailureSite::kDestroySolver;
    case CudaTeardownType::kBlas:
      return CudaFailureSite::kDestroyBlas;
    case CudaTeardownType::kEvent:
      return CudaFailureSite::kDestroyEvent;
    case CudaTeardownType::kStream:
      return CudaFailureSite::kDestroyStream;
    case CudaTeardownType::kAllocation:
      return CudaFailureSite::kDestroyAllocation;
  }
  return CudaFailureSite::kDestroyAllocation;
}

void RecordCleanupResult(const CudaTeardownType type,
                         const CudaStatusDomain domain,
                         const int64_t raw_status,
                         const uintptr_t handle,
                         const int32_t device) noexcept {
  CudaResourceOwnershipEntry* ownership = FindCudaResource(handle, type);
  const bool success = raw_status == 0;
  if (ownership != nullptr) {
    if (success) {
      ownership->active = false;
    } else {
      ownership->quarantined = true;
    }
  }
  CudaFullLmRuntimeInfo* runtime = g_cuda_active_audit_runtime;
  if (runtime != nullptr) {
    const size_t index = static_cast<size_t>(type);
    CudaTeardownRecordV2& record = runtime->teardown_records[index];
    if (!record.attempted) {
      record.teardown_type = type;
      record.device = device;
      record.creation_sequence =
          ownership == nullptr ? 0 : ownership->creation_sequence;
      record.success = true;
    }
    record.attempted = true;
    record.success = record.success && success;
    record.status_domain = domain;
    record.raw_status_code = raw_status;
    record.quarantined = record.quarantined || !success;
    runtime->teardown_record_count = kCudaTeardownRecordCapacity;
    if (!success) {
      ++runtime->resource_quarantine_count;
      runtime->resource_cleanup_complete = false;
      if (!runtime->has_first_cleanup_failure) {
        runtime->has_first_cleanup_failure = true;
        runtime->first_cleanup_failure.error_classification =
            CudaSolveErrorClass::kResourceCleanup;
        runtime->first_cleanup_failure.failure_site = CleanupFailureSite(type);
        runtime->first_cleanup_failure.status_domain = domain;
        runtime->first_cleanup_failure.raw_status_code = raw_status;
      }
    }
  }
  if (!success) {
    g_cuda_resource_health = CudaResourceHealth::kTainted;
    g_cuda_taint_cleanup_complete = false;
  }
}

cudaError_t CleanupCudaGetDevice(int* device) noexcept {
  const cudaError_t status = ShouldInjectCleanupFailure(
      CudaTeardownType::kGetDevice) ? cudaErrorUnknown
                                    : cudaGetDevice(device);
  RecordCleanupResult(CudaTeardownType::kGetDevice,
                      CudaStatusDomain::kCudaRuntime,
                      static_cast<int64_t>(status), 0,
                      status == cudaSuccess && device != nullptr ? *device
                                                                 : -1);
  return status;
}

cudaError_t CleanupCudaSetDevice(const int device) noexcept {
  const cudaError_t status = ShouldInjectCleanupFailure(
      CudaTeardownType::kSetDevice) ? cudaErrorUnknown
                                    : cudaSetDevice(device);
  RecordCleanupResult(CudaTeardownType::kSetDevice,
                      CudaStatusDomain::kCudaRuntime,
                      static_cast<int64_t>(status), 0, device);
  return status;
}

cudaError_t CleanupCudaFree(void* pointer, const int device) noexcept {
  const cudaError_t status = ShouldInjectCleanupFailure(
      CudaTeardownType::kAllocation) ? cudaErrorUnknown : cudaFree(pointer);
  RecordCleanupResult(CudaTeardownType::kAllocation,
                      CudaStatusDomain::kCudaRuntime,
                      static_cast<int64_t>(status),
                      reinterpret_cast<uintptr_t>(pointer), device);
  return status;
}

cudaError_t CleanupCudaStreamDestroy(cudaStream_t stream,
                                     const int device) noexcept {
  const cudaError_t status = ShouldInjectCleanupFailure(
      CudaTeardownType::kStream) ? cudaErrorUnknown
                                 : cudaStreamDestroy(stream);
  RecordCleanupResult(CudaTeardownType::kStream,
                      CudaStatusDomain::kCudaRuntime,
                      static_cast<int64_t>(status),
                      reinterpret_cast<uintptr_t>(stream), device);
  return status;
}

cudaError_t CleanupCudaEventDestroy(cudaEvent_t event,
                                    const int device) noexcept {
  const cudaError_t status = ShouldInjectCleanupFailure(
      CudaTeardownType::kEvent) ? cudaErrorUnknown : cudaEventDestroy(event);
  RecordCleanupResult(CudaTeardownType::kEvent,
                      CudaStatusDomain::kCudaRuntime,
                      static_cast<int64_t>(status),
                      reinterpret_cast<uintptr_t>(event), device);
  return status;
}

cusolverStatus_t CleanupCudaSolverDestroy(cusolverDnHandle_t handle,
                                          const int device) noexcept {
  const cusolverStatus_t status = ShouldInjectCleanupFailure(
      CudaTeardownType::kSolver) ? CUSOLVER_STATUS_INTERNAL_ERROR
                                 : cusolverDnDestroy(handle);
  RecordCleanupResult(CudaTeardownType::kSolver,
                      CudaStatusDomain::kCusolver,
                      static_cast<int64_t>(status),
                      reinterpret_cast<uintptr_t>(handle), device);
  return status;
}

cublasStatus_t CleanupCudaBlasDestroy(cublasHandle_t handle,
                                      const int device) noexcept {
  const cublasStatus_t status = ShouldInjectCleanupFailure(
      CudaTeardownType::kBlas) ? CUBLAS_STATUS_INTERNAL_ERROR
                               : cublasDestroy(handle);
  RecordCleanupResult(CudaTeardownType::kBlas,
                      CudaStatusDomain::kCublas,
                      static_cast<int64_t>(status),
                      reinterpret_cast<uintptr_t>(handle), device);
  return status;
}

struct CudaRuntimePoolEntry {
  int device = -1;
  CudaCacheKey key;
  cudaStream_t stream = nullptr;
  std::array<cudaEvent_t, 20> events{};
  cusolverDnHandle_t solver = nullptr;
  cublasHandle_t blas = nullptr;
  void* arena = nullptr;
  uint64_t arena_capacity = 0;
  uint64_t context_incarnation = 0;
  uint64_t arena_generation = 0;
  PersistentDeviceCatalogState persistent_device_catalog;
  uint64_t lease_generation = 0;
  bool retainable = false;
  bool externally_cleared = false;
};

bool CurrentCudaCacheKey(CudaCacheKey* key);
const char* CudaErrorText(cudaError_t status);

struct CudaRuntimePoolLease {
  std::unique_ptr<CudaRuntimePoolEntry> entry;
  uint64_t generation = 0;
  bool hot = false;

  CudaRuntimePoolLease() = default;
  CudaRuntimePoolLease(const CudaRuntimePoolLease&) = delete;
  CudaRuntimePoolLease& operator=(const CudaRuntimePoolLease&) = delete;
  CudaRuntimePoolLease(CudaRuntimePoolLease&&) noexcept = default;
  CudaRuntimePoolLease& operator=(CudaRuntimePoolLease&&) noexcept = default;
};

std::mutex g_cuda_runtime_pool_mutex;
std::map<int, std::unique_ptr<CudaRuntimePoolEntry>>
    g_cuda_runtime_pool_idle;
std::set<CudaRuntimePoolEntry*> g_cuda_runtime_pool_active;
std::set<int> g_cuda_runtime_pool_poisoned_devices;
std::set<int> g_cuda_runtime_pool_clearing_devices;
std::map<int, uint64_t> g_cuda_runtime_pool_active_by_device;
std::atomic<uint64_t> g_cuda_runtime_pool_next_lease_generation{0};
uint64_t g_cuda_runtime_pool_next_context_incarnation = 0;

bool RegisterPoolResource(const uintptr_t handle,
                          const CudaTeardownType type,
                          const int device) {
  return RegisterCudaResource(handle, type, device) &&
         MarkCudaResourcePoolRetained(handle, type);
}

bool DestroyRuntimePoolEntry(CudaRuntimePoolEntry* entry) noexcept {
  if (entry == nullptr || entry->externally_cleared) return true;
  entry->persistent_device_catalog.Invalidate();
  if (entry->device >= 0 &&
      CleanupCudaSetDevice(entry->device) != cudaSuccess) {
    return false;
  }
  bool success = true;
  if (entry->solver != nullptr) {
    success = CleanupCudaSolverDestroy(entry->solver, entry->device) ==
                  CUSOLVER_STATUS_SUCCESS && success;
    entry->solver = nullptr;
  }
  if (entry->blas != nullptr) {
    success = CleanupCudaBlasDestroy(entry->blas, entry->device) ==
                  CUBLAS_STATUS_SUCCESS && success;
    entry->blas = nullptr;
  }
  for (cudaEvent_t& event : entry->events) {
    if (event != nullptr) {
      success = CleanupCudaEventDestroy(event, entry->device) == cudaSuccess &&
                success;
      event = nullptr;
    }
  }
  if (entry->stream != nullptr) {
    success = CleanupCudaStreamDestroy(entry->stream, entry->device) ==
                  cudaSuccess && success;
    entry->stream = nullptr;
  }
  if (entry->arena != nullptr) {
    success = CleanupCudaFree(entry->arena, entry->device) == cudaSuccess &&
              success;
    entry->arena = nullptr;
    entry->arena_capacity = 0;
  }
  return success;
}

bool CreateRuntimePoolEntry(const int device,
                            const bool retainable,
                            CudaRuntimePoolEntry* entry,
                            std::string* error) {
  if (entry == nullptr || error == nullptr) return false;
  if (g_cuda_runtime_pool_next_context_incarnation ==
      std::numeric_limits<uint64_t>::max()) {
    *error = "RuntimePool CUDA context incarnation exhausted";
    return false;
  }
  entry->device = device;
  entry->retainable = retainable;
  entry->context_incarnation =
      ++g_cuda_runtime_pool_next_context_incarnation;
  entry->arena_generation = 0;
  entry->persistent_device_catalog.Invalidate();
  if (cudaSetDevice(device) != cudaSuccess ||
      !CurrentCudaCacheKey(&entry->key) || !entry->key.valid ||
      entry->key.device != device) {
    *error = "RuntimePool CUDA device/context query failed";
    return false;
  }
  cudaError_t cuda_status =
      cudaStreamCreateWithFlags(&entry->stream, cudaStreamNonBlocking);
  if (cuda_status != cudaSuccess ||
      !RegisterPoolResource(reinterpret_cast<uintptr_t>(entry->stream),
                            CudaTeardownType::kStream, device)) {
    *error = "RuntimePool stream creation failed";
    DestroyRuntimePoolEntry(entry);
    return false;
  }
  for (cudaEvent_t& event : entry->events) {
    cuda_status = cudaEventCreate(&event);
    if (cuda_status != cudaSuccess ||
        !RegisterPoolResource(reinterpret_cast<uintptr_t>(event),
                              CudaTeardownType::kEvent, device)) {
      *error = "RuntimePool event creation failed";
      DestroyRuntimePoolEntry(entry);
      return false;
    }
  }
  cusolverStatus_t solver_status = cusolverDnCreate(&entry->solver);
  if (solver_status != CUSOLVER_STATUS_SUCCESS ||
      !RegisterPoolResource(reinterpret_cast<uintptr_t>(entry->solver),
                            CudaTeardownType::kSolver, device)) {
    *error = "RuntimePool cuSOLVER creation failed";
    DestroyRuntimePoolEntry(entry);
    return false;
  }
  cublasStatus_t blas_status = cublasCreate(&entry->blas);
  if (blas_status != CUBLAS_STATUS_SUCCESS ||
      !RegisterPoolResource(reinterpret_cast<uintptr_t>(entry->blas),
                            CudaTeardownType::kBlas, device)) {
    *error = "RuntimePool cuBLAS creation failed";
    DestroyRuntimePoolEntry(entry);
    return false;
  }
  solver_status = cusolverDnSetStream(entry->solver, entry->stream);
  blas_status = cublasSetStream(entry->blas, entry->stream);
  if (solver_status != CUSOLVER_STATUS_SUCCESS ||
      blas_status != CUBLAS_STATUS_SUCCESS) {
    *error = "RuntimePool handle stream binding failed";
    DestroyRuntimePoolEntry(entry);
    return false;
  }
  return true;
}

bool AcquireRuntimePoolLease(const int device,
                             CudaPersistentDeviceRuntimeInfo* runtime,
                             CudaRuntimePoolLease* lease,
                             std::string* error) {
  if (runtime == nullptr || lease == nullptr || error == nullptr) return false;
  std::lock_guard<std::mutex> lock(g_cuda_runtime_pool_mutex);
  ++runtime->runtime_pool_acquire_calls;
  if (g_cuda_runtime_pool_poisoned_devices.count(device) != 0 ||
      g_cuda_runtime_pool_clearing_devices.count(device) != 0) {
    ++runtime->runtime_pool_poison_count;
    *error = "ResourceCleanup: CUDA RuntimePool device is poisoned";
    return false;
  }
  std::unique_ptr<CudaRuntimePoolEntry> entry;
  auto idle = g_cuda_runtime_pool_idle.find(device);
  if (idle != g_cuda_runtime_pool_idle.end()) {
    entry = std::move(idle->second);
    g_cuda_runtime_pool_idle.erase(idle);
    lease->hot = true;
    ++runtime->runtime_pool_hot_leases;
  } else {
    const bool retainable = g_cuda_runtime_pool_active_by_device[device] == 0;
    entry.reset(new CudaRuntimePoolEntry());
    if (!CreateRuntimePoolEntry(device, retainable, entry.get(), error)) {
      return false;
    }
    ++runtime->runtime_pool_cold_creates;
  }
  lease->generation =
      ++g_cuda_runtime_pool_next_lease_generation;
  if (lease->generation == 0)
    lease->generation = ++g_cuda_runtime_pool_next_lease_generation;
  entry->lease_generation = lease->generation;
  runtime->runtime_pool_lease_generation = lease->generation;
  runtime->arena_capacity_bytes = entry->arena_capacity;
  ++g_cuda_runtime_pool_active_by_device[device];
  g_cuda_runtime_pool_active.insert(entry.get());
  lease->entry = std::move(entry);
  return true;
}

bool EnsureRuntimePoolArena(CudaRuntimePoolLease* lease,
                            const uint64_t required,
                            CudaPersistentDeviceRuntimeInfo* runtime,
                            std::string* error) {
  if (lease == nullptr || lease->entry == nullptr || runtime == nullptr ||
      error == nullptr || required == 0) {
    if (error != nullptr) *error = "RuntimePool arena request is invalid";
    return false;
  }
  CudaRuntimePoolEntry& entry = *lease->entry;
  runtime->arena_required_bytes = required;
  if (entry.arena_capacity >= required) {
    runtime->arena_capacity_bytes = entry.arena_capacity;
    runtime->arena_retained_bytes = entry.arena_capacity;
    return true;
  }
  constexpr uint64_t kArenaQuantum = 4ull * 1024ull * 1024ull;
  if (required > std::numeric_limits<uint64_t>::max() -
                     (kArenaQuantum - 1)) {
    *error = "RuntimePool arena capacity overflow";
    return false;
  }
  const uint64_t capacity =
      ((required + kArenaQuantum - 1) / kArenaQuantum) * kArenaQuantum;
  if (entry.arena_generation == std::numeric_limits<uint64_t>::max()) {
    *error = "RuntimePool arena generation exhausted";
    return false;
  }
  size_t free_bytes = 0;
  size_t total_bytes = 0;
  if (cudaMemGetInfo(&free_bytes, &total_bytes) != cudaSuccess ||
      !HasCudaMemoryHeadroom(free_bytes, capacity,
                             512ull * 1024ull * 1024ull)) {
    *error = "INSUFFICIENT_GPU_MEMORY for RuntimePool arena";
    return false;
  }
  void* replacement = nullptr;
  const cudaError_t allocation_status = cudaMalloc(&replacement, capacity);
  if (allocation_status != cudaSuccess ||
      !RegisterPoolResource(reinterpret_cast<uintptr_t>(replacement),
                            CudaTeardownType::kAllocation, entry.device)) {
    if (allocation_status == cudaSuccess) {
      CleanupCudaFree(replacement, entry.device);
    }
    *error = std::string("RuntimePool arena allocation failed: ") +
             CudaErrorText(allocation_status);
    return false;
  }
  void* previous = entry.arena;
  const uint64_t previous_capacity = entry.arena_capacity;
  const bool invalidated_catalog = entry.persistent_device_catalog.valid();
  entry.arena = replacement;
  entry.arena_capacity = capacity;
  ++entry.arena_generation;
  entry.persistent_device_catalog.Invalidate();
  if (invalidated_catalog) ++runtime->indexed_device_catalog_invalidations;
  ++runtime->arena_grow_calls;
  runtime->arena_grow_bytes = SaturatingAdd(runtime->arena_grow_bytes,
                                             capacity);
  if (previous != nullptr &&
      CleanupCudaFree(previous, entry.device) != cudaSuccess) {
    entry.arena = replacement;
    entry.arena_capacity = capacity;
    *error = "ResourceCleanup: RuntimePool arena replacement cleanup failed";
    return false;
  }
  (void)previous_capacity;
  runtime->arena_capacity_bytes = capacity;
  runtime->arena_retained_bytes = capacity;
  return true;
}

struct IndexedDeviceCatalogView {
  const MapperCatalogCameraSlot* cameras = nullptr;
  const MapperCatalogImageSlot* images = nullptr;
  const MapperCatalogPointSlot* points = nullptr;
  const MapperCatalogObservationSlot* observations = nullptr;
  const MapperCatalogIncidenceSlot* image_incidences = nullptr;
  const MapperCatalogIncidenceSlot* point_incidences = nullptr;
  uint32_t camera_count = 0;
  uint32_t image_count = 0;
  uint32_t point_count = 0;
  uint32_t observation_count = 0;
  uint32_t image_incidence_count = 0;
  uint32_t point_incidence_count = 0;
  DeviceCatalogPhysicalIdentity identity;
};

bool SameDeviceCatalogLayout(const DeviceCatalogLayout& lhs,
                             const DeviceCatalogLayout& rhs) noexcept {
  const auto same = [](const DeviceCatalogSlice& a,
                       const DeviceCatalogSlice& b) {
    return a.offset == b.offset && a.bytes == b.bytes &&
           a.elements == b.elements;
  };
  return lhs.alignment == rhs.alignment && lhs.begin == rhs.begin &&
         lhs.end == rhs.end && same(lhs.cameras, rhs.cameras) &&
         same(lhs.images, rhs.images) && same(lhs.points, rhs.points) &&
         same(lhs.observations, rhs.observations) &&
         same(lhs.image_incidences, rhs.image_incidences) &&
         same(lhs.point_incidences, rhs.point_incidences);
}

template <typename T>
bool UploadRuntimePoolCatalogVector(
    CudaRuntimePoolEntry* entry,
    const DeviceCatalogSlice& slice,
    const std::vector<T>& source,
    CudaPersistentDeviceRuntimeInfo* runtime,
    std::string* error) {
  if (slice.elements != source.size() ||
      slice.bytes != source.size() * sizeof(T) ||
      slice.offset > entry->arena_capacity ||
      slice.bytes > entry->arena_capacity - slice.offset) {
    *error = "indexed device catalog slice identity is invalid";
    return false;
  }
  if (source.empty()) return true;
  void* destination = static_cast<void*>(
      static_cast<uint8_t*>(entry->arena) + slice.offset);
  const cudaError_t status = cudaMemcpyAsync(
      destination, source.data(), slice.bytes, cudaMemcpyHostToDevice,
      entry->stream);
  if (status != cudaSuccess) {
    *error = std::string("indexed device catalog upload failed: ") +
             CudaErrorText(status);
    return false;
  }
  runtime->indexed_device_catalog_full_upload_bytes = SaturatingAdd(
      runtime->indexed_device_catalog_full_upload_bytes, slice.bytes);
  return true;
}

bool BindRuntimePoolIndexedCatalog(
    CudaRuntimePoolLease* lease,
    const MapperStaticCatalogStableTables& tables,
    const DeviceCatalogLayout& layout,
    CudaPersistentDeviceRuntimeInfo* runtime,
    IndexedDeviceCatalogView* view,
    std::string* error) {
  if (lease == nullptr || lease->entry == nullptr || runtime == nullptr ||
      view == nullptr || error == nullptr || tables.owner_epoch == 0 ||
      tables.catalog_generation == 0) {
    if (error != nullptr) *error = "indexed device catalog bind is invalid";
    return false;
  }
  CudaRuntimePoolEntry& entry = *lease->entry;
  ++runtime->indexed_device_catalog_lookup_calls;
  DeviceCatalogPhysicalIdentity identity;
  identity.device_ordinal = entry.device;
  identity.context_incarnation = entry.context_incarnation;
  identity.owner_epoch = tables.owner_epoch;
  identity.catalog_revision = tables.catalog_revision;
  identity.catalog_generation = tables.catalog_generation;
  identity.arena_generation = entry.arena_generation;
  if (!identity.valid() || layout.end > entry.arena_capacity ||
      layout.end == 0) {
    *error = "indexed device catalog physical identity is invalid";
    return false;
  }

  bool reused = entry.persistent_device_catalog.CanReuse(identity);
  if (!reused &&
      entry.persistent_device_catalog.CanReuseStorage(identity) &&
      SameDeviceCatalogLayout(entry.persistent_device_catalog.layout(),
                              layout)) {
    if (!entry.persistent_device_catalog.Publish(identity, layout, error)) {
      return false;
    }
    reused = true;
    ++runtime->indexed_device_catalog_revision_rebinds;
  }
  if (!reused) {
    const bool uploaded =
        UploadRuntimePoolCatalogVector(&entry, layout.cameras, tables.cameras,
                                       runtime, error) &&
        UploadRuntimePoolCatalogVector(&entry, layout.images, tables.images,
                                       runtime, error) &&
        UploadRuntimePoolCatalogVector(&entry, layout.points, tables.points,
                                       runtime, error) &&
        UploadRuntimePoolCatalogVector(&entry, layout.observations,
                                       tables.observations, runtime, error) &&
        UploadRuntimePoolCatalogVector(&entry, layout.image_incidences,
                                       tables.image_incidences, runtime,
                                       error) &&
        UploadRuntimePoolCatalogVector(&entry, layout.point_incidences,
                                       tables.point_incidences, runtime,
                                       error);
    if (!uploaded ||
        !entry.persistent_device_catalog.Publish(identity, layout, error)) {
      entry.persistent_device_catalog.Invalidate();
      ++runtime->indexed_device_catalog_invalidations;
      return false;
    }
    ++runtime->indexed_device_catalog_full_upload_calls;
  } else {
    ++runtime->indexed_device_catalog_reuse_calls;
  }

  const uint8_t* base = static_cast<const uint8_t*>(entry.arena);
  const auto pointer = [base](const DeviceCatalogSlice& slice) {
    return base + slice.offset;
  };
  view->cameras = reinterpret_cast<const MapperCatalogCameraSlot*>(
      pointer(layout.cameras));
  view->images = reinterpret_cast<const MapperCatalogImageSlot*>(
      pointer(layout.images));
  view->points = reinterpret_cast<const MapperCatalogPointSlot*>(
      pointer(layout.points));
  view->observations = reinterpret_cast<const MapperCatalogObservationSlot*>(
      pointer(layout.observations));
  view->image_incidences =
      reinterpret_cast<const MapperCatalogIncidenceSlot*>(
          pointer(layout.image_incidences));
  view->point_incidences =
      reinterpret_cast<const MapperCatalogIncidenceSlot*>(
          pointer(layout.point_incidences));
  view->camera_count = static_cast<uint32_t>(tables.cameras.size());
  view->image_count = static_cast<uint32_t>(tables.images.size());
  view->point_count = static_cast<uint32_t>(tables.points.size());
  view->observation_count =
      static_cast<uint32_t>(tables.observations.size());
  view->image_incidence_count =
      static_cast<uint32_t>(tables.image_incidences.size());
  view->point_incidence_count =
      static_cast<uint32_t>(tables.point_incidences.size());
  view->identity = identity;
  runtime->indexed_device_catalog_prefix_bytes = layout.end;
  runtime->indexed_device_catalog_arena_generation = entry.arena_generation;
  return true;
}

bool ReleaseRuntimePoolLease(CudaRuntimePoolLease* lease,
                             const bool healthy,
                             CudaPersistentDeviceRuntimeInfo* runtime,
                             std::string* error) noexcept {
  if (lease == nullptr || lease->entry == nullptr || runtime == nullptr) {
    return true;
  }
  std::unique_ptr<CudaRuntimePoolEntry> entry = std::move(lease->entry);
  const int device = entry->device;
  bool retain = false;
  {
    std::lock_guard<std::mutex> lock(g_cuda_runtime_pool_mutex);
    g_cuda_runtime_pool_active.erase(entry.get());
    auto active = g_cuda_runtime_pool_active_by_device.find(device);
    if (active != g_cuda_runtime_pool_active_by_device.end() &&
        active->second != 0) {
      --active->second;
    }
    ++runtime->runtime_pool_returns;
    const bool poisoned =
        g_cuda_runtime_pool_poisoned_devices.count(device) != 0;
    const bool discard = !healthy || entry->externally_cleared || poisoned;
    if (!discard && entry->retainable &&
        g_cuda_runtime_pool_idle.count(device) == 0) {
      runtime->runtime_pool_retained_entries = 1;
      runtime->arena_retained_bytes = entry->arena_capacity;
      g_cuda_runtime_pool_idle.emplace(device, std::move(entry));
      retain = true;
    } else if (poisoned) {
      ++runtime->runtime_pool_discards;
      ++runtime->runtime_pool_poison_count;
    } else {
      ++runtime->runtime_pool_discards;
    }
  }
  if (retain) return true;
  const bool destroyed = DestroyRuntimePoolEntry(entry.get());
  ++runtime->runtime_pool_destroys;
  if (!destroyed) {
    std::lock_guard<std::mutex> lock(g_cuda_runtime_pool_mutex);
    g_cuda_runtime_pool_poisoned_devices.insert(device);
    ++runtime->runtime_pool_poison_count;
    if (error != nullptr && error->empty()) {
      *error = "ResourceCleanup: RuntimePool entry destroy failed";
    }
  }
  return destroyed;
}

void BeginRuntimePoolGlobalClear() noexcept {
  std::lock_guard<std::mutex> lock(g_cuda_runtime_pool_mutex);
  for (CudaRuntimePoolEntry* entry : g_cuda_runtime_pool_active) {
    if (entry != nullptr) {
      entry->externally_cleared = true;
      entry->retainable = false;
      g_cuda_runtime_pool_clearing_devices.insert(entry->device);
    }
  }
  for (auto& item : g_cuda_runtime_pool_idle) {
    item.second->externally_cleared = true;
    item.second->retainable = false;
    g_cuda_runtime_pool_clearing_devices.insert(item.first);
  }
  // Device resources remain registered and are destroyed exactly once by the
  // common teardown below. These unique_ptrs now own host bookkeeping only.
  g_cuda_runtime_pool_idle.clear();
}

void FinishRuntimePoolGlobalClear(const bool cleanup_succeeded) noexcept {
  std::lock_guard<std::mutex> lock(g_cuda_runtime_pool_mutex);
  if (!cleanup_succeeded) {
    g_cuda_runtime_pool_poisoned_devices.insert(
        g_cuda_runtime_pool_clearing_devices.begin(),
        g_cuda_runtime_pool_clearing_devices.end());
  }
  g_cuda_runtime_pool_clearing_devices.clear();
}

class CudaAuditRuntimeScope {
 public:
  CudaAuditRuntimeScope(CudaFullLmRuntimeInfo* runtime,
                        const CudaFaultTrigger& fault) noexcept {
    g_cuda_active_audit_runtime = runtime;
    g_cuda_active_audit_fault = fault;
    g_cuda_active_audit_fault_consumed = false;
  }
  ~CudaAuditRuntimeScope() noexcept {
    g_cuda_active_audit_runtime = nullptr;
    g_cuda_active_audit_fault = CudaFaultTrigger();
    g_cuda_active_audit_fault_consumed = false;
  }
};

bool ShouldInjectTimingFailure(const CudaFailureSite site) noexcept {
  if (g_cuda_active_audit_runtime == nullptr ||
      !g_cuda_active_audit_runtime->instrumentation_effective ||
      g_cuda_active_audit_fault_consumed ||
      g_cuda_active_audit_fault.fault_kind !=
          CudaFaultInjection::kForceTimingApiFailure) {
    return false;
  }
  if (g_cuda_active_audit_fault.operation != 0 &&
      g_cuda_active_audit_fault.operation != static_cast<uint16_t>(site)) {
    return false;
  }
  g_cuda_active_audit_fault_consumed = true;
  return true;
}

void RecordTimingEventResult(const CudaFailureSite site,
                             const bool success,
                             const bool interval_query) noexcept {
  CudaFullLmRuntimeInfo* runtime = g_cuda_active_audit_runtime;
  if (runtime == nullptr || !runtime->instrumentation_effective) return;
  CudaTimingStructureV2& timing = runtime->timing_structure_v2;
  ++timing.event_attempts;
  if (success) {
    ++timing.event_completions;
  } else {
    ++timing.event_failures;
    if (!timing.has_first_incomplete_site) {
      timing.has_first_incomplete_site = true;
      timing.first_incomplete_site = site;
    }
  }
  if (interval_query) {
    ++timing.intervals_started;
    if (success) {
      ++timing.intervals_completed;
    } else {
      ++timing.intervals_abandoned;
    }
  } else if (!success) {
    ++timing.intervals_started;
    ++timing.intervals_abandoned;
  }
}

cudaError_t AuditCudaEventCreate(cudaEvent_t* event) noexcept {
  if (ShouldInjectTimingFailure(CudaFailureSite::kTimingEventAcquire)) {
    RecordTimingEventResult(CudaFailureSite::kTimingEventAcquire, false,
                            false);
    return cudaErrorUnknown;
  }
  const cudaError_t status = cudaEventCreate(event);
  RecordTimingEventResult(CudaFailureSite::kTimingEventAcquire,
                          status == cudaSuccess, false);
  return status;
}

cudaError_t AuditCudaEventRecord(cudaEvent_t event,
                                 cudaStream_t stream) noexcept {
  if (ShouldInjectTimingFailure(CudaFailureSite::kTimingEventRecord)) {
    RecordTimingEventResult(CudaFailureSite::kTimingEventRecord, false,
                            false);
    return cudaErrorUnknown;
  }
  const cudaError_t status = cudaEventRecord(event, stream);
  RecordTimingEventResult(CudaFailureSite::kTimingEventRecord,
                          status == cudaSuccess, false);
  return status;
}

cudaError_t AuditCudaEventElapsedTime(float* milliseconds,
                                      cudaEvent_t begin,
                                      cudaEvent_t end) noexcept {
  if (ShouldInjectTimingFailure(CudaFailureSite::kTimingElapsedQuery)) {
    RecordTimingEventResult(CudaFailureSite::kTimingElapsedQuery, false,
                            true);
    return cudaErrorUnknown;
  }
  const cudaError_t status = cudaEventElapsedTime(milliseconds, begin, end);
  RecordTimingEventResult(CudaFailureSite::kTimingElapsedQuery,
                          status == cudaSuccess, true);
  return status;
}

class CudaCacheCallScope {
 public:
  CudaCacheCallScope() : lock_(g_cuda_cache_mutex) {}

 private:
  std::unique_lock<std::recursive_mutex> lock_;
};

bool CurrentCudaCacheKey(CudaCacheKey* key) {
  if (key == nullptr) return false;
  *key = CudaCacheKey();
  if (cudaGetDevice(&key->device) != cudaSuccess) return false;
  CUcontext context = nullptr;
  if (cuCtxGetCurrent(&context) != CUDA_SUCCESS || context == nullptr) {
    // A runtime call can succeed before the driver context is observable. Do
    // not reuse context-bound resources in that state.
    key->valid = false;
    return true;
  }
  key->context = reinterpret_cast<uintptr_t>(context);
  key->valid = true;
  return true;
}

void SetDeviceForKey(const CudaCacheKey& key) {
  if (key.device >= 0) cudaSetDevice(key.device);
  if (key.valid && key.context != 0) {
    cuCtxSetCurrent(reinterpret_cast<CUcontext>(key.context));
  }
}

void EnableCudaBufferReuse(const bool enabled) {
  g_cuda_buffer_reuse_enabled = enabled;
}

bool CudaResourceReuseAllowed() {
  if (g_cuda_resource_health == CudaResourceHealth::kClean) return true;
  if (g_cuda_buffer_reuse_enabled) ++g_cuda_resource_lookup_blocked_count;
  return false;
}

bool CudaCleanupSucceeded(std::string* error) {
  if (g_cuda_resource_health == CudaResourceHealth::kClean &&
      g_cuda_taint_cleanup_complete) {
    return true;
  }
  if (error != nullptr)
    *error = "ResourceCleanup: CUDA resource cleanup failed";
  return false;
}

bool CudaStandaloneEntryAllowed(std::string* error) {
  if (g_cuda_resource_health == CudaResourceHealth::kClean &&
      g_cuda_taint_cleanup_complete) {
    return true;
  }
  if (error != nullptr)
    *error = "ResourceCleanup: CUDA resource generation is tainted";
  return false;
}

uint64_t CudaBufferReuseHits() {
  return g_cuda_buffer_reuse_hits;
}

uint64_t CudaStreamReuseHits() { return g_cuda_stream_reuse_hits; }
uint64_t CudaEventReuseHits() { return g_cuda_event_reuse_hits; }
uint64_t CudaSolverReuseHits() { return g_cuda_solver_reuse_hits; }
uint64_t CudaBlasReuseHits() { return g_cuda_blas_reuse_hits; }
void ClearCudaBufferCache();
void ClearCudaRuntimeCache();
void ClearCudaAllResourceCaches();

uint64_t CudaCachedBytesForDevice(const int device) {
  uint64_t bytes = 0;
  for (const CachedCudaAllocation& allocation : g_cuda_buffer_cache) {
    if (allocation.device == device) bytes += allocation.bytes;
  }
  return bytes;
}

uint64_t CudaActiveBytesForDevice(const int device) {
  uint64_t bytes = 0;
  for (const auto& entry : g_cuda_live_allocations) {
    if (entry.second.device == device) bytes += entry.second.bytes;
  }
  return bytes;
}

class CudaBufferReuseScope {
 public:
  explicit CudaBufferReuseScope(const bool enabled) : enabled_(enabled) {
    requested_ = enabled;
    if (enabled_) {
      if (g_cuda_cache_owner_active &&
          g_cuda_cache_owner != std::this_thread::get_id()) {
        error_ = "CUDA_REUSE_CACHE_CONCURRENT_CALL_UNSUPPORTED";
        enabled_ = false;
        return;
      }
      g_cuda_cache_owner = std::this_thread::get_id();
      g_cuda_cache_owner_active = true;
      acquired_ = true;
      g_cuda_buffer_reuse_hits = 0;
      g_cuda_stream_reuse_hits = 0;
      g_cuda_event_reuse_hits = 0;
      g_cuda_solver_reuse_hits = 0;
      g_cuda_blas_reuse_hits = 0;
      EnableCudaBufferReuse(true);
    }
  }
  ~CudaBufferReuseScope() noexcept { Close(); }
  void Close() noexcept {
    if (acquired_) {
      hits_at_close_ = CudaBufferReuseHits();
      EnableCudaBufferReuse(false);
      ClearCudaAllResourceCaches();
      g_cuda_cache_owner_active = false;
      acquired_ = false;
    }
  }
  uint64_t hits() const {
    return acquired_ ? CudaBufferReuseHits() : hits_at_close_;
  }
  bool acquired() const { return !requested_ || acquired_; }
  const std::string& error() const { return error_; }

 private:
  bool enabled_ = false;
  bool requested_ = false;
  bool acquired_ = false;
  uint64_t hits_at_close_ = 0;
  std::string error_;
};

void ClearCudaBufferCache() {
  HostPhaseScope timing(CUDA_TIMING_PHASE(resource_release));
  int previous_device = -1;
  CleanupCudaGetDevice(&previous_device);
  size_t cached_write = 0;
  for (size_t i = 0; i < g_cuda_buffer_cache.size(); ++i) {
    const CachedCudaAllocation allocation = g_cuda_buffer_cache[i];
    bool released = true;
    if (allocation.pointer != nullptr) {
      if (allocation.device >= 0) CleanupCudaSetDevice(allocation.device);
      released = CleanupCudaFree(allocation.pointer, allocation.device) ==
                 cudaSuccess;
    }
    if (!released) g_cuda_buffer_cache[cached_write++] = allocation;
  }
  g_cuda_buffer_cache.resize(cached_write);
  for (auto it = g_cuda_live_allocations.begin();
       it != g_cuda_live_allocations.end();) {
    bool released = true;
    if (it->second.pointer != nullptr) {
      if (it->second.device >= 0) CleanupCudaSetDevice(it->second.device);
      released = CleanupCudaFree(it->second.pointer, it->second.device) ==
                 cudaSuccess;
    }
    if (released) {
      it = g_cuda_live_allocations.erase(it);
    } else {
      ++it;
    }
  }
  if (previous_device >= 0) CleanupCudaSetDevice(previous_device);
  g_cuda_active_bytes = 0;
  for (const auto& entry : g_cuda_live_allocations)
    g_cuda_active_bytes += entry.second.bytes;
  g_cuda_cached_bytes = 0;
  for (const CachedCudaAllocation& allocation : g_cuda_buffer_cache)
    g_cuda_cached_bytes += allocation.bytes;
  g_cuda_buffer_reuse_hits = 0;
  g_cuda_stream_reuse_hits = 0;
  g_cuda_event_reuse_hits = 0;
  g_cuda_solver_reuse_hits = 0;
  g_cuda_blas_reuse_hits = 0;
}

cudaError_t AcquireCudaStream(cudaStream_t* stream) {
  CudaCacheKey key;
  if (!CurrentCudaCacheKey(&key)) return cudaErrorInitializationError;
  if (g_cuda_buffer_reuse_enabled && CudaResourceReuseAllowed() && key.valid) {
    for (auto it = g_cached_streams.begin(); it != g_cached_streams.end();
         ++it) {
      if (SameCudaCacheKey(it->key, key)) {
        *stream = it->handle;
        g_live_streams[*stream] = it->key;
        g_cached_streams.erase(it);
        ++g_cuda_stream_reuse_hits;
        return cudaSuccess;
      }
    }
  }
  const cudaError_t status =
      cudaStreamCreateWithFlags(stream, cudaStreamNonBlocking);
  if (status == cudaSuccess) {
    if (!RegisterCudaResource(reinterpret_cast<uintptr_t>(*stream),
                              CudaTeardownType::kStream, key.device)) {
      CleanupCudaStreamDestroy(*stream, key.device);
      *stream = nullptr;
      return cudaErrorMemoryAllocation;
    }
    g_live_streams[*stream] = key;
  }
  return status;
}

void ReleaseCudaStream(cudaStream_t stream) {
  if (stream == nullptr) return;
  HostPhaseScope timing(CUDA_TIMING_PHASE(resource_release));
  CudaCacheKey key;
  const auto live = g_live_streams.find(stream);
  if (live != g_live_streams.end()) {
    key = live->second;
  } else {
    CurrentCudaCacheKey(&key);
  }
  SetDeviceForKey(key);
  const bool ready = cudaStreamQuery(stream) == cudaSuccess;
  if (g_cuda_buffer_reuse_enabled && CudaResourceReuseAllowed() && key.valid) {
    if (ready || TimedCudaStreamSynchronize(
                     stream, CudaSyncSite::kResourceRelease) == cudaSuccess) {
      g_cached_streams.push_back({stream, key});
      if (live != g_live_streams.end()) g_live_streams.erase(live);
      return;
    }
  }
  const cudaError_t status = CleanupCudaStreamDestroy(stream, key.device);
  if (status == cudaSuccess && live != g_live_streams.end()) {
    g_live_streams.erase(live);
  }
}

cudaError_t AcquireCudaEvent(cudaEvent_t* event) {
  CudaCacheKey key;
  if (!CurrentCudaCacheKey(&key)) return cudaErrorInitializationError;
  if (g_cuda_buffer_reuse_enabled && CudaResourceReuseAllowed() && key.valid) {
    for (auto it = g_cached_events.begin(); it != g_cached_events.end();
         ++it) {
      if (SameCudaCacheKey(it->key, key)) {
        *event = it->handle;
        g_live_events[*event] = it->key;
        g_cached_events.erase(it);
        ++g_cuda_event_reuse_hits;
        return cudaSuccess;
      }
    }
  }
  const cudaError_t status = AuditCudaEventCreate(event);
  if (status == cudaSuccess) {
    if (!RegisterCudaResource(reinterpret_cast<uintptr_t>(*event),
                              CudaTeardownType::kEvent, key.device)) {
      CleanupCudaEventDestroy(*event, key.device);
      *event = nullptr;
      return cudaErrorMemoryAllocation;
    }
    g_live_events[*event] = key;
  }
  return status;
}

void ReleaseCudaEvent(cudaEvent_t event) {
  if (event == nullptr) return;
  HostPhaseScope timing(CUDA_TIMING_PHASE(resource_release));
  CudaCacheKey key;
  const auto live = g_live_events.find(event);
  if (live != g_live_events.end()) {
    key = live->second;
  } else {
    CurrentCudaCacheKey(&key);
  }
  SetDeviceForKey(key);
  if (g_cuda_buffer_reuse_enabled && CudaResourceReuseAllowed() && key.valid &&
      cudaEventQuery(event) == cudaSuccess) {
    g_cached_events.push_back({event, key});
    if (live != g_live_events.end()) g_live_events.erase(live);
    return;
  }
  const cudaError_t status = CleanupCudaEventDestroy(event, key.device);
  if (status == cudaSuccess && live != g_live_events.end()) {
    g_live_events.erase(live);
  }
}

class CudaTransferBatchAudit {
 public:
  CudaTransferBatchAudit(cudaStream_t stream, CudaPhaseTiming* phase)
      : stream_(stream), phase_(phase) {}

  ~CudaTransferBatchAudit() noexcept {
    Close(nullptr);
  }

  bool Close(std::string* error) {
    if (closed_) return CudaCleanupSucceeded(error);
    ReleaseCudaEvent(begin_);
    ReleaseCudaEvent(end_);
    begin_ = nullptr;
    end_ = nullptr;
    closed_ = true;
    return CudaCleanupSucceeded(error);
  }

  bool Begin(std::string* error) {
    if (phase_ == nullptr) return true;
    cudaError_t status = AcquireCudaEvent(&begin_);
    if (status == cudaSuccess) status = AcquireCudaEvent(&end_);
    if (status != cudaSuccess) {
      *error = "CUDA transfer audit event creation failed";
      return false;
    }
    status = AuditCudaEventRecord(begin_, stream_);
    if (status != cudaSuccess) {
      *error = "CUDA transfer audit begin record failed";
      return false;
    }
    active_ = true;
    return true;
  }

  bool End(std::string* error) {
    if (!active_) return true;
    const cudaError_t status = AuditCudaEventRecord(end_, stream_);
    if (status != cudaSuccess) {
      *error = "CUDA transfer audit end record failed";
      return false;
    }
    ended_ = true;
    return true;
  }

  bool CompleteAfterExistingSync(std::string* error) {
    if (!ended_) return true;
    float elapsed = 0.0f;
    const cudaError_t status =
        AuditCudaEventElapsedTime(&elapsed, begin_, end_);
    if (status != cudaSuccess) {
      *error = "CUDA transfer audit elapsed-time query failed";
      return false;
    }
    AccumulateCudaEvent(phase_, elapsed);
    ended_ = false;
    return true;
  }

 private:
  cudaStream_t stream_ = nullptr;
  CudaPhaseTiming* phase_ = nullptr;
  cudaEvent_t begin_ = nullptr;
  cudaEvent_t end_ = nullptr;
  bool active_ = false;
  bool ended_ = false;
  bool closed_ = false;
};

void ClearCudaRuntimeCache() {
  HostPhaseScope timing(CUDA_TIMING_PHASE(resource_release));
  size_t write = 0;
  for (size_t i = 0; i < g_cached_solvers.size(); ++i) {
    const CachedCudaSolver cached = g_cached_solvers[i];
    if (cached.key.device >= 0) CleanupCudaSetDevice(cached.key.device);
    if (CleanupCudaSolverDestroy(cached.handle, cached.key.device) !=
        CUSOLVER_STATUS_SUCCESS) {
      g_cached_solvers[write++] = cached;
    }
  }
  g_cached_solvers.resize(write);
  for (auto it = g_live_solvers.begin(); it != g_live_solvers.end();) {
    if (it->second.device >= 0) CleanupCudaSetDevice(it->second.device);
    if (CleanupCudaSolverDestroy(it->first, it->second.device) ==
        CUSOLVER_STATUS_SUCCESS) {
      it = g_live_solvers.erase(it);
    } else {
      ++it;
    }
  }

  write = 0;
  for (size_t i = 0; i < g_cached_blases.size(); ++i) {
    const CachedCudaBlas cached = g_cached_blases[i];
    if (cached.key.device >= 0) CleanupCudaSetDevice(cached.key.device);
    if (CleanupCudaBlasDestroy(cached.handle, cached.key.device) !=
        CUBLAS_STATUS_SUCCESS) {
      g_cached_blases[write++] = cached;
    }
  }
  g_cached_blases.resize(write);
  for (auto it = g_live_blases.begin(); it != g_live_blases.end();) {
    if (it->second.device >= 0) CleanupCudaSetDevice(it->second.device);
    if (CleanupCudaBlasDestroy(it->first, it->second.device) ==
        CUBLAS_STATUS_SUCCESS) {
      it = g_live_blases.erase(it);
    } else {
      ++it;
    }
  }

  write = 0;
  for (size_t i = 0; i < g_cached_events.size(); ++i) {
    const CachedCudaEvent cached = g_cached_events[i];
    if (cached.key.device >= 0) CleanupCudaSetDevice(cached.key.device);
    if (CleanupCudaEventDestroy(cached.handle, cached.key.device) !=
        cudaSuccess) {
      g_cached_events[write++] = cached;
    }
  }
  g_cached_events.resize(write);
  for (auto it = g_live_events.begin(); it != g_live_events.end();) {
    if (it->second.device >= 0) CleanupCudaSetDevice(it->second.device);
    if (CleanupCudaEventDestroy(it->first, it->second.device) == cudaSuccess) {
      it = g_live_events.erase(it);
    } else {
      ++it;
    }
  }

  write = 0;
  for (size_t i = 0; i < g_cached_streams.size(); ++i) {
    const CachedCudaStream cached = g_cached_streams[i];
    if (cached.key.device >= 0) CleanupCudaSetDevice(cached.key.device);
    if (CleanupCudaStreamDestroy(cached.handle, cached.key.device) !=
        cudaSuccess) {
      g_cached_streams[write++] = cached;
    }
  }
  g_cached_streams.resize(write);
  for (auto it = g_live_streams.begin(); it != g_live_streams.end();) {
    if (it->second.device >= 0) CleanupCudaSetDevice(it->second.device);
    if (CleanupCudaStreamDestroy(it->first, it->second.device) == cudaSuccess) {
      it = g_live_streams.erase(it);
    } else {
      ++it;
    }
  }
}

bool IsCudaResourceActive(const uintptr_t handle,
                          const CudaTeardownType type) noexcept {
  for (uint64_t i = 0; i < g_cuda_resource_registry_count; ++i) {
    const CudaResourceOwnershipEntry& entry =
        g_cuda_resource_registry[static_cast<size_t>(i)];
    if (entry.handle == handle && entry.type == type) return entry.active;
  }
  return false;
}

void RemoveReleasedCudaResourcesFromCaches() noexcept {
  const auto stream_released = [](const CachedCudaStream& value) {
    return !IsCudaResourceActive(reinterpret_cast<uintptr_t>(value.handle),
                                 CudaTeardownType::kStream);
  };
  g_cached_streams.erase(
      std::remove_if(g_cached_streams.begin(), g_cached_streams.end(),
                     stream_released),
      g_cached_streams.end());
  for (auto it = g_live_streams.begin(); it != g_live_streams.end();) {
    if (!IsCudaResourceActive(reinterpret_cast<uintptr_t>(it->first),
                              CudaTeardownType::kStream)) {
      it = g_live_streams.erase(it);
    } else {
      ++it;
    }
  }
  const auto event_released = [](const CachedCudaEvent& value) {
    return !IsCudaResourceActive(reinterpret_cast<uintptr_t>(value.handle),
                                 CudaTeardownType::kEvent);
  };
  g_cached_events.erase(
      std::remove_if(g_cached_events.begin(), g_cached_events.end(),
                     event_released),
      g_cached_events.end());
  for (auto it = g_live_events.begin(); it != g_live_events.end();) {
    if (!IsCudaResourceActive(reinterpret_cast<uintptr_t>(it->first),
                              CudaTeardownType::kEvent)) {
      it = g_live_events.erase(it);
    } else {
      ++it;
    }
  }
  const auto solver_released = [](const CachedCudaSolver& value) {
    return !IsCudaResourceActive(reinterpret_cast<uintptr_t>(value.handle),
                                 CudaTeardownType::kSolver);
  };
  g_cached_solvers.erase(
      std::remove_if(g_cached_solvers.begin(), g_cached_solvers.end(),
                     solver_released),
      g_cached_solvers.end());
  for (auto it = g_live_solvers.begin(); it != g_live_solvers.end();) {
    if (!IsCudaResourceActive(reinterpret_cast<uintptr_t>(it->first),
                              CudaTeardownType::kSolver)) {
      it = g_live_solvers.erase(it);
    } else {
      ++it;
    }
  }
  const auto blas_released = [](const CachedCudaBlas& value) {
    return !IsCudaResourceActive(reinterpret_cast<uintptr_t>(value.handle),
                                 CudaTeardownType::kBlas);
  };
  g_cached_blases.erase(
      std::remove_if(g_cached_blases.begin(), g_cached_blases.end(),
                     blas_released),
      g_cached_blases.end());
  for (auto it = g_live_blases.begin(); it != g_live_blases.end();) {
    if (!IsCudaResourceActive(reinterpret_cast<uintptr_t>(it->first),
                              CudaTeardownType::kBlas)) {
      it = g_live_blases.erase(it);
    } else {
      ++it;
    }
  }
  g_cuda_buffer_cache.erase(
      std::remove_if(
          g_cuda_buffer_cache.begin(), g_cuda_buffer_cache.end(),
          [](const CachedCudaAllocation& value) {
            return !IsCudaResourceActive(
                reinterpret_cast<uintptr_t>(value.pointer),
                CudaTeardownType::kAllocation);
          }),
      g_cuda_buffer_cache.end());
  for (auto it = g_cuda_live_allocations.begin();
       it != g_cuda_live_allocations.end();) {
    if (!IsCudaResourceActive(reinterpret_cast<uintptr_t>(it->first),
                              CudaTeardownType::kAllocation)) {
      it = g_cuda_live_allocations.erase(it);
    } else {
      ++it;
    }
  }
  g_cuda_active_bytes = 0;
  for (const auto& value : g_cuda_live_allocations)
    g_cuda_active_bytes = SaturatingAdd(g_cuda_active_bytes,
                                        value.second.bytes);
  g_cuda_cached_bytes = 0;
  for (const CachedCudaAllocation& value : g_cuda_buffer_cache)
    g_cuda_cached_bytes = SaturatingAdd(g_cuda_cached_bytes, value.bytes);
}

void ClearCudaAllResourceCaches() {
  HostPhaseScope timing(CUDA_TIMING_PHASE(resource_release));
  int previous_device = -1;
  CleanupCudaGetDevice(&previous_device);
  std::array<uint64_t, kCudaResourceRegistryCapacity> order{};
  size_t count = 0;
  for (uint64_t i = 0; i < g_cuda_resource_registry_count; ++i) {
    if (g_cuda_resource_registry[static_cast<size_t>(i)].active) {
      order[count++] = i;
    }
  }
  std::sort(order.begin(), order.begin() + count,
            [](const uint64_t lhs_index, const uint64_t rhs_index) {
    const CudaResourceOwnershipEntry& lhs =
        g_cuda_resource_registry[static_cast<size_t>(lhs_index)];
    const CudaResourceOwnershipEntry& rhs =
        g_cuda_resource_registry[static_cast<size_t>(rhs_index)];
    return std::tie(lhs.device, lhs.type, lhs.creation_sequence) <
           std::tie(rhs.device, rhs.type, rhs.creation_sequence);
  });
  int selected_device = std::numeric_limits<int>::min();
  bool device_ready = true;
  for (size_t i = 0; i < count; ++i) {
    CudaResourceOwnershipEntry& entry = g_cuda_resource_registry[
        static_cast<size_t>(order[i])];
    if (!entry.active) continue;
    if (entry.device != selected_device) {
      selected_device = entry.device;
      device_ready = selected_device < 0 ||
          CleanupCudaSetDevice(selected_device) == cudaSuccess;
    }
    if (!device_ready) {
      entry.quarantined = true;
      continue;
    }
    switch (entry.type) {
      case CudaTeardownType::kSolver:
        CleanupCudaSolverDestroy(
            reinterpret_cast<cusolverDnHandle_t>(entry.handle), entry.device);
        break;
      case CudaTeardownType::kBlas:
        CleanupCudaBlasDestroy(
            reinterpret_cast<cublasHandle_t>(entry.handle), entry.device);
        break;
      case CudaTeardownType::kEvent:
        CleanupCudaEventDestroy(reinterpret_cast<cudaEvent_t>(entry.handle),
                                entry.device);
        break;
      case CudaTeardownType::kStream:
        CleanupCudaStreamDestroy(
            reinterpret_cast<cudaStream_t>(entry.handle), entry.device);
        break;
      case CudaTeardownType::kAllocation:
        CleanupCudaFree(reinterpret_cast<void*>(entry.handle), entry.device);
        break;
      case CudaTeardownType::kGetDevice:
      case CudaTeardownType::kSetDevice:
        break;
    }
  }
  if (previous_device >= 0 && previous_device != selected_device)
    CleanupCudaSetDevice(previous_device);
  RemoveReleasedCudaResourcesFromCaches();
  g_cuda_buffer_reuse_hits = 0;
  g_cuda_stream_reuse_hits = 0;
  g_cuda_event_reuse_hits = 0;
  g_cuda_solver_reuse_hits = 0;
  g_cuda_blas_reuse_hits = 0;
}

cusolverStatus_t AcquireCudaSolver(cusolverDnHandle_t* handle) {
  CudaCacheKey key;
  if (!CurrentCudaCacheKey(&key)) return CUSOLVER_STATUS_NOT_INITIALIZED;
  if (g_cuda_buffer_reuse_enabled && CudaResourceReuseAllowed() && key.valid) {
    for (auto it = g_cached_solvers.begin(); it != g_cached_solvers.end();
         ++it) {
      if (SameCudaCacheKey(it->key, key)) {
        *handle = it->handle;
        g_live_solvers[*handle] = it->key;
        g_cached_solvers.erase(it);
        ++g_cuda_solver_reuse_hits;
        return CUSOLVER_STATUS_SUCCESS;
      }
    }
  }
  const cusolverStatus_t status = cusolverDnCreate(handle);
  if (status == CUSOLVER_STATUS_SUCCESS) {
    if (!RegisterCudaResource(reinterpret_cast<uintptr_t>(*handle),
                              CudaTeardownType::kSolver, key.device)) {
      CleanupCudaSolverDestroy(*handle, key.device);
      *handle = nullptr;
      return CUSOLVER_STATUS_ALLOC_FAILED;
    }
    g_live_solvers[*handle] = key;
  }
  return status;
}

void ReleaseCudaSolver(cusolverDnHandle_t handle, const bool ready) {
  if (handle == nullptr) return;
  HostPhaseScope timing(CUDA_TIMING_PHASE(resource_release));
  CudaCacheKey key;
  const auto live = g_live_solvers.find(handle);
  if (live != g_live_solvers.end()) {
    key = live->second;
  } else {
    CurrentCudaCacheKey(&key);
  }
  SetDeviceForKey(key);
  if (g_cuda_buffer_reuse_enabled && CudaResourceReuseAllowed() && key.valid &&
      ready) {
    g_cached_solvers.push_back({handle, key});
    if (live != g_live_solvers.end()) g_live_solvers.erase(live);
    return;
  }
  const cusolverStatus_t status =
      CleanupCudaSolverDestroy(handle, key.device);
  if (status == CUSOLVER_STATUS_SUCCESS && live != g_live_solvers.end()) {
    g_live_solvers.erase(live);
  }
}

cublasStatus_t AcquireCudaBlas(cublasHandle_t* handle) {
  CudaCacheKey key;
  if (!CurrentCudaCacheKey(&key)) return CUBLAS_STATUS_NOT_INITIALIZED;
  if (g_cuda_buffer_reuse_enabled && CudaResourceReuseAllowed() && key.valid) {
    for (auto it = g_cached_blases.begin(); it != g_cached_blases.end();
         ++it) {
      if (SameCudaCacheKey(it->key, key)) {
        *handle = it->handle;
        g_live_blases[*handle] = it->key;
        g_cached_blases.erase(it);
        ++g_cuda_blas_reuse_hits;
        return CUBLAS_STATUS_SUCCESS;
      }
    }
  }
  const cublasStatus_t status = cublasCreate(handle);
  if (status == CUBLAS_STATUS_SUCCESS) {
    if (!RegisterCudaResource(reinterpret_cast<uintptr_t>(*handle),
                              CudaTeardownType::kBlas, key.device)) {
      CleanupCudaBlasDestroy(*handle, key.device);
      *handle = nullptr;
      return CUBLAS_STATUS_ALLOC_FAILED;
    }
    g_live_blases[*handle] = key;
  }
  return status;
}

void ReleaseCudaBlas(cublasHandle_t handle, const bool ready) {
  if (handle == nullptr) return;
  HostPhaseScope timing(CUDA_TIMING_PHASE(resource_release));
  CudaCacheKey key;
  const auto live = g_live_blases.find(handle);
  if (live != g_live_blases.end()) {
    key = live->second;
  } else {
    CurrentCudaCacheKey(&key);
  }
  SetDeviceForKey(key);
  if (g_cuda_buffer_reuse_enabled && CudaResourceReuseAllowed() && key.valid &&
      ready) {
    g_cached_blases.push_back({handle, key});
    if (live != g_live_blases.end()) g_live_blases.erase(live);
    return;
  }
  const cublasStatus_t status = CleanupCudaBlasDestroy(handle, key.device);
  if (status == CUBLAS_STATUS_SUCCESS && live != g_live_blases.end()) {
    g_live_blases.erase(live);
  }
}

// OpenCVCameraModel::kModelId from base/camera_models.h.  The CUDA translation
// unit intentionally does not include that large templated header: including
// it would make nvcc instantiate unrelated host-only Eigen camera models.
constexpr int kOpenCvcCameraModelId = 4;

__device__ inline bool DeviceFinite(const double value) {
  return isfinite(value);
}

template <size_t N>
__device__ inline bool DeviceAllFinite(const double (&values)[N]) {
  for (size_t i = 0; i < N; ++i) {
    if (!DeviceFinite(values[i])) return false;
  }
  return true;
}

__device__ inline void DeviceQuaternionPlusJacobian(const double* q,
                                                    double* jacobian) {
  const double w = q[0];
  const double x = q[1];
  const double y = q[2];
  const double z = q[3];
  jacobian[0] = -x;
  jacobian[1] = -y;
  jacobian[2] = -z;
  jacobian[3] = w;
  jacobian[4] = z;
  jacobian[5] = -y;
  jacobian[6] = -z;
  jacobian[7] = w;
  jacobian[8] = x;
  jacobian[9] = y;
  jacobian[10] = -x;
  jacobian[11] = w;
}

__device__ inline void DeviceMultiply2x3By3xN(const double* lhs,
                                               const double* rhs,
                                               size_t columns,
                                               double* result) {
  for (size_t row = 0; row < 2; ++row) {
    for (size_t col = 0; col < columns; ++col) {
      result[row * columns + col] =
          lhs[row * 3 + 0] * rhs[0 * columns + col] +
          lhs[row * 3 + 1] * rhs[1 * columns + col] +
          lhs[row * 3 + 2] * rhs[2 * columns + col];
    }
  }
}

// This is a fixed-size device translation of EvaluateOpenCVVisual. Keep the
// operation order aligned with the CPU analytic reference; later reductions
// have their own explicit deterministic-order gate.
__device__ inline void EvaluateVisualDevice(const CudaVisualInput& input,
                                            CudaVisualOutput* output) {
  const double w = input.quaternion[0];
  const double x = input.quaternion[1];
  const double y = input.quaternion[2];
  const double z = input.quaternion[3];
  const double px = input.point[0];
  const double py = input.point[1];
  const double pz = input.point[2];

  bool finite = DeviceAllFinite(input.quaternion) &&
                DeviceAllFinite(input.translation) &&
                DeviceAllFinite(input.point) &&
                DeviceAllFinite(input.camera) &&
                DeviceAllFinite(input.observation);
  if (!finite) {
    output->finite = 0;
    return;
  }

  const double t2 = w * x;
  const double t3 = w * y;
  const double t4 = w * z;
  const double t5 = -x * x;
  const double t6 = x * y;
  const double t7 = x * z;
  const double t8 = -y * y;
  const double t9 = y * z;
  const double t1 = -z * z;
  const double r00 = 2.0 * (t8 + t1) + 1.0;
  const double r01 = 2.0 * (t6 - t4);
  const double r02 = 2.0 * (t3 + t7);
  const double r10 = 2.0 * (t4 + t6);
  const double r11 = 2.0 * (t5 + t1) + 1.0;
  const double r12 = 2.0 * (t9 - t2);
  const double r20 = 2.0 * (t7 - t3);
  const double r21 = 2.0 * (t2 + t9);
  const double r22 = 2.0 * (t5 + t8) + 1.0;

  const double X =
      2.0 * ((t8 + t1) * px + (t6 - t4) * py + (t3 + t7) * pz) +
      px + input.translation[0];
  const double Y =
      2.0 * ((t4 + t6) * px + (t5 + t1) * py + (t9 - t2) * pz) +
      py + input.translation[1];
  const double Z =
      2.0 * ((t7 - t3) * px + (t2 + t9) * py + (t5 + t8) * pz) +
      pz + input.translation[2];
  output->camera_point[0] = X;
  output->camera_point[1] = Y;
  output->camera_point[2] = Z;
  if (!DeviceFinite(Z) || fabs(Z) <= DBL_MIN) {
    output->finite = 0;
    return;
  }

  const double u = X / Z;
  const double v = Y / Z;
  const double u2 = u * u;
  const double uv = u * v;
  const double v2 = v * v;
  const double r2 = u2 + v2;
  const double fx = input.camera[0];
  const double fy = input.camera[1];
  const double cx = input.camera[2];
  const double cy = input.camera[3];
  const double k1 = input.camera[4];
  const double k2 = input.camera[5];
  const double p1 = input.camera[6];
  const double p2 = input.camera[7];
  const double radial = k1 * r2 + k2 * r2 * r2;
  const double du =
      u * radial + 2.0 * p1 * uv + p2 * (r2 + 2.0 * u2);
  const double dv =
      v * radial + 2.0 * p2 * uv + p1 * (r2 + 2.0 * v2);
  const double distorted_u = u + du;
  const double distorted_v = v + dv;
  output->residual[0] = fx * distorted_u + cx - input.observation[0];
  output->residual[1] = fy * distorted_v + cy - input.observation[1];

  const double radial_u = 2.0 * u * (k1 + 2.0 * k2 * r2);
  const double radial_v = 2.0 * v * (k1 + 2.0 * k2 * r2);
  const double ddu_du =
      1.0 + radial + u * radial_u + 2.0 * p1 * v + 6.0 * p2 * u;
  const double ddu_dv = u * radial_v + 2.0 * p1 * u + 2.0 * p2 * v;
  const double ddv_du = v * radial_u + 2.0 * p2 * v + 2.0 * p1 * u;
  const double ddv_dv =
      1.0 + radial + v * radial_v + 2.0 * p2 * u + 6.0 * p1 * v;
  const double inverse_z = 1.0 / Z;
  const double normalized_jacobian[6] = {
      inverse_z, 0.0, -u * inverse_z, 0.0, inverse_z, -v * inverse_z};
  const double distortion_jacobian[4] = {
      fx * ddu_du, fx * ddu_dv, fy * ddv_du, fy * ddv_dv};
  double camera_point_jacobian[6];
  for (size_t row = 0; row < 2; ++row) {
    for (size_t col = 0; col < 3; ++col) {
      camera_point_jacobian[row * 3 + col] =
          distortion_jacobian[row * 2 + 0] *
              normalized_jacobian[0 * 3 + col] +
          distortion_jacobian[row * 2 + 1] *
              normalized_jacobian[1 * 3 + col];
    }
  }
  for (size_t i = 0; i < 6; ++i) {
    output->translation_jacobian[i] = camera_point_jacobian[i];
  }

  const double rotation[9] = {
      r00, r01, r02, r10, r11, r12, r20, r21, r22};
  DeviceMultiply2x3By3xN(camera_point_jacobian, rotation, 3,
                          output->point_jacobian);

  const double rotated_point_quaternion_jacobian[12] = {
      2.0 * (-z * py + y * pz), 2.0 * (y * py + z * pz),
      2.0 * (-2.0 * y * px + x * py + w * pz),
      2.0 * (-2.0 * z * px - w * py + x * pz),
      2.0 * (z * px - x * pz),
      2.0 * (y * px - 2.0 * x * py - w * pz),
      2.0 * (x * px + z * pz),
      2.0 * (w * px - 2.0 * z * py + y * pz),
      2.0 * (-y * px + x * py),
      2.0 * (z * px + w * py - 2.0 * x * pz),
      2.0 * (-w * px + z * py - 2.0 * y * pz),
      2.0 * (x * px + y * py)};
  DeviceMultiply2x3By3xN(camera_point_jacobian,
                          rotated_point_quaternion_jacobian, 4,
                          output->ambient_quaternion_jacobian);

  DeviceQuaternionPlusJacobian(input.quaternion, output->plus_jacobian);
  for (size_t row = 0; row < 2; ++row) {
    for (size_t col = 0; col < 3; ++col) {
      double value = 0.0;
      for (size_t ambient = 0; ambient < 4; ++ambient) {
        value += output->ambient_quaternion_jacobian[row * 4 + ambient] *
                 output->plus_jacobian[ambient * 3 + col];
      }
      output->local_rotation_jacobian[row * 3 + col] = value;
    }
  }

  output->camera_jacobian[0] = distorted_u;
  output->camera_jacobian[1] = 0.0;
  output->camera_jacobian[2] = 1.0;
  output->camera_jacobian[3] = 0.0;
  output->camera_jacobian[4] = fx * u * r2;
  output->camera_jacobian[5] = fx * u * r2 * r2;
  output->camera_jacobian[6] = fx * 2.0 * uv;
  output->camera_jacobian[7] = fx * (r2 + 2.0 * u2);
  output->camera_jacobian[8] = 0.0;
  output->camera_jacobian[9] = distorted_v;
  output->camera_jacobian[10] = 0.0;
  output->camera_jacobian[11] = 1.0;
  output->camera_jacobian[12] = fy * v * r2;
  output->camera_jacobian[13] = fy * v * r2 * r2;
  output->camera_jacobian[14] = fy * (r2 + 2.0 * v2);
  output->camera_jacobian[15] = fy * 2.0 * uv;

  finite = DeviceAllFinite(output->residual) &&
           DeviceAllFinite(output->ambient_quaternion_jacobian) &&
           DeviceAllFinite(output->plus_jacobian) &&
           DeviceAllFinite(output->local_rotation_jacobian) &&
           DeviceAllFinite(output->translation_jacobian) &&
           DeviceAllFinite(output->point_jacobian) &&
           DeviceAllFinite(output->camera_jacobian);
  output->finite = finite ? 1 : 0;
}

__device__ inline void EvaluateLidarDevice(const CudaLidarInput& input,
                                           CudaLidarOutput* output) {
  const double d = input.plane[0] * input.point[0] +
                   input.plane[1] * input.point[1] +
                   input.plane[2] * input.point[2] + input.plane[3];
  output->signed_distance = d;
  output->exact_zero = d == 0.0 ? 1 : 0;
  output->near_zero = fabs(d) <= input.near_zero_threshold ? 1 : 0;
  double derivative = 0.0;
  if (input.mode == static_cast<uint8_t>(LidarResidualMode::kSigned)) {
    output->residual = input.weight * d;
    derivative = input.weight;
  } else {
    const double magnitude = sqrt(d * d);
    output->residual = input.weight * magnitude;
    if (input.mode ==
            static_cast<uint8_t>(LidarResidualMode::kLegacyGuarded) &&
        output->near_zero != 0) {
      derivative = 0.0;
      output->guarded = 1;
    } else {
      derivative = input.weight * d / magnitude;
    }
  }
  for (size_t i = 0; i < 3; ++i) {
    output->point_jacobian[i] = derivative * input.plane[i];
  }
  output->finite = (DeviceFinite(d) && DeviceFinite(output->residual) &&
                    DeviceAllFinite(output->point_jacobian))
                       ? 1
                       : 0;
}

__global__ void LayerAVisualKernel(const CudaVisualInput* input,
                                   CudaVisualOutput* output,
                                   size_t count) {
  const size_t index = blockIdx.x * blockDim.x + threadIdx.x;
  if (index < count) EvaluateVisualDevice(input[index], &output[index]);
}

__global__ void LayerALidarKernel(const CudaLidarInput* input,
                                  CudaLidarOutput* output,
                                  size_t count) {
  const size_t index = blockIdx.x * blockDim.x + threadIdx.x;
  if (index < count) EvaluateLidarDevice(input[index], &output[index]);
}

// Persistent full-solve Layer A separates immutable residual bindings from
// state values. The kernel reconstructs the validated ABI record in registers
// and then calls the same arithmetic routine as the legacy path.
struct DeviceVisualStaticInput {
  uint64_t source_index;
  uint32_t image_id;
  uint64_t point3D_id;
  uint32_t image_entity_index;
  uint32_t point_entity_index;
  uint32_t camera_entity_index;
  double observation[2];
};

struct DeviceVisualDynamicInput {
  double quaternion[4];
  double translation[3];
  double point[3];
  double camera[8];
};

struct DeviceLidarStaticInput {
  uint64_t source_index;
  uint64_t point3D_id;
  uint32_t point_entity_index;
  double plane[4];
  double weight;
  uint8_t mode;
  double near_zero_threshold;
};

struct DeviceLidarDynamicInput {
  double point[3];
};

struct DeviceImageEntityState {
  double quaternion[4];
  double translation[3];
};

struct DevicePointEntityState {
  double xyz[3];
};

struct DeviceCameraEntityState {
  double params[8];
};

// Persistent production-only ABI. Public CudaVisualOutput remains unchanged
// for standalone/oracle callers. The canonical pose Jacobian stores rotation
// columns [0,3) followed by translation columns [3,6), independent of a
// solve's translation subset mask.
struct CudaCompactVisualOutput {
  double residual[2];
  double pose_jacobian[12];
  double point_jacobian[6];
  uint32_t status;
  uint32_t reserved;
};

// Solve-owned Phase 10.1b arithmetic records. They are never aliased with the
// public/double ABI and are allocated only for the explicit fp32_mixed mode.
struct MixedVisualOutput {
  float residual[2];
  float pose_jacobian[12];
  float point_jacobian[6];
  uint32_t finite;
};

struct MixedLidarOutput {
  float residual;
  float point_jacobian[3];
  uint32_t finite;
};

struct MixedPoseBlockOutput {
  uint32_t image_id;
  uint32_t dimension;
  int32_t free_translation_indices[3];
  float hessian[36];
  double gradient[6];
  float jacobi_scaling[6];
  float damping[6];
};

struct MixedPointBlockOutput {
  uint64_t point3D_id;
  float hessian[9];
  double gradient[3];
  float jacobi_scaling[3];
  float damping[3];
};

struct MixedEdgeBlockOutput {
  uint32_t pose_index;
  uint32_t point_index;
  uint32_t pose_dimension;
  uint32_t reserved;
  float value[18];
};

struct MixedPointAssemblyPartial {
  float hessian[9];
  double gradient[3];
};

static_assert(std::is_trivially_copyable<MixedVisualOutput>::value &&
                  std::is_trivially_copyable<MixedLidarOutput>::value &&
                  std::is_trivially_copyable<MixedPoseBlockOutput>::value &&
                  std::is_trivially_copyable<MixedPointBlockOutput>::value &&
                  std::is_trivially_copyable<MixedEdgeBlockOutput>::value,
              "mixed precision records must remain trivially copyable");

static_assert(sizeof(CudaVisualOutput) == 480,
              "public CudaVisualOutput ABI changed");
static_assert(sizeof(CudaCompactVisualOutput) <= 192,
              "compact visual output exceeds the production budget");
static_assert(std::is_trivially_copyable<CudaCompactVisualOutput>::value,
              "compact visual output must be trivially copyable");

struct DeviceCanonicalVisualValue {
  double residual[2];
  double pose_jacobian[12];
  double point_jacobian[6];
  uint8_t finite;
};

__device__ inline DeviceCanonicalVisualValue LoadCanonicalVisual(
    const void* records,
    const bool compact,
    const size_t index) {
  DeviceCanonicalVisualValue result;
  if (compact) {
    const CudaCompactVisualOutput value =
        static_cast<const CudaCompactVisualOutput*>(records)[index];
    for (size_t i = 0; i < 2; ++i) result.residual[i] = value.residual[i];
    for (size_t i = 0; i < 12; ++i)
      result.pose_jacobian[i] = value.pose_jacobian[i];
    for (size_t i = 0; i < 6; ++i)
      result.point_jacobian[i] = value.point_jacobian[i];
    result.finite = (value.status & 1u) != 0 ? 1 : 0;
  } else {
    const CudaVisualOutput value =
        static_cast<const CudaVisualOutput*>(records)[index];
    for (size_t row = 0; row < 2; ++row) {
      result.residual[row] = value.residual[row];
      for (size_t i = 0; i < 3; ++i) {
        result.pose_jacobian[row * 6 + i] =
            value.local_rotation_jacobian[row * 3 + i];
        result.pose_jacobian[row * 6 + 3 + i] =
            value.translation_jacobian[row * 3 + i];
        result.point_jacobian[row * 3 + i] =
            value.point_jacobian[row * 3 + i];
      }
    }
    result.finite = value.finite;
  }
  return result;
}

__device__ inline void StoreCompactVisual(
    const CudaVisualOutput& full,
    CudaCompactVisualOutput* compact) {
  for (size_t row = 0; row < 2; ++row) {
    compact->residual[row] = full.residual[row];
    for (size_t i = 0; i < 3; ++i) {
      compact->pose_jacobian[row * 6 + i] =
          full.local_rotation_jacobian[row * 3 + i];
      compact->pose_jacobian[row * 6 + 3 + i] =
          full.translation_jacobian[row * 3 + i];
      compact->point_jacobian[row * 3 + i] =
          full.point_jacobian[row * 3 + i];
    }
  }
  compact->status = full.finite != 0 ? 1u : 0u;
  compact->reserved = 0;
}

