__device__ inline bool MixedFinite(const float value) {
  return isfinite(value);
}

__device__ inline void EvaluateVisualMixed(
    const DeviceVisualStaticInput& fixed,
    const DeviceImageEntityState& image,
    const DevicePointEntityState& point,
    const DeviceCameraEntityState& camera,
    MixedVisualOutput* output) {
  *output = MixedVisualOutput{};
  const float w = static_cast<float>(image.quaternion[0]);
  const float x = static_cast<float>(image.quaternion[1]);
  const float y = static_cast<float>(image.quaternion[2]);
  const float z = static_cast<float>(image.quaternion[3]);
  const float tx = static_cast<float>(image.translation[0]);
  const float ty = static_cast<float>(image.translation[1]);
  const float tz = static_cast<float>(image.translation[2]);
  const float px = static_cast<float>(point.xyz[0]);
  const float py = static_cast<float>(point.xyz[1]);
  const float pz = static_cast<float>(point.xyz[2]);
  float c[8];
  for (uint32_t i = 0; i < 8; ++i) {
    c[i] = static_cast<float>(camera.params[i]);
  }
  if (!MixedFinite(w) || !MixedFinite(x) || !MixedFinite(y) ||
      !MixedFinite(z) || !MixedFinite(tx) || !MixedFinite(ty) ||
      !MixedFinite(tz) || !MixedFinite(px) || !MixedFinite(py) ||
      !MixedFinite(pz)) {
    return;
  }
  for (const float value : c) {
    if (!MixedFinite(value)) return;
  }

  const float t2 = w * x;
  const float t3 = w * y;
  const float t4 = w * z;
  const float t5 = -x * x;
  const float t6 = x * y;
  const float t7 = x * z;
  const float t8 = -y * y;
  const float t9 = y * z;
  const float t1 = -z * z;
  const float rotation[9] = {
      2.0f * (t8 + t1) + 1.0f, 2.0f * (t6 - t4),
      2.0f * (t3 + t7), 2.0f * (t4 + t6),
      2.0f * (t5 + t1) + 1.0f, 2.0f * (t9 - t2),
      2.0f * (t7 - t3), 2.0f * (t2 + t9),
      2.0f * (t5 + t8) + 1.0f};
  const float X = rotation[0] * px + rotation[1] * py +
                  rotation[2] * pz + tx;
  const float Y = rotation[3] * px + rotation[4] * py +
                  rotation[5] * pz + ty;
  const float Z = rotation[6] * px + rotation[7] * py +
                  rotation[8] * pz + tz;
  if (!MixedFinite(Z) || fabsf(Z) <= FLT_MIN) return;
  const float u = X / Z;
  const float v = Y / Z;
  const float u2 = u * u;
  const float uv = u * v;
  const float v2 = v * v;
  const float r2 = u2 + v2;
  const float radial = c[4] * r2 + c[5] * r2 * r2;
  const float du = u * radial + 2.0f * c[6] * uv +
                   c[7] * (r2 + 2.0f * u2);
  const float dv = v * radial + 2.0f * c[7] * uv +
                   c[6] * (r2 + 2.0f * v2);
  const float distorted_u = u + du;
  const float distorted_v = v + dv;
  output->residual[0] =
      c[0] * distorted_u + c[2] - static_cast<float>(fixed.observation[0]);
  output->residual[1] =
      c[1] * distorted_v + c[3] - static_cast<float>(fixed.observation[1]);

  const float radial_u = 2.0f * u * (c[4] + 2.0f * c[5] * r2);
  const float radial_v = 2.0f * v * (c[4] + 2.0f * c[5] * r2);
  const float ddu_du = 1.0f + radial + u * radial_u + 2.0f * c[6] * v +
                       6.0f * c[7] * u;
  const float ddu_dv = u * radial_v + 2.0f * c[6] * u + 2.0f * c[7] * v;
  const float ddv_du = v * radial_u + 2.0f * c[7] * v + 2.0f * c[6] * u;
  const float ddv_dv = 1.0f + radial + v * radial_v + 2.0f * c[7] * u +
                       6.0f * c[6] * v;
  const float inverse_z = 1.0f / Z;
  const float normalized[6] =
      {inverse_z, 0.0f, -u * inverse_z,
       0.0f, inverse_z, -v * inverse_z};
  const float distortion[4] =
      {c[0] * ddu_du, c[0] * ddu_dv,
       c[1] * ddv_du, c[1] * ddv_dv};
  float camera_point_jacobian[6];
  for (uint32_t row = 0; row < 2; ++row) {
    for (uint32_t col = 0; col < 3; ++col) {
      camera_point_jacobian[row * 3 + col] =
          distortion[row * 2] * normalized[col] +
          distortion[row * 2 + 1] * normalized[3 + col];
    }
  }
  for (uint32_t row = 0; row < 2; ++row) {
    for (uint32_t col = 0; col < 3; ++col) {
      output->point_jacobian[row * 3 + col] =
          camera_point_jacobian[row * 3] * rotation[col] +
          camera_point_jacobian[row * 3 + 1] * rotation[3 + col] +
          camera_point_jacobian[row * 3 + 2] * rotation[6 + col];
    }
  }
  const float rotated_q_jacobian[12] = {
      2.0f * (-z * py + y * pz), 2.0f * (y * py + z * pz),
      2.0f * (-2.0f * y * px + x * py + w * pz),
      2.0f * (-2.0f * z * px - w * py + x * pz),
      2.0f * (z * px - x * pz),
      2.0f * (y * px - 2.0f * x * py - w * pz),
      2.0f * (x * px + z * pz),
      2.0f * (w * px - 2.0f * z * py + y * pz),
      2.0f * (-y * px + x * py),
      2.0f * (z * px + w * py - 2.0f * x * pz),
      2.0f * (-w * px + z * py - 2.0f * y * pz),
      2.0f * (x * px + y * py)};
  float ambient[8];
  for (uint32_t row = 0; row < 2; ++row) {
    for (uint32_t col = 0; col < 4; ++col) {
      ambient[row * 4 + col] =
          camera_point_jacobian[row * 3] * rotated_q_jacobian[col] +
          camera_point_jacobian[row * 3 + 1] *
              rotated_q_jacobian[4 + col] +
          camera_point_jacobian[row * 3 + 2] *
              rotated_q_jacobian[8 + col];
    }
  }
  const float plus[12] =
      {-x, -y, -z, w, z, -y, -z, w, x, y, -x, w};
  for (uint32_t row = 0; row < 2; ++row) {
    for (uint32_t col = 0; col < 3; ++col) {
      float value = 0.0f;
      for (uint32_t ambient_index = 0; ambient_index < 4;
           ++ambient_index) {
        value += ambient[row * 4 + ambient_index] *
                 plus[ambient_index * 3 + col];
      }
      output->pose_jacobian[row * 6 + col] = value;
      output->pose_jacobian[row * 6 + 3 + col] =
          camera_point_jacobian[row * 3 + col];
    }
  }
  bool finite = true;
  for (const float value : output->residual) finite &= MixedFinite(value);
  for (const float value : output->pose_jacobian) finite &= MixedFinite(value);
  for (const float value : output->point_jacobian)
    finite &= MixedFinite(value);
  output->finite = finite ? 1u : 0u;
}

__global__ void LayerAVisualMixedDeviceStateKernel(
    const DeviceVisualStaticInput* static_input,
    const DeviceImageEntityState* images,
    const DevicePointEntityState* points,
    const DeviceCameraEntityState* cameras,
    MixedVisualOutput* output,
    const size_t count) {
  const size_t index = blockIdx.x * blockDim.x + threadIdx.x;
  if (index >= count) return;
  const DeviceVisualStaticInput fixed = static_input[index];
  EvaluateVisualMixed(fixed, images[fixed.image_entity_index],
                      points[fixed.point_entity_index],
                      cameras[fixed.camera_entity_index], &output[index]);
  if (output[index].finite == 0) {
    output[index].residual[0] = nanf("");
  }
}

__global__ void LayerALidarMixedDeviceStateKernel(
    const DeviceLidarStaticInput* static_input,
    const DevicePointEntityState* points,
    MixedLidarOutput* output,
    const size_t count) {
  const size_t index = blockIdx.x * blockDim.x + threadIdx.x;
  if (index >= count) return;
  const DeviceLidarStaticInput fixed = static_input[index];
  const DevicePointEntityState point = points[fixed.point_entity_index];
  const float x = static_cast<float>(point.xyz[0]);
  const float y = static_cast<float>(point.xyz[1]);
  const float z = static_cast<float>(point.xyz[2]);
  const float p0 = static_cast<float>(fixed.plane[0]);
  const float p1 = static_cast<float>(fixed.plane[1]);
  const float p2 = static_cast<float>(fixed.plane[2]);
  const float p3 = static_cast<float>(fixed.plane[3]);
  const float weight = static_cast<float>(fixed.weight);
  const float d = fmaf(p0, x, fmaf(p1, y, fmaf(p2, z, p3)));
  float derivative = 0.0f;
  float residual = 0.0f;
  if (fixed.mode == static_cast<uint8_t>(LidarResidualMode::kSigned)) {
    residual = weight * d;
    derivative = weight;
  } else {
    const float magnitude = sqrtf(d * d);
    residual = weight * magnitude;
    if (fixed.mode ==
            static_cast<uint8_t>(LidarResidualMode::kLegacyGuarded) &&
        fabsf(d) <= static_cast<float>(fixed.near_zero_threshold)) {
      derivative = 0.0f;
    } else {
      derivative = weight * d / magnitude;
    }
  }
  output[index].residual = residual;
  output[index].point_jacobian[0] = derivative * p0;
  output[index].point_jacobian[1] = derivative * p1;
  output[index].point_jacobian[2] = derivative * p2;
  output[index].finite =
      MixedFinite(residual) && MixedFinite(output[index].point_jacobian[0]) &&
              MixedFinite(output[index].point_jacobian[1]) &&
              MixedFinite(output[index].point_jacobian[2])
          ? 1u
          : 0u;
  if (output[index].finite == 0) output[index].residual = nanf("");
}

__global__ void LayerAVisualMixedFromCompactKernel(
    const CudaCompactVisualOutput* input,
    MixedVisualOutput* output,
    const size_t count) {
  const size_t index = blockIdx.x * blockDim.x + threadIdx.x;
  if (index >= count) return;
  const CudaCompactVisualOutput source = input[index];
  MixedVisualOutput destination{};
  bool finite = (source.status & 1u) != 0;
  for (uint32_t i = 0; i < 2; ++i) {
    destination.residual[i] = static_cast<float>(source.residual[i]);
    finite &= MixedFinite(destination.residual[i]);
  }
  for (uint32_t i = 0; i < 12; ++i) {
    destination.pose_jacobian[i] =
        static_cast<float>(source.pose_jacobian[i]);
    finite &= MixedFinite(destination.pose_jacobian[i]);
  }
  for (uint32_t i = 0; i < 6; ++i) {
    destination.point_jacobian[i] =
        static_cast<float>(source.point_jacobian[i]);
    finite &= MixedFinite(destination.point_jacobian[i]);
  }
  destination.finite = finite ? 1u : 0u;
  if (!finite) destination.residual[0] = nanf("");
  output[index] = destination;
}

__global__ void LayerAVisualMixedFromFullKernel(
    const CudaVisualOutput* input,
    MixedVisualOutput* output,
    const size_t count) {
  const size_t index = blockIdx.x * blockDim.x + threadIdx.x;
  if (index >= count) return;
  const CudaVisualOutput source = input[index];
  MixedVisualOutput destination{};
  bool finite = source.finite != 0;
  for (uint32_t row = 0; row < 2; ++row) {
    destination.residual[row] = static_cast<float>(source.residual[row]);
    finite &= MixedFinite(destination.residual[row]);
    for (uint32_t i = 0; i < 3; ++i) {
      destination.pose_jacobian[row * 6 + i] =
          static_cast<float>(source.local_rotation_jacobian[row * 3 + i]);
      destination.pose_jacobian[row * 6 + 3 + i] =
          static_cast<float>(source.translation_jacobian[row * 3 + i]);
      destination.point_jacobian[row * 3 + i] =
          static_cast<float>(source.point_jacobian[row * 3 + i]);
      finite &= MixedFinite(destination.pose_jacobian[row * 6 + i]) &&
                MixedFinite(destination.pose_jacobian[row * 6 + 3 + i]) &&
                MixedFinite(destination.point_jacobian[row * 3 + i]);
    }
  }
  destination.finite = finite ? 1u : 0u;
  if (!finite) destination.residual[0] = nanf("");
  output[index] = destination;
}

__global__ void LayerALidarMixedFromDoubleKernel(
    const CudaLidarOutput* input,
    MixedLidarOutput* output,
    const size_t count) {
  const size_t index = blockIdx.x * blockDim.x + threadIdx.x;
  if (index >= count) return;
  const CudaLidarOutput source = input[index];
  MixedLidarOutput destination{};
  bool finite = source.finite != 0;
  destination.residual = static_cast<float>(source.residual);
  finite &= MixedFinite(destination.residual);
  for (uint32_t i = 0; i < 3; ++i) {
    destination.point_jacobian[i] =
        static_cast<float>(source.point_jacobian[i]);
    finite &= MixedFinite(destination.point_jacobian[i]);
  }
  destination.finite = finite ? 1u : 0u;
  if (!finite) destination.residual = nanf("");
  output[index] = destination;
}

