};

__device__ inline double DeviceLossJacobianScale(
    const double squared_norm,
    const uint8_t loss_mode,
    const double loss_scale) {
  if (loss_mode != static_cast<uint8_t>(CudaLossMode::kSoftL1)) return 1.0;
  const double inverse_scale_squared = 1.0 / (loss_scale * loss_scale);
  const double root = sqrt(1.0 + squared_norm * inverse_scale_squared);
  const double rho1 = fmax(DBL_MIN, 1.0 / root);
  return sqrt(rho1);
}

__device__ inline double DeviceLossCost(const double squared_norm,
                                        const uint8_t loss_mode,
                                        const double loss_scale) {
  if (loss_mode != static_cast<uint8_t>(CudaLossMode::kSoftL1)) {
    return 0.5 * squared_norm;
  }
  const double scale_squared = loss_scale * loss_scale;
  return scale_squared *
         (sqrt(1.0 + squared_norm / scale_squared) - 1.0);
}

__device__ inline void FillPoseJacobian(
                                        const DeviceCanonicalVisualValue& visual,
                                        const DevicePoseMeta& pose,
                                        const size_t row,
                                        double* jacobian) {
  jacobian[0] = visual.pose_jacobian[row * 6 + 0];
  jacobian[1] = visual.pose_jacobian[row * 6 + 1];
  jacobian[2] = visual.pose_jacobian[row * 6 + 2];
  for (uint32_t index = 3; index < pose.dimension; ++index) {
    jacobian[index] = visual.pose_jacobian[
        row * 6 + 3 + pose.free_translation_indices[index - 3]];
  }
}

__global__ void LayerBPoseKernel(const DevicePoseMeta* metadata,
                                 const uint32_t* adjacency,
                                 const void* visual,
                                 bool compact_visual,
                                 uint8_t loss_mode,
                                 double loss_scale,
                                 const double* frozen_jacobi_scaling,
                                 double min_lm_diagonal,
                                 double max_lm_diagonal,
                                 CudaPoseBlockOutput* output,
                                 size_t count) {
  const size_t index = blockIdx.x * blockDim.x + threadIdx.x;
  if (index >= count) return;
  const DevicePoseMeta pose = metadata[index];
  double hessian[36] = {};
  double gradient[6] = {};
  for (uint32_t entry = pose.adjacency_begin;
       entry < pose.adjacency_end; ++entry) {
    const DeviceCanonicalVisualValue value =
        LoadCanonicalVisual(visual, compact_visual, adjacency[entry]);
    const double robust_scale = DeviceLossJacobianScale(
        value.residual[0] * value.residual[0] +
            value.residual[1] * value.residual[1],
        loss_mode, loss_scale);
    for (size_t row = 0; row < 2; ++row) {
      double jacobian[6] = {};
      FillPoseJacobian(value, pose, row, jacobian);
      for (uint32_t i = 0; i < pose.dimension; ++i) {
        const double ji = jacobian[i] * robust_scale;
        const double residual = value.residual[row] * robust_scale;
        gradient[i] += ji * residual;
        for (uint32_t j = 0; j < pose.dimension; ++j) {
          hessian[i * pose.dimension + j] +=
              ji * (jacobian[j] * robust_scale);
        }
      }
    }
  }
  CudaPoseBlockOutput& result = output[index];
  result.image_id = pose.image_id;
  result.dimension = pose.dimension;
  for (size_t i = 0; i < 3; ++i) {
    result.free_translation_indices[i] = pose.free_translation_indices[i];
  }
  for (uint32_t i = 0; i < pose.dimension; ++i) {
    result.gradient[i] = gradient[i];
    const double diagonal = fmax(0.0, hessian[i * pose.dimension + i]);
    const double scale = frozen_jacobi_scaling == nullptr
                             ? 1.0 / (1.0 + sqrt(diagonal))
                             : frozen_jacobi_scaling[index * 6 + i];
    const double scaled_diagonal =
        hessian[i * pose.dimension + i] * scale * scale;
    const double clamped =
        fmin(fmax(scaled_diagonal, min_lm_diagonal), max_lm_diagonal);
    result.jacobi_scaling[i] = scale;
    result.damping[i] = clamped / (scale * scale);
    for (uint32_t j = 0; j < pose.dimension; ++j) {
      result.hessian[i * pose.dimension + j] =
          hessian[i * pose.dimension + j];
    }
  }
}

// The optimized pose kernel changes only ownership and input loading. Each
// active Hessian/gradient scalar has one owner and visits observations and the
// two residual rows in the exact reference order. Shared memory stages input
// values; it never groups or reduces floating-point contributions.
constexpr int kLayerBPoseOptimizedThreads = 64;
constexpr int kLayerBPoseObservationTile = 8;

__global__ void LayerBPoseOptimizedKernel(
    const DevicePoseMeta* metadata,
    const uint32_t* adjacency,
    const void* visual,
    bool compact_visual,
    uint8_t loss_mode,
    double loss_scale,
    const double* frozen_jacobi_scaling,
    double min_lm_diagonal,
    double max_lm_diagonal,
    CudaPoseBlockOutput* output,
    size_t count) {
  const size_t pose_index = blockIdx.x;
  if (pose_index >= count) return;
  const DevicePoseMeta pose = metadata[pose_index];
  const uint32_t thread = threadIdx.x;
  const bool owns_hessian = thread < pose.dimension * pose.dimension;
  const bool owns_gradient =
      thread >= 36 && thread < 36 + pose.dimension;
  const uint32_t hessian_row = owns_hessian ? thread / pose.dimension : 0;
  const uint32_t hessian_col = owns_hessian ? thread % pose.dimension : 0;
  const uint32_t gradient_row = owns_gradient ? thread - 36 : 0;
  double hessian = 0.0;
  double gradient = 0.0;

  __shared__ double shared_scale[kLayerBPoseObservationTile];
  __shared__ double shared_residual[kLayerBPoseObservationTile][2];
  __shared__ double shared_jacobian[kLayerBPoseObservationTile][2][6];
  for (uint32_t tile_begin = pose.adjacency_begin;
       tile_begin < pose.adjacency_end;
       tile_begin += kLayerBPoseObservationTile) {
    const uint32_t tile_count = min(
        static_cast<uint32_t>(kLayerBPoseObservationTile),
        pose.adjacency_end - tile_begin);
    if (thread < tile_count) {
      const DeviceCanonicalVisualValue value = LoadCanonicalVisual(
          visual, compact_visual, adjacency[tile_begin + thread]);
      const double robust_scale = DeviceLossJacobianScale(
          value.residual[0] * value.residual[0] +
              value.residual[1] * value.residual[1],
          loss_mode, loss_scale);
      shared_scale[thread] = robust_scale;
      for (size_t row = 0; row < 2; ++row) {
        shared_residual[thread][row] = value.residual[row];
        FillPoseJacobian(value, pose, row,
                         shared_jacobian[thread][row]);
      }
    }
    __syncthreads();
    if (owns_hessian) {
      for (uint32_t item = 0; item < tile_count; ++item) {
        const double robust_scale = shared_scale[item];
        for (size_t row = 0; row < 2; ++row) {
          const double ji =
              shared_jacobian[item][row][hessian_row] * robust_scale;
          hessian += ji *
              (shared_jacobian[item][row][hessian_col] * robust_scale);
        }
      }
    }
    if (owns_gradient) {
      for (uint32_t item = 0; item < tile_count; ++item) {
        const double robust_scale = shared_scale[item];
        for (size_t row = 0; row < 2; ++row) {
          const double ji =
              shared_jacobian[item][row][gradient_row] * robust_scale;
          const double residual = shared_residual[item][row] * robust_scale;
          gradient += ji * residual;
        }
      }
    }
    __syncthreads();
  }

  CudaPoseBlockOutput& result = output[pose_index];
  if (thread == 0) {
    result.image_id = pose.image_id;
    result.dimension = pose.dimension;
    for (size_t i = 0; i < 3; ++i)
      result.free_translation_indices[i] = pose.free_translation_indices[i];
  }
  if (owns_hessian) {
    result.hessian[thread] = hessian;
    if (hessian_row == hessian_col) {
      const double diagonal = fmax(0.0, hessian);
      const double scale = frozen_jacobi_scaling == nullptr
                               ? 1.0 / (1.0 + sqrt(diagonal))
                               : frozen_jacobi_scaling[pose_index * 6 +
                                                       hessian_row];
      const double scaled_diagonal = hessian * scale * scale;
      const double clamped = fmin(fmax(scaled_diagonal, min_lm_diagonal),
                                  max_lm_diagonal);
      result.jacobi_scaling[hessian_row] = scale;
      result.damping[hessian_row] = clamped / (scale * scale);
    }
  }
  if (owns_gradient) result.gradient[gradient_row] = gradient;
}

// Segmented Hessian keeps a small compatibility-order gradient finalize. One
// block stages each observation once; six scalar owners reproduce the exact
// historical observation/row order without serializing the 36 Hessian owners.
__global__ void LayerBPoseGradientCompatibilityKernel(
    const DevicePoseMeta* metadata,
    const uint32_t* adjacency,
    const void* visual,
    bool compact_visual,
    uint8_t loss_mode,
    double loss_scale,
    CudaPoseBlockOutput* output,
    size_t count) {
  const size_t pose_index = blockIdx.x;
  if (pose_index >= count) return;
  const DevicePoseMeta pose = metadata[pose_index];
  const uint32_t thread = threadIdx.x;
  const bool owner = thread < pose.dimension;
  double gradient = 0.0;
  constexpr uint32_t kGradientTile = 64;
  __shared__ double shared_scale[kGradientTile];
  __shared__ double shared_residual[kGradientTile][2];
  __shared__ double shared_jacobian[kGradientTile][2][6];
  for (uint32_t tile_begin = pose.adjacency_begin;
       tile_begin < pose.adjacency_end;
       tile_begin += kGradientTile) {
    const uint32_t tile_count = min(
        kGradientTile, pose.adjacency_end - tile_begin);
    if (thread < tile_count) {
      const DeviceCanonicalVisualValue value = LoadCanonicalVisual(
          visual, compact_visual, adjacency[tile_begin + thread]);
      shared_scale[thread] = DeviceLossJacobianScale(
          value.residual[0] * value.residual[0] +
              value.residual[1] * value.residual[1],
          loss_mode, loss_scale);
      for (uint32_t row = 0; row < 2; ++row) {
        shared_residual[thread][row] = value.residual[row];
        FillPoseJacobian(value, pose, row, shared_jacobian[thread][row]);
      }
    }
    __syncthreads();
    if (owner) {
      for (uint32_t item = 0; item < tile_count; ++item) {
        const double scale = shared_scale[item];
        for (uint32_t row = 0; row < 2; ++row) {
          gradient += (shared_jacobian[item][row][thread] * scale) *
                      (shared_residual[item][row] * scale);
        }
      }
    }
    __syncthreads();
  }
  if (owner) output[pose_index].gradient[thread] = gradient;
}

__global__ void LayerBPointKernel(const DevicePointMeta* metadata,
                                  const uint32_t* target_indices,
                                  const DevicePointAdjacency* adjacency,
                                  const void* visual,
                                  bool compact_visual,
                                  const CudaLidarOutput* lidar,
                                  uint8_t loss_mode,
                                  double loss_scale,
                                  const double* frozen_jacobi_scaling,
                                  double min_lm_diagonal,
                                  double max_lm_diagonal,
                                  CudaPointBlockOutput* output,
                                  size_t count) {
  const size_t work_index = blockIdx.x * blockDim.x + threadIdx.x;
  if (work_index >= count) return;
  const size_t index = target_indices == nullptr
                           ? work_index
                           : target_indices[work_index];
  const DevicePointMeta point = metadata[index];
  double hessian[9] = {};
  double gradient[3] = {};
  for (uint32_t entry = point.adjacency_begin;
       entry < point.adjacency_end; ++entry) {
    const DevicePointAdjacency binding = adjacency[entry];
    if (binding.residual_kind == 0) {
      const DeviceCanonicalVisualValue value = LoadCanonicalVisual(
          visual, compact_visual, binding.residual_index);
      const double robust_scale = DeviceLossJacobianScale(
          value.residual[0] * value.residual[0] +
              value.residual[1] * value.residual[1],
          loss_mode, loss_scale);
      for (size_t row = 0; row < 2; ++row) {
        for (size_t i = 0; i < 3; ++i) {
          const double ji =
              value.point_jacobian[row * 3 + i] * robust_scale;
          gradient[i] += ji * value.residual[row] * robust_scale;
          for (size_t j = 0; j < 3; ++j) {
            hessian[i * 3 + j] +=
                ji * value.point_jacobian[row * 3 + j] * robust_scale;
          }
        }
      }
    } else {
      const CudaLidarOutput value = lidar[binding.residual_index];
      const double robust_scale = DeviceLossJacobianScale(
          value.residual * value.residual, loss_mode, loss_scale);
      for (size_t i = 0; i < 3; ++i) {
        const double ji = value.point_jacobian[i] * robust_scale;
        gradient[i] += ji * value.residual * robust_scale;
        for (size_t j = 0; j < 3; ++j) {
          hessian[i * 3 + j] += ji * value.point_jacobian[j] * robust_scale;
        }
      }
    }
  }
  CudaPointBlockOutput& result = output[index];
  result.point3D_id = point.point3D_id;
  for (size_t i = 0; i < 3; ++i) {
    result.gradient[i] = gradient[i];
    const double diagonal = fmax(0.0, hessian[i * 3 + i]);
    const double scale = frozen_jacobi_scaling == nullptr
                             ? 1.0 / (1.0 + sqrt(diagonal))
                             : frozen_jacobi_scaling[index * 3 + i];
    const double scaled_diagonal = hessian[i * 3 + i] * scale * scale;
    const double clamped =
        fmin(fmax(scaled_diagonal, min_lm_diagonal), max_lm_diagonal);
    result.jacobi_scaling[i] = scale;
    result.damping[i] = clamped / (scale * scale);
    for (size_t j = 0; j < 3; ++j) {
      result.hessian[i * 3 + j] = hessian[i * 3 + j];
    }
  }
}

__global__ void LayerBEdgeKernel(const DeviceEdgeMeta* metadata,
                                 const uint32_t* adjacency,
                                 const DevicePoseMeta* poses,
                                 const void* visual,
                                 bool compact_visual,
                                 uint8_t loss_mode,
                                 double loss_scale,
                                 CudaEdgeBlockOutput* output,
                                 size_t count) {
  const size_t index = blockIdx.x * blockDim.x + threadIdx.x;
  if (index >= count) return;
  const DeviceEdgeMeta edge = metadata[index];
  const DevicePoseMeta pose = poses[edge.pose_index];
  double value[18] = {};
  for (uint32_t entry = edge.adjacency_begin;
       entry < edge.adjacency_end; ++entry) {
    const DeviceCanonicalVisualValue residual =
        LoadCanonicalVisual(visual, compact_visual, adjacency[entry]);
    const double robust_scale = DeviceLossJacobianScale(
        residual.residual[0] * residual.residual[0] +
            residual.residual[1] * residual.residual[1],
        loss_mode, loss_scale);
    for (size_t row = 0; row < 2; ++row) {
      double pose_jacobian[6] = {};
      FillPoseJacobian(residual, pose, row, pose_jacobian);
      for (uint32_t i = 0; i < pose.dimension; ++i) {
        for (size_t j = 0; j < 3; ++j) {
          value[i * 3 + j] +=
              (pose_jacobian[i] * robust_scale) *
              (residual.point_jacobian[row * 3 + j] * robust_scale);
        }
      }
    }
  }
  CudaEdgeBlockOutput& result = output[index];
  result.pose_index = edge.pose_index;
  result.point_index = edge.point_index;
  result.pose_dimension = edge.pose_dimension;
  for (size_t i = 0; i < edge.pose_dimension * 3; ++i) {
    result.value[i] = value[i];
  }
}

constexpr uint32_t kPoseAssemblyPartialScalars = 42;  // 6x6 + 6
constexpr uint32_t kPointAssemblyPartialScalars = 12;  // 3x3 + 3
constexpr uint32_t kEdgeAssemblyPartialScalars = 18;   // 6x3
constexpr uint32_t kObservationAssemblyThreads = 128;
constexpr uint32_t kObservationSegmentThreads = 64;

__global__ void LayerBObservationVisualAtomicKernel(
    const DeviceVisualAssemblyBinding* bindings,
    const DevicePoseMeta* poses,
    const DeviceEdgeMeta* edges,
    const void* visual,
    bool compact_visual,
    uint8_t loss_mode,
    double loss_scale,
    CudaPoseBlockOutput* pose_output,
    CudaPointBlockOutput* point_output,
    CudaEdgeBlockOutput* edge_output,
    size_t count) {
  const size_t residual_index = blockIdx.x * blockDim.x + threadIdx.x;
  if (residual_index >= count) return;
  const DeviceVisualAssemblyBinding binding = bindings[residual_index];
  const DeviceCanonicalVisualValue value =
      LoadCanonicalVisual(visual, compact_visual, residual_index);
  const double robust_scale = DeviceLossJacobianScale(
      value.residual[0] * value.residual[0] +
          value.residual[1] * value.residual[1],
      loss_mode, loss_scale);
  const bool has_pose = binding.pose_index != kInvalidAssemblyTarget;
  const bool has_point = binding.point_index != kInvalidAssemblyTarget;
  DevicePoseMeta pose{};
  if (has_pose) pose = poses[binding.pose_index];
  for (uint32_t row = 0; row < 2; ++row) {
    double pose_jacobian[6] = {};
    if (has_pose) FillPoseJacobian(value, pose, row, pose_jacobian);
    const double weighted_residual = value.residual[row] * robust_scale;
    if (has_pose) {
      CudaPoseBlockOutput& output = pose_output[binding.pose_index];
      for (uint32_t i = 0; i < pose.dimension; ++i) {
        const double ji = pose_jacobian[i] * robust_scale;
        atomicAdd(&output.gradient[i], ji * weighted_residual);
        for (uint32_t j = 0; j < pose.dimension; ++j) {
          atomicAdd(&output.hessian[i * pose.dimension + j],
                    ji * (pose_jacobian[j] * robust_scale));
        }
      }
    }
    if (has_point) {
      CudaPointBlockOutput& output = point_output[binding.point_index];
      for (uint32_t i = 0; i < 3; ++i) {
        const double ji = value.point_jacobian[row * 3 + i] * robust_scale;
        atomicAdd(&output.gradient[i], ji * weighted_residual);
        for (uint32_t j = 0; j < 3; ++j) {
          atomicAdd(&output.hessian[i * 3 + j],
                    ji * (value.point_jacobian[row * 3 + j] * robust_scale));
        }
      }
    }
    if (binding.edge_index != kInvalidAssemblyTarget) {
      const DeviceEdgeMeta edge = edges[binding.edge_index];
      CudaEdgeBlockOutput& output = edge_output[binding.edge_index];
      const bool unique_owner =
          edge.adjacency_end - edge.adjacency_begin == 1;
      for (uint32_t i = 0; i < edge.pose_dimension; ++i) {
        const double ji = pose_jacobian[i] * robust_scale;
        for (uint32_t j = 0; j < 3; ++j) {
          const double contribution =
              ji * (value.point_jacobian[row * 3 + j] * robust_scale);
          if (unique_owner) {
            output.value[i * 3 + j] += contribution;
          } else {
            atomicAdd(&output.value[i * 3 + j], contribution);
          }
        }
      }
    }
  }
}

__global__ void LayerBObservationLidarAtomicKernel(
    const DeviceLidarAssemblyBinding* bindings,
    const CudaLidarOutput* lidar,
    uint8_t loss_mode,
    double loss_scale,
    CudaPointBlockOutput* point_output,
    size_t count) {
  const size_t residual_index = blockIdx.x * blockDim.x + threadIdx.x;
  if (residual_index >= count) return;
  const uint32_t point_index = bindings[residual_index].point_index;
  if (point_index == kInvalidAssemblyTarget) return;
  const CudaLidarOutput value = lidar[residual_index];
  const double robust_scale = DeviceLossJacobianScale(
      value.residual * value.residual, loss_mode, loss_scale);
  const double weighted_residual = value.residual * robust_scale;
  CudaPointBlockOutput& output = point_output[point_index];
  for (uint32_t i = 0; i < 3; ++i) {
    const double ji = value.point_jacobian[i] * robust_scale;
    atomicAdd(&output.gradient[i], ji * weighted_residual);
    for (uint32_t j = 0; j < 3; ++j) {
      atomicAdd(&output.hessian[i * 3 + j],
                ji * (value.point_jacobian[j] * robust_scale));
    }
  }
}

__global__ void LayerBFinalizePoseKernel(
    const DevicePoseMeta* metadata,
    const double* frozen_jacobi_scaling,
    double min_lm_diagonal,
    double max_lm_diagonal,
    CudaPoseBlockOutput* output,
    size_t count) {
  const size_t index = blockIdx.x * blockDim.x + threadIdx.x;
  if (index >= count) return;
  const DevicePoseMeta pose = metadata[index];
  CudaPoseBlockOutput& result = output[index];
  result.image_id = pose.image_id;
  result.dimension = pose.dimension;
  for (uint32_t i = 0; i < 3; ++i)
    result.free_translation_indices[i] = pose.free_translation_indices[i];
  for (uint32_t i = 0; i < pose.dimension; ++i) {
    const double raw = result.hessian[i * pose.dimension + i];
    const double diagonal = fmax(0.0, raw);
    const double scale = frozen_jacobi_scaling == nullptr
        ? 1.0 / (1.0 + sqrt(diagonal))
        : frozen_jacobi_scaling[index * 6 + i];
    const double scaled_diagonal = raw * scale * scale;
    const double clamped =
        fmin(fmax(scaled_diagonal, min_lm_diagonal), max_lm_diagonal);
    result.jacobi_scaling[i] = scale;
    result.damping[i] = clamped / (scale * scale);
  }
}

__global__ void LayerBFinalizePointKernel(
    const DevicePointMeta* metadata,
    const double* frozen_jacobi_scaling,
    double min_lm_diagonal,
    double max_lm_diagonal,
    CudaPointBlockOutput* output,
    size_t count) {
  const size_t index = blockIdx.x * blockDim.x + threadIdx.x;
  if (index >= count) return;
  const DevicePointMeta point = metadata[index];
  CudaPointBlockOutput& result = output[index];
  result.point3D_id = point.point3D_id;
  for (uint32_t i = 0; i < 3; ++i) {
    const double raw = result.hessian[i * 3 + i];
    const double diagonal = fmax(0.0, raw);
    const double scale = frozen_jacobi_scaling == nullptr
        ? 1.0 / (1.0 + sqrt(diagonal))
        : frozen_jacobi_scaling[index * 3 + i];
    const double scaled_diagonal = raw * scale * scale;
    const double clamped =
        fmin(fmax(scaled_diagonal, min_lm_diagonal), max_lm_diagonal);
    result.jacobi_scaling[i] = scale;
    result.damping[i] = clamped / (scale * scale);
