}

__global__ void LayerBFinalizeEdgeKernel(const DeviceEdgeMeta* metadata,
                                         CudaEdgeBlockOutput* output,
                                         size_t count) {
  const size_t index = blockIdx.x * blockDim.x + threadIdx.x;
  if (index >= count) return;
  const DeviceEdgeMeta edge = metadata[index];
  output[index].pose_index = edge.pose_index;
  output[index].point_index = edge.point_index;
