__global__ void LayerBPoseSegmentPartialKernel(
    const DeviceAssemblySegment* segments,
    const uint32_t* adjacency,
    const DevicePoseMeta* metadata,
    const void* visual,
    bool compact_visual,
    uint8_t loss_mode,
    double loss_scale,
    double* partials,
    size_t segment_count) {
  const size_t segment_index = blockIdx.x;
  if (segment_index >= segment_count) return;
  const DeviceAssemblySegment segment = segments[segment_index];
  const DevicePoseMeta pose = metadata[segment.target_index];
  const uint32_t scalar = threadIdx.x;
  const uint32_t item_count = segment.adjacency_end - segment.adjacency_begin;
  __shared__ double shared_scale[64];
  __shared__ double shared_residual[64][2];
  __shared__ double shared_jacobian[64][2][6];
  if (scalar < item_count) {
    const DeviceCanonicalVisualValue value = LoadCanonicalVisual(
        visual, compact_visual, adjacency[segment.adjacency_begin + scalar]);
    shared_scale[scalar] = DeviceLossJacobianScale(
        value.residual[0] * value.residual[0] +
            value.residual[1] * value.residual[1],
        loss_mode, loss_scale);
    for (uint32_t row = 0; row < 2; ++row) {
      shared_residual[scalar][row] = value.residual[row];
      FillPoseJacobian(value, pose, row, shared_jacobian[scalar][row]);
    }
  }
  __syncthreads();
  double sum = 0.0;
  if (scalar < kPoseAssemblyPartialScalars) {
    const bool gradient = scalar >= 36;
    const uint32_t i = gradient ? scalar - 36 : scalar / 6;
    const uint32_t j = gradient ? 0 : scalar % 6;
    if (!gradient && i < pose.dimension && j < pose.dimension) {
      for (uint32_t item = 0; item < item_count; ++item) {
        const double scale = shared_scale[item];
        for (uint32_t row = 0; row < 2; ++row) {
          const double ji = shared_jacobian[item][row][i] * scale;
          sum += gradient
              ? ji * (shared_residual[item][row] * scale)
              : ji * (shared_jacobian[item][row][j] * scale);
        }
      }
    }
    partials[segment_index * kPoseAssemblyPartialScalars + scalar] = sum;
  }
}

__global__ void LayerBPointSegmentPartialKernel(
    const DeviceAssemblySegment* segments,
    const DevicePointAdjacency* adjacency,
    const void* visual,
    bool compact_visual,
    const CudaLidarOutput* lidar,
    uint8_t loss_mode,
    double loss_scale,
    double* partials,
    size_t segment_count) {
  const size_t segment_index = blockIdx.x;
  if (segment_index >= segment_count) return;
  const DeviceAssemblySegment segment = segments[segment_index];
  const uint32_t scalar = threadIdx.x;
  const uint32_t item_count = segment.adjacency_end - segment.adjacency_begin;
  __shared__ double shared_scale[64];
  __shared__ double shared_residual[64][2];
  __shared__ double shared_jacobian[64][2][3];
  __shared__ uint8_t shared_rows[64];
  if (scalar < item_count) {
    const DevicePointAdjacency binding =
        adjacency[segment.adjacency_begin + scalar];
    if (binding.residual_kind == 0) {
      const DeviceCanonicalVisualValue value = LoadCanonicalVisual(
          visual, compact_visual, binding.residual_index);
      shared_scale[scalar] = DeviceLossJacobianScale(
          value.residual[0] * value.residual[0] +
              value.residual[1] * value.residual[1],
          loss_mode, loss_scale);
      shared_rows[scalar] = 2;
      for (uint32_t row = 0; row < 2; ++row) {
        shared_residual[scalar][row] = value.residual[row];
        for (uint32_t i = 0; i < 3; ++i)
          shared_jacobian[scalar][row][i] =
              value.point_jacobian[row * 3 + i];
      }
    } else {
      const CudaLidarOutput value = lidar[binding.residual_index];
      shared_scale[scalar] = DeviceLossJacobianScale(
          value.residual * value.residual, loss_mode, loss_scale);
      shared_rows[scalar] = 1;
      shared_residual[scalar][0] = value.residual;
      shared_residual[scalar][1] = 0.0;
      for (uint32_t i = 0; i < 3; ++i) {
        shared_jacobian[scalar][0][i] = value.point_jacobian[i];
        shared_jacobian[scalar][1][i] = 0.0;
      }
    }
  }
  __syncthreads();
  if (scalar >= kPointAssemblyPartialScalars) return;
  const bool gradient = scalar >= 9;
  const uint32_t i = gradient ? scalar - 9 : scalar / 3;
  const uint32_t j = gradient ? 0 : scalar % 3;
  double sum = 0.0;
  for (uint32_t item = 0; item < item_count; ++item) {
    const double scale = shared_scale[item];
    for (uint32_t row = 0; row < shared_rows[item]; ++row) {
      const double ji = shared_jacobian[item][row][i] * scale;
      sum += gradient
          ? ji * (shared_residual[item][row] * scale)
          : ji * (shared_jacobian[item][row][j] * scale);
    }
  }
  partials[segment_index * kPointAssemblyPartialScalars + scalar] = sum;
}

__global__ void LayerBEdgeSegmentPartialKernel(
    const DeviceAssemblySegment* segments,
    const uint32_t* adjacency,
    const DeviceEdgeMeta* metadata,
    const DevicePoseMeta* poses,
    const void* visual,
    bool compact_visual,
    uint8_t loss_mode,
    double loss_scale,
    double* partials,
    size_t segment_count) {
  const size_t segment_index = blockIdx.x;
  if (segment_index >= segment_count) return;
  const DeviceAssemblySegment segment = segments[segment_index];
  const DeviceEdgeMeta edge = metadata[segment.target_index];
  const DevicePoseMeta pose = poses[edge.pose_index];
  const uint32_t scalar = threadIdx.x;
  double sum = 0.0;
  const uint32_t i = scalar / 3;
  const uint32_t j = scalar % 3;
  if (scalar < kEdgeAssemblyPartialScalars && i < edge.pose_dimension) {
    for (uint32_t entry = segment.adjacency_begin;
         entry < segment.adjacency_end; ++entry) {
      const DeviceCanonicalVisualValue value = LoadCanonicalVisual(
          visual, compact_visual, adjacency[entry]);
      const double scale = DeviceLossJacobianScale(
          value.residual[0] * value.residual[0] +
              value.residual[1] * value.residual[1],
          loss_mode, loss_scale);
      for (uint32_t row = 0; row < 2; ++row) {
        double pose_jacobian[6] = {};
        FillPoseJacobian(value, pose, row, pose_jacobian);
        sum += (pose_jacobian[i] * scale) *
               (value.point_jacobian[row * 3 + j] * scale);
      }
    }
  }
  if (scalar < kEdgeAssemblyPartialScalars) {
    partials[segment_index * kEdgeAssemblyPartialScalars + scalar] = sum;
  }
}

__global__ void LayerBPoseSegmentMergeKernel(
    const DevicePoseMeta* metadata,
    const DeviceAssemblyTargetRange* ranges,
    const double* partials,
    const double* frozen_jacobi_scaling,
    double min_lm_diagonal,
    double max_lm_diagonal,
    CudaPoseBlockOutput* output,
    size_t count) {
  const size_t target = blockIdx.x;
  if (target >= count) return;
  const DevicePoseMeta pose = metadata[target];
  const DeviceAssemblyTargetRange range = ranges[target];
  const uint32_t scalar = threadIdx.x;
  if (scalar == 0) {
    output[target].image_id = pose.image_id;
    output[target].dimension = pose.dimension;
    for (uint32_t i = 0; i < 3; ++i)
      output[target].free_translation_indices[i] =
          pose.free_translation_indices[i];
  }
  if (scalar >= kPoseAssemblyPartialScalars) return;
  double sum = 0.0;
  for (uint32_t segment = range.segment_begin;
       segment < range.segment_end; ++segment) {
    sum += partials[segment * kPoseAssemblyPartialScalars + scalar];
  }
  if (scalar < 36) {
    const uint32_t i = scalar / 6;
    const uint32_t j = scalar % 6;
    if (i < pose.dimension && j < pose.dimension) {
      output[target].hessian[i * pose.dimension + j] = sum;
      if (i == j) {
        const double diagonal = fmax(0.0, sum);
        const double scale = frozen_jacobi_scaling == nullptr
            ? 1.0 / (1.0 + sqrt(diagonal))
            : frozen_jacobi_scaling[target * 6 + i];
        const double scaled_diagonal = sum * scale * scale;
        const double clamped = fmin(
            fmax(scaled_diagonal, min_lm_diagonal), max_lm_diagonal);
        output[target].jacobi_scaling[i] = scale;
        output[target].damping[i] = clamped / (scale * scale);
      }
    }
  } else {
    const uint32_t i = scalar - 36;
    if (i < pose.dimension) output[target].gradient[i] = sum;
  }
}

__global__ void LayerBPointSegmentMergeKernel(
    const DevicePointMeta* metadata,
    const DeviceAssemblyTargetRange* ranges,
    const double* partials,
    const double* frozen_jacobi_scaling,
    double min_lm_diagonal,
    double max_lm_diagonal,
    CudaPointBlockOutput* output,
    size_t count) {
  const size_t target = blockIdx.x;
  if (target >= count) return;
  const DeviceAssemblyTargetRange range = ranges[target];
  if (range.segment_begin == range.segment_end) return;
  const uint32_t scalar = threadIdx.x;
  if (scalar == 0) output[target].point3D_id = metadata[target].point3D_id;
  if (scalar >= kPointAssemblyPartialScalars) return;
  double sum = 0.0;
  for (uint32_t segment = range.segment_begin;
       segment < range.segment_end; ++segment) {
    sum += partials[segment * kPointAssemblyPartialScalars + scalar];
  }
  if (scalar < 9) {
    const uint32_t i = scalar / 3;
    const uint32_t j = scalar % 3;
    output[target].hessian[scalar] = sum;
    if (i == j) {
      const double diagonal = fmax(0.0, sum);
      const double scale = frozen_jacobi_scaling == nullptr
          ? 1.0 / (1.0 + sqrt(diagonal))
          : frozen_jacobi_scaling[target * 3 + i];
      const double scaled_diagonal = sum * scale * scale;
      const double clamped = fmin(
          fmax(scaled_diagonal, min_lm_diagonal), max_lm_diagonal);
      output[target].jacobi_scaling[i] = scale;
      output[target].damping[i] = clamped / (scale * scale);
    }
  } else {
    output[target].gradient[scalar - 9] = sum;
  }
}

__global__ void LayerBEdgeSegmentMergeKernel(
    const DeviceEdgeMeta* metadata,
    const DeviceAssemblyTargetRange* ranges,
    const double* partials,
    CudaEdgeBlockOutput* output,
    size_t count) {
  const size_t target = blockIdx.x;
  if (target >= count) return;
  const DeviceEdgeMeta edge = metadata[target];
  const DeviceAssemblyTargetRange range = ranges[target];
  const uint32_t scalar = threadIdx.x;
  if (scalar == 0) {
    output[target].pose_index = edge.pose_index;
    output[target].point_index = edge.point_index;
    output[target].pose_dimension = edge.pose_dimension;
  }
  if (scalar >= kEdgeAssemblyPartialScalars ||
      scalar >= edge.pose_dimension * 3) return;
  double sum = 0.0;
  for (uint32_t segment = range.segment_begin;
       segment < range.segment_end; ++segment) {
    sum += partials[segment * kEdgeAssemblyPartialScalars + scalar];
  }
  output[target].value[scalar] = sum;
}

__device__ inline float MixedLossJacobianScale(
    const float squared_norm,
    const uint8_t loss_mode,
    const float loss_scale) {
  if (loss_mode != static_cast<uint8_t>(CudaLossMode::kSoftL1)) return 1.0f;
  const float root = sqrtf(1.0f + squared_norm /
                                      (loss_scale * loss_scale));
  return sqrtf(fmaxf(FLT_MIN, 1.0f / root));
}

__device__ inline void FillMixedPoseJacobian(
    const MixedVisualOutput& visual,
    const DevicePoseMeta& pose,
    const uint32_t row,
    float* jacobian) {
  jacobian[0] = visual.pose_jacobian[row * 6 + 0];
  jacobian[1] = visual.pose_jacobian[row * 6 + 1];
  jacobian[2] = visual.pose_jacobian[row * 6 + 2];
  for (uint32_t index = 3; index < pose.dimension; ++index) {
    jacobian[index] = visual.pose_jacobian[
        row * 6 + 3 + pose.free_translation_indices[index - 3]];
  }
}

__global__ void LayerBMixedPoseSegmentPartialKernel(
    const DeviceAssemblySegment* segments,
    const uint32_t* adjacency,
    const DevicePoseMeta* metadata,
    const MixedVisualOutput* visual,
    const uint8_t loss_mode,
    const float loss_scale,
    float* hessian_partials,
    const size_t segment_count) {
  const size_t segment_index = blockIdx.x;
  if (segment_index >= segment_count) return;
  const DeviceAssemblySegment segment = segments[segment_index];
  const DevicePoseMeta pose = metadata[segment.target_index];
  const uint32_t scalar = threadIdx.x;
  const uint32_t item_count = segment.adjacency_end - segment.adjacency_begin;
  __shared__ float shared_scale[64];
  __shared__ float shared_jacobian[64][2][6];
  if (scalar < item_count) {
    const MixedVisualOutput value =
        visual[adjacency[segment.adjacency_begin + scalar]];
    shared_scale[scalar] = MixedLossJacobianScale(
        value.residual[0] * value.residual[0] +
            value.residual[1] * value.residual[1],
        loss_mode, loss_scale);
    for (uint32_t row = 0; row < 2; ++row) {
      FillMixedPoseJacobian(value, pose, row,
                            shared_jacobian[scalar][row]);
    }
  }
  __syncthreads();
  if (scalar >= 36) return;
  const uint32_t i = scalar / 6;
  const uint32_t j = scalar % 6;
  float sum = 0.0f;
  if (i < pose.dimension && j < pose.dimension) {
    for (uint32_t item = 0; item < item_count; ++item) {
      const float scale = shared_scale[item];
      for (uint32_t row = 0; row < 2; ++row) {
        sum += (shared_jacobian[item][row][i] * scale) *
               (shared_jacobian[item][row][j] * scale);
      }
    }
  }
  hessian_partials[segment_index * 36 + scalar] = sum;
}

// Mixed Hessians consume float records, but gradients intentionally restart
// from the simultaneously produced FP64 compact records. This preserves the
// cancellation behavior needed by Schur RHS without recomputing geometry.
__global__ void LayerBMixedPoseGradientFromFp64Kernel(
    const DevicePoseMeta* metadata,
    const uint32_t* adjacency,
    const void* visual,
    const bool compact_visual,
    const uint8_t loss_mode,
    const double loss_scale,
    MixedPoseBlockOutput* output,
    const size_t count) {
  const size_t pose_index = blockIdx.x;
  if (pose_index >= count) return;
  const DevicePoseMeta pose = metadata[pose_index];
  const uint32_t owner = threadIdx.x;
  double gradient = 0.0;
  constexpr uint32_t kTile = 64;
  __shared__ double shared_scale[kTile];
  __shared__ double shared_residual[kTile][2];
  __shared__ double shared_jacobian[kTile][2][6];
  for (uint32_t begin = pose.adjacency_begin; begin < pose.adjacency_end;
       begin += kTile) {
    const uint32_t item_count = min(kTile, pose.adjacency_end - begin);
    if (owner < item_count) {
      const DeviceCanonicalVisualValue value =
          LoadCanonicalVisual(visual, compact_visual, adjacency[begin + owner]);
      shared_scale[owner] = DeviceLossJacobianScale(
          value.residual[0] * value.residual[0] +
              value.residual[1] * value.residual[1],
          loss_mode, loss_scale);
      for (uint32_t row = 0; row < 2; ++row) {
        shared_residual[owner][row] = value.residual[row];
        FillPoseJacobian(value, pose, row, shared_jacobian[owner][row]);
      }
    }
    __syncthreads();
    if (owner < pose.dimension) {
      for (uint32_t item = 0; item < item_count; ++item) {
        const double scale = shared_scale[item];
        for (uint32_t row = 0; row < 2; ++row) {
          const double jacobian = shared_jacobian[item][row][owner];
          const double residual = shared_residual[item][row];
          gradient += (jacobian * scale) * (residual * scale);
        }
      }
    }
    __syncthreads();
  }
  if (owner < pose.dimension) output[pose_index].gradient[owner] = gradient;
}

__global__ void LayerBMixedPointGradientFromFp64Kernel(
    const DevicePointMeta* metadata,
    const DevicePointAdjacency* adjacency,
    const void* visual,
    const bool compact_visual,
    const CudaLidarOutput* lidar,
    const uint8_t loss_mode,
    const double loss_scale,
    MixedPointBlockOutput* output,
    const size_t count) {
  const size_t point_index = blockIdx.x;
  const uint32_t owner = threadIdx.x;
  if (point_index >= count || owner >= 3) return;
  const DevicePointMeta point = metadata[point_index];
  double gradient = 0.0;
  for (uint32_t entry = point.adjacency_begin;
       entry < point.adjacency_end; ++entry) {
    const DevicePointAdjacency binding = adjacency[entry];
    if (binding.residual_kind == 0) {
      const DeviceCanonicalVisualValue value = LoadCanonicalVisual(
          visual, compact_visual, binding.residual_index);
      const double scale = DeviceLossJacobianScale(
          value.residual[0] * value.residual[0] +
              value.residual[1] * value.residual[1],
          loss_mode, loss_scale);
      for (uint32_t row = 0; row < 2; ++row) {
        gradient += (value.point_jacobian[row * 3 + owner] * scale) *
                    (value.residual[row] * scale);
      }
    } else {
      const CudaLidarOutput value = lidar[binding.residual_index];
      const double scale = DeviceLossJacobianScale(
          value.residual * value.residual, loss_mode, loss_scale);
      gradient += (value.point_jacobian[owner] * scale) *
                  (value.residual * scale);
    }
  }
  output[point_index].gradient[owner] = gradient;
}

__global__ void LayerBMixedPoseGradientFromFp32ForTestingKernel(
    const DevicePoseMeta* metadata,
    const uint32_t* adjacency,
    const MixedVisualOutput* visual,
    MixedPoseBlockOutput* output) {
  if (blockIdx.x != 0 || threadIdx.x != 0) return;
  const DevicePoseMeta pose = metadata[0];
  double gradient = 0.0;
  for (uint32_t entry = pose.adjacency_begin;
       entry < pose.adjacency_end; ++entry) {
    const MixedVisualOutput value = visual[adjacency[entry]];
    gradient += static_cast<double>(value.pose_jacobian[0]) *
                static_cast<double>(value.residual[0]);
  }
  output[0].gradient[0] = gradient;
}

__global__ void LayerBMixedPointDirectKernel(
    const DevicePointMeta* metadata,
    const uint32_t* target_indices,
    const DevicePointAdjacency* adjacency,
    const MixedVisualOutput* visual,
    const MixedLidarOutput* lidar,
    const uint8_t loss_mode,
    const float loss_scale,
    const double* frozen_jacobi_scaling,
    const float min_lm_diagonal,
    const float max_lm_diagonal,
    MixedPointBlockOutput* output,
    const size_t count) {
  const size_t work_index = blockIdx.x * blockDim.x + threadIdx.x;
  if (work_index >= count) return;
  const size_t target = target_indices == nullptr
                            ? work_index
                            : target_indices[work_index];
  const DevicePointMeta point = metadata[target];
  float hessian[9] = {};
  for (uint32_t entry = point.adjacency_begin;
       entry < point.adjacency_end; ++entry) {
    const DevicePointAdjacency binding = adjacency[entry];
    if (binding.residual_kind == 0) {
      const MixedVisualOutput value = visual[binding.residual_index];
      const float scale = MixedLossJacobianScale(
          value.residual[0] * value.residual[0] +
              value.residual[1] * value.residual[1],
          loss_mode, loss_scale);
      for (uint32_t row = 0; row < 2; ++row) {
        for (uint32_t i = 0; i < 3; ++i) {
          const float ji = value.point_jacobian[row * 3 + i] * scale;
          for (uint32_t j = 0; j < 3; ++j) {
            hessian[i * 3 + j] +=
                ji * (value.point_jacobian[row * 3 + j] * scale);
          }
        }
      }
    } else {
      const MixedLidarOutput value = lidar[binding.residual_index];
      const float scale = MixedLossJacobianScale(
          value.residual * value.residual, loss_mode, loss_scale);
      for (uint32_t i = 0; i < 3; ++i) {
        const float ji = value.point_jacobian[i] * scale;
        for (uint32_t j = 0; j < 3; ++j) {
          hessian[i * 3 + j] += ji * (value.point_jacobian[j] * scale);
        }
      }
    }
  }
  MixedPointBlockOutput& result = output[target];
  result.point3D_id = point.point3D_id;
  for (uint32_t i = 0; i < 3; ++i) {
    const float diagonal = fmaxf(0.0f, hessian[i * 3 + i]);
    const float scale = frozen_jacobi_scaling == nullptr
                            ? 1.0f / (1.0f + sqrtf(diagonal))
                            : static_cast<float>(
                                  frozen_jacobi_scaling[target * 3 + i]);
    const float scaled_diagonal = hessian[i * 3 + i] * scale * scale;
    const float clamped = fminf(fmaxf(scaled_diagonal, min_lm_diagonal),
                                max_lm_diagonal);
    result.jacobi_scaling[i] = scale;
    result.damping[i] = clamped / (scale * scale);
    for (uint32_t j = 0; j < 3; ++j) {
      result.hessian[i * 3 + j] = hessian[i * 3 + j];
    }
  }
}

__global__ void LayerBMixedPointSegmentPartialKernel(
    const DeviceAssemblySegment* segments,
    const DevicePointAdjacency* adjacency,
    const MixedVisualOutput* visual,
    const MixedLidarOutput* lidar,
    const uint8_t loss_mode,
    const float loss_scale,
    MixedPointAssemblyPartial* partials,
    const size_t segment_count) {
  const size_t segment_index = blockIdx.x;
  if (segment_index >= segment_count) return;
  const DeviceAssemblySegment segment = segments[segment_index];
  const uint32_t scalar = threadIdx.x;
  const uint32_t item_count = segment.adjacency_end - segment.adjacency_begin;
  __shared__ float shared_scale[64];
  __shared__ float shared_residual[64][2];
  __shared__ float shared_jacobian[64][2][3];
  __shared__ uint8_t shared_rows[64];
  if (scalar < item_count) {
    const DevicePointAdjacency binding =
        adjacency[segment.adjacency_begin + scalar];
    if (binding.residual_kind == 0) {
      const MixedVisualOutput value = visual[binding.residual_index];
      shared_scale[scalar] = MixedLossJacobianScale(
          value.residual[0] * value.residual[0] +
              value.residual[1] * value.residual[1],
          loss_mode, loss_scale);
      shared_rows[scalar] = 2;
      for (uint32_t row = 0; row < 2; ++row) {
        shared_residual[scalar][row] = value.residual[row];
        for (uint32_t i = 0; i < 3; ++i) {
          shared_jacobian[scalar][row][i] =
              value.point_jacobian[row * 3 + i];
        }
      }
    } else {
      const MixedLidarOutput value = lidar[binding.residual_index];
      shared_scale[scalar] = MixedLossJacobianScale(
          value.residual * value.residual, loss_mode, loss_scale);
      shared_rows[scalar] = 1;
      shared_residual[scalar][0] = value.residual;
      shared_residual[scalar][1] = 0.0f;
      for (uint32_t i = 0; i < 3; ++i) {
        shared_jacobian[scalar][0][i] = value.point_jacobian[i];
        shared_jacobian[scalar][1][i] = 0.0f;
      }
    }
  }
  __syncthreads();
  if (scalar < 9) {
    const uint32_t i = scalar / 3;
    const uint32_t j = scalar % 3;
    float sum = 0.0f;
    for (uint32_t item = 0; item < item_count; ++item) {
      const float scale = shared_scale[item];
      for (uint32_t row = 0; row < shared_rows[item]; ++row) {
        sum += (shared_jacobian[item][row][i] * scale) *
               (shared_jacobian[item][row][j] * scale);
      }
    }
    partials[segment_index].hessian[scalar] = sum;
  }
}

__global__ void LayerBMixedEdgeKernel(
    const DeviceEdgeMeta* metadata,
    const uint32_t* adjacency,
    const DevicePoseMeta* poses,
    const MixedVisualOutput* visual,
    const uint8_t loss_mode,
    const float loss_scale,
    MixedEdgeBlockOutput* output,
    const size_t count) {
  const size_t target = blockIdx.x * blockDim.x + threadIdx.x;
  if (target >= count) return;
  const DeviceEdgeMeta edge = metadata[target];
  const DevicePoseMeta pose = poses[edge.pose_index];
  MixedEdgeBlockOutput result{};
  result.pose_index = edge.pose_index;
  result.point_index = edge.point_index;
  result.pose_dimension = edge.pose_dimension;
  for (uint32_t entry = edge.adjacency_begin;
       entry < edge.adjacency_end; ++entry) {
    const MixedVisualOutput value = visual[adjacency[entry]];
    const float scale = MixedLossJacobianScale(
        value.residual[0] * value.residual[0] +
            value.residual[1] * value.residual[1],
        loss_mode, loss_scale);
    for (uint32_t row = 0; row < 2; ++row) {
      float pose_jacobian[6] = {};
      FillMixedPoseJacobian(value, pose, row, pose_jacobian);
      for (uint32_t i = 0; i < edge.pose_dimension; ++i) {
        for (uint32_t j = 0; j < 3; ++j) {
          result.value[i * 3 + j] +=
              (pose_jacobian[i] * scale) *
              (value.point_jacobian[row * 3 + j] * scale);
        }
      }
    }
  }
  output[target] = result;
}

__global__ void LayerBMixedPoseSegmentMergeKernel(
    const DevicePoseMeta* metadata,
    const DeviceAssemblyTargetRange* ranges,
    const float* hessian_partials,
    const double* frozen_jacobi_scaling,
    const float min_lm_diagonal,
    const float max_lm_diagonal,
    MixedPoseBlockOutput* output,
    const size_t count) {
  const size_t target = blockIdx.x;
  if (target >= count) return;
  const DevicePoseMeta pose = metadata[target];
  const DeviceAssemblyTargetRange range = ranges[target];
  const uint32_t scalar = threadIdx.x;
  if (scalar == 0) {
    output[target].image_id = pose.image_id;
    output[target].dimension = pose.dimension;
    for (uint32_t i = 0; i < 3; ++i) {
      output[target].free_translation_indices[i] =
          pose.free_translation_indices[i];
    }
  }
  if (scalar >= 36) return;
  const uint32_t i = scalar / 6;
  const uint32_t j = scalar % 6;
  if (i >= pose.dimension || j >= pose.dimension) return;
  float sum = 0.0f;
  for (uint32_t segment = range.segment_begin;
       segment < range.segment_end; ++segment) {
    sum += hessian_partials[segment * 36 + scalar];
  }
  output[target].hessian[i * pose.dimension + j] = sum;
  if (i == j) {
    const float diagonal = fmaxf(0.0f, sum);
    const float scale = frozen_jacobi_scaling == nullptr
                            ? 1.0f / (1.0f + sqrtf(diagonal))
                            : static_cast<float>(
                                  frozen_jacobi_scaling[target * 6 + i]);
    const float scaled_diagonal = sum * scale * scale;
    const float clamped = fminf(fmaxf(scaled_diagonal, min_lm_diagonal),
                                max_lm_diagonal);
    output[target].jacobi_scaling[i] = scale;
    output[target].damping[i] = clamped / (scale * scale);
  }
}

__global__ void LayerBMixedPointSegmentMergeKernel(
    const DevicePointMeta* metadata,
    const DeviceAssemblyTargetRange* ranges,
    const MixedPointAssemblyPartial* partials,
    const double* frozen_jacobi_scaling,
    const float min_lm_diagonal,
    const float max_lm_diagonal,
    MixedPointBlockOutput* output,
    const size_t count) {
  const size_t target = blockIdx.x;
  if (target >= count) return;
  const DeviceAssemblyTargetRange range = ranges[target];
  if (range.segment_begin == range.segment_end) return;
  const uint32_t scalar = threadIdx.x;
  if (scalar == 0) output[target].point3D_id = metadata[target].point3D_id;
  if (scalar < 9) {
    float sum = 0.0f;
    for (uint32_t segment = range.segment_begin;
         segment < range.segment_end; ++segment) {
      sum += partials[segment].hessian[scalar];
    }
    output[target].hessian[scalar] = sum;
    const uint32_t i = scalar / 3;
    const uint32_t j = scalar % 3;
    if (i == j) {
      const float diagonal = fmaxf(0.0f, sum);
      const float scale = frozen_jacobi_scaling == nullptr
                              ? 1.0f / (1.0f + sqrtf(diagonal))
                              : static_cast<float>(
                                    frozen_jacobi_scaling[target * 3 + i]);
      const float scaled_diagonal = sum * scale * scale;
      const float clamped = fminf(fmaxf(scaled_diagonal, min_lm_diagonal),
                                  max_lm_diagonal);
      output[target].jacobi_scaling[i] = scale;
      output[target].damping[i] = clamped / (scale * scale);
    }
  }
}

__global__ void ConvertMixedPoseBlocksKernel(
