  const MixedPoseBlockOutput value = input[target];
  if (scalar == 0) {
    output[target].image_id = value.image_id;
    output[target].dimension = value.dimension;
    for (uint32_t i = 0; i < 3; ++i) {
      output[target].free_translation_indices[i] =
          value.free_translation_indices[i];
