  }
  if (scalar < 36) output[target].hessian[scalar] = value.hessian[scalar];
  if (scalar < 6) {
    output[target].gradient[scalar] = value.gradient[scalar];
    output[target].jacobi_scaling[scalar] = value.jacobi_scaling[scalar];
    output[target].damping[scalar] = value.damping[scalar];
