__global__ void PublishPoseJacobiScalingKernel(
    const CudaPoseBlockOutput* poses,
    double* frozen,
    size_t count) {
  const size_t index = blockIdx.x * blockDim.x + threadIdx.x;
  if (index >= count * 6) return;
