}

__device__ inline void QuaternionPlusCeres14Device(const double* quaternion,
                                                   const double* delta,
                                                   double* result) {
  const double squared_norm = delta[0] * delta[0] + delta[1] * delta[1] +
                              delta[2] * delta[2];
  const double norm = sqrt(squared_norm);
  if (norm == 0.0) {
    for (size_t i = 0; i < 4; ++i) result[i] = quaternion[i];
    return;
  }
  const double sin_norm_by_norm = sin(norm) / norm;
  const double dw = cos(norm);
  const double dx = sin_norm_by_norm * delta[0];
  const double dy = sin_norm_by_norm * delta[1];
  const double dz = sin_norm_by_norm * delta[2];
  const double w = quaternion[0];
  const double x = quaternion[1];
  const double y = quaternion[2];
  const double z = quaternion[3];
  result[0] = dw * w - dx * x - dy * y - dz * z;
  result[1] = dw * x + dx * w + dy * z - dz * y;
  result[2] = dw * y - dx * z + dy * w + dz * x;
  result[3] = dw * z + dx * y - dy * x + dz * w;
}

__global__ void UpdateImageEntityStateKernel(
    const DeviceImageEntityState* current,
    const DeviceImageUpdateMeta* metadata,
    const double* pose_delta,
    DeviceImageEntityState* trial,
    uint32_t* status,
    size_t count) {
  const size_t index = blockIdx.x * blockDim.x + threadIdx.x;
  if (index >= count) return;
  const DeviceImageEntityState source = current[index];
  const DeviceImageUpdateMeta meta = metadata[index];
  DeviceImageEntityState output = source;
  if (meta.variable_pose_index >= 0) {
    if (meta.dimension < 3 || meta.dimension > 6) {
      atomicOr(status, 1u);
    } else {
      QuaternionPlusCeres14Device(source.quaternion,
                                  pose_delta + meta.delta_offset,
                                  output.quaternion);
      for (uint32_t component = 3; component < meta.dimension; ++component) {
        const int32_t translation =
            meta.free_translation_indices[component - 3];
        if (translation < 0 || translation >= 3) {
          atomicOr(status, 2u);
        } else {
          output.translation[translation] +=
              pose_delta[meta.delta_offset + component];
        }
      }
    }
  }
  bool finite = true;
  for (size_t i = 0; i < 4; ++i)
    finite = finite && DeviceFinite(output.quaternion[i]);
  for (size_t i = 0; i < 3; ++i)
    finite = finite && DeviceFinite(output.translation[i]);
  if (!finite) atomicOr(status, 4u);
  trial[index] = output;
}

__global__ void UpdatePointEntityStateKernel(
    const DevicePointEntityState* current,
    const DevicePointUpdateMeta* metadata,
    const double* point_delta,
    DevicePointEntityState* trial,
    uint32_t* status,
    size_t count) {
  const size_t index = blockIdx.x * blockDim.x + threadIdx.x;
  if (index >= count) return;
  const DevicePointEntityState source = current[index];
  const DevicePointUpdateMeta meta = metadata[index];
  DevicePointEntityState output = source;
  if (meta.variable_point_index >= 0) {
    const size_t offset = static_cast<size_t>(meta.variable_point_index) * 3;
    for (size_t i = 0; i < 3; ++i)
      output.xyz[i] += point_delta[offset + i];
  }
  bool finite = true;
  for (size_t i = 0; i < 3; ++i)
    finite = finite && DeviceFinite(output.xyz[i]);
  if (!finite) atomicOr(status, 8u);
  trial[index] = output;
}

__global__ void InjectStateUpdateStatusForTestingKernel(
    uint32_t* status, const uint32_t injected_status) {
  if (blockIdx.x == 0 && threadIdx.x == 0)
    atomicOr(status, injected_status);
}

__global__ void GatherVariablePoseStateKernel(
    const DeviceImageEntityState* images,
    const uint32_t* image_entity_indices,
    DevicePoseState* output,
    size_t count) {
  const size_t index = blockIdx.x * blockDim.x + threadIdx.x;
  if (index >= count) return;
  const DeviceImageEntityState image = images[image_entity_indices[index]];
  for (size_t i = 0; i < 4; ++i) output[index].quaternion[i] = image.quaternion[i];
}

__global__ void QuaternionPlusTestKernel(const double* quaternion,
                                         const double* delta,
                                         double* output,
                                         uint32_t* status) {
  if (blockIdx.x != 0 || threadIdx.x != 0) return;
  QuaternionPlusCeres14Device(quaternion, delta, output);
  bool finite = true;
  for (size_t i = 0; i < 4; ++i)
    finite = finite && DeviceFinite(output[i]);
  *status = finite ? 0u : 1u;
}

__global__ void LayerBGradientNormKernel(
    const DevicePoseMeta* pose_metadata,
    const DevicePoseState* pose_state,
    const CudaPoseBlockOutput* poses,
    size_t pose_count,
    const CudaPointBlockOutput* points,
    size_t point_count,
    double* output) {
  if (blockIdx.x != 0 || threadIdx.x != 0) return;
  double projected = 0.0;
  double raw_tangent = 0.0;
  double scaled = 0.0;
  for (size_t pose_index = 0; pose_index < pose_count; ++pose_index) {
    const DevicePoseMeta meta = pose_metadata[pose_index];
    const DevicePoseState state = pose_state[pose_index];
    const CudaPoseBlockOutput pose = poses[pose_index];
    double negative_gradient[3] = {-pose.gradient[0], -pose.gradient[1],
                                   -pose.gradient[2]};
    double plus[4];
    QuaternionPlusCeres14Device(state.quaternion, negative_gradient, plus);
    for (size_t i = 0; i < 4; ++i) {
      projected = fmax(projected, fabs(state.quaternion[i] - plus[i]));
    }
    for (uint32_t i = 0; i < pose.dimension; ++i) {
      raw_tangent = fmax(raw_tangent, fabs(pose.gradient[i]));
      scaled = fmax(scaled, fabs(pose.gradient[i]) /
                                fmax(sqrt(fmax(pose.hessian[
                                                  i * pose.dimension + i],
                                              1e-12)),
                                     1e-12));
      if (i >= 3) projected = fmax(projected, fabs(pose.gradient[i]));
    }
  }
  for (size_t point_index = 0; point_index < point_count; ++point_index) {
    const CudaPointBlockOutput point = points[point_index];
    for (size_t i = 0; i < 3; ++i) {
      projected = fmax(projected, fabs(point.gradient[i]));
      raw_tangent = fmax(raw_tangent, fabs(point.gradient[i]));
      scaled = fmax(scaled, fabs(point.gradient[i]) /
                                fmax(sqrt(fmax(point.hessian[i * 3 + i],
                                              1e-12)),
                                     1e-12));
    }
  }
  output[0] = projected;
  output[1] = raw_tangent;
  output[2] = scaled;
}

__global__ void LayerBGradientNormPartialKernel(
    const DevicePoseMeta* pose_metadata,
    const DevicePoseState* pose_state,
    const CudaPoseBlockOutput* poses,
    size_t pose_count,
    const CudaPointBlockOutput* points,
    size_t point_count,
    double* partials) {
  const size_t index = blockIdx.x * blockDim.x + threadIdx.x;
  const size_t count = pose_count + point_count;
  if (index >= count) return;
  double projected = 0.0;
  double raw_tangent = 0.0;
  double scaled = 0.0;
  if (index < pose_count) {
    const DevicePoseMeta meta = pose_metadata[index];
    const DevicePoseState state = pose_state[index];
    const CudaPoseBlockOutput pose = poses[index];
    const double negative_gradient[3] = {-pose.gradient[0],
                                         -pose.gradient[1],
                                         -pose.gradient[2]};
    double plus[4];
    QuaternionPlusCeres14Device(state.quaternion, negative_gradient, plus);
    for (size_t i = 0; i < 4; ++i)
      projected = fmax(projected, fabs(state.quaternion[i] - plus[i]));
    for (uint32_t i = 0; i < pose.dimension; ++i) {
      raw_tangent = fmax(raw_tangent, fabs(pose.gradient[i]));
      scaled = fmax(scaled, fabs(pose.gradient[i]) /
                                  fmax(sqrt(fmax(pose.hessian[
                                                     i * pose.dimension + i],
                                                 1e-12)),
                                           1e-12));
      if (i >= 3) projected = fmax(projected, fabs(pose.gradient[i]));
    }
  } else {
    const CudaPointBlockOutput point = points[index - pose_count];
    for (size_t i = 0; i < 3; ++i) {
      projected = fmax(projected, fabs(point.gradient[i]));
      raw_tangent = fmax(raw_tangent, fabs(point.gradient[i]));
      scaled = fmax(scaled, fabs(point.gradient[i]) /
                                  fmax(sqrt(fmax(point.hessian[i * 3 + i],
                                                 1e-12)),
                                           1e-12));
    }
  }
  partials[index * 3 + 0] = projected;
  partials[index * 3 + 1] = raw_tangent;
  partials[index * 3 + 2] = scaled;
}

__global__ void LayerBGradientNormReduceKernel(const double* partials,
                                                size_t count,
                                                double* output) {
  if (blockIdx.x != 0 || threadIdx.x != 0) return;
  double projected = 0.0;
  double raw_tangent = 0.0;
  double scaled = 0.0;
  for (size_t index = 0; index < count; ++index) {
    projected = fmax(projected, partials[index * 3 + 0]);
    raw_tangent = fmax(raw_tangent, partials[index * 3 + 1]);
    scaled = fmax(scaled, partials[index * 3 + 2]);
  }
  output[0] = projected;
  output[1] = raw_tangent;
  output[2] = scaled;
}

struct DeviceGradientMaxReduction {
  double projected;
  double raw_tangent;
  double scaled;
};

constexpr int kLayerBGradientReductionThreads = 128;
constexpr int kLayerBGradientReductionItemsPerThread = 4;
constexpr size_t kLayerBGradientReductionItemsPerBlock =
    kLayerBGradientReductionThreads * kLayerBGradientReductionItemsPerThread;

inline size_t LayerBGradientReductionBlockCount(const size_t count) {
  return (count + kLayerBGradientReductionItemsPerBlock - 1) /
      kLayerBGradientReductionItemsPerBlock;
}

__device__ inline DeviceGradientMaxReduction CombineGradientMax(
    const DeviceGradientMaxReduction& lhs,
    const DeviceGradientMaxReduction& rhs) {
  return {fmax(lhs.projected, rhs.projected),
          fmax(lhs.raw_tangent, rhs.raw_tangent),
          fmax(lhs.scaled, rhs.scaled)};
}

__global__ void LayerBGradientMaxLeafKernel(
    const double* input,
    size_t count,
    DeviceGradientMaxReduction* output) {
  __shared__ DeviceGradientMaxReduction
      shared[kLayerBGradientReductionThreads];
  const size_t begin = blockIdx.x * kLayerBGradientReductionItemsPerBlock +
      threadIdx.x * kLayerBGradientReductionItemsPerThread;
  DeviceGradientMaxReduction local{0.0, 0.0, 0.0};
  for (int item = 0; item < kLayerBGradientReductionItemsPerThread; ++item) {
    const size_t index = begin + static_cast<size_t>(item);
    if (index < count) {
      local = CombineGradientMax(
          local, {input[index * 3], input[index * 3 + 1],
                  input[index * 3 + 2]});
    }
  }
  shared[threadIdx.x] = local;
  __syncthreads();
  for (int stride = kLayerBGradientReductionThreads / 2; stride > 0;
       stride /= 2) {
    if (threadIdx.x < stride) {
      shared[threadIdx.x] = CombineGradientMax(
          shared[threadIdx.x], shared[threadIdx.x + stride]);
    }
    __syncthreads();
  }
  if (threadIdx.x == 0) output[blockIdx.x] = shared[0];
}

__global__ void LayerBGradientMaxMergeKernel(
    const DeviceGradientMaxReduction* input,
    size_t count,
    DeviceGradientMaxReduction* output) {
  __shared__ DeviceGradientMaxReduction
      shared[kLayerBGradientReductionThreads];
  const size_t begin = blockIdx.x * kLayerBGradientReductionItemsPerBlock +
      threadIdx.x * kLayerBGradientReductionItemsPerThread;
  DeviceGradientMaxReduction local{0.0, 0.0, 0.0};
  for (int item = 0; item < kLayerBGradientReductionItemsPerThread; ++item) {
    const size_t index = begin + static_cast<size_t>(item);
    if (index < count) local = CombineGradientMax(local, input[index]);
  }
  shared[threadIdx.x] = local;
  __syncthreads();
  for (int stride = kLayerBGradientReductionThreads / 2; stride > 0;
       stride /= 2) {
    if (threadIdx.x < stride) {
      shared[threadIdx.x] = CombineGradientMax(
          shared[threadIdx.x], shared[threadIdx.x + stride]);
    }
    __syncthreads();
  }
  if (threadIdx.x == 0) output[blockIdx.x] = shared[0];
}

__global__ void LayerBGradientMaxFinalizeKernel(
    const DeviceGradientMaxReduction* input,
    size_t count,
    double* output) {
  if (blockIdx.x != 0 || threadIdx.x != 0) return;
  const DeviceGradientMaxReduction value =
      count == 0 ? DeviceGradientMaxReduction{0.0, 0.0, 0.0} : input[0];
  output[0] = value.projected;
  output[1] = value.raw_tangent;
  output[2] = value.scaled;
}

void LaunchLayerBGradientMaxReduction(
    const double* input,
    size_t count,
    DeviceGradientMaxReduction* buffer_a,
    DeviceGradientMaxReduction* buffer_b,
    double* output,
    cudaStream_t stream) {
  size_t current_count = LayerBGradientReductionBlockCount(count);
  LayerBGradientMaxLeafKernel<<<current_count,
                                kLayerBGradientReductionThreads, 0, stream>>>(
      input, count, buffer_a);
  DeviceGradientMaxReduction* current = buffer_a;
  DeviceGradientMaxReduction* next = buffer_b;
  while (current_count > 1) {
    const size_t next_count = LayerBGradientReductionBlockCount(current_count);
    LayerBGradientMaxMergeKernel<<<next_count,
                                   kLayerBGradientReductionThreads, 0,
                                   stream>>>(current, current_count, next);
    std::swap(current, next);
    current_count = next_count;
  }
  LayerBGradientMaxFinalizeKernel<<<1, 1, 0, stream>>>(
      current, current_count, output);
}

