enum class PersistentSlotKind : uint8_t {
  kLayerAWorking = 0,
  kLayerATrial = 1,
  kLinearizationCurrent = 2,
  kLinearizationPending = 3,
  kLinearizationTemporary = 4,
  kStateCurrent = 5,
  kStateTrial = 6,
};

