  kOptimized = 1,
  kTransformed = 2,
};

const char* HessianAssemblyBackendName(
    const CudaHessianAssemblyBackend backend) {
  switch (backend) {
    case CudaHessianAssemblyBackend::kCompatibilityDefault:
      return "compatibility_default";
    case CudaHessianAssemblyBackend::kPoseOwnedScalarCompatibility:
      return "pose_owned_scalar";
    case CudaHessianAssemblyBackend::kPoseOwnedOptimizedReference:
      return "pose_owned";
    case CudaHessianAssemblyBackend::kObservationAtomic:
      return "observation_atomic";
    case CudaHessianAssemblyBackend::kObservationSegmented:
      return "observation_segmented";
  }
  return "invalid";
}

bool ResolveHessianAssemblyBackend(
    const CudaHessianAssemblyBackend typed_backend,
    const HotKernelImplementation hot_kernel,
    CudaHessianAssemblyBackend* backend,
    std::string* requested,
    std::string* error) {
  if (backend == nullptr || requested == nullptr || error == nullptr)
    return false;
  if (typed_backend != CudaHessianAssemblyBackend::kCompatibilityDefault) {
    if (typed_backend !=
            CudaHessianAssemblyBackend::kPoseOwnedScalarCompatibility &&
        typed_backend !=
            CudaHessianAssemblyBackend::kPoseOwnedOptimizedReference &&
        typed_backend != CudaHessianAssemblyBackend::kObservationAtomic &&
        typed_backend != CudaHessianAssemblyBackend::kObservationSegmented) {
      *error = "typed Hessian assembly backend is invalid";
      return false;
    }
    *backend = typed_backend;
    *requested = HessianAssemblyBackendName(typed_backend);
    return true;
  }
  const char* environment =
      std::getenv("COLMAP_PCD_GPU_BA_HESSIAN_ASSEMBLY_BACKEND");
  if (environment != nullptr && environment[0] != '\0') {
    const std::string value(environment);
    if (value == "pose_owned_scalar") {
      *backend = CudaHessianAssemblyBackend::kPoseOwnedScalarCompatibility;
    } else if (value == "pose_owned") {
      *backend = CudaHessianAssemblyBackend::kPoseOwnedOptimizedReference;
    } else if (value == "observation_atomic") {
      *backend = CudaHessianAssemblyBackend::kObservationAtomic;
    } else if (value == "observation_segmented") {
      *backend = CudaHessianAssemblyBackend::kObservationSegmented;
    } else {
      *error = "COLMAP_PCD_GPU_BA_HESSIAN_ASSEMBLY_BACKEND must be "
               "pose_owned_scalar, pose_owned, observation_atomic, or "
               "observation_segmented";
      return false;
    }
    *requested = value;
    return true;
  }
  *requested = "compatibility_default";
  *backend = hot_kernel == HotKernelImplementation::kReference
      ? CudaHessianAssemblyBackend::kPoseOwnedScalarCompatibility
      : CudaHessianAssemblyBackend::kPoseOwnedOptimizedReference;
  return true;
}

const char* ArithmeticPrecisionName(const CudaArithmeticPrecision precision) {
  switch (precision) {
    case CudaArithmeticPrecision::kCompatibilityDefault:
      return "compatibility_default";
    case CudaArithmeticPrecision::kFp64:
      return "fp64";
    case CudaArithmeticPrecision::kFp32Core:
      return "fp32_core";
    case CudaArithmeticPrecision::kFp32StateQuantizedMixed:
      return "fp32_state_quantized";
    case CudaArithmeticPrecision::kPureFp32Experimental:
      return "pure_fp32";
    case CudaArithmeticPrecision::kFp32MixedStable:
      return "fp32_mixed";
  }
  return "invalid";
}

const char* AuditProfileName(const CudaAuditProfile profile) {
  switch (profile) {
    case CudaAuditProfile::kCompatibilityDefault:
      return "compatibility_default";
    case CudaAuditProfile::kProduction:
      return "production";
    case CudaAuditProfile::kCorrectness:
      return "correctness";
    case CudaAuditProfile::kForensic:
      return "forensic";
  }
  return "invalid";
}

bool ResolveAuditProfile(const CudaFullLmOptions& options,
                         CudaAuditProfile* effective,
                         bool* capture_state_trace,
                         bool* instrumentation_enabled,
                         bool* audit_mirror_enabled,
                         std::string* error) {
  if (effective == nullptr || capture_state_trace == nullptr ||
      instrumentation_enabled == nullptr || audit_mirror_enabled == nullptr ||
      error == nullptr) {
    return false;
  }
  const bool has_fault_injection =
      options.fault_injection != CudaFaultInjection::kNone ||
      options.fault_trigger.fault_kind != CudaFaultInjection::kNone;
  switch (options.audit_profile) {
    case CudaAuditProfile::kCompatibilityDefault:
      *capture_state_trace = options.capture_state_trace;
      *instrumentation_enabled =
          options.instrumentation_mode == CudaInstrumentationMode::kEnabled;
      *audit_mirror_enabled =
          *capture_state_trace || *instrumentation_enabled || has_fault_injection;
      *effective = *audit_mirror_enabled ? CudaAuditProfile::kForensic
                                         : CudaAuditProfile::kCorrectness;
      return true;
    case CudaAuditProfile::kProduction:
    case CudaAuditProfile::kCorrectness:
      if (has_fault_injection) {
        *error = "fault injection requires the forensic CUDA audit profile";
        return false;
      }
      *capture_state_trace = false;
      *instrumentation_enabled = false;
      *audit_mirror_enabled = false;
      *effective = options.audit_profile;
      return true;
    case CudaAuditProfile::kForensic:
      *capture_state_trace = true;
      *instrumentation_enabled = true;
      *audit_mirror_enabled = true;
      *effective = CudaAuditProfile::kForensic;
      return true;
  }
  *error = "typed CUDA audit profile is invalid";
  return false;
}

bool ResolveArithmeticPrecision(
    const CudaArithmeticPrecision requested,
    CudaArithmeticPrecision* effective,
    std::string* error) {
  if (effective == nullptr || error == nullptr) return false;
  switch (requested) {
    case CudaArithmeticPrecision::kCompatibilityDefault:
    case CudaArithmeticPrecision::kFp64:
      *effective = CudaArithmeticPrecision::kFp64;
      return true;
    case CudaArithmeticPrecision::kFp32Core:
    case CudaArithmeticPrecision::kFp32StateQuantizedMixed:
    case CudaArithmeticPrecision::kFp32MixedStable:
      *effective = requested;
      return true;
    case CudaArithmeticPrecision::kPureFp32Experimental:
      *error = "pure FP32 arithmetic is not implemented";
      return false;
  }
  *error = "typed arithmetic precision is invalid";
  return false;
}

bool ResolveHotKernelImplementation(const CudaHotKernelMode typed_mode,
                                    const bool device_control,
                                    const bool explicit_standalone_selector,
                                    HotKernelImplementation* implementation,
                                    std::string* error) {
  if (implementation == nullptr || error == nullptr) return false;
  if (typed_mode != CudaHotKernelMode::kCompatibilityDefault) {
    switch (typed_mode) {
      case CudaHotKernelMode::kReference:
        *implementation = HotKernelImplementation::kReference;
        return true;
      case CudaHotKernelMode::kOptimized:
        *implementation = HotKernelImplementation::kOptimized;
        return true;
      case CudaHotKernelMode::kTransformed:
        *implementation = HotKernelImplementation::kTransformed;
        return true;
      case CudaHotKernelMode::kCompatibilityDefault:
        break;
    }
  }
  const char* value =
      std::getenv("COLMAP_PCD_GPU_BA_HOT_KERNEL_IMPLEMENTATION");
  if (!device_control && !explicit_standalone_selector) {
    *implementation = HotKernelImplementation::kReference;
    return true;
  }
  if (value == nullptr || value[0] == '\0') {
    *implementation = explicit_standalone_selector
                          ? HotKernelImplementation::kReference
                          : HotKernelImplementation::kOptimized;
    return true;
  }
  const std::string selected(value);
  if (selected == "reference") {
    *implementation = HotKernelImplementation::kReference;
    return true;
  }
  if (selected == "optimized") {
    *implementation = HotKernelImplementation::kOptimized;
    return true;
  }
  if (selected == "transformed") {
    *implementation = HotKernelImplementation::kTransformed;
    return true;
  }
  *error = "COLMAP_PCD_GPU_BA_HOT_KERNEL_IMPLEMENTATION must be reference, optimized, or transformed";
  return false;
}

const char* SchurContributionBackendName(
    const CudaSchurContributionBackend backend) {
  switch (backend) {
    case CudaSchurContributionBackend::kCompatibilityDefault:
      return "compatibility_default";
    case CudaSchurContributionBackend::kDirectTransformed:
      return "direct";
    case CudaSchurContributionBackend::kSegmentedTransformed:
      return "segmented";
  }
  return "invalid";
}

bool ResolveSchurContributionBackend(
    const CudaSchurContributionBackend typed_backend,
    CudaSchurContributionBackend* backend,
    std::string* requested,
    std::string* error) {
  if (backend == nullptr || requested == nullptr || error == nullptr)
    return false;
  if (typed_backend !=
      CudaSchurContributionBackend::kCompatibilityDefault) {
    if (typed_backend != CudaSchurContributionBackend::kDirectTransformed &&
        typed_backend !=
            CudaSchurContributionBackend::kSegmentedTransformed) {
      *error = "typed Schur contribution backend is invalid";
      return false;
    }
    *backend = typed_backend;
    *requested = SchurContributionBackendName(typed_backend);
    return true;
  }
  const char* environment =
      std::getenv("COLMAP_PCD_GPU_BA_SCHUR_CONTRIBUTION_BACKEND");
  if (environment == nullptr || environment[0] == '\0') {
    *backend = CudaSchurContributionBackend::kDirectTransformed;
    *requested = "compatibility_default";
    return true;
  }
  const std::string value(environment);
  if (value == "direct") {
    *backend = CudaSchurContributionBackend::kDirectTransformed;
    *requested = value;
    return true;
  }
  if (value == "segmented") {
    *backend = CudaSchurContributionBackend::kSegmentedTransformed;
    *requested = value;
    return true;
  }
  *error = "COLMAP_PCD_GPU_BA_SCHUR_CONTRIBUTION_BACKEND must be direct or segmented";
  return false;
}

