bool LaunchLayerCSegmentedSchurPairChunks(
    const LayerCTopology& topology,
    const int device,
    const DevicePairMeta* pair_meta,
    const uint32_t* direct_pair_indices,
    const DeviceSchurSegment* segments,
    const DeviceSchurPairSegmentRange* pair_segment_ranges,
    const DevicePairContribution* pair_contributions,
    const DeviceSolvePoseMeta* pose_meta,
    const CudaEdgeBlockOutput* edges,
    const double* transformed_edges,
    double* partials,
    double* schur,
    const size_t pose_dimension,
    cudaStream_t stream,
    CudaLayerCRuntimeInfo* layer_runtime,
    CudaPersistentDeviceRuntimeInfo* persistent_runtime,
    std::string* error,
    const SchurSegmentProfileEvents* profile_events = nullptr) {
  if (layer_runtime == nullptr || error == nullptr) return false;
  ++layer_runtime->schur_contribution_calls;
  if (persistent_runtime != nullptr)
    ++persistent_runtime->schur_contribution_calls;
  if (topology.pairs.empty()) return true;
  if (topology.segment_chunks.size() != topology.pair_chunks.size() ||
      pair_meta == nullptr || pair_contributions == nullptr ||
      pose_meta == nullptr || edges == nullptr || transformed_edges == nullptr ||
      schur == nullptr || topology.segment_size == 0 ||
      topology.segment_pair_ranges.size() != topology.pairs.size() ||
      (!topology.segment_direct_pair_indices.empty() &&
       direct_pair_indices == nullptr) ||
      (!topology.segments.empty() &&
       (segments == nullptr || pair_segment_ranges == nullptr ||
        partials == nullptr))) {
    ++layer_runtime->coverage_violations;
    if (persistent_runtime != nullptr)
      ++persistent_runtime->schur_contribution_coverage_violations;
    *error = "segmented Schur contribution launch layout is invalid";
    return false;
  }
  cudaDeviceProp properties;
  const cudaError_t property_status = cudaGetDeviceProperties(&properties, device);
  if (property_status != cudaSuccess || properties.maxGridSize[0] <= 0) {
    *error = "segmented Schur CUDA grid limit query failed";
    return false;
  }
  for (const LayerCSegmentChunk& chunk : topology.segment_chunks) {
    ++layer_runtime->pair_contribution_chunk_launches;
    if (persistent_runtime != nullptr)
      ++persistent_runtime->schur_pair_contribution_chunk_launches;
    const uint64_t direct_count =
        chunk.direct_index_end - chunk.direct_index_begin;
    const uint64_t segment_count = chunk.segment_end - chunk.segment_begin;
    const uint64_t pair_count = chunk.pair_end - chunk.pair_begin;
    if (direct_count > static_cast<uint64_t>(properties.maxGridSize[0]) ||
        segment_count > static_cast<uint64_t>(properties.maxGridSize[0]) ||
        pair_count > static_cast<uint64_t>(properties.maxGridSize[0])) {
      *error = "segmented Schur grid width exceeds CUDA device limit";
      return false;
    }
    if (profile_events != nullptr &&
        cudaEventRecord(profile_events->short_direct_begin, stream) !=
            cudaSuccess) {
      *error = "segmented Schur direct profile event record failed";
      return false;
    }
    if (direct_count != 0) {
      LayerCSchurPairTransformedIndexedKernel<<<
          static_cast<uint32_t>(direct_count),
          kSchurPairTransformedThreads, 0, stream>>>(
          pair_meta, direct_pair_indices + chunk.direct_index_begin,
          pair_contributions, pose_meta, edges, transformed_edges, schur,
          pose_dimension, direct_count);
      ++layer_runtime->layer_c_pair_chunk_launch_calls;
      if (persistent_runtime != nullptr)
        ++persistent_runtime->layer_c_pair_chunk_launch_calls;
    }
    if (profile_events != nullptr &&
        cudaEventRecord(profile_events->short_direct_end, stream) !=
            cudaSuccess) {
      *error = "segmented Schur direct profile event record failed";
      return false;
    }
    if (segment_count != 0) {
      if (profile_events != nullptr &&
          cudaEventRecord(profile_events->partial_begin, stream) !=
              cudaSuccess) {
        *error = "segmented Schur partial profile event record failed";
        return false;
      }
      LayerCSchurSegmentPartialKernel<<<
          static_cast<uint32_t>(segment_count),
          kSchurPairTransformedThreads, 0, stream>>>(
          pair_meta, segments, pair_contributions, pose_meta, edges,
          transformed_edges, partials, chunk.segment_begin, segment_count);
      if (profile_events != nullptr &&
          cudaEventRecord(profile_events->partial_end, stream) !=
              cudaSuccess) {
        *error = "segmented Schur partial profile event record failed";
        return false;
      }
      if (profile_events != nullptr &&
          cudaEventRecord(profile_events->merge_begin, stream) !=
              cudaSuccess) {
        *error = "segmented Schur merge profile event record failed";
        return false;
      }
      LayerCSchurSegmentMergeKernel<<<
          static_cast<uint32_t>(pair_count),
          kSchurPairTransformedThreads, 0, stream>>>(
          pair_meta, pair_segment_ranges, pose_meta, partials, schur,
          pose_dimension, chunk.pair_begin, pair_count);
      if (profile_events != nullptr &&
          cudaEventRecord(profile_events->merge_end, stream) != cudaSuccess) {
        *error = "segmented Schur merge profile event record failed";
        return false;
      }
      ++layer_runtime->partial_kernel_launches;
      ++layer_runtime->merge_kernel_launches;
      if (persistent_runtime != nullptr) {
        ++persistent_runtime->schur_partial_kernel_launches;
        ++persistent_runtime->schur_merge_kernel_launches;
      }
    }
    const cudaError_t launch_status = cudaPeekAtLastError();
    layer_runtime->cuda_launch_status = static_cast<int>(launch_status);
    if (launch_status != cudaSuccess) {
      *error = std::string("segmented Schur contribution launch failed: ") +
               CudaErrorText(launch_status);
      return false;
    }
  }
  layer_runtime->direct_pair_count =
      topology.segment_direct_pair_indices.size();
  layer_runtime->segmented_pair_count = topology.pairs.size() -
      topology.segment_direct_pair_indices.size();
  layer_runtime->segment_count = topology.segments.size();
  layer_runtime->max_segments_per_pair = topology.max_segments_per_pair;
  layer_runtime->segment_size = topology.segment_size;
  layer_runtime->partial_workspace_bytes =
      topology.segment_partial_workspace_bytes;
  layer_runtime->layer_c_max_chunks_per_step = std::max<uint64_t>(
      layer_runtime->layer_c_max_chunks_per_step,
      topology.segment_chunks.size());
  layer_runtime->layer_c_max_chunk_bytes = std::max(
      layer_runtime->layer_c_max_chunk_bytes, topology.pair_chunk_max_bytes);
  if (persistent_runtime != nullptr) {
    persistent_runtime->direct_pair_count = layer_runtime->direct_pair_count;
    persistent_runtime->segmented_pair_count =
        layer_runtime->segmented_pair_count;
    persistent_runtime->segment_count = layer_runtime->segment_count;
    persistent_runtime->max_segments_per_pair =
        layer_runtime->max_segments_per_pair;
    persistent_runtime->schur_segment_size = layer_runtime->segment_size;
    persistent_runtime->schur_partial_workspace_bytes =
        layer_runtime->partial_workspace_bytes;
    persistent_runtime->layer_c_max_chunks_per_step = std::max<uint64_t>(
        persistent_runtime->layer_c_max_chunks_per_step,
        topology.segment_chunks.size());
    persistent_runtime->layer_c_max_chunk_bytes = std::max(
        persistent_runtime->layer_c_max_chunk_bytes,
        topology.pair_chunk_max_bytes);
  }
  return true;
}

bool LaunchLayerCMixedNativeSchurPairChunks(
    const LayerCTopology& topology,
    const int device,
    const DevicePairMeta* pair_meta,
    const uint32_t* direct_pair_indices,
    const DeviceSchurSegment* segments,
    const DeviceSchurPairSegmentRange* pair_segment_ranges,
    const DevicePairContribution* pair_contributions,
    const DeviceSolvePoseMeta* pose_meta,
    const MixedEdgeBlockOutput* edges,
    const float* transformed_edges,
    float* partials,
    double* schur,
    const size_t pose_dimension,
    cudaStream_t stream,
    CudaLayerCRuntimeInfo* layer_runtime,
    CudaPersistentDeviceRuntimeInfo* persistent_runtime,
    std::string* error) {
  if (layer_runtime == nullptr || persistent_runtime == nullptr ||
      error == nullptr) return false;
  ++layer_runtime->schur_contribution_calls;
  ++persistent_runtime->schur_contribution_calls;
  ++persistent_runtime->mixed_native_fp32_schur_calls;
  ++persistent_runtime->mixed_fp64_schur_contribution_calls;
  if (topology.pairs.empty()) return topology.segment_chunks.empty();
  if (topology.segment_chunks.size() != topology.pair_chunks.size() ||
      pair_meta == nullptr || pair_contributions == nullptr ||
      pose_meta == nullptr || edges == nullptr || transformed_edges == nullptr ||
      schur == nullptr || topology.segment_size == 0 ||
      topology.segment_pair_ranges.size() != topology.pairs.size() ||
      (!topology.segment_direct_pair_indices.empty() &&
       direct_pair_indices == nullptr) ||
      (!topology.segments.empty() &&
       (segments == nullptr || pair_segment_ranges == nullptr ||
        partials == nullptr))) {
    ++layer_runtime->coverage_violations;
    ++persistent_runtime->schur_contribution_coverage_violations;
    *error = "native FP32 segmented Schur launch layout is invalid";
    return false;
  }
  cudaDeviceProp properties;
  const cudaError_t property_status = cudaGetDeviceProperties(&properties, device);
  if (property_status != cudaSuccess || properties.maxGridSize[0] <= 0) {
    *error = "native FP32 segmented Schur CUDA grid limit query failed";
    return false;
  }
  for (const LayerCSegmentChunk& chunk : topology.segment_chunks) {
    const uint64_t direct_count =
        chunk.direct_index_end - chunk.direct_index_begin;
    const uint64_t segment_count = chunk.segment_end - chunk.segment_begin;
    const uint64_t pair_count = chunk.pair_end - chunk.pair_begin;
    if (direct_count > static_cast<uint64_t>(properties.maxGridSize[0]) ||
        segment_count > static_cast<uint64_t>(properties.maxGridSize[0]) ||
        pair_count > static_cast<uint64_t>(properties.maxGridSize[0])) {
      *error = "native FP32 segmented Schur grid width exceeds CUDA device limit";
      return false;
    }
    ++layer_runtime->pair_contribution_chunk_launches;
    ++persistent_runtime->schur_pair_contribution_chunk_launches;
    if (direct_count != 0) {
      MixedFloatSchurPairIndexedToDoubleKernel<<<
          static_cast<uint32_t>(direct_count),
          kSchurPairTransformedThreads, 0, stream>>>(
          pair_meta, direct_pair_indices + chunk.direct_index_begin,
          pair_contributions, pose_meta, edges, transformed_edges, schur,
          pose_dimension, direct_count);
      ++layer_runtime->layer_c_pair_chunk_launch_calls;
      ++persistent_runtime->layer_c_pair_chunk_launch_calls;
    }
    if (segment_count != 0) {
      MixedFloatSchurSegmentPartialKernel<<<
          static_cast<uint32_t>(segment_count),
          kSchurPairTransformedThreads, 0, stream>>>(
          pair_meta, segments, pair_contributions, pose_meta, edges,
          transformed_edges, partials, chunk.segment_begin, segment_count);
      MixedFloatSchurSegmentMergeToDoubleKernel<<<
          static_cast<uint32_t>(pair_count),
          kSchurPairTransformedThreads, 0, stream>>>(
          pair_meta, pair_segment_ranges, pose_meta, partials, schur,
          pose_dimension, chunk.pair_begin, pair_count);
      ++layer_runtime->partial_kernel_launches;
      ++layer_runtime->merge_kernel_launches;
      ++persistent_runtime->schur_partial_kernel_launches;
      ++persistent_runtime->schur_merge_kernel_launches;
      ++persistent_runtime->mixed_native_fp32_schur_partial_calls;
    }
    const cudaError_t launch_status = cudaPeekAtLastError();
    layer_runtime->cuda_launch_status = static_cast<int>(launch_status);
    if (launch_status != cudaSuccess) {
      *error = std::string("native FP32 segmented Schur launch failed: ") +
               CudaErrorText(launch_status);
      return false;
    }
  }
  layer_runtime->direct_pair_count =
      topology.segment_direct_pair_indices.size();
  layer_runtime->segmented_pair_count =
      topology.pairs.size() - topology.segment_direct_pair_indices.size();
  layer_runtime->segment_count = topology.segments.size();
  layer_runtime->max_segments_per_pair = topology.max_segments_per_pair;
  layer_runtime->segment_size = topology.segment_size;
  layer_runtime->partial_workspace_bytes =
      topology.segments.size() * kSchurSegmentStoredScalars * sizeof(float);
  persistent_runtime->direct_pair_count = layer_runtime->direct_pair_count;
  persistent_runtime->segmented_pair_count = layer_runtime->segmented_pair_count;
  persistent_runtime->segment_count = layer_runtime->segment_count;
  persistent_runtime->max_segments_per_pair =
      layer_runtime->max_segments_per_pair;
  persistent_runtime->schur_segment_size = layer_runtime->segment_size;
  persistent_runtime->schur_partial_workspace_bytes =
      layer_runtime->partial_workspace_bytes;
  return true;
}

bool LaunchLayerCSchurPairChunks(
    const LayerCTopology& topology,
    const HotKernelImplementation implementation,
    const int device,
    const DevicePairMeta* pair_meta,
    const DevicePairContribution* pair_contributions,
    const DeviceSolvePoseMeta* pose_meta,
    const CudaEdgeBlockOutput* edges,
    const double* point_inverse,
    const double* transformed_edges,
    double* schur,
    const size_t pose_dimension,
    cudaStream_t stream,
    CudaLayerCRuntimeInfo* layer_runtime,
    CudaPersistentDeviceRuntimeInfo* persistent_runtime,
    std::string* error) {
  if (layer_runtime == nullptr || error == nullptr) return false;
  ++layer_runtime->schur_contribution_calls;
  if (persistent_runtime != nullptr)
    ++persistent_runtime->schur_contribution_calls;
  if (topology.pairs.empty()) {
    if (!topology.pair_chunks.empty()) {
      *error = "Layer C empty pair topology has non-empty chunk layout";
      return false;
    }
    return true;
  }
  if (topology.pair_chunks.empty() || pair_meta == nullptr ||
      pair_contributions == nullptr || pose_meta == nullptr || edges == nullptr ||
      schur == nullptr ||
      topology.pair_chunk_algorithm_version !=
          kLayerCPairChunkAlgorithmVersion) {
    *error = "Layer C pair chunk launch layout is invalid";
    return false;
  }
  cudaDeviceProp properties;
  const cudaError_t property_status = cudaGetDeviceProperties(&properties, device);
  if (property_status != cudaSuccess || properties.maxGridSize[0] <= 0) {
    layer_runtime->cuda_launch_status = static_cast<int>(property_status);
    *error = std::string("Layer C CUDA grid limit query failed: ") +
             CudaErrorText(property_status);
    return false;
  }

  uint64_t expected_pair = 0;
  uint64_t expected_contribution = 0;
  for (const LayerCPairChunk& chunk : topology.pair_chunks) {
    ++layer_runtime->pair_contribution_chunk_launches;
    if (persistent_runtime != nullptr)
      ++persistent_runtime->schur_pair_contribution_chunk_launches;
    if (chunk.pair_begin != expected_pair ||
        chunk.contribution_begin != expected_contribution ||
        chunk.pair_end <= chunk.pair_begin ||
        chunk.pair_end > topology.pairs.size() ||
        chunk.contribution_end < chunk.contribution_begin ||
        chunk.contribution_end > topology.pair_contributions.size() ||
        chunk.pair_begin > std::numeric_limits<size_t>::max() ||
        chunk.pair_end > std::numeric_limits<size_t>::max()) {
      *error = "Layer C pair chunk launch coverage is invalid";
      return false;
    }
    uint64_t chunk_bytes = 0;
    if (!CheckedMultiply(chunk.contribution_end - chunk.contribution_begin,
                         sizeof(DevicePairContribution), &chunk_bytes) ||
        chunk_bytes > topology.pair_chunk_limit_bytes ||
        topology.pairs[static_cast<size_t>(chunk.pair_begin)].adjacency_begin !=
            chunk.contribution_begin ||
        topology.pairs[static_cast<size_t>(chunk.pair_end - 1)].adjacency_end !=
            chunk.contribution_end) {
      *error = "Layer C pair chunk launch boundary is invalid";
      return false;
    }
    const uint64_t grid_width = chunk.pair_end - chunk.pair_begin;
    if (grid_width > static_cast<uint64_t>(properties.maxGridSize[0]) ||
        grid_width > std::numeric_limits<uint32_t>::max()) {
      *error = "Layer C pair chunk grid width exceeds CUDA device limit";
      return false;
    }
    const size_t pair_begin = static_cast<size_t>(chunk.pair_begin);
    const size_t pair_count = static_cast<size_t>(grid_width);
    if (implementation == HotKernelImplementation::kTransformed) {
      if (transformed_edges == nullptr) {
        *error = "Layer C transformed pair launch has no transformed edges";
        return false;
      }
      LayerCSchurPairTransformedKernel<<<
          static_cast<uint32_t>(grid_width), kSchurPairTransformedThreads, 0,
          stream>>>(pair_meta + pair_begin, pair_contributions, pose_meta, edges,
                    transformed_edges, schur, pose_dimension, pair_count);
    } else if (implementation == HotKernelImplementation::kOptimized) {
      LayerCSchurPairOptimizedKernel<<<
          static_cast<uint32_t>(grid_width), kSchurPairOptimizedThreads, 0,
          stream>>>(pair_meta + pair_begin, pair_contributions, pose_meta, edges,
                    point_inverse, schur, pose_dimension, pair_count);
    } else {
      LayerCSchurPairKernel<<<static_cast<uint32_t>(grid_width), 36, 0, stream>>>(
          pair_meta + pair_begin, pair_contributions, pose_meta, edges,
          point_inverse, schur, pose_dimension, pair_count);
    }
    ++layer_runtime->layer_c_pair_chunk_launch_calls;
    layer_runtime->layer_c_max_chunk_bytes =
        std::max(layer_runtime->layer_c_max_chunk_bytes, chunk_bytes);
    if (persistent_runtime != nullptr) {
      ++persistent_runtime->layer_c_pair_chunk_launch_calls;
      persistent_runtime->layer_c_max_chunk_bytes =
          std::max(persistent_runtime->layer_c_max_chunk_bytes, chunk_bytes);
    }
    const cudaError_t launch_status = cudaPeekAtLastError();
    layer_runtime->cuda_launch_status = static_cast<int>(launch_status);
    if (launch_status != cudaSuccess) {
      *error = std::string("Layer C pair chunk launch failed: ") +
               CudaErrorText(launch_status);
      return false;
    }
    expected_pair = chunk.pair_end;
    expected_contribution = chunk.contribution_end;
  }
  if (expected_pair != topology.pairs.size() ||
      expected_contribution != topology.pair_contributions.size()) {
    *error = "Layer C pair chunk launch did not cover the topology";
    return false;
  }
  layer_runtime->layer_c_max_chunks_per_step = std::max<uint64_t>(
      layer_runtime->layer_c_max_chunks_per_step, topology.pair_chunks.size());
  if (persistent_runtime != nullptr) {
    persistent_runtime->layer_c_max_chunks_per_step = std::max<uint64_t>(
        persistent_runtime->layer_c_max_chunks_per_step,
        topology.pair_chunks.size());
  }
  return true;
}

struct DeviceCommitToken {
  DeviceCommitToken() = default;
  DeviceCommitToken(const DeviceCommitToken&) = delete;
  DeviceCommitToken& operator=(const DeviceCommitToken&) = delete;
  DeviceCommitToken(DeviceCommitToken&&) noexcept = default;
  DeviceCommitToken& operator=(DeviceCommitToken&&) noexcept = default;
  bool valid = false;
  uint64_t context_identity = 0;
  CudaArithmeticPrecision arithmetic_precision =
      CudaArithmeticPrecision::kFp64;
  CudaLinearizationIdentity identity;
  size_t pending_b_slot = 0;
  uint64_t pending_b_generation = 0;
  size_t trial_state_slot = 0;
  uint64_t trial_state_generation = 0;
};

struct PersistentSlotIdentity {
  CudaLinearizationIdentity linearization;
  uint64_t context_identity = 0;
  uint64_t layout_id = 0;
  uint64_t slot_generation = 0;
  CudaArithmeticPrecision arithmetic_precision =
      CudaArithmeticPrecision::kFp64;
  PersistentSlotKind kind = PersistentSlotKind::kLayerAWorking;
  bool valid = false;
};

struct DeviceLayerAView {
  const void* visual = nullptr;
  bool compact_visual = false;
  const CudaLidarOutput* lidar = nullptr;
  const MixedVisualOutput* mixed_visual = nullptr;
  const MixedLidarOutput* mixed_lidar = nullptr;
  size_t visual_count = 0;
  size_t lidar_count = 0;
  PersistentSlotIdentity identity;
  PersistentSlotIdentity source_state_identity;
};

struct DeviceLayerBView {
  const CudaPoseBlockOutput* poses = nullptr;
  const CudaPointBlockOutput* points = nullptr;
  const CudaEdgeBlockOutput* edges = nullptr;
  const MixedPoseBlockOutput* mixed_poses = nullptr;
  const MixedPointBlockOutput* mixed_points = nullptr;
  const MixedEdgeBlockOutput* mixed_edges = nullptr;
  size_t pose_count = 0;
  size_t point_count = 0;
  size_t edge_count = 0;
