  PersistentSlotIdentity identity;
};

// Device-buffer liveness for the persistent full-solve backend:
//
// Buffer group                 Class       First write        Last consumer
// visual/lidar binding         static      Initialize         final Layer A
// camera/entity update maps    static      Initialize         final update/A
// cost/B/C topology            static      Initialize         final B/C/cost
// dynamic A state              legacy      each packing       that Layer A
// current/trial entity state   slot        init/update         A / next trial
// A working/trial output       slot        Layer A            B+cost / cost
// B current/pending output     slot        Layer B            repeated C
// frozen Jacobi scaling        static      bootstrap finalize final Layer B
// transformed edge scratch     workspace   point factor       same C pair
// C matrices/workspace         workspace   each Layer C       same Layer C
//
// Device-state A reads the complete entity slot and immutable camera buffer.
// A outputs are not retained after both direct device consumers finish.
// Current/trial state and current/pending B slots are independent; accepted
// commit swaps their host indices only and performs no CUDA operation or copy.
class GpuBaDeviceContext {
 public:
  GpuBaDeviceContext() = default;
  GpuBaDeviceContext(const GpuBaDeviceContext&) = delete;
  GpuBaDeviceContext& operator=(const GpuBaDeviceContext&) = delete;
  GpuBaDeviceContext(GpuBaDeviceContext&&) = delete;
  GpuBaDeviceContext& operator=(GpuBaDeviceContext&&) = delete;
  ~GpuBaDeviceContext() noexcept { Close(nullptr); }

  bool Initialize(const Snapshot& initial_snapshot,
                  const PackedLayerAState& initial,
                  const CostLayout& cost_layout,
                  const LayerBTopology& layer_b,
                  const LayerCTopology& layer_c,
                  const CudaLayerBOptions& options,
                  uint64_t solve_generation,
                  uint64_t topology_generation,
                  bool device_state_enabled,
                  bool device_control_enabled,
                  HotKernelImplementation hot_kernel_implementation,
                  CudaHessianAssemblyBackend hessian_assembly_backend,
                  CudaSchurContributionBackend schur_contribution_backend,
                  CudaArithmeticPrecision arithmetic_precision,
                  CudaExecutionProfile execution_profile,
                  bool audit_mirror_enabled,
                  const MapperStaticCatalogStableTables* indexed_catalog,
                  CudaFullLmRuntimeInfo* runtime,
                  std::string* error);
  bool InitializeNative(const NativeHostSolveView& view,
                        const ActiveStateBuffer& initial_state,
                        const LegacyKernelInputBundle::Impl& native,
                        const CudaLayerBOptions& options,
                        uint64_t solve_generation,
                        uint64_t topology_generation,
                        HotKernelImplementation hot_kernel_implementation,
                        CudaHessianAssemblyBackend hessian_assembly_backend,
                        CudaSchurContributionBackend schur_contribution_backend,
                        CudaArithmeticPrecision arithmetic_precision,
                        CudaExecutionProfile execution_profile,
                        CudaFullLmRuntimeInfo* runtime,
                        std::string* error);
  bool FinalizeConfig(uint64_t config_generation, std::string* error) noexcept;
  bool UploadFrozenScaling(const CudaLayerBOptions& options,
                           std::string* error);
  bool PublishFrozenScalingFromInitial(
      const CudaDeviceLinearizationToken& token,
      const CudaLinearizationIdentity& identity,
      std::string* error);
  bool RunLayerB(const PackedLayerAState& packed,
                 const CudaLayerBOptions& options,
                 const CudaLinearizationIdentity& identity,
                 CudaFaultLogicalSite site,
                 CudaLossMode loss_mode,
                 double loss_scale,
                 CudaLayerBResult* result,
                 CudaDeviceLinearizationToken* token,
                 std::string* error);
  bool RunLayerBFromDeviceState(
      const Snapshot& host_state,
      const CudaLayerBOptions& options,
      const CudaLinearizationIdentity& identity,
      CudaFaultLogicalSite site,
      CudaLossMode loss_mode,
      double loss_scale,
      CudaLayerBResult* result,
      CudaDeviceLinearizationToken* token,
      std::string* error);
  bool RunLayerBFromNativeDeviceState(
      const CudaLayerBOptions& options,
      const CudaLinearizationIdentity& identity,
      CudaFaultLogicalSite site,
      CudaLossMode loss_mode,
      double loss_scale,
      CudaLayerBResult* result,
      CudaDeviceLinearizationToken* token,
      std::string* error);
  bool RunLayerCLinearSolve(const LayerBTopology& layer_b_topology,
                            const LayerCTopology& layer_c_topology,
                            const CudaLayerCOptions& options,
                            const CudaLinearizationIdentity& identity,
                            const CudaDeviceLinearizationToken& token,
                            const CudaLayerBResult& layer_b,
                            CudaLayerCStepResult* result,
                            std::string* error);
  bool RunTrialCost(const PackedLayerAState& trial_packed,
                    const CudaLayerBOptions& options,
                    const CudaLinearizationIdentity& identity,
                    CudaLossMode loss_mode,
                    double loss_scale,
                    double* trial_cost,
                    double* kernel_milliseconds,
                    std::string* error);
  bool BuildDeviceTrialState(const Snapshot& host_current,
                             const CudaLinearizationIdentity& current_identity,
