bool SameNativeIdentity(const NativeHostSolveViewIdentity& lhs,
                        const NativeHostSolveViewIdentity& rhs) noexcept {
  return lhs.abi_version == rhs.abi_version &&
         lhs.catalog_abi_version == rhs.catalog_abi_version &&
         lhs.owner_epoch == rhs.owner_epoch &&
         lhs.catalog_revision == rhs.catalog_revision &&
         lhs.catalog_generation == rhs.catalog_generation &&
         lhs.selection_revision == rhs.selection_revision &&
         lhs.config_generation == rhs.config_generation &&
         lhs.lidar_map_generation == rhs.lidar_map_generation &&
         lhs.lidar_match_config_generation ==
             rhs.lidar_match_config_generation;
}

template <typename State>
uint32_t NativeStateSlot(const State& state);
template <>
uint32_t NativeStateSlot(const DenseCameraState& state) {
  return state.camera_slot;
}
template <>
uint32_t NativeStateSlot(const DenseImageState& state) {
  return state.image_slot;
}
template <>
uint32_t NativeStateSlot(const DensePointState& state) {
  return state.point_slot;
}

template <typename State>
bool BuildNativeStateLookup(const std::vector<State>& states,
                            const uint64_t generation,
                            std::unordered_map<uint32_t, const State*>* lookup,
                            std::string* error) {
  lookup->clear();
  lookup->reserve(states.size());
  for (const State& state : states) {
    if (state.state_generation != generation ||
        !lookup->emplace(NativeStateSlot(state), &state).second) {
      *error = "native state generation or slot identity is invalid";
      return false;
    }
  }
  return true;
}

template <typename T>
bool NativeFinite(const T& values) {
  for (const double value : values)
    if (!std::isfinite(value)) return false;
  return true;
}

const ImageFixedPolicyResult* NativeImagePolicy(
    const NativeHostSolveView& view, const uint32_t slot) {
  for (const ImageFixedPolicyResult& value : view.fixed.images)
    if (value.image_slot == slot) return &value;
  return nullptr;
}
const PointFixedPolicyResult* NativePointPolicy(
    const NativeHostSolveView& view, const uint32_t slot) {
  for (const PointFixedPolicyResult& value : view.fixed.points)
    if (value.point_slot == slot) return &value;
  return nullptr;
}
const LidarConstraintRecord* NativeLidarConstraint(
    const NativeHostSolveView& view, const uint32_t slot) {
  for (const LidarConstraintRecord& value : view.lidar.constraints)
    if (value.constraint_slot == slot) return &value;
  return nullptr;
}

bool NativeBundleIdentityReady(const NativeHostSolveView& view,
                               const LegacyKernelInputBundle::Impl& bundle,
                               std::string* error) {
  if (!bundle.identity_valid || !SameNativeIdentity(bundle.identity,
                                                     view.identity)) {
    *error = "native kernel bundle identity mismatch";
    return false;
  }
  return true;
}

}  // namespace

bool BuildCudaLayerAInputs(const NativeHostSolveView& view,
                           const ActiveStateBuffer& state,
                           LegacyKernelInputBundle* output,
                           std::string* error) {
  if (output == nullptr || output->impl_ == nullptr || error == nullptr)
    return false;
  if (!ValidateNativeHostSolveView(view, state, error)) return false;
  LegacyKernelInputBundle::Impl& bundle = *output->impl_;
  bundle = LegacyKernelInputBundle::Impl();
  std::unordered_map<uint32_t, const DenseCameraState*> cameras;
  std::unordered_map<uint32_t, const DenseImageState*> images;
  std::unordered_map<uint32_t, const DensePointState*> points;
  if (!BuildNativeStateLookup(state.cameras, state.state_generation, &cameras,
                              error) ||
      !BuildNativeStateLookup(state.images, state.state_generation, &images,
                              error) ||
      !BuildNativeStateLookup(state.points, state.state_generation, &points,
                              error)) {
    return false;
  }
  const auto graph_cameras = view.catalog.cameras();
  const auto graph_images = view.catalog.images();
  const auto graph_points = view.catalog.points();
  const auto graph_observations = view.catalog.observations();
  const uint32_t invalid = std::numeric_limits<uint32_t>::max();
  bundle.visual_output_by_execution_ordinal.assign(
      view.residual_ordinals.size(), invalid);
  bundle.lidar_output_by_execution_ordinal.assign(
      view.residual_ordinals.size(), invalid);
  bundle.packed.visual.reserve(view.visual_observation_slots.size());
  bundle.packed.lidar.reserve(view.lidar.constraints.size());
  for (const ResidualOrdinal& ordinal : view.residual_ordinals) {
    if (ordinal.execution_ordinal >= view.residual_ordinals.size()) {
      *error = "native residual execution ordinal is out of bounds";
      return false;
    }
    if (ordinal.kind == ResidualKind::kVisual) {
      if (ordinal.source_slot >= graph_observations.size) {
        *error = "native visual observation slot is out of bounds";
        return false;
      }
      const HostBaObservationSlot& observation =
          graph_observations[ordinal.source_slot];
      if (!observation.header.alive ||
          ordinal.physical_identity != observation.source_identity ||
          observation.image_slot >= graph_images.size ||
          observation.point_slot >= graph_points.size ||
          observation.camera_slot >= graph_cameras.size) {
        *error = "native visual references a dead graph slot";
        return false;
      }
      const auto image = images.find(observation.image_slot);
      const auto point = points.find(observation.point_slot);
      const auto camera = cameras.find(observation.camera_slot);
      if (image == images.end() || point == points.end() ||
          camera == cameras.end() ||
          graph_cameras[observation.camera_slot].model_id !=
              kOpenCvcCameraModelId ||
          camera->second->parameters.size() != 8 ||
          !NativeFinite(camera->second->parameters)) {
        *error = "native visual state or OPENCV camera layout is invalid";
        return false;
      }
      CudaVisualInput packed;
      packed.source_index = ordinal.source_insertion_index;
      packed.image_id = graph_images[observation.image_slot].image_id;
      packed.point3D_id = graph_points[observation.point_slot].point3D_id;
      std::copy(image->second->quaternion.begin(),
                image->second->quaternion.end(), packed.quaternion);
      std::copy(image->second->translation.begin(),
                image->second->translation.end(), packed.translation);
      std::copy(point->second->xyz.begin(), point->second->xyz.end(),
                packed.point);
      std::copy(camera->second->parameters.begin(),
                camera->second->parameters.end(), packed.camera);
      std::copy(observation.xy.begin(), observation.xy.end(),
                packed.observation);
      bundle.visual_output_by_execution_ordinal[ordinal.execution_ordinal] =
          static_cast<uint32_t>(bundle.packed.visual.size());
      bundle.packed.visual.push_back(packed);
    } else {
      const LidarConstraintRecord* constraint =
          NativeLidarConstraint(view, ordinal.source_slot);
      if (constraint == nullptr ||
          ordinal.physical_identity != constraint->physical_identity) {
        *error = "native LiDAR ordinal references a missing constraint";
        return false;
      }
      const auto point = points.find(constraint->point_slot);
      if (point == points.end() ||
          constraint->point_slot >= graph_points.size) {
        *error = "native LiDAR state is missing";
        return false;
      }
      CudaLidarInput packed;
      packed.source_index = ordinal.source_insertion_index;
      packed.point3D_id = graph_points[constraint->point_slot].point3D_id;
      std::copy(point->second->xyz.begin(), point->second->xyz.end(),
                packed.point);
      std::copy(constraint->plane.begin(), constraint->plane.end(),
                packed.plane);
      packed.weight = constraint->weight;
      packed.mode = static_cast<uint8_t>(view.config.lidar_residual_mode);
      packed.near_zero_threshold = view.config.lidar_near_zero_threshold;
      bundle.lidar_output_by_execution_ordinal[ordinal.execution_ordinal] =
          static_cast<uint32_t>(bundle.packed.lidar.size());
      bundle.packed.lidar.push_back(packed);
    }
  }
  ++bundle.runtime.build_cuda_layer_a_inputs_calls;
  bundle.runtime.temporary_visual_input_bytes =
      bundle.packed.visual.size() * sizeof(CudaVisualInput);
  bundle.runtime.temporary_lidar_input_bytes =
      bundle.packed.lidar.size() * sizeof(CudaLidarInput);
  bundle.identity = view.identity;
  bundle.identity_valid = true;
  bundle.layer_a_ready = true;
  return true;
}

bool BuildStaticLayout(const NativeHostSolveView& view,
                       const ActiveStateBuffer& state,
                       LegacyKernelInputBundle* output,
                       std::string* error) {
  if (output == nullptr || output->impl_ == nullptr || error == nullptr ||
      !ValidateNativeHostSolveView(view, state, error)) {
    return false;
  }
  LegacyKernelInputBundle::Impl& bundle = *output->impl_;
  if (!bundle.layer_a_ready || !NativeBundleIdentityReady(view, bundle, error))
    return false;
  bundle.camera_slots = view.active_camera_slots;
  bundle.image_slots = view.active_image_slots;
  bundle.image_slots.insert(bundle.image_slots.end(),
                            view.boundary_image_slots.begin(),
                            view.boundary_image_slots.end());
  bundle.point_slots = view.active_point_slots;
  const auto images = view.catalog.images();
  bundle.image_camera_slots.clear();
  bundle.image_camera_slots.reserve(bundle.image_slots.size());
  for (const uint32_t slot : bundle.image_slots) {
    if (slot >= images.size) {
      *error = "native image entity slot is out of bounds";
      return false;
    }
    bundle.image_camera_slots.push_back(images[slot].camera_slot);
  }
  ++bundle.runtime.build_static_layout_calls;
  bundle.static_layout_ready = true;
  return true;
}

bool BuildCostLayout(const NativeHostSolveView& view,
                     LegacyKernelInputBundle* output,
                     std::string* error) {
  if (output == nullptr || output->impl_ == nullptr || error == nullptr)
    return false;
  LegacyKernelInputBundle::Impl& bundle = *output->impl_;
  if (!bundle.layer_a_ready || !NativeBundleIdentityReady(view, bundle, error))
    return false;
  CostLayout cost;
  cost.residual_order = view.config.residual_order;
  cost.visual_count = bundle.packed.visual.size();
  cost.lidar_count = bundle.packed.lidar.size();
  cost.entries.reserve(view.residual_ordinals.size());
  uint64_t layout_id = 1469598103934665603ull;
  HashTag(&layout_id, 0x4e4154495645434full);
  HashWord(&layout_id, static_cast<uint64_t>(cost.residual_order));
  for (const ResidualOrdinal& ordinal : view.residual_ordinals) {
    DeviceCostEntry entry;
    entry.residual_kind = ordinal.kind == ResidualKind::kVisual ? 0 : 1;
    entry.output_index = ordinal.kind == ResidualKind::kVisual
        ? bundle.visual_output_by_execution_ordinal[ordinal.execution_ordinal]
        : bundle.lidar_output_by_execution_ordinal[ordinal.execution_ordinal];
    const size_t bound = entry.residual_kind == 0
        ? bundle.packed.visual.size() : bundle.packed.lidar.size();
    if (entry.output_index >= bound) {
      *error = "native CostLayout kind-local index is out of bounds";
      return false;
    }
    cost.entries.push_back(entry);
    HashWord(&layout_id, ordinal.source_insertion_index);
    HashWord(&layout_id, ordinal.physical_identity);
    HashWord(&layout_id, entry.residual_kind);
    HashWord(&layout_id, entry.output_index);
  }
  cost.layout_id = layout_id == 0 ? 1 : layout_id;
  bundle.cost_layout = std::move(cost);
  bundle.runtime.real_cost_layout_entries = bundle.cost_layout.entries.size();
  ++bundle.runtime.build_cost_layout_calls;
  bundle.cost_layout_ready = true;
  return true;
}

bool BuildLayerBTopology(const NativeHostSolveView& view,
                         LegacyKernelInputBundle* output,
                         std::string* error) {
  if (output == nullptr || output->impl_ == nullptr || error == nullptr)
    return false;
  LegacyKernelInputBundle::Impl& bundle = *output->impl_;
  if (!bundle.static_layout_ready || !bundle.cost_layout_ready ||
      !NativeBundleIdentityReady(view, bundle, error)) {
    return false;
  }
  const auto images = view.catalog.images();
  const auto points = view.catalog.points();
  std::vector<const ImageFixedPolicyResult*> variable_images;
  std::vector<const PointFixedPolicyResult*> variable_points;
  if (view.config.residual_order == CudaResidualOrder::kCanonical) {
    for (const ImageFixedPolicyResult& policy : view.fixed.images)
      if (!policy.pose_constant) variable_images.push_back(&policy);
    for (const PointFixedPolicyResult& policy : view.fixed.points)
      if (!policy.constant) variable_points.push_back(&policy);
    std::sort(variable_images.begin(), variable_images.end(),
              [&images](const auto* lhs, const auto* rhs) {
                return images[lhs->image_slot].image_id <
                       images[rhs->image_slot].image_id;
              });
    std::sort(variable_points.begin(), variable_points.end(),
              [&points](const auto* lhs, const auto* rhs) {
                return points[lhs->point_slot].point3D_id <
                       points[rhs->point_slot].point3D_id;
              });
  } else {
    std::unordered_set<uint32_t> seen_images;
    std::unordered_set<uint32_t> seen_points;
    for (const ParameterOrdinal& parameter : view.parameter_ordinals) {
      if (parameter.kind == ParameterKind::kQuaternion && !parameter.constant &&
          seen_images.insert(static_cast<uint32_t>(parameter.entity_slot)).second) {
        const auto* policy = NativeImagePolicy(
            view, static_cast<uint32_t>(parameter.entity_slot));
        if (policy != nullptr) variable_images.push_back(policy);
      } else if (parameter.kind == ParameterKind::kPoint3D &&
                 !parameter.constant &&
                 seen_points.insert(
                     static_cast<uint32_t>(parameter.entity_slot)).second) {
        const auto* policy = NativePointPolicy(
            view, static_cast<uint32_t>(parameter.entity_slot));
        if (policy != nullptr) variable_points.push_back(policy);
      }
    }
  }
  LayerBTopology topology;
  std::vector<int32_t> pose_by_image_slot(images.size, -1);
  std::vector<int32_t> point_by_point_slot(points.size, -1);
  topology.poses.resize(variable_images.size());
  std::vector<std::vector<uint32_t>> pose_entries(variable_images.size());
  for (size_t i = 0; i < variable_images.size(); ++i) {
    const auto& policy = *variable_images[i];
    DevicePoseMeta& meta = topology.poses[i];
    meta.image_id = images[policy.image_slot].image_id;
    meta.dimension = 3;
    for (int32_t& value : meta.free_translation_indices) value = -1;
    for (int translation = 0; translation < 3; ++translation) {
      if ((policy.translation_subset_mask & (1u << translation)) == 0) {
        meta.free_translation_indices[meta.dimension - 3] = translation;
        ++meta.dimension;
      }
    }
    pose_by_image_slot[policy.image_slot] = static_cast<int32_t>(i);
  }
  topology.points.resize(variable_points.size());
  std::vector<std::vector<DevicePointAdjacency>> point_entries(
      variable_points.size());
  for (size_t i = 0; i < variable_points.size(); ++i) {
    topology.points[i].point3D_id =
        points[variable_points[i]->point_slot].point3D_id;
    point_by_point_slot[variable_points[i]->point_slot] =
        static_cast<int32_t>(i);
  }
  const auto observations = view.catalog.observations();
  std::map<std::pair<uint32_t, uint32_t>, std::vector<uint32_t>> edge_entries;
  for (const ResidualOrdinal& ordinal : view.residual_ordinals) {
    if (ordinal.kind != ResidualKind::kVisual) continue;
    const HostBaObservationSlot& observation = observations[ordinal.source_slot];
    const int32_t pose = pose_by_image_slot[observation.image_slot];
    const int32_t point = point_by_point_slot[observation.point_slot];
    const uint32_t visual_index =
        bundle.visual_output_by_execution_ordinal[ordinal.execution_ordinal];
    if (pose >= 0) pose_entries[pose].push_back(visual_index);
    if (pose >= 0 && point >= 0) {
      edge_entries[{static_cast<uint32_t>(pose),
                    static_cast<uint32_t>(point)}].push_back(visual_index);
    }
  }
  for (const DeviceCostEntry& entry : bundle.cost_layout.entries) {
    uint64_t point_id = 0;
    if (entry.residual_kind == 0) {
      point_id = bundle.packed.visual[entry.output_index].point3D_id;
    } else {
      point_id = bundle.packed.lidar[entry.output_index].point3D_id;
    }
    const HostBaPointSlot* graph_point = view.catalog.FindPointById(point_id);
    if (graph_point == nullptr || graph_point->header.slot >=
                                      point_by_point_slot.size()) {
      *error = "native point adjacency references a missing point";
      return false;
    }
    const int32_t point = point_by_point_slot[graph_point->header.slot];
    if (point >= 0) {
      DevicePointAdjacency adjacency;
      adjacency.residual_kind = entry.residual_kind;
      adjacency.residual_index = entry.output_index;
      point_entries[point].push_back(adjacency);
    }
  }
  for (size_t i = 0; i < topology.poses.size(); ++i) {
    topology.poses[i].adjacency_begin = topology.pose_adjacency.size();
    topology.pose_adjacency.insert(topology.pose_adjacency.end(),
                                   pose_entries[i].begin(), pose_entries[i].end());
    topology.poses[i].adjacency_end = topology.pose_adjacency.size();
  }
  for (size_t i = 0; i < topology.points.size(); ++i) {
    topology.points[i].adjacency_begin = topology.point_adjacency.size();
    topology.point_adjacency.insert(topology.point_adjacency.end(),
                                    point_entries[i].begin(), point_entries[i].end());
    topology.points[i].adjacency_end = topology.point_adjacency.size();
  }
  for (const auto& item : edge_entries) {
    DeviceEdgeMeta edge;
    edge.pose_index = item.first.first;
    edge.point_index = item.first.second;
    edge.pose_dimension = topology.poses[edge.pose_index].dimension;
    edge.adjacency_begin = topology.edge_adjacency.size();
    topology.edge_adjacency.insert(topology.edge_adjacency.end(),
                                   item.second.begin(), item.second.end());
    edge.adjacency_end = topology.edge_adjacency.size();
    topology.edges.push_back(edge);
  }
  if (!BuildLayerBObservationExecutionPlan(
          bundle.packed.visual, bundle.packed.lidar,
          view.config.hessian_backend, view.config.hessian_segment_size,
          &topology, error)) {
    return false;
  }
  bundle.layer_b_topology = std::move(topology);
  bundle.runtime.real_pose_adjacency_entries =
      bundle.layer_b_topology.pose_adjacency.size();
  bundle.runtime.real_point_adjacency_entries =
      bundle.layer_b_topology.point_adjacency.size();
  bundle.runtime.real_edge_adjacency_entries =
      bundle.layer_b_topology.edge_adjacency.size();
  ++bundle.runtime.build_layer_b_topology_calls;
  bundle.layer_b_ready = true;
  return true;
}

bool BuildLayerCTopology(const NativeHostSolveView& view,
                         LegacyKernelInputBundle* output,
                         std::string* error) {
  if (output == nullptr || output->impl_ == nullptr || error == nullptr)
    return false;
  LegacyKernelInputBundle::Impl& bundle = *output->impl_;
  if (!bundle.layer_b_ready || !NativeBundleIdentityReady(view, bundle, error))
    return false;
  LayerCTopology topology;
  if (!BuildLayerCTopology(bundle.layer_b_topology,
                           view.config.pair_chunk_limit_bytes, &topology,
                           error) ||
      (view.config.schur_backend ==
           CudaSchurContributionBackend::kSegmentedTransformed &&
       !BuildLayerCSegmentPlan(view.config.schur_segment_size, &topology,
                               error))) {
    return false;
  }
  bundle.layer_c_topology = std::move(topology);
  bundle.runtime.real_schur_pair_contributions =
      bundle.layer_c_topology.pair_contributions.size();
  ++bundle.runtime.build_layer_c_topology_calls;
  bundle.layer_c_ready = true;
  return true;
}

bool BuildLegacyKernelInputBundle(const NativeHostSolveView& view,
                                  const ActiveStateBuffer& state,
                                  LegacyKernelInputBundle* output,
                                  std::string* error) {
  if (output == nullptr || output->impl_ == nullptr || error == nullptr)
    return false;
  if (!BuildCudaLayerAInputs(view, state, output, error)) return false;
  ++output->impl_->runtime.legacy_kernel_input_bundle_calls;
  return BuildStaticLayout(view, state, output, error) &&
         BuildCostLayout(view, output, error) &&
         BuildLayerBTopology(view, output, error) &&
         BuildLayerCTopology(view, output, error);
}

bool CopyActiveStateForTesting(const NativeHostSolveView& view,
                               const ActiveStateBuffer& state,
                               DenseActiveState* output,
                               std::string* error) {
  if (output == nullptr || error == nullptr ||
      !ValidateNativeHostSolveView(view, state, error)) {
    return false;
  }
  output->owner_epoch = state.owner_epoch;
  output->state_generation = state.state_generation;
  output->cameras = state.cameras;
  output->images = state.images;
  output->points = state.points;
  return true;
}

namespace {

class GpuBaSolveContext {
 public:
  GpuBaSolveContext() = default;
  GpuBaSolveContext(const GpuBaSolveContext&) = delete;
  GpuBaSolveContext& operator=(const GpuBaSolveContext&) = delete;
  GpuBaSolveContext(GpuBaSolveContext&&) = delete;
  GpuBaSolveContext& operator=(GpuBaSolveContext&&) = delete;

  void SetArithmeticPrecisionForSolve(
      const CudaArithmeticPrecision precision) noexcept {
    arithmetic_precision_ = precision;
  }

  bool InitializeNative(
      const NativeHostSolveView& view,
      const ActiveStateBuffer& state,
      const LegacyKernelInputBundle::Impl& native,
      const CudaLayerBOptions& options,
      const uint64_t solve_generation,
      const HotKernelImplementation hot_kernel_implementation,
      CudaFullLmRuntimeInfo* runtime,
      std::string* error) {
    if (initialized_ || error == nullptr || runtime == nullptr ||
        !native.layer_a_ready || !native.static_layout_ready ||
        !native.cost_layout_ready || !native.layer_b_ready ||
        !native.layer_c_ready || !native.identity_valid ||
        !SameNativeIdentity(native.identity, view.identity) ||
        !ValidateNativeHostSolveView(view, state, error)) {
      if (error != nullptr && error->empty())
        *error = "native GpuBaSolveContext initialization is invalid";
      return false;
    }
    solve_generation_ = solve_generation == 0 ? 1 : solve_generation;
    backend_ = CudaDeviceContextBackend::kDeviceControl;
    execution_profile_ = view.config.execution_profile;
    audit_mirror_enabled_ = false;
    audit_runtime_ = runtime;
    residual_order_ = view.config.residual_order;
    loss_mode_ = view.config.loss_mode;
    loss_scale_ = loss_mode_ == CudaLossMode::kTrivial
        ? 1.0 : view.config.loss_scale;
    arithmetic_precision_ = view.config.arithmetic_precision;
    native_hessian_backend_ = view.config.hessian_backend;
    borrowed_native_ = &native;
    topology_generation_ = NextMathematicalGeneration();
    packed_state_.topology_generation = topology_generation_;
    packed_state_.config_generation = 0;
    packed_state_.layout_id = native.cost_layout.layout_id;
    device_context_.reset(new GpuBaDeviceContext());
    if (!device_context_->InitializeNative(
            view, state, native, options, solve_generation_,
            topology_generation_, hot_kernel_implementation,
            view.config.hessian_backend, view.config.schur_backend,
            view.config.arithmetic_precision, view.config.execution_profile,
            runtime, error)) {
      device_context_.reset();
      borrowed_native_ = nullptr;
      return false;
    }
    has_layer_c_topology_ = true;
    prepared_initial_available_ = true;
    initialized_ = true;
    return true;
  }

  bool SetIndexedCatalogForSolve(
      const MapperStaticCatalogStableTables* tables,
      const IndexedActiveSolveDescriptor* descriptor,
      const CudaArithmeticPrecision arithmetic_precision,
      const CudaHessianAssemblyBackend hessian_backend,
      const CudaSchurContributionBackend schur_backend,
      const CudaHotKernelMode hot_kernel,
      const CudaExecutionProfile execution_profile,
      const CudaLossMode loss_mode,
      const double loss_scale,
      std::string* error) noexcept {
    if ((tables == nullptr) != (descriptor == nullptr)) {
      if (error != nullptr)
        *error = "indexed catalog and active descriptor must be bound together";
      return false;
    }
    if (tables != nullptr) {
      IndexedActiveSolveConfig expected = descriptor->config;
      expected.effective_config_resolved = true;
      expected.arithmetic_precision = arithmetic_precision;
      expected.hessian_backend = hessian_backend;
      expected.schur_backend = schur_backend;
      expected.hot_kernel = hot_kernel;
      expected.execution_profile = execution_profile;
      expected.loss_mode = loss_mode;
      expected.loss_scale = loss_scale;
      if (arithmetic_precision != arithmetic_precision_ ||
          !ValidateIndexedCatalogSolveBinding(
              *tables, *descriptor, expected, error)) {
        if (error != nullptr && error->empty())
          *error = "indexed catalog arithmetic precision mismatch";
        return false;
      }
    }
    indexed_catalog_tables_ = tables;
    indexed_active_solve_ = descriptor;
    return true;
  }

  bool MoveHostPreparationTo(PreparedHostSolveViewData* output,
                             std::string* error) {
    if (output == nullptr || error == nullptr || !initialized_ ||
        device_context_ != nullptr || borrowed_prepared_host_ != nullptr) {
      if (error != nullptr)
        *error = "host preparation export requires a host-only initialized context";
      return false;
    }
    output->residual_order = residual_order_;
    output->loss_mode = loss_mode_;
    output->loss_scale = loss_scale_;
    output->execution_profile = execution_profile_;
    output->camera_layout = std::move(camera_layout_);
    output->camera_parameters = std::move(camera_parameters_);
    output->image_layout = std::move(image_layout_);
    output->point_layout = std::move(point_layout_);
    output->visual_layout = std::move(visual_layout_);
    output->lidar_layout = std::move(lidar_layout_);
    output->camera_indices = std::move(camera_indices_);
    output->image_indices = std::move(image_indices_);
    output->point_indices = std::move(point_indices_);
    output->observation_indices = std::move(observation_indices_);
    output->lidar_indices = std::move(lidar_indices_);
    output->visual_output_indices = std::move(visual_output_indices_);
    output->lidar_output_indices = std::move(lidar_output_indices_);
    output->packed_template = std::move(packed_state_);
    output->cost_layout = std::move(cost_layout_);
    output->layer_b_topology = std::move(layer_b_topology_);
    output->layer_c_topology = has_layer_c_topology_
        ? std::make_shared<const LayerCTopology>(std::move(layer_c_topology_))
        : std::shared_ptr<const LayerCTopology>();
    initialized_ = false;
    prepared_initial_available_ = false;
    has_layer_c_topology_ = false;
    return true;
  }

  bool InitializeFromPreparedHostView(
      const Snapshot& snapshot,
      const CudaLayerBOptions& options,
      const uint64_t pair_chunk_limit_bytes,
      const uint64_t solve_generation,
      const CudaDeviceContextBackend backend,
      const HotKernelImplementation hot_kernel_implementation,
      const CudaSchurContributionBackend schur_contribution_backend,
      const uint32_t schur_segment_size,
      const CudaExecutionProfile execution_profile,
      const bool audit_mirror_enabled,
      CudaFullLmRuntimeInfo* audit_runtime,
      const PreparedHostSolveViewData& prepared,
      std::string* error) {
    if (initialized_ || error == nullptr) {
      if (error != nullptr)
        *error = "GpuBaSolveContext cannot be initialized more than once";
      return false;
    }
    solve_generation_ = solve_generation == 0 ? 1 : solve_generation;
    backend_ = backend;
    execution_profile_ = execution_profile;
    audit_mirror_enabled_ = audit_mirror_enabled;
    audit_runtime_ = audit_runtime;
    residual_order_ = options.layer_a.residual_order;
    if (!ResolveCudaLoss(snapshot, options, &loss_mode_, &loss_scale_, error))
      return false;
    CudaHessianAssemblyBackend hessian_assembly_backend =
        CudaHessianAssemblyBackend::kPoseOwnedScalarCompatibility;
    std::string hessian_assembly_requested;
    if (!ResolveHessianAssemblyBackend(
            options.hessian_assembly_backend, hot_kernel_implementation,
            &hessian_assembly_backend, &hessian_assembly_requested, error)) {
      return false;
    }
    if (prepared.layer_c_topology == nullptr ||
        prepared.residual_order != residual_order_ ||
        prepared.loss_mode != loss_mode_ || prepared.loss_scale != loss_scale_ ||
        prepared.hessian_backend != hessian_assembly_backend ||
        prepared.schur_backend != schur_contribution_backend ||
        prepared.execution_profile != execution_profile ||
        prepared.pair_chunk_limit_bytes != pair_chunk_limit_bytes ||
        prepared.hessian_segment_size !=
            options.hessian_segment_size_for_testing ||
        prepared.schur_segment_size != schur_segment_size ||
        prepared.arithmetic_precision != arithmetic_precision_) {
      *error = "prepared host solve view configuration identity mismatch";
      if (audit_runtime_ != nullptr)
        ++audit_runtime_->host_problem_store.owner_identity_violations;
      return false;
    }
    if (audit_runtime_ != nullptr) {
      audit_runtime_->persistent_device.hessian_assembly_backend_requested =
          hessian_assembly_requested;
      audit_runtime_->persistent_device.hessian_assembly_backend_effective =
          HessianAssemblyBackendName(hessian_assembly_backend);
      audit_runtime_->cross_solve_cache_hits = 0;
    }
    const auto borrow_start = std::chrono::steady_clock::now();
    borrowed_prepared_host_ = &prepared;
    packed_state_ = PackedLayerAState();
    has_layer_c_topology_ = true;
    topology_generation_ = NextMathematicalGeneration();
    packed_state_.topology_generation = topology_generation_;
    packed_state_.config_generation = 0;
    packed_state_.layout_id = CostLayoutRef().layout_id;
    const auto refresh_start = std::chrono::steady_clock::now();
    if (!PackDynamicState(snapshot, error)) return false;
    const double refresh_milliseconds =
        std::chrono::duration<double, std::milli>(
            std::chrono::steady_clock::now() - refresh_start).count();
    if (audit_runtime_ != nullptr) {
      ++audit_runtime_->host_problem_store.dynamic_state_refresh_calls;
      audit_runtime_->host_problem_store.dynamic_state_refresh_wall_milliseconds +=
          refresh_milliseconds;
      audit_runtime_->host_problem_store.host_preparation_total_wall_milliseconds +=
          std::chrono::duration<double, std::milli>(
              std::chrono::steady_clock::now() - borrow_start).count();
      ++audit_runtime_->topology_reuse_hits;
    }
    const bool fingerprint_requested = audit_mirror_enabled_ ||
        (audit_runtime_ != nullptr && audit_runtime_->instrumentation_effective);
    if (fingerprint_requested) {
      topology_fingerprint_ = TopologyFingerprint(
          CostLayoutRef(), LayerBTopologyRef(), LayerCTopologyRef());
      if (g_cuda_timing_sink != nullptr) {
        g_cuda_timing_sink->topology_fingerprint = topology_fingerprint_;
        g_cuda_timing_sink->topology_epoch = 1;
        g_cuda_timing_sink->topology_generation = topology_generation_;
        ++g_cuda_timing_sink->topology_fingerprint_computations;
      }
    }
    if (backend_ != CudaDeviceContextBackend::kLegacy) {
      device_context_.reset(new GpuBaDeviceContext());
      if (!device_context_->Initialize(
              snapshot, packed_state_, CostLayoutRef(), LayerBTopologyRef(),
              LayerCTopologyRef(), options, solve_generation_,
              topology_generation_,
              backend_ == CudaDeviceContextBackend::kDeviceState ||
                  backend_ == CudaDeviceContextBackend::kDeviceControl,
              backend_ == CudaDeviceContextBackend::kDeviceControl,
              hot_kernel_implementation, hessian_assembly_backend,
              schur_contribution_backend, arithmetic_precision_,
              execution_profile, audit_mirror_enabled_,
              indexed_catalog_tables_, audit_runtime_, error)) {
        device_context_.reset();
        return false;
      }
    }
    prepared_initial_available_ = true;
    initialized_ = true;
    return true;
  }

  bool Initialize(const Snapshot& snapshot,
                  const CudaLayerBOptions& options,
                  const uint64_t pair_chunk_limit_bytes,
                  const uint64_t solve_generation,
                  const bool require_layer_c,
                  const CudaDeviceContextBackend backend,
                  const HotKernelImplementation hot_kernel_implementation,
                  const CudaSchurContributionBackend
                      schur_contribution_backend,
                  const uint32_t schur_segment_size,
                  const CudaExecutionProfile execution_profile,
                  const bool audit_mirror_enabled,
                  CudaFullLmRuntimeInfo* audit_runtime,
                  std::string* error) {
    if (initialized_) {
      *error = "GpuBaSolveContext cannot be initialized more than once";
      return false;
    }
    solve_generation_ = solve_generation == 0 ? 1 : solve_generation;
    backend_ = backend;
    execution_profile_ = execution_profile;
    audit_mirror_enabled_ = audit_mirror_enabled;
    audit_runtime_ = audit_runtime;
    if (audit_runtime_ != nullptr) audit_runtime_->cross_solve_cache_hits = 0;
    residual_order_ = options.layer_a.residual_order;
    if (!ResolveCudaLoss(snapshot, options, &loss_mode_, &loss_scale_, error))
      return false;
    CudaHessianAssemblyBackend hessian_assembly_backend =
        CudaHessianAssemblyBackend::kPoseOwnedScalarCompatibility;
    std::string hessian_assembly_requested;
    if (!ResolveHessianAssemblyBackend(
            options.hessian_assembly_backend, hot_kernel_implementation,
            &hessian_assembly_backend, &hessian_assembly_requested, error)) {
      return false;
    }
    if (audit_runtime_ != nullptr) {
      audit_runtime_->persistent_device.hessian_assembly_backend_requested =
          hessian_assembly_requested;
      audit_runtime_->persistent_device.hessian_assembly_backend_effective =
          HessianAssemblyBackendName(hessian_assembly_backend);
    }
    const auto topology_preparation_start = std::chrono::steady_clock::now();

    // The initial dynamic pack is retained and consumed by the first Layer B.
    // It is the one compatibility-counted packing for that Layer A call.
    if (ProfileAtLeast(execution_profile_,
                       CudaExecutionProfile::kUnifiedBuilder) &&
        audit_runtime_ != nullptr) {
      ++audit_runtime_->persistent_device.unified_problem_builder_calls;
      // Entity/static residual, cost order, parameter order, B adjacency, and
      // C pair finalization remain distinct stable-order passes. The unified
      // builder shares their lookup tables and invokes them once per solve.
      audit_runtime_->persistent_device.unified_problem_builder_traversals =
          require_layer_c ? 6 : 5;
    }
    if (audit_runtime_ != nullptr)
      ++audit_runtime_->persistent_device.host_build_cuda_layer_a_inputs_calls;
    if (!BuildCudaLayerAInputs(snapshot, residual_order_,
                               &packed_state_.visual, &packed_state_.lidar,
                               error)) {
      return false;
    }
    if (audit_runtime_ != nullptr)
      ++audit_runtime_->persistent_device.host_build_static_layout_calls;
    if (!BuildStaticLayout(snapshot, error)) return false;
    if (audit_runtime_ != nullptr)
      ++audit_runtime_->persistent_device.host_build_cost_layout_calls;
    if (!BuildCostLayout(snapshot, residual_order_, packed_state_.visual,
                         packed_state_.lidar, visual_output_indices_,
                         lidar_output_indices_, &cost_layout_, error)) {
      return false;
    }
    if (audit_runtime_ != nullptr)
      ++audit_runtime_->persistent_device.host_build_layer_b_topology_calls;
    if (!BuildLayerBTopology(snapshot, packed_state_.visual,
                             packed_state_.lidar, cost_layout_, image_indices_,
                             point_indices_, &layer_b_topology_, error)) {
      return false;
    }
    if (hessian_assembly_backend ==
            CudaHessianAssemblyBackend::kObservationAtomic ||
        hessian_assembly_backend ==
            CudaHessianAssemblyBackend::kObservationSegmented) {
      const auto candidate_plan_start = std::chrono::steady_clock::now();
      if (!BuildLayerBObservationExecutionPlan(
              packed_state_.visual, packed_state_.lidar,
              hessian_assembly_backend,
              options.hessian_segment_size_for_testing,
              &layer_b_topology_, error)) {
        return false;
      }
      if (audit_runtime_ != nullptr) {
        ++audit_runtime_->persistent_device
              .hessian_candidate_metadata_build_calls;
        audit_runtime_->persistent_device
            .hessian_candidate_metadata_host_milliseconds +=
            std::chrono::duration<double, std::milli>(
                std::chrono::steady_clock::now() - candidate_plan_start)
                .count();
      }
    }
    if (g_cuda_timing_sink != nullptr) {
      ++g_cuda_timing_sink->cache_miss_count;
      RecordExplicitCall(CUDA_TIMING_PHASE(topology_lookup));
      ++g_cuda_timing_sink->cache_lookup_count;
    }
    if (require_layer_c) {
      if (audit_runtime_ != nullptr)
        ++audit_runtime_->persistent_device.host_build_layer_c_topology_calls;
      if (!BuildLayerCTopology(layer_b_topology_, pair_chunk_limit_bytes,
                               &layer_c_topology_, error))
        return false;
      if (schur_contribution_backend ==
          CudaSchurContributionBackend::kSegmentedTransformed) {
        const auto segment_plan_start = std::chrono::steady_clock::now();
        if (!BuildLayerCSegmentPlan(schur_segment_size, &layer_c_topology_,
                                    error)) {
          return false;
        }
        if (audit_runtime_ != nullptr) {
          audit_runtime_->persistent_device
              .schur_segment_plan_host_milliseconds +=
              std::chrono::duration<double, std::milli>(
                  std::chrono::steady_clock::now() - segment_plan_start)
                  .count();
        }
      }
      has_layer_c_topology_ = true;
      if (g_cuda_timing_sink != nullptr) ++g_cuda_timing_sink->cache_miss_count;
    }
    if (audit_runtime_ != nullptr) {
      audit_runtime_->persistent_device
          .problem_topology_preparation_wall_milliseconds +=
          std::chrono::duration<double, std::milli>(
              std::chrono::steady_clock::now() - topology_preparation_start)
              .count();
    }
    const bool fast_identity = ProfileAtLeast(
        execution_profile_, CudaExecutionProfile::kFastIdentity);
    topology_generation_ = fast_identity
        ? NextMathematicalGeneration()
        : ComputeTopologyGeneration(snapshot);
    if (!fast_identity && audit_runtime_ != nullptr) {
      ++audit_runtime_->persistent_device.production_identity_fingerprint_calls;
      audit_runtime_->persistent_device.production_identity_fingerprint_bytes =
          SaturatingAdd(
              audit_runtime_->persistent_device
                  .production_identity_fingerprint_bytes,
              snapshot.images.size() * sizeof(ImageSnapshot) +
                  snapshot.points.size() * sizeof(PointSnapshot) +
                  snapshot.source_insertion_order.size() *
                      sizeof(OrderEntrySnapshot));
    }
    cost_layout_.RebindIdentity(topology_generation_, 0);
    packed_state_.topology_generation = topology_generation_;
    packed_state_.config_generation = 0;
    packed_state_.layout_id = cost_layout_.layout_id;
    if (!PackPoseState(snapshot, error)) return false;
    const bool fingerprint_requested = !fast_identity ||
        audit_mirror_enabled_ ||
        (audit_runtime_ != nullptr &&
         audit_runtime_->instrumentation_effective);
    if (has_layer_c_topology_ && fingerprint_requested) {
      HostPhaseScope fingerprint_timing(
          CUDA_TIMING_PHASE(topology_fingerprint_audit));
      topology_fingerprint_ = TopologyFingerprint(
          cost_layout_, layer_b_topology_, layer_c_topology_);
      if (g_cuda_timing_sink != nullptr) {
        g_cuda_timing_sink->topology_fingerprint = topology_fingerprint_;
        g_cuda_timing_sink->topology_epoch = 1;
        g_cuda_timing_sink->topology_generation = topology_generation_;
        ++g_cuda_timing_sink->topology_fingerprint_computations;
      }
    }
    if (backend_ != CudaDeviceContextBackend::kLegacy) {
      device_context_.reset(new GpuBaDeviceContext());
      if (!device_context_->Initialize(
              snapshot, packed_state_, cost_layout_, layer_b_topology_,
              layer_c_topology_, options, solve_generation_,
              topology_generation_,
              backend_ == CudaDeviceContextBackend::kDeviceState ||
                  backend_ == CudaDeviceContextBackend::kDeviceControl,
              backend_ == CudaDeviceContextBackend::kDeviceControl,
              hot_kernel_implementation,
              hessian_assembly_backend,
              schur_contribution_backend,
              arithmetic_precision_,
              execution_profile,
              audit_mirror_enabled_,
              indexed_catalog_tables_,
              audit_runtime_, error)) {
        device_context_.reset();
        return false;
      }
    }
    prepared_initial_available_ = true;
    initialized_ = true;
    return true;
  }

  bool FinalizeResolvedConfig(const uint64_t config_generation,
                              std::string* error) {
    if (!initialized_ || config_generation == 0) {
      if (error != nullptr)
        *error = "GpuBaSolveContext final config identity is invalid";
      return false;
    }
    if (config_finalized_ && config_generation_ != config_generation) {
      if (error != nullptr)
        *error = "GpuBaSolveContext config identity changed after finalize";
      return false;
    }
    config_generation_ = config_generation;
    config_finalized_ = true;
    if (borrowed_prepared_host_ == nullptr)
      cost_layout_.RebindIdentity(topology_generation_, config_generation_);
    packed_state_.config_generation = config_generation_;
    if (device_context_ != nullptr &&
        !device_context_->FinalizeConfig(config_generation_, error)) {
      return false;
    }
    return true;
  }

  bool UploadPersistentFrozenScaling(const CudaLayerBOptions& options,
                                     std::string* error) {
    return device_context_ == nullptr ||
           device_context_->UploadFrozenScaling(options, error);
  }

  bool PublishPersistentFrozenScalingFromInitial(
      const CudaDeviceLinearizationToken& token,
      const CudaLinearizationIdentity& identity,
      std::string* error) {
    return device_context_ != nullptr &&
           device_context_->PublishFrozenScalingFromInitial(
               token, identity, error);
  }

  bool persistent_device_enabled() const noexcept {
    return device_context_ != nullptr;
  }

  bool device_state_enabled() const noexcept {
    return backend_ == CudaDeviceContextBackend::kDeviceState ||
           backend_ == CudaDeviceContextBackend::kDeviceControl;
  }

  bool device_control_enabled() const noexcept {
    return backend_ == CudaDeviceContextBackend::kDeviceControl;
  }

  bool audit_mirror_enabled() const noexcept {
    return audit_mirror_enabled_;
  }

  GpuBaDeviceContext* persistent_device() noexcept {
    return device_context_.get();
  }

  void PublishPersistentInitial(
      const CudaLinearizationIdentity& identity) noexcept {
    if (device_context_ != nullptr) device_context_->PublishInitial(identity);
  }

  bool PreparePersistentCommit(
      const CudaLinearizationIdentity& identity,
      DeviceCommitToken* token,
      std::string* error) noexcept {
    return device_context_ == nullptr ||
           device_context_->PrepareCommitToken(identity, token, error);
  }

  void CommitPersistentPending(DeviceCommitToken&& token) noexcept {
    if (device_context_ != nullptr)
      device_context_->CommitPending(std::move(token));
  }

  void DiscardPersistentBuild(const CudaFaultLogicalSite site) noexcept {
    if (device_context_ != nullptr) device_context_->DiscardBuild(site);
  }

  void DiscardDeviceTrialState() noexcept {
    if (device_context_ != nullptr) device_context_->DiscardTrialState();
  }

  bool ClosePersistent(std::string* error) noexcept {
    return device_context_ == nullptr || device_context_->Close(error);
  }

  bool ValidateDeviceLinearizationBinding(
      const UndampedCurrentLinearization& value,
      std::string* error) noexcept {
    return device_context_ == nullptr ||
           device_context_->ValidateLinearizationToken(
               value.device_token(), value.identity(), error);
  }

  bool AcquirePackedState(const Snapshot& snapshot,
                          const bool allow_prepared_initial,
                          const PackedLayerAState** output,
                          std::string* error) {
    if (!initialized_ || output == nullptr || error == nullptr) return false;
    if (allow_prepared_initial && prepared_initial_available_) {
      prepared_initial_available_ = false;
      *output = &packed_state_;
      return true;
    }
    if (!PackDynamicState(snapshot, error)) return false;
    prepared_initial_available_ = false;
    *output = &packed_state_;
    return true;
  }

  bool ValidateLayerBOptions(const Snapshot& snapshot,
                             const CudaLayerBOptions& options,
                             std::string* error) const {
    CudaLossMode mode;
    double scale = 1.0;
    if (options.layer_a.residual_order != residual_order_ ||
        !ResolveCudaLoss(snapshot, options, &mode, &scale, error) ||
        mode != loss_mode_ || scale != loss_scale_) {
      if (error != nullptr && error->empty())
        *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
      return false;
    }
    return true;
  }

  bool ValidateNativeLayerBOptions(const CudaLayerBOptions& options,
                                   std::string* error) const {
    if (borrowed_native_ == nullptr ||
        options.layer_a.residual_order != residual_order_ ||
        options.loss_mode != loss_mode_ ||
        (loss_mode_ != CudaLossMode::kTrivial &&
         options.loss_scale != loss_scale_) ||
        options.hessian_assembly_backend != native_hessian_backend_) {
      if (error != nullptr) *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
      return false;
    }
    return true;
  }

  bool ValidateDeviceStateHostMirror(const Snapshot& snapshot,
                                     std::string* error) const {
    if (!ValidateStaticState(snapshot, error)) return false;
    const auto& camera_parameters = CameraParametersRef();
    if (snapshot.cameras.size() != camera_parameters.size()) {
      *error = "GpuBaSolveContext camera state count changed";
      return false;
    }
    for (size_t i = 0; i < snapshot.cameras.size(); ++i) {
      if (snapshot.cameras[i].params != camera_parameters[i]) {
        *error = "GpuBaSolveContext fixed camera parameters changed";
        return false;
      }
    }
    return true;
  }

  LayerAOutputView MakeLayerAView(const CudaLayerAResult& output) const {
    LayerAOutputView view;
    view.output = &output;
    view.topology_generation = topology_generation_;
    view.config_generation = config_generation_;
    view.layout_id = CostLayoutRef().layout_id;
    return view;
  }

  bool ValidateLayerAView(const LayerAOutputView& view,
                          std::string* error) const {
    const CostLayout& layout = CostLayoutRef();
    const bool counts_match = view.output != nullptr &&
        view.output->visual.size() == layout.visual_count &&
        view.output->lidar.size() == layout.lidar_count;
    const bool identity_match =
        view.layout_id == layout.layout_id &&
        view.topology_generation == topology_generation_ &&
        view.config_generation == config_generation_;
    if (!counts_match || !identity_match) {
      if (error != nullptr) *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
      return false;
    }
    return true;
  }

  const LayerBTopology& BorrowLayerBTopology() {
    RecordTopologyBorrow();
    return LayerBTopologyRef();
  }

  const LayerCTopology& BorrowLayerCTopology() {
    RecordTopologyBorrow();
    return LayerCTopologyRef();
  }

  void RecordDynamicRefresh() {
    ++topology_refresh_count_;
    if (g_cuda_timing_sink != nullptr) {
      HostPhaseScope timing(CUDA_TIMING_PHASE(topology_refresh));
      ++g_cuda_timing_sink->topology_refresh_count;
    }
  }

  const CostLayout& cost_layout() const noexcept { return CostLayoutRef(); }
  CudaLossMode loss_mode() const noexcept { return loss_mode_; }
  double loss_scale() const noexcept { return loss_scale_; }
  uint64_t solve_generation() const noexcept { return solve_generation_; }
  uint64_t topology_generation() const noexcept {
    return topology_generation_;
  }
  uint64_t config_generation() const noexcept { return config_generation_; }
  uint64_t topology_reuse_hits() const noexcept {
    return topology_reuse_hits_;
  }
  uint64_t topology_refresh_count() const noexcept {
    return topology_refresh_count_;
  }
  const std::string& topology_fingerprint() const noexcept {
    return topology_fingerprint_;
  }

 private:
  const std::vector<CameraStaticLayoutEntry>& CameraLayoutRef() const {
    return borrowed_prepared_host_ == nullptr
        ? camera_layout_ : borrowed_prepared_host_->camera_layout;
  }
  const std::vector<std::vector<double>>& CameraParametersRef() const {
    return borrowed_prepared_host_ == nullptr
        ? camera_parameters_ : borrowed_prepared_host_->camera_parameters;
  }
  const std::vector<ImageStaticLayoutEntry>& ImageLayoutRef() const {
    return borrowed_prepared_host_ == nullptr
        ? image_layout_ : borrowed_prepared_host_->image_layout;
  }
  const std::vector<PointStaticLayoutEntry>& PointLayoutRef() const {
    return borrowed_prepared_host_ == nullptr
        ? point_layout_ : borrowed_prepared_host_->point_layout;
  }
  const std::vector<VisualStaticLayoutEntry>& VisualLayoutRef() const {
    return borrowed_prepared_host_ == nullptr
        ? visual_layout_ : borrowed_prepared_host_->visual_layout;
  }
  const std::vector<LidarStaticLayoutEntry>& LidarLayoutRef() const {
    return borrowed_prepared_host_ == nullptr
        ? lidar_layout_ : borrowed_prepared_host_->lidar_layout;
  }
  const std::unordered_map<uint32_t, size_t>& ImageIndicesRef() const {
    return borrowed_prepared_host_ == nullptr
        ? image_indices_ : borrowed_prepared_host_->image_indices;
  }
  const CostLayout& CostLayoutRef() const {
    if (borrowed_native_ != nullptr) return borrowed_native_->cost_layout;
    return borrowed_prepared_host_ == nullptr
               ? cost_layout_ : borrowed_prepared_host_->cost_layout;
  }
  const LayerBTopology& LayerBTopologyRef() const {
    if (borrowed_native_ != nullptr) return borrowed_native_->layer_b_topology;
    return borrowed_prepared_host_ == nullptr
               ? layer_b_topology_ : borrowed_prepared_host_->layer_b_topology;
  }
  const LayerCTopology& LayerCTopologyRef() const {
    if (borrowed_native_ != nullptr) return borrowed_native_->layer_c_topology;
    return borrowed_prepared_host_ == nullptr
               ? layer_c_topology_ : *borrowed_prepared_host_->layer_c_topology;
  }

  bool BuildStaticLayout(const Snapshot& snapshot, std::string* error) {
    camera_indices_.clear();
    image_indices_.clear();
    point_indices_.clear();
    observation_indices_.clear();
    lidar_indices_.clear();
    visual_output_indices_.clear();
    lidar_output_indices_.clear();
    camera_indices_.reserve(snapshot.cameras.size());
    image_indices_.reserve(snapshot.images.size());
    point_indices_.reserve(snapshot.points.size());
    observation_indices_.reserve(snapshot.observations.size());
    lidar_indices_.reserve(snapshot.lidar.size());
    visual_output_indices_.reserve(packed_state_.visual.size());
    lidar_output_indices_.reserve(packed_state_.lidar.size());
    camera_layout_.resize(snapshot.cameras.size());
    camera_parameters_.resize(snapshot.cameras.size());
    image_layout_.resize(snapshot.images.size());
    point_layout_.resize(snapshot.points.size());
    for (size_t i = 0; i < snapshot.cameras.size(); ++i) {
      const CameraSnapshot& camera = snapshot.cameras[i];
      if (!camera_indices_.emplace(camera.camera_id, i).second) {
        *error = "duplicate camera ID in unified problem layout";
        return false;
      }
      camera_layout_[i] = {camera.camera_id, camera.model_id,
                           camera.width, camera.height,
                           camera.params.size(), camera.constant};
      camera_parameters_[i] = camera.params;
    }
    for (size_t i = 0; i < snapshot.images.size(); ++i) {
      const ImageSnapshot& image = snapshot.images[i];
      if (!image_indices_.emplace(image.image_id, i).second) {
        *error = "duplicate image ID in unified problem layout";
        return false;
      }
      image_layout_[i] = {image.image_id, image.camera_id, image.selected,
                          image.pose_constant,
                          image.has_pose_parameter_blocks,
                          image.constant_tvec_mask};
    }
    for (size_t i = 0; i < snapshot.points.size(); ++i) {
      const PointSnapshot& point = snapshot.points[i];
      if (!point_indices_.emplace(point.point3D_id, i).second) {
        *error = "duplicate point ID in unified problem layout";
        return false;
      }
      point_layout_[i] = {point.point3D_id, point.constant,
                          point.config_role, point.has_search_range,
                          point.search_range};
    }
    for (size_t i = 0; i < snapshot.observations.size(); ++i) {
      if (!observation_indices_
               .emplace(snapshot.observations[i].source_index, i).second) {
        *error = "duplicate visual source index in unified problem layout";
        return false;
      }
    }
    for (size_t i = 0; i < snapshot.lidar.size(); ++i) {
      if (!lidar_indices_.emplace(snapshot.lidar[i].source_index, i).second) {
        *error = "duplicate LiDAR source index in unified problem layout";
        return false;
      }
    }

    visual_layout_.reserve(packed_state_.visual.size());
    for (size_t output_index = 0;
         output_index < packed_state_.visual.size(); ++output_index) {
      const CudaVisualInput& input = packed_state_.visual[output_index];
      const auto observation_it = observation_indices_.find(input.source_index);
      const auto image_it = image_indices_.find(input.image_id);
      const auto point_it = point_indices_.find(input.point3D_id);
      if (observation_it == observation_indices_.end() ||
          image_it == image_indices_.end() ||
          point_it == point_indices_.end()) {
        *error = "static visual layout references a missing entity";
        return false;
      }
      if (!visual_output_indices_
               .emplace(input.source_index,
                        static_cast<uint32_t>(output_index)).second) {
        *error = "duplicate visual source index in unified problem layout";
        return false;
      }
      const auto camera_it = camera_indices_.find(
          snapshot.images[image_it->second].camera_id);
      if (camera_it == camera_indices_.end()) {
        *error = "static visual layout references a missing camera";
        return false;
      }
      VisualStaticLayoutEntry entry;
      entry.observation_index = observation_it->second;
      entry.image_index = image_it->second;
      entry.point_index = point_it->second;
      entry.camera_index = camera_it->second;
      entry.point2D_idx =
          snapshot.observations[observation_it->second].point2D_idx;
      entry.packed_template = input;
      visual_layout_.push_back(entry);
    }
    lidar_layout_.reserve(packed_state_.lidar.size());
    for (size_t output_index = 0;
         output_index < packed_state_.lidar.size(); ++output_index) {
      const CudaLidarInput& input = packed_state_.lidar[output_index];
      const auto lidar_it = lidar_indices_.find(input.source_index);
      const auto point_it = point_indices_.find(input.point3D_id);
      if (lidar_it == lidar_indices_.end() ||
          point_it == point_indices_.end()) {
        *error = "static LiDAR layout references a missing entity";
        return false;
      }
      if (!lidar_output_indices_
               .emplace(input.source_index,
                        static_cast<uint32_t>(output_index)).second) {
        *error = "duplicate LiDAR source index in unified problem layout";
        return false;
      }
      LidarStaticLayoutEntry entry;
      entry.lidar_index = lidar_it->second;
      entry.point_index = point_it->second;
      entry.lidar_type = snapshot.lidar[lidar_it->second].lidar_type;
      entry.packed_template = input;
      lidar_layout_.push_back(entry);
    }
    return true;
  }

  bool ValidateStaticState(const Snapshot& snapshot, std::string* error) const {
    const auto& camera_layout = CameraLayoutRef();
    const auto& image_layout = ImageLayoutRef();
    const auto& point_layout = PointLayoutRef();
    const auto& visual_layout = VisualLayoutRef();
    const auto& lidar_layout = LidarLayoutRef();
    if (snapshot.cameras.size() != camera_layout.size() ||
        snapshot.images.size() != image_layout.size() ||
        snapshot.points.size() != point_layout.size() ||
        snapshot.observations.size() < visual_layout.size() ||
        snapshot.lidar.size() < lidar_layout.size()) {
      *error = "GpuBaSolveContext static entity counts changed";
      return false;
    }
    for (size_t i = 0; i < camera_layout.size(); ++i) {
      const CameraSnapshot& value = snapshot.cameras[i];
      const CameraStaticLayoutEntry& expected = camera_layout[i];
      if (value.camera_id != expected.camera_id ||
          value.model_id != expected.model_id ||
          value.width != expected.width || value.height != expected.height ||
          value.params.size() != expected.parameter_count ||
          value.constant != expected.constant) {
        *error = "GpuBaSolveContext camera layout changed";
        return false;
      }
    }
    for (size_t i = 0; i < image_layout.size(); ++i) {
      const ImageSnapshot& value = snapshot.images[i];
      const ImageStaticLayoutEntry& expected = image_layout[i];
      if (value.image_id != expected.image_id ||
          value.camera_id != expected.camera_id ||
          value.selected != expected.selected ||
          value.pose_constant != expected.pose_constant ||
          value.has_pose_parameter_blocks != expected.has_pose_parameter_blocks ||
          value.constant_tvec_mask != expected.constant_tvec_mask) {
        *error = "GpuBaSolveContext image layout changed";
        return false;
      }
    }
    for (size_t i = 0; i < point_layout.size(); ++i) {
      const PointSnapshot& value = snapshot.points[i];
      const PointStaticLayoutEntry& expected = point_layout[i];
      if (value.point3D_id != expected.point3D_id ||
          value.constant != expected.constant ||
          value.config_role != expected.config_role ||
          value.has_search_range != expected.has_search_range ||
          (value.has_search_range &&
           value.search_range != expected.search_range)) {
        *error = "GpuBaSolveContext point layout changed";
        return false;
      }
    }
    return true;
  }

  bool PackPoseState(const Snapshot& snapshot, std::string* error) {
    const LayerBTopology& topology = LayerBTopologyRef();
    const auto& image_indices = ImageIndicesRef();
    packed_state_.pose_state.resize(topology.poses.size());
    for (size_t i = 0; i < topology.poses.size(); ++i) {
      const auto image_it = image_indices.find(topology.poses[i].image_id);
      if (image_it == image_indices.end()) {
        *error = "dynamic pose state references a missing image";
        return false;
      }
      const ImageSnapshot& image = snapshot.images[image_it->second];
      for (size_t j = 0; j < 4; ++j)
        packed_state_.pose_state[i].quaternion[j] = image.qvec[j];
    }
    return true;
  }

  bool PackDynamicState(const Snapshot& snapshot, std::string* error) {
    HostPhaseScope timing(CUDA_TIMING_PHASE(build_cuda_layer_a_inputs));
    if (g_cuda_solve_call_counters != nullptr)
      ++g_cuda_solve_call_counters->build_cuda_layer_a_inputs;
    if (g_cuda_timing_sink != nullptr)
      ++g_cuda_timing_sink->build_cuda_layer_a_inputs_count;
    if (!ValidateStaticState(snapshot, error)) return false;
    const auto& visual_layout = VisualLayoutRef();
    const auto& lidar_layout = LidarLayoutRef();
    packed_state_.visual.resize(visual_layout.size());
    for (size_t i = 0; i < visual_layout.size(); ++i) {
      const VisualStaticLayoutEntry& layout = visual_layout[i];
      const ObservationSnapshot& observation =
          snapshot.observations[layout.observation_index];
      const ImageSnapshot& image = snapshot.images[layout.image_index];
      const PointSnapshot& point = snapshot.points[layout.point_index];
      const CameraSnapshot& camera = snapshot.cameras[layout.camera_index];
      if (observation.source_index != layout.packed_template.source_index ||
          observation.image_id != layout.packed_template.image_id ||
          observation.point3D_id != layout.packed_template.point3D_id ||
          observation.point2D_idx != layout.point2D_idx ||
          observation.xy[0] != layout.packed_template.observation[0] ||
          observation.xy[1] != layout.packed_template.observation[1] ||
          camera.model_id != kOpenCvcCameraModelId ||
          camera.params.size() != 8) {
        *error = "GpuBaSolveContext visual residual layout changed";
        return false;
      }
      CudaVisualInput& output = packed_state_.visual[i];
      output = layout.packed_template;
      for (size_t j = 0; j < 4; ++j) output.quaternion[j] = image.qvec[j];
      for (size_t j = 0; j < 3; ++j) {
        output.translation[j] = image.tvec[j];
        output.point[j] = point.xyz[j];
      }
      for (size_t j = 0; j < 8; ++j) output.camera[j] = camera.params[j];
    }
    packed_state_.lidar.resize(lidar_layout.size());
    for (size_t i = 0; i < lidar_layout.size(); ++i) {
      const LidarStaticLayoutEntry& layout = lidar_layout[i];
      const LidarSnapshot& lidar = snapshot.lidar[layout.lidar_index];
      const PointSnapshot& point = snapshot.points[layout.point_index];
      if (lidar.source_index != layout.packed_template.source_index ||
          lidar.point3D_id != layout.packed_template.point3D_id ||
          lidar.lidar_type != layout.lidar_type) {
        *error = "GpuBaSolveContext LiDAR residual layout changed";
        return false;
      }
      CudaLidarInput& output = packed_state_.lidar[i];
      output = layout.packed_template;
      for (size_t j = 0; j < 3; ++j) {
        output.point[j] = point.xyz[j];
        output.plane[j] = lidar.plane[j];
      }
      output.plane[3] = lidar.plane[3];
      output.weight = lidar.weight;
    }
    packed_state_.topology_generation = topology_generation_;
    packed_state_.config_generation = config_generation_;
    packed_state_.layout_id = CostLayoutRef().layout_id;
    if (g_cuda_timing_sink != nullptr) {
      g_cuda_timing_sink->build_cuda_layer_a_inputs.bytes = SaturatingAdd(
          g_cuda_timing_sink->build_cuda_layer_a_inputs.bytes,
          static_cast<uint64_t>(packed_state_.visual.size() *
                                    sizeof(CudaVisualInput) +
                                packed_state_.lidar.size() *
                                    sizeof(CudaLidarInput)));
    }
    return PackPoseState(snapshot, error);
  }

  void RecordTopologyBorrow() {
    ++topology_reuse_hits_;
    if (g_cuda_timing_sink != nullptr) {
      ++g_cuda_timing_sink->cache_lookup_count;
      ++g_cuda_timing_sink->cache_hit_count;
      RecordExplicitCall(CUDA_TIMING_PHASE(topology_lookup));
      RecordExplicitCall(CUDA_TIMING_PHASE(topology_cache));
    }
  }

  bool initialized_ = false;
  bool config_finalized_ = false;
  bool prepared_initial_available_ = false;
  bool has_layer_c_topology_ = false;
  uint64_t solve_generation_ = 0;
  uint64_t topology_generation_ = 0;
  uint64_t config_generation_ = 0;
  uint64_t topology_reuse_hits_ = 0;
  uint64_t topology_refresh_count_ = 0;
  CudaResidualOrder residual_order_ = CudaResidualOrder::kCanonical;
  CudaLossMode loss_mode_ = CudaLossMode::kTrivial;
  double loss_scale_ = 1.0;
  CudaDeviceContextBackend backend_ = CudaDeviceContextBackend::kLegacy;
  CudaExecutionProfile execution_profile_ = CudaExecutionProfile::kBaseline;
  CudaArithmeticPrecision arithmetic_precision_ =
      CudaArithmeticPrecision::kFp64;
  const MapperStaticCatalogStableTables* indexed_catalog_tables_ = nullptr;
  const IndexedActiveSolveDescriptor* indexed_active_solve_ = nullptr;
  bool audit_mirror_enabled_ = false;
  CudaFullLmRuntimeInfo* audit_runtime_ = nullptr;
  // Non-owning immutable borrow. PreparedHostSolveView owns the shared data
  // for the complete synchronous RunCustomCudaSolve call.
  const PreparedHostSolveViewData* borrowed_prepared_host_ = nullptr;
  const LegacyKernelInputBundle::Impl* borrowed_native_ = nullptr;
  CudaHessianAssemblyBackend native_hessian_backend_ =
      CudaHessianAssemblyBackend::kCompatibilityDefault;
  std::vector<CameraStaticLayoutEntry> camera_layout_;
  std::vector<std::vector<double>> camera_parameters_;
  std::vector<ImageStaticLayoutEntry> image_layout_;
  std::vector<PointStaticLayoutEntry> point_layout_;
  std::vector<VisualStaticLayoutEntry> visual_layout_;
  std::vector<LidarStaticLayoutEntry> lidar_layout_;
  std::unordered_map<uint32_t, size_t> camera_indices_;
  std::unordered_map<uint32_t, size_t> image_indices_;
  std::unordered_map<uint64_t, size_t> point_indices_;
  std::unordered_map<uint64_t, size_t> observation_indices_;
  std::unordered_map<uint64_t, size_t> lidar_indices_;
  std::unordered_map<uint64_t, uint32_t> visual_output_indices_;
  std::unordered_map<uint64_t, uint32_t> lidar_output_indices_;
  PackedLayerAState packed_state_;
  CostLayout cost_layout_;
  LayerBTopology layer_b_topology_;
  LayerCTopology layer_c_topology_;
  std::string topology_fingerprint_;
  std::unique_ptr<GpuBaDeviceContext> device_context_;
};

static_assert(!std::is_copy_constructible<GpuBaSolveContext>::value,
              "GpuBaSolveContext must remain solve-owned and non-copyable");
static_assert(!std::is_copy_assignable<GpuBaSolveContext>::value,
              "GpuBaSolveContext must remain solve-owned and non-copyable");

namespace {

bool SameNativeCostLayout(const CostLayout& lhs, const CostLayout& rhs) {
  if (lhs.residual_order != rhs.residual_order ||
      lhs.visual_count != rhs.visual_count ||
      lhs.lidar_count != rhs.lidar_count ||
      lhs.entries.size() != rhs.entries.size()) {
    return false;
  }
  for (size_t i = 0; i < lhs.entries.size(); ++i) {
    if (lhs.entries[i].residual_kind != rhs.entries[i].residual_kind ||
        lhs.entries[i].output_index != rhs.entries[i].output_index) {
      return false;
    }
  }
  return true;
}

bool SameNativeLayerB(const LayerBTopology& lhs,
                      const LayerBTopology& rhs) {
  if (lhs.poses.size() != rhs.poses.size() ||
      lhs.points.size() != rhs.points.size() ||
      lhs.edges.size() != rhs.edges.size() ||
      lhs.pose_adjacency != rhs.pose_adjacency ||
      lhs.edge_adjacency != rhs.edge_adjacency ||
      lhs.point_adjacency.size() != rhs.point_adjacency.size()) {
    return false;
  }
  for (size_t i = 0; i < lhs.poses.size(); ++i) {
    const DevicePoseMeta& a = lhs.poses[i];
    const DevicePoseMeta& b = rhs.poses[i];
    if (a.image_id != b.image_id || a.dimension != b.dimension ||
        a.adjacency_begin != b.adjacency_begin ||
        a.adjacency_end != b.adjacency_end ||
        !std::equal(std::begin(a.free_translation_indices),
                    std::end(a.free_translation_indices),
                    std::begin(b.free_translation_indices))) {
      return false;
    }
  }
  for (size_t i = 0; i < lhs.points.size(); ++i) {
    if (lhs.points[i].point3D_id != rhs.points[i].point3D_id ||
        lhs.points[i].adjacency_begin != rhs.points[i].adjacency_begin ||
        lhs.points[i].adjacency_end != rhs.points[i].adjacency_end) {
      return false;
    }
  }
  for (size_t i = 0; i < lhs.edges.size(); ++i) {
    const DeviceEdgeMeta& a = lhs.edges[i];
    const DeviceEdgeMeta& b = rhs.edges[i];
    if (a.pose_index != b.pose_index || a.point_index != b.point_index ||
        a.pose_dimension != b.pose_dimension ||
        a.adjacency_begin != b.adjacency_begin ||
        a.adjacency_end != b.adjacency_end) {
      return false;
    }
  }
  for (size_t i = 0; i < lhs.point_adjacency.size(); ++i) {
    if (lhs.point_adjacency[i].residual_kind !=
            rhs.point_adjacency[i].residual_kind ||
        lhs.point_adjacency[i].residual_index !=
            rhs.point_adjacency[i].residual_index) {
      return false;
    }
  }
  return true;
}

bool SameNativeLayerC(const LayerCTopology& lhs,
                      const LayerCTopology& rhs) {
  if (lhs.pose_dimension != rhs.pose_dimension ||
      lhs.poses.size() != rhs.poses.size() ||
      lhs.points.size() != rhs.points.size() ||
      lhs.pose_edges != rhs.pose_edges || lhs.point_edges != rhs.point_edges ||
      lhs.pairs.size() != rhs.pairs.size() ||
      lhs.pair_contributions.size() != rhs.pair_contributions.size()) {
    return false;
  }
  for (size_t i = 0; i < lhs.poses.size(); ++i) {
    if (lhs.poses[i].offset != rhs.poses[i].offset ||
        lhs.poses[i].dimension != rhs.poses[i].dimension ||
        lhs.poses[i].edge_begin != rhs.poses[i].edge_begin ||
        lhs.poses[i].edge_end != rhs.poses[i].edge_end) return false;
  }
  for (size_t i = 0; i < lhs.points.size(); ++i) {
    if (lhs.points[i].edge_begin != rhs.points[i].edge_begin ||
        lhs.points[i].edge_end != rhs.points[i].edge_end) return false;
  }
  for (size_t i = 0; i < lhs.pairs.size(); ++i) {
    const DevicePairMeta& a = lhs.pairs[i];
    const DevicePairMeta& b = rhs.pairs[i];
    if (a.lhs_pose != b.lhs_pose || a.rhs_pose != b.rhs_pose ||
        a.adjacency_begin != b.adjacency_begin ||
        a.adjacency_end != b.adjacency_end) return false;
  }
  for (size_t i = 0; i < lhs.pair_contributions.size(); ++i) {
    const DevicePairContribution& a = lhs.pair_contributions[i];
    const DevicePairContribution& b = rhs.pair_contributions[i];
    if (a.point_index != b.point_index || a.lhs_edge != b.lhs_edge ||
        a.rhs_edge != b.rhs_edge) return false;
  }
  return true;
}

