bool CompareNativePreparationToLegacyForTesting(
    const Snapshot& legacy,
    const NativeHostSolveView& native_view,
    const ActiveStateBuffer& native_state,
    const CudaLayerBOptions& options,
    const uint64_t pair_chunk_limit_bytes,
    const CudaHotKernelMode hot_kernel_mode,
    const CudaSchurContributionBackend schur_backend,
    const uint32_t schur_segment_size,
    NativePreparationComparisonResult* result,
    std::string* error) {
  if (result == nullptr || error == nullptr) return false;
  *result = NativePreparationComparisonResult();
  LegacyKernelInputBundle native;
  if (!BuildLegacyKernelInputBundle(native_view, native_state, &native,
                                    error)) return false;
  HotKernelImplementation hot = HotKernelImplementation::kReference;
  if (!ResolveHotKernelImplementation(hot_kernel_mode, false, true, &hot,
                                      error)) return false;
  GpuBaSolveContext legacy_context;
  legacy_context.SetArithmeticPrecisionForSolve(
      native_view.config.arithmetic_precision);
  if (!legacy_context.Initialize(
          legacy, options, pair_chunk_limit_bytes, 1, true,
          CudaDeviceContextBackend::kLegacy, hot, schur_backend,
          schur_segment_size, native_view.config.execution_profile, false,
          nullptr, error)) {
    return false;
  }
  const PackedLayerAState* legacy_packed = nullptr;
  if (!legacy_context.AcquirePackedState(legacy, true, &legacy_packed, error))
    return false;
  const CostLayout& legacy_cost = legacy_context.cost_layout();
  const LayerBTopology& legacy_b = legacy_context.BorrowLayerBTopology();
  const LayerCTopology& legacy_c = legacy_context.BorrowLayerCTopology();
  const LegacyKernelInputBundle::Impl& candidate = *native.impl_;
  result->visual_count = candidate.packed.visual.size();
  result->lidar_count = candidate.packed.lidar.size();
  result->cost_entry_count = candidate.cost_layout.entries.size();
  result->pose_adjacency_count = candidate.layer_b_topology.pose_adjacency.size();
  result->point_adjacency_count =
      candidate.layer_b_topology.point_adjacency.size();
  result->edge_adjacency_count = candidate.layer_b_topology.edge_adjacency.size();
  result->pair_contribution_count =
      candidate.layer_c_topology.pair_contributions.size();
  std::vector<uint8_t> sources(native_view.residual_ordinals.size(), 0);
  result->source_indices_dense = true;
  for (const CudaVisualInput& value : candidate.packed.visual) {
    if (value.source_index >= sources.size() || sources[value.source_index]++)
      result->source_indices_dense = false;
  }
  for (const CudaLidarInput& value : candidate.packed.lidar) {
    if (value.source_index >= sources.size() || sources[value.source_index]++)
      result->source_indices_dense = false;
  }
  result->source_indices_dense = result->source_indices_dense &&
      std::all_of(sources.begin(), sources.end(),
                  [](const uint8_t value) { return value == 1; });
  result->cost_entries_exact = SameNativeCostLayout(
      legacy_cost, candidate.cost_layout);
  result->layer_b_exact = SameNativeLayerB(legacy_b,
                                           candidate.layer_b_topology);
  result->layer_c_exact = SameNativeLayerC(legacy_c,
                                           candidate.layer_c_topology);
  if (legacy_packed->visual.size() != candidate.packed.visual.size() ||
      legacy_packed->lidar.size() != candidate.packed.lidar.size() ||
      !result->source_indices_dense || !result->cost_entries_exact ||
      !result->layer_b_exact || !result->layer_c_exact) {
    *error = "native and legacy production preparation differ";
    return false;
  }
  for (size_t i = 0; i < legacy_packed->visual.size(); ++i) {
    const CudaVisualInput& a = legacy_packed->visual[i];
    const CudaVisualInput& b = candidate.packed.visual[i];
    if (a.source_index != b.source_index || a.image_id != b.image_id ||
        a.point3D_id != b.point3D_id ||
        !std::equal(std::begin(a.quaternion), std::end(a.quaternion),
                    std::begin(b.quaternion)) ||
        !std::equal(std::begin(a.translation), std::end(a.translation),
                    std::begin(b.translation)) ||
        !std::equal(std::begin(a.point), std::end(a.point),
                    std::begin(b.point)) ||
        !std::equal(std::begin(a.camera), std::end(a.camera),
                    std::begin(b.camera)) ||
        !std::equal(std::begin(a.observation), std::end(a.observation),
                    std::begin(b.observation))) {
      *error = "native visual packed input differs from legacy";
      return false;
    }
  }
  for (size_t i = 0; i < legacy_packed->lidar.size(); ++i) {
    const CudaLidarInput& a = legacy_packed->lidar[i];
    const CudaLidarInput& b = candidate.packed.lidar[i];
    if (a.source_index != b.source_index ||
        a.point3D_id != b.point3D_id || a.weight != b.weight ||
        a.mode != b.mode ||
        a.near_zero_threshold != b.near_zero_threshold ||
        !std::equal(std::begin(a.point), std::end(a.point),
                    std::begin(b.point)) ||
        !std::equal(std::begin(a.plane), std::end(a.plane),
                    std::begin(b.plane))) {
      *error = "native LiDAR packed input differs from legacy";
      return false;
    }
  }
  return true;
}

namespace {

template <typename T>
bool GpuBaDeviceContext::AllocatePersistent(T** pointer,
                                             const size_t count,
                                             std::string* error) {
  if (pointer == nullptr || error == nullptr) return false;
  *pointer = nullptr;
  if (count == 0) return true;
  if (count > std::numeric_limits<size_t>::max() / sizeof(T)) {
    *error = "persistent CUDA allocation size overflow";
    return false;
  }
  const size_t bytes = count * sizeof(T);
  if (arena_enabled_) {
    constexpr uint64_t kAlignment = 256;
    if (arena_offset_ > std::numeric_limits<uint64_t>::max() -
                            (kAlignment - 1)) {
      *error = "persistent CUDA arena alignment overflow";
      return false;
    }
    const uint64_t aligned =
        (arena_offset_ + kAlignment - 1) & ~(kAlignment - 1);
    if (bytes > std::numeric_limits<uint64_t>::max() - aligned) {
      *error = "persistent CUDA arena slice overflow";
      return false;
    }
    const uint64_t end = aligned + bytes;
    arena_offset_ = end;
    if (arena_planning_) return true;
    if (runtime_pool_lease_.entry == nullptr ||
        runtime_pool_lease_.entry->arena == nullptr ||
        end > runtime_pool_lease_.entry->arena_capacity) {
      *error = "persistent CUDA arena slice exceeds planned capacity";
      return false;
    }
    *pointer = reinterpret_cast<T*>(
        static_cast<uint8_t*>(runtime_pool_lease_.entry->arena) + aligned);
    ++runtime_->persistent_device.arena_slice_count;
    runtime_->persistent_device.arena_slice_bytes = SaturatingAdd(
        runtime_->persistent_device.arena_slice_bytes,
        static_cast<uint64_t>(bytes));
    return true;
  }
  HostPhaseScope timing(CUDA_TIMING_PHASE(allocation), bytes);
  cudaError_t status = memory_mode_ == CudaMemoryMode::kUnifiedManaged
                           ? cudaMallocManaged(reinterpret_cast<void**>(pointer),
                                               bytes, cudaMemAttachGlobal)
                           : cudaMalloc(reinterpret_cast<void**>(pointer), bytes);
  if (status != cudaSuccess) {
    *error = std::string("persistent cudaMalloc failed: ") +
             CudaErrorText(status);
    return false;
  }
  if (!RegisterCudaResource(reinterpret_cast<uintptr_t>(*pointer),
                            CudaTeardownType::kAllocation, device_)) {
    CleanupCudaFree(*pointer, device_);
    *pointer = nullptr;
    *error = "AUDIT_CAPACITY: persistent CUDA resource registry is full";
    return false;
  }
  allocations_.push_back({*pointer, static_cast<uint64_t>(bytes)});
  CudaPersistentDeviceRuntimeInfo& audit = runtime_->persistent_device;
  if (initializing_) {
    ++audit.initialization_allocation_calls;
    audit.initialization_allocation_bytes = SaturatingAdd(
        audit.initialization_allocation_bytes, static_cast<uint64_t>(bytes));
  } else {
    ++audit.post_initialize_allocation_calls;
    audit.post_initialize_allocation_bytes = SaturatingAdd(
        audit.post_initialize_allocation_bytes, static_cast<uint64_t>(bytes));
  }
  audit.peak_resident_bytes = std::max(
      audit.peak_resident_bytes, audit.initialization_allocation_bytes);
  return true;
}

template <typename T>
bool GpuBaDeviceContext::UploadStatic(T* destination,
                                      const std::vector<T>& source,
                                      std::string* error) {
  if (source.empty()) return true;
  const uint64_t bytes = static_cast<uint64_t>(source.size() * sizeof(T));
  HostPhaseScope timing(CUDA_TIMING_PHASE(h2d_memcpy), bytes);
  const cudaError_t status = cudaMemcpyAsync(
      destination, source.data(), bytes, cudaMemcpyHostToDevice, stream_);
  if (status != cudaSuccess) {
    *error = std::string("persistent static upload failed: ") +
             CudaErrorText(status);
    return false;
  }
  ++runtime_->persistent_device.static_upload_calls;
  runtime_->persistent_device.static_upload_bytes = SaturatingAdd(
      runtime_->persistent_device.static_upload_bytes, bytes);
  return true;
}

template <typename T>
bool GpuBaDeviceContext::UploadDynamic(T* destination,
                                       const std::vector<T>& source,
                                       std::string* error) {
  if (source.empty()) return true;
  const uint64_t bytes = static_cast<uint64_t>(source.size() * sizeof(T));
  HostPhaseScope timing(CUDA_TIMING_PHASE(h2d_memcpy), bytes);
  const cudaError_t status = cudaMemcpyAsync(
      destination, source.data(), bytes, cudaMemcpyHostToDevice, stream_);
  if (status != cudaSuccess) {
    *error = std::string("persistent dynamic upload failed: ") +
             CudaErrorText(status);
    return false;
  }
  ++runtime_->persistent_device.dynamic_state_upload_calls;
  runtime_->persistent_device.dynamic_state_upload_bytes = SaturatingAdd(
      runtime_->persistent_device.dynamic_state_upload_bytes, bytes);
  return true;
}

template <typename T>
bool GpuBaDeviceContext::DownloadController(T* source,
                                            std::vector<T>* destination,
                                            std::string* error) {
  if (destination->empty()) return true;
  const uint64_t bytes =
      static_cast<uint64_t>(destination->size() * sizeof(T));
  HostPhaseScope timing(CUDA_TIMING_PHASE(d2h_memcpy), bytes);
  const cudaError_t status = cudaMemcpyAsync(
      destination->data(), source, bytes, cudaMemcpyDeviceToHost, stream_);
  if (status != cudaSuccess) {
    *error = std::string("persistent controller D2H failed: ") +
             CudaErrorText(status);
    return false;
  }
  ++runtime_->persistent_device.host_controller_d2h_calls;
  runtime_->persistent_device.host_controller_d2h_bytes = SaturatingAdd(
      runtime_->persistent_device.host_controller_d2h_bytes, bytes);
  return true;
}

template <typename T>
bool GpuBaDeviceContext::DownloadDiagnostics(T* source,
                                             std::vector<T>* destination,
                                             std::string* error) {
  if (destination->empty()) return true;
  const uint64_t bytes =
      static_cast<uint64_t>(destination->size() * sizeof(T));
  HostPhaseScope timing(CUDA_TIMING_PHASE(d2h_memcpy), bytes);
  const cudaError_t status = cudaMemcpyAsync(
      destination->data(), source, bytes, cudaMemcpyDeviceToHost, stream_);
  if (status != cudaSuccess) {
    *error = std::string("persistent diagnostics D2H failed: ") +
             CudaErrorText(status);
    return false;
  }
  ++runtime_->persistent_device.host_diagnostics_d2h_calls;
  runtime_->persistent_device.host_diagnostics_d2h_bytes = SaturatingAdd(
      runtime_->persistent_device.host_diagnostics_d2h_bytes, bytes);
  return true;
}

bool GpuBaDeviceContext::DownloadScalarPacket(DeviceLmScalarPacket* packet,
                                              std::string* error) {
  if (packet == nullptr || error == nullptr || d_scalar_packet_ == nullptr) {
    if (error != nullptr) *error = "device-control scalar packet is invalid";
    return false;
  }
  HostPhaseScope timing(CUDA_TIMING_PHASE(d2h_memcpy),
                        sizeof(DeviceLmScalarPacket));
  const cudaError_t status = cudaMemcpyAsync(
      packet, d_scalar_packet_, sizeof(DeviceLmScalarPacket),
      cudaMemcpyDeviceToHost, stream_);
  if (status != cudaSuccess) {
    *error = std::string("device-control scalar packet D2H failed: ") +
             CudaErrorText(status);
    return false;
  }
  ++runtime_->persistent_device.scalar_packet_d2h_calls;
  runtime_->persistent_device.scalar_packet_d2h_bytes = SaturatingAdd(
      runtime_->persistent_device.scalar_packet_d2h_bytes,
      sizeof(DeviceLmScalarPacket));
  if (arithmetic_precision_ ==
      CudaArithmeticPrecision::kFp32MixedStable) {
    ++runtime_->persistent_device.mixed_scalar_packet_calls;
    runtime_->persistent_device.mixed_scalar_packet_bytes = SaturatingAdd(
        runtime_->persistent_device.mixed_scalar_packet_bytes,
        sizeof(DeviceLmScalarPacket));
  }
  if (compact_control_enabled_) {
    ++runtime_->persistent_device.scalar_decision_packet_calls;
    runtime_->persistent_device.scalar_decision_packet_bytes = SaturatingAdd(
        runtime_->persistent_device.scalar_decision_packet_bytes,
        sizeof(DeviceLmScalarPacket));
  }
  return true;
}

bool GpuBaDeviceContext::Initialize(
    const Snapshot& initial_snapshot,
    const PackedLayerAState& initial,
    const CostLayout& cost_layout,
    const LayerBTopology& layer_b,
    const LayerCTopology& layer_c,
    const CudaLayerBOptions& options,
    const uint64_t solve_generation,
    const uint64_t topology_generation,
    const bool device_state_enabled,
    const bool device_control_enabled,
    const HotKernelImplementation hot_kernel_implementation,
    const CudaHessianAssemblyBackend hessian_assembly_backend,
    const CudaSchurContributionBackend schur_contribution_backend,
    const CudaArithmeticPrecision arithmetic_precision,
    const CudaExecutionProfile execution_profile,
    const bool audit_mirror_enabled,
    const MapperStaticCatalogStableTables* indexed_catalog,
    CudaFullLmRuntimeInfo* runtime,
    std::string* error) {
  return InitializeImpl(
      &initial_snapshot, nullptr, nullptr, nullptr, initial, cost_layout,
      layer_b, layer_c, options, solve_generation, topology_generation,
      device_state_enabled, device_control_enabled, hot_kernel_implementation,
      hessian_assembly_backend, schur_contribution_backend,
      arithmetic_precision, execution_profile, audit_mirror_enabled,
      indexed_catalog, runtime, error);
}

bool GpuBaDeviceContext::InitializeNative(
    const NativeHostSolveView& view,
    const ActiveStateBuffer& initial_state,
    const LegacyKernelInputBundle::Impl& native,
    const CudaLayerBOptions& options,
    const uint64_t solve_generation,
    const uint64_t topology_generation,
    const HotKernelImplementation hot_kernel_implementation,
    const CudaHessianAssemblyBackend hessian_assembly_backend,
    const CudaSchurContributionBackend schur_contribution_backend,
    const CudaArithmeticPrecision arithmetic_precision,
    const CudaExecutionProfile execution_profile,
    CudaFullLmRuntimeInfo* runtime,
    std::string* error) {
  return InitializeImpl(
      nullptr, &view, &initial_state, &native, native.packed,
      native.cost_layout, native.layer_b_topology, native.layer_c_topology,
      options, solve_generation, topology_generation, true, true,
      hot_kernel_implementation, hessian_assembly_backend,
      schur_contribution_backend, arithmetic_precision, execution_profile,
      false, nullptr, runtime, error);
}

bool GpuBaDeviceContext::InitializeImpl(
    const Snapshot* legacy_initial_snapshot,
    const NativeHostSolveView* native_view,
    const ActiveStateBuffer* native_initial_state,
    const LegacyKernelInputBundle::Impl* native,
    const PackedLayerAState& initial,
    const CostLayout& cost_layout,
    const LayerBTopology& layer_b,
    const LayerCTopology& layer_c,
    const CudaLayerBOptions& options,
    const uint64_t solve_generation,
    const uint64_t topology_generation,
    const bool device_state_enabled,
    const bool device_control_enabled,
    const HotKernelImplementation hot_kernel_implementation,
    const CudaHessianAssemblyBackend hessian_assembly_backend,
    const CudaSchurContributionBackend schur_contribution_backend,
    const CudaArithmeticPrecision arithmetic_precision,
    const CudaExecutionProfile execution_profile,
    const bool audit_mirror_enabled,
    const MapperStaticCatalogStableTables* indexed_catalog,
    CudaFullLmRuntimeInfo* runtime,
    std::string* error) {
  const bool native_initialization = native != nullptr;
  if (native_initialization != (native_view != nullptr) ||
      native_initialization != (native_initial_state != nullptr) ||
      native_initialization == (legacy_initial_snapshot != nullptr)) {
    if (error != nullptr) *error = "persistent initial-state adapter is invalid";
    return false;
  }
  if (initialized_ || initializing_ || runtime == nullptr || error == nullptr) {
    if (error != nullptr) *error = "persistent device context init is invalid";
    return false;
  }
  error->clear();
  initializing_ = true;
  runtime_ = runtime;
  runtime_->persistent_device.requested = true;
  device_state_enabled_ = device_state_enabled;
  device_control_enabled_ = device_control_enabled;
  execution_profile_ = execution_profile;
  runtime_pool_enabled_ =
      ProfileAtLeast(execution_profile_, CudaExecutionProfile::kRuntimePool);
  arena_enabled_ =
      ProfileAtLeast(execution_profile_, CudaExecutionProfile::kArena);
  device_scaling_enabled_ = device_control_enabled_ && ProfileAtLeast(
      execution_profile_, CudaExecutionProfile::kDeviceScaling);
  compact_layer_a_enabled_ = device_control_enabled_ && ProfileAtLeast(
      execution_profile_, CudaExecutionProfile::kCompactLayerA);
  compact_control_enabled_ = device_control_enabled_ && ProfileAtLeast(
      execution_profile_, CudaExecutionProfile::kCompactControl);
  const auto fits_uint32 = [](const size_t count) {
    return count <= std::numeric_limits<uint32_t>::max();
  };
  if (indexed_catalog != nullptr &&
      (!runtime_pool_enabled_ || !arena_enabled_ ||
       indexed_catalog->owner_epoch == 0 ||
       indexed_catalog->catalog_generation == 0 ||
       indexed_catalog->abi_version != kMapperStaticCatalogAbiVersion ||
       !fits_uint32(indexed_catalog->cameras.size()) ||
       !fits_uint32(indexed_catalog->images.size()) ||
       !fits_uint32(indexed_catalog->points.size()) ||
       !fits_uint32(indexed_catalog->observations.size()) ||
       !fits_uint32(indexed_catalog->image_incidences.size()) ||
       !fits_uint32(indexed_catalog->point_incidences.size()))) {
    *error = "indexed device catalog requires a bounded RuntimePool arena";
    initializing_ = false;
    return false;
  }
  if (indexed_catalog != nullptr) {
    DeviceCatalogLayoutSpec catalog_spec;
    if (!PlanPersistentDeviceCatalogLayout(
            *indexed_catalog, catalog_spec, &indexed_catalog_layout_, error)) {
      initializing_ = false;
      return false;
    }
    indexed_catalog_bound_ = true;
  }
  audit_mirror_enabled_ = audit_mirror_enabled;
  hot_kernel_implementation_ = hot_kernel_implementation;
  hessian_assembly_backend_ = hessian_assembly_backend;
  schur_contribution_backend_ = schur_contribution_backend;
  arithmetic_precision_ = arithmetic_precision;
  const bool mixed_precision =
      arithmetic_precision_ == CudaArithmeticPrecision::kFp32MixedStable;
  if (arithmetic_precision_ != CudaArithmeticPrecision::kFp64 &&
      !mixed_precision) {
    *error = "persistent device context precision is unsupported";
    initializing_ = false;
    return false;
  }
  if (mixed_precision &&
      (!device_control_enabled_ || !compact_control_enabled_ ||
       hessian_assembly_backend_ !=
           CudaHessianAssemblyBackend::kObservationSegmented ||
       hot_kernel_implementation_ != HotKernelImplementation::kTransformed ||
       schur_contribution_backend_ !=
           CudaSchurContributionBackend::kSegmentedTransformed)) {
    *error = "fp32_mixed requires device_control compact_control, "
             "observation_segmented Hessian, and transformed segmented Schur";
    initializing_ = false;
    return false;
  }
  runtime_->persistent_device.hessian_assembly_backend_effective =
      HessianAssemblyBackendName(hessian_assembly_backend_);
  runtime_->persistent_device.schur_contribution_backend_effective =
      SchurContributionBackendName(schur_contribution_backend_);
  runtime_->persistent_device.hot_kernel_optimized =
      hot_kernel_implementation_ == HotKernelImplementation::kOptimized;
  runtime_->persistent_device.hot_kernel_transformed =
      hot_kernel_implementation_ == HotKernelImplementation::kTransformed;
  if (schur_contribution_backend_ ==
      CudaSchurContributionBackend::kSegmentedTransformed) {
    runtime_->persistent_device.schur_segment_plan_builds = 1;
    runtime_->persistent_device.schur_segment_size = layer_c.segment_size;
    runtime_->persistent_device.direct_pair_count =
        layer_c.segment_direct_pair_indices.size();
    runtime_->persistent_device.segmented_pair_count =
        layer_c.pairs.size() - layer_c.segment_direct_pair_indices.size();
    runtime_->persistent_device.segment_count = layer_c.segments.size();
    runtime_->persistent_device.max_segments_per_pair =
        layer_c.max_segments_per_pair;
    runtime_->persistent_device.schur_partial_workspace_bytes =
        layer_c.segment_partial_workspace_bytes;
    runtime_->persistent_device.schur_segment_metadata_h2d_bytes =
        layer_c.segment_direct_pair_indices.size() * sizeof(uint32_t) +
        layer_c.segments.size() * sizeof(DeviceSchurSegment) +
        layer_c.segment_pair_ranges.size() *
            sizeof(DeviceSchurPairSegmentRange);
  }
  device_ = options.layer_a.device;
  memory_mode_ = options.layer_a.memory_mode;
  solve_generation_ = solve_generation;
  topology_generation_ = topology_generation;
  layout_id_ = cost_layout.layout_id;
  visual_count_ = initial.visual.size();
  lidar_count_ = initial.lidar.size();
  pose_count_ = layer_b.poses.size();
  point_count_ = layer_b.points.size();
  edge_count_ = layer_b.edges.size();
  pose_assembly_segment_count_ = layer_b.pose_segments.size();
  point_assembly_segment_count_ = layer_b.point_segments.size();
  edge_assembly_segment_count_ = layer_b.edge_segments.size();
  point_assembly_direct_count_ = layer_b.point_direct_indices.size();
  hessian_segment_size_ = layer_b.hessian_segment_size;
  if (hessian_assembly_backend_ ==
      CudaHessianAssemblyBackend::kObservationAtomic) {
    if (layer_b.atomic_visual_bindings.size() != visual_count_ ||
        layer_b.atomic_lidar_bindings.size() != lidar_count_) {
      *error = "observation atomic binding coverage is incomplete";
      initializing_ = false;
      return false;
    }
    uint64_t pose_atomics = 0;
    uint64_t point_atomics = 0;
    uint64_t edge_atomics = 0;
    for (const DeviceVisualAssemblyBinding& binding :
         layer_b.atomic_visual_bindings) {
      if (binding.pose_index != kInvalidAssemblyTarget) {
        const uint64_t dimension = layer_b.poses[binding.pose_index].dimension;
        pose_atomics = SaturatingAdd(
            pose_atomics, 2 * (dimension * dimension + dimension));
      }
      if (binding.point_index != kInvalidAssemblyTarget)
        point_atomics = SaturatingAdd(point_atomics, 24);
      if (binding.edge_index != kInvalidAssemblyTarget) {
        const DeviceEdgeMeta& edge = layer_b.edges[binding.edge_index];
        if (edge.adjacency_end - edge.adjacency_begin > 1) {
          edge_atomics =
              SaturatingAdd(edge_atomics, 2 * edge.pose_dimension * 3);
        }
      }
    }
    for (const DeviceLidarAssemblyBinding& binding :
         layer_b.atomic_lidar_bindings) {
      if (binding.point_index != kInvalidAssemblyTarget)
        point_atomics = SaturatingAdd(point_atomics, 12);
    }
    runtime_->persistent_device.atomic_add_estimate_pose = pose_atomics;
    runtime_->persistent_device.atomic_add_estimate_point = point_atomics;
    runtime_->persistent_device.atomic_add_estimate_edge = edge_atomics;
    runtime_->persistent_device.hessian_candidate_metadata_h2d_bytes =
        layer_b.atomic_visual_bindings.size() *
            sizeof(DeviceVisualAssemblyBinding) +
        layer_b.atomic_lidar_bindings.size() *
            sizeof(DeviceLidarAssemblyBinding);
  }
  if (hessian_assembly_backend_ ==
      CudaHessianAssemblyBackend::kObservationSegmented) {
    if (layer_b.pose_segment_ranges.size() != pose_count_ ||
        layer_b.point_segment_ranges.size() != point_count_ ||
        !layer_b.edge_segment_ranges.empty() ||
        !layer_b.edge_segments.empty() ||
        hessian_segment_size_ == 0) {
      *error = "observation segmented coverage metadata is incomplete";
      ++runtime_->persistent_device.hessian_assembly_coverage_violations;
      initializing_ = false;
      return false;
    }
    uint64_t pose_bytes = 0;
    uint64_t point_bytes = 0;
    uint64_t edge_bytes = 0;
    const uint64_t pose_partial_stride = mixed_precision
        ? 36 * sizeof(float)
        : kPoseAssemblyPartialScalars * sizeof(double);
    const uint64_t point_partial_stride = mixed_precision
        ? sizeof(MixedPointAssemblyPartial)
        : kPointAssemblyPartialScalars * sizeof(double);
    const uint64_t edge_partial_stride = mixed_precision
        ? 0
        : kEdgeAssemblyPartialScalars * sizeof(double);
    if (!CheckedMultiply(pose_assembly_segment_count_, pose_partial_stride,
                         &pose_bytes) ||
        !CheckedMultiply(point_assembly_segment_count_, point_partial_stride,
                         &point_bytes) ||
        !CheckedMultiply(edge_assembly_segment_count_, edge_partial_stride,
                         &edge_bytes) ||
        pose_bytes > std::numeric_limits<uint64_t>::max() - point_bytes ||
        pose_bytes + point_bytes >
            std::numeric_limits<uint64_t>::max() - edge_bytes) {
      *error = "observation segmented partial workspace size overflow";
      initializing_ = false;
      return false;
    }
    runtime_->persistent_device.hessian_segment_count_pose =
        pose_assembly_segment_count_;
    runtime_->persistent_device.hessian_segment_count_point =
        point_assembly_segment_count_;
    runtime_->persistent_device.hessian_segment_count_edge =
        edge_assembly_segment_count_;
    runtime_->persistent_device.hessian_segment_size = hessian_segment_size_;
    runtime_->persistent_device.hessian_partial_workspace_bytes =
        pose_bytes + point_bytes + edge_bytes;
    runtime_->persistent_device.hessian_candidate_metadata_h2d_bytes =
        layer_b.pose_segments.size() * sizeof(DeviceAssemblySegment) +
        layer_b.point_segments.size() * sizeof(DeviceAssemblySegment) +
        layer_b.edge_segments.size() * sizeof(DeviceAssemblySegment) +
        layer_b.point_direct_indices.size() * sizeof(uint32_t) +
        layer_b.pose_segment_ranges.size() *
            sizeof(DeviceAssemblyTargetRange) +
        layer_b.point_segment_ranges.size() *
            sizeof(DeviceAssemblyTargetRange) +
        layer_b.edge_segment_ranges.size() *
            sizeof(DeviceAssemblyTargetRange);
  }
  cost_count_ = cost_layout.entries.size();
  image_entity_count_ = native_initialization
      ? native->image_slots.size() : legacy_initial_snapshot->images.size();
  point_entity_count_ = native_initialization
      ? native->point_slots.size() : legacy_initial_snapshot->points.size();
  camera_entity_count_ = native_initialization
      ? native->camera_slots.size() : legacy_initial_snapshot->cameras.size();
  gradient_slots_ = pose_count_ + point_count_;
  pose_dimension_ = layer_c.pose_dimension;
  schur_elements_ = pose_dimension_ * pose_dimension_;
  uint64_t identity = 1469598103934665603ull;
  HashTag(&identity, 0x5045525349535445ull);
  HashWord(&identity, solve_generation_);
  HashWord(&identity, topology_generation_);
  HashWord(&identity, layout_id_);
  HashWord(&identity, static_cast<uint64_t>(device_));
  HashWord(&identity, static_cast<uint64_t>(arithmetic_precision_));
  context_identity_ = identity == 0 ? 1 : identity;
  runtime_->persistent_device.context_identity = context_identity_;
  runtime_->persistent_device.execution_profile = execution_profile_;
  runtime_->persistent_device.public_visual_record_bytes =
      sizeof(CudaVisualOutput);

  try {
    allocations_.reserve(80);
    if (!device_state_enabled_) {
      host_visual_dynamic_.resize(visual_count_);
      host_lidar_dynamic_.resize(lidar_count_);
    }
    host_image_entities_.resize(image_entity_count_);
    host_point_entities_.resize(point_entity_count_);
    host_camera_entities_.resize(camera_entity_count_);
  } catch (const std::exception& exception) {
    *error = std::string("persistent host capacity allocation failed: ") +
             exception.what();
    initializing_ = false;
    return false;
  }

  cudaError_t cuda_status = cudaSetDevice(device_);
  if (cuda_status != cudaSuccess) {
    *error = std::string("persistent cudaSetDevice failed: ") +
             CudaErrorText(cuda_status);
    initializing_ = false;
    return false;
  }
  CudaCacheKey key;
  if (!CurrentCudaCacheKey(&key) || !key.valid || key.device != device_) {
    *error = "persistent CUDA device/context identity query failed";
    initializing_ = false;
    return false;
  }

  cusolverStatus_t solver_status = CUSOLVER_STATUS_SUCCESS;
  cublasStatus_t blas_status = CUBLAS_STATUS_SUCCESS;
  if (runtime_pool_enabled_) {
    if (!AcquireRuntimePoolLease(device_, &runtime_->persistent_device,
                                 &runtime_pool_lease_, error)) {
      initializing_ = false;
      return false;
    }
    CudaRuntimePoolEntry& pooled = *runtime_pool_lease_.entry;
    if (!indexed_catalog_bound_ && pooled.persistent_device_catalog.valid()) {
      pooled.persistent_device_catalog.Invalidate();
      ++runtime_->persistent_device.indexed_device_catalog_invalidations;
    }
    stream_ = pooled.stream;
    events_ = pooled.events;
    solver_ = pooled.solver;
    blas_ = pooled.blas;
    uint64_t pooled_identity = context_identity_;
    HashWord(&pooled_identity, runtime_pool_lease_.generation);
    HashWord(&pooled_identity, pooled.key.context);
    context_identity_ = pooled_identity == 0 ? 1 : pooled_identity;
    runtime_->persistent_device.context_identity = context_identity_;
    if (!runtime_pool_lease_.hot) {
      runtime_->persistent_device.init_stream_create_count = 1;
      runtime_->persistent_device.init_event_create_count = events_.size();
      runtime_->persistent_device.init_solver_create_count = 1;
      runtime_->persistent_device.init_blas_create_count = 1;
    }
  } else {
    cuda_status = cudaStreamCreateWithFlags(&stream_, cudaStreamNonBlocking);
    if (cuda_status != cudaSuccess ||
        !RegisterCudaResource(reinterpret_cast<uintptr_t>(stream_),
                              CudaTeardownType::kStream, device_)) {
      if (cuda_status == cudaSuccess)
        CleanupCudaStreamDestroy(stream_, device_);
      stream_ = nullptr;
      *error = "persistent CUDA stream creation failed";
      initializing_ = false;
      return false;
    }
    ++runtime_->persistent_device.init_stream_create_count;
    for (cudaEvent_t& event : events_) {
      cuda_status = AuditCudaEventCreate(&event);
      if (cuda_status != cudaSuccess ||
          !RegisterCudaResource(reinterpret_cast<uintptr_t>(event),
                                CudaTeardownType::kEvent, device_)) {
        if (cuda_status == cudaSuccess)
          CleanupCudaEventDestroy(event, device_);
        event = nullptr;
        *error = "persistent CUDA event creation failed";
        initializing_ = false;
        Close(nullptr);
        return false;
      }
      ++runtime_->persistent_device.init_event_create_count;
    }
    solver_status = cusolverDnCreate(&solver_);
    if (solver_status != CUSOLVER_STATUS_SUCCESS ||
        !RegisterCudaResource(reinterpret_cast<uintptr_t>(solver_),
                              CudaTeardownType::kSolver, device_)) {
