      *error = "persistent cuBLAS creation failed";
      initializing_ = false;
      Close(nullptr);
      return false;
    }
    ++runtime_->persistent_device.init_blas_create_count;
    solver_status = cusolverDnSetStream(solver_, stream_);
    blas_status = cublasSetStream(blas_, stream_);
    if (solver_status != CUSOLVER_STATUS_SUCCESS ||
        blas_status != CUBLAS_STATUS_SUCCESS) {
      *error = "persistent CUDA handle stream binding failed";
