      AllocatePersistent(&d_edge_assembly_segments_,
                         hessian_assembly_backend_ ==
                                 CudaHessianAssemblyBackend::kObservationSegmented
                             ? layer_b.edge_segments.size() : 0, error) &&
      AllocatePersistent(&d_pose_assembly_ranges_,
                         hessian_assembly_backend_ ==
