        solver_, CUBLAS_FILL_MODE_LOWER, static_cast<int>(pose_dimension_),
        query_factor, static_cast<int>(pose_dimension_), &workspace_count);
    if (solver_status != CUSOLVER_STATUS_SUCCESS || workspace_count < 0) {
      *error = "persistent cusolverDnDpotrf_bufferSize failed";
