      const PointSnapshot& point = legacy_initial_snapshot->points[i];
      if (!point_indices.emplace(point.point3D_id,
                                 static_cast<uint32_t>(i)).second) {
        *error = "device-state layout contains a duplicate point id";
        initializing_ = false;
        Close(nullptr);
        return false;
      }
      for (size_t j = 0; j < 3; ++j)
        host_point_entities_[i].xyz[j] = point.xyz[j];
    }
    for (size_t i = 0; i < camera_entity_count_; ++i) {
      const CameraSnapshot& camera = legacy_initial_snapshot->cameras[i];
      if (!camera_indices.emplace(camera.camera_id,
                                  static_cast<uint32_t>(i)).second ||
          camera.model_id != kOpenCvcCameraModelId || camera.params.size() != 8) {
        *error = "device-state layout requires unique 8-parameter OPENCV cameras";
        initializing_ = false;
        Close(nullptr);
        return false;
      }
      for (size_t j = 0; j < 8; ++j)
        host_camera_entities_[i].params[j] = camera.params[j];
    }
  } else {
    const auto graph_cameras = native_view->catalog.cameras();
    const auto graph_images = native_view->catalog.images();
    const auto graph_points = native_view->catalog.points();
    std::unordered_map<uint32_t, const DenseCameraState*> camera_state;
    std::unordered_map<uint32_t, const DenseImageState*> image_state;
    std::unordered_map<uint32_t, const DensePointState*> point_state;
    if (!BuildNativeStateLookup(native_initial_state->cameras,
                                native_initial_state->state_generation,
                                &camera_state, error) ||
        !BuildNativeStateLookup(native_initial_state->images,
                                native_initial_state->state_generation,
                                &image_state, error) ||
        !BuildNativeStateLookup(native_initial_state->points,
                                native_initial_state->state_generation,
                                &point_state, error)) {
      initializing_ = false;
      Close(nullptr);
      return false;
    }
    native_camera_slots_ = native->camera_slots;
    native_image_slots_ = native->image_slots;
    native_point_slots_ = native->point_slots;
    for (size_t i = 0; i < native_image_slots_.size(); ++i) {
      const uint32_t slot = native_image_slots_[i];
      const auto state = image_state.find(slot);
      if (slot >= graph_images.size || state == image_state.end() ||
          !image_indices.emplace(graph_images[slot].image_id,
                                 static_cast<uint32_t>(i)).second) {
        *error = "native device image entity layout is invalid";
        initializing_ = false;
        Close(nullptr);
        return false;
      }
      std::copy(state->second->quaternion.begin(),
                state->second->quaternion.end(),
                host_image_entities_[i].quaternion);
      std::copy(state->second->translation.begin(),
                state->second->translation.end(),
                host_image_entities_[i].translation);
    }
    for (size_t i = 0; i < native_point_slots_.size(); ++i) {
      const uint32_t slot = native_point_slots_[i];
      const auto state = point_state.find(slot);
      if (slot >= graph_points.size || state == point_state.end() ||
          !point_indices.emplace(graph_points[slot].point3D_id,
                                 static_cast<uint32_t>(i)).second) {
        *error = "native device point entity layout is invalid";
        initializing_ = false;
        Close(nullptr);
        return false;
      }
      std::copy(state->second->xyz.begin(), state->second->xyz.end(),
                host_point_entities_[i].xyz);
    }
    for (size_t i = 0; i < native_camera_slots_.size(); ++i) {
      const uint32_t slot = native_camera_slots_[i];
      const auto state = camera_state.find(slot);
      if (slot >= graph_cameras.size || state == camera_state.end() ||
          graph_cameras[slot].model_id != kOpenCvcCameraModelId ||
          state->second->parameters.size() != 8 ||
          !camera_indices.emplace(graph_cameras[slot].camera_id,
                                  static_cast<uint32_t>(i)).second) {
        *error = "native device camera entity layout is invalid";
        initializing_ = false;
        Close(nullptr);
        return false;
      }
      std::copy(state->second->parameters.begin(),
                state->second->parameters.end(),
                host_camera_entities_[i].params);
    }
  }
  for (size_t i = 0; i < visual_count_; ++i) {
    visual_static[i].source_index = initial.visual[i].source_index;
    visual_static[i].image_id = initial.visual[i].image_id;
    visual_static[i].point3D_id = initial.visual[i].point3D_id;
    const auto image_it = image_indices.find(initial.visual[i].image_id);
    const auto point_it = point_indices.find(initial.visual[i].point3D_id);
    if (image_it == image_indices.end() || point_it == point_indices.end()) {
      *error = "device-state visual binding references a missing entity";
      initializing_ = false;
      Close(nullptr);
      return false;
    }
    const uint32_t camera_id = native_initialization
        ? native_view->catalog.cameras()[
              native->image_camera_slots[image_it->second]]
              .camera_id
        : legacy_initial_snapshot->images[image_it->second].camera_id;
    const auto camera_it = camera_indices.find(camera_id);
    if (camera_it == camera_indices.end()) {
      *error = "device-state visual binding references a missing camera";
      initializing_ = false;
      Close(nullptr);
      return false;
    }
    visual_static[i].image_entity_index = image_it->second;
    visual_static[i].point_entity_index = point_it->second;
    visual_static[i].camera_entity_index = camera_it->second;
    visual_static[i].observation[0] = initial.visual[i].observation[0];
    visual_static[i].observation[1] = initial.visual[i].observation[1];
  }
  std::vector<DeviceLidarStaticInput> lidar_static(lidar_count_);
  for (size_t i = 0; i < lidar_count_; ++i) {
    lidar_static[i].source_index = initial.lidar[i].source_index;
    lidar_static[i].point3D_id = initial.lidar[i].point3D_id;
    const auto point_it = point_indices.find(initial.lidar[i].point3D_id);
    if (point_it == point_indices.end()) {
      *error = "device-state LiDAR binding references a missing point";
      initializing_ = false;
      Close(nullptr);
      return false;
    }
    lidar_static[i].point_entity_index = point_it->second;
    for (size_t j = 0; j < 4; ++j)
      lidar_static[i].plane[j] = initial.lidar[i].plane[j];
    lidar_static[i].weight = initial.lidar[i].weight;
    lidar_static[i].mode = initial.lidar[i].mode;
    lidar_static[i].near_zero_threshold = initial.lidar[i].near_zero_threshold;
  }
  std::vector<DeviceImageUpdateMeta> image_update(image_entity_count_);
  for (DeviceImageUpdateMeta& meta : image_update) {
    meta.variable_pose_index = -1;
    meta.delta_offset = 0;
    meta.dimension = 0;
    for (int32_t& value : meta.free_translation_indices) value = -1;
  }
  std::vector<uint32_t> pose_image_indices(pose_count_);
  for (size_t i = 0; i < pose_count_; ++i) {
    const auto image_it = image_indices.find(layer_b.poses[i].image_id);
    if (image_it == image_indices.end() || i >= layer_c.poses.size() ||
        layer_c.poses[i].dimension != layer_b.poses[i].dimension ||
        static_cast<uint64_t>(layer_c.poses[i].offset) +
                layer_b.poses[i].dimension >
            layer_c.pose_dimension) {
      *error = "device-state pose update mapping is incomplete";
      initializing_ = false;
      Close(nullptr);
      return false;
    }
    pose_image_indices[i] = image_it->second;
    DeviceImageUpdateMeta& meta = image_update[image_it->second];
    meta.variable_pose_index = static_cast<int32_t>(i);
    meta.delta_offset = layer_c.poses[i].offset;
    meta.dimension = layer_b.poses[i].dimension;
    for (size_t j = 0; j < 3; ++j)
      meta.free_translation_indices[j] =
          layer_b.poses[i].free_translation_indices[j];
  }
  std::vector<DevicePointUpdateMeta> point_update(point_entity_count_);
  std::vector<uint32_t> point_entity_indices(point_count_);
  for (DevicePointUpdateMeta& meta : point_update)
    meta.variable_point_index = -1;
  for (size_t i = 0; i < point_count_; ++i) {
    const auto point_it = point_indices.find(layer_b.points[i].point3D_id);
    if (point_it == point_indices.end()) {
      *error = "device-state point update mapping is incomplete";
      initializing_ = false;
      Close(nullptr);
      return false;
    }
    point_update[point_it->second].variable_point_index =
        static_cast<int32_t>(i);
    point_entity_indices[i] = point_it->second;
  }
  const bool uploaded =
      UploadStatic(d_visual_static_, visual_static, error) &&
      UploadStatic(d_lidar_static_, lidar_static, error) &&
      UploadStatic(d_camera_entities_, host_camera_entities_, error) &&
      UploadStatic(d_image_update_meta_, image_update, error) &&
      UploadStatic(d_point_update_meta_, point_update, error) &&
      UploadStatic(d_pose_image_entity_indices_, pose_image_indices, error) &&
      UploadStatic(d_point_entity_indices_, point_entity_indices, error) &&
      UploadStatic(d_cost_order_, cost_layout.entries, error) &&
      UploadStatic(d_pose_meta_, layer_b.poses, error) &&
      UploadStatic(d_point_meta_, layer_b.points, error) &&
      UploadStatic(d_edge_meta_, layer_b.edges, error) &&
      UploadStatic(d_pose_adjacency_, layer_b.pose_adjacency, error) &&
      UploadStatic(d_point_adjacency_, layer_b.point_adjacency, error) &&
      UploadStatic(d_edge_adjacency_, layer_b.edge_adjacency, error) &&
      UploadStatic(d_atomic_visual_bindings_,
                   layer_b.atomic_visual_bindings, error) &&
      UploadStatic(d_atomic_lidar_bindings_,
                   layer_b.atomic_lidar_bindings, error) &&
      UploadStatic(d_pose_assembly_segments_, layer_b.pose_segments, error) &&
      UploadStatic(d_point_assembly_segments_, layer_b.point_segments, error) &&
      UploadStatic(d_edge_assembly_segments_, layer_b.edge_segments, error) &&
      UploadStatic(d_pose_assembly_ranges_,
                   layer_b.pose_segment_ranges, error) &&
      UploadStatic(d_point_assembly_ranges_,
                   layer_b.point_segment_ranges, error) &&
      UploadStatic(d_edge_assembly_ranges_,
                   layer_b.edge_segment_ranges, error) &&
      UploadStatic(d_point_assembly_direct_indices_,
                   layer_b.point_direct_indices, error) &&
      UploadStatic(d_solve_pose_meta_, layer_c.poses, error) &&
      UploadStatic(d_solve_point_meta_, layer_c.points, error) &&
      UploadStatic(d_pair_meta_, layer_c.pairs, error) &&
      UploadStatic(d_pair_contributions_, layer_c.pair_contributions, error) &&
      UploadStatic(d_segment_direct_pair_indices_,
                   layer_c.segment_direct_pair_indices, error) &&
      UploadStatic(d_schur_segments_, layer_c.segments, error) &&
      UploadStatic(d_schur_pair_segment_ranges_,
                   layer_c.segment_pair_ranges, error) &&
      UploadStatic(d_pose_edges_, layer_c.pose_edges, error) &&
      UploadStatic(d_point_edges_, layer_c.point_edges, error);
  if (!uploaded) {
    initializing_ = false;
    Close(nullptr);
    return false;
  }
  if (device_state_enabled_) {
    runtime_->persistent_device.static_problem_layout_builds = 1;
    runtime_->persistent_device.initial_entity_state_pack_calls = 1;
    runtime_->persistent_device.initial_entity_state_pack_bytes =
        image_entity_count_ * sizeof(DeviceImageEntityState) +
        point_entity_count_ * sizeof(DevicePointEntityState);
    const auto upload_initial = [&](auto* destination, const auto& source) {
      if (source.empty()) return true;
      const uint64_t bytes = source.size() * sizeof(source[0]);
      HostPhaseScope timing(CUDA_TIMING_PHASE(h2d_memcpy), bytes);
      const cudaError_t status = cudaMemcpyAsync(
          destination, source.data(), bytes, cudaMemcpyHostToDevice, stream_);
      if (status != cudaSuccess) return false;
      ++runtime_->persistent_device.initial_entity_state_upload_calls;
      runtime_->persistent_device.initial_entity_state_upload_bytes =
          SaturatingAdd(
              runtime_->persistent_device.initial_entity_state_upload_bytes,
              bytes);
      return true;
    };
    if (!upload_initial(state_slots_[current_state_slot_].images,
                        host_image_entities_) ||
        !upload_initial(state_slots_[current_state_slot_].points,
                        host_point_entities_)) {
      *error = "device-state initial entity upload failed";
      initializing_ = false;
      Close(nullptr);
      return false;
    }
    StateSlot& current_state = state_slots_[current_state_slot_];
    current_state.identity.linearization.solve_generation = solve_generation_;
    current_state.identity.linearization.state_epoch = 0;
    current_state.identity.linearization.topology_generation =
        topology_generation_;
    current_state.identity.linearization.config_generation = 0;
    current_state.identity.context_identity = context_identity_;
    current_state.identity.layout_id = layout_id_;
    current_state.identity.slot_generation = ++next_slot_generation_;
    current_state.identity.arithmetic_precision = arithmetic_precision_;
    current_state.identity.kind = PersistentSlotKind::kStateCurrent;
    current_state.identity.valid = true;
  }
  if (!Synchronize(CudaSyncSite::kResourceRelease, error)) {
    initializing_ = false;
    Close(nullptr);
    return false;
  }
  initializing_ = false;
  initialized_ = true;
  runtime_->persistent_device.effective = true;
  runtime_->persistent_device.peak_resident_bytes = std::max(
      runtime_->persistent_device.peak_resident_bytes,
      runtime_->persistent_device.initialization_allocation_bytes);
  return true;
}

bool GpuBaDeviceContext::FinalizeConfig(const uint64_t config_generation,
                                        std::string* error) noexcept {
  if (!initialized_ || config_generation == 0) {
    if (error != nullptr) *error = "persistent config identity is invalid";
    return false;
  }
  if (config_generation_ != 0 && config_generation_ != config_generation) {
    if (error != nullptr) *error = "persistent config identity changed";
    return false;
  }
  config_generation_ = config_generation;
  for (LayerBSlot& slot : layer_b_slots_) {
    if (slot.identity.valid &&
        slot.identity.linearization.config_generation == 0) {
      slot.identity.linearization.config_generation = config_generation;
    }
    if (slot.source_state_identity.valid &&
        slot.source_state_identity.linearization.config_generation == 0) {
      slot.source_state_identity.linearization.config_generation =
          config_generation;
    }
  }
  for (StateSlot& slot : state_slots_) {
    if (slot.identity.valid &&
        slot.identity.linearization.config_generation == 0) {
      slot.identity.linearization.config_generation = config_generation;
    }
  }
  state_ready_ = device_state_enabled_;
  return true;
}

bool GpuBaDeviceContext::UploadFrozenScaling(
    const CudaLayerBOptions& options,
    std::string* error) {
  if (!initialized_ || frozen_scaling_uploaded_ || error == nullptr ||
      options.frozen_pose_jacobi_scaling.size() != pose_count_ * 6 ||
      options.frozen_point_jacobi_scaling.size() != point_count_ * 3) {
    if (error != nullptr) *error = "persistent frozen scaling upload is invalid";
    return false;
  }
  const uint64_t before_calls =
      runtime_->persistent_device.dynamic_state_upload_calls;
  const uint64_t before_bytes =
      runtime_->persistent_device.dynamic_state_upload_bytes;
  if (!UploadDynamic(d_frozen_pose_scaling_,
                     options.frozen_pose_jacobi_scaling, error) ||
      !UploadDynamic(d_frozen_point_scaling_,
                     options.frozen_point_jacobi_scaling, error) ||
      !Synchronize(CudaSyncSite::kResourceRelease, error)) {
    return false;
  }
  runtime_->persistent_device.frozen_scaling_upload_calls =
      runtime_->persistent_device.dynamic_state_upload_calls - before_calls;
  runtime_->persistent_device.frozen_scaling_upload_bytes =
      runtime_->persistent_device.dynamic_state_upload_bytes - before_bytes;
  runtime_->persistent_device.dynamic_state_upload_calls = before_calls;
  runtime_->persistent_device.dynamic_state_upload_bytes = before_bytes;
  frozen_scaling_uploaded_ = true;
  return true;
}

bool GpuBaDeviceContext::PublishFrozenScalingFromInitial(
    const CudaDeviceLinearizationToken& token,
    const CudaLinearizationIdentity& identity,
    std::string* error) {
  if (!initialized_ || !device_scaling_enabled_ ||
      frozen_scaling_uploaded_ || error == nullptr) {
    if (error != nullptr)
      *error = "device frozen scaling publication is invalid";
    return false;
  }
  DeviceLayerBView initial = LayerBViewFromToken(token, identity, error);
  if (!initial.identity.valid) return false;
  constexpr int kBlockSize = 128;
  if (pose_count_ != 0) {
    const size_t count = pose_count_ * 6;
    PublishPoseJacobiScalingKernel<<<
        static_cast<unsigned>((count + kBlockSize - 1) / kBlockSize),
        kBlockSize, 0, stream_>>>(initial.poses, d_frozen_pose_scaling_,
                                  pose_count_);
    ++runtime_->persistent_device.scaling_d2d_calls;
    runtime_->persistent_device.scaling_d2d_bytes = SaturatingAdd(
        runtime_->persistent_device.scaling_d2d_bytes,
        count * sizeof(double));
  }
  if (point_count_ != 0) {
    const size_t count = point_count_ * 3;
    PublishPointJacobiScalingKernel<<<
        static_cast<unsigned>((count + kBlockSize - 1) / kBlockSize),
        kBlockSize, 0, stream_>>>(initial.points, d_frozen_point_scaling_,
                                  point_count_);
    ++runtime_->persistent_device.scaling_d2d_calls;
    runtime_->persistent_device.scaling_d2d_bytes = SaturatingAdd(
        runtime_->persistent_device.scaling_d2d_bytes,
        count * sizeof(double));
  }
  const cudaError_t status = cudaGetLastError();
  if (status != cudaSuccess ||
      !Synchronize(CudaSyncSite::kResourceRelease, error)) {
    if (error->empty()) {
      *error = std::string("device frozen scaling publication failed: ") +
               CudaErrorText(status);
    }
    return false;
  }
  frozen_scaling_uploaded_ = true;
  ++runtime_->persistent_device.scaling_slot_publishes;
  return true;
}

bool GpuBaDeviceContext::Synchronize(const CudaSyncSite site,
                                     std::string* error) {
  const cudaError_t status = TimedCudaStreamSynchronize(stream_, site);
  if (status != cudaSuccess) {
    if (error != nullptr)
      *error = std::string("persistent CUDA synchronization failed: ") +
               CudaErrorText(status);
    return false;
  }
  return true;
}

double GpuBaDeviceContext::EventElapsed(const size_t begin,
                                        const size_t end) noexcept {
  if (begin >= events_.size() || end >= events_.size()) return 0.0;
  float elapsed = 0.0f;
  if (AuditCudaEventElapsedTime(&elapsed, events_[begin], events_[end]) !=
      cudaSuccess) {
    return 0.0;
  }
  return static_cast<double>(elapsed);
}

void GpuBaDeviceContext::InvalidateLayerASlot(const size_t index) noexcept {
  if (index >= layer_a_slots_.size()) return;
  ++layer_a_slots_[index].identity.slot_generation;
  layer_a_slots_[index].identity.valid = false;
  ++runtime_->persistent_device.slot_invalidate_count;
}

void GpuBaDeviceContext::InvalidateLayerBSlot(const size_t index) noexcept {
  if (index >= layer_b_slots_.size()) return;
  ++layer_b_slots_[index].identity.slot_generation;
  layer_b_slots_[index].identity.valid = false;
  ++runtime_->persistent_device.slot_invalidate_count;
}

void GpuBaDeviceContext::InvalidateStateSlot(const size_t index) noexcept {
  if (index >= state_slots_.size()) return;
  ++state_slots_[index].identity.slot_generation;
  state_slots_[index].identity.valid = false;
  ++runtime_->persistent_device.state_slot_invalidate_count;
}

size_t GpuBaDeviceContext::SelectLayerBSlot(
    const CudaFaultLogicalSite site) noexcept {
  if (site == CudaFaultLogicalSite::kInitialLinearization) {
    return current_b_slot_;
  }
  return pending_b_slot_;
}

void GpuBaDeviceContext::PublishInitial(
    const CudaLinearizationIdentity& identity) noexcept {
  LayerBSlot& slot = layer_b_slots_[current_b_slot_];
  bool valid = slot.identity.valid &&
      slot.identity.arithmetic_precision == arithmetic_precision_ &&
      SameLinearizationIdentity(slot.identity.linearization, identity);
  if (device_state_enabled_) {
    StateSlot& state = state_slots_[current_state_slot_];
    valid = valid && state.identity.valid &&
            state.identity.arithmetic_precision == arithmetic_precision_ &&
            SameLinearizationIdentity(state.identity.linearization, identity) &&
            slot.source_state_identity.slot_generation ==
                state.identity.slot_generation;
    ++runtime_->persistent_device.state_b_pair_checks;
    if (!valid) ++runtime_->persistent_device.state_b_pair_violations;
    if (valid) {
      state.identity.kind = PersistentSlotKind::kStateCurrent;
      ++runtime_->persistent_device.state_slot_publish_count;
    }
  }
  if (valid) {
    latest_b_slot_ = current_b_slot_;
    slot.identity.kind = PersistentSlotKind::kLinearizationCurrent;
    ++runtime_->persistent_device.slot_publish_count;
  }
}

bool GpuBaDeviceContext::PrepareCommitToken(
    const CudaLinearizationIdentity& identity,
    DeviceCommitToken* token,
    std::string* error) noexcept {
  if (token == nullptr) return false;
  *token = DeviceCommitToken();
  ++runtime_->persistent_device.commit_token_checks;
  LayerBSlot& pending = layer_b_slots_[pending_b_slot_];
  bool valid = pending.identity.valid &&
      pending.identity.arithmetic_precision == arithmetic_precision_ &&
      SameLinearizationIdentity(pending.identity.linearization, identity);
  if (device_state_enabled_) {
    StateSlot& trial = state_slots_[trial_state_slot_];
    valid = valid && trial.identity.valid &&
            trial.identity.arithmetic_precision == arithmetic_precision_ &&
            SameLinearizationIdentity(trial.identity.linearization, identity) &&
            pending.source_state_identity.slot_generation ==
                trial.identity.slot_generation;
    ++runtime_->persistent_device.state_b_pair_checks;
    if (!valid) ++runtime_->persistent_device.state_b_pair_violations;
  }
  if (!valid) {
    ++runtime_->persistent_device.stale_handle_reject_count;
    ++runtime_->persistent_device.commit_token_violations;
    if (error != nullptr) *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
    return false;
  }
  token->valid = true;
  token->context_identity = context_identity_;
  token->arithmetic_precision = arithmetic_precision_;
  token->identity = identity;
  token->pending_b_slot = pending_b_slot_;
  token->pending_b_generation = pending.identity.slot_generation;
  token->trial_state_slot = trial_state_slot_;
  token->trial_state_generation = device_state_enabled_
      ? state_slots_[trial_state_slot_].identity.slot_generation : 0;
  return true;
}

void GpuBaDeviceContext::CommitPending(
    DeviceCommitToken&& token) noexcept {
  // PrepareCommitToken has already validated every identity and generation.
  // This function is deliberately limited to no-fail ownership changes.
  assert(token.valid && token.context_identity == context_identity_ &&
         token.arithmetic_precision == arithmetic_precision_);
  assert(token.pending_b_slot < layer_b_slots_.size());
  assert(layer_b_slots_[token.pending_b_slot].identity.slot_generation ==
         token.pending_b_generation);
  if (device_state_enabled_) {
    assert(token.trial_state_slot < state_slots_.size());
    assert(state_slots_[token.trial_state_slot].identity.slot_generation ==
           token.trial_state_generation);
    const size_t old_current_state = current_state_slot_;
    current_state_slot_ = token.trial_state_slot;
    trial_state_slot_ = old_current_state;
    state_slots_[current_state_slot_].identity.kind =
        PersistentSlotKind::kStateCurrent;
    state_slots_[trial_state_slot_].identity.kind =
        PersistentSlotKind::kStateTrial;
    ++runtime_->persistent_device.state_slot_swap_count;
    ++runtime_->persistent_device.state_slot_publish_count;
  }
  const size_t old_current_b = current_b_slot_;
  current_b_slot_ = token.pending_b_slot;
  pending_b_slot_ = old_current_b;
  latest_b_slot_ = current_b_slot_;
  layer_b_slots_[current_b_slot_].identity.kind =
      PersistentSlotKind::kLinearizationCurrent;
  ++runtime_->persistent_device.slot_swap_count;
  ++runtime_->persistent_device.b_slot_swap_count;
  ++runtime_->persistent_device.slot_publish_count;
  token.valid = false;
}

void GpuBaDeviceContext::DiscardBuild(
    const CudaFaultLogicalSite site) noexcept {
  InvalidateLayerBSlot(SelectLayerBSlot(site));
}

void GpuBaDeviceContext::DiscardTrialState() noexcept {
  if (!device_state_enabled_) return;
  if (state_slots_[trial_state_slot_].identity.valid) {
    InvalidateStateSlot(trial_state_slot_);
    ++runtime_->persistent_device.state_slot_discard_count;
  }
  InvalidateLayerASlot(1);
}

bool GpuBaDeviceContext::Close(std::string* error) noexcept {
  if (closed_) {
    const bool success = runtime_ == nullptr ||
                         runtime_->persistent_device.close_succeeded;
    if (!success && error != nullptr && error->empty())
      *error = "ResourceCleanup: persistent CUDA context close failed";
    return success;
  }
  closed_ = true;
  if (device_ >= 0) cudaSetDevice(device_);
  if (runtime_pool_enabled_ && runtime_pool_lease_.entry != nullptr) {
    bool healthy = g_cuda_resource_health == CudaResourceHealth::kClean &&
                   !runtime_pool_lease_.entry->externally_cleared;
    if (initializing_ && stream_ != nullptr &&
        cudaStreamSynchronize(stream_) != cudaSuccess) {
      healthy = false;
    }
    stream_ = nullptr;
    events_.fill(nullptr);
    solver_ = nullptr;
    blas_ = nullptr;
    allocations_.clear();
    const bool released = ReleaseRuntimePoolLease(
        &runtime_pool_lease_, healthy, &runtime_->persistent_device, error);
    initialized_ = false;
    initializing_ = false;
    runtime_->persistent_device.close_succeeded = released;
    if (!released && error != nullptr && error->empty()) {
      *error = "ResourceCleanup: RuntimePool release failed";
    }
    return released;
  }
  bool success = true;
  if (solver_ != nullptr &&
      IsCudaResourceActive(reinterpret_cast<uintptr_t>(solver_),
                           CudaTeardownType::kSolver)) {
    ++runtime_->persistent_device.close_solver_destroy_count;
    success = CleanupCudaSolverDestroy(solver_, device_) ==
                  CUSOLVER_STATUS_SUCCESS && success;
  }
  solver_ = nullptr;
  if (blas_ != nullptr &&
      IsCudaResourceActive(reinterpret_cast<uintptr_t>(blas_),
                           CudaTeardownType::kBlas)) {
    ++runtime_->persistent_device.close_blas_destroy_count;
    success = CleanupCudaBlasDestroy(blas_, device_) == CUBLAS_STATUS_SUCCESS &&
              success;
  }
  blas_ = nullptr;
  for (cudaEvent_t& event : events_) {
    if (event != nullptr &&
        IsCudaResourceActive(reinterpret_cast<uintptr_t>(event),
                             CudaTeardownType::kEvent)) {
      ++runtime_->persistent_device.close_event_destroy_count;
      success = CleanupCudaEventDestroy(event, device_) == cudaSuccess && success;
    }
    event = nullptr;
  }
  if (stream_ != nullptr &&
      IsCudaResourceActive(reinterpret_cast<uintptr_t>(stream_),
                           CudaTeardownType::kStream)) {
    ++runtime_->persistent_device.close_stream_destroy_count;
    success = CleanupCudaStreamDestroy(stream_, device_) == cudaSuccess && success;
  }
  stream_ = nullptr;
  for (auto it = allocations_.rbegin(); it != allocations_.rend(); ++it) {
    if (it->pointer != nullptr &&
        IsCudaResourceActive(reinterpret_cast<uintptr_t>(it->pointer),
                             CudaTeardownType::kAllocation)) {
      success = CleanupCudaFree(it->pointer, device_) == cudaSuccess && success;
    }
  }
  allocations_.clear();
  initialized_ = false;
  initializing_ = false;
  // A successfully cleared tainted generation intentionally remains Tainted
  // until the next solve. Resource closure is nevertheless successful when no
  // teardown wrapper failed and the generation cleanup completed.
  const bool close_succeeded = success && g_cuda_taint_cleanup_complete;
  if (runtime_ != nullptr)
    runtime_->persistent_device.close_succeeded = close_succeeded;
  if (!close_succeeded) {
    if (error != nullptr && error->empty())
      *error = "ResourceCleanup: persistent CUDA context close failed";
    return false;
  }
  return true;
}

bool GpuBaDeviceContext::ValidateLayerAView(
    const DeviceLayerAView& view,
    std::string* error) noexcept {
  const bool identity_match = initialized_ && view.identity.valid &&
      view.identity.context_identity == context_identity_ &&
      view.identity.layout_id == layout_id_ &&
      view.identity.arithmetic_precision == arithmetic_precision_ &&
      view.identity.linearization.solve_generation == solve_generation_ &&
      view.identity.linearization.topology_generation == topology_generation_ &&
      view.identity.linearization.config_generation == config_generation_ &&
      view.visual_count == visual_count_ && view.lidar_count == lidar_count_;
  bool generation_match = false;
  for (const LayerASlot& slot : layer_a_slots_) {
    const void* slot_visual = view.compact_visual
        ? static_cast<const void*>(slot.compact_visual)
        : static_cast<const void*>(slot.visual);
    if (slot_visual == view.visual && slot.lidar == view.lidar &&
        slot.mixed_visual == view.mixed_visual &&
        slot.mixed_lidar == view.mixed_lidar &&
        slot.identity.slot_generation == view.identity.slot_generation &&
        slot.identity.valid) {
      generation_match = true;
      break;
    }
  }
  if (!identity_match || !generation_match) {
    ++runtime_->persistent_device.stale_handle_reject_count;
    if (error != nullptr) *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
    return false;
  }
  if (device_state_enabled_) {
    ++runtime_->persistent_device.state_lineage_checks;
    if (!view.source_state_identity.valid) {
      ++runtime_->persistent_device.state_lineage_violations;
      if (error != nullptr) *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
      return false;
    }
  }
  return true;
}

bool GpuBaDeviceContext::ValidateLayerBView(
    const DeviceLayerBView& view,
    const CudaLinearizationIdentity& identity,
    std::string* error) noexcept {
  const bool identity_match = initialized_ && view.identity.valid &&
      view.identity.context_identity == context_identity_ &&
      view.identity.layout_id == layout_id_ &&
      view.identity.arithmetic_precision == arithmetic_precision_ &&
      SameLinearizationIdentity(view.identity.linearization, identity) &&
      view.pose_count == pose_count_ && view.point_count == point_count_ &&
      view.edge_count == edge_count_ &&
      (arithmetic_precision_ != CudaArithmeticPrecision::kFp32MixedStable ||
       ((pose_count_ == 0 || view.mixed_poses != nullptr) &&
        (point_count_ == 0 || view.mixed_points != nullptr) &&
        (edge_count_ == 0 || view.mixed_edges != nullptr)));
  bool generation_match = false;
  for (const LayerBSlot& slot : layer_b_slots_) {
    if (slot.poses == view.poses && slot.points == view.points &&
        slot.edges == view.edges &&
        slot.mixed_poses == view.mixed_poses &&
        slot.mixed_points == view.mixed_points &&
        slot.mixed_edges == view.mixed_edges && slot.identity.valid &&
        slot.identity.slot_generation == view.identity.slot_generation) {
      generation_match = true;
      break;
    }
  }
  if (!identity_match || !generation_match) {
    ++runtime_->persistent_device.stale_handle_reject_count;
    if (error != nullptr) *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
    return false;
  }
  return true;
}

bool GpuBaDeviceContext::ValidateStateView(
    const DeviceStateView& view,
    const CudaLinearizationIdentity& identity,
    std::string* error) noexcept {
  ++runtime_->persistent_device.state_lineage_checks;
  const bool base_match = device_state_enabled_ && initialized_ &&
      view.identity.valid && view.identity.context_identity == context_identity_ &&
      view.identity.layout_id == layout_id_ &&
      view.identity.arithmetic_precision == arithmetic_precision_ &&
      SameLinearizationIdentity(view.identity.linearization, identity) &&
      view.image_count == image_entity_count_ &&
      view.point_count == point_entity_count_ &&
      view.camera_count == camera_entity_count_ &&
      view.slot_index < state_slots_.size();
  bool slot_match = false;
  if (base_match) {
    const StateSlot& slot = state_slots_[view.slot_index];
    slot_match = slot.identity.valid &&
        slot.images == view.images && slot.points == view.points &&
        slot.identity.slot_generation == view.identity.slot_generation;
  }
  if (!base_match || !slot_match) {
    ++runtime_->persistent_device.state_lineage_violations;
    ++runtime_->persistent_device.stale_handle_reject_count;
    if (view.identity.context_identity != 0 &&
        view.identity.context_identity != context_identity_) {
      ++runtime_->persistent_device.cross_solve_state_handle_hits;
    }
    if (error != nullptr) *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
    return false;
  }
  return true;
}

bool GpuBaDeviceContext::ValidateStateBPair(
    const DeviceStateView& state,
    const DeviceLayerBView& layer_b,
    std::string* error) noexcept {
  ++runtime_->persistent_device.state_b_pair_checks;
  const bool valid = state.identity.valid && layer_b.identity.valid &&
      SameLinearizationIdentity(state.identity.linearization,
                                layer_b.identity.linearization) &&
      layer_b.source_state_identity.valid &&
      layer_b.source_state_identity.context_identity == context_identity_ &&
      layer_b.source_state_identity.slot_generation ==
          state.identity.slot_generation &&
      layer_b.source_state_identity.layout_id == state.identity.layout_id;
  if (!valid) {
    ++runtime_->persistent_device.state_b_pair_violations;
    if (error != nullptr) *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
    return false;
  }
  return true;
}

DeviceStateView GpuBaDeviceContext::CurrentStateView(
    const CudaLinearizationIdentity& identity,
    std::string* error) noexcept {
  DeviceStateView view;
  const StateSlot& slot = state_slots_[current_state_slot_];
  view.images = slot.images;
  view.points = slot.points;
  view.cameras = d_camera_entities_;
  view.image_count = image_entity_count_;
  view.point_count = point_entity_count_;
  view.camera_count = camera_entity_count_;
  view.slot_index = static_cast<uint32_t>(current_state_slot_);
  view.identity = slot.identity;
  if (!ValidateStateView(view, identity, error)) return DeviceStateView();
  return view;
}

DeviceStateView GpuBaDeviceContext::TrialStateView(
    const CudaLinearizationIdentity& identity,
    std::string* error) noexcept {
  DeviceStateView view;
  const StateSlot& slot = state_slots_[trial_state_slot_];
  view.images = slot.images;
  view.points = slot.points;
  view.cameras = d_camera_entities_;
  view.image_count = image_entity_count_;
  view.point_count = point_entity_count_;
  view.camera_count = camera_entity_count_;
  view.slot_index = static_cast<uint32_t>(trial_state_slot_);
  view.identity = slot.identity;
  if (!ValidateStateView(view, identity, error)) return DeviceStateView();
  return view;
}

bool GpuBaDeviceContext::PackAndRunLayerA(
    const PackedLayerAState& packed,
    const CudaLayerAOptions& options,
    const CudaLinearizationIdentity& identity,
    const size_t slot_index,
    const PersistentSlotKind kind,
    DeviceLayerAView* view,
    CudaRuntimeInfo* layer_runtime,
    std::string* error) {
  if (!initialized_ || slot_index >= layer_a_slots_.size() || view == nullptr ||
      layer_runtime == nullptr || error == nullptr ||
      packed.visual.size() != visual_count_ ||
      packed.lidar.size() != lidar_count_ ||
      packed.pose_state.size() != pose_count_ ||
      packed.layout_id != layout_id_ ||
      packed.topology_generation != topology_generation_ ||
      packed.config_generation != config_generation_ ||
      identity.solve_generation != solve_generation_ ||
      identity.topology_generation != topology_generation_ ||
      identity.config_generation != config_generation_) {
    if (error != nullptr) *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
    return false;
  }
  if (options.device != device_ || options.memory_mode != memory_mode_ ||
      options.block_size <= 0 || options.block_size > 1024) {
    *error = "persistent Layer A options differ from initialized context";
    return false;
  }
  if (g_cuda_solve_call_counters != nullptr)
    ++g_cuda_solve_call_counters->layer_a;
  if (g_cuda_timing_sink != nullptr) ++g_cuda_timing_sink->layer_a_calls;
  InclusiveCallScope inclusive_call(CUDA_TIMING_PHASE(layer_a_call));

  for (size_t i = 0; i < visual_count_; ++i) {
    const CudaVisualInput& input = packed.visual[i];
    DeviceVisualDynamicInput& state = host_visual_dynamic_[i];
    for (size_t j = 0; j < 4; ++j) state.quaternion[j] = input.quaternion[j];
    for (size_t j = 0; j < 3; ++j) {
      state.translation[j] = input.translation[j];
      state.point[j] = input.point[j];
    }
    for (size_t j = 0; j < 8; ++j) state.camera[j] = input.camera[j];
  }
  for (size_t i = 0; i < lidar_count_; ++i) {
    for (size_t j = 0; j < 3; ++j)
      host_lidar_dynamic_[i].point[j] = packed.lidar[i].point[j];
  }
  if (!UploadDynamic(d_visual_dynamic_, host_visual_dynamic_, error) ||
      !UploadDynamic(d_lidar_dynamic_, host_lidar_dynamic_, error) ||
      !UploadDynamic(d_pose_state_, packed.pose_state, error)) {
    return false;
  }
  LayerASlot& slot = layer_a_slots_[slot_index];
  InvalidateLayerASlot(slot_index);
  slot.identity.linearization = identity;
  slot.identity.context_identity = context_identity_;
  slot.identity.layout_id = layout_id_;
  slot.identity.slot_generation = ++next_slot_generation_;
  slot.identity.arithmetic_precision = arithmetic_precision_;
  slot.identity.kind = kind;
  slot.identity.valid = true;
  AuditCudaEventRecord(events_[0], stream_);
  const auto blocks_for = [options](const size_t count) {
    return static_cast<int>((count + static_cast<size_t>(options.block_size) - 1) /
                            static_cast<size_t>(options.block_size));
  };
  if (visual_count_ != 0) {
    LayerAVisualPersistentKernel<<<blocks_for(visual_count_), options.block_size,
                                   0, stream_>>>(
        d_visual_static_, d_visual_dynamic_, slot.visual, visual_count_);
  }
  if (lidar_count_ != 0) {
    LayerALidarPersistentKernel<<<blocks_for(lidar_count_), options.block_size,
                                  0, stream_>>>(
        d_lidar_static_, d_lidar_dynamic_, slot.lidar, lidar_count_);
  }
  const cudaError_t status = cudaGetLastError();
  layer_runtime->launch_status = static_cast<int>(status);
  if (status != cudaSuccess) {
    slot.identity.valid = false;
    *error = std::string("persistent Layer A launch failed: ") +
             CudaErrorText(status);
    return false;
  }
  AuditCudaEventRecord(events_[1], stream_);
  layer_runtime->device = device_;
  layer_runtime->visual_bytes =
      visual_count_ * sizeof(DeviceVisualDynamicInput);
  layer_runtime->lidar_bytes = lidar_count_ * sizeof(DeviceLidarDynamicInput);
  layer_runtime->output_bytes =
      visual_count_ * sizeof(CudaVisualOutput) +
      lidar_count_ * sizeof(CudaLidarOutput);
  layer_runtime->explicit_synchronization = true;
  layer_runtime->used_unified_memory =
      memory_mode_ == CudaMemoryMode::kUnifiedManaged;
  view->visual = slot.visual;
  view->compact_visual = false;
  view->lidar = slot.lidar;
  view->visual_count = visual_count_;
  view->lidar_count = lidar_count_;
  view->identity = slot.identity;
  return true;
}

bool GpuBaDeviceContext::RunLayerAFromDeviceState(
    const DeviceStateView& state,
    const CudaLayerAOptions& options,
    const CudaLinearizationIdentity& identity,
    const size_t slot_index,
    const PersistentSlotKind kind,
    DeviceLayerAView* view,
    CudaRuntimeInfo* layer_runtime,
    std::string* error) {
  if (!device_state_enabled_ ||
      (!state_ready_ && identity.config_generation != 0) ||
      slot_index >= layer_a_slots_.size() || view == nullptr ||
      layer_runtime == nullptr || error == nullptr ||
      !ValidateStateView(state, identity, error)) {
    if (error != nullptr && error->empty())
      *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
    return false;
  }
  if (options.device != device_ || options.memory_mode != memory_mode_ ||
      options.block_size <= 0 || options.block_size > 1024) {
    *error = "device-state Layer A options differ from initialized context";
    return false;
  }
  if (g_cuda_solve_call_counters != nullptr)
    ++g_cuda_solve_call_counters->layer_a;
  if (g_cuda_timing_sink != nullptr) ++g_cuda_timing_sink->layer_a_calls;
  InclusiveCallScope inclusive_call(CUDA_TIMING_PHASE(layer_a_call));
  LayerASlot& slot = layer_a_slots_[slot_index];
  InvalidateLayerASlot(slot_index);
  slot.identity.linearization = identity;
  slot.identity.context_identity = context_identity_;
  slot.identity.layout_id = layout_id_;
  slot.identity.slot_generation = ++next_slot_generation_;
  slot.identity.arithmetic_precision = arithmetic_precision_;
  slot.identity.kind = kind;
  slot.identity.valid = true;
  const int block_size = options.block_size;
  const auto blocks_for = [block_size](const size_t count) {
    return static_cast<int>((count + static_cast<size_t>(block_size) - 1) /
                            static_cast<size_t>(block_size));
  };
  AuditCudaEventRecord(events_[0], stream_);
  const bool mixed_precision =
      arithmetic_precision_ == CudaArithmeticPrecision::kFp32MixedStable;
  if (visual_count_ != 0) {
    if (compact_layer_a_enabled_) {
      LayerAVisualDeviceStateCompactKernel<<<
          blocks_for(visual_count_), block_size, 0, stream_>>>(
          d_visual_static_, state.images, state.points, state.cameras,
          slot.compact_visual, visual_count_);
      ++runtime_->persistent_device.compact_layer_a_calls;
    } else {
      LayerAVisualDeviceStateKernel<<<blocks_for(visual_count_), block_size, 0,
                                      stream_>>>(
          d_visual_static_, state.images, state.points, state.cameras,
          slot.visual, visual_count_);
    }
    if (mixed_precision) {
      if (compact_layer_a_enabled_) {
        LayerAVisualMixedFromCompactKernel<<<
            blocks_for(visual_count_), block_size, 0, stream_>>>(
            slot.compact_visual, slot.mixed_visual, visual_count_);
      } else {
        LayerAVisualMixedFromFullKernel<<<
            blocks_for(visual_count_), block_size, 0, stream_>>>(
            slot.visual, slot.mixed_visual, visual_count_);
      }
      ++runtime_->persistent_device.mixed_layer_a_cast_calls;
      runtime_->persistent_device.mixed_layer_a_cast_bytes = SaturatingAdd(
          runtime_->persistent_device.mixed_layer_a_cast_bytes,
          visual_count_ * sizeof(MixedVisualOutput));
    }
  }
  if (lidar_count_ != 0) {
    LayerALidarDeviceStateKernel<<<blocks_for(lidar_count_), block_size, 0,
                                   stream_>>>(
        d_lidar_static_, state.points, slot.lidar, lidar_count_);
    if (mixed_precision) {
      LayerALidarMixedFromDoubleKernel<<<
          blocks_for(lidar_count_), block_size, 0, stream_>>>(
          slot.lidar, slot.mixed_lidar, lidar_count_);
      ++runtime_->persistent_device.mixed_layer_a_cast_calls;
      runtime_->persistent_device.mixed_layer_a_cast_bytes = SaturatingAdd(
          runtime_->persistent_device.mixed_layer_a_cast_bytes,
          lidar_count_ * sizeof(MixedLidarOutput));
    }
  }
  const cudaError_t status = cudaGetLastError();
  layer_runtime->launch_status = static_cast<int>(status);
  if (status != cudaSuccess) {
    slot.identity.valid = false;
    *error = std::string("device-state Layer A launch failed: ") +
             CudaErrorText(status);
    return false;
  }
  AuditCudaEventRecord(events_[1], stream_);
  layer_runtime->device = device_;
  layer_runtime->visual_bytes = 0;
  layer_runtime->lidar_bytes = 0;
  layer_runtime->output_bytes =
      visual_count_ * (compact_layer_a_enabled_
                           ? sizeof(CudaCompactVisualOutput)
                           : sizeof(CudaVisualOutput)) +
      lidar_count_ * sizeof(CudaLidarOutput);
  if (mixed_precision) {
    layer_runtime->output_bytes +=
        visual_count_ * sizeof(MixedVisualOutput) +
        lidar_count_ * sizeof(MixedLidarOutput);
  }
  layer_runtime->explicit_synchronization = true;
  layer_runtime->used_unified_memory =
      memory_mode_ == CudaMemoryMode::kUnifiedManaged;
  view->visual = compact_layer_a_enabled_
      ? static_cast<const void*>(slot.compact_visual)
      : static_cast<const void*>(slot.visual);
  view->compact_visual = compact_layer_a_enabled_;
  view->lidar = slot.lidar;
  view->mixed_visual = slot.mixed_visual;
  view->mixed_lidar = slot.mixed_lidar;
  view->visual_count = visual_count_;
  view->lidar_count = lidar_count_;
  view->identity = slot.identity;
  view->source_state_identity = state.identity;
  return true;
}

bool GpuBaDeviceContext::ComputeCost(
    const DeviceLayerAView& view,
    const CudaLayerBOptions& options,
    const CudaLossMode loss_mode,
    const double loss_scale,
    double* cost,
    double* kernel_milliseconds,
    DeviceLmScalarPacket* combined_current_packet,
    std::string* error) {
  if (cost == nullptr || kernel_milliseconds == nullptr || error == nullptr ||
      !ValidateLayerAView(view, error)) {
    return false;
  }
  if (g_cuda_solve_call_counters != nullptr)
    ++g_cuda_solve_call_counters->cost;
  if (g_cuda_timing_sink != nullptr) ++g_cuda_timing_sink->cost_calls;
  HostPhaseScope timing(CUDA_TIMING_PHASE(trial_cost));
  const bool parallel =
      options.reduction_mode == CudaReductionMode::kParallelDeterministic;
  const int workers = parallel
                          ? std::min(1024, std::max(1,
                              options.cost_reduction_threads))
                          : 1;
  AuditCudaEventRecord(events_[8], stream_);
  if (parallel) {
    LayerCCostPartialKernel<<<1, workers, 0, stream_>>>(
        d_cost_order_, cost_count_, view.visual, view.compact_visual,
        view.lidar,
        static_cast<uint8_t>(loss_mode), loss_scale, d_cost_partials_);
    LayerCCostOrderedReduceKernel<<<1, 1, 0, stream_>>>(
        d_cost_partials_, static_cast<size_t>(workers), d_cost_);
  } else {
    LayerCCostKernel<<<1, 1, 0, stream_>>>(
        d_cost_order_, cost_count_, view.visual, view.compact_visual,
        view.lidar,
        static_cast<uint8_t>(loss_mode), loss_scale,
        options.cost_reduction_threads, d_cost_);
  }
  const cudaError_t launch_status = cudaGetLastError();
  if (launch_status != cudaSuccess) {
    *error = std::string("persistent cost launch failed: ") +
             CudaErrorText(launch_status);
    return false;
  }
  AuditCudaEventRecord(events_[9], stream_);
  if (combined_current_packet != nullptr) {
    DeviceStoreCurrentCostKernel<<<1, 1, 0, stream_>>>(d_cost_,
                                                       d_scalar_packet_);
    if (cudaGetLastError() != cudaSuccess ||
        !DownloadScalarPacket(combined_current_packet, error) ||
        !Synchronize(CudaSyncSite::kTrialCostFinal, error)) {
      return false;
    }
    ++runtime_->persistent_device.scalar_current_packet_calls;
    *cost = combined_current_packet->current_cost;
  } else {
    std::vector<double> cost_value(1, 0.0);
    if (!DownloadController(d_cost_, &cost_value, error) ||
        !Synchronize(CudaSyncSite::kTrialCostFinal, error)) {
      return false;
    }
    *cost = cost_value[0];
  }
  *kernel_milliseconds = EventElapsed(8, 9);
  RecordCudaEvent(CUDA_TIMING_PHASE(trial_cost), *kernel_milliseconds);
  return std::isfinite(*cost);
}

bool GpuBaDeviceContext::RunLayerB(
    const PackedLayerAState& packed,
    const CudaLayerBOptions& options,
    const CudaLinearizationIdentity& identity,
    const CudaFaultLogicalSite site,
    const CudaLossMode loss_mode,
    const double loss_scale,
    CudaLayerBResult* result,
    CudaDeviceLinearizationToken* token,
    std::string* error) {
  if (result == nullptr || error == nullptr) return false;
  const bool host_frozen = !options.frozen_pose_jacobi_scaling.empty() ||
                           !options.frozen_point_jacobi_scaling.empty();
  const bool frozen = options.device_frozen_jacobi_scaling || host_frozen;
  if (frozen != frozen_scaling_uploaded_ ||
      (host_frozen &&
       (options.frozen_pose_jacobi_scaling.size() != pose_count_ * 6 ||
        options.frozen_point_jacobi_scaling.size() != point_count_ * 3))) {
    *error = "persistent frozen Jacobi scaling state mismatch";
    result->error = *error;
    return false;
  }
  DeviceLayerAView layer_a;
  if (!PackAndRunLayerA(packed, options.layer_a, identity, 0,
                        PersistentSlotKind::kLayerAWorking, &layer_a,
                        &result->layer_a.runtime, error)) {
    result->error = *error;
    return false;
  }
  return AssembleLayerB(layer_a, nullptr, options, identity, site, loss_mode,
                        loss_scale, result, token, error);
}

bool GpuBaDeviceContext::RunLayerBFromDeviceState(
    const Snapshot& host_state,
    const CudaLayerBOptions& options,
    const CudaLinearizationIdentity& identity,
    const CudaFaultLogicalSite site,
    const CudaLossMode loss_mode,
    const double loss_scale,
    CudaLayerBResult* result,
    CudaDeviceLinearizationToken* token,
    std::string* error) {
  if (!device_state_enabled_ || result == nullptr || token == nullptr ||
      error == nullptr) return false;
  if (host_state.images.size() != image_entity_count_ ||
      host_state.points.size() != point_entity_count_ ||
      host_state.cameras.size() != camera_entity_count_) {
    *error = "device-state host mirror entity counts changed";
    result->error = *error;
    return false;
  }
  for (size_t i = 0; i < camera_entity_count_; ++i) {
    if (host_state.cameras[i].params.size() != 8) {
      *error = "device-state camera parameter layout changed";
      result->error = *error;
      return false;
    }
    for (size_t j = 0; j < 8; ++j) {
      if (host_state.cameras[i].params[j] != host_camera_entities_[i].params[j]) {
        *error = "device-state fixed camera parameters changed";
        result->error = *error;
        return false;
      }
    }
  }
  DeviceStateView state =
      site == CudaFaultLogicalSite::kAcceptedPendingLinearization
          ? TrialStateView(identity, error)
          : CurrentStateView(identity, error);
  if (!state.identity.valid) {
    result->error = *error;
    return false;
  }
  DeviceLayerAView layer_a;
  if (!RunLayerAFromDeviceState(
          state, options.layer_a, identity, 0,
          PersistentSlotKind::kLayerAWorking, &layer_a,
          &result->layer_a.runtime, error)) {
    result->error = *error;
    return false;
  }
  return AssembleLayerB(layer_a, &state, options, identity, site, loss_mode,
                        loss_scale, result, token, error);
}

bool GpuBaDeviceContext::RunLayerBFromNativeDeviceState(
    const CudaLayerBOptions& options,
    const CudaLinearizationIdentity& identity,
    const CudaFaultLogicalSite site,
    const CudaLossMode loss_mode,
    const double loss_scale,
    CudaLayerBResult* result,
    CudaDeviceLinearizationToken* token,
    std::string* error) {
  if (!device_state_enabled_ || result == nullptr || token == nullptr ||
      error == nullptr || native_image_slots_.size() != image_entity_count_ ||
      native_point_slots_.size() != point_entity_count_ ||
      native_camera_slots_.size() != camera_entity_count_) {
    if (error != nullptr) *error = "native device-state Layer B is invalid";
    return false;
  }
  DeviceStateView state =
      site == CudaFaultLogicalSite::kAcceptedPendingLinearization
          ? TrialStateView(identity, error)
          : CurrentStateView(identity, error);
  if (!state.identity.valid) {
    result->error = *error;
    return false;
  }
  DeviceLayerAView layer_a;
  if (!RunLayerAFromDeviceState(
          state, options.layer_a, identity, 0,
          PersistentSlotKind::kLayerAWorking, &layer_a,
          &result->layer_a.runtime, error)) {
    result->error = *error;
    return false;
  }
  return AssembleLayerB(layer_a, &state, options, identity, site, loss_mode,
                        loss_scale, result, token, error);
}

bool GpuBaDeviceContext::AssembleLayerB(
    const DeviceLayerAView& layer_a,
    const DeviceStateView* state,
    const CudaLayerBOptions& options,
    const CudaLinearizationIdentity& identity,
    const CudaFaultLogicalSite site,
    const CudaLossMode loss_mode,
    const double loss_scale,
    CudaLayerBResult* result,
    CudaDeviceLinearizationToken* token,
    std::string* error) {
  const bool host_frozen = !options.frozen_pose_jacobi_scaling.empty() ||
                           !options.frozen_point_jacobi_scaling.empty();
  const bool frozen = options.device_frozen_jacobi_scaling || host_frozen;
  const bool bootstrap_mirror =
      device_control_enabled_ &&
      site == CudaFaultLogicalSite::kInitialLinearization &&
      !device_scaling_enabled_;
  const bool full_mirror = !device_control_enabled_ || bootstrap_mirror ||
                           audit_mirror_enabled_;
  if (frozen != frozen_scaling_uploaded_ ||
      (host_frozen &&
       (options.frozen_pose_jacobi_scaling.size() != pose_count_ * 6 ||
        options.frozen_point_jacobi_scaling.size() != point_count_ * 3))) {
    *error = "persistent frozen Jacobi scaling state mismatch";
    result->error = *error;
    return false;
  }
  const size_t slot_index = SelectLayerBSlot(site);
  InvalidateLayerBSlot(slot_index);
  LayerBSlot& slot = layer_b_slots_[slot_index];
  slot.identity.linearization = identity;
  slot.identity.context_identity = context_identity_;
  slot.identity.layout_id = layout_id_;
  slot.identity.slot_generation = ++next_slot_generation_;
  slot.identity.arithmetic_precision = arithmetic_precision_;
  slot.identity.kind = site == CudaFaultLogicalSite::kInitialLinearization
                           ? PersistentSlotKind::kLinearizationCurrent
                           : (site == CudaFaultLogicalSite::kAcceptedPendingLinearization
                                  ? PersistentSlotKind::kLinearizationPending
                                  : PersistentSlotKind::kLinearizationTemporary);
  slot.identity.valid = true;
  slot.source_state_identity =
      state == nullptr ? PersistentSlotIdentity() : state->identity;
  const int block_size = options.layer_a.block_size;
  const auto blocks_for = [block_size](const size_t count) {
    return static_cast<int>((count + static_cast<size_t>(block_size) - 1) /
                            static_cast<size_t>(block_size));
  };
  const bool parallel =
      options.reduction_mode == CudaReductionMode::kParallelDeterministic;
  AuditCudaEventRecord(events_[2], stream_);
  if (state != nullptr && pose_count_ != 0) {
    GatherVariablePoseStateKernel<<<blocks_for(pose_count_), block_size, 0,
                                    stream_>>>(
        state->images, d_pose_image_entity_indices_, d_pose_state_, pose_count_);
  }
  AuditCudaEventRecord(events_[12], stream_);
  ++runtime_->persistent_device.hessian_gradient_assembly_calls;
  ++result->runtime.hessian_gradient_assembly_calls;
  result->runtime.hessian_assembly_backend_effective =
      HessianAssemblyBackendName(hessian_assembly_backend_);
  const auto record_block_calls = [&]() {
    if (pose_count_ != 0) {
      ++runtime_->persistent_device.pose_block_assembly_calls;
      ++result->runtime.pose_block_assembly_calls;
    }
    if (point_count_ != 0) {
      ++runtime_->persistent_device.point_block_assembly_calls;
      ++result->runtime.point_block_assembly_calls;
    }
    if (edge_count_ != 0) {
      ++runtime_->persistent_device.edge_block_assembly_calls;
      ++result->runtime.edge_block_assembly_calls;
    }
  };
  record_block_calls();
  const bool mixed_precision =
      arithmetic_precision_ == CudaArithmeticPrecision::kFp32MixedStable;
  if (mixed_precision) {
    if (layer_a.mixed_visual == nullptr ||
        (lidar_count_ != 0 && layer_a.mixed_lidar == nullptr)) {
      slot.identity.valid = false;
      *error = "fp32_mixed linearization view is missing typed records";
      result->error = *error;
      return false;
    }
    if (pose_count_ != 0) {
      cudaMemsetAsync(slot.mixed_poses, 0,
                      pose_count_ * sizeof(MixedPoseBlockOutput), stream_);
    }
    if (point_count_ != 0) {
      cudaMemsetAsync(slot.mixed_points, 0,
                      point_count_ * sizeof(MixedPointBlockOutput), stream_);
    }
    if (edge_count_ != 0) {
      cudaMemsetAsync(slot.mixed_edges, 0,
                      edge_count_ * sizeof(MixedEdgeBlockOutput), stream_);
    }
    runtime_->persistent_device.output_zero_kernel_launches +=
        (pose_count_ != 0) + (point_count_ != 0) + (edge_count_ != 0);
    result->runtime.output_zero_kernel_launches +=
        (pose_count_ != 0) + (point_count_ != 0) + (edge_count_ != 0);
    if (point_assembly_direct_count_ != 0) {
      LayerBMixedPointDirectKernel<<<
          blocks_for(point_assembly_direct_count_), block_size, 0, stream_>>>(
          d_point_meta_, d_point_assembly_direct_indices_, d_point_adjacency_,
          layer_a.mixed_visual, layer_a.mixed_lidar,
          static_cast<uint8_t>(loss_mode), static_cast<float>(loss_scale),
          frozen ? d_frozen_point_scaling_ : nullptr,
          static_cast<float>(options.min_lm_diagonal),
          static_cast<float>(options.max_lm_diagonal), slot.mixed_points,
          point_assembly_direct_count_);
    }
    if (pose_assembly_segment_count_ != 0) {
      LayerBMixedPoseSegmentPartialKernel<<<
          pose_assembly_segment_count_, kObservationSegmentThreads, 0,
          stream_>>>(
          d_pose_assembly_segments_, d_pose_adjacency_, d_pose_meta_,
          layer_a.mixed_visual, static_cast<uint8_t>(loss_mode),
          static_cast<float>(loss_scale), d_mixed_pose_hessian_partials_,
          pose_assembly_segment_count_);
      ++runtime_->persistent_device.observation_segment_partial_launches;
      ++result->runtime.observation_segment_partial_launches;
    }
    if (point_assembly_segment_count_ != 0) {
      LayerBMixedPointSegmentPartialKernel<<<
          point_assembly_segment_count_, kObservationSegmentThreads, 0,
          stream_>>>(
          d_point_assembly_segments_, d_point_adjacency_,
          layer_a.mixed_visual, layer_a.mixed_lidar,
          static_cast<uint8_t>(loss_mode), static_cast<float>(loss_scale),
          d_mixed_point_partials_, point_assembly_segment_count_);
      ++runtime_->persistent_device.observation_segment_partial_launches;
      ++result->runtime.observation_segment_partial_launches;
    }
    if (edge_count_ != 0) {
      LayerBMixedEdgeKernel<<<blocks_for(edge_count_), block_size, 0, stream_>>>(
          d_edge_meta_, d_edge_adjacency_, d_pose_meta_,
          layer_a.mixed_visual, static_cast<uint8_t>(loss_mode),
          static_cast<float>(loss_scale), slot.mixed_edges, edge_count_);
    }
    AuditCudaEventRecord(events_[13], stream_);
    if (pose_count_ != 0) {
      LayerBMixedPoseSegmentMergeKernel<<<
          pose_count_, kObservationSegmentThreads, 0, stream_>>>(
          d_pose_meta_, d_pose_assembly_ranges_,
          d_mixed_pose_hessian_partials_,
          frozen ? d_frozen_pose_scaling_ : nullptr,
          static_cast<float>(options.min_lm_diagonal),
          static_cast<float>(options.max_lm_diagonal), slot.mixed_poses,
          pose_count_);
      LayerBMixedPoseGradientFromFp64Kernel<<<
          pose_count_, kLayerBPoseOptimizedThreads, 0, stream_>>>(
          d_pose_meta_, d_pose_adjacency_, layer_a.visual,
          layer_a.compact_visual, static_cast<uint8_t>(loss_mode), loss_scale,
          slot.mixed_poses, pose_count_);
      ++runtime_->persistent_device.mixed_fp64_gradient_calls;
      ++runtime_->persistent_device
            .mixed_fp64_gradient_from_fp64_records_calls;
    }
    if (point_count_ != 0) {
      LayerBMixedPointSegmentMergeKernel<<<
          point_count_, kObservationSegmentThreads, 0, stream_>>>(
          d_point_meta_, d_point_assembly_ranges_, d_mixed_point_partials_,
          frozen ? d_frozen_point_scaling_ : nullptr,
          static_cast<float>(options.min_lm_diagonal),
          static_cast<float>(options.max_lm_diagonal), slot.mixed_points,
          point_count_);
      LayerBMixedPointGradientFromFp64Kernel<<<point_count_, 3, 0, stream_>>>(
          d_point_meta_, d_point_adjacency_, layer_a.visual,
          layer_a.compact_visual, layer_a.lidar,
          static_cast<uint8_t>(loss_mode), loss_scale, slot.mixed_points,
          point_count_);
      ++runtime_->persistent_device.mixed_fp64_gradient_calls;
      ++runtime_->persistent_device
            .mixed_fp64_gradient_from_fp64_records_calls;
    }
    AuditCudaEventRecord(events_[14], stream_);
    if (pose_count_ != 0) {
      ConvertMixedPoseBlocksKernel<<<pose_count_, 64, 0, stream_>>>(
          slot.mixed_poses, slot.poses, pose_count_);
    }
    if (point_count_ != 0) {
      ConvertMixedPointBlocksKernel<<<point_count_, 32, 0, stream_>>>(
          slot.mixed_points, slot.points, point_count_);
    }
    if (edge_count_ != 0 && full_mirror) {
      ConvertMixedEdgeBlocksKernel<<<edge_count_, 32, 0, stream_>>>(
          slot.mixed_edges, slot.edges, edge_count_);
      ++runtime_->persistent_device.mixed_double_edge_materialization_calls;
      runtime_->persistent_device.mixed_double_edge_materialization_bytes =
          SaturatingAdd(
              runtime_->persistent_device.mixed_double_edge_materialization_bytes,
              edge_count_ * sizeof(CudaEdgeBlockOutput));
    }
    ++runtime_->persistent_device.jacobi_damping_finalize_calls;
    ++runtime_->persistent_device.jacobi_finalize_kernel_launches;
    ++result->runtime.jacobi_damping_finalize_calls;
    ++result->runtime.jacobi_finalize_kernel_launches;
  } else if (hessian_assembly_backend_ ==
          CudaHessianAssemblyBackend::kPoseOwnedScalarCompatibility ||
      hessian_assembly_backend_ ==
          CudaHessianAssemblyBackend::kPoseOwnedOptimizedReference) {
    if (pose_count_ != 0) {
      if (hessian_assembly_backend_ ==
          CudaHessianAssemblyBackend::kPoseOwnedOptimizedReference) {
        LayerBPoseOptimizedKernel<<<pose_count_,
                                    kLayerBPoseOptimizedThreads, 0, stream_>>>(
            d_pose_meta_, d_pose_adjacency_, layer_a.visual,
            layer_a.compact_visual, static_cast<uint8_t>(loss_mode),
            loss_scale, frozen ? d_frozen_pose_scaling_ : nullptr,
            options.min_lm_diagonal, options.max_lm_diagonal,
            slot.poses, pose_count_);
      } else {
        LayerBPoseKernel<<<blocks_for(pose_count_), block_size, 0, stream_>>>(
            d_pose_meta_, d_pose_adjacency_, layer_a.visual,
            layer_a.compact_visual, static_cast<uint8_t>(loss_mode),
            loss_scale, frozen ? d_frozen_pose_scaling_ : nullptr,
            options.min_lm_diagonal, options.max_lm_diagonal,
            slot.poses, pose_count_);
      }
    }
    AuditCudaEventRecord(events_[13], stream_);
    if (point_count_ != 0) {
      LayerBPointKernel<<<blocks_for(point_count_), block_size, 0, stream_>>>(
          d_point_meta_, nullptr, d_point_adjacency_, layer_a.visual,
          layer_a.compact_visual, layer_a.lidar,
          static_cast<uint8_t>(loss_mode), loss_scale,
          frozen ? d_frozen_point_scaling_ : nullptr,
          options.min_lm_diagonal, options.max_lm_diagonal,
          slot.points, point_count_);
    }
    AuditCudaEventRecord(events_[14], stream_);
    if (edge_count_ != 0) {
      LayerBEdgeKernel<<<blocks_for(edge_count_), block_size, 0, stream_>>>(
          d_edge_meta_, d_edge_adjacency_, d_pose_meta_, layer_a.visual,
          layer_a.compact_visual, static_cast<uint8_t>(loss_mode),
          loss_scale, slot.edges, edge_count_);
    }
    ++runtime_->persistent_device.jacobi_damping_finalize_calls;
    ++result->runtime.jacobi_damping_finalize_calls;
  } else if (hessian_assembly_backend_ ==
             CudaHessianAssemblyBackend::kObservationAtomic) {
    if (pose_count_ != 0) {
      cudaMemsetAsync(slot.poses, 0,
                      pose_count_ * sizeof(CudaPoseBlockOutput), stream_);
      ++runtime_->persistent_device.output_zero_kernel_launches;
      ++result->runtime.output_zero_kernel_launches;
    }
    if (point_count_ != 0) {
      cudaMemsetAsync(slot.points, 0,
                      point_count_ * sizeof(CudaPointBlockOutput), stream_);
      ++runtime_->persistent_device.output_zero_kernel_launches;
      ++result->runtime.output_zero_kernel_launches;
    }
    if (edge_count_ != 0) {
      cudaMemsetAsync(slot.edges, 0,
                      edge_count_ * sizeof(CudaEdgeBlockOutput), stream_);
      ++runtime_->persistent_device.output_zero_kernel_launches;
      ++result->runtime.output_zero_kernel_launches;
    }
    if (visual_count_ != 0) {
      LayerBObservationVisualAtomicKernel<<<blocks_for(visual_count_),
          block_size, 0, stream_>>>(
          d_atomic_visual_bindings_, d_pose_meta_, d_edge_meta_,
          layer_a.visual, layer_a.compact_visual,
          static_cast<uint8_t>(loss_mode), loss_scale, slot.poses,
          slot.points, slot.edges, visual_count_);
      ++runtime_->persistent_device.observation_atomic_kernel_launches;
      ++result->runtime.observation_atomic_kernel_launches;
    }
    if (lidar_count_ != 0) {
      LayerBObservationLidarAtomicKernel<<<blocks_for(lidar_count_),
          block_size, 0, stream_>>>(
          d_atomic_lidar_bindings_, layer_a.lidar,
          static_cast<uint8_t>(loss_mode), loss_scale, slot.points,
          lidar_count_);
      ++runtime_->persistent_device.observation_atomic_kernel_launches;
      ++result->runtime.observation_atomic_kernel_launches;
    }
    AuditCudaEventRecord(events_[13], stream_);
    if (pose_count_ != 0) {
      LayerBFinalizePoseKernel<<<blocks_for(pose_count_), block_size, 0,
                                 stream_>>>(
          d_pose_meta_, frozen ? d_frozen_pose_scaling_ : nullptr,
          options.min_lm_diagonal, options.max_lm_diagonal,
          slot.poses, pose_count_);
    }
    if (point_count_ != 0) {
      LayerBFinalizePointKernel<<<blocks_for(point_count_), block_size, 0,
                                  stream_>>>(
          d_point_meta_, frozen ? d_frozen_point_scaling_ : nullptr,
          options.min_lm_diagonal, options.max_lm_diagonal,
          slot.points, point_count_);
    }
    if (edge_count_ != 0) {
      LayerBFinalizeEdgeKernel<<<blocks_for(edge_count_), block_size, 0,
                                 stream_>>>(d_edge_meta_, slot.edges,
                                            edge_count_);
    }
    AuditCudaEventRecord(events_[14], stream_);
    ++runtime_->persistent_device.jacobi_damping_finalize_calls;
    ++runtime_->persistent_device.jacobi_finalize_kernel_launches;
    ++result->runtime.jacobi_damping_finalize_calls;
    ++result->runtime.jacobi_finalize_kernel_launches;
  } else {
    if (point_assembly_direct_count_ != 0) {
      LayerBPointKernel<<<blocks_for(point_assembly_direct_count_), block_size,
                          0, stream_>>>(
          d_point_meta_, d_point_assembly_direct_indices_,
          d_point_adjacency_, layer_a.visual, layer_a.compact_visual,
          layer_a.lidar, static_cast<uint8_t>(loss_mode), loss_scale,
          frozen ? d_frozen_point_scaling_ : nullptr,
          options.min_lm_diagonal, options.max_lm_diagonal,
          slot.points, point_assembly_direct_count_);
    }
    if (pose_assembly_segment_count_ != 0) {
      LayerBPoseSegmentPartialKernel<<<pose_assembly_segment_count_,
          kObservationSegmentThreads, 0, stream_>>>(
          d_pose_assembly_segments_, d_pose_adjacency_, d_pose_meta_,
          layer_a.visual, layer_a.compact_visual,
          static_cast<uint8_t>(loss_mode), loss_scale,
          d_pose_assembly_partials_, pose_assembly_segment_count_);
      ++runtime_->persistent_device.observation_segment_partial_launches;
      ++result->runtime.observation_segment_partial_launches;
    }
    if (point_assembly_segment_count_ != 0) {
      LayerBPointSegmentPartialKernel<<<point_assembly_segment_count_,
          kObservationSegmentThreads, 0, stream_>>>(
          d_point_assembly_segments_, d_point_adjacency_, layer_a.visual,
          layer_a.compact_visual, layer_a.lidar,
          static_cast<uint8_t>(loss_mode), loss_scale,
          d_point_assembly_partials_, point_assembly_segment_count_);
      ++runtime_->persistent_device.observation_segment_partial_launches;
      ++result->runtime.observation_segment_partial_launches;
    }
    if (edge_count_ != 0) {
      LayerBEdgeKernel<<<blocks_for(edge_count_), block_size, 0, stream_>>>(
          d_edge_meta_, d_edge_adjacency_, d_pose_meta_, layer_a.visual,
          layer_a.compact_visual, static_cast<uint8_t>(loss_mode),
          loss_scale, slot.edges, edge_count_);
    }
    AuditCudaEventRecord(events_[13], stream_);
    if (pose_count_ != 0) {
      LayerBPoseSegmentMergeKernel<<<pose_count_,
          kObservationSegmentThreads, 0, stream_>>>(
          d_pose_meta_, d_pose_assembly_ranges_, d_pose_assembly_partials_,
          frozen ? d_frozen_pose_scaling_ : nullptr,
          options.min_lm_diagonal, options.max_lm_diagonal,
          slot.poses, pose_count_);
      ++runtime_->persistent_device.observation_segment_merge_launches;
      ++result->runtime.observation_segment_merge_launches;
      LayerBPoseGradientCompatibilityKernel<<<
          pose_count_, kLayerBPoseOptimizedThreads, 0, stream_>>>(
          d_pose_meta_, d_pose_adjacency_, layer_a.visual,
          layer_a.compact_visual, static_cast<uint8_t>(loss_mode), loss_scale,
          slot.poses, pose_count_);
    }
    if (point_count_ != 0) {
      LayerBPointSegmentMergeKernel<<<point_count_,
          kObservationSegmentThreads, 0, stream_>>>(
          d_point_meta_, d_point_assembly_ranges_, d_point_assembly_partials_,
          frozen ? d_frozen_point_scaling_ : nullptr,
          options.min_lm_diagonal, options.max_lm_diagonal,
          slot.points, point_count_);
      ++runtime_->persistent_device.observation_segment_merge_launches;
      ++result->runtime.observation_segment_merge_launches;
    }
    AuditCudaEventRecord(events_[14], stream_);
    ++runtime_->persistent_device.jacobi_damping_finalize_calls;
    ++runtime_->persistent_device.jacobi_finalize_kernel_launches;
    ++result->runtime.jacobi_damping_finalize_calls;
    ++result->runtime.jacobi_finalize_kernel_launches;
  }
  AuditCudaEventRecord(events_[15], stream_);
  if (parallel && gradient_slots_ != 0) {
    LayerBGradientNormPartialKernel<<<blocks_for(gradient_slots_), block_size,
                                      0, stream_>>>(
        d_pose_meta_, d_pose_state_, slot.poses, pose_count_, slot.points,
        point_count_, d_gradient_partials_);
    if (hessian_assembly_backend_ !=
        CudaHessianAssemblyBackend::kPoseOwnedScalarCompatibility) {
      LaunchLayerBGradientMaxReduction(
          d_gradient_partials_, gradient_slots_, d_gradient_reduce_a_,
          d_gradient_reduce_b_, d_gradient_norms_, stream_);
    } else {
      LayerBGradientNormReduceKernel<<<1, 1, 0, stream_>>>(
          d_gradient_partials_, gradient_slots_, d_gradient_norms_);
    }
  } else {
    LayerBGradientNormKernel<<<1, 1, 0, stream_>>>(
        d_pose_meta_, d_pose_state_, slot.poses, pose_count_, slot.points,
        point_count_, d_gradient_norms_);
  }
  ++runtime_->persistent_device.gradient_summary_calls;
  ++runtime_->persistent_device.gradient_summary_launches;
  ++result->runtime.gradient_summary_calls;
  ++result->runtime.gradient_summary_launches;
  AuditCudaEventRecord(events_[16], stream_);
  const cudaError_t launch_status = cudaGetLastError();
  result->runtime.launch_status = static_cast<int>(launch_status);
  if (launch_status != cudaSuccess) {
    slot.identity.valid = false;
    *error = std::string("persistent Layer B launch failed: ") +
             CudaErrorText(launch_status);
    result->error = *error;
    return false;
  }
  AuditCudaEventRecord(events_[3], stream_);
  DeviceLmScalarPacket scalar{};
  if (device_control_enabled_) {
    const uint64_t state_generation =
        state == nullptr ? 0 : state->identity.slot_generation;
    AuditCudaEventRecord(events_[4], stream_);
    DeviceLmPacketResetKernel<<<1, 1, 0, stream_>>>(
        d_scalar_packet_, context_identity_, identity, layout_id_,
        state_generation, slot.identity.slot_generation);
    ++runtime_->persistent_device.diagnostic_kernel_calls;
    DeviceStoreGradientSummaryKernel<<<1, 1, 0, stream_>>>(
        d_gradient_norms_, d_scalar_packet_);
    ++runtime_->persistent_device.diagnostic_kernel_calls;
    LaunchLmDiagonalReduction(
        slot.poses, pose_count_, slot.points, point_count_, d_minmax_reduce_a_,
        d_minmax_reduce_b_, d_scalar_packet_, stream_,
        &runtime_->persistent_device.diagnostic_kernel_calls);
    AuditCudaEventRecord(events_[5], stream_);
    if (cudaGetLastError() != cudaSuccess ||
        (!compact_control_enabled_ &&
         !DownloadScalarPacket(&scalar, error))) {
      slot.identity.valid = false;
      result->error = *error;
      return false;
    }
  }
  std::vector<double> gradient_norms(3, 0.0);
  if (full_mirror) {
    result->poses.resize(pose_count_);
    result->points.resize(point_count_);
    result->edges.resize(edge_count_);
    if (!DownloadDiagnostics(slot.poses, &result->poses, error) ||
        !DownloadDiagnostics(slot.points, &result->points, error) ||
        !DownloadDiagnostics(slot.edges, &result->edges, error)) {
      slot.identity.valid = false;
      result->error = *error;
      return false;
    }
    const uint64_t mirror_bytes =
        pose_count_ * sizeof(CudaPoseBlockOutput) +
        point_count_ * sizeof(CudaPointBlockOutput) +
        edge_count_ * sizeof(CudaEdgeBlockOutput);
    if (bootstrap_mirror) {
      runtime_->persistent_device.bootstrap_scaling_mirror_calls += 3;
      runtime_->persistent_device.bootstrap_scaling_mirror_bytes =
          SaturatingAdd(
              runtime_->persistent_device.bootstrap_scaling_mirror_bytes,
              mirror_bytes);
      runtime_->persistent_device.bootstrap_scaling_full_d2h_calls += 3;
      runtime_->persistent_device.bootstrap_scaling_full_d2h_bytes =
          SaturatingAdd(
              runtime_->persistent_device.bootstrap_scaling_full_d2h_bytes,
              mirror_bytes);
    } else if (device_control_enabled_) {
      runtime_->persistent_device.audit_mirror_b_calls += 3;
      runtime_->persistent_device.audit_mirror_b_bytes = SaturatingAdd(
          runtime_->persistent_device.audit_mirror_b_bytes, mirror_bytes);
    } else {
      runtime_->persistent_device.steady_full_b_d2h_calls += 3;
      runtime_->persistent_device.steady_full_b_d2h_bytes = SaturatingAdd(
          runtime_->persistent_device.steady_full_b_d2h_bytes, mirror_bytes);
    }
  }
  if (!device_control_enabled_ &&
      !DownloadController(d_gradient_norms_, &gradient_norms, error)) {
    slot.identity.valid = false;
    result->error = *error;
    return false;
  }
  if (!ComputeCost(layer_a, options, loss_mode, loss_scale, &result->cost,
                   &result->runtime.cost_kernel_milliseconds,
                   compact_control_enabled_ ? &scalar : nullptr, error)) {
    slot.identity.valid = false;
    result->error = *error;
    return false;
  }
  if (device_control_enabled_) {
    const double elapsed = EventElapsed(4, 5);
    runtime_->persistent_device.diagnostic_lm_diagonal_milliseconds += elapsed;
    runtime_->persistent_device.diagnostic_all_added_inclusive_milliseconds +=
        elapsed;
  }
  // ComputeCost synchronizes the same stream, so all B mirrors are now visible.
  result->projected_gradient_max_norm =
      device_control_enabled_ ? scalar.projected_gradient : gradient_norms[0];
  result->raw_tangent_gradient_max_norm =
      device_control_enabled_ ? scalar.raw_gradient : gradient_norms[1];
  result->scaled_gradient_max_norm =
      device_control_enabled_ ? scalar.scaled_gradient : gradient_norms[2];
  result->compact_device_summary = device_control_enabled_ && !full_mirror;
  result->lm_diagonal_base_min = scalar.lm_diagonal_base_min;
  result->lm_diagonal_base_max = scalar.lm_diagonal_base_max;
  result->runtime.assembly_kernel_milliseconds = EventElapsed(2, 3);
  result->runtime.gradient_kernel_milliseconds =
      result->runtime.assembly_kernel_milliseconds;
  result->runtime.reduction_mode = options.reduction_mode;
  result->runtime.cost_reduction_parallel = parallel;
  result->runtime.gradient_reduction_parallel = parallel;
  result->runtime.configured_worker_count =
      std::max(1, options.cost_reduction_threads);
  result->runtime.effective_worker_count = parallel
      ? std::min(1024, result->runtime.configured_worker_count) : 1;
  result->runtime.metadata_bytes = 0;
  result->runtime.adjacency_bytes = 0;
  result->runtime.output_bytes =
      pose_count_ * sizeof(CudaPoseBlockOutput) +
      point_count_ * sizeof(CudaPointBlockOutput) +
      edge_count_ * sizeof(CudaEdgeBlockOutput) + 4 * sizeof(double);
  result->runtime.resident_bytes =
      runtime_->persistent_device.initialization_allocation_bytes;
  result->runtime.predicted_peak_bytes = result->runtime.resident_bytes;
  runtime_->persistent_device.layer_b_pose_milliseconds +=
      EventElapsed(12, 13);
  runtime_->persistent_device.layer_b_point_milliseconds +=
      EventElapsed(13, 14);
  runtime_->persistent_device.layer_b_edge_milliseconds +=
      EventElapsed(14, 15);
  runtime_->persistent_device.layer_b_gradient_milliseconds +=
      EventElapsed(15, 16);
  runtime_->persistent_device.layer_b_total_inclusive_milliseconds +=
      EventElapsed(2, 3);
  if (mixed_precision) {
    runtime_->persistent_device.mixed_residual_jacobian_milliseconds +=
        EventElapsed(0, 1);
    runtime_->persistent_device.mixed_hessian_milliseconds +=
        EventElapsed(12, 15);
    runtime_->persistent_device.mixed_gradient_milliseconds +=
        EventElapsed(15, 16);
  }
  result->layer_a.success = true;
  result->layer_a.runtime.kernel_milliseconds = EventElapsed(0, 1);
  RecordCudaEvent(CUDA_TIMING_PHASE(layer_a_kernel),
                  result->layer_a.runtime.kernel_milliseconds);
  RecordCudaEvent(CUDA_TIMING_PHASE(layer_b_gradient_kernel),
                  result->runtime.gradient_kernel_milliseconds);
  latest_b_slot_ = slot_index;
  if (token != nullptr) {
    token->valid = true;
    token->context_identity = context_identity_;
    token->layout_id = layout_id_;
    token->arithmetic_precision = arithmetic_precision_;
    token->linearization = identity;
    token->layer_b_slot = static_cast<uint32_t>(slot_index);
    token->layer_b_slot_generation = slot.identity.slot_generation;
    if (state != nullptr) {
      token->state_slot = state->slot_index;
      token->state_slot_generation = state->identity.slot_generation;
    }
  }
  result->success = true;
  return true;
}

DeviceLayerBView GpuBaDeviceContext::LayerBViewFromToken(
    const CudaDeviceLinearizationToken& token,
    const CudaLinearizationIdentity& identity,
    std::string* error) noexcept {
  DeviceLayerBView view;
  if (!token.valid || token.context_identity != context_identity_ ||
      token.layout_id != layout_id_ ||
      token.arithmetic_precision != arithmetic_precision_ ||
      !SameLinearizationIdentity(token.linearization, identity) ||
      token.layer_b_slot >= layer_b_slots_.size()) {
    if (device_state_enabled_ && token.context_identity != 0 &&
        token.context_identity != context_identity_) {
      ++runtime_->persistent_device.cross_solve_state_handle_hits;
    }
    ++runtime_->persistent_device.stale_handle_reject_count;
    if (error != nullptr) *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
    return view;
  }
  const LayerBSlot& slot = layer_b_slots_[token.layer_b_slot];
  if (slot.identity.slot_generation != token.layer_b_slot_generation) {
    ++runtime_->persistent_device.stale_handle_reject_count;
    if (error != nullptr) *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
    return view;
  }
  view.poses = slot.poses;
  view.points = slot.points;
  view.edges = slot.edges;
  view.mixed_poses = slot.mixed_poses;
  view.mixed_points = slot.mixed_points;
  view.mixed_edges = slot.mixed_edges;
  view.pose_count = pose_count_;
  view.point_count = point_count_;
  view.edge_count = edge_count_;
  view.identity = slot.identity;
  view.source_state_identity = slot.source_state_identity;
  if (!ValidateLayerBView(view, identity, error)) return DeviceLayerBView();
  return view;
}

bool GpuBaDeviceContext::ValidateLinearizationToken(
    const CudaDeviceLinearizationToken& token,
    const CudaLinearizationIdentity& identity,
    std::string* error) noexcept {
  DeviceLayerBView layer_b = LayerBViewFromToken(token, identity, error);
  if (!layer_b.identity.valid) return false;
  if (!device_state_enabled_) return true;
  if (token.state_slot >= state_slots_.size()) {
    ++runtime_->persistent_device.state_lineage_violations;
    if (error != nullptr) *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
    return false;
  }
  const StateSlot& slot = state_slots_[token.state_slot];
  DeviceStateView state;
  state.images = slot.images;
  state.points = slot.points;
  state.cameras = d_camera_entities_;
  state.image_count = image_entity_count_;
  state.point_count = point_entity_count_;
  state.camera_count = camera_entity_count_;
  state.slot_index = token.state_slot;
  state.identity = slot.identity;
  if (token.state_slot_generation != state.identity.slot_generation) {
    ++runtime_->persistent_device.state_lineage_violations;
    ++runtime_->persistent_device.stale_handle_reject_count;
    if (error != nullptr) *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
    return false;
  }
  if (!ValidateStateView(state, identity, error) ||
      !ValidateStateBPair(state, layer_b, error)) {
    return false;
  }
  return true;
}

bool GpuBaDeviceContext::RunLayerCLinearSolve(
    const LayerBTopology& layer_b_topology,
    const LayerCTopology& layer_c_topology,
    const CudaLayerCOptions& options,
    const CudaLinearizationIdentity& identity,
    const CudaDeviceLinearizationToken& token,
    const CudaLayerBResult& layer_b,
    CudaLayerCStepResult* result,
    std::string* error) {
  if (result == nullptr || error == nullptr || !initialized_) return false;
  if (!std::isfinite(options.lambda) || options.lambda < 0.0) {
    *error = "Invalid Layer C lambda";
    result->error = *error;
    return false;
  }
  if (options.fault_injection ==
      CudaFaultInjection::kForcePointFactorizationFailure) {
    result->runtime.point_factorization_failures = 1;
    result->runtime.first_point_factorization_failure = 0;
    *error = "Layer C point block Cholesky failed (fault injection)";
    result->error = *error;
    return false;
  }
  if (options.fault_injection ==
          CudaFaultInjection::kForceWorkspaceAllocationFailure ||
      options.layer_b.fault_injection ==
          CudaFaultInjection::kForceWorkspaceAllocationFailure) {
    *error = "INSUFFICIENT_GPU_MEMORY for persistent cuSOLVER workspace "
             "(fault injection)";
    result->error = *error;
    return false;
  }
  if ((!layer_b.compact_device_summary &&
       (layer_b.poses.size() != pose_count_ ||
        layer_b.points.size() != point_count_ ||
        layer_b.edges.size() != edge_count_)) ||
      layer_b_topology.poses.size() != pose_count_ ||
      layer_b_topology.points.size() != point_count_ ||
      layer_b_topology.edges.size() != edge_count_ ||
      layer_c_topology.pose_dimension != pose_dimension_) {
    *error = "persistent Layer B/C topology counts differ";
    result->error = *error;
    return false;
  }
  DeviceLayerBView current = LayerBViewFromToken(token, identity, error);
  if (!current.identity.valid) {
    result->error = *error;
    return false;
  }
  if (device_state_enabled_) {
    DeviceStateView state = CurrentStateView(identity, error);
    if (!state.identity.valid || !ValidateStateBPair(state, current, error)) {
      result->error = *error;
      return false;
    }
  }
  result->pose_dimension = pose_dimension_;
  result->point_dimension = point_count_ * 3;
  const int block_size = options.layer_b.layer_a.block_size;
  const auto blocks_for = [block_size](const size_t count) {
    return static_cast<int>((count + static_cast<size_t>(block_size) - 1) /
                            static_cast<size_t>(block_size));
  };
  const bool mixed_precision =
      arithmetic_precision_ == CudaArithmeticPrecision::kFp32MixedStable;
  cudaError_t schur_residual_status = cudaMemsetAsync(
      d_schur_solve_backward_error_, 0, sizeof(double), stream_);
  if (schur_residual_status != cudaSuccess) {
    *error = "persistent Schur solve residual initialization failed";
    result->error = *error;
    return false;
  }

  AuditCudaEventRecord(events_[2], stream_);
  if (point_count_ != 0) {
    if (mixed_precision) {
      LayerCMixedPointFactorKernel<<<blocks_for(point_count_), block_size, 0,
                                      stream_>>>(
          current.mixed_points, options.lambda, d_point_inverse_,
          d_inverse_gradient_, d_point_status_, point_count_);
      ++runtime_->persistent_device.mixed_fp64_point_inverse_calls;
    } else {
      LayerCPointFactorKernel<<<blocks_for(point_count_), block_size, 0,
                                stream_>>>(
          current.points, options.lambda, d_point_inverse_, d_inverse_gradient_,
          d_point_status_, point_count_);
    }
  }
  AuditCudaEventRecord(events_[3], stream_);
  DeviceLmScalarPacket point_packet{};
  if (device_control_enabled_ && !audit_mirror_enabled_) {
    AuditCudaEventRecord(events_[0], stream_);
    DeviceLmPacketResetKernel<<<1, 1, 0, stream_>>>(
        d_scalar_packet_, context_identity_, identity, layout_id_,
        current.source_state_identity.slot_generation,
        current.identity.slot_generation);
    ++runtime_->persistent_device.diagnostic_kernel_calls;
    LaunchPointStatusReduction(
        d_point_status_, point_count_, d_status_reduce_a_, d_status_reduce_b_,
        d_scalar_packet_, stream_,
        &runtime_->persistent_device.diagnostic_kernel_calls);
    AuditCudaEventRecord(events_[1], stream_);
    const auto packet_start = std::chrono::steady_clock::now();
    if (!DownloadScalarPacket(&point_packet, error) ||
        !Synchronize(CudaSyncSite::kLayerCFactor, error)) {
      result->error = *error;
      return false;
    }
    if (compact_control_enabled_)
      ++runtime_->persistent_device.scalar_factor_status_packet_calls;
    const double packet_elapsed = std::chrono::duration<double, std::milli>(
        std::chrono::steady_clock::now() - packet_start).count();
    const double status_elapsed = EventElapsed(0, 1);
    runtime_->persistent_device.diagnostic_point_status_milliseconds +=
        status_elapsed;
    runtime_->persistent_device.diagnostic_packet_copy_sync_milliseconds +=
        packet_elapsed;
    runtime_->persistent_device.diagnostic_all_added_inclusive_milliseconds +=
        status_elapsed + packet_elapsed;
  } else {
    std::vector<uint8_t> point_status(point_count_, 0);
    if (!DownloadController(d_point_status_, &point_status, error) ||
        !Synchronize(CudaSyncSite::kLayerCFactor, error)) {
      result->error = *error;
      return false;
    }
    for (size_t i = 0; i < point_status.size(); ++i) {
      if (point_status[i] != 0) {
        ++result->runtime.point_factorization_failures;
        if (result->runtime.first_point_factorization_failure < 0)
          result->runtime.first_point_factorization_failure =
              static_cast<int64_t>(i);
      }
    }
  }
  result->runtime.point_kernel_milliseconds = EventElapsed(2, 3);
  if (device_control_enabled_ && !audit_mirror_enabled_) {
    result->runtime.point_factorization_failures =
        point_packet.point_failure_count;
    result->runtime.first_point_factorization_failure =
        point_packet.first_point_failure;
  }
  if (result->runtime.point_factorization_failures != 0) {
    *error = "Layer C point block Cholesky failed at point index=" +
             std::to_string(result->runtime.first_point_factorization_failure);
    result->error = *error;
    return false;
  }
  if (mixed_precision && point_count_ != 0) {
    const size_t inverse_elements = point_count_ * 9;
    LayerCMixedPointInverseToFloatKernel<<<blocks_for(inverse_elements),
                                           block_size, 0, stream_>>>(
        d_point_inverse_, d_mixed_point_inverse_, inverse_elements);
    ++runtime_->persistent_device.mixed_native_fp32_point_inverse_cast_calls;
    runtime_->persistent_device.mixed_native_fp32_point_inverse_cast_bytes =
        SaturatingAdd(
            runtime_->persistent_device
                .mixed_native_fp32_point_inverse_cast_bytes,
            inverse_elements * sizeof(float));
  }

  const bool transformed =
      hot_kernel_implementation_ == HotKernelImplementation::kTransformed;
  double transform_milliseconds = 0.0;
  if (transformed) {
    AuditCudaEventRecord(events_[17], stream_);
    if (edge_count_ != 0) {
      if (mixed_precision) {
        MixedFloatTransformEdgeKernel<<<edge_count_, kTransformedEdgeThreads,
                                        0, stream_>>>(
            current.mixed_edges, d_mixed_point_inverse_,
            d_mixed_transformed_edges_, edge_count_);
        ++runtime_->persistent_device.mixed_native_fp32_transform_calls;
        runtime_->persistent_device.mixed_native_fp32_transform_bytes =
            SaturatingAdd(
                runtime_->persistent_device.mixed_native_fp32_transform_bytes,
                transformed_edge_elements_ * sizeof(float));
      } else {
        LayerCTransformEdgeKernel<<<edge_count_, kTransformedEdgeThreads, 0,
                                    stream_>>>(
            current.edges, d_point_inverse_, d_transformed_edges_, edge_count_);
      }
      ++runtime_->persistent_device.transform_kernel_calls;
    }
    AuditCudaEventRecord(events_[18], stream_);
  }

  const size_t zero_count = std::max(schur_elements_, pose_dimension_);
  AuditCudaEventRecord(events_[4], stream_);
  if (!mixed_precision ||
      ShouldLaunchMixedDenseSchurKernels(pose_dimension_)) {
    LayerCZeroSchurKernel<<<blocks_for(zero_count), block_size, 0, stream_>>>(
        d_schur_, d_rhs_, pose_dimension_);
  }
  AuditCudaEventRecord(events_[8], stream_);
  if (mixed_precision) {
    ++runtime_->persistent_device.mixed_fp64_pose_damping_calls;
  }
  if (pose_count_ != 0) {
    if (mixed_precision) {
      MixedInitializeDoubleSchurKernel<<<pose_count_, 36, 0, stream_>>>(
          d_solve_pose_meta_, current.mixed_poses, options.lambda, d_schur_,
          d_rhs_, pose_dimension_, pose_count_);
    } else {
      LayerCInitializePoseKernel<<<pose_count_, 36, 0, stream_>>>(
          d_solve_pose_meta_, current.poses, options.lambda, d_schur_, d_rhs_,
          pose_dimension_, pose_count_);
    }
  }
  AuditCudaEventRecord(events_[9], stream_);
  const bool segmented = schur_contribution_backend_ ==
      CudaSchurContributionBackend::kSegmentedTransformed;
  const bool contribution_launched = mixed_precision
      ? (segmented && transformed && LaunchLayerCMixedNativeSchurPairChunks(
            layer_c_topology, device_, d_pair_meta_,
            d_segment_direct_pair_indices_, d_schur_segments_,
            d_schur_pair_segment_ranges_, d_pair_contributions_,
            d_solve_pose_meta_, current.mixed_edges,
            d_mixed_transformed_edges_, d_mixed_schur_segment_partials_,
            d_schur_, pose_dimension_, stream_, &result->runtime,
            &runtime_->persistent_device, error))
      : (segmented
      ? LaunchLayerCSegmentedSchurPairChunks(
            layer_c_topology, device_, d_pair_meta_,
            d_segment_direct_pair_indices_, d_schur_segments_,
            d_schur_pair_segment_ranges_, d_pair_contributions_,
            d_solve_pose_meta_, current.edges, d_transformed_edges_,
            d_schur_segment_partials_, d_schur_, pose_dimension_, stream_,
            &result->runtime, &runtime_->persistent_device, error)
      : LaunchLayerCSchurPairChunks(
            layer_c_topology, hot_kernel_implementation_, device_, d_pair_meta_,
            d_pair_contributions_, d_solve_pose_meta_, current.edges,
            d_point_inverse_, d_transformed_edges_, d_schur_, pose_dimension_,
            stream_, &result->runtime, &runtime_->persistent_device, error));
  if (!contribution_launched) {
    if (mixed_precision && error->empty()) {
      *error = "fp32_mixed requires transformed segmented Schur";
    }
    result->error = *error;
    return false;
  }
  AuditCudaEventRecord(events_[5], stream_);
  if (pose_count_ != 0) {
    ++result->runtime.schur_rhs_calls;
    ++runtime_->persistent_device.schur_rhs_calls;
    if (mixed_precision) {
      LayerCMixedRhsKernel<<<pose_count_, 6, 0, stream_>>>(
          d_solve_pose_meta_, d_pose_edges_, current.mixed_edges,
          d_inverse_gradient_, d_rhs_, pose_count_);
      ++runtime_->persistent_device.mixed_fp64_rhs_calls;
    } else {
      LayerCRhsKernel<<<pose_count_, 6, 0, stream_>>>(
          d_solve_pose_meta_, d_pose_edges_, current.edges, d_inverse_gradient_,
          d_rhs_, pose_count_);
    }
  }
  AuditCudaEventRecord(events_[6], stream_);
  cudaError_t cuda_status = cudaGetLastError();
  result->runtime.cuda_launch_status = static_cast<int>(cuda_status);
  if (cuda_status != cudaSuccess) {
    *error = std::string("persistent Layer C Schur launch failed: ") +
             CudaErrorText(cuda_status);
    result->error = *error;
    return false;
  }
  {
    const uint64_t bytes = schur_elements_ * sizeof(double);
    HostPhaseScope timing(CUDA_TIMING_PHASE(d2d_memcpy), bytes);
    cuda_status = cudaMemcpyAsync(d_factor_, d_schur_, bytes,
                                  cudaMemcpyDeviceToDevice, stream_);
  }
  AuditCudaEventRecord(events_[11], stream_);
  if (cuda_status != cudaSuccess) {
    *error = "persistent Layer C Schur preservation copy failed";
    result->error = *error;
    return false;
  }
  cublasStatus_t blas_status = cublasDcopy(
      blas_, static_cast<int>(pose_dimension_), d_rhs_, 1, d_camera_delta_, 1);
  result->runtime.cublas_create_status = CUBLAS_STATUS_SUCCESS;
  result->runtime.cublas_set_stream_status = CUBLAS_STATUS_SUCCESS;
  result->runtime.cublas_copy_status = static_cast<int>(blas_status);
  cusolverStatus_t solver_status = cusolverDnDpotrf(
      solver_, CUBLAS_FILL_MODE_LOWER, static_cast<int>(pose_dimension_),
      d_factor_, static_cast<int>(pose_dimension_), d_workspace_,
      static_cast<int>(workspace_count_), d_solver_info_);
  ++result->runtime.factorization_calls;
  ++runtime_->persistent_device.factorization_calls;
  ++runtime_->persistent_device.dpotrf_calls;
  result->runtime.cusolver_create_status = CUSOLVER_STATUS_SUCCESS;
  result->runtime.cusolver_set_stream_status = CUSOLVER_STATUS_SUCCESS;
  result->runtime.cusolver_buffer_size_status = CUSOLVER_STATUS_SUCCESS;
  result->runtime.cusolver_potrf_status = static_cast<int>(solver_status);
  if (solver_status == CUSOLVER_STATUS_SUCCESS) {
    solver_status = cusolverDnDpotrs(
        solver_, CUBLAS_FILL_MODE_LOWER, static_cast<int>(pose_dimension_), 1,
        d_factor_, static_cast<int>(pose_dimension_), d_camera_delta_,
        static_cast<int>(pose_dimension_), d_solver_info_);
    ++runtime_->persistent_device.dpotrs_calls;
  }
  result->runtime.cusolver_potrs_status = static_cast<int>(solver_status);
  AuditCudaEventRecord(events_[7], stream_);
  std::vector<int> solver_info(1, 0);
  if (!DownloadController(d_solver_info_, &solver_info, error) ||
      !Synchronize(CudaSyncSite::kLayerCSolver, error)) {
    result->error = *error;
    return false;
  }
  result->runtime.cusolver_dev_info = solver_info[0];
  if (blas_status != CUBLAS_STATUS_SUCCESS ||
      solver_status != CUSOLVER_STATUS_SUCCESS || solver_info[0] != 0) {
    *error = "persistent Layer C dense Schur factorization/solve failed";
    result->error = *error;
    return false;
  }
  if (pose_dimension_ != 0) {
    DeviceSchurSolveResidualKernel<<<
        static_cast<int>((pose_dimension_ + kDiagnosticReductionThreads - 1) /
                         kDiagnosticReductionThreads),
        kDiagnosticReductionThreads, 0, stream_>>>(
        d_schur_, d_rhs_, d_camera_delta_, pose_dimension_,
        d_diagnostic_rows_, d_schur_solve_blocks_);
    ++runtime_->persistent_device.diagnostic_kernel_calls;
    LaunchSchurSolveBackwardErrorReduction(
        d_diagnostic_rows_, pose_dimension_, d_schur_solve_blocks_,
        d_diagnostic_reduce_a_, d_diagnostic_reduce_b_,
        d_schur_solve_backward_error_, stream_,
        &runtime_->persistent_device.diagnostic_kernel_calls);
  }
  if (point_count_ != 0) {
    if (mixed_precision) {
      LayerCMixedBackSubstitutionKernel<<<blocks_for(point_count_), block_size,
                                          0, stream_>>>(
          d_solve_point_meta_, d_point_edges_, d_solve_pose_meta_,
          current.mixed_edges, current.mixed_points, d_point_inverse_,
          d_camera_delta_, d_point_delta_, point_count_);
      ++runtime_->persistent_device.mixed_fp64_back_substitution_calls;
    } else {
      LayerCBackSubstitutionKernel<<<blocks_for(point_count_), block_size, 0,
                                     stream_>>>(
          d_solve_point_meta_, d_point_edges_, d_solve_pose_meta_, current.edges,
          current.points, d_point_inverse_, d_camera_delta_, d_point_delta_,
          point_count_);
    }
  }
  AuditCudaEventRecord(events_[10], stream_);
  const bool compact = device_control_enabled_ && !audit_mirror_enabled_;
  if (compact) {
    if (!Synchronize(CudaSyncSite::kLayerCFinal, error)) {
      result->error = *error;
      return false;
    }
  } else {
    result->schur.resize(schur_elements_);
    result->camera_delta.resize(pose_dimension_);
    result->point_delta.resize(point_count_ * 3);
    std::vector<double> schur_solve_backward_error(1, 0.0);
    if (!DownloadDiagnostics(d_schur_, &result->schur, error) ||
        !DownloadDiagnostics(d_camera_delta_, &result->camera_delta, error) ||
        !DownloadDiagnostics(d_point_delta_, &result->point_delta, error) ||
        !DownloadController(d_schur_solve_backward_error_,
                            &schur_solve_backward_error, error) ||
        !Synchronize(CudaSyncSite::kLayerCFinal, error)) {
      result->error = *error;
      return false;
    }
    result->schur_solve_backward_error =
        schur_solve_backward_error.front();
    runtime_->persistent_device.schur_solve_backward_error_last =
        result->schur_solve_backward_error;
    runtime_->persistent_device.schur_solve_backward_error_max = std::max(
        runtime_->persistent_device.schur_solve_backward_error_max,
        result->schur_solve_backward_error);
    const uint64_t schur_bytes = schur_elements_ * sizeof(double);
    const uint64_t delta_bytes =
        (pose_dimension_ + point_count_ * 3) * sizeof(double);
    if (device_control_enabled_) {
      runtime_->persistent_device.audit_mirror_schur_calls += 1;
      runtime_->persistent_device.audit_mirror_schur_bytes = SaturatingAdd(
          runtime_->persistent_device.audit_mirror_schur_bytes, schur_bytes);
      runtime_->persistent_device.audit_mirror_delta_calls += 2;
      runtime_->persistent_device.audit_mirror_delta_bytes = SaturatingAdd(
          runtime_->persistent_device.audit_mirror_delta_bytes, delta_bytes);
    } else {
      runtime_->persistent_device.steady_schur_d2h_calls += 1;
      runtime_->persistent_device.steady_schur_d2h_bytes = SaturatingAdd(
          runtime_->persistent_device.steady_schur_d2h_bytes, schur_bytes);
      runtime_->persistent_device.steady_delta_d2h_calls += 2;
      runtime_->persistent_device.steady_delta_d2h_bytes = SaturatingAdd(
          runtime_->persistent_device.steady_delta_d2h_bytes, delta_bytes);
    }
  }
  result->runtime.point_kernel_milliseconds = EventElapsed(2, 3);
  if (transformed) transform_milliseconds = EventElapsed(17, 18);
  const double pair_milliseconds = EventElapsed(9, 5);
  result->runtime.schur_kernel_milliseconds =
      EventElapsed(4, 5) + transform_milliseconds;
  const double rhs_milliseconds = EventElapsed(5, 6);
  result->runtime.factorization_milliseconds = EventElapsed(6, 7);
  result->runtime.back_substitution_milliseconds = EventElapsed(7, 10);
  if (arithmetic_precision_ ==
      CudaArithmeticPrecision::kFp32MixedStable) {
    runtime_->persistent_device.mixed_point_inverse_milliseconds +=
        result->runtime.point_kernel_milliseconds;
    runtime_->persistent_device.mixed_schur_milliseconds +=
        result->runtime.schur_kernel_milliseconds;
    runtime_->persistent_device.mixed_rhs_milliseconds += rhs_milliseconds;
    runtime_->persistent_device.mixed_back_substitution_milliseconds +=
        result->runtime.back_substitution_milliseconds;
  }
  runtime_->persistent_device.schur_zero_milliseconds += EventElapsed(4, 8);
  runtime_->persistent_device.schur_pose_init_milliseconds +=
      EventElapsed(8, 9);
  runtime_->persistent_device.schur_pair_milliseconds += pair_milliseconds;
  runtime_->persistent_device.schur_contribution_inclusive_milliseconds +=
      pair_milliseconds;
  if (segmented) {
    runtime_->persistent_device.schur_contribution_partial_milliseconds +=
        pair_milliseconds;
  } else {
    runtime_->persistent_device.schur_contribution_direct_milliseconds +=
        pair_milliseconds;
  }
  result->runtime.schur_contribution_inclusive_milliseconds =
      pair_milliseconds;
  result->runtime.schur_contribution_direct_milliseconds =
      segmented ? 0.0 : pair_milliseconds;
  result->runtime.schur_contribution_partial_milliseconds =
      segmented ? pair_milliseconds : 0.0;
  if (transformed) {
    runtime_->persistent_device.transform_kernel_milliseconds +=
        transform_milliseconds;
    runtime_->persistent_device.transformed_pair_kernel_milliseconds +=
        pair_milliseconds;
  }
  runtime_->persistent_device.schur_rhs_milliseconds += EventElapsed(5, 6);
  runtime_->persistent_device.schur_preservation_copy_milliseconds +=
      EventElapsed(6, 11);
  runtime_->persistent_device.schur_factorization_milliseconds +=
      EventElapsed(11, 7);
  runtime_->persistent_device.schur_back_substitution_milliseconds +=
      EventElapsed(7, 10);
  runtime_->persistent_device.schur_total_inclusive_milliseconds +=
      EventElapsed(4, 10) + transform_milliseconds;
  result->runtime.cusolver_workspace_bytes = workspace_count_ * sizeof(double);
  result->runtime.pair_adjacency_bytes =
      layer_c_topology.pair_contributions.size() *
      sizeof(DevicePairContribution);
  result->runtime.resident_bytes =
      runtime_->persistent_device.initialization_allocation_bytes;
  result->runtime.predicted_peak_bytes = result->runtime.resident_bytes;
  RecordCudaEvent(CUDA_TIMING_PHASE(layer_c_point_factor),
                  result->runtime.point_kernel_milliseconds);
  RecordCudaEvent(CUDA_TIMING_PHASE(schur),
                  result->runtime.schur_kernel_milliseconds);
  RecordCudaEvent(CUDA_TIMING_PHASE(rhs), rhs_milliseconds);
  RecordCudaEvent(CUDA_TIMING_PHASE(cusolver),
                  result->runtime.factorization_milliseconds);
  RecordCudaEvent(CUDA_TIMING_PHASE(back_substitution),
                  result->runtime.back_substitution_milliseconds);
  return true;
}

bool GpuBaDeviceContext::RunTrialCost(
    const PackedLayerAState& trial_packed,
    const CudaLayerBOptions& options,
    const CudaLinearizationIdentity& identity,
    const CudaLossMode loss_mode,
    const double loss_scale,
    double* trial_cost,
    double* kernel_milliseconds,
    std::string* error) {
  DeviceLayerAView trial_view;
  CudaRuntimeInfo trial_runtime;
  CudaLinearizationIdentity trial_identity = identity;
  if (!PackAndRunLayerA(trial_packed, options.layer_a, trial_identity, 1,
                        PersistentSlotKind::kLayerATrial, &trial_view,
                        &trial_runtime, error) ||
      !ComputeCost(trial_view, options, loss_mode, loss_scale, trial_cost,
                   kernel_milliseconds, nullptr, error)) {
    InvalidateLayerASlot(1);
    return false;
  }
  InvalidateLayerASlot(1);
  return true;
}

bool GpuBaDeviceContext::BuildDeviceTrialState(
    const Snapshot& host_current,
    const CudaLinearizationIdentity& current_identity,
    const int block_size,
    const bool materialize_host_state,
    Snapshot* trial,
    std::string* error) {
  if (trial == nullptr ||
      host_current.images.size() != image_entity_count_ ||
      host_current.points.size() != point_entity_count_ ||
      host_current.cameras.size() != camera_entity_count_) {
    if (error != nullptr) *error = "device-state trial preparation is invalid";
    return false;
  }
  return BuildDeviceTrialStateImpl(current_identity, block_size,
                                   materialize_host_state, trial,
                                   &host_current, error);
}

bool GpuBaDeviceContext::BuildNativeDeviceTrialState(
    const CudaLinearizationIdentity& current_identity,
    const int block_size,
    std::string* error) {
  return BuildDeviceTrialStateImpl(current_identity, block_size, false,
                                   nullptr, nullptr, error);
}

bool GpuBaDeviceContext::BuildDeviceTrialStateImpl(
    const CudaLinearizationIdentity& current_identity,
    const int block_size,
    const bool materialize_host_state,
    Snapshot* trial,
    const Snapshot* host_current,
    std::string* error) {
  if (!device_state_enabled_ || !state_ready_ || error == nullptr ||
      block_size <= 0 || block_size > 1024 ||
      (materialize_host_state && (trial == nullptr || host_current == nullptr))) {
    if (error != nullptr) *error = "device-state trial preparation is invalid";
    return false;
  }
  DeviceStateView current = CurrentStateView(current_identity, error);
  if (!current.identity.valid) return false;
  InvalidateStateSlot(trial_state_slot_);
  LayerASlot& trial_a = layer_a_slots_[1];
  if (trial_a.identity.valid) InvalidateLayerASlot(1);
  StateSlot& trial_slot = state_slots_[trial_state_slot_];
  trial_slot.identity.linearization = current_identity;
  ++trial_slot.identity.linearization.state_epoch;
  trial_slot.identity.context_identity = context_identity_;
  trial_slot.identity.layout_id = layout_id_;
  trial_slot.identity.slot_generation = ++next_slot_generation_;
  trial_slot.identity.arithmetic_precision = arithmetic_precision_;
  trial_slot.identity.kind = PersistentSlotKind::kStateTrial;
  trial_slot.identity.valid = true;
  cudaError_t status = cudaMemsetAsync(d_state_update_status_, 0,
                                       sizeof(uint32_t), stream_);
  if (status != cudaSuccess) {
    InvalidateStateSlot(trial_state_slot_);
    *error = "device-state status initialization failed";
    return false;
  }
  const auto blocks_for = [block_size](const size_t count) {
    return static_cast<int>((count + static_cast<size_t>(block_size) - 1) /
                            static_cast<size_t>(block_size));
  };
  if (image_entity_count_ != 0) {
    UpdateImageEntityStateKernel<<<blocks_for(image_entity_count_), block_size,
                                   0, stream_>>>(
        current.images, d_image_update_meta_, d_camera_delta_,
        trial_slot.images, d_state_update_status_, image_entity_count_);
  }
  if (point_entity_count_ != 0) {
    UpdatePointEntityStateKernel<<<blocks_for(point_entity_count_), block_size,
                                   0, stream_>>>(
        current.points, d_point_update_meta_, d_point_delta_,
        trial_slot.points, d_state_update_status_, point_entity_count_);
  }
  if (g_state_update_status_override_for_testing != 0 &&
      !g_state_update_status_override_consumed) {
    InjectStateUpdateStatusForTestingKernel<<<1, 1, 0, stream_>>>(
        d_state_update_status_, g_state_update_status_override_for_testing);
    g_state_update_status_override_consumed = true;
  }
  status = cudaGetLastError();
  if (status != cudaSuccess) {
    InvalidateStateSlot(trial_state_slot_);
    *error = std::string("device-state update kernel launch failed: ") +
             CudaErrorText(status);
    return false;
  }
  ++runtime_->persistent_device.state_update_kernel_calls;
  uint32_t host_status = 0;
  {
    HostPhaseScope timing(CUDA_TIMING_PHASE(d2h_memcpy), sizeof(host_status));
    status = cudaMemcpyAsync(&host_status, d_state_update_status_,
                             sizeof(host_status), cudaMemcpyDeviceToHost,
                             stream_);
  }
  const auto download_entities = [&](auto* source, auto* destination) {
    if (destination->empty()) return true;
    const uint64_t bytes = destination->size() * sizeof((*destination)[0]);
    HostPhaseScope timing(CUDA_TIMING_PHASE(d2h_memcpy), bytes);
    const cudaError_t copy_status = cudaMemcpyAsync(
        destination->data(), source, bytes, cudaMemcpyDeviceToHost, stream_);
    if (copy_status != cudaSuccess) return false;
    ++runtime_->persistent_device.trial_entity_state_d2h_calls;
    runtime_->persistent_device.trial_entity_state_d2h_bytes = SaturatingAdd(
        runtime_->persistent_device.trial_entity_state_d2h_bytes, bytes);
    if (device_control_enabled_) {
      ++runtime_->persistent_device.audit_mirror_state_calls;
      runtime_->persistent_device.audit_mirror_state_bytes = SaturatingAdd(
          runtime_->persistent_device.audit_mirror_state_bytes, bytes);
    } else {
      ++runtime_->persistent_device.steady_trial_state_d2h_calls;
      runtime_->persistent_device.steady_trial_state_d2h_bytes = SaturatingAdd(
          runtime_->persistent_device.steady_trial_state_d2h_bytes, bytes);
    }
    return true;
  };
  if (status != cudaSuccess ||
      (materialize_host_state &&
       !download_entities(trial_slot.images, &host_image_entities_)) ||
      (materialize_host_state &&
       !download_entities(trial_slot.points, &host_point_entities_)) ||
      !Synchronize(CudaSyncSite::kLayerCFinal, error)) {
    InvalidateStateSlot(trial_state_slot_);
    if (error->empty()) *error = "device-state trial materialization failed";
    return false;
  }
  if (host_status != 0) {
    InvalidateStateSlot(trial_state_slot_);
    if ((host_status & 3u) != 0 || (host_status & ~15u) != 0) {
      *error = "device-state update produced an invalid mapping (status=" +
               std::to_string(host_status) + ")";
    } else {
      *error = "device-state update produced a nonfinite trial state "
               "(status=" + std::to_string(host_status) + ")";
    }
    return false;
  }
  if (!materialize_host_state) return true;
  *trial = *host_current;
  for (size_t i = 0; i < image_entity_count_; ++i) {
    for (size_t j = 0; j < 4; ++j)
      trial->images[i].qvec[j] = host_image_entities_[i].quaternion[j];
    for (size_t j = 0; j < 3; ++j)
      trial->images[i].tvec[j] = host_image_entities_[i].translation[j];
  }
  for (size_t i = 0; i < point_entity_count_; ++i) {
    for (size_t j = 0; j < 3; ++j)
      trial->points[i].xyz[j] = host_point_entities_[i].xyz[j];
  }
  return true;
}

bool GpuBaDeviceContext::RunDeviceTrialCost(
    const CudaLayerBOptions& options,
    const CudaLinearizationIdentity& trial_identity,
    const CudaLossMode loss_mode,
    const double loss_scale,
    double* trial_cost,
    double* kernel_milliseconds,
    std::string* error) {
  DeviceStateView trial_state = TrialStateView(trial_identity, error);
  if (!trial_state.identity.valid) return false;
  DeviceLayerAView trial_view;
  CudaRuntimeInfo trial_runtime;
  if (!RunLayerAFromDeviceState(
          trial_state, options.layer_a, trial_identity, 1,
          PersistentSlotKind::kLayerATrial, &trial_view, &trial_runtime,
          error) ||
      !ComputeCost(trial_view, options, loss_mode, loss_scale, trial_cost,
                   kernel_milliseconds, nullptr, error)) {
    InvalidateLayerASlot(1);
    return false;
  }
  InvalidateLayerASlot(1);
  return true;
}

bool GpuBaDeviceContext::RunDeviceDiagnostics(
    const CudaLinearizationIdentity& current_identity,
    const CudaDeviceLinearizationToken& token,
    const double lambda,
    CudaLayerCStepResult* result,
    std::string* error) {
  if (!device_control_enabled_ || audit_mirror_enabled_ || result == nullptr ||
      error == nullptr || !std::isfinite(lambda)) {
    if (error != nullptr) *error = "device-control diagnostics are invalid";
    return false;
  }
  DeviceLayerBView layer_b =
      LayerBViewFromToken(token, current_identity, error);
  DeviceStateView current = CurrentStateView(current_identity, error);
  CudaLinearizationIdentity trial_identity = current_identity;
  ++trial_identity.state_epoch;
  DeviceStateView trial = TrialStateView(trial_identity, error);
  if (!layer_b.identity.valid || !current.identity.valid ||
      !trial.identity.valid || !ValidateStateBPair(current, layer_b, error)) {
    return false;
  }
  constexpr int kBlockSize = 128;
  const auto blocks_for = [](const size_t count) {
    return static_cast<int>((count + kBlockSize - 1) / kBlockSize);
  };
  AuditCudaEventRecord(events_[0], stream_);
  DeviceLmPacketResetKernel<<<1, 1, 0, stream_>>>(
      d_scalar_packet_, context_identity_, current_identity, layout_id_,
      current.identity.slot_generation, layer_b.identity.slot_generation);
  ++runtime_->persistent_device.diagnostic_kernel_calls;
  DeviceStoreSchurSolveBackwardErrorKernel<<<1, 1, 0, stream_>>>(
      d_schur_solve_backward_error_, d_scalar_packet_);
  ++runtime_->persistent_device.diagnostic_kernel_calls;
  if (pose_count_ != 0) {
    if (arithmetic_precision_ == CudaArithmeticPrecision::kFp32MixedStable) {
      DeviceLayerCDiagnosticPoseKernelT<
          MixedPoseBlockOutput, MixedEdgeBlockOutput><<<
          pose_count_, kBlockSize, 0, stream_>>>(
          d_solve_pose_meta_, d_pose_edges_, layer_b.mixed_poses,
          layer_b.mixed_edges, d_camera_delta_, d_point_delta_, lambda,
          d_diagnostic_rows_, d_diagnostic_blocks_, pose_count_);
    } else {
      DeviceLayerCDiagnosticPoseKernelT<
          CudaPoseBlockOutput, CudaEdgeBlockOutput><<<
          pose_count_, kBlockSize, 0, stream_>>>(
          d_solve_pose_meta_, d_pose_edges_, layer_b.poses, layer_b.edges,
          d_camera_delta_, d_point_delta_, lambda, d_diagnostic_rows_,
          d_diagnostic_blocks_, pose_count_);
    }
    ++runtime_->persistent_device.diagnostic_kernel_calls;
  }
  AuditCudaEventRecord(events_[1], stream_);
  if (point_count_ != 0) {
    if (arithmetic_precision_ == CudaArithmeticPrecision::kFp32MixedStable) {
      DeviceLayerCDiagnosticPointKernelT<
          MixedPointBlockOutput, MixedEdgeBlockOutput><<<
          blocks_for(point_count_), kBlockSize, 0, stream_>>>(
          d_solve_point_meta_, d_point_edges_, d_solve_pose_meta_,
          layer_b.mixed_points, layer_b.mixed_edges, d_camera_delta_,
          d_point_delta_, lambda, pose_dimension_, d_diagnostic_rows_,
          d_diagnostic_blocks_, pose_count_, point_count_);
    } else {
      DeviceLayerCDiagnosticPointKernelT<
          CudaPointBlockOutput, CudaEdgeBlockOutput><<<
          blocks_for(point_count_), kBlockSize, 0, stream_>>>(
          d_solve_point_meta_, d_point_edges_, d_solve_pose_meta_, layer_b.points,
          layer_b.edges, d_camera_delta_, d_point_delta_, lambda,
          pose_dimension_, d_diagnostic_rows_, d_diagnostic_blocks_,
          pose_count_, point_count_);
    }
    ++runtime_->persistent_device.diagnostic_kernel_calls;
  }
  AuditCudaEventRecord(events_[2], stream_);
  LaunchLayerCDiagnosticReduction(
      d_diagnostic_rows_, diagnostic_row_count_, d_diagnostic_blocks_,
      diagnostic_block_count_, lambda, d_diagnostic_reduce_a_,
      d_diagnostic_reduce_b_, d_scalar_packet_, stream_,
      &runtime_->persistent_device.diagnostic_kernel_calls);
  AuditCudaEventRecord(events_[3], stream_);
  if (pose_count_ != 0) {
    DeviceStateNormPoseKernel<<<blocks_for(pose_count_), kBlockSize, 0,
                                stream_>>>(
        current.images, trial.images, d_pose_image_entity_indices_,
        d_state_norm_partials_, pose_count_);
    ++runtime_->persistent_device.diagnostic_kernel_calls;
  }
  if (point_count_ != 0) {
    DeviceStateNormPointKernel<<<blocks_for(point_count_), kBlockSize, 0,
                                 stream_>>>(
        current.points, trial.points, d_point_entity_indices_,
        d_state_norm_partials_, pose_count_, point_count_);
    ++runtime_->persistent_device.diagnostic_kernel_calls;
  }
  LaunchStateNormReduction(
      d_state_norm_partials_, diagnostic_block_count_, d_sum2_reduce_a_,
      d_sum2_reduce_b_, d_scalar_packet_, stream_,
      &runtime_->persistent_device.diagnostic_kernel_calls);
  AuditCudaEventRecord(events_[4], stream_);
  if (pose_dimension_ != 0) {
    DeviceSchurSymmetryPartialKernel<<<blocks_for(pose_dimension_), kBlockSize,
                                       0, stream_>>>(
        d_schur_, pose_dimension_, d_symmetry_partials_);
    ++runtime_->persistent_device.diagnostic_kernel_calls;
  }
  LaunchMaxReduction(d_symmetry_partials_, pose_dimension_, d_max_reduce_a_,
                     d_max_reduce_b_, d_scalar_packet_, stream_,
                     &runtime_->persistent_device.diagnostic_kernel_calls);
  AuditCudaEventRecord(events_[5], stream_);
  const cudaError_t launch = cudaGetLastError();
  if (launch != cudaSuccess) {
    ++runtime_->persistent_device.diagnostic_reduction_failures;
    *error = std::string("device-control diagnostic launch failed: ") +
             CudaErrorText(launch);
    return false;
  }
  DeviceLmScalarPacket packet{};
  const auto packet_start = std::chrono::steady_clock::now();
  if (!DownloadScalarPacket(&packet, error) ||
      !Synchronize(CudaSyncSite::kLayerCFinal, error)) {
    ++runtime_->persistent_device.diagnostic_reduction_failures;
    return false;
  }
  if (compact_control_enabled_)
    ++runtime_->persistent_device.scalar_trial_packet_calls;
  const double packet_elapsed = std::chrono::duration<double, std::milli>(
      std::chrono::steady_clock::now() - packet_start).count();
  const double pose_elapsed = EventElapsed(0, 1);
  const double point_elapsed = EventElapsed(1, 2);
  const double merge_elapsed = EventElapsed(2, 3);
  const double norm_elapsed = EventElapsed(3, 4);
  const double symmetry_elapsed = EventElapsed(4, 5);
  const double total_elapsed = EventElapsed(0, 5);
  runtime_->persistent_device.diagnostic_pose_partial_milliseconds +=
      pose_elapsed;
  runtime_->persistent_device.diagnostic_point_partial_milliseconds +=
      point_elapsed;
  runtime_->persistent_device.diagnostic_merge_milliseconds += merge_elapsed;
  runtime_->persistent_device.diagnostic_state_norm_milliseconds +=
      norm_elapsed;
  runtime_->persistent_device.diagnostic_symmetry_milliseconds +=
      symmetry_elapsed;
  runtime_->persistent_device.diagnostic_packet_copy_sync_milliseconds +=
      packet_elapsed;
  runtime_->persistent_device.diagnostic_kernel_milliseconds += total_elapsed;
  runtime_->persistent_device.diagnostic_total_inclusive_milliseconds +=
      total_elapsed + packet_elapsed;
  runtime_->persistent_device.diagnostic_all_added_inclusive_milliseconds +=
      total_elapsed + packet_elapsed;
  if (arithmetic_precision_ ==
      CudaArithmeticPrecision::kFp32MixedStable) {
    runtime_->persistent_device.mixed_diagnostics_milliseconds +=
        total_elapsed + packet_elapsed;
  }
  const bool identity_match = packet.valid == 1 && packet.version == 1 &&
      packet.context_identity == context_identity_ &&
      packet.solve_generation == current_identity.solve_generation &&
      packet.state_epoch == current_identity.state_epoch &&
      packet.topology_generation == current_identity.topology_generation &&
      packet.config_generation == current_identity.config_generation &&
      packet.layout_id == layout_id_ &&
      packet.state_slot_generation == current.identity.slot_generation &&
      packet.layer_b_slot_generation == layer_b.identity.slot_generation;
  if (!identity_match || packet.reduction_status != 0 ||
      packet.finite_flags != 0) {
    ++runtime_->persistent_device.diagnostic_reduction_failures;
    *error = identity_match
                 ? "device-control diagnostic reduction is non-finite"
                 : "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
    return false;
  }
  result->backward_error = packet.backward_error;
  result->schur_solve_backward_error = packet.schur_solve_backward_error;
  runtime_->persistent_device.schur_solve_backward_error_last =
      result->schur_solve_backward_error;
  runtime_->persistent_device.schur_solve_backward_error_max = std::max(
      runtime_->persistent_device.schur_solve_backward_error_max,
      result->schur_solve_backward_error);
  result->predicted_reduction = packet.predicted_reduction;
  result->state_norm = packet.state_norm;
  result->step_norm = packet.step_norm;
  result->symmetry_error = packet.symmetry_error;
  return true;
}

bool GpuBaDeviceContext::MaterializeCurrentState(
    const Snapshot& host_template,
    Snapshot* output,
    const bool final_materialization,
    std::string* error) {
  if (!device_state_enabled_ || output == nullptr || error == nullptr ||
      host_template.images.size() != image_entity_count_ ||
      host_template.points.size() != point_entity_count_) {
    if (error != nullptr) *error = "device-state current materialization is invalid";
    return false;
  }
  const StateSlot& current = state_slots_[current_state_slot_];
  if (!current.identity.valid) {
    *error = "device-state current slot is invalid";
    return false;
  }
  if (final_materialization) {
    ++runtime_->persistent_device.final_state_materialization_operations;
  }
  const auto download_entities = [&](auto* source, auto* destination) {
    if (destination->empty()) return true;
    const uint64_t bytes = destination->size() * sizeof((*destination)[0]);
    HostPhaseScope timing(CUDA_TIMING_PHASE(d2h_memcpy), bytes);
    const cudaError_t status = cudaMemcpyAsync(
        destination->data(), source, bytes, cudaMemcpyDeviceToHost, stream_);
    if (status != cudaSuccess) return false;
    if (final_materialization) {
      ++runtime_->persistent_device.final_entity_state_d2h_calls;
      runtime_->persistent_device.final_entity_state_d2h_bytes = SaturatingAdd(
          runtime_->persistent_device.final_entity_state_d2h_bytes, bytes);
      ++runtime_->persistent_device.final_state_d2h_calls;
      runtime_->persistent_device.final_state_d2h_bytes = SaturatingAdd(
          runtime_->persistent_device.final_state_d2h_bytes, bytes);
    }
    return true;
  };
  if (!download_entities(current.images, &host_image_entities_) ||
      !download_entities(current.points, &host_point_entities_) ||
      !Synchronize(CudaSyncSite::kLayerCFinal, error)) {
    if (error->empty()) *error = "device-state current materialization failed";
    return false;
  }
  *output = host_template;
  for (size_t i = 0; i < image_entity_count_; ++i) {
    for (size_t j = 0; j < 4; ++j)
      output->images[i].qvec[j] = host_image_entities_[i].quaternion[j];
    for (size_t j = 0; j < 3; ++j)
      output->images[i].tvec[j] = host_image_entities_[i].translation[j];
  }
  for (size_t i = 0; i < point_entity_count_; ++i) {
    for (size_t j = 0; j < 3; ++j)
      output->points[i].xyz[j] = host_point_entities_[i].xyz[j];
  }
  return true;
}

bool GpuBaDeviceContext::DownloadCurrentNativeState(
    const NativeHostSolveView& view,
    const ActiveStateBuffer& initial_state,
    const CudaLinearizationIdentity& expected,
    DenseActiveState* output,
    std::string* error) {
  if (!device_state_enabled_ || output == nullptr || error == nullptr ||
      view.identity.owner_epoch != initial_state.owner_epoch ||
      native_image_slots_.size() != image_entity_count_ ||
      native_point_slots_.size() != point_entity_count_ ||
      native_camera_slots_.size() != camera_entity_count_) {
    if (error != nullptr) *error = "native final-state download is invalid";
    return false;
  }
  const StateSlot& current = state_slots_[current_state_slot_];
  if (!current.identity.valid ||
      !SameLinearizationIdentity(current.identity.linearization, expected)) {
    *error = "native current device state slot is invalid";
    return false;
  }
  const auto download = [&](auto* source, auto* destination) {
    if (destination->empty()) return true;
    const uint64_t bytes = destination->size() * sizeof((*destination)[0]);
    HostPhaseScope timing(CUDA_TIMING_PHASE(d2h_memcpy), bytes);
    const cudaError_t status = cudaMemcpyAsync(
        destination->data(), source, bytes, cudaMemcpyDeviceToHost, stream_);
    if (status != cudaSuccess) return false;
    ++runtime_->persistent_device.final_entity_state_d2h_calls;
    runtime_->persistent_device.final_entity_state_d2h_bytes = SaturatingAdd(
        runtime_->persistent_device.final_entity_state_d2h_bytes, bytes);
    ++runtime_->persistent_device.final_state_d2h_calls;
    runtime_->persistent_device.final_state_d2h_bytes = SaturatingAdd(
        runtime_->persistent_device.final_state_d2h_bytes, bytes);
    return true;
  };
  ++runtime_->persistent_device.final_state_materialization_operations;
  if (!download(current.images, &host_image_entities_) ||
      !download(current.points, &host_point_entities_) ||
      !Synchronize(CudaSyncSite::kLayerCFinal, error)) {
    if (error->empty()) *error = "native final-state download failed";
    return false;
  }
  std::unordered_map<uint32_t, const DenseCameraState*> initial_cameras;
  if (!BuildNativeStateLookup(initial_state.cameras,
                              initial_state.state_generation,
                              &initial_cameras, error)) {
    return false;
  }
  *output = DenseActiveState();
  output->owner_epoch = initial_state.owner_epoch;
  if (expected.state_epoch >
      std::numeric_limits<uint64_t>::max() - initial_state.state_generation) {
    *error = "native final state generation overflow";
    return false;
  }
  output->state_generation =
      initial_state.state_generation + expected.state_epoch;
  output->cameras.reserve(native_camera_slots_.size());
  for (const uint32_t slot : native_camera_slots_) {
    const auto found = initial_cameras.find(slot);
    if (found == initial_cameras.end()) {
      *error = "native final state is missing fixed camera state";
      return false;
    }
    DenseCameraState camera = *found->second;
    camera.state_generation = output->state_generation;
    output->cameras.push_back(std::move(camera));
  }
  output->images.reserve(native_image_slots_.size());
  for (size_t i = 0; i < native_image_slots_.size(); ++i) {
    DenseImageState image;
    image.image_slot = native_image_slots_[i];
    image.state_generation = output->state_generation;
    std::copy(host_image_entities_[i].quaternion,
              host_image_entities_[i].quaternion + 4,
              image.quaternion.begin());
    std::copy(host_image_entities_[i].translation,
              host_image_entities_[i].translation + 3,
              image.translation.begin());
    output->images.push_back(image);
  }
  output->points.reserve(native_point_slots_.size());
  for (size_t i = 0; i < native_point_slots_.size(); ++i) {
    DensePointState point;
    point.point_slot = native_point_slots_[i];
    point.state_generation = output->state_generation;
    std::copy(host_point_entities_[i].xyz,
              host_point_entities_[i].xyz + 3, point.xyz.begin());
    output->points.push_back(point);
  }
  return true;
}

bool GpuBaDeviceContext::StaleHandleSelfTest(
    const PackedLayerAState& packed,
    const CudaLayerAOptions& options,
    std::string* error) {
  CudaLinearizationIdentity identity;
  identity.solve_generation = solve_generation_;
  identity.state_epoch = 0;
  identity.topology_generation = topology_generation_;
  identity.config_generation = config_generation_;
  DeviceLayerAView first;
  DeviceLayerAView second;
  CudaRuntimeInfo first_runtime;
  CudaRuntimeInfo second_runtime;
  if (!PackAndRunLayerA(packed, options, identity, 0,
                        PersistentSlotKind::kLayerAWorking, &first,
                        &first_runtime, error) ||
      !PackAndRunLayerA(packed, options, identity, 0,
                        PersistentSlotKind::kLayerAWorking, &second,
                        &second_runtime, error) ||
      !Synchronize(CudaSyncSite::kLayerAFinal, error)) {
    return false;
  }
  std::string stale_error;
  const bool stale_accepted = ValidateLayerAView(first, &stale_error);
  const bool current_accepted = ValidateLayerAView(second, error);
  if (stale_accepted || !current_accepted ||
      stale_error != "CURRENT_LINEARIZATION_IDENTITY_MISMATCH") {
    if (error != nullptr) *error = "persistent stale-handle self-test failed";
    return false;
  }
  return true;
}

bool GpuBaDeviceContext::DeviceStateHandleSelfTest(
    const Snapshot& snapshot,
    const CudaLayerBOptions& options,
    std::string* error) {
  if (!device_state_enabled_ || error == nullptr) return false;
  CudaLinearizationIdentity identity;
  identity.solve_generation = solve_generation_;
  identity.state_epoch = 0;
  identity.topology_generation = topology_generation_;
  identity.config_generation = config_generation_;
  CudaLayerBResult layer_b;
  CudaDeviceLinearizationToken token;
  if (!RunLayerBFromDeviceState(
          snapshot, options, identity,
          CudaFaultLogicalSite::kInitialLinearization,
          CudaLossMode::kTrivial, 1.0, &layer_b, &token, error) ||
      !ValidateLinearizationToken(token, identity, error)) {
    return false;
  }
  CudaDeviceLinearizationToken stale = token;
  ++stale.state_slot_generation;
  std::string stale_error;
  const bool stale_accepted =
      ValidateLinearizationToken(stale, identity, &stale_error);
  CudaDeviceLinearizationToken cross_solve = token;
  ++cross_solve.context_identity;
  std::string cross_error;
  const bool cross_accepted =
      ValidateLinearizationToken(cross_solve, identity, &cross_error);
  if (stale_accepted || cross_accepted ||
      stale_error != "CURRENT_LINEARIZATION_IDENTITY_MISMATCH" ||
      cross_error != "CURRENT_LINEARIZATION_IDENTITY_MISMATCH") {
    std::ostringstream message;
    message << "device-state stale/cross-solve handle self-test failed"
            << " stale_accepted=" << stale_accepted
            << " stale_error=" << stale_error
            << " cross_accepted=" << cross_accepted
            << " cross_error=" << cross_error;
    *error = message.str();
    return false;
  }
  return true;
}

bool GpuBaDeviceContext::CaptureMixedLayerAForTesting(
    const CudaLossMode loss_mode,
    const double loss_scale,
    std::vector<double>* reference_values,
    std::vector<double>* mixed_values,
    std::vector<double>* reference_scales,
    std::vector<double>* mixed_scales,
    std::string* error) {
  if (!initialized_ || arithmetic_precision_ !=
                           CudaArithmeticPrecision::kFp32MixedStable ||
      reference_values == nullptr || mixed_values == nullptr ||
      reference_scales == nullptr || mixed_scales == nullptr ||
      error == nullptr || !std::isfinite(loss_scale) || loss_scale <= 0.0) {
    if (error != nullptr) *error = "mixed Layer A test capture is invalid";
    return false;
  }
  const LayerASlot* slot = nullptr;
  for (const LayerASlot& candidate : layer_a_slots_) {
    if (candidate.identity.valid && candidate.mixed_visual != nullptr) {
      slot = &candidate;
      break;
    }
  }
  if (slot == nullptr || slot->compact_visual == nullptr ||
      (lidar_count_ != 0 &&
       (slot->lidar == nullptr || slot->mixed_lidar == nullptr))) {
    *error = "mixed Layer A test capture has no live typed slot";
    return false;
  }
  std::vector<CudaCompactVisualOutput> reference_visual(visual_count_);
  std::vector<MixedVisualOutput> mixed_visual(visual_count_);
  std::vector<CudaLidarOutput> reference_lidar(lidar_count_);
  std::vector<MixedLidarOutput> mixed_lidar(lidar_count_);
  const auto copy = [this](void* destination, const void* source,
                           const uint64_t bytes) {
    return bytes == 0 ||
           cudaMemcpyAsync(destination, source, bytes,
                           cudaMemcpyDeviceToHost, stream_) == cudaSuccess;
  };
  if (!copy(reference_visual.data(), slot->compact_visual,
            visual_count_ * sizeof(CudaCompactVisualOutput)) ||
      !copy(mixed_visual.data(), slot->mixed_visual,
            visual_count_ * sizeof(MixedVisualOutput)) ||
      !copy(reference_lidar.data(), slot->lidar,
            lidar_count_ * sizeof(CudaLidarOutput)) ||
      !copy(mixed_lidar.data(), slot->mixed_lidar,
            lidar_count_ * sizeof(MixedLidarOutput)) ||
      !Synchronize(CudaSyncSite::kLayerBFinal, error)) {
    if (error->empty()) *error = "mixed Layer A test capture failed";
    return false;
  }
  reference_values->clear();
  mixed_values->clear();
  reference_scales->clear();
  mixed_scales->clear();
  reference_values->reserve(visual_count_ * 20 + lidar_count_ * 4);
  mixed_values->reserve(reference_values->capacity());
  reference_scales->reserve(visual_count_ + lidar_count_);
  mixed_scales->reserve(visual_count_ + lidar_count_);
  const auto reference_scale = [loss_mode, loss_scale](const double squared) {
    if (loss_mode != CudaLossMode::kSoftL1) return 1.0;
    const double root = std::sqrt(1.0 + squared / (loss_scale * loss_scale));
    return std::sqrt(std::max(std::numeric_limits<double>::min(),
                              1.0 / root));
  };
  const float float_loss_scale = static_cast<float>(loss_scale);
  const auto mixed_scale = [loss_mode, float_loss_scale](const float squared) {
    if (loss_mode != CudaLossMode::kSoftL1) return 1.0f;
    const float root =
        std::sqrt(1.0f + squared / (float_loss_scale * float_loss_scale));
    return std::sqrt(std::max(std::numeric_limits<float>::min(),
                              1.0f / root));
  };
  for (size_t index = 0; index < visual_count_; ++index) {
    const CudaCompactVisualOutput& reference = reference_visual[index];
    const MixedVisualOutput& candidate = mixed_visual[index];
    if (((reference.status & 1u) != 0) != (candidate.finite != 0)) {
      *error = "mixed visual finite status differs from FP64";
      return false;
    }
    for (size_t row = 0; row < 2; ++row) {
      reference_values->push_back(reference.residual[row]);
      mixed_values->push_back(candidate.residual[row]);
    }
    for (size_t component = 0; component < 12; ++component) {
      reference_values->push_back(reference.pose_jacobian[component]);
      mixed_values->push_back(candidate.pose_jacobian[component]);
    }
    for (size_t component = 0; component < 6; ++component) {
      reference_values->push_back(reference.point_jacobian[component]);
      mixed_values->push_back(candidate.point_jacobian[component]);
    }
    const double reference_squared =
        reference.residual[0] * reference.residual[0] +
        reference.residual[1] * reference.residual[1];
    const float mixed_squared =
        candidate.residual[0] * candidate.residual[0] +
        candidate.residual[1] * candidate.residual[1];
    reference_scales->push_back(reference_scale(reference_squared));
    mixed_scales->push_back(
        static_cast<double>(mixed_scale(mixed_squared)));
  }
  for (size_t index = 0; index < lidar_count_; ++index) {
    const CudaLidarOutput& reference = reference_lidar[index];
    const MixedLidarOutput& candidate = mixed_lidar[index];
    if ((reference.finite != 0) != (candidate.finite != 0)) {
      *error = "mixed LiDAR finite status differs from FP64";
      return false;
    }
    reference_values->push_back(reference.residual);
    mixed_values->push_back(candidate.residual);
    for (size_t component = 0; component < 3; ++component) {
      reference_values->push_back(reference.point_jacobian[component]);
      mixed_values->push_back(candidate.point_jacobian[component]);
    }
    reference_scales->push_back(
        reference_scale(reference.residual * reference.residual));
    mixed_scales->push_back(static_cast<double>(mixed_scale(
        candidate.residual * candidate.residual)));
  }
  return true;
}

bool GpuBaDeviceContext::CaptureLayerCWorkspaceForTesting(
    std::vector<double>* point_inverse,
    std::vector<double>* inverse_gradient,
    std::vector<double>* transformed_edge,
    std::vector<double>* rhs,
    std::string* error) {
  if (!initialized_ || point_inverse == nullptr ||
      inverse_gradient == nullptr || transformed_edge == nullptr ||
      rhs == nullptr || error == nullptr) {
    if (error != nullptr) *error = "Layer C workspace test capture is invalid";
    return false;
  }
  point_inverse->resize(point_count_ * 9);
  inverse_gradient->resize(point_count_ * 3);
  transformed_edge->resize(transformed_edge_elements_);
  rhs->resize(pose_dimension_);
  std::vector<float> mixed_transformed;
  if (arithmetic_precision_ == CudaArithmeticPrecision::kFp32MixedStable) {
    mixed_transformed.resize(transformed_edge_elements_);
  }
  const auto copy = [this](void* destination, const void* source,
                           const uint64_t bytes) {
    return bytes == 0 ||
           cudaMemcpyAsync(destination, source, bytes,
                           cudaMemcpyDeviceToHost, stream_) == cudaSuccess;
  };
  if (!copy(point_inverse->data(), d_point_inverse_,
            point_inverse->size() * sizeof(double)) ||
      !copy(inverse_gradient->data(), d_inverse_gradient_,
            inverse_gradient->size() * sizeof(double)) ||
      !(arithmetic_precision_ == CudaArithmeticPrecision::kFp32MixedStable
            ? copy(mixed_transformed.data(), d_mixed_transformed_edges_,
                   mixed_transformed.size() * sizeof(float))
            : copy(transformed_edge->data(), d_transformed_edges_,
                   transformed_edge->size() * sizeof(double))) ||
      !copy(rhs->data(), d_rhs_, rhs->size() * sizeof(double)) ||
      !Synchronize(CudaSyncSite::kLayerCFinal, error)) {
    if (error->empty()) *error = "Layer C workspace test capture failed";
    return false;
  }
  if (!mixed_transformed.empty()) {
    for (size_t index = 0; index < mixed_transformed.size(); ++index) {
      (*transformed_edge)[index] = mixed_transformed[index];
    }
  }
  return true;
}

bool BeginCudaResourceGeneration(CudaFullLmRuntimeInfo* runtime,
                                 const bool allow_pool_retained,
                                 std::string* error) {
  if (runtime == nullptr || error == nullptr) return false;
  runtime->initial_resource_health = g_cuda_resource_health;
  if (g_cuda_resource_health == CudaResourceHealth::kTainted) {
    if (!g_cuda_taint_cleanup_complete) {
      *error = "CUDA_RESOURCE_CLEANUP_FAILED: resource generation remains "
               "tainted";
      runtime->final_resource_health = CudaResourceHealth::kTainted;
      runtime->resource_generation = g_cuda_resource_generation;
      runtime->resource_cleanup_complete = false;
      return false;
    }
    // A successfully cleared tainted generation is never revived. The next
    // solve starts from a new generation with empty caches.
    ClearCudaAllResourceCaches();
    if (!g_cuda_taint_cleanup_complete || !g_cached_solvers.empty() ||
        !g_cached_blases.empty() || !g_cached_events.empty() ||
        !g_cached_streams.empty() || !g_live_solvers.empty() ||
        !g_live_blases.empty() || !g_live_events.empty() ||
        !g_live_streams.empty() || !g_cuda_buffer_cache.empty() ||
        !g_cuda_live_allocations.empty()) {
      runtime->resource_cleanup_complete = false;
      runtime->final_resource_health = CudaResourceHealth::kTainted;
      *error = "CUDA_RESOURCE_CLEANUP_FAILED: cleared generation remains "
               "quarantined";
      return false;
    }
    g_cuda_resource_health = CudaResourceHealth::kClean;
  }
  for (uint64_t i = 0; i < g_cuda_resource_registry_count; ++i) {
    const CudaResourceOwnershipEntry& entry =
        g_cuda_resource_registry[static_cast<size_t>(i)];
    if (entry.active && !(allow_pool_retained && entry.pool_retained)) {
      g_cuda_resource_health = CudaResourceHealth::kTainted;
      g_cuda_taint_cleanup_complete = false;
      runtime->resource_cleanup_complete = false;
      runtime->final_resource_health = CudaResourceHealth::kTainted;
      *error = "CUDA_RESOURCE_CLEANUP_FAILED: active ownership entry at solve "
               "begin";
      return false;
    }
  }
  if (allow_pool_retained) {
    uint64_t write = 0;
    for (uint64_t i = 0; i < g_cuda_resource_registry_count; ++i) {
      const CudaResourceOwnershipEntry& entry =
          g_cuda_resource_registry[static_cast<size_t>(i)];
      if (entry.active && entry.pool_retained) {
        g_cuda_resource_registry[static_cast<size_t>(write++)] = entry;
      }
    }
    g_cuda_resource_registry_count = write;
  } else {
    g_cuda_resource_registry_count = 0;
  }
  ++runtime->resource_generation_advance_events;
  if (runtime->resource_generation_advance_events != 1) {
    ++runtime->resource_generation_advance_violations;
    runtime->resource_generation_advanced_by_this_solve = false;
    runtime->final_resource_health = CudaResourceHealth::kTainted;
    g_cuda_resource_health = CudaResourceHealth::kTainted;
    g_cuda_taint_cleanup_complete = false;
    runtime->resource_cleanup_complete = false;
    *error = "CUDA_RESOURCE_GENERATION_DOUBLE_ADVANCE";
    return false;
  }
  ++g_cuda_resource_generation;
  g_cuda_resource_lookup_blocked_count = 0;
  runtime->resource_generation = g_cuda_resource_generation;
  runtime->final_resource_health = g_cuda_resource_health;
  runtime->resource_generation_advanced_by_this_solve = true;
  runtime->resource_cleanup_complete = true;
  return true;
}

bool TaintAndClearCudaResources(const bool force_cleanup_failure,
                                CudaFullLmRuntimeInfo* runtime,
                                std::string* error) {
  if (runtime == nullptr || error == nullptr) return false;
  g_cuda_resource_health = CudaResourceHealth::kTainted;
  g_cuda_taint_cleanup_complete = false;
  runtime->resource_cleanup_complete = false;
  ++runtime->resource_taint_count;
  ++runtime->resource_cleanup_attempts;
  EnableCudaBufferReuse(false);
  // Pool entries contain runtime resources only. Once the global generation
  // is tainted, no active or idle lease may be returned or reused; the common
  // ownership registry below performs the actual teardown exactly once.
  BeginRuntimePoolGlobalClear();
  g_cuda_resource_health = CudaResourceHealth::kClearing;
  // The wrappers atomically clear this optimistic value on the first failure.
  g_cuda_taint_cleanup_complete = true;
  runtime->resource_cleanup_complete = true;
  ClearCudaAllResourceCaches();
  // Even successful teardown leaves the old generation tainted. Only the next
  // solve may create a clean generation.
  g_cuda_resource_health = CudaResourceHealth::kTainted;
  if (force_cleanup_failure) {
    g_cuda_taint_cleanup_complete = false;
    runtime->resource_cleanup_complete = false;
    ++runtime->resource_cleanup_failures;
    runtime->final_resource_health = CudaResourceHealth::kTainted;
    FinishRuntimePoolGlobalClear(false);
    *error = "CUDA_RESOURCE_CLEANUP_FAILED: injected teardown failure";
    return false;
  }
  if (!g_cuda_taint_cleanup_complete || !g_cached_solvers.empty() ||
      !g_cached_blases.empty() || !g_cached_events.empty() ||
      !g_cached_streams.empty() || !g_live_solvers.empty() ||
      !g_live_blases.empty() || !g_live_events.empty() ||
      !g_live_streams.empty() || !g_cuda_buffer_cache.empty() ||
      !g_cuda_live_allocations.empty()) {
    ++runtime->resource_cleanup_failures;
    runtime->resource_cleanup_complete = false;
    runtime->final_resource_health = CudaResourceHealth::kTainted;
    FinishRuntimePoolGlobalClear(false);
    *error = "CUDA_RESOURCE_CLEANUP_FAILED: teardown wrapper failed";
    return false;
  }
  ++runtime->resource_cleanup_successes;
  runtime->final_resource_health = CudaResourceHealth::kTainted;
  FinishRuntimePoolGlobalClear(true);
  return true;
}

bool ApplyLayerCStep(const Snapshot& snapshot,
                     const CudaLayerBResult& layer_b,
                     const LayerCTopology& topology,
                     const std::vector<double>& camera_delta,
                     const std::vector<double>& point_delta,
                     Snapshot* trial,
                     std::string* error) {
  HostPhaseScope timing(CUDA_TIMING_PHASE(apply_layer_c_step));
  *trial = snapshot;
  std::unordered_map<uint32_t, ImageSnapshot*> images;
  std::unordered_map<uint64_t, PointSnapshot*> points;
  for (ImageSnapshot& image : trial->images) images.emplace(image.image_id, &image);
  for (PointSnapshot& point : trial->points)
    points.emplace(point.point3D_id, &point);
  for (size_t pose_index = 0; pose_index < layer_b.poses.size(); ++pose_index) {
    const CudaPoseBlockOutput& pose = layer_b.poses[pose_index];
    const DeviceSolvePoseMeta& meta = topology.poses[pose_index];
    const auto image_it = images.find(pose.image_id);
    if (image_it == images.end()) {
      *error = "Layer C trial update references missing image";
      return false;
    }
    std::array<double, 3> rotation{{camera_delta[meta.offset + 0],
                                    camera_delta[meta.offset + 1],
                                    camera_delta[meta.offset + 2]}};
    std::array<double, 4> updated;
    if (!QuaternionPlusCeres14(image_it->second->qvec, rotation, &updated)) {
      *error = "Layer C trial QuaternionPlus failed";
      return false;
    }
    image_it->second->qvec = updated;
    for (uint32_t index = 3; index < pose.dimension; ++index) {
      const int translation = pose.free_translation_indices[index - 3];
      image_it->second->tvec[translation] += camera_delta[meta.offset + index];
    }
  }
  for (size_t point_index = 0; point_index < layer_b.points.size();
       ++point_index) {
    const auto point_it =
        points.find(layer_b.points[point_index].point3D_id);
    if (point_it == points.end()) {
      *error = "Layer C trial update references missing point";
      return false;
    }
    for (size_t i = 0; i < 3; ++i)
      point_it->second->xyz[i] += point_delta[point_index * 3 + i];
  }
  return true;
}

bool ComputeLayerCDiagnostics(const CudaLayerBResult& layer_b,
                              const LayerCTopology& topology,
                              double lambda,
                              const std::vector<double>& camera_delta,
                              const std::vector<double>& point_delta,
                              double* backward_error,
                              double* predicted_reduction,
                              std::string* error) {
  HostPhaseScope timing(CUDA_TIMING_PHASE(compute_layer_c_diagnostics));
  std::vector<double> camera_residual(topology.pose_dimension, 0.0);
  std::vector<double> point_residual(layer_b.points.size() * 3, 0.0);
  std::vector<double> camera_row_sum(topology.pose_dimension, 0.0);
  std::vector<double> point_row_sum(layer_b.points.size() * 3, 0.0);
  double gradient_norm = 0.0;
  double delta_norm = 0.0;
  double damping_quadratic = 0.0;
  double gradient_dot_delta = 0.0;
  for (size_t pose_index = 0; pose_index < layer_b.poses.size(); ++pose_index) {
    const CudaPoseBlockOutput& pose = layer_b.poses[pose_index];
    const DeviceSolvePoseMeta& meta = topology.poses[pose_index];
    for (uint32_t row = 0; row < pose.dimension; ++row) {
      camera_residual[meta.offset + row] = pose.gradient[row];
      gradient_norm = fmax(gradient_norm, fabs(pose.gradient[row]));
      delta_norm = fmax(delta_norm, fabs(camera_delta[meta.offset + row]));
      damping_quadratic += pose.damping[row] *
                           camera_delta[meta.offset + row] *
                           camera_delta[meta.offset + row];
      gradient_dot_delta +=
          pose.gradient[row] * camera_delta[meta.offset + row];
      for (uint32_t col = 0; col < pose.dimension; ++col) {
        double value = pose.hessian[row * pose.dimension + col];
        if (row == col) value += lambda * pose.damping[row];
        camera_residual[meta.offset + row] +=
            value * camera_delta[meta.offset + col];
        camera_row_sum[meta.offset + row] += fabs(value);
      }
    }
  }
  for (size_t point_index = 0; point_index < layer_b.points.size();
       ++point_index) {
    const CudaPointBlockOutput& point = layer_b.points[point_index];
    for (size_t row = 0; row < 3; ++row) {
      point_residual[point_index * 3 + row] = point.gradient[row];
      gradient_norm = fmax(gradient_norm, fabs(point.gradient[row]));
      delta_norm =
          fmax(delta_norm, fabs(point_delta[point_index * 3 + row]));
      damping_quadratic += point.damping[row] *
                           point_delta[point_index * 3 + row] *
                           point_delta[point_index * 3 + row];
      gradient_dot_delta +=
          point.gradient[row] * point_delta[point_index * 3 + row];
      for (size_t col = 0; col < 3; ++col) {
        double value = point.hessian[row * 3 + col];
        if (row == col) value += lambda * point.damping[row];
        point_residual[point_index * 3 + row] +=
            value * point_delta[point_index * 3 + col];
        point_row_sum[point_index * 3 + row] += fabs(value);
      }
    }
  }
  for (const CudaEdgeBlockOutput& edge : layer_b.edges) {
    const DeviceSolvePoseMeta& pose = topology.poses[edge.pose_index];
    for (uint32_t row = 0; row < pose.dimension; ++row) {
      for (size_t col = 0; col < 3; ++col) {
        const double value = edge.value[row * 3 + col];
        camera_residual[pose.offset + row] +=
            value * point_delta[edge.point_index * 3 + col];
        camera_row_sum[pose.offset + row] += fabs(value);
        point_residual[edge.point_index * 3 + col] +=
            value * camera_delta[pose.offset + row];
        point_row_sum[edge.point_index * 3 + col] += fabs(value);
      }
    }
  }
  double residual_norm = 0.0;
  double hessian_norm = 0.0;
  for (double value : camera_residual)
    residual_norm = fmax(residual_norm, fabs(value));
  for (double value : point_residual)
    residual_norm = fmax(residual_norm, fabs(value));
  for (double value : camera_row_sum)
    hessian_norm = fmax(hessian_norm, value);
  for (double value : point_row_sum)
    hessian_norm = fmax(hessian_norm, value);
  const double denominator = hessian_norm * delta_norm + gradient_norm;
  *backward_error = denominator == 0.0 ? 0.0 : residual_norm / denominator;
  *predicted_reduction =
      0.5 * (lambda * damping_quadratic - gradient_dot_delta);
  if (!std::isfinite(*backward_error) ||
      !std::isfinite(*predicted_reduction)) {
    *error = "Layer C backward error or predicted reduction is non-finite";
    return false;
  }
  return true;
}

bool ComputeCudaCost(const CostLayout& cost_layout,
                     const LayerAOutputView& layer_a_view,
                     const CudaLossMode loss_mode,
                     const double loss_scale,
                     const CudaLayerBOptions& options,
                     double* cost,
                     double* kernel_milliseconds,
                     std::string* error) {
  if (g_cuda_solve_call_counters != nullptr)
    ++g_cuda_solve_call_counters->cost;
  if (g_cuda_timing_sink != nullptr) ++g_cuda_timing_sink->cost_calls;
  if (layer_a_view.output == nullptr ||
      layer_a_view.layout_id != cost_layout.layout_id) {
    *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
    return false;
  }
  const CudaLayerAResult& layer_a = *layer_a_view.output;
  const std::vector<DeviceCostEntry>& cost_order = cost_layout.entries;
  if (layer_a.visual.size() != cost_layout.visual_count ||
      layer_a.lidar.size() != cost_layout.lidar_count ||
      cost_order.size() != cost_layout.visual_count + cost_layout.lidar_count) {
    *error = "cost input/output residual counts differ";
    return false;
  }
  HostPhaseScope timing(CUDA_TIMING_PHASE(trial_cost));
  const CudaMemoryMode memory_mode = options.layer_a.memory_mode;
  cudaError_t memory_status = cudaSetDevice(options.layer_a.device);
  size_t free_bytes = 0;
  size_t total_bytes = 0;
  if (memory_status == cudaSuccess) {
    memory_status = cudaMemGetInfo(&free_bytes, &total_bytes);
  }
  if (options.memory_budget_override_bytes != 0) {
    free_bytes = std::min<uint64_t>(
        free_bytes, options.memory_budget_override_bytes);
  }
  (void)total_bytes;
  const uint64_t predicted_bytes =
      cost_order.size() * sizeof(DeviceCostEntry) +
      layer_a.visual.size() * sizeof(CudaVisualOutput) +
      layer_a.lidar.size() * sizeof(CudaLidarOutput) + sizeof(double);
  const int worker_count = options.reduction_mode ==
                                   CudaReductionMode::kParallelDeterministic
                               ? std::min(1024, std::max(1,
                                     options.cost_reduction_threads))
                               : 1;
  const uint64_t reduction_bytes =
      static_cast<uint64_t>(worker_count) * sizeof(double);
  const uint64_t predicted_bytes_with_reduction =
      predicted_bytes + reduction_bytes;
  const uint64_t reserve = std::max<uint64_t>(
      512ull * 1024ull * 1024ull, predicted_bytes / 4);
  if (options.fault_injection ==
          CudaFaultInjection::kForceInsufficientMemory ||
      memory_status != cudaSuccess ||
      !HasCudaMemoryHeadroom(free_bytes, predicted_bytes_with_reduction,
                             reserve)) {
    std::ostringstream message;
    message << "INSUFFICIENT_GPU_MEMORY before cost allocation predicted="
            << predicted_bytes << " reserve=" << reserve
            << " reduction_workers=" << worker_count
            << " free=" << free_bytes;
    *error = message.str();
    return false;
  }
  cudaStream_t stream = nullptr;
  cudaEvent_t begin = nullptr;
  cudaEvent_t end = nullptr;
  DeviceCostEntry* d_order = nullptr;
  CudaVisualOutput* d_visual = nullptr;
  CudaLidarOutput* d_lidar = nullptr;
  double* d_cost = nullptr;
  double* d_partials = nullptr;
  auto cleanup = [&]() {
    ReleaseCudaEvent(begin);
    ReleaseCudaEvent(end);
    ReleaseCudaStream(stream);
    Release(d_order);
    Release(d_visual);
    Release(d_lidar);
    Release(d_cost);
    Release(d_partials);
    return CudaCleanupSucceeded(error);
  };
  cudaError_t status = AcquireCudaStream(&stream);
  if (status != cudaSuccess ||
      !Allocate(&d_order, cost_order.size(), memory_mode, error) ||
      !Allocate(&d_visual, layer_a.visual.size(), memory_mode, error) ||
      !Allocate(&d_lidar, layer_a.lidar.size(), memory_mode, error) ||
      !Allocate(&d_cost, 1, memory_mode, error) ||
      !Allocate(&d_partials, static_cast<size_t>(worker_count), memory_mode,
                error)) {
    if (status != cudaSuccess)
      *error = std::string("trial cost stream creation failed: ") +
               CudaErrorText(status);
    cleanup();
    return false;
  }
  CudaTransferBatchAudit h2d_batch(
      stream, memory_mode == CudaMemoryMode::kExplicitDeviceCopy
                  ? CUDA_TIMING_PHASE(h2d_memcpy)
                  : nullptr);
  if (!h2d_batch.Begin(error)) {
    cleanup();
    return false;
  }
  if (!CopyToDevice(d_order, cost_order, memory_mode, stream, error) ||
      !CopyToDevice(d_visual, layer_a.visual, memory_mode, stream, error) ||
      !CopyToDevice(d_lidar, layer_a.lidar, memory_mode, stream, error) ||
      !h2d_batch.End(error)) {
    cleanup();
    return false;
  }
  status = AcquireCudaEvent(&begin);
  if (status == cudaSuccess) status = AcquireCudaEvent(&end);
  if (status != cudaSuccess) {
    *error = "trial cost event creation failed";
    cleanup();
    return false;
  }
  AuditCudaEventRecord(begin, stream);
  if (options.reduction_mode == CudaReductionMode::kParallelDeterministic) {
    LayerCCostPartialKernel<<<1, worker_count, 0, stream>>>(
        d_order, cost_order.size(), d_visual, false, d_lidar,
        static_cast<uint8_t>(loss_mode), loss_scale, d_partials);
    LayerCCostOrderedReduceKernel<<<1, 1, 0, stream>>>(
        d_partials, static_cast<size_t>(worker_count), d_cost);
  } else {
    LayerCCostKernel<<<1, 1, 0, stream>>>(
        d_order, cost_order.size(), d_visual, false, d_lidar,
        static_cast<uint8_t>(loss_mode), loss_scale,
        options.cost_reduction_threads, d_cost);
  }
  status = cudaGetLastError();
  if (status != cudaSuccess) {
    *error = std::string("trial cost kernel launch failed: ") +
             CudaErrorText(status);
    cleanup();
    return false;
  }
  AuditCudaEventRecord(end, stream);
  std::vector<double> host_cost(1, 0.0);
  CudaTransferBatchAudit d2h_batch(stream,
                                   CUDA_TIMING_PHASE(d2h_memcpy));
  if (!d2h_batch.Begin(error)) {
    cleanup();
    return false;
  }
  if (!CopyFromDevice(d_cost, &host_cost, memory_mode, stream, error)) {
    cleanup();
    return false;
  }
  if (!d2h_batch.End(error)) {
    cleanup();
    return false;
  }
  status = TimedCudaStreamSynchronize(stream,
                                      CudaSyncSite::kTrialCostFinal);
  if (status != cudaSuccess) {
    *error = std::string("trial cost synchronization failed: ") +
             CudaErrorText(status);
    cleanup();
    return false;
  }
  if (!h2d_batch.CompleteAfterExistingSync(error) ||
      !d2h_batch.CompleteAfterExistingSync(error)) {
    cleanup();
    return false;
  }
  float elapsed = 0.0f;
  AuditCudaEventElapsedTime(&elapsed, begin, end);
  *kernel_milliseconds = elapsed;
  AccumulateCudaEvent(CUDA_TIMING_PHASE(trial_cost),
                      *kernel_milliseconds);
  *cost = host_cost[0];
  if (!h2d_batch.Close(error) || !d2h_batch.Close(error) || !cleanup())
    return false;
  if (!std::isfinite(*cost)) {
    *error = "trial cost reduction produced a non-finite value";
    return false;
  }
  return true;
}

void CaptureFrozenJacobiScaling(const CudaLayerBResult& layer_b,
                                CudaLayerBOptions* options) {
  options->frozen_pose_jacobi_scaling.assign(layer_b.poses.size() * 6, 0.0);
  options->frozen_point_jacobi_scaling.assign(layer_b.points.size() * 3, 0.0);
  for (size_t pose = 0; pose < layer_b.poses.size(); ++pose) {
    for (uint32_t i = 0; i < layer_b.poses[pose].dimension; ++i) {
      options->frozen_pose_jacobi_scaling[pose * 6 + i] =
          layer_b.poses[pose].jacobi_scaling[i];
    }
  }
  for (size_t point = 0; point < layer_b.points.size(); ++point) {
    for (size_t i = 0; i < 3; ++i) {
      options->frozen_point_jacobi_scaling[point * 3 + i] =
          layer_b.points[point].jacobi_scaling[i];
    }
  }
}

void ComputeLmDiagonalRange(const CudaLayerBResult& layer_b,
                            double radius,
                            double* minimum,
                            double* maximum) {
  if (layer_b.compact_device_summary) {
    const double inverse_sqrt_radius = 1.0 / std::sqrt(radius);
    *minimum = layer_b.lm_diagonal_base_min * inverse_sqrt_radius;
    *maximum = layer_b.lm_diagonal_base_max * inverse_sqrt_radius;
    return;
  }
  *minimum = std::numeric_limits<double>::max();
  *maximum = 0.0;
  for (const CudaPoseBlockOutput& pose : layer_b.poses) {
    for (uint32_t i = 0; i < pose.dimension; ++i) {
      const double value = std::sqrt(
          pose.damping[i] * pose.jacobi_scaling[i] *
          pose.jacobi_scaling[i] / radius);
      *minimum = std::min(*minimum, value);
      *maximum = std::max(*maximum, value);
    }
  }
  for (const CudaPointBlockOutput& point : layer_b.points) {
    for (size_t i = 0; i < 3; ++i) {
      const double value = std::sqrt(
          point.damping[i] * point.jacobi_scaling[i] *
          point.jacobi_scaling[i] / radius);
      *minimum = std::min(*minimum, value);
      *maximum = std::max(*maximum, value);
    }
  }
  if (*minimum == std::numeric_limits<double>::max()) *minimum = 0.0;
}

bool AmbientStateAndDifferenceNorm(const Snapshot& state,
                                   const Snapshot* trial,
                                   const CudaLayerBResult& layout,
                                   double* state_norm,
                                   double* difference_norm,
                                   std::string* error) {
  std::unordered_map<uint32_t, const ImageSnapshot*> state_images;
  std::unordered_map<uint64_t, const PointSnapshot*> state_points;
  std::unordered_map<uint32_t, const ImageSnapshot*> trial_images;
  std::unordered_map<uint64_t, const PointSnapshot*> trial_points;
  for (const ImageSnapshot& image : state.images)
    state_images.emplace(image.image_id, &image);
  for (const PointSnapshot& point : state.points)
    state_points.emplace(point.point3D_id, &point);
  if (trial != nullptr) {
    for (const ImageSnapshot& image : trial->images)
      trial_images.emplace(image.image_id, &image);
    for (const PointSnapshot& point : trial->points)
      trial_points.emplace(point.point3D_id, &point);
  }
  long double state_squared = 0.0;
  long double difference_squared = 0.0;
  for (const CudaPoseBlockOutput& pose : layout.poses) {
    const auto state_it = state_images.find(pose.image_id);
    if (state_it == state_images.end()) {
      *error = "LM norm references a missing variable image";
      return false;
    }
    const ImageSnapshot& lhs = *state_it->second;
    for (double value : lhs.qvec) state_squared += value * value;
    for (double value : lhs.tvec) state_squared += value * value;
    if (trial != nullptr) {
      const auto trial_it = trial_images.find(pose.image_id);
      if (trial_it == trial_images.end()) {
        *error = "LM trial norm references a missing variable image";
        return false;
      }
      for (size_t i = 0; i < 4; ++i) {
        const double difference = lhs.qvec[i] - trial_it->second->qvec[i];
        difference_squared += difference * difference;
      }
      for (size_t i = 0; i < 3; ++i) {
        const double difference = lhs.tvec[i] - trial_it->second->tvec[i];
        difference_squared += difference * difference;
      }
    }
  }
  for (const CudaPointBlockOutput& point : layout.points) {
    const auto state_it = state_points.find(point.point3D_id);
    if (state_it == state_points.end()) {
      *error = "LM norm references a missing variable point";
      return false;
    }
    for (double value : state_it->second->xyz) state_squared += value * value;
    if (trial != nullptr) {
      const auto trial_it = trial_points.find(point.point3D_id);
      if (trial_it == trial_points.end()) {
        *error = "LM trial norm references a missing variable point";
        return false;
      }
      for (size_t i = 0; i < 3; ++i) {
        const double difference =
            state_it->second->xyz[i] - trial_it->second->xyz[i];
        difference_squared += difference * difference;
      }
    }
  }
  *state_norm = std::sqrt(static_cast<double>(state_squared));
  *difference_norm = std::sqrt(static_cast<double>(difference_squared));
  return std::isfinite(*state_norm) && std::isfinite(*difference_norm);
}

bool IsRecoverableFactorizationFailure(const std::string& error) {
  return error.find("point block Cholesky failed") != std::string::npos ||
         error.find("dense Schur factorization/solve failed") !=
             std::string::npos;
}

bool IsRecoverableNonfiniteTrialState(const std::string& error) {
  return error.find("device-state update produced a nonfinite trial state") !=
         std::string::npos;
}

void AccumulateLayerBRuntime(const CudaLayerBResult& layer_b,
                             CudaFullLmRuntimeInfo* total) {
  total->layer_a_kernel_milliseconds +=
      layer_b.layer_a.runtime.kernel_milliseconds;
  total->layer_b_kernel_milliseconds +=
      layer_b.runtime.assembly_kernel_milliseconds;
  total->cost_reduction_kernel_milliseconds +=
      layer_b.runtime.cost_kernel_milliseconds;
  total->gradient_reduction_kernel_milliseconds +=
      layer_b.runtime.gradient_kernel_milliseconds;
  total->copy_milliseconds += layer_b.layer_a.runtime.copy_milliseconds +
                              layer_b.runtime.copy_milliseconds;
  total->peak_active_bytes = std::max(
      total->peak_active_bytes,
      std::max(layer_b.layer_a.runtime.active_bytes,
               layer_b.runtime.active_bytes));
  total->peak_cached_bytes = std::max(
      total->peak_cached_bytes,
      std::max(layer_b.layer_a.runtime.cached_bytes,
               layer_b.runtime.cached_bytes));
  total->peak_resident_bytes = std::max(
      total->peak_resident_bytes,
      std::max(layer_b.layer_a.runtime.active_bytes +
                   layer_b.layer_a.runtime.cached_bytes,
               layer_b.runtime.resident_bytes));
  total->peak_predicted_bytes = std::max(
      total->peak_predicted_bytes,
      std::max(layer_b.layer_a.runtime.active_bytes +
                   layer_b.layer_a.runtime.cached_bytes,
               std::max(layer_b.runtime.resident_bytes,
                        layer_b.runtime.predicted_peak_bytes)));
}

void AccumulateLayerCRuntime(const CudaLayerCStepResult& step,
                             CudaFullLmRuntimeInfo* total) {
  total->point_kernel_milliseconds += step.runtime.point_kernel_milliseconds;
  total->schur_kernel_milliseconds += step.runtime.schur_kernel_milliseconds;
  total->factorization_milliseconds +=
      step.runtime.factorization_milliseconds;
  total->back_substitution_milliseconds +=
      step.runtime.back_substitution_milliseconds;
  total->trial_cost_kernel_milliseconds +=
      step.runtime.trial_cost_kernel_milliseconds;
  total->allocation_milliseconds += step.runtime.allocation_milliseconds;
  total->copy_milliseconds += step.runtime.copy_milliseconds;
  total->synchronization_milliseconds +=
      step.runtime.synchronization_milliseconds;
  total->peak_predicted_bytes =
      std::max(total->peak_predicted_bytes,
               std::max(step.runtime.predicted_peak_bytes,
                        step.runtime.resident_bytes));
  total->peak_active_bytes =
      std::max(total->peak_active_bytes, step.runtime.active_bytes);
  total->peak_cached_bytes =
      std::max(total->peak_cached_bytes, step.runtime.cached_bytes);
  total->peak_resident_bytes =
      std::max(total->peak_resident_bytes, step.runtime.resident_bytes);
  if (total->minimum_free_bytes == 0) {
    total->minimum_free_bytes = step.runtime.free_bytes_before;
  } else {
    total->minimum_free_bytes =
        std::min(total->minimum_free_bytes, step.runtime.free_bytes_before);
  }
}

void AddPhaseTiming(CudaPhaseTiming* destination,
                    const CudaPhaseTiming& source) {
  destination->host_wall_milliseconds += source.host_wall_milliseconds;
  destination->cuda_event_milliseconds += source.cuda_event_milliseconds;
  destination->calls = SaturatingAdd(destination->calls, source.calls);
  destination->bytes = SaturatingAdd(destination->bytes, source.bytes);
}

void AddTimingLedger(CudaTimingLedger* destination,
                     const CudaTimingLedger& source) {
#define ADD_PHASE(name) AddPhaseTiming(&destination->name, source.name)
  ADD_PHASE(layer_a_call);
  ADD_PHASE(layer_b_call);
  ADD_PHASE(layer_c_call);
  ADD_PHASE(build_cuda_layer_a_inputs);
  ADD_PHASE(topology_lookup);
  ADD_PHASE(topology_build);
  ADD_PHASE(topology_refresh);
  ADD_PHASE(topology_cache);
  ADD_PHASE(build_cost_order);
  ADD_PHASE(allocation);
  ADD_PHASE(free);
  ADD_PHASE(h2d_memcpy);
  ADD_PHASE(d2h_memcpy);
  ADD_PHASE(d2d_memcpy);
  ADD_PHASE(managed_prefetch);
  ADD_PHASE(layer_a_kernel);
  ADD_PHASE(layer_b_pose_kernel);
  ADD_PHASE(layer_b_point_kernel);
  ADD_PHASE(layer_b_edge_kernel);
  ADD_PHASE(layer_b_gradient_kernel);
  ADD_PHASE(layer_c_point_factor);
  ADD_PHASE(schur);
  ADD_PHASE(rhs);
  ADD_PHASE(cusolver);
  ADD_PHASE(back_substitution);
  ADD_PHASE(back_substitution_host_self);
  ADD_PHASE(trial_cost);
  ADD_PHASE(apply_layer_c_step);
  ADD_PHASE(compute_layer_c_diagnostics);
  ADD_PHASE(lm_decision);
  ADD_PHASE(synchronization);
  ADD_PHASE(state_hash);
  ADD_PHASE(topology_fingerprint_audit);
  ADD_PHASE(controller_self);
  ADD_PHASE(resource_release);
  ADD_PHASE(other);
#undef ADD_PHASE
  destination->synchronization_audit.stream_synchronize_calls = SaturatingAdd(
      destination->synchronization_audit.stream_synchronize_calls,
      source.synchronization_audit.stream_synchronize_calls);
  destination->synchronization_audit.event_synchronize_calls = SaturatingAdd(
      destination->synchronization_audit.event_synchronize_calls,
      source.synchronization_audit.event_synchronize_calls);
  destination->synchronization_audit.device_synchronize_calls = SaturatingAdd(
      destination->synchronization_audit.device_synchronize_calls,
      source.synchronization_audit.device_synchronize_calls);
  destination->synchronization_audit.stream_host_wait_milliseconds +=
      source.synchronization_audit.stream_host_wait_milliseconds;
  destination->synchronization_audit.event_host_wait_milliseconds +=
      source.synchronization_audit.event_host_wait_milliseconds;
  destination->synchronization_audit.device_host_wait_milliseconds +=
      source.synchronization_audit.device_host_wait_milliseconds;
#define ADD_SYNC_SITE(name)                                                   \
  destination->synchronization_audit.name.calls = SaturatingAdd(             \
      destination->synchronization_audit.name.calls,                         \
      source.synchronization_audit.name.calls);                              \
  destination->synchronization_audit.name.host_wait_milliseconds +=          \
      source.synchronization_audit.name.host_wait_milliseconds
  ADD_SYNC_SITE(layer_a_final);
  ADD_SYNC_SITE(layer_b_final);
  ADD_SYNC_SITE(layer_c_factor);
  ADD_SYNC_SITE(layer_c_solver);
  ADD_SYNC_SITE(layer_c_final);
  ADD_SYNC_SITE(trial_cost_final);
  ADD_SYNC_SITE(resource_release);
#undef ADD_SYNC_SITE
  if (destination->h2d_host_memory_kind == "none")
    destination->h2d_host_memory_kind = source.h2d_host_memory_kind;
  if (destination->d2h_host_memory_kind == "none")
    destination->d2h_host_memory_kind = source.d2h_host_memory_kind;
  destination->topology_epoch =
      std::max(destination->topology_epoch, source.topology_epoch);
  destination->topology_build_count = SaturatingAdd(
      destination->topology_build_count, source.topology_build_count);
  destination->topology_refresh_count = SaturatingAdd(
      destination->topology_refresh_count, source.topology_refresh_count);
  destination->cache_lookup_count = SaturatingAdd(
      destination->cache_lookup_count, source.cache_lookup_count);
  destination->cache_hit_count = SaturatingAdd(
      destination->cache_hit_count, source.cache_hit_count);
  destination->cache_miss_count = SaturatingAdd(
      destination->cache_miss_count, source.cache_miss_count);
  destination->cache_invalidation_count = SaturatingAdd(
      destination->cache_invalidation_count, source.cache_invalidation_count);
  destination->build_cuda_layer_a_inputs_count = SaturatingAdd(
      destination->build_cuda_layer_a_inputs_count,
      source.build_cuda_layer_a_inputs_count);
  destination->build_cost_order_count = SaturatingAdd(
      destination->build_cost_order_count, source.build_cost_order_count);
  destination->layer_a_calls =
      SaturatingAdd(destination->layer_a_calls, source.layer_a_calls);
  destination->layer_b_calls =
      SaturatingAdd(destination->layer_b_calls, source.layer_b_calls);
  destination->layer_c_calls =
      SaturatingAdd(destination->layer_c_calls, source.layer_c_calls);
  destination->cost_calls =
      SaturatingAdd(destination->cost_calls, source.cost_calls);
  destination->topology_fingerprint_computations = SaturatingAdd(
      destination->topology_fingerprint_computations,
      source.topology_fingerprint_computations);
  destination->topology_generation =
      std::max(destination->topology_generation, source.topology_generation);
  if (destination->topology_fingerprint.empty())
    destination->topology_fingerprint = source.topology_fingerprint;
}

void FinalizeTimingLedger(CudaTimingLedger* ledger,
                          const double runtime_host_wall_milliseconds) {
  if (ledger == nullptr) return;
  double known = 0.0;
#define SUM_PHASE(name) known += ledger->name.host_wall_milliseconds
  SUM_PHASE(build_cuda_layer_a_inputs);
  SUM_PHASE(topology_lookup);
  SUM_PHASE(topology_build);
  SUM_PHASE(topology_refresh);
  SUM_PHASE(topology_cache);
  SUM_PHASE(build_cost_order);
  SUM_PHASE(allocation);
  SUM_PHASE(free);
  SUM_PHASE(h2d_memcpy);
  SUM_PHASE(d2h_memcpy);
  SUM_PHASE(d2d_memcpy);
  SUM_PHASE(managed_prefetch);
  SUM_PHASE(layer_a_kernel);
  SUM_PHASE(layer_b_pose_kernel);
  SUM_PHASE(layer_b_point_kernel);
  SUM_PHASE(layer_b_edge_kernel);
  SUM_PHASE(layer_b_gradient_kernel);
  SUM_PHASE(layer_c_point_factor);
  SUM_PHASE(schur);
  SUM_PHASE(rhs);
  SUM_PHASE(cusolver);
  SUM_PHASE(back_substitution);
  SUM_PHASE(back_substitution_host_self);
  SUM_PHASE(trial_cost);
  SUM_PHASE(apply_layer_c_step);
  SUM_PHASE(compute_layer_c_diagnostics);
  SUM_PHASE(lm_decision);
  SUM_PHASE(synchronization);
  SUM_PHASE(state_hash);
  SUM_PHASE(topology_fingerprint_audit);
  SUM_PHASE(controller_self);
  SUM_PHASE(resource_release);
#undef SUM_PHASE
  ledger->accounted_interval_wall_milliseconds =
      runtime_host_wall_milliseconds;
  ledger->explicitly_measured_host_wall_milliseconds = known;
  ledger->uninstrumented_remainder_milliseconds =
      runtime_host_wall_milliseconds - known;
  ledger->known_host_wall_milliseconds = known;
  ledger->other_host_wall_milliseconds =
      ledger->uninstrumented_remainder_milliseconds;
  ledger->other.host_wall_milliseconds = ledger->other_host_wall_milliseconds;
  ledger->other.calls = 1;
  const double denominator = std::max(1e-12, runtime_host_wall_milliseconds);
  ledger->host_partition_error_percent =
      100.0 * std::abs(known + ledger->other_host_wall_milliseconds -
                        runtime_host_wall_milliseconds) /
      denominator;
  ledger->host_partition_pass = ledger->host_partition_error_percent <= 1.0;
}

struct LifecycleCounters {
  uint64_t layer_a = 0;
  uint64_t layer_b = 0;
  uint64_t layer_c = 0;
  uint64_t cost = 0;
  uint64_t topology_build = 0;
  uint64_t topology_refresh = 0;
  uint64_t cache_hit = 0;
  uint64_t cache_lookup = 0;
  uint64_t cache_miss = 0;
  uint64_t cache_invalidation = 0;
};

LifecycleCounters ReadLifecycleCounters(const CudaTimingLedger& ledger) {
  LifecycleCounters result;
  result.layer_a = ledger.layer_a_calls;
  result.layer_b = ledger.layer_b_calls;
  result.layer_c = ledger.layer_c_calls;
  result.cost = ledger.cost_calls;
  result.topology_build = ledger.topology_build_count;
  result.topology_refresh = ledger.topology_refresh_count;
  result.cache_hit = ledger.cache_hit_count;
  result.cache_lookup = ledger.cache_lookup_count;
  result.cache_miss = ledger.cache_miss_count;
  result.cache_invalidation = ledger.cache_invalidation_count;
  return result;
}

uint64_t CounterDelta(const uint64_t after, const uint64_t before) {
  return after >= before ? after - before : 0;
}

}  // namespace

namespace {

std::atomic<uint64_t> g_host_store_lookup_hash_for_testing{0};

uint64_t HashPreparedHostViewDescriptor(const CudaSolveProblem& snapshot,
                                        const CudaFullLmOptions& options) {
  if (snapshot.prepared_host_topology_identity == 0) return 0;
  const uint64_t forced_hash =
      g_host_store_lookup_hash_for_testing.load(std::memory_order_relaxed);
  if (forced_hash != 0) return forced_hash;
  uint64_t state = snapshot.prepared_host_topology_identity;
  HashTag(&state, 0x484f535456494557ull);
  HashWord(&state, static_cast<uint64_t>(options.arithmetic_precision));
  HashWord(&state, static_cast<uint64_t>(options.hot_kernel_mode));
  HashWord(&state, static_cast<uint64_t>(
      options.layer_c.layer_b.hessian_assembly_backend));
  HashWord(&state, static_cast<uint64_t>(
      options.layer_c.schur_contribution_backend));
  HashWord(&state, static_cast<uint64_t>(options.execution_profile));
  HashWord(&state, options.pair_chunk_limit_bytes_for_testing);
  HashWord(&state, options.layer_c.layer_b.hessian_segment_size_for_testing);
  HashWord(&state, options.layer_c.schur_segment_size_for_testing);
  HashWord(&state, static_cast<uint64_t>(options.layer_c.layer_b.loss_mode));
  HashDouble(&state, options.layer_c.layer_b.loss_scale);
  HashWord(&state, static_cast<uint64_t>(CudaResidualOrder::kSourceInsertion));
  return state == 0 ? 1 : state;
}

bool SamePreparedObservation(const ObservationSnapshot& lhs,
                             const ObservationSnapshot& rhs) {
  return lhs.source_index == rhs.source_index &&
         lhs.image_id == rhs.image_id &&
         lhs.point2D_idx == rhs.point2D_idx &&
         lhs.point3D_id == rhs.point3D_id &&
         lhs.pose_constant == rhs.pose_constant && lhs.xy == rhs.xy;
}

bool SamePreparedLidar(const LidarSnapshot& lhs,
                       const LidarSnapshot& rhs) {
  return lhs.source_index == rhs.source_index &&
         lhs.point3D_id == rhs.point3D_id &&
         lhs.lidar_type == rhs.lidar_type &&
         lhs.has_search_range == rhs.has_search_range &&
         lhs.search_range == rhs.search_range && lhs.weight == rhs.weight &&
         lhs.lidar_xyz == rhs.lidar_xyz && lhs.plane == rhs.plane;
}

bool SamePreparedParameter(const ParameterBlockSnapshot& lhs,
                           const ParameterBlockSnapshot& rhs) {
  return lhs.source_index == rhs.source_index && lhs.kind == rhs.kind &&
         lhs.entity_id == rhs.entity_id &&
         lhs.ambient_size == rhs.ambient_size &&
         lhs.tangent_size == rhs.tangent_size &&
         lhs.constant == rhs.constant;
}

bool SamePreparedOrderEntry(const OrderEntrySnapshot& lhs,
                            const OrderEntrySnapshot& rhs) {
  return lhs.source_index == rhs.source_index &&
         lhs.residual_kind == rhs.residual_kind &&
         lhs.image_id == rhs.image_id &&
         lhs.point2D_idx == rhs.point2D_idx &&
         lhs.point3D_id == rhs.point3D_id;
}

template <typename Left, typename Right, typename Predicate>
bool SamePreparedSequence(const std::vector<Left>& lhs,
                          const std::vector<Right>& rhs,
                          Predicate predicate) {
  if (lhs.size() != rhs.size()) return false;
  for (size_t i = 0; i < lhs.size(); ++i) {
    if (!predicate(lhs[i], rhs[i])) return false;
  }
  return true;
}

bool PreparedHostCanonicalDescriptorMatches(
    const PreparedHostSolveViewData& prepared,
    const CudaSolveProblem& snapshot) {
  if (prepared.descriptor_ba_kind != snapshot.metadata.ba_kind ||
      prepared.descriptor_lidar_residual_mode !=
          snapshot.metadata.lidar_residual_mode ||
      prepared.camera_layout.size() != snapshot.cameras.size() ||
      prepared.camera_parameters.size() != snapshot.cameras.size() ||
      prepared.image_layout.size() != snapshot.images.size() ||
      prepared.point_layout.size() != snapshot.points.size()) {
    return false;
  }
  for (size_t i = 0; i < snapshot.cameras.size(); ++i) {
    const CameraSnapshot& current = snapshot.cameras[i];
    const CameraStaticLayoutEntry& cached = prepared.camera_layout[i];
    if (current.camera_id != cached.camera_id ||
        current.model_id != cached.model_id || current.width != cached.width ||
        current.height != cached.height ||
        current.params.size() != cached.parameter_count ||
        current.constant != cached.constant ||
        current.params != prepared.camera_parameters[i]) {
      return false;
    }
  }
  for (size_t i = 0; i < snapshot.images.size(); ++i) {
    const ImageSnapshot& current = snapshot.images[i];
    const ImageStaticLayoutEntry& cached = prepared.image_layout[i];
    if (current.image_id != cached.image_id ||
        current.camera_id != cached.camera_id ||
        current.selected != cached.selected ||
        current.pose_constant != cached.pose_constant ||
        current.has_pose_parameter_blocks != cached.has_pose_parameter_blocks ||
        current.constant_tvec_mask != cached.constant_tvec_mask) {
      return false;
    }
  }
  for (size_t i = 0; i < snapshot.points.size(); ++i) {
    const PointSnapshot& current = snapshot.points[i];
    const PointStaticLayoutEntry& cached = prepared.point_layout[i];
    if (current.point3D_id != cached.point3D_id ||
        current.constant != cached.constant ||
        current.config_role != cached.config_role ||
        current.has_search_range != cached.has_search_range ||
        (current.has_search_range &&
         current.search_range != cached.search_range)) {
      return false;
    }
  }
  return SamePreparedSequence(prepared.descriptor_observations,
                              snapshot.observations,
                              SamePreparedObservation) &&
         SamePreparedSequence(prepared.descriptor_lidar, snapshot.lidar,
                              SamePreparedLidar) &&
         SamePreparedSequence(prepared.descriptor_parameter_blocks,
                              snapshot.parameter_blocks_source_order,
                              SamePreparedParameter) &&
         SamePreparedSequence(prepared.descriptor_source_order,
                              snapshot.source_insertion_order,
                              SamePreparedOrderEntry) &&
         SamePreparedSequence(prepared.descriptor_canonical_order,
                              snapshot.canonical_order,
                              SamePreparedOrderEntry);
}

uint64_t EstimatePreparedHostBytes(const PreparedHostSolveViewData& value) {
  uint64_t bytes = sizeof(value);
#define ADD_VECTOR_BYTES(field) \
  bytes = SaturatingAdd(bytes, value.field.size() * sizeof(value.field[0]))
  ADD_VECTOR_BYTES(camera_layout);
  ADD_VECTOR_BYTES(camera_parameters);
  for (const auto& parameters : value.camera_parameters)
    bytes = SaturatingAdd(bytes, parameters.size() * sizeof(double));
  ADD_VECTOR_BYTES(image_layout);
  ADD_VECTOR_BYTES(point_layout);
  ADD_VECTOR_BYTES(visual_layout);
  ADD_VECTOR_BYTES(lidar_layout);
  ADD_VECTOR_BYTES(descriptor_observations);
  ADD_VECTOR_BYTES(descriptor_lidar);
  ADD_VECTOR_BYTES(descriptor_parameter_blocks);
  ADD_VECTOR_BYTES(descriptor_source_order);
  ADD_VECTOR_BYTES(descriptor_canonical_order);
  bytes = SaturatingAdd(bytes, value.packed_template.visual.size() *
                                   sizeof(CudaVisualInput));
  bytes = SaturatingAdd(bytes, value.packed_template.lidar.size() *
                                   sizeof(CudaLidarInput));
  bytes = SaturatingAdd(bytes, value.packed_template.pose_state.size() *
                                   sizeof(DevicePoseState));
  bytes = SaturatingAdd(bytes, value.cost_layout.entries.size() *
                                   sizeof(DeviceCostEntry));
  bytes = SaturatingAdd(bytes, value.cost_layout.source_order.size() *
                                   sizeof(OrderEntrySnapshot));
  ADD_VECTOR_BYTES(layer_b_topology.poses);
  ADD_VECTOR_BYTES(layer_b_topology.points);
  ADD_VECTOR_BYTES(layer_b_topology.edges);
  ADD_VECTOR_BYTES(layer_b_topology.pose_adjacency);
  ADD_VECTOR_BYTES(layer_b_topology.point_adjacency);
  ADD_VECTOR_BYTES(layer_b_topology.edge_adjacency);
  ADD_VECTOR_BYTES(layer_b_topology.atomic_visual_bindings);
  ADD_VECTOR_BYTES(layer_b_topology.atomic_lidar_bindings);
  ADD_VECTOR_BYTES(layer_b_topology.pose_segments);
  ADD_VECTOR_BYTES(layer_b_topology.point_segments);
  ADD_VECTOR_BYTES(layer_b_topology.edge_segments);
  ADD_VECTOR_BYTES(layer_b_topology.point_direct_indices);
  ADD_VECTOR_BYTES(layer_b_topology.pose_segment_ranges);
  ADD_VECTOR_BYTES(layer_b_topology.point_segment_ranges);
  ADD_VECTOR_BYTES(layer_b_topology.edge_segment_ranges);
  if (value.layer_c_topology != nullptr) {
    const LayerCTopology& layer_c = *value.layer_c_topology;
    bytes = SaturatingAdd(bytes, layer_c.poses.size() * sizeof(layer_c.poses[0]));
    bytes = SaturatingAdd(bytes, layer_c.points.size() * sizeof(layer_c.points[0]));
    bytes = SaturatingAdd(bytes, layer_c.pose_edges.size() * sizeof(uint32_t));
    bytes = SaturatingAdd(bytes, layer_c.point_edges.size() * sizeof(uint32_t));
    bytes = SaturatingAdd(bytes, layer_c.pairs.size() * sizeof(layer_c.pairs[0]));
    bytes = SaturatingAdd(bytes, layer_c.pair_contributions.size() *
                                     sizeof(layer_c.pair_contributions[0]));
    bytes = SaturatingAdd(bytes, layer_c.pair_chunks.size() *
                                     sizeof(layer_c.pair_chunks[0]));
    bytes = SaturatingAdd(bytes, layer_c.segments.size() *
                                     sizeof(layer_c.segments[0]));
    bytes = SaturatingAdd(bytes, layer_c.segment_pair_ranges.size() *
                                     sizeof(layer_c.segment_pair_ranges[0]));
    bytes = SaturatingAdd(bytes, layer_c.segment_direct_pair_indices.size() *
                                     sizeof(uint32_t));
    bytes = SaturatingAdd(bytes, layer_c.segment_chunks.size() *
                                     sizeof(layer_c.segment_chunks[0]));
  }
#undef ADD_VECTOR_BYTES
  const uint64_t map_entries = value.camera_indices.size() +
      value.image_indices.size() + value.point_indices.size() +
      value.observation_indices.size() + value.lidar_indices.size() +
      value.visual_output_indices.size() + value.lidar_output_indices.size();
  return SaturatingAdd(bytes, map_entries * 40);
}

bool ResolvePreparedHostBuildConfiguration(
    const CudaFullLmOptions& options,
    CudaLayerCOptions* step_options,
    CudaArithmeticPrecision* arithmetic_precision,
    HotKernelImplementation* hot_kernel,
    CudaSchurContributionBackend* schur_backend,
    std::string* error) {
  if (step_options == nullptr || arithmetic_precision == nullptr ||
      hot_kernel == nullptr || schur_backend == nullptr || error == nullptr) {
    return false;
  }
  *step_options = options.layer_c;
  step_options->pair_chunk_limit_bytes_for_testing =
      options.pair_chunk_limit_bytes_for_testing;
  step_options->layer_b.layer_a.residual_order =
      CudaResidualOrder::kSourceInsertion;
  if (options.performance_mode) {
    step_options->layer_b.reduction_mode =
        CudaReductionMode::kParallelDeterministic;
    if (step_options->layer_b.cost_reduction_threads <= 1)
      step_options->layer_b.cost_reduction_threads = 128;
  }
  if (!ResolveArithmeticPrecision(options.arithmetic_precision,
                                  arithmetic_precision, error)) {
    return false;
  }
  const bool device_control = options.device_context_mode ==
      CudaDeviceContextMode::kDeviceControl;
  if (!ResolveHotKernelImplementation(options.hot_kernel_mode, device_control,
                                      false, hot_kernel, error)) {
    return false;
  }
  std::string requested;
  if (!ResolveSchurContributionBackend(
          step_options->schur_contribution_backend, schur_backend,
          &requested, error)) {
    return false;
  }
  return true;
}

bool BuildPreparedHostViewFromCatalog(
    const CudaSolveProblem& snapshot,
    const CudaLayerCOptions& step_options,
    const CudaArithmeticPrecision precision,
    const HotKernelImplementation hot_kernel,
    const CudaSchurContributionBackend schur_backend,
    const CudaExecutionProfile execution_profile,
    const std::shared_ptr<const StaticProblemDataCatalog>& catalog,
    CudaHostProblemStoreRuntimeInfo* runtime,
    PreparedHostSolveViewData* output,
    std::string* error) {
  if (catalog == nullptr || runtime == nullptr || output == nullptr ||
      error == nullptr) {
    return false;
  }
  error->clear();
  output->catalog = catalog;
  output->residual_order = step_options.layer_b.layer_a.residual_order;
  output->arithmetic_precision = precision;
  output->execution_profile = execution_profile;
  output->schur_backend = schur_backend;
  output->pair_chunk_limit_bytes =
      step_options.pair_chunk_limit_bytes_for_testing;
  output->hessian_segment_size =
      step_options.layer_b.hessian_segment_size_for_testing;
  output->schur_segment_size =
      step_options.schur_segment_size_for_testing;
  output->descriptor_ba_kind = snapshot.metadata.ba_kind;
  output->descriptor_lidar_residual_mode =
      snapshot.metadata.lidar_residual_mode;
  output->descriptor_observations = snapshot.observations;
  output->descriptor_lidar = snapshot.lidar;
  output->descriptor_parameter_blocks =
      snapshot.parameter_blocks_source_order;
  output->descriptor_source_order = snapshot.source_insertion_order;
  output->descriptor_canonical_order = snapshot.canonical_order;
  if (!ResolveCudaLoss(snapshot, step_options.layer_b, &output->loss_mode,
                       &output->loss_scale, error)) {
    return false;
  }
  std::string hessian_requested;
  if (!ResolveHessianAssemblyBackend(
          step_options.layer_b.hessian_assembly_backend, hot_kernel,
          &output->hessian_backend, &hessian_requested, error)) {
    return false;
  }

  ++runtime->static_binding_builder_calls;
  ++runtime->host_builder_calls_executed;
  output->camera_indices.reserve(snapshot.cameras.size());
  output->image_indices.reserve(snapshot.images.size());
  output->point_indices.reserve(snapshot.points.size());
  output->observation_indices.reserve(snapshot.observations.size());
  output->lidar_indices.reserve(snapshot.lidar.size());
  output->camera_layout.resize(snapshot.cameras.size());
  output->camera_parameters.resize(snapshot.cameras.size());
  output->image_layout.resize(snapshot.images.size());
  output->point_layout.resize(snapshot.points.size());
  ++runtime->host_builder_traversals_executed;
  for (size_t i = 0; i < snapshot.cameras.size(); ++i) {
    const CameraSnapshot& value = snapshot.cameras[i];
    const HostCatalogCamera* stable = FindCatalogCamera(catalog, value.camera_id);
    if (stable == nullptr || stable->model_id != value.model_id ||
        stable->width != value.width || stable->height != value.height ||
        stable->parameter_count != value.params.size() ||
        !output->camera_indices.emplace(value.camera_id, i).second) {
      *error = "prepared view camera is inconsistent with the host catalog";
      return false;
    }
    output->camera_layout[i] = {value.camera_id, value.model_id,
                                value.width, value.height,
                                value.params.size(), value.constant};
    output->camera_parameters[i] = value.params;
  }
  ++runtime->host_builder_traversals_executed;
  for (size_t i = 0; i < snapshot.images.size(); ++i) {
    const ImageSnapshot& value = snapshot.images[i];
    const HostCatalogImage* stable = FindCatalogImage(catalog, value.image_id);
    if (stable == nullptr || stable->camera_id != value.camera_id ||
        !output->image_indices.emplace(value.image_id, i).second) {
      *error = "prepared view image is inconsistent with the host catalog";
      return false;
    }
    output->image_layout[i] = {value.image_id, value.camera_id,
                               value.selected,
                               value.pose_constant,
                               value.has_pose_parameter_blocks,
                               value.constant_tvec_mask};
  }
  ++runtime->host_builder_traversals_executed;
  for (size_t i = 0; i < snapshot.points.size(); ++i) {
    const PointSnapshot& value = snapshot.points[i];
    if (FindCatalogPoint(catalog, value.point3D_id) == nullptr ||
        !output->point_indices.emplace(value.point3D_id, i).second) {
      *error = "prepared view point is inconsistent with the host catalog";
      return false;
    }
    output->point_layout[i] = {value.point3D_id, value.constant,
                               value.config_role, value.has_search_range,
                               value.search_range};
  }
  ++runtime->host_builder_traversals_executed;
  for (size_t i = 0; i < snapshot.observations.size(); ++i) {
    if (!output->observation_indices.emplace(
             snapshot.observations[i].source_index, i).second) {
      *error = "duplicate visual source index in prepared view";
      return false;
    }
  }
  ++runtime->host_builder_traversals_executed;
  for (size_t i = 0; i < snapshot.lidar.size(); ++i) {
    if (!output->lidar_indices.emplace(snapshot.lidar[i].source_index, i)
             .second) {
      *error = "duplicate LiDAR source index in prepared view";
      return false;
    }
  }

  ++runtime->cost_layout_builder_calls;
  ++runtime->host_builder_calls_executed;
  ++runtime->host_builder_traversals_executed;
  std::vector<OrderEntrySnapshot> order =
      output->residual_order == CudaResidualOrder::kSourceInsertion
          ? snapshot.source_insertion_order
          : snapshot.canonical_order;
  if (order.size() != snapshot.observations.size() + snapshot.lidar.size()) {
    *error = "prepared view residual order is incomplete";
    return false;
  }
  LidarResidualMode lidar_mode;
  const std::string lidar_mode_name =
      snapshot.metadata.lidar_residual_mode.empty()
          ? "legacy_exact" : snapshot.metadata.lidar_residual_mode;
  if (!ParseLidarResidualMode(lidar_mode_name, &lidar_mode)) {
    *error = "unsupported LiDAR mode in prepared view";
    return false;
  }
  output->packed_template.visual.reserve(snapshot.observations.size());
  output->packed_template.lidar.reserve(snapshot.lidar.size());
  output->visual_layout.reserve(snapshot.observations.size());
  output->lidar_layout.reserve(snapshot.lidar.size());
  output->visual_output_indices.reserve(snapshot.observations.size());
  output->lidar_output_indices.reserve(snapshot.lidar.size());
  output->cost_layout = CostLayout();
  output->cost_layout.residual_order = output->residual_order;
  output->cost_layout.visual_count = snapshot.observations.size();
  output->cost_layout.lidar_count = snapshot.lidar.size();
  output->cost_layout.source_order = order;
  output->cost_layout.entries.reserve(order.size());
  std::unordered_set<uint64_t> covered_sources;
  covered_sources.reserve(order.size());
  for (const OrderEntrySnapshot& entry : order) {
    if (!covered_sources.insert(entry.source_index).second) {
      *error = "prepared view residual order contains a duplicate source";
      return false;
    }
    DeviceCostEntry cost;
    if (entry.residual_kind == ResidualKind::kVisual) {
      const auto observation_it =
          output->observation_indices.find(entry.source_index);
      if (observation_it == output->observation_indices.end()) {
        *error = "prepared view order references a missing observation";
        return false;
      }
      const ObservationSnapshot& observation =
          snapshot.observations[observation_it->second];
      const HostCatalogObservation* stable = FindCatalogObservation(
          catalog, observation.image_id, observation.point2D_idx);
      const auto image_it = output->image_indices.find(observation.image_id);
      const auto point_it = output->point_indices.find(observation.point3D_id);
      if (stable == nullptr || stable->point3D_id != observation.point3D_id ||
          stable->xy != observation.xy ||
          image_it == output->image_indices.end() ||
          point_it == output->point_indices.end()) {
        *error = "prepared visual residual is inconsistent with the catalog";
        return false;
      }
      const ImageSnapshot& image = snapshot.images[image_it->second];
      const auto camera_it = output->camera_indices.find(image.camera_id);
      if (camera_it == output->camera_indices.end()) {
        *error = "prepared visual residual references a missing camera";
        return false;
      }
      const CameraSnapshot& camera = snapshot.cameras[camera_it->second];
      if (camera.model_id != kOpenCvcCameraModelId ||
          camera.params.size() != 8) {
        *error = "prepared visual residual requires OPENCV camera";
        return false;
      }
      CudaVisualInput packed;
      packed.source_index = observation.source_index;
      packed.image_id = observation.image_id;
      packed.point3D_id = observation.point3D_id;
      for (size_t j = 0; j < 4; ++j) packed.quaternion[j] = image.qvec[j];
      for (size_t j = 0; j < 3; ++j) {
        packed.translation[j] = image.tvec[j];
        packed.point[j] = snapshot.points[point_it->second].xyz[j];
      }
      for (size_t j = 0; j < 8; ++j) packed.camera[j] = camera.params[j];
      packed.observation[0] = stable->xy[0];
      packed.observation[1] = stable->xy[1];
      const uint32_t output_index = static_cast<uint32_t>(
          output->packed_template.visual.size());
      output->packed_template.visual.push_back(packed);
      output->visual_output_indices.emplace(entry.source_index, output_index);
      VisualStaticLayoutEntry layout;
      layout.observation_index = observation_it->second;
      layout.image_index = image_it->second;
      layout.point_index = point_it->second;
      layout.camera_index = camera_it->second;
      layout.point2D_idx = observation.point2D_idx;
      layout.packed_template = packed;
      output->visual_layout.push_back(layout);
      cost.output_index = output_index;
      cost.residual_kind = 0;
    } else {
      const auto lidar_it = output->lidar_indices.find(entry.source_index);
      if (lidar_it == output->lidar_indices.end()) {
        *error = "prepared view order references a missing LiDAR residual";
        return false;
      }
      const LidarSnapshot& lidar = snapshot.lidar[lidar_it->second];
      const auto point_it = output->point_indices.find(lidar.point3D_id);
      if (point_it == output->point_indices.end()) {
        *error = "prepared LiDAR residual references a missing point";
        return false;
      }
      CudaLidarInput packed;
      packed.source_index = lidar.source_index;
      packed.point3D_id = lidar.point3D_id;
      for (size_t j = 0; j < 3; ++j) {
        packed.point[j] = snapshot.points[point_it->second].xyz[j];
        packed.plane[j] = lidar.plane[j];
      }
      packed.plane[3] = lidar.plane[3];
      packed.weight = lidar.weight;
      packed.mode = static_cast<uint8_t>(lidar_mode);
      packed.near_zero_threshold = 1e-12;
      const uint32_t output_index = static_cast<uint32_t>(
          output->packed_template.lidar.size());
      output->packed_template.lidar.push_back(packed);
      output->lidar_output_indices.emplace(entry.source_index, output_index);
      LidarStaticLayoutEntry layout;
      layout.lidar_index = lidar_it->second;
      layout.point_index = point_it->second;
      layout.lidar_type = lidar.lidar_type;
      layout.packed_template = packed;
      output->lidar_layout.push_back(layout);
      cost.output_index = output_index;
      cost.residual_kind = 1;
    }
    output->cost_layout.entries.push_back(cost);
  }
  if (output->packed_template.visual.size() != snapshot.observations.size() ||
      output->packed_template.lidar.size() != snapshot.lidar.size()) {
    *error = "prepared view residual coverage is incomplete";
    return false;
  }
  uint64_t layout_id = 1469598103934665603ull;
  HashTag(&layout_id, 0x434f53544c41594full);
  HashWord(&layout_id, static_cast<uint64_t>(output->residual_order));
  HashWord(&layout_id, output->packed_template.visual.size());
  HashWord(&layout_id, output->packed_template.lidar.size());
  for (size_t i = 0; i < order.size(); ++i) {
    HashWord(&layout_id, order[i].source_index);
    HashWord(&layout_id, static_cast<uint64_t>(order[i].residual_kind));
    HashWord(&layout_id, output->cost_layout.entries[i].output_index);
    HashWord(&layout_id, output->cost_layout.entries[i].residual_kind);
  }
  output->cost_layout.layout_id = layout_id == 0 ? 1 : layout_id;

  ++runtime->hessian_topology_builder_calls;
  ++runtime->host_builder_calls_executed;
  ++runtime->host_builder_traversals_executed;
  if (!BuildLayerBTopology(snapshot, output->packed_template.visual,
                           output->packed_template.lidar, output->cost_layout,
                           output->image_indices, output->point_indices,
                           &output->layer_b_topology, error)) {
    return false;
  }
  if (output->hessian_backend ==
          CudaHessianAssemblyBackend::kObservationAtomic ||
      output->hessian_backend ==
          CudaHessianAssemblyBackend::kObservationSegmented) {
    ++runtime->hessian_segment_plan_builder_calls;
    ++runtime->host_builder_calls_executed;
    ++runtime->host_builder_traversals_executed;
    if (!BuildLayerBObservationExecutionPlan(
            output->packed_template.visual, output->packed_template.lidar,
            output->hessian_backend,
            step_options.layer_b.hessian_segment_size_for_testing,
            &output->layer_b_topology, error)) {
      return false;
    }
  }
  std::shared_ptr<LayerCTopology> layer_c(new LayerCTopology());
  ++runtime->schur_topology_builder_calls;
  ++runtime->host_builder_calls_executed;
  ++runtime->host_builder_traversals_executed;
  if (!BuildLayerCTopology(output->layer_b_topology,
                           step_options.pair_chunk_limit_bytes_for_testing,
                           layer_c.get(), error)) {
    return false;
  }
  if (schur_backend ==
      CudaSchurContributionBackend::kSegmentedTransformed) {
    ++runtime->schur_segment_plan_builder_calls;
    ++runtime->host_builder_calls_executed;
    ++runtime->host_builder_traversals_executed;
    if (!BuildLayerCSegmentPlan(step_options.schur_segment_size_for_testing,
                                layer_c.get(), error)) {
      return false;
    }
  }
  output->layer_c_topology = std::move(layer_c);
  return true;
}

void AccumulateHostStoreRuntime(const CudaHostProblemStoreRuntimeInfo& value,
                                CudaHostProblemStoreRuntimeInfo* total) {
  if (total == nullptr) return;
#define ADD_COUNTER(field) total->field = SaturatingAdd(total->field, value.field)
  ADD_COUNTER(store_lookup_calls);
  ADD_COUNTER(store_hits);
  ADD_COUNTER(store_misses);
  ADD_COUNTER(catalog_cold_builds);
  ADD_COUNTER(catalog_delta_updates);
  ADD_COUNTER(catalog_full_rebuilds);
  ADD_COUNTER(journal_events);
  ADD_COUNTER(journal_gaps);
  ADD_COUNTER(journal_overflows);
  ADD_COUNTER(journal_unknown_events);
  ADD_COUNTER(exact_view_reuses);
  ADD_COUNTER(solve_view_patches);
  ADD_COUNTER(solve_view_rebuilds);
  ADD_COUNTER(fallback_rebuilds);
  ADD_COUNTER(host_builder_calls_executed);
  ADD_COUNTER(host_builder_calls_saved);
  ADD_COUNTER(host_builder_traversals_executed);
  ADD_COUNTER(host_builder_traversals_saved);
  ADD_COUNTER(estimated_host_builder_bytes_executed);
  ADD_COUNTER(estimated_host_builder_bytes_saved);
  ADD_COUNTER(static_binding_builder_calls);
  ADD_COUNTER(cost_layout_builder_calls);
  ADD_COUNTER(hessian_topology_builder_calls);
  ADD_COUNTER(hessian_segment_plan_builder_calls);
  ADD_COUNTER(schur_topology_builder_calls);
  ADD_COUNTER(schur_segment_plan_builder_calls);
  ADD_COUNTER(dynamic_state_refresh_calls);
  ADD_COUNTER(indexed_catalog_full_graph_build_calls);
  ADD_COUNTER(indexed_catalog_journal_apply_calls);
  ADD_COUNTER(indexed_catalog_flatten_calls);
  ADD_COUNTER(indexed_catalog_reconcile_calls);
  ADD_COUNTER(indexed_catalog_export_calls);
  ADD_COUNTER(indexed_active_materializer_calls);
  ADD_COUNTER(indexed_full_graph_records_scanned);
  ADD_COUNTER(indexed_estimated_impl_copy_bytes);
  ADD_COUNTER(indexed_estimated_export_bytes);
  ADD_COUNTER(evictions);
  ADD_COUNTER(invalidations);
  ADD_COUNTER(owner_identity_violations);
  ADD_COUNTER(coverage_violations);
  ADD_COUNTER(store_busy_failures);
  ADD_COUNTER(device_cleanup_failures_observed);
#undef ADD_COUNTER
  total->host_peak_bytes = std::max(total->host_peak_bytes,
                                    value.host_peak_bytes);
  total->journal_cursor_before = value.journal_cursor_before;
  total->journal_cursor_after = value.journal_cursor_after;
  total->catalog_generation = value.catalog_generation;
  total->view_generation = value.view_generation;
  total->config_generation = value.config_generation;
  total->host_catalog_valid = value.host_catalog_valid;
  total->device_poisoned = total->device_poisoned || value.device_poisoned;
  total->host_resident_bytes = value.host_resident_bytes;
  total->snapshot_descriptor_wall_milliseconds +=
      value.snapshot_descriptor_wall_milliseconds;
  total->store_lookup_wall_milliseconds += value.store_lookup_wall_milliseconds;
  total->catalog_delta_update_wall_milliseconds +=
      value.catalog_delta_update_wall_milliseconds;
  total->solve_view_build_or_patch_wall_milliseconds +=
      value.solve_view_build_or_patch_wall_milliseconds;
  total->dynamic_state_refresh_wall_milliseconds +=
      value.dynamic_state_refresh_wall_milliseconds;
  total->host_preparation_total_wall_milliseconds +=
      value.host_preparation_total_wall_milliseconds;
}

}  // namespace

struct GpuBaHostProblemStoreControl {
  const Reconstruction* reconstruction = nullptr;
  uint64_t owner_epoch = 0;
  uint64_t journal_cursor = 0;
  uint64_t indexed_journal_cursor = 0;
  uint64_t catalog_generation = 0;
  uint64_t indexed_catalog_generation = 0;
  uint64_t next_view_generation = 0;
  uint64_t next_config_generation = 0;
  uint64_t next_lease_generation = 0;
  bool catalog_valid = false;
  bool active = false;
  bool shutdown = false;
  bool shutdown_requested = false;
  uint64_t active_lease_generation = 0;
  std::shared_ptr<const StaticProblemDataCatalog> catalog;
  std::unordered_map<uint64_t,
                     std::shared_ptr<const PreparedHostSolveViewData>> views;
  std::deque<uint64_t> lru;
  std::shared_ptr<const StaticProblemDataCatalog> indexed_catalog_root;
  std::shared_ptr<MapperStaticProblemDataCatalog> indexed_catalog;
  std::shared_ptr<MapperStaticCatalogStableTables> indexed_catalog_tables;
  IndexedActiveSolveMaterializer indexed_materializer;
  CudaHostProblemStoreRuntimeInfo lifetime;
};

struct PreparedIndexedCatalogPublication {
  std::shared_ptr<const StaticProblemDataCatalog> root;
  std::shared_ptr<MapperStaticProblemDataCatalog> catalog;
  std::shared_ptr<MapperStaticCatalogStableTables> tables;
  uint64_t journal_cursor = 0;
  uint64_t root_generation = 0;
  uint64_t resident_bytes = 0;
  uint64_t peak_bytes = 0;
};

struct PreparedHostStorePublication {
  std::shared_ptr<const StaticProblemDataCatalog> catalog;
  std::unordered_map<uint64_t,
                     std::shared_ptr<const PreparedHostSolveViewData>> views;
  std::deque<uint64_t> lru;
  uint64_t journal_cursor = 0;
  uint64_t catalog_generation = 0;
  uint64_t resident_bytes = 0;
};

PreparedHostSolveView::PreparedHostSolveView() = default;

PreparedHostSolveView::~PreparedHostSolveView() { CancelIfActive(); }

PreparedHostSolveView::PreparedHostSolveView(
    PreparedHostSolveView&& other) noexcept {
  *this = std::move(other);
}

PreparedHostSolveView& PreparedHostSolveView::operator=(
    PreparedHostSolveView&& other) noexcept {
  if (this == &other) return *this;
  CancelIfActive();
  data_ = std::move(other.data_);
  control_ = std::move(other.control_);
  publication_ = std::move(other.publication_);
  lease_generation_ = other.lease_generation_;
  owner_epoch_ = other.owner_epoch_;
  catalog_generation_ = other.catalog_generation_;
  view_generation_ = other.view_generation_;
  config_generation_ = other.config_generation_;
  source_revision_ = other.source_revision_;
  active_ = other.active_;
  runtime_ = std::move(other.runtime_);
  other.active_ = false;
  return *this;
}

bool PreparedHostSolveView::valid() const noexcept {
  return active_ && data_ != nullptr && control_ != nullptr;
}

uint64_t PreparedHostSolveView::owner_epoch() const noexcept {
  return owner_epoch_;
}

uint64_t PreparedHostSolveView::catalog_generation() const noexcept {
  return catalog_generation_;
}

uint64_t PreparedHostSolveView::view_generation() const noexcept {
  return view_generation_;
}

uint64_t PreparedHostSolveView::config_generation() const noexcept {
  return config_generation_;
}

const PreparedHostSolveViewData*
PreparedHostSolveView::data_for_internal_use() const noexcept {
  return valid() ? data_.get() : nullptr;
}

const CudaHostProblemStoreRuntimeInfo&
PreparedHostSolveView::runtime_info() const noexcept {
  return runtime_;
}

void PreparedHostSolveView::CancelIfActive() noexcept {
  if (active_) {
    std::string ignored;
    Complete(false, false, &ignored);
  }
}

bool PreparedHostSolveView::Complete(const bool publish,
                                     const bool device_cleanup_failed,
                                     std::string* error) noexcept {
  if (error == nullptr) return false;
  error->clear();
  if (!active_ || control_ == nullptr) return true;
  GpuBaHostProblemStoreControl& store = *control_;
  if (!store.active || store.active_lease_generation != lease_generation_ ||
      store.owner_epoch != owner_epoch_) {
    *error = "host prepared store lease identity mismatch";
    ++runtime_.owner_identity_violations;
    if (store.active && store.active_lease_generation == lease_generation_) {
      store.active = false;
      store.active_lease_generation = 0;
    }
    active_ = false;
    control_.reset();
    publication_.reset();
    data_.reset();
    return false;
  }
  if (device_cleanup_failed) {
    ++runtime_.device_cleanup_failures_observed;
    runtime_.device_poisoned = true;
  }
  if (publish && data_ != nullptr && !store.shutdown_requested) {
    if (publication_ == nullptr || publication_->catalog == nullptr ||
        publication_->catalog->owner_epoch != store.owner_epoch ||
        publication_->catalog->generation != catalog_generation_ ||
        publication_->catalog->revision != source_revision_ ||
        publication_->catalog_generation != catalog_generation_ ||
        publication_->journal_cursor != source_revision_) {
      *error = "pending host catalog publish identity mismatch";
      ++runtime_.owner_identity_violations;
      store.active = false;
      store.active_lease_generation = 0;
      active_ = false;
      control_.reset();
      publication_.reset();
      data_.reset();
      return false;
    }
    store.catalog.swap(publication_->catalog);
    store.views.swap(publication_->views);
    store.lru.swap(publication_->lru);
    store.catalog_valid = true;
    store.catalog_generation = publication_->catalog_generation;
    store.journal_cursor = publication_->journal_cursor;
    runtime_.journal_cursor_after = store.journal_cursor;
    runtime_.host_resident_bytes = publication_->resident_bytes;
    runtime_.host_peak_bytes = std::max(
        store.lifetime.host_peak_bytes, publication_->resident_bytes);
    runtime_.host_catalog_valid = true;
  } else {
    // A cancelled or failed solve must report the published store state, not
    // the pending revision carried by this lease.
    runtime_.journal_cursor_after = store.journal_cursor;
    runtime_.catalog_generation = store.catalog_generation;
    runtime_.host_catalog_valid = store.catalog_valid;
  }
  store.active = false;
  store.active_lease_generation = 0;
  AccumulateHostStoreRuntime(runtime_, &store.lifetime);
  if (store.shutdown_requested) {
    store.views.clear();
    store.lru.clear();
    store.catalog.reset();
    store.indexed_catalog_root.reset();
    store.indexed_catalog_tables.reset();
    store.indexed_catalog.reset();
    store.catalog_valid = false;
    store.shutdown = true;
    store.lifetime.host_resident_bytes = 0;
  }
  active_ = false;
  control_.reset();
  publication_.reset();
  data_.reset();
  return true;
}

PreparedIndexedActiveSolve::PreparedIndexedActiveSolve() = default;

PreparedIndexedActiveSolve::~PreparedIndexedActiveSolve() {
  CancelIfActive();
}

PreparedIndexedActiveSolve::PreparedIndexedActiveSolve(
    PreparedIndexedActiveSolve&& other) noexcept {
  *this = std::move(other);
}

PreparedIndexedActiveSolve& PreparedIndexedActiveSolve::operator=(
    PreparedIndexedActiveSolve&& other) noexcept {
  if (this == &other) return *this;
  CancelIfActive();
  descriptor_ = std::move(other.descriptor_);
  catalog_tables_ = std::move(other.catalog_tables_);
  control_ = std::move(other.control_);
  publication_ = std::move(other.publication_);
  lease_generation_ = other.lease_generation_;
  owner_epoch_ = other.owner_epoch_;
  active_ = other.active_;
  runtime_ = std::move(other.runtime_);
  other.active_ = false;
  return *this;
}

bool PreparedIndexedActiveSolve::valid() const noexcept {
  return active_ && descriptor_ != nullptr && catalog_tables_ != nullptr &&
         control_ != nullptr && publication_ != nullptr;
}

const IndexedActiveSolveDescriptor*
PreparedIndexedActiveSolve::descriptor() const noexcept {
  return valid() ? descriptor_.get() : nullptr;
}

const MapperStaticCatalogStableTables*
PreparedIndexedActiveSolve::catalog_tables() const noexcept {
  return valid() ? catalog_tables_.get() : nullptr;
}

const CudaHostProblemStoreRuntimeInfo&
PreparedIndexedActiveSolve::runtime_info() const noexcept {
  return runtime_;
}

void PreparedIndexedActiveSolve::CancelIfActive() noexcept {
  if (!active_ || control_ == nullptr) return;
  GpuBaHostProblemStoreControl& store = *control_;
  if (store.active &&
      store.active_lease_generation == lease_generation_) {
    runtime_.journal_cursor_after = store.indexed_journal_cursor;
    runtime_.catalog_generation = store.indexed_catalog == nullptr
        ? 0 : store.indexed_catalog->generation();
    runtime_.host_catalog_valid = store.indexed_catalog != nullptr;
    runtime_.host_resident_bytes = store.lifetime.host_resident_bytes;
    AccumulateHostStoreRuntime(runtime_, &store.lifetime);
    store.active = false;
    store.active_lease_generation = 0;
  }
  if (store.shutdown_requested) {
    store.views.clear();
    store.lru.clear();
    store.catalog.reset();
    store.indexed_catalog_root.reset();
    store.indexed_catalog_tables.reset();
    store.indexed_catalog.reset();
    store.catalog_valid = false;
    store.shutdown = true;
    store.lifetime.host_resident_bytes = 0;
  }
  active_ = false;
  descriptor_.reset();
  catalog_tables_.reset();
  publication_.reset();
  control_.reset();
}

bool PreparedIndexedActiveSolve::Complete(
    const bool publish,
    const bool device_cleanup_failed,
    std::string* error) noexcept {
  if (error == nullptr) return false;
  error->clear();
  if (!active_ || control_ == nullptr) return true;
  GpuBaHostProblemStoreControl& store = *control_;
  if (!store.active || store.active_lease_generation != lease_generation_ ||
      store.owner_epoch != owner_epoch_) {
    *error = "indexed catalog lease identity mismatch";
    ++store.lifetime.owner_identity_violations;
    CancelIfActive();
    return false;
  }
  if (device_cleanup_failed) {
    ++store.lifetime.device_cleanup_failures_observed;
    store.lifetime.device_poisoned = true;
  }
  if (publish) {
    if (publication_ == nullptr || publication_->root == nullptr ||
        publication_->catalog == nullptr || publication_->tables == nullptr) {
      *error = "indexed catalog publication is incomplete";
      ++store.lifetime.coverage_violations;
      CancelIfActive();
      return false;
    }
    store.indexed_catalog_root = publication_->root;
    store.indexed_catalog = publication_->catalog;
    store.indexed_catalog_tables = publication_->tables;
    store.indexed_journal_cursor = publication_->journal_cursor;
    store.indexed_catalog_generation = publication_->root_generation;
    runtime_.journal_cursor_after = store.indexed_journal_cursor;
    runtime_.catalog_generation = store.indexed_catalog->generation();
    runtime_.host_resident_bytes = publication_->resident_bytes;
    runtime_.host_peak_bytes = std::max(store.lifetime.host_peak_bytes,
                                        publication_->peak_bytes);
    runtime_.host_catalog_valid = true;
  } else {
    runtime_.journal_cursor_after = store.indexed_journal_cursor;
    runtime_.catalog_generation = store.indexed_catalog == nullptr
        ? 0 : store.indexed_catalog->generation();
    runtime_.host_resident_bytes = store.lifetime.host_resident_bytes;
    runtime_.host_catalog_valid = store.indexed_catalog != nullptr;
  }
  AccumulateHostStoreRuntime(runtime_, &store.lifetime);
  store.active = false;
  store.active_lease_generation = 0;
  if (store.shutdown_requested) {
    store.views.clear();
    store.lru.clear();
    store.catalog.reset();
    store.indexed_catalog_root.reset();
    store.indexed_catalog_tables.reset();
    store.indexed_catalog.reset();
    store.catalog_valid = false;
    store.shutdown = true;
    store.lifetime.host_resident_bytes = 0;
  }
  active_ = false;
  descriptor_.reset();
  catalog_tables_.reset();
  publication_.reset();
  control_.reset();
  return true;
}

GpuBaHostProblemStore::GpuBaHostProblemStore(
    const Reconstruction* reconstruction, const uint64_t owner_epoch)
    : control_(std::make_shared<GpuBaHostProblemStoreControl>()) {
  control_->reconstruction = reconstruction;
  control_->owner_epoch = owner_epoch;
  control_->journal_cursor = reconstruction == nullptr
      ? 0
      : HostReconstructionStructureRevision(reconstruction);
  control_->indexed_journal_cursor = control_->journal_cursor;
  control_->lifetime.owner_epoch = owner_epoch;
}

GpuBaHostProblemStore::~GpuBaHostProblemStore() {
  std::string ignored;
  Shutdown(&ignored);
}

uint64_t GpuBaHostProblemStore::owner_epoch() const noexcept {
  return control_ == nullptr ? 0 : control_->owner_epoch;
}

bool GpuBaHostProblemStore::Shutdown(std::string* error) noexcept {
  if (error == nullptr) return false;
  error->clear();
  if (control_ == nullptr || control_->shutdown) return true;
  if (control_->active) {
    *error = "StoreBusy: cannot shutdown an active host prepared store";
    control_->shutdown_requested = true;
    ++control_->lifetime.store_busy_failures;
    return false;
  }
  ++control_->lifetime.host_shutdown_calls;
  control_->views.clear();
  control_->lru.clear();
  control_->catalog.reset();
  control_->indexed_catalog_root.reset();
  control_->indexed_catalog_tables.reset();
  control_->indexed_catalog.reset();
  control_->catalog_valid = false;
  control_->shutdown = true;
  control_->lifetime.host_resident_bytes = 0;
  return true;
}

CudaHostProblemStoreRuntimeInfo
GpuBaHostProblemStore::LifetimeRuntimeInfo() const {
  return control_ == nullptr ? CudaHostProblemStoreRuntimeInfo()
                             : control_->lifetime;
}

bool RunCudaHostProblemStoreLeaseLifetimeForTesting(
    CudaHostProblemStoreLeaseTestResult* result,
    std::string* error) {
  if (result == nullptr || error == nullptr) return false;
  *result = CudaHostProblemStoreLeaseTestResult();
  error->clear();
  constexpr uint64_t kOwnerEpoch = 0x1100a;
  std::unique_ptr<GpuBaHostProblemStore> owner(
      new GpuBaHostProblemStore(nullptr, kOwnerEpoch));
  std::shared_ptr<GpuBaHostProblemStoreControl> control = owner->control_;
  control->active = true;
  control->active_lease_generation = 1;
  PreparedHostSolveView lease;
  lease.data_ = std::make_shared<PreparedHostSolveViewData>();
  lease.control_ = control;
  lease.lease_generation_ = 1;
  lease.owner_epoch_ = kOwnerEpoch;
  lease.active_ = true;
  std::string shutdown_error;
  result->shutdown_reported_store_busy =
      !owner->Shutdown(&shutdown_error) &&
      shutdown_error.find("StoreBusy") != std::string::npos;
  owner.reset();
  result->control_survived_owner_destruction = lease.valid();
  result->lease_completion_succeeded = lease.Complete(false, false, error);
  result->deferred_shutdown_completed =
      control->shutdown && !control->active && control->catalog == nullptr;
  if (!result->lease_completion_succeeded) return false;

  GpuBaHostProblemStore mismatch_owner(nullptr, kOwnerEpoch + 1);
  std::shared_ptr<GpuBaHostProblemStoreControl> mismatch_control =
      mismatch_owner.control_;
  mismatch_control->active = true;
  mismatch_control->active_lease_generation = 7;
  PreparedHostSolveView mismatch;
  mismatch.data_ = std::make_shared<PreparedHostSolveViewData>();
  mismatch.control_ = mismatch_control;
  mismatch.lease_generation_ = 7;
  mismatch.owner_epoch_ = kOwnerEpoch;
  mismatch.active_ = true;
  std::string mismatch_error;
  const bool mismatch_ok = mismatch.Complete(false, false, &mismatch_error);
  result->mismatch_released_matching_active_lease =
      !mismatch_ok && !mismatch_control->active &&
      mismatch_error.find("identity mismatch") != std::string::npos;
  std::string final_shutdown_error;
  if (!mismatch_owner.Shutdown(&final_shutdown_error)) {
    *error = final_shutdown_error;
    return false;
  }
  return result->shutdown_reported_store_busy &&
         result->control_survived_owner_destruction &&
         result->lease_completion_succeeded &&
         result->deferred_shutdown_completed &&
         result->mismatch_released_matching_active_lease;
}

bool ParseCudaHostProblemStoreMode(const std::string& value,
                                   CudaHostProblemStoreMode* mode) {
  if (mode == nullptr) return false;
  if (value.empty() || value == "disabled") {
    *mode = CudaHostProblemStoreMode::kDisabled;
    return true;
  }
  if (value == "host_prepared_store") {
    *mode = CudaHostProblemStoreMode::kHostPreparedStore;
    return true;
  }
  return false;
}

const char* CudaHostProblemStoreModeName(
    const CudaHostProblemStoreMode mode) {
  switch (mode) {
    case CudaHostProblemStoreMode::kDisabled: return "disabled";
    case CudaHostProblemStoreMode::kHostPreparedStore:
      return "host_prepared_store";
  }
  return "invalid";
}

void SetCudaHostProblemStoreLookupHashForTesting(
    const uint64_t value) noexcept {
  g_host_store_lookup_hash_for_testing.store(value,
                                              std::memory_order_relaxed);
}

bool PrepareCudaIndexedActiveSolve(
    const CudaSolveProblem& problem,
    const CudaFullLmOptions& options,
    const CudaHostStoreBinding& binding,
    PreparedIndexedActiveSolve* prepared,
    std::string* error) {
  if (prepared == nullptr || error == nullptr) return false;
  prepared->CancelIfActive();
  prepared->runtime_ = CudaHostProblemStoreRuntimeInfo();
  prepared->runtime_.mode_requested = "host_prepared_store";
  prepared->runtime_.mode_effective = "host_prepared_store";
  error->clear();
  if (binding.mode != CudaHostProblemStoreMode::kHostPreparedStore ||
      binding.store == nullptr || binding.store->control_ == nullptr) {
    *error = "indexed catalog requires an enabled host store binding";
    prepared->runtime_.mode_effective = "invalid";
    return false;
  }

  std::shared_ptr<GpuBaHostProblemStoreControl> control =
      binding.store->control_;
  GpuBaHostProblemStoreControl& store = *control;
  prepared->runtime_.owner_epoch = binding.owner_epoch;
  if (store.shutdown || store.shutdown_requested ||
      store.reconstruction == nullptr || binding.owner_epoch == 0 ||
      binding.owner_epoch != store.owner_epoch ||
      HostReconstructionOwnerEpoch(store.reconstruction) != store.owner_epoch) {
    *error = "indexed catalog owner identity mismatch";
    prepared->runtime_.mode_effective = "invalid";
    ++prepared->runtime_.owner_identity_violations;
    ++store.lifetime.owner_identity_violations;
    return false;
  }
  if (store.active) {
    *error = "StoreBusy: host store already has an active solve";
    ++prepared->runtime_.store_busy_failures;
    ++store.lifetime.store_busy_failures;
    return false;
  }

  store.active = true;
  store.active_lease_generation = ++store.next_lease_generation;
  if (store.active_lease_generation == 0) {
    store.active_lease_generation = ++store.next_lease_generation;
  }
  const auto preparation_start = std::chrono::steady_clock::now();
  const auto fail = [&]() {
    prepared->runtime_.host_preparation_total_wall_milliseconds =
        std::chrono::duration<double, std::milli>(
            std::chrono::steady_clock::now() - preparation_start).count();
    prepared->runtime_.journal_cursor_after = store.indexed_journal_cursor;
    prepared->runtime_.catalog_generation = store.indexed_catalog == nullptr
        ? 0 : store.indexed_catalog->generation();
    prepared->runtime_.host_catalog_valid = store.indexed_catalog != nullptr;
    prepared->runtime_.host_resident_bytes = store.lifetime.host_resident_bytes;
    AccumulateHostStoreRuntime(prepared->runtime_, &store.lifetime);
    store.active = false;
    store.active_lease_generation = 0;
    return false;
  };

  try {
    prepared->runtime_.owner_epoch = store.owner_epoch;
    prepared->runtime_.journal_cursor_before = store.indexed_journal_cursor;
    prepared->runtime_.journal_cursor_after = store.indexed_journal_cursor;
    ++prepared->runtime_.store_lookup_calls;

    CudaLayerCOptions step_options;
    CudaArithmeticPrecision precision = CudaArithmeticPrecision::kFp64;
    HotKernelImplementation hot_kernel = HotKernelImplementation::kReference;
    CudaSchurContributionBackend schur_backend =
        CudaSchurContributionBackend::kDirectTransformed;
    if (!ResolvePreparedHostBuildConfiguration(
            options, &step_options, &precision, &hot_kernel, &schur_backend,
            error)) {
      return fail();
    }
    if (precision != CudaArithmeticPrecision::kFp64 &&
        precision != CudaArithmeticPrecision::kFp32MixedStable) {
      *error = "indexed catalog supports fp64 and fp32_mixed precision";
      return fail();
    }

    IndexedActiveSolveConfig config;
    config.effective_config_resolved = true;
    if (store.next_config_generation ==
        std::numeric_limits<uint64_t>::max()) {
      *error = "indexed catalog config generation exhausted";
      return fail();
    }
    config.config_generation = ++store.next_config_generation;
    if (config.config_generation == 0) {
      config.config_generation = ++store.next_config_generation;
    }
    config.arithmetic_precision = precision;
    config.schur_backend = schur_backend;
    config.execution_profile = options.execution_profile;
    switch (hot_kernel) {
      case HotKernelImplementation::kReference:
        config.hot_kernel = CudaHotKernelMode::kReference;
        break;
      case HotKernelImplementation::kOptimized:
        config.hot_kernel = CudaHotKernelMode::kOptimized;
        break;
      case HotKernelImplementation::kTransformed:
        config.hot_kernel = CudaHotKernelMode::kTransformed;
        break;
    }
    std::string hessian_requested;
    if (!ResolveHessianAssemblyBackend(
            step_options.layer_b.hessian_assembly_backend, hot_kernel,
            &config.hessian_backend, &hessian_requested, error) ||
        !ResolveCudaLoss(problem, step_options.layer_b, &config.loss_mode,
                         &config.loss_scale, error)) {
      return fail();
    }

    const auto lookup_start = std::chrono::steady_clock::now();
    HostStructureReadResult journal;
    if (!ReadHostStructureEventsSince(
            store.reconstruction, store.owner_epoch,
            store.indexed_journal_cursor, &journal, error) ||
        journal.owner_epoch != store.owner_epoch) {
      if (error->empty()) *error = "indexed catalog journal owner mismatch";
      return fail();
    }
    uint64_t event_count = 0;
    uint64_t unknown_count = 0;
    for (const HostStructureBatch& batch : journal.batches) {
      event_count = SaturatingAdd(event_count, batch.events.size());
      for (const HostStructureEvent& event : batch.events) {
        if (event.kind == HostStructureEventKind::kBulkUnknown)
          unknown_count = SaturatingAdd(unknown_count, 1);
      }
    }
    const bool has_unknown = unknown_count != 0;
    prepared->runtime_.journal_events = event_count;
    prepared->runtime_.journal_unknown_events = unknown_count;
    prepared->runtime_.store_lookup_wall_milliseconds =
        std::chrono::duration<double, std::milli>(
            std::chrono::steady_clock::now() - lookup_start).count();

    const bool cold = store.indexed_catalog_root == nullptr ||
                      store.indexed_catalog == nullptr ||
                      store.indexed_catalog_tables == nullptr;
    const bool journal_gap = !journal.complete || journal.gap;
    constexpr uint32_t kMaximumIndexedCatalogOverlayDepth = 32;
    const bool overlay_compaction =
        !cold && event_count != 0 && store.indexed_catalog_root != nullptr &&
        store.indexed_catalog_root->overlay_depth >=
            kMaximumIndexedCatalogOverlayDepth;
    const bool force_full_rebuild =
        cold || journal_gap || has_unknown || overlay_compaction;
    bool full_catalog_rebuild = force_full_rebuild;
    if (journal_gap) {
      ++prepared->runtime_.journal_gaps;
      if (store.indexed_journal_cursor < journal.oldest_retained_revision)
        ++prepared->runtime_.journal_overflows;
    }

    std::shared_ptr<const StaticProblemDataCatalog> pending_root =
        store.indexed_catalog_root;
    std::shared_ptr<MapperStaticProblemDataCatalog> pending_catalog =
        store.indexed_catalog;
    std::shared_ptr<MapperStaticCatalogStableTables> pending_tables =
        store.indexed_catalog_tables;
    uint64_t pending_root_generation = store.indexed_catalog_generation;
    uint64_t flat_transient_bytes = 0;
    uint64_t reconcile_transient_bytes = 0;
    MapperStaticCatalogUpdateResult update;
    const bool catalog_update_required = force_full_rebuild || event_count != 0;
    const auto catalog_update_start = std::chrono::steady_clock::now();
    if (catalog_update_required) {
      if (pending_root_generation == std::numeric_limits<uint64_t>::max()) {
        *error = "indexed host catalog generation exhausted";
        return fail();
      }
      ++pending_root_generation;
      if (pending_root_generation == 0) ++pending_root_generation;
      if (full_catalog_rebuild) {
        ++prepared->runtime_.indexed_catalog_full_graph_build_calls;
        ++prepared->runtime_.host_builder_calls_executed;
        ++prepared->runtime_.host_builder_traversals_executed;
        if (!BuildStaticProblemDataCatalog(
                store.reconstruction, store.owner_epoch,
                journal.current_revision, pending_root_generation,
                &pending_root, error)) {
          return fail();
        }
        if (cold) {
          ++prepared->runtime_.catalog_cold_builds;
          prepared->runtime_.view_action = "indexed_catalog_cold_build";
          prepared->runtime_.rebuild_reason = "catalog_cold";
        } else {
          ++prepared->runtime_.catalog_full_rebuilds;
          ++prepared->runtime_.fallback_rebuilds;
          prepared->runtime_.view_action = "indexed_catalog_full_rebuild";
          prepared->runtime_.rebuild_reason = journal_gap
              ? "journal_gap"
              : (has_unknown ? "journal_bulk_unknown"
                             : "catalog_overlay_compaction");
        }
        ++prepared->runtime_.store_misses;
      } else {
        ++prepared->runtime_.indexed_catalog_journal_apply_calls;
        ++prepared->runtime_.host_builder_calls_executed;
        ++prepared->runtime_.host_builder_traversals_executed;
        if (!ApplyStructureJournalToCatalog(
                store.reconstruction, journal, pending_root_generation,
                store.indexed_catalog_root, &pending_root, error)) {
          const std::string delta_error = *error;
          error->clear();
          ++prepared->runtime_.indexed_catalog_full_graph_build_calls;
          ++prepared->runtime_.host_builder_calls_executed;
          ++prepared->runtime_.host_builder_traversals_executed;
          if (!BuildStaticProblemDataCatalog(
                  store.reconstruction, store.owner_epoch,
                  journal.current_revision, pending_root_generation,
                  &pending_root, error)) {
            *error = "indexed catalog delta apply failed (" + delta_error +
                     "); full rebuild also failed: " + *error;
            return fail();
          }
          full_catalog_rebuild = true;
          ++prepared->runtime_.catalog_full_rebuilds;
          ++prepared->runtime_.fallback_rebuilds;
          ++prepared->runtime_.store_misses;
          prepared->runtime_.view_action = "indexed_catalog_full_rebuild";
          prepared->runtime_.rebuild_reason = "catalog_delta_apply_failed";
        } else {
          ++prepared->runtime_.catalog_delta_updates;
          ++prepared->runtime_.store_hits;
          prepared->runtime_.view_action = "indexed_catalog_delta_update";
        }
      }

      // The journal conversion is incremental and transactional. Flattening
      // the overlay plus copying the stable Impl/export tables is still a
      // measured O(catalog) preparation debt; the counters below prevent it
      // from being reported as an O(delta) fast path.
      HostIndexedCatalogData flat;
      ++prepared->runtime_.indexed_catalog_flatten_calls;
      ++prepared->runtime_.host_builder_calls_executed;
      ++prepared->runtime_.host_builder_traversals_executed;
      if (!FlattenStaticProblemDataCatalog(pending_root, &flat, error)) {
        return fail();
      }
      flat_transient_bytes = flat.resident_bytes;
      if (full_catalog_rebuild) {
        const uint64_t generation_floor = store.indexed_catalog == nullptr
            ? 0 : store.indexed_catalog->generation();
        pending_catalog = std::make_shared<MapperStaticProblemDataCatalog>(
            store.owner_epoch, generation_floor);
      } else {
        // Copy-on-write publication currently clones the complete stable Impl
        // before Reconcile performs its own transactional pending copy.
        // Account for that debt explicitly until slot-level COW lands.
        prepared->runtime_.indexed_estimated_impl_copy_bytes =
            store.indexed_catalog->EstimatedResidentBytes();
        pending_catalog =
            std::make_shared<MapperStaticProblemDataCatalog>(
                *store.indexed_catalog);
      }
      ++prepared->runtime_.indexed_catalog_reconcile_calls;
      ++prepared->runtime_.host_builder_calls_executed;
      ++prepared->runtime_.host_builder_traversals_executed;
      if (!pending_catalog->ReconcileFullStaticData(flat, &update, error)) {
        return fail();
      }
      reconcile_transient_bytes = update.estimated_impl_copy_bytes;
      prepared->runtime_.indexed_full_graph_records_scanned =
          update.full_graph_records_scanned;
      prepared->runtime_.indexed_estimated_impl_copy_bytes = SaturatingAdd(
          prepared->runtime_.indexed_estimated_impl_copy_bytes,
          update.estimated_impl_copy_bytes);
      pending_tables = std::make_shared<MapperStaticCatalogStableTables>();
      ++prepared->runtime_.indexed_catalog_export_calls;
      ++prepared->runtime_.host_builder_calls_executed;
      ++prepared->runtime_.host_builder_traversals_executed;
      if (!pending_catalog->ExportStableTables(pending_tables.get(), error)) {
        return fail();
      }
      uint64_t export_bytes = 0;
      const auto add_export_bytes = [&](const uint64_t count,
                                        const uint64_t element_bytes) {
        uint64_t bytes = 0;
        if (!CheckedMultiply(count, element_bytes, &bytes)) {
          export_bytes = std::numeric_limits<uint64_t>::max();
        } else {
          export_bytes = SaturatingAdd(export_bytes, bytes);
        }
      };
      add_export_bytes(pending_tables->cameras.size(),
                       sizeof(MapperCatalogCameraSlot));
      add_export_bytes(pending_tables->images.size(),
                       sizeof(MapperCatalogImageSlot));
      add_export_bytes(pending_tables->points.size(),
                       sizeof(MapperCatalogPointSlot));
      add_export_bytes(pending_tables->observations.size(),
                       sizeof(MapperCatalogObservationSlot));
      add_export_bytes(pending_tables->image_incidences.size(),
                       sizeof(MapperCatalogIncidenceSlot));
      add_export_bytes(pending_tables->point_incidences.size(),
                       sizeof(MapperCatalogIncidenceSlot));
      prepared->runtime_.indexed_estimated_export_bytes = export_bytes;
      prepared->runtime_.estimated_host_builder_bytes_executed =
          SaturatingAdd(
              prepared->runtime_.indexed_estimated_impl_copy_bytes,
              export_bytes);
    } else {
      ++prepared->runtime_.store_hits;
      prepared->runtime_.view_action = "indexed_catalog_reuse";
    }
    prepared->runtime_.catalog_delta_update_wall_milliseconds =
        std::chrono::duration<double, std::milli>(
            std::chrono::steady_clock::now() - catalog_update_start).count();

    std::shared_ptr<IndexedActiveSolveDescriptor> descriptor =
        std::make_shared<IndexedActiveSolveDescriptor>();
    const auto materialize_start = std::chrono::steady_clock::now();
    ++prepared->runtime_.indexed_active_materializer_calls;
    ++prepared->runtime_.host_builder_calls_executed;
    ++prepared->runtime_.host_builder_traversals_executed;
    if (!store.indexed_materializer.Materialize(
            store.owner_epoch, *pending_catalog, problem, config,
            descriptor.get(),
            error)) {
      return fail();
    }
    ++prepared->runtime_.dynamic_state_refresh_calls;
    prepared->runtime_.dynamic_state_refresh_wall_milliseconds =
        descriptor->runtime.dynamic_state_wall_milliseconds;
    ++prepared->runtime_.solve_view_rebuilds;
    prepared->runtime_.solve_view_build_or_patch_wall_milliseconds =
        std::chrono::duration<double, std::milli>(
            std::chrono::steady_clock::now() - materialize_start).count();
    if (descriptor->identity.catalog_revision !=
            pending_tables->catalog_revision ||
        descriptor->identity.catalog_generation !=
            pending_tables->catalog_generation ||
        descriptor->identity.owner_epoch != pending_tables->owner_epoch) {
      *error = "indexed descriptor and stable catalog publication mismatch";
      return fail();
    }
    std::shared_ptr<PreparedIndexedCatalogPublication> publication =
        std::make_shared<PreparedIndexedCatalogPublication>();
    publication->root = std::move(pending_root);
    publication->catalog = std::move(pending_catalog);
    publication->tables = pending_tables;
    publication->journal_cursor = journal.current_revision;
    publication->root_generation = pending_root_generation;
    uint64_t root_resident_bytes = 0;
    for (auto node = publication->root; node != nullptr; node = node->parent) {
      root_resident_bytes = SaturatingAdd(root_resident_bytes,
                                          node->resident_bytes);
    }
    publication->resident_bytes = SaturatingAdd(
        root_resident_bytes,
        SaturatingAdd(publication->catalog->EstimatedResidentBytes(),
                      prepared->runtime_.indexed_estimated_export_bytes));
    const uint64_t retained_peak_bytes = catalog_update_required
        ? SaturatingAdd(store.lifetime.host_resident_bytes,
                        publication->resident_bytes)
        : publication->resident_bytes;
    publication->peak_bytes = SaturatingAdd(
        retained_peak_bytes,
        SaturatingAdd(
            flat_transient_bytes,
            SaturatingAdd(reconcile_transient_bytes,
                          descriptor->runtime.descriptor_bytes)));
    prepared->runtime_.catalog_generation =
        publication->catalog->generation();
    prepared->runtime_.view_generation =
        descriptor->identity.solve_view_generation;
    prepared->runtime_.config_generation = config.config_generation;
    prepared->runtime_.host_resident_bytes = publication->resident_bytes;
    prepared->runtime_.host_peak_bytes = std::max(
        store.lifetime.host_peak_bytes, publication->peak_bytes);
    prepared->runtime_.host_catalog_valid = true;
    prepared->runtime_.host_preparation_total_wall_milliseconds =
        std::chrono::duration<double, std::milli>(
            std::chrono::steady_clock::now() - preparation_start).count();
    prepared->descriptor_ = std::move(descriptor);
    prepared->catalog_tables_ = std::move(pending_tables);
    prepared->control_ = std::move(control);
    prepared->publication_ = std::move(publication);
    prepared->lease_generation_ = store.active_lease_generation;
    prepared->owner_epoch_ = store.owner_epoch;
    prepared->active_ = true;
    return true;
  } catch (const std::bad_alloc&) {
    *error = "indexed catalog preparation allocation failed";
    return fail();
  }
}

bool PrepareCudaHostSolveView(
    const CudaSolveProblem& snapshot,
    const CudaFullLmOptions& options,
    const CudaHostStoreBinding& binding,
    PreparedHostSolveView* view,
    CudaHostProblemStoreRuntimeInfo* runtime,
    std::string* error) {
  if (view == nullptr || runtime == nullptr || error == nullptr) return false;
  view->CancelIfActive();
  *runtime = CudaHostProblemStoreRuntimeInfo();
  error->clear();
  runtime->mode_requested = CudaHostProblemStoreModeName(binding.mode);
  runtime->mode_effective = runtime->mode_requested;
  if (binding.mode == CudaHostProblemStoreMode::kDisabled) {
    runtime->view_action = "disabled";
    return true;
  }
  if (binding.mode != CudaHostProblemStoreMode::kHostPreparedStore ||
      binding.store == nullptr || binding.store->control_ == nullptr) {
    *error = "host prepared store binding is invalid";
    runtime->mode_effective = "invalid";
    ++runtime->owner_identity_violations;
    return false;
  }
  std::shared_ptr<GpuBaHostProblemStoreControl> store_control =
      binding.store->control_;
  GpuBaHostProblemStoreControl& store = *store_control;
  runtime->owner_epoch = binding.owner_epoch;
  runtime->journal_cursor_before = store.journal_cursor;
  if (store.shutdown || store.shutdown_requested ||
      store.reconstruction == nullptr ||
      binding.owner_epoch == 0 || binding.owner_epoch != store.owner_epoch ||
      HostReconstructionOwnerEpoch(store.reconstruction) != store.owner_epoch) {
    *error = "host prepared store owner identity mismatch";
    ++runtime->owner_identity_violations;
    return false;
  }
  if (store.active) {
    *error = "StoreBusy: host prepared store already has an active solve";
    ++runtime->store_busy_failures;
    AccumulateHostStoreRuntime(*runtime, &store.lifetime);
    return false;
  }
  store.active = true;
  store.active_lease_generation = ++store.next_lease_generation;
  const auto fail = [&]() {
    store.active = false;
    store.active_lease_generation = 0;
    AccumulateHostStoreRuntime(*runtime, &store.lifetime);
    return false;
  };

  const auto lookup_start = std::chrono::steady_clock::now();
  ++runtime->store_lookup_calls;
  const auto descriptor_start = std::chrono::steady_clock::now();
  const uint64_t structural_identity =
      HashPreparedHostViewDescriptor(snapshot, options);
  runtime->snapshot_descriptor_wall_milliseconds =
      snapshot.prepared_host_descriptor_wall_milliseconds +
      std::chrono::duration<double, std::milli>(
          std::chrono::steady_clock::now() - descriptor_start).count();
  if (structural_identity == 0) {
    *error = "host prepared view requires a recorder-produced descriptor";
    ++runtime->coverage_violations;
    return fail();
  }
  HostStructureReadResult journal;
  if (!ReadHostStructureEventsSince(
          store.reconstruction, store.owner_epoch, store.journal_cursor,
          &journal, error)) {
    return fail();
  }
  bool force_full_rebuild = !store.catalog_valid || store.catalog == nullptr;
  bool unknown = false;
  uint64_t event_count = 0;
  if (!store.catalog_valid) {
    ++runtime->catalog_cold_builds;
    runtime->rebuild_reason = "catalog_cold";
  } else if (!journal.complete || journal.gap) {
    ++runtime->journal_gaps;
    ++runtime->catalog_full_rebuilds;
    ++runtime->fallback_rebuilds;
    runtime->rebuild_reason = "journal_gap";
    force_full_rebuild = true;
  } else {
    const auto delta_start = std::chrono::steady_clock::now();
    for (const HostStructureBatch& batch : journal.batches) {
      for (const HostStructureEvent& event : batch.events) {
        ++event_count;
        if (event.kind == HostStructureEventKind::kBulkUnknown) {
          unknown = true;
          ++runtime->journal_unknown_events;
          if (runtime->rebuild_reason.empty())
            runtime->rebuild_reason = event.reason;
        }
      }
    }
    runtime->journal_events = event_count;
    if (unknown) {
      ++runtime->catalog_full_rebuilds;
      ++runtime->fallback_rebuilds;
      force_full_rebuild = true;
    } else if (event_count != 0) {
      ++runtime->catalog_delta_updates;
    }
    runtime->catalog_delta_update_wall_milliseconds =
        std::chrono::duration<double, std::milli>(
            std::chrono::steady_clock::now() - delta_start).count();
  }
  const uint64_t source_revision = journal.current_revision == 0
      ? HostReconstructionStructureRevision(store.reconstruction)
      : journal.current_revision;
  std::shared_ptr<const StaticProblemDataCatalog> pending_catalog =
      store.catalog;
  const uint64_t pending_catalog_generation =
      store.catalog_generation +
      ((force_full_rebuild || event_count != 0 || pending_catalog == nullptr)
           ? 1 : 0);
  const auto catalog_start = std::chrono::steady_clock::now();
  if (force_full_rebuild || pending_catalog == nullptr) {
    if (!BuildStaticProblemDataCatalog(
            store.reconstruction, store.owner_epoch, source_revision,
            std::max<uint64_t>(1, pending_catalog_generation),
            &pending_catalog, error)) {
      return fail();
    }
  } else if (event_count != 0) {
    constexpr uint32_t kMaximumCatalogOverlayDepth = 32;
    if (pending_catalog->overlay_depth >= kMaximumCatalogOverlayDepth) {
      ++runtime->catalog_full_rebuilds;
      ++runtime->fallback_rebuilds;
      runtime->rebuild_reason = "catalog_overlay_compaction";
      force_full_rebuild = true;
      if (!BuildStaticProblemDataCatalog(
              store.reconstruction, store.owner_epoch, source_revision,
              pending_catalog_generation, &pending_catalog, error)) {
        return fail();
      }
    } else if (!ApplyStructureJournalToCatalog(
                   store.reconstruction, journal,
                   pending_catalog_generation, pending_catalog,
                   &pending_catalog, error)) {
      ++runtime->fallback_rebuilds;
      runtime->rebuild_reason = "catalog_delta_validation_failed";
      force_full_rebuild = true;
      if (!BuildStaticProblemDataCatalog(
              store.reconstruction, store.owner_epoch, source_revision,
              pending_catalog_generation, &pending_catalog, error)) {
        return fail();
      }
    }
  }
  runtime->catalog_delta_update_wall_milliseconds +=
      std::chrono::duration<double, std::milli>(
          std::chrono::steady_clock::now() - catalog_start).count();

  CudaLayerCOptions step_options;
  CudaArithmeticPrecision precision = CudaArithmeticPrecision::kFp64;
  HotKernelImplementation hot_kernel = HotKernelImplementation::kReference;
  CudaSchurContributionBackend schur_backend =
      CudaSchurContributionBackend::kDirectTransformed;
  if (!ResolvePreparedHostBuildConfiguration(
          options, &step_options, &precision, &hot_kernel, &schur_backend,
          error)) {
    return fail();
  }
  CudaHessianAssemblyBackend hessian_backend =
      CudaHessianAssemblyBackend::kPoseOwnedScalarCompatibility;
  std::string hessian_requested;
  CudaLossMode resolved_loss_mode = CudaLossMode::kTrivial;
  double resolved_loss_scale = 1.0;
  if (!ResolveHessianAssemblyBackend(
          step_options.layer_b.hessian_assembly_backend, hot_kernel,
          &hessian_backend, &hessian_requested, error) ||
      !ResolveCudaLoss(snapshot, step_options.layer_b, &resolved_loss_mode,
                       &resolved_loss_scale, error)) {
    return fail();
  }
  const auto configuration_matches = [&](
      const PreparedHostSolveViewData& value) {
    return value.residual_order == step_options.layer_b.layer_a.residual_order &&
           value.loss_mode == resolved_loss_mode &&
           value.loss_scale == resolved_loss_scale &&
           value.hessian_backend == hessian_backend &&
           value.schur_backend == schur_backend &&
           value.hot_kernel_mode == options.hot_kernel_mode &&
           value.arithmetic_precision == precision &&
           value.execution_profile == options.execution_profile &&
           value.pair_chunk_limit_bytes ==
               step_options.pair_chunk_limit_bytes_for_testing &&
           value.hessian_segment_size ==
               step_options.layer_b.hessian_segment_size_for_testing &&
           value.schur_segment_size ==
               step_options.schur_segment_size_for_testing;
  };

  std::shared_ptr<const PreparedHostSolveViewData> prepared;
  const auto cached = store.views.find(structural_identity);
  const bool cached_configuration_matches =
      cached != store.views.end() && configuration_matches(*cached->second);
  const bool cached_descriptor_matches =
      cached_configuration_matches &&
      PreparedHostCanonicalDescriptorMatches(*cached->second, snapshot);
  if (!force_full_rebuild && cached_descriptor_matches) {
    prepared = cached->second;
    ++runtime->store_hits;
    ++runtime->exact_view_reuses;
    runtime->view_action = "exact_view_reuse";
    runtime->host_builder_calls_saved = prepared->builder_calls_executed;
    runtime->host_builder_traversals_saved =
        prepared->builder_traversals_executed;
    runtime->estimated_host_builder_bytes_saved =
        prepared->estimated_host_bytes;
  } else {
    ++runtime->store_misses;
    if (!force_full_rebuild && cached != store.views.end() &&
        runtime->rebuild_reason.empty()) {
      runtime->rebuild_reason = cached_configuration_matches
          ? "canonical_descriptor_mismatch"
          : "resolved_configuration_mismatch";
    }
    const auto build_start = std::chrono::steady_clock::now();
    const uint64_t builder_calls_before =
        runtime->host_builder_calls_executed;
    const uint64_t builder_traversals_before =
        runtime->host_builder_traversals_executed;
    std::shared_ptr<PreparedHostSolveViewData> pending(
        new PreparedHostSolveViewData());
    if (!BuildPreparedHostViewFromCatalog(
            snapshot, step_options, precision, hot_kernel, schur_backend,
            options.execution_profile, pending_catalog, runtime,
            pending.get(), error)) {
      return fail();
    }
    pending->structural_identity = structural_identity;
    pending->owner_epoch = store.owner_epoch;
    pending->catalog_generation = pending_catalog->generation;
    pending->view_generation = ++store.next_view_generation;
    pending->config_generation = ++store.next_config_generation;
    pending->source_revision = source_revision;
    pending->schur_backend = schur_backend;
    pending->hot_kernel_mode = options.hot_kernel_mode;
    pending->arithmetic_precision = precision;
    pending->execution_profile = options.execution_profile;
    pending->pair_chunk_limit_bytes =
        step_options.pair_chunk_limit_bytes_for_testing;
    pending->hessian_segment_size =
        step_options.layer_b.hessian_segment_size_for_testing;
    pending->schur_segment_size =
        step_options.schur_segment_size_for_testing;
    pending->estimated_host_bytes = EstimatePreparedHostBytes(*pending);
    pending->builder_calls_executed =
        runtime->host_builder_calls_executed - builder_calls_before;
    pending->builder_traversals_executed =
        runtime->host_builder_traversals_executed -
        builder_traversals_before;
    pending->cold_build_milliseconds =
        std::chrono::duration<double, std::milli>(
            std::chrono::steady_clock::now() - build_start).count();
    prepared = std::move(pending);
    runtime->estimated_host_builder_bytes_executed =
        prepared->estimated_host_bytes;
    runtime->solve_view_build_or_patch_wall_milliseconds =
        prepared->cold_build_milliseconds;
    ++runtime->solve_view_rebuilds;
    runtime->view_action = store.catalog_valid
        ? "solve_view_rebuild_from_catalog"
        : "solve_view_rebuild";
  }
  runtime->catalog_generation = pending_catalog->generation;
  runtime->view_generation = prepared->view_generation;
  runtime->config_generation = prepared->config_generation;
  // source_revision belongs to the pending publication. The public "after"
  // counter is strictly the committed cursor until Complete(true) succeeds.
  runtime->journal_cursor_after = store.journal_cursor;
  runtime->host_resident_bytes = store.lifetime.host_resident_bytes;
  runtime->host_peak_bytes = std::max(store.lifetime.host_peak_bytes,
                                      prepared->estimated_host_bytes);
  runtime->host_catalog_valid = store.catalog_valid;
  runtime->device_static_h2d_saved_calls = 0;
  runtime->device_static_h2d_saved_bytes = 0;
  runtime->device_prepared_context_reuse = false;
  runtime->full_cross_solve_initialization_removed = false;
  runtime->store_lookup_wall_milliseconds =
      std::chrono::duration<double, std::milli>(
          std::chrono::steady_clock::now() - lookup_start).count();
  runtime->host_preparation_total_wall_milliseconds =
      runtime->snapshot_descriptor_wall_milliseconds +
      runtime->catalog_delta_update_wall_milliseconds +
      runtime->solve_view_build_or_patch_wall_milliseconds;
  std::shared_ptr<PreparedHostStorePublication> publication;
  try {
    publication.reset(new PreparedHostStorePublication());
    publication->catalog = pending_catalog;
    if (!force_full_rebuild) {
      publication->views = store.views;
      publication->lru = store.lru;
    } else {
      runtime->invalidations += store.views.size();
    }
    publication->views[structural_identity] = prepared;
    publication->lru.erase(
        std::remove(publication->lru.begin(), publication->lru.end(),
                    structural_identity),
        publication->lru.end());
    publication->lru.push_back(structural_identity);
    constexpr size_t kMaximumRetainedViews = 16;
    while (publication->lru.size() > kMaximumRetainedViews) {
      const uint64_t evicted = publication->lru.front();
      publication->lru.pop_front();
      publication->views.erase(evicted);
      ++runtime->evictions;
    }
    publication->journal_cursor = source_revision;
    publication->catalog_generation = pending_catalog->generation;
    for (auto node = pending_catalog; node != nullptr; node = node->parent) {
      publication->resident_bytes = SaturatingAdd(
          publication->resident_bytes, node->resident_bytes);
    }
    for (const auto& item : publication->views) {
      publication->resident_bytes = SaturatingAdd(
          publication->resident_bytes, item.second->estimated_host_bytes);
    }
  } catch (const std::bad_alloc&) {
    *error = "host prepared store publication allocation failed";
    return fail();
  }
  runtime->host_resident_bytes = publication->resident_bytes;
  runtime->host_peak_bytes = std::max(
      store.lifetime.host_peak_bytes, publication->resident_bytes);
  view->data_ = std::move(prepared);
  view->control_ = std::move(store_control);
  view->publication_ = std::move(publication);
  view->lease_generation_ = store.active_lease_generation;
  view->owner_epoch_ = store.owner_epoch;
  view->catalog_generation_ = view->data_->catalog_generation;
  view->view_generation_ = view->data_->view_generation;
  view->config_generation_ = view->data_->config_generation;
  view->source_revision_ = source_revision;
  view->catalog_generation_ = view->publication_->catalog_generation;
  runtime->catalog_generation = view->catalog_generation_;
  view->active_ = true;
  view->runtime_ = *runtime;
  return true;
}

bool BuildCudaLayerAInputs(const Snapshot& snapshot,
                           CudaResidualOrder residual_order,
                           std::vector<CudaVisualInput>* visual,
                           std::vector<CudaLidarInput>* lidar,
                           std::string* error) {
  HostPhaseScope timing(CUDA_TIMING_PHASE(build_cuda_layer_a_inputs));
  if (g_cuda_solve_call_counters != nullptr)
    ++g_cuda_solve_call_counters->build_cuda_layer_a_inputs;
  if (g_cuda_timing_sink != nullptr) {
    ++g_cuda_timing_sink->build_cuda_layer_a_inputs_count;
  }
  if (visual == nullptr || lidar == nullptr || error == nullptr) return false;
  error->clear();
  visual->clear();
  lidar->clear();
  SnapshotLookup lookup;
  if (!BuildLookup(snapshot, &lookup, error)) return false;

  LidarResidualMode lidar_mode;
  const std::string mode_name = snapshot.metadata.lidar_residual_mode.empty()
                                    ? "legacy_exact"
                                    : snapshot.metadata.lidar_residual_mode;
  if (!ParseLidarResidualMode(mode_name, &lidar_mode)) {
    *error = "unsupported lidar residual mode: " + mode_name;
    return false;
  }

  const std::vector<OrderEntrySnapshot>& selected_order =
      residual_order == CudaResidualOrder::kSourceInsertion
          ? snapshot.source_insertion_order
          : snapshot.canonical_order;
  std::vector<OrderEntrySnapshot> order = selected_order;
  if (order.empty()) {
    order.reserve(snapshot.observations.size() + snapshot.lidar.size());
    for (const ObservationSnapshot& value : snapshot.observations) {
      OrderEntrySnapshot entry;
      entry.source_index = value.source_index;
      entry.residual_kind = ResidualKind::kVisual;
      entry.image_id = value.image_id;
      entry.point2D_idx = value.point2D_idx;
      entry.point3D_id = value.point3D_id;
      order.push_back(entry);
    }
    for (const LidarSnapshot& value : snapshot.lidar) {
      OrderEntrySnapshot entry;
      entry.source_index = value.source_index;
      entry.residual_kind = ResidualKind::kLidar;
      entry.point3D_id = value.point3D_id;
      order.push_back(entry);
    }
    std::sort(order.begin(), order.end(), [](const OrderEntrySnapshot& lhs,
                                             const OrderEntrySnapshot& rhs) {
      return std::tie(lhs.residual_kind, lhs.image_id, lhs.point2D_idx,
                      lhs.point3D_id, lhs.source_index) <
             std::tie(rhs.residual_kind, rhs.image_id, rhs.point2D_idx,
                      rhs.point3D_id, rhs.source_index);
    });
  }

  for (const OrderEntrySnapshot& entry : order) {
    if (entry.residual_kind == ResidualKind::kVisual) {
      const auto it = lookup.observations.find(entry.source_index);
      if (it == lookup.observations.end()) {
        *error = "canonical visual order references missing observation";
        return false;
      }
      CudaVisualInput packed;
      if (!PackVisual(lookup, *it->second, &packed, error)) return false;
      visual->push_back(packed);
    } else {
      const auto it = lookup.lidar.find(entry.source_index);
      if (it == lookup.lidar.end()) {
        *error = "canonical lidar order references missing residual";
        return false;
      }
      CudaLidarInput packed;
      if (!PackLidar(lookup, *it->second, lidar_mode, &packed, error)) {
        return false;
      }
      lidar->push_back(packed);
    }
  }
  if (g_cuda_timing_sink != nullptr) {
    g_cuda_timing_sink->build_cuda_layer_a_inputs.bytes = SaturatingAdd(
        g_cuda_timing_sink->build_cuda_layer_a_inputs.bytes,
        static_cast<uint64_t>(visual->size() * sizeof(CudaVisualInput) +
                              lidar->size() * sizeof(CudaLidarInput)));
  }
  return true;
}

bool BuildCudaLayerAInputs(const Snapshot& snapshot,
                           std::vector<CudaVisualInput>* visual,
                           std::vector<CudaLidarInput>* lidar,
                           std::string* error) {
  return BuildCudaLayerAInputs(snapshot, CudaResidualOrder::kCanonical,
                               visual, lidar, error);
}

bool RunCudaLayerA(const std::vector<CudaVisualInput>& visual,
                   const std::vector<CudaLidarInput>& lidar,
                   const CudaLayerAOptions& options,
                   CudaLayerAResult* result) {
  CudaCacheCallScope cache_scope;
  if (result == nullptr) return false;
  *result = CudaLayerAResult();
  if (!CudaStandaloneEntryAllowed(&result->error)) return false;
  TimingLedgerScope timing_scope(&result->runtime.timing);
  InclusiveCallScope inclusive_call(CUDA_TIMING_PHASE(layer_a_call));
  if (g_cuda_solve_call_counters != nullptr)
    ++g_cuda_solve_call_counters->layer_a;
  if (g_cuda_timing_sink != nullptr) ++g_cuda_timing_sink->layer_a_calls;
  const auto host_start = std::chrono::steady_clock::now();
  if (options.block_size <= 0 || options.block_size > 1024) {
    result->error = "invalid CUDA block size";
    return false;
  }
  cudaError_t status = cudaSetDevice(options.device);
  if (status != cudaSuccess) {
    result->error = std::string("cudaSetDevice failed: ") + CudaErrorText(status);
    return false;
  }
  result->runtime.device = options.device;
  result->runtime.used_unified_memory =
      options.memory_mode == CudaMemoryMode::kUnifiedManaged;
  result->runtime.explicit_synchronization = true;
  cudaDeviceProp properties;
  status = cudaGetDeviceProperties(&properties, options.device);
  if (status != cudaSuccess) {
    result->error = std::string("cudaGetDeviceProperties failed: ") +
                    CudaErrorText(status);
    return false;
  }
  result->runtime.device_major = properties.major;
  result->runtime.device_minor = properties.minor;
  result->runtime.visual_bytes = visual.size() * sizeof(CudaVisualInput);
  result->runtime.lidar_bytes = lidar.size() * sizeof(CudaLidarInput);
  result->runtime.output_bytes =
      visual.size() * sizeof(CudaVisualOutput) +
      lidar.size() * sizeof(CudaLidarOutput);
  result->visual.resize(visual.size());
  result->lidar.resize(lidar.size());
  status = cudaMemGetInfo(&result->runtime.free_bytes_before,
                          &result->runtime.total_bytes);
  result->runtime.memory_status = static_cast<int>(status);
  if (status != cudaSuccess) {
    result->error = std::string("cudaMemGetInfo failed: ") + CudaErrorText(status);
    return false;
  }
  result->runtime.active_bytes = CudaActiveBytesForDevice(options.device);
  result->runtime.cached_bytes = CudaCachedBytesForDevice(options.device);

  cudaStream_t stream = nullptr;
  cudaEvent_t begin = nullptr;
  cudaEvent_t end = nullptr;
  CudaVisualInput* d_visual = nullptr;
  CudaVisualOutput* d_visual_output = nullptr;
  CudaLidarInput* d_lidar = nullptr;
  CudaLidarOutput* d_lidar_output = nullptr;
  auto cleanup = [&]() {
    ReleaseCudaEvent(begin);
    ReleaseCudaEvent(end);
    ReleaseCudaStream(stream);
    Release(d_visual);
    Release(d_visual_output);
    Release(d_lidar);
    Release(d_lidar_output);
    if (!CudaCleanupSucceeded(&result->error)) {
      result->success = false;
      return false;
    }
    return true;
  };

  status = AcquireCudaStream(&stream);
  if (status != cudaSuccess) {
    result->error = std::string("cudaStreamCreate failed: ") + CudaErrorText(status);
    cleanup();
    return false;
  }
  if (!Allocate(&d_visual, visual.size(), options.memory_mode, &result->error) ||
      !Allocate(&d_visual_output, visual.size(), options.memory_mode,
                &result->error) ||
      !Allocate(&d_lidar, lidar.size(), options.memory_mode, &result->error) ||
      !Allocate(&d_lidar_output, lidar.size(), options.memory_mode,
                &result->error)) {
    cleanup();
    return false;
  }
  result->runtime.active_bytes = CudaActiveBytesForDevice(options.device);
  const auto copy_start = std::chrono::steady_clock::now();
  CudaTransferBatchAudit h2d_batch(
      stream, options.memory_mode == CudaMemoryMode::kExplicitDeviceCopy
                  ? CUDA_TIMING_PHASE(h2d_memcpy)
                  : nullptr);
  if (!h2d_batch.Begin(&result->error)) {
    cleanup();
    return false;
  }
  if (!CopyToDevice(d_visual, visual, options.memory_mode, stream,
                    &result->error) ||
      !CopyToDevice(d_lidar, lidar, options.memory_mode, stream,
                    &result->error) ||
      !PrepareManagedForDevice(d_visual, visual.size(), options.memory_mode,
                               options.device, stream, &result->error) ||
      !PrepareManagedForDevice(d_lidar, lidar.size(), options.memory_mode,
                               options.device, stream, &result->error) ||
      !PrepareManagedForDevice(d_visual_output, visual.size(),
                               options.memory_mode, options.device, stream,
                               &result->error) ||
      !PrepareManagedForDevice(d_lidar_output, lidar.size(),
                               options.memory_mode, options.device, stream,
                               &result->error) ||
      !h2d_batch.End(&result->error)) {
    cleanup();
    return false;
  }
  result->runtime.copy_milliseconds +=
      std::chrono::duration<double, std::milli>(
          std::chrono::steady_clock::now() - copy_start).count();

  status = AcquireCudaEvent(&begin);
  if (status == cudaSuccess) status = AcquireCudaEvent(&end);
  if (status != cudaSuccess) {
    result->error = std::string("cudaEventCreate failed: ") + CudaErrorText(status);
    cleanup();
    return false;
  }
  AuditCudaEventRecord(begin, stream);
  if (!visual.empty()) {
    const int blocks = static_cast<int>(
        (visual.size() + static_cast<size_t>(options.block_size) - 1) /
        static_cast<size_t>(options.block_size));
    LayerAVisualKernel<<<blocks, options.block_size, 0, stream>>>(
        d_visual, d_visual_output, visual.size());
  }
  if (!lidar.empty()) {
    const int blocks = static_cast<int>(
        (lidar.size() + static_cast<size_t>(options.block_size) - 1) /
        static_cast<size_t>(options.block_size));
    LayerALidarKernel<<<blocks, options.block_size, 0, stream>>>(
        d_lidar, d_lidar_output, lidar.size());
  }
  status = cudaGetLastError();
  result->runtime.launch_status = static_cast<int>(status);
  if (status != cudaSuccess) {
    result->error = std::string("Layer A kernel launch failed: ") +
                    CudaErrorText(status);
    cleanup();
    return false;
  }
  AuditCudaEventRecord(end, stream);
  CudaTransferBatchAudit d2h_batch(stream, CUDA_TIMING_PHASE(d2h_memcpy));
  if (!d2h_batch.Begin(&result->error)) {
    cleanup();
    return false;
  }
  if (!CopyFromDevice(d_visual_output, &result->visual, options.memory_mode,
                      stream, &result->error) ||
      !CopyFromDevice(d_lidar_output, &result->lidar, options.memory_mode,
                      stream, &result->error) ||
      !d2h_batch.End(&result->error)) {
    cleanup();
    return false;
  }
  status = TimedCudaStreamSynchronize(stream, CudaSyncSite::kLayerAFinal);
  result->runtime.synchronize_status = static_cast<int>(status);
  if (status != cudaSuccess) {
    result->error = std::string("cudaStreamSynchronize failed: ") +
                    CudaErrorText(status);
    cleanup();
    return false;
  }
  if (!h2d_batch.CompleteAfterExistingSync(&result->error) ||
      !d2h_batch.CompleteAfterExistingSync(&result->error)) {
    cleanup();
    return false;
  }
  float kernel_ms = 0.0f;
  status = AuditCudaEventElapsedTime(&kernel_ms, begin, end);
  if (status != cudaSuccess) {
    result->error = std::string("cudaEventElapsedTime failed: ") +
                    CudaErrorText(status);
    cleanup();
    return false;
  }
  result->runtime.kernel_milliseconds = kernel_ms;
  RecordCudaEvent(CUDA_TIMING_PHASE(layer_a_kernel), kernel_ms);
  result->runtime.host_wall_milliseconds =
      std::chrono::duration<double, std::milli>(
          std::chrono::steady_clock::now() - host_start)
          .count();
  if (!h2d_batch.Close(&result->error) ||
      !d2h_batch.Close(&result->error) || !cleanup()) {
    result->success = false;
    return false;
  }
  result->success = true;
  return true;
}

bool RunCudaSnapshotLayerA(const Snapshot& snapshot,
                           const CudaLayerAOptions& options,
                           CudaLayerAResult* result,
                           std::string* error) {
  CudaCacheCallScope cache_scope;
  if (error == nullptr || result == nullptr) return false;
  error->clear();
  std::vector<CudaVisualInput> visual;
  std::vector<CudaLidarInput> lidar;
  if (!BuildCudaLayerAInputs(snapshot, options.residual_order, &visual,
                             &lidar, error)) {
    return false;
  }
  if (!RunCudaLayerA(visual, lidar, options, result)) {
    *error = result->error;
    return false;
  }
  return true;
}

bool RunCudaCompactLayerAComparisonSelfTest(
    const std::vector<CudaVisualInput>& visual,
    const double atol,
    const double rtol,
    std::string* error) {
  if (error == nullptr || !std::isfinite(atol) || !std::isfinite(rtol) ||
      atol < 0.0 || rtol < 0.0) {
    return false;
  }
  error->clear();
  if (visual.empty()) return true;
  CudaLayerAOptions options;
  CudaLayerAResult full_result;
  if (!RunCudaLayerA(visual, {}, options, &full_result)) {
    *error = full_result.error;
    return false;
  }
  CudaVisualInput* d_input = nullptr;
  CudaCompactVisualOutput* d_output = nullptr;
  std::vector<CudaCompactVisualOutput> compact(visual.size());
  const size_t input_bytes = visual.size() * sizeof(CudaVisualInput);
  const size_t output_bytes = compact.size() * sizeof(CudaCompactVisualOutput);
  const auto cleanup = [&]() {
    if (d_output != nullptr) cudaFree(d_output);
    if (d_input != nullptr) cudaFree(d_input);
  };
  if (cudaMalloc(reinterpret_cast<void**>(&d_input), input_bytes) !=
          cudaSuccess ||
      cudaMalloc(reinterpret_cast<void**>(&d_output), output_bytes) !=
          cudaSuccess ||
      cudaMemcpy(d_input, visual.data(), input_bytes, cudaMemcpyHostToDevice) !=
          cudaSuccess) {
    cleanup();
    *error = "compact Layer A oracle allocation/upload failed";
    return false;
  }
  constexpr int kThreads = 128;
  LayerAVisualCompactOracleKernel<<<
      static_cast<int>((visual.size() + kThreads - 1) / kThreads), kThreads>>>(
      d_input, d_output, visual.size());
  if (cudaGetLastError() != cudaSuccess ||
      cudaMemcpy(compact.data(), d_output, output_bytes,
                 cudaMemcpyDeviceToHost) != cudaSuccess) {
    cleanup();
    *error = "compact Layer A oracle kernel/download failed";
    return false;
  }
  cleanup();
  if (full_result.visual.size() != compact.size()) {
    *error = "compact Layer A oracle output size mismatch";
    return false;
  }
  const auto within = [atol, rtol](const double reference,
                                   const double candidate) {
    return std::isfinite(reference) == std::isfinite(candidate) &&
           (!std::isfinite(reference) ||
            std::abs(reference - candidate) <=
                atol + rtol * std::max(1.0, std::abs(reference)));
  };
  for (size_t index = 0; index < compact.size(); ++index) {
    const CudaVisualOutput& reference = full_result.visual[index];
    const CudaCompactVisualOutput& candidate = compact[index];
    if (((candidate.status & 1u) != 0) != (reference.finite != 0)) {
      *error = "compact Layer A finite/status mismatch";
      return false;
    }
    for (size_t row = 0; row < 2; ++row) {
      if (!within(reference.residual[row], candidate.residual[row])) {
        *error = "compact Layer A residual mismatch";
        return false;
      }
      for (size_t column = 0; column < 3; ++column) {
        if (!within(reference.local_rotation_jacobian[row * 3 + column],
                    candidate.pose_jacobian[row * 6 + column]) ||
            !within(reference.translation_jacobian[row * 3 + column],
                    candidate.pose_jacobian[row * 6 + 3 + column]) ||
            !within(reference.point_jacobian[row * 3 + column],
                    candidate.point_jacobian[row * 3 + column])) {
          *error = "compact Layer A Jacobian mismatch";
          return false;
        }
      }
    }
  }
  return true;
}

bool RunCudaDeviceScalingComparisonSelfTest(
    const Snapshot& snapshot,
    const double atol,
    const double rtol,
    std::string* error) {
  if (error == nullptr || !std::isfinite(atol) || !std::isfinite(rtol) ||
      atol < 0.0 || rtol < 0.0) {
    return false;
  }
  CudaLayerBOptions options;
  CudaLayerBResult bootstrap;
  if (!RunCudaSnapshotLayerB(snapshot, options, &bootstrap, error)) return false;
  CudaPoseBlockOutput* d_poses = nullptr;
  CudaPointBlockOutput* d_points = nullptr;
  double* d_pose_scaling = nullptr;
  double* d_point_scaling = nullptr;
  const size_t pose_bytes = bootstrap.poses.size() * sizeof(CudaPoseBlockOutput);
  const size_t point_bytes = bootstrap.points.size() * sizeof(CudaPointBlockOutput);
  const size_t pose_scaling_bytes = bootstrap.poses.size() * 6 * sizeof(double);
  const size_t point_scaling_bytes = bootstrap.points.size() * 3 * sizeof(double);
  const auto cleanup = [&]() {
    if (d_point_scaling != nullptr) cudaFree(d_point_scaling);
    if (d_pose_scaling != nullptr) cudaFree(d_pose_scaling);
    if (d_points != nullptr) cudaFree(d_points);
    if (d_poses != nullptr) cudaFree(d_poses);
  };
  bool transfer_ok = true;
  if (pose_bytes != 0) {
    transfer_ok = cudaMalloc(reinterpret_cast<void**>(&d_poses), pose_bytes) ==
                      cudaSuccess &&
                  cudaMalloc(reinterpret_cast<void**>(&d_pose_scaling),
                             pose_scaling_bytes) == cudaSuccess &&
                  cudaMemcpy(d_poses, bootstrap.poses.data(), pose_bytes,
                             cudaMemcpyHostToDevice) == cudaSuccess;
  }
  if (transfer_ok && point_bytes != 0) {
    transfer_ok = cudaMalloc(reinterpret_cast<void**>(&d_points), point_bytes) ==
                      cudaSuccess &&
                  cudaMalloc(reinterpret_cast<void**>(&d_point_scaling),
                             point_scaling_bytes) == cudaSuccess &&
                  cudaMemcpy(d_points, bootstrap.points.data(), point_bytes,
                             cudaMemcpyHostToDevice) == cudaSuccess;
  }
  if (!transfer_ok) {
    cleanup();
    *error = "device scaling oracle allocation/upload failed";
    return false;
  }
  constexpr int kThreads = 128;
  if (!bootstrap.poses.empty()) {
    PublishPoseJacobiScalingKernel<<<
        static_cast<int>((bootstrap.poses.size() + kThreads - 1) / kThreads),
        kThreads>>>(d_poses, d_pose_scaling, bootstrap.poses.size());
  }
  if (!bootstrap.points.empty()) {
    PublishPointJacobiScalingKernel<<<
        static_cast<int>((bootstrap.points.size() + kThreads - 1) / kThreads),
        kThreads>>>(d_points, d_point_scaling, bootstrap.points.size());
  }
  std::vector<double> pose_scaling(bootstrap.poses.size() * 6);
  std::vector<double> point_scaling(bootstrap.points.size() * 3);
  if (cudaGetLastError() != cudaSuccess ||
      (pose_scaling_bytes != 0 &&
       cudaMemcpy(pose_scaling.data(), d_pose_scaling, pose_scaling_bytes,
                  cudaMemcpyDeviceToHost) != cudaSuccess) ||
      (point_scaling_bytes != 0 &&
       cudaMemcpy(point_scaling.data(), d_point_scaling, point_scaling_bytes,
                  cudaMemcpyDeviceToHost) != cudaSuccess)) {
    cleanup();
    *error = "device scaling oracle kernel/download failed";
    return false;
  }
  cleanup();
  const auto within = [atol, rtol](const double reference,
                                   const double candidate) {
    return std::isfinite(reference) && std::isfinite(candidate) &&
           std::abs(reference - candidate) <=
               atol + rtol * std::max(1.0, std::abs(reference));
  };
  for (size_t block = 0; block < bootstrap.poses.size(); ++block) {
    for (size_t column = 0; column < 6; ++column) {
      const double expected =
          column < bootstrap.poses[block].dimension
              ? bootstrap.poses[block].jacobi_scaling[column]
              : 0.0;
      if (!within(expected, pose_scaling[block * 6 + column])) {
        *error = "device pose scaling oracle mismatch";
        return false;
      }
    }
  }
  for (size_t block = 0; block < bootstrap.points.size(); ++block) {
    for (size_t column = 0; column < 3; ++column) {
      if (!within(bootstrap.points[block].jacobi_scaling[column],
                  point_scaling[block * 3 + column])) {
        *error = "device point scaling oracle mismatch";
        return false;
      }
    }
  }
  return true;
}

static bool RunCudaLayerBFromContext(GpuBaSolveContext* context,
                                     const Snapshot& snapshot,
                                     const CudaLayerBOptions& options,
                                     const CudaLinearizationIdentity* identity,
                                     const CudaFaultLogicalSite site,
                                     CudaLayerBResult* result,
                                     CudaDeviceLinearizationToken* token,
                                     std::string* error) {
  CudaCacheCallScope cache_scope;
  if (context == nullptr || result == nullptr || error == nullptr) return false;
  *result = CudaLayerBResult();
  if (!CudaStandaloneEntryAllowed(error)) {
    result->error = *error;
    return false;
  }
  TimingLedgerScope timing_scope(&result->runtime.timing);
  InclusiveCallScope inclusive_call(CUDA_TIMING_PHASE(layer_b_call));
  if (g_cuda_solve_call_counters != nullptr)
    ++g_cuda_solve_call_counters->layer_b;
  if (g_cuda_timing_sink != nullptr) ++g_cuda_timing_sink->layer_b_calls;
  error->clear();
  const auto host_start = std::chrono::steady_clock::now();
  if (!std::isfinite(options.min_lm_diagonal) ||
      !std::isfinite(options.max_lm_diagonal) ||
      options.min_lm_diagonal <= 0.0 ||
      options.max_lm_diagonal < options.min_lm_diagonal) {
    *error = "Invalid Layer B LM diagonal limits";
    result->error = *error;
    return false;
  }
  if (!context->ValidateLayerBOptions(snapshot, options, error)) {
    result->error = *error;
    return false;
  }
  const CudaLossMode loss_mode = context->loss_mode();
  const double loss_scale = context->loss_scale();
  const LayerBTopology& topology = context->BorrowLayerBTopology();
  context->RecordDynamicRefresh();
  if (context->device_state_enabled()) {
    if (identity == nullptr || token == nullptr ||
        !context->ValidateDeviceStateHostMirror(snapshot, error)) {
      if (error->empty())
        *error = "device-state Layer B requires an explicit identity";
      result->error = *error;
      return false;
    }
    const bool success = context->persistent_device()->RunLayerBFromDeviceState(
        snapshot, options, *identity, site, loss_mode, loss_scale, result,
        token, error);
    result->runtime.host_wall_milliseconds =
        std::chrono::duration<double, std::milli>(
            std::chrono::steady_clock::now() - host_start).count();
    return success;
  }
  const PackedLayerAState* packed = nullptr;
  if (!context->AcquirePackedState(snapshot, true, &packed, error)) {
    result->error = *error;
    return false;
  }
  const std::vector<CudaVisualInput>& visual_input = packed->visual;
  const std::vector<CudaLidarInput>& lidar_input = packed->lidar;
  const std::vector<DevicePoseState>& pose_state = packed->pose_state;
  if (context->persistent_device_enabled()) {
    if (identity == nullptr) {
      *error = "persistent Layer B requires an explicit identity";
      result->error = *error;
      return false;
    }
    const bool success = context->persistent_device()->RunLayerB(
        *packed, options, *identity, site, loss_mode, loss_scale, result,
        token, error);
    result->runtime.host_wall_milliseconds =
        std::chrono::duration<double, std::milli>(
            std::chrono::steady_clock::now() - host_start).count();
    return success;
  }
  CudaLayerAResult layer_a;
  if (!RunCudaLayerA(visual_input, lidar_input, options.layer_a, &layer_a)) {
    *error = layer_a.error;
    result->error = *error;
    return false;
  }
  if (pose_state.size() != topology.poses.size()) {
    *error = "GpuBaSolveContext dynamic pose layout is inconsistent";
    result->error = *error;
    return false;
  }
  const bool frozen_scaling =
      !options.frozen_pose_jacobi_scaling.empty() ||
      !options.frozen_point_jacobi_scaling.empty();
  if (frozen_scaling &&
      (options.frozen_pose_jacobi_scaling.size() !=
           topology.poses.size() * 6 ||
       options.frozen_point_jacobi_scaling.size() !=
           topology.points.size() * 3)) {
    *error = "custom_cuda frozen Jacobi scaling dimensions differ from "
             "the current variable layout";
    result->error = *error;
    return false;
  }

  result->poses.resize(topology.poses.size());
  result->points.resize(topology.points.size());
  result->edges.resize(topology.edges.size());
  result->runtime.metadata_bytes =
      topology.poses.size() * sizeof(DevicePoseMeta) +
      pose_state.size() * sizeof(DevicePoseState) +
      topology.points.size() * sizeof(DevicePointMeta) +
      topology.edges.size() * sizeof(DeviceEdgeMeta) +
      layer_a.visual.size() * sizeof(CudaVisualOutput) +
      layer_a.lidar.size() * sizeof(CudaLidarOutput);
  result->runtime.adjacency_bytes =
      topology.pose_adjacency.size() * sizeof(uint32_t) +
      topology.point_adjacency.size() * sizeof(DevicePointAdjacency) +
      topology.edge_adjacency.size() * sizeof(uint32_t);
  if (frozen_scaling) {
    result->runtime.metadata_bytes +=
        options.frozen_pose_jacobi_scaling.size() * sizeof(double) +
        options.frozen_point_jacobi_scaling.size() * sizeof(double);
  }
  result->runtime.output_bytes =
      result->poses.size() * sizeof(CudaPoseBlockOutput) +
      result->points.size() * sizeof(CudaPointBlockOutput) +
      result->edges.size() * sizeof(CudaEdgeBlockOutput) + 3 * sizeof(double);
  const bool parallel_reduction =
      options.reduction_mode == CudaReductionMode::kParallelDeterministic;
  const size_t gradient_slots = topology.poses.size() + topology.points.size();
  if (parallel_reduction)
    result->runtime.output_bytes += gradient_slots * 3 * sizeof(double);
  result->runtime.cost_reduction_parallel = parallel_reduction;
  result->runtime.gradient_reduction_parallel = parallel_reduction;
  result->runtime.reduction_mode = options.reduction_mode;
  result->runtime.configured_worker_count =
      std::max(1, options.cost_reduction_threads);
  result->runtime.effective_worker_count =
      parallel_reduction
          ? std::min(1024, result->runtime.configured_worker_count)
          : 1;
  uint64_t predicted_bytes = result->runtime.metadata_bytes +
                             result->runtime.adjacency_bytes +
                             result->runtime.output_bytes;
  size_t free_bytes = 0;
  size_t total_bytes = 0;
  cudaError_t status = cudaSetDevice(options.layer_a.device);
  if (status == cudaSuccess) status = cudaMemGetInfo(&free_bytes, &total_bytes);
  if (options.memory_budget_override_bytes != 0) {
    free_bytes = std::min<uint64_t>(
        free_bytes, options.memory_budget_override_bytes);
  }
  result->runtime.active_bytes = CudaActiveBytesForDevice(options.layer_a.device);
  result->runtime.cached_bytes = CudaCachedBytesForDevice(options.layer_a.device);
  result->runtime.resident_bytes =
      result->runtime.active_bytes + result->runtime.cached_bytes;
  result->runtime.predicted_additional_bytes = predicted_bytes;
  result->runtime.predicted_peak_bytes = ResidentPeakBytes(
      result->runtime.active_bytes, result->runtime.cached_bytes,
      predicted_bytes);
  result->runtime.free_bytes_before = free_bytes;
  result->runtime.total_bytes = total_bytes;
  const uint64_t reserve =
      std::max<uint64_t>(512ull * 1024ull * 1024ull, predicted_bytes / 4);
  if (options.fault_injection ==
          CudaFaultInjection::kForceInsufficientMemory ||
      status != cudaSuccess ||
      !HasCudaMemoryHeadroom(free_bytes, predicted_bytes, reserve)) {
    std::ostringstream message;
    message << "INSUFFICIENT_GPU_MEMORY additional=" << predicted_bytes
            << " resident_before=" << result->runtime.resident_bytes
            << " predicted_peak=" << result->runtime.predicted_peak_bytes
            << " reserve=" << reserve << " free=" << free_bytes;
    *error = message.str();
    result->error = *error;
    return false;
  }

  cudaStream_t stream = nullptr;
  cudaEvent_t begin = nullptr;
  cudaEvent_t end = nullptr;
  cudaEvent_t gradient_begin = nullptr;
  cudaEvent_t gradient_end = nullptr;
  cudaEvent_t pose_begin = nullptr;
  cudaEvent_t pose_end = nullptr;
  cudaEvent_t point_begin = nullptr;
  cudaEvent_t point_end = nullptr;
  cudaEvent_t edge_begin = nullptr;
  cudaEvent_t edge_end = nullptr;
  DevicePoseMeta* d_pose_meta = nullptr;
  DevicePoseState* d_pose_state = nullptr;
  DevicePointMeta* d_point_meta = nullptr;
  DeviceEdgeMeta* d_edge_meta = nullptr;
  uint32_t* d_pose_adjacency = nullptr;
  DevicePointAdjacency* d_point_adjacency = nullptr;
  uint32_t* d_edge_adjacency = nullptr;
  CudaVisualOutput* d_visual = nullptr;
  CudaLidarOutput* d_lidar = nullptr;
  CudaPoseBlockOutput* d_poses = nullptr;
  CudaPointBlockOutput* d_points = nullptr;
  CudaEdgeBlockOutput* d_edges = nullptr;
  double* d_gradient_norms = nullptr;
  double* d_gradient_partials = nullptr;
  double* d_frozen_pose_scaling = nullptr;
  double* d_frozen_point_scaling = nullptr;
  auto cleanup = [&]() {
    ReleaseCudaEvent(begin);
    ReleaseCudaEvent(end);
    ReleaseCudaEvent(gradient_begin);
    ReleaseCudaEvent(gradient_end);
    ReleaseCudaEvent(pose_begin);
    ReleaseCudaEvent(pose_end);
    ReleaseCudaEvent(point_begin);
    ReleaseCudaEvent(point_end);
    ReleaseCudaEvent(edge_begin);
    ReleaseCudaEvent(edge_end);
    ReleaseCudaStream(stream);
    Release(d_pose_meta);
    Release(d_pose_state);
    Release(d_point_meta);
    Release(d_edge_meta);
    Release(d_pose_adjacency);
    Release(d_point_adjacency);
    Release(d_edge_adjacency);
    Release(d_visual);
    Release(d_lidar);
    Release(d_poses);
    Release(d_points);
    Release(d_edges);
    Release(d_gradient_norms);
    Release(d_gradient_partials);
    Release(d_frozen_pose_scaling);
    Release(d_frozen_point_scaling);
    if (!CudaCleanupSucceeded(error)) {
      result->error = *error;
      result->success = false;
      return false;
    }
    return true;
  };
  const CudaMemoryMode memory_mode = options.layer_a.memory_mode;
  const auto allocation_start = std::chrono::steady_clock::now();
  status = AcquireCudaStream(&stream);
  if (status != cudaSuccess) {
    *error = std::string("Layer B cudaStreamCreate failed: ") +
             CudaErrorText(status);
    result->error = *error;
    cleanup();
    return false;
  }
  auto allocate_checked = [&](auto pointer, const size_t count,
                              const char* name) {
    if (Allocate(pointer, count, memory_mode, error)) return true;
    if (error->empty()) *error = std::string("allocation failed: ") + name;
    return false;
  };
  const bool allocation_ok =
      allocate_checked(&d_pose_meta, topology.poses.size(), "pose_meta") &&
      allocate_checked(&d_pose_state, pose_state.size(), "pose_state") &&
      allocate_checked(&d_point_meta, topology.points.size(), "point_meta") &&
      allocate_checked(&d_edge_meta, topology.edges.size(), "edge_meta") &&
      allocate_checked(&d_pose_adjacency, topology.pose_adjacency.size(),
                       "pose_adjacency") &&
      allocate_checked(&d_point_adjacency, topology.point_adjacency.size(),
                       "point_adjacency") &&
      allocate_checked(&d_edge_adjacency, topology.edge_adjacency.size(),
                       "edge_adjacency") &&
      allocate_checked(&d_visual, layer_a.visual.size(), "visual") &&
      allocate_checked(&d_lidar, layer_a.lidar.size(), "lidar") &&
      allocate_checked(&d_poses, topology.poses.size(), "poses") &&
      allocate_checked(&d_points, topology.points.size(), "points") &&
      allocate_checked(&d_edges, topology.edges.size(), "edges") &&
      allocate_checked(&d_gradient_norms, 3, "gradient_norms") &&
      (!parallel_reduction ||
       allocate_checked(&d_gradient_partials, gradient_slots * 3,
                        "gradient_partials")) &&
      (!frozen_scaling ||
       (allocate_checked(&d_frozen_pose_scaling,
                         options.frozen_pose_jacobi_scaling.size(),
                         "frozen_pose_scaling") &&
        allocate_checked(&d_frozen_point_scaling,
                         options.frozen_point_jacobi_scaling.size(),
                         "frozen_point_scaling")));
  if (!allocation_ok) {
    result->error = *error;
    cleanup();
    return false;
  }
  result->runtime.active_bytes =
      CudaActiveBytesForDevice(options.layer_a.device);
  result->runtime.cached_bytes =
      CudaCachedBytesForDevice(options.layer_a.device);
  result->runtime.resident_bytes =
      result->runtime.active_bytes + result->runtime.cached_bytes;
  result->runtime.allocation_milliseconds =
      std::chrono::duration<double, std::milli>(
          std::chrono::steady_clock::now() - allocation_start)
          .count();
  const auto copy_start = std::chrono::steady_clock::now();
  CudaTransferBatchAudit h2d_batch(
      stream, memory_mode == CudaMemoryMode::kExplicitDeviceCopy
                  ? CUDA_TIMING_PHASE(h2d_memcpy)
                  : nullptr);
  if (!h2d_batch.Begin(error)) {
    result->error = *error;
    cleanup();
    return false;
  }
  if (!CopyToDevice(d_pose_meta, topology.poses, memory_mode, stream, error) ||
      !CopyToDevice(d_pose_state, pose_state, memory_mode, stream, error) ||
      !CopyToDevice(d_point_meta, topology.points, memory_mode, stream, error) ||
      !CopyToDevice(d_edge_meta, topology.edges, memory_mode, stream, error) ||
      !CopyToDevice(d_pose_adjacency, topology.pose_adjacency, memory_mode,
                    stream, error) ||
      !CopyToDevice(d_point_adjacency, topology.point_adjacency, memory_mode,
                    stream, error) ||
      !CopyToDevice(d_edge_adjacency, topology.edge_adjacency, memory_mode,
                    stream, error) ||
      !CopyToDevice(d_visual, layer_a.visual, memory_mode, stream, error) ||
      !CopyToDevice(d_lidar, layer_a.lidar, memory_mode, stream, error) ||
      (frozen_scaling &&
       (!CopyToDevice(d_frozen_pose_scaling,
                      options.frozen_pose_jacobi_scaling, memory_mode, stream,
                      error) ||
        !CopyToDevice(d_frozen_point_scaling,
                      options.frozen_point_jacobi_scaling, memory_mode,
                      stream, error))) ||
      !h2d_batch.End(error)) {
    result->error = *error;
    cleanup();
    return false;
  }
  result->runtime.copy_milliseconds +=
      std::chrono::duration<double, std::milli>(
          std::chrono::steady_clock::now() - copy_start).count();

  status = AcquireCudaEvent(&begin);
  if (status == cudaSuccess) status = AcquireCudaEvent(&end);
  if (status == cudaSuccess) status = AcquireCudaEvent(&gradient_begin);
  if (status == cudaSuccess) status = AcquireCudaEvent(&gradient_end);
  if (status == cudaSuccess) status = AcquireCudaEvent(&pose_begin);
  if (status == cudaSuccess) status = AcquireCudaEvent(&pose_end);
  if (status == cudaSuccess) status = AcquireCudaEvent(&point_begin);
  if (status == cudaSuccess) status = AcquireCudaEvent(&point_end);
  if (status == cudaSuccess) status = AcquireCudaEvent(&edge_begin);
  if (status == cudaSuccess) status = AcquireCudaEvent(&edge_end);
  if (status != cudaSuccess) {
    *error = std::string("Layer B cudaEventCreate failed: ") +
             CudaErrorText(status);
    result->error = *error;
    cleanup();
    return false;
  }
  AuditCudaEventRecord(begin, stream);
  AuditCudaEventRecord(pose_begin, stream);
  const int block_size = options.layer_a.block_size;
  auto blocks_for = [block_size](const size_t count) {
    return static_cast<int>((count + static_cast<size_t>(block_size) - 1) /
                            static_cast<size_t>(block_size));
  };
  if (!topology.poses.empty()) {
    LayerBPoseKernel<<<blocks_for(topology.poses.size()), block_size, 0,
                       stream>>>(d_pose_meta, d_pose_adjacency, d_visual,
                                 false,
                                 static_cast<uint8_t>(loss_mode), loss_scale,
                                 d_frozen_pose_scaling,
                                 options.min_lm_diagonal,
                                 options.max_lm_diagonal, d_poses,
                                 topology.poses.size());
  }
  AuditCudaEventRecord(pose_end, stream);
  AuditCudaEventRecord(point_begin, stream);
  if (!topology.points.empty()) {
    LayerBPointKernel<<<blocks_for(topology.points.size()), block_size, 0,
                        stream>>>(d_point_meta, nullptr, d_point_adjacency, d_visual,
                                  false, d_lidar,
                                  static_cast<uint8_t>(loss_mode),
                                  loss_scale, d_frozen_point_scaling,
                                  options.min_lm_diagonal,
                                  options.max_lm_diagonal, d_points,
                                  topology.points.size());
  }
  AuditCudaEventRecord(point_end, stream);
  AuditCudaEventRecord(edge_begin, stream);
  if (!topology.edges.empty()) {
    LayerBEdgeKernel<<<blocks_for(topology.edges.size()), block_size, 0,
                       stream>>>(d_edge_meta, d_edge_adjacency, d_pose_meta,
                                 d_visual, false,
                                 static_cast<uint8_t>(loss_mode),
                                 loss_scale, d_edges, topology.edges.size());
  }
  AuditCudaEventRecord(edge_end, stream);
  AuditCudaEventRecord(gradient_begin, stream);
  if (parallel_reduction && gradient_slots != 0) {
    const int gradient_blocks = static_cast<int>(
        (gradient_slots + static_cast<size_t>(block_size) - 1) /
        static_cast<size_t>(block_size));
    LayerBGradientNormPartialKernel<<<gradient_blocks, block_size, 0, stream>>>(
        d_pose_meta, d_pose_state, d_poses, topology.poses.size(), d_points,
        topology.points.size(), d_gradient_partials);
    LayerBGradientNormReduceKernel<<<1, 1, 0, stream>>>(
        d_gradient_partials, gradient_slots, d_gradient_norms);
  } else {
    LayerBGradientNormKernel<<<1, 1, 0, stream>>>(
        d_pose_meta, d_pose_state, d_poses, topology.poses.size(), d_points,
        topology.points.size(), d_gradient_norms);
  }
  AuditCudaEventRecord(gradient_end, stream);
  status = cudaGetLastError();
  result->runtime.launch_status = static_cast<int>(status);
  if (status != cudaSuccess) {
    *error = std::string("Layer B kernel launch failed: ") +
             CudaErrorText(status);
    result->error = *error;
    cleanup();
    return false;
  }
  AuditCudaEventRecord(end, stream);
  std::vector<double> gradient_norms(3, 0.0);
  CudaTransferBatchAudit d2h_batch(stream, CUDA_TIMING_PHASE(d2h_memcpy));
  if (!d2h_batch.Begin(error)) {
    result->error = *error;
    cleanup();
    return false;
  }
  if (!CopyFromDevice(d_poses, &result->poses, memory_mode, stream, error) ||
      !CopyFromDevice(d_points, &result->points, memory_mode, stream, error) ||
      !CopyFromDevice(d_edges, &result->edges, memory_mode, stream, error) ||
      !CopyFromDevice(d_gradient_norms, &gradient_norms, memory_mode, stream,
                      error) ||
      !d2h_batch.End(error)) {
    result->error = *error;
    cleanup();
    return false;
  }
  const auto synchronization_start = std::chrono::steady_clock::now();
  status = TimedCudaStreamSynchronize(stream, CudaSyncSite::kLayerBFinal);
  result->runtime.synchronization_milliseconds +=
      std::chrono::duration<double, std::milli>(
          std::chrono::steady_clock::now() - synchronization_start)
          .count();
  result->runtime.synchronize_status = static_cast<int>(status);
  if (status != cudaSuccess) {
    *error = std::string("Layer B cudaStreamSynchronize failed: ") +
             CudaErrorText(status);
    result->error = *error;
    cleanup();
    return false;
  }
  if (!h2d_batch.CompleteAfterExistingSync(error) ||
      !d2h_batch.CompleteAfterExistingSync(error)) {
    result->error = *error;
    cleanup();
    return false;
  }
  float kernel_ms = 0.0f;
  status = AuditCudaEventElapsedTime(&kernel_ms, begin, end);
  if (status != cudaSuccess) {
    *error = std::string("Layer B cudaEventElapsedTime failed: ") +
             CudaErrorText(status);
    result->error = *error;
    cleanup();
    return false;
  }
  result->projected_gradient_max_norm = gradient_norms[0];
  result->raw_tangent_gradient_max_norm = gradient_norms[1];
  result->scaled_gradient_max_norm = gradient_norms[2];
  result->runtime.assembly_kernel_milliseconds = kernel_ms;
  float pose_kernel_ms = 0.0f;
  float point_kernel_ms = 0.0f;
  float edge_kernel_ms = 0.0f;
  if (AuditCudaEventElapsedTime(&pose_kernel_ms, pose_begin, pose_end) ==
      cudaSuccess) {
    RecordCudaEvent(CUDA_TIMING_PHASE(layer_b_pose_kernel), pose_kernel_ms);
  }
  if (AuditCudaEventElapsedTime(&point_kernel_ms, point_begin, point_end) ==
      cudaSuccess) {
    RecordCudaEvent(CUDA_TIMING_PHASE(layer_b_point_kernel), point_kernel_ms);
  }
  if (AuditCudaEventElapsedTime(&edge_kernel_ms, edge_begin, edge_end) ==
      cudaSuccess) {
    RecordCudaEvent(CUDA_TIMING_PHASE(layer_b_edge_kernel), edge_kernel_ms);
  }
  float gradient_kernel_ms = 0.0f;
  status = AuditCudaEventElapsedTime(&gradient_kernel_ms, gradient_begin,
                                     gradient_end);
  if (status == cudaSuccess)
    result->runtime.gradient_kernel_milliseconds = gradient_kernel_ms;
  RecordCudaEvent(CUDA_TIMING_PHASE(layer_b_gradient_kernel),
                  gradient_kernel_ms);
  result->runtime.host_wall_milliseconds =
      std::chrono::duration<double, std::milli>(
          std::chrono::steady_clock::now() - host_start)
          .count();
  result->layer_a = std::move(layer_a);
  double cost_kernel_milliseconds = 0.0;
  const LayerAOutputView layer_a_view =
      context->MakeLayerAView(result->layer_a);
  if (!context->ValidateLayerAView(layer_a_view, error) ||
      !ComputeCudaCost(context->cost_layout(), layer_a_view, loss_mode,
                       loss_scale, options, &result->cost,
                       &cost_kernel_milliseconds, error)) {
    result->error = *error;
    cleanup();
    return false;
  }
  result->runtime.cost_kernel_milliseconds = cost_kernel_milliseconds;
  if (!h2d_batch.Close(error) || !d2h_batch.Close(error) || !cleanup()) {
    result->error = *error;
    result->success = false;
    return false;
  }
  result->success = true;
  return true;
}

static bool RunCudaNativeLayerBFromContext(
    GpuBaSolveContext* context,
    const CudaLayerBOptions& options,
    const CudaLinearizationIdentity& identity,
    const CudaFaultLogicalSite site,
    CudaLayerBResult* result,
    CudaDeviceLinearizationToken* token,
    std::string* error) {
  if (context == nullptr || result == nullptr || token == nullptr ||
      error == nullptr) {
    return false;
  }
  *result = CudaLayerBResult();
  InclusiveCallScope inclusive_call(CUDA_TIMING_PHASE(layer_b_call));
  if (g_cuda_solve_call_counters != nullptr)
    ++g_cuda_solve_call_counters->layer_b;
  if (g_cuda_timing_sink != nullptr) ++g_cuda_timing_sink->layer_b_calls;
  if (!std::isfinite(options.min_lm_diagonal) ||
      !std::isfinite(options.max_lm_diagonal) ||
      options.min_lm_diagonal <= 0.0 ||
      options.max_lm_diagonal < options.min_lm_diagonal ||
      !context->ValidateNativeLayerBOptions(options, error)) {
    if (error->empty()) *error = "native Layer B options are invalid";
    result->error = *error;
    return false;
  }
  context->RecordDynamicRefresh();
  if (!context->persistent_device()->RunLayerBFromNativeDeviceState(
          options, identity, site, context->loss_mode(), context->loss_scale(),
          result, token, error)) {
    result->error = *error;
    return false;
  }
  return result->success;
}

bool RunCudaSnapshotLayerB(const Snapshot& snapshot,
                           const CudaLayerBOptions& options,
                           CudaLayerBResult* result,
                           std::string* error) {
  if (result == nullptr || error == nullptr) return false;
  if (!CudaStandaloneEntryAllowed(error)) {
    result->error = *error;
    return false;
  }
  GpuBaSolveContext context;
  if (!context.Initialize(snapshot, options, 0, 1, false,
                          CudaDeviceContextBackend::kLegacy,
                          HotKernelImplementation::kReference,
                          CudaSchurContributionBackend::kDirectTransformed, 0,
                          CudaExecutionProfile::kBaseline, false, nullptr,
                          error)) {
    if (result != nullptr && error != nullptr) result->error = *error;
    return false;
  }
  return RunCudaLayerBFromContext(
      &context, snapshot, options, nullptr,
      CudaFaultLogicalSite::kInitialLinearization, result, nullptr, error);
}

static bool RunCudaLayerCFromContext(GpuBaSolveContext* context,
                                    const Snapshot& snapshot,
                                    const CudaLayerCOptions& options,
                                    const CudaLayerBResult& layer_b,
                                    const CudaLinearizationIdentity* identity,
                                    const CudaDeviceLinearizationToken* token,
                                    CudaLayerCStepResult* result,
                                    std::string* error) {
  CudaCacheCallScope cache_scope;
  if (context == nullptr || result == nullptr || error == nullptr) return false;
  *result = CudaLayerCStepResult();
  if (!CudaStandaloneEntryAllowed(error)) {
    result->error = *error;
    return false;
  }
  TimingLedgerScope timing_scope(&result->runtime.timing);
  InclusiveCallScope inclusive_call(CUDA_TIMING_PHASE(layer_c_call));
  if (g_cuda_solve_call_counters != nullptr)
    ++g_cuda_solve_call_counters->layer_c;
  if (g_cuda_timing_sink != nullptr) ++g_cuda_timing_sink->layer_c_calls;
  error->clear();
  const auto host_start = std::chrono::steady_clock::now();
  if (!std::isfinite(options.lambda) || options.lambda < 0.0) {
    *error = "Invalid Layer C lambda";
    result->error = *error;
    return false;
  }
  if (options.fault_injection ==
      CudaFaultInjection::kForcePointFactorizationFailure) {
    result->runtime.point_factorization_failures = 1;
    result->runtime.first_point_factorization_failure = 0;
    *error = "Layer C point block Cholesky failed (fault injection)";
    result->error = *error;
    return false;
  }
  const LayerBTopology& layer_b_topology = context->BorrowLayerBTopology();
  const LayerCTopology& topology = context->BorrowLayerCTopology();
  if (!layer_b.compact_device_summary &&
      (layer_b.poses.size() != topology.poses.size() ||
       layer_b.points.size() != topology.points.size() ||
       layer_b.edges.size() != layer_b_topology.edges.size())) {
    *error = "Layer B output and Layer C topology counts differ";
    result->error = *error;
    return false;
  }
  result->pose_dimension = topology.pose_dimension;
  result->point_dimension = topology.points.size() * 3;
  if (topology.pose_dimension == 0) {
    *error = "Layer C v1 requires at least one variable pose";
    result->error = *error;
    return false;
  }

  if (context->persistent_device_enabled()) {
    if (identity == nullptr || token == nullptr || !token->valid) {
      *error = "persistent Layer C requires an explicit identity";
      result->error = *error;
      return false;
    }
    if (!context->persistent_device()->RunLayerCLinearSolve(
            layer_b_topology, topology, options, *identity, *token, layer_b,
            result, error)) {
      result->error = *error;
      return false;
    }
    const bool compact_device_control =
        context->device_control_enabled() && !context->audit_mirror_enabled();
    if (!compact_device_control) {
      HostPhaseScope host_back_substitution(
          CUDA_TIMING_PHASE(back_substitution_host_self));
      result->symmetry_error = 0.0;
      for (size_t row = 0; row < topology.pose_dimension; ++row) {
        for (size_t col = 0; col < topology.pose_dimension; ++col) {
          result->symmetry_error = std::max(
              result->symmetry_error,
              std::abs(result->schur[row * topology.pose_dimension + col] -
                       result->schur[col * topology.pose_dimension + row]));
        }
      }
      if (!ComputeLayerCDiagnostics(
              layer_b, topology, options.lambda, result->camera_delta,
              result->point_delta, &result->backward_error,
              &result->predicted_reduction, error)) {
        result->error = *error;
        return false;
      }
    }
    if (context->device_state_enabled()) {
      CudaLinearizationIdentity trial_identity = *identity;
      ++trial_identity.state_epoch;
      if (!context->persistent_device()->BuildDeviceTrialState(
              snapshot, *identity, options.layer_b.layer_a.block_size,
              !compact_device_control,
              &result->trial_state, error) ||
          !context->persistent_device()->RunDeviceTrialCost(
              options.layer_b, trial_identity, context->loss_mode(),
              context->loss_scale(), &result->trial_cost,
              &result->runtime.trial_cost_kernel_milliseconds, error)) {
        context->DiscardDeviceTrialState();
        result->error = *error;
        return false;
      }
      if (compact_device_control &&
          !context->persistent_device()->RunDeviceDiagnostics(
              *identity, *token, options.lambda, result, error)) {
        context->DiscardDeviceTrialState();
        result->error = *error;
        return false;
      }
    } else {
      if (!ApplyLayerCStep(snapshot, layer_b, topology, result->camera_delta,
                           result->point_delta, &result->trial_state, error)) {
        result->error = *error;
        return false;
      }
      const PackedLayerAState* trial_packed = nullptr;
      if (!context->AcquirePackedState(result->trial_state, false,
                                       &trial_packed, error) ||
          !context->persistent_device()->RunTrialCost(
              *trial_packed, options.layer_b, *identity, context->loss_mode(),
              context->loss_scale(), &result->trial_cost,
              &result->runtime.trial_cost_kernel_milliseconds, error)) {
        result->error = *error;
        return false;
      }
    }
    context->persistent_device()->RecordDiagnosticSymmetry(
        result->symmetry_error);
    result->runtime.host_wall_milliseconds =
        std::chrono::duration<double, std::milli>(
            std::chrono::steady_clock::now() - host_start).count();
    result->success = true;
    return true;
  }

  HotKernelImplementation standalone_hot_kernel =
      HotKernelImplementation::kReference;
  const bool public_standalone_call = identity == nullptr && token == nullptr;
  if (!ResolveHotKernelImplementation(
          CudaHotKernelMode::kCompatibilityDefault, false,
          public_standalone_call,
                                      &standalone_hot_kernel, error)) {
    result->error = *error;
    return false;
  }
  CudaSchurContributionBackend schur_contribution_backend =
      CudaSchurContributionBackend::kDirectTransformed;
  std::string schur_contribution_requested;
  if (!ResolveSchurContributionBackend(
          options.schur_contribution_backend,
          &schur_contribution_backend, &schur_contribution_requested,
          error)) {
    result->error = *error;
    return false;
  }
  const bool standalone_transformed =
      standalone_hot_kernel == HotKernelImplementation::kTransformed ||
      schur_contribution_backend ==
          CudaSchurContributionBackend::kSegmentedTransformed;
  if (standalone_transformed &&
      layer_b.edges.size() >
          std::numeric_limits<size_t>::max() / kTransformedEdgeStride) {
    *error = "INSUFFICIENT_GPU_MEMORY: transformed edge workspace size overflow";
    result->error = *error;
    return false;
  }
  const uint64_t transformed_workspace_bytes =
      standalone_transformed
          ? static_cast<uint64_t>(layer_b.edges.size()) *
                kTransformedEdgeStride * sizeof(double)
          : 0;
  const CudaMemoryMode memory_mode = options.layer_b.layer_a.memory_mode;
  const int device = options.layer_b.layer_a.device;
  const int block_size = options.layer_b.layer_a.block_size;
  cudaError_t cuda_status = cudaSetDevice(device);
  if (cuda_status != cudaSuccess ||
      (cuda_status = cudaMemGetInfo(&result->runtime.free_bytes_before,
                                    &result->runtime.total_bytes)) !=
          cudaSuccess) {
    *error = std::string("Layer C CUDA device/memory query failed: ") +
             CudaErrorText(cuda_status);
    result->error = *error;
    return false;
  }
  if (options.layer_b.memory_budget_override_bytes != 0) {
    result->runtime.free_bytes_before = std::min<uint64_t>(
        result->runtime.free_bytes_before,
        options.layer_b.memory_budget_override_bytes);
  }
  result->runtime.active_bytes = CudaActiveBytesForDevice(device);
  result->runtime.cached_bytes = CudaCachedBytesForDevice(device);
  result->runtime.resident_bytes =
      result->runtime.active_bytes + result->runtime.cached_bytes;
  result->runtime.pair_adjacency_bytes =
      topology.pair_contributions.size() * sizeof(DevicePairContribution);
  const uint64_t matrix_bytes =
      static_cast<uint64_t>(topology.pose_dimension) *
      topology.pose_dimension * sizeof(double);
  result->runtime.predicted_peak_bytes =
      layer_b.poses.size() * sizeof(CudaPoseBlockOutput) +
      layer_b.points.size() * sizeof(CudaPointBlockOutput) +
      layer_b.edges.size() * sizeof(CudaEdgeBlockOutput) +
      topology.poses.size() * sizeof(DeviceSolvePoseMeta) +
      topology.points.size() * sizeof(DeviceSolvePointMeta) +
      topology.pairs.size() * sizeof(DevicePairMeta) +
      topology.pose_edges.size() * sizeof(uint32_t) +
      topology.point_edges.size() * sizeof(uint32_t) +
      result->runtime.pair_adjacency_bytes +
      layer_b.points.size() * (9 + 3) * sizeof(double) +
      layer_b.points.size() * sizeof(uint8_t) +
      2 * matrix_bytes +
      (2 * topology.pose_dimension + layer_b.points.size() * 3) *
          sizeof(double) +
      transformed_workspace_bytes +
      topology.segment_direct_pair_indices.size() * sizeof(uint32_t) +
      topology.segments.size() * sizeof(DeviceSchurSegment) +
      topology.segment_pair_ranges.size() *
          sizeof(DeviceSchurPairSegmentRange) +
      topology.segment_partial_workspace_bytes;
  result->runtime.predicted_additional_bytes =
      result->runtime.predicted_peak_bytes;
  result->runtime.predicted_peak_bytes = ResidentPeakBytes(
      result->runtime.active_bytes, result->runtime.cached_bytes,
      result->runtime.predicted_additional_bytes);
  const uint64_t reserve = std::max<uint64_t>(
      512ull * 1024ull * 1024ull,
      result->runtime.predicted_additional_bytes / 4);
  if (options.layer_b.fault_injection ==
          CudaFaultInjection::kForceInsufficientMemory ||
      !HasCudaMemoryHeadroom(result->runtime.free_bytes_before,
                             result->runtime.predicted_additional_bytes,
                             reserve)) {
    *error = "INSUFFICIENT_GPU_MEMORY before Layer C allocation: additional=" +
             std::to_string(result->runtime.predicted_additional_bytes) +
             " resident_before=" +
             std::to_string(result->runtime.resident_bytes) +
             " predicted_peak=" +
             std::to_string(result->runtime.predicted_peak_bytes);
    result->error = *error;
    return false;
  }

  cudaStream_t stream = nullptr;
  cudaEvent_t events[7] = {nullptr, nullptr, nullptr, nullptr,
                           nullptr, nullptr, nullptr};
  cusolverDnHandle_t solver = nullptr;
  cublasHandle_t blas = nullptr;
  DeviceSolvePoseMeta* d_pose_meta = nullptr;
  DeviceSolvePointMeta* d_point_meta = nullptr;
  DevicePairMeta* d_pair_meta = nullptr;
  DevicePairContribution* d_pair_contributions = nullptr;
  uint32_t* d_segment_direct_pair_indices = nullptr;
  DeviceSchurSegment* d_schur_segments = nullptr;
  DeviceSchurPairSegmentRange* d_schur_pair_segment_ranges = nullptr;
  uint32_t* d_pose_edges = nullptr;
  uint32_t* d_point_edges = nullptr;
  CudaPoseBlockOutput* d_poses = nullptr;
  CudaPointBlockOutput* d_points = nullptr;
  CudaEdgeBlockOutput* d_edges = nullptr;
  double* d_point_inverse = nullptr;
  double* d_transformed_edges = nullptr;
  double* d_schur_segment_partials = nullptr;
  double* d_inverse_gradient = nullptr;
  uint8_t* d_point_status = nullptr;
  double* d_schur = nullptr;
  double* d_factor = nullptr;
  double* d_rhs = nullptr;
  double* d_camera_delta = nullptr;
  double* d_point_delta = nullptr;
  double* d_workspace = nullptr;
  int* d_solver_info = nullptr;
  auto cleanup = [&]() {
    const bool stream_ready =
        stream == nullptr || cudaStreamQuery(stream) == cudaSuccess;
    ReleaseCudaSolver(solver, stream_ready);
    ReleaseCudaBlas(blas, stream_ready);
    for (cudaEvent_t event : events) ReleaseCudaEvent(event);
    ReleaseCudaStream(stream);
    Release(d_pose_meta);
    Release(d_point_meta);
    Release(d_pair_meta);
    Release(d_pair_contributions);
    Release(d_segment_direct_pair_indices);
    Release(d_schur_segments);
    Release(d_schur_pair_segment_ranges);
    Release(d_pose_edges);
    Release(d_point_edges);
    Release(d_poses);
    Release(d_points);
    Release(d_edges);
    Release(d_point_inverse);
    Release(d_transformed_edges);
    Release(d_schur_segment_partials);
    Release(d_inverse_gradient);
    Release(d_point_status);
    Release(d_schur);
    Release(d_factor);
    Release(d_rhs);
    Release(d_camera_delta);
    Release(d_point_delta);
    Release(d_workspace);
    Release(d_solver_info);
    if (!CudaCleanupSucceeded(error)) {
      result->error = *error;
      result->success = false;
      return false;
    }
    return true;
  };
  const auto allocation_start = std::chrono::steady_clock::now();
  cuda_status = AcquireCudaStream(&stream);
  if (cuda_status != cudaSuccess) {
    *error = "Layer C stream creation failed";
    result->error = *error;
    cleanup();
    return false;
  }
  for (cudaEvent_t& event : events) {
    cuda_status = AcquireCudaEvent(&event);
    if (cuda_status != cudaSuccess) {
      *error = "Layer C event creation failed";
      result->error = *error;
      cleanup();
      return false;
    }
  }
  if (!Allocate(&d_pose_meta, topology.poses.size(), memory_mode, error) ||
      !Allocate(&d_point_meta, topology.points.size(), memory_mode, error) ||
      !Allocate(&d_pair_meta, topology.pairs.size(), memory_mode, error) ||
      !Allocate(&d_pair_contributions, topology.pair_contributions.size(),
                memory_mode, error) ||
      !Allocate(&d_segment_direct_pair_indices,
                topology.segment_direct_pair_indices.size(), memory_mode,
                error) ||
      !Allocate(&d_schur_segments, topology.segments.size(), memory_mode,
                error) ||
      !Allocate(&d_schur_pair_segment_ranges,
                topology.segment_pair_ranges.size(), memory_mode, error) ||
      !Allocate(&d_pose_edges, topology.pose_edges.size(), memory_mode,
                error) ||
      !Allocate(&d_point_edges, topology.point_edges.size(), memory_mode,
                error) ||
      !Allocate(&d_poses, layer_b.poses.size(), memory_mode, error) ||
      !Allocate(&d_points, layer_b.points.size(), memory_mode, error) ||
      !Allocate(&d_edges, layer_b.edges.size(), memory_mode, error) ||
      !Allocate(&d_point_inverse, layer_b.points.size() * 9, memory_mode,
                error) ||
      !Allocate(&d_transformed_edges,
                standalone_transformed
                    ? layer_b.edges.size() * kTransformedEdgeStride
                    : 0,
                memory_mode, error) ||
      !Allocate(&d_schur_segment_partials,
                topology.segments.size() * kSchurSegmentStoredScalars,
                memory_mode, error) ||
      !Allocate(&d_inverse_gradient, layer_b.points.size() * 3, memory_mode,
                error) ||
      !Allocate(&d_point_status, layer_b.points.size(), memory_mode, error) ||
      !Allocate(&d_schur,
                static_cast<size_t>(topology.pose_dimension) *
                    topology.pose_dimension,
                memory_mode, error) ||
      !Allocate(&d_factor,
                static_cast<size_t>(topology.pose_dimension) *
                    topology.pose_dimension,
                memory_mode, error) ||
      !Allocate(&d_rhs, topology.pose_dimension, memory_mode, error) ||
      !Allocate(&d_camera_delta, topology.pose_dimension, memory_mode,
                error) ||
      !Allocate(&d_point_delta, layer_b.points.size() * 3, memory_mode,
                error) ||
      !Allocate(&d_solver_info, 1, memory_mode, error)) {
    result->error = *error;
    cleanup();
    return false;
  }
  result->runtime.active_bytes = CudaActiveBytesForDevice(device);
  result->runtime.cached_bytes = CudaCachedBytesForDevice(device);
  result->runtime.resident_bytes =
      result->runtime.active_bytes + result->runtime.cached_bytes;
  result->runtime.allocation_milliseconds =
      std::chrono::duration<double, std::milli>(
          std::chrono::steady_clock::now() - allocation_start)
          .count();
  CudaTransferBatchAudit h2d_batch(
      stream, memory_mode == CudaMemoryMode::kExplicitDeviceCopy
                  ? CUDA_TIMING_PHASE(h2d_memcpy)
                  : nullptr);
  if (!h2d_batch.Begin(error)) {
    result->error = *error;
    cleanup();
    return false;
  }
  if (!CopyToDevice(d_pose_meta, topology.poses, memory_mode, stream, error) ||
      !CopyToDevice(d_point_meta, topology.points, memory_mode, stream,
                    error) ||
      !CopyToDevice(d_pair_meta, topology.pairs, memory_mode, stream, error) ||
      !CopyToDevice(d_pair_contributions, topology.pair_contributions,
                    memory_mode, stream, error) ||
      !CopyToDevice(d_segment_direct_pair_indices,
                    topology.segment_direct_pair_indices, memory_mode,
                    stream, error) ||
      !CopyToDevice(d_schur_segments, topology.segments, memory_mode, stream,
                    error) ||
      !CopyToDevice(d_schur_pair_segment_ranges,
                    topology.segment_pair_ranges, memory_mode, stream,
                    error) ||
      !CopyToDevice(d_pose_edges, topology.pose_edges, memory_mode, stream,
                    error) ||
      !CopyToDevice(d_point_edges, topology.point_edges, memory_mode, stream,
                    error) ||
      !CopyToDevice(d_poses, layer_b.poses, memory_mode, stream, error) ||
      !CopyToDevice(d_points, layer_b.points, memory_mode, stream, error) ||
      !CopyToDevice(d_edges, layer_b.edges, memory_mode, stream, error) ||
      !h2d_batch.End(error)) {
    result->error = *error;
    cleanup();
    return false;
  }

  AuditCudaEventRecord(events[0], stream);
  if (!layer_b.points.empty()) {
    const int blocks = static_cast<int>(
        (layer_b.points.size() + static_cast<size_t>(block_size) - 1) /
        static_cast<size_t>(block_size));
    LayerCPointFactorKernel<<<blocks, block_size, 0, stream>>>(
        d_points, options.lambda, d_point_inverse, d_inverse_gradient,
        d_point_status, layer_b.points.size());
  }
  AuditCudaEventRecord(events[1], stream);
  std::vector<uint8_t> point_status(layer_b.points.size(), 0);
  CudaTransferBatchAudit point_status_d2h(
      stream, CUDA_TIMING_PHASE(d2h_memcpy));
  if (!point_status_d2h.Begin(error)) {
    result->error = *error;
    cleanup();
    return false;
  }
  if (!CopyFromDevice(d_point_status, &point_status, memory_mode, stream,
                      error) ||
      !point_status_d2h.End(error)) {
    result->error = *error;
    cleanup();
    return false;
  }
  const auto synchronization_start = std::chrono::steady_clock::now();
  cuda_status = TimedCudaStreamSynchronize(stream, CudaSyncSite::kLayerCFactor);
  result->runtime.synchronization_milliseconds +=
      std::chrono::duration<double, std::milli>(
          std::chrono::steady_clock::now() - synchronization_start)
          .count();
  if (cuda_status != cudaSuccess) {
    *error = std::string("Layer C point factorization sync failed: ") +
             CudaErrorText(cuda_status);
    result->error = *error;
    cleanup();
    return false;
  }
  if (!h2d_batch.CompleteAfterExistingSync(error) ||
      !point_status_d2h.CompleteAfterExistingSync(error)) {
    result->error = *error;
    cleanup();
    return false;
  }
  for (size_t i = 0; i < point_status.size(); ++i) {
    if (point_status[i] != 0) {
      ++result->runtime.point_factorization_failures;
      if (result->runtime.first_point_factorization_failure < 0)
        result->runtime.first_point_factorization_failure = i;
    }
  }
  if (result->runtime.point_factorization_failures != 0) {
    *error = "Layer C point block Cholesky failed at point index=" +
             std::to_string(
                 result->runtime.first_point_factorization_failure);
    result->error = *error;
    cleanup();
    return false;
  }

  const size_t schur_elements =
      static_cast<size_t>(topology.pose_dimension) * topology.pose_dimension;
  const size_t zero_count = std::max<size_t>(
      schur_elements, static_cast<size_t>(topology.pose_dimension));
  AuditCudaEventRecord(events[2], stream);
  if (standalone_transformed && !layer_b.edges.empty()) {
    LayerCTransformEdgeKernel<<<layer_b.edges.size(), kTransformedEdgeThreads,
                                0, stream>>>(
        d_edges, d_point_inverse, d_transformed_edges, layer_b.edges.size());
  }
  LayerCZeroSchurKernel<<<
      static_cast<int>((zero_count + block_size - 1) / block_size),
      block_size, 0, stream>>>(d_schur, d_rhs, topology.pose_dimension);
  LayerCInitializePoseKernel<<<topology.poses.size(), 36, 0, stream>>>(
      d_pose_meta, d_poses, options.lambda, d_schur, d_rhs,
      topology.pose_dimension, topology.poses.size());
  const bool standalone_segmented = schur_contribution_backend ==
      CudaSchurContributionBackend::kSegmentedTransformed;
  if (standalone_segmented) {
    result->runtime.segment_plan_builds = 1;
    result->runtime.segment_metadata_h2d_bytes =
        topology.segment_direct_pair_indices.size() * sizeof(uint32_t) +
        topology.segments.size() * sizeof(DeviceSchurSegment) +
        topology.segment_pair_ranges.size() *
            sizeof(DeviceSchurPairSegmentRange);
  }
  const bool contribution_launched = standalone_segmented
      ? LaunchLayerCSegmentedSchurPairChunks(
            topology, device, d_pair_meta, d_segment_direct_pair_indices,
            d_schur_segments, d_schur_pair_segment_ranges,
            d_pair_contributions, d_pose_meta, d_edges, d_transformed_edges,
            d_schur_segment_partials, d_schur, topology.pose_dimension, stream,
            &result->runtime, nullptr, error)
      : LaunchLayerCSchurPairChunks(
            topology, standalone_hot_kernel, device, d_pair_meta,
            d_pair_contributions, d_pose_meta, d_edges, d_point_inverse,
            d_transformed_edges, d_schur, topology.pose_dimension, stream,
            &result->runtime, nullptr, error);
  if (!contribution_launched) {
    result->error = *error;
    cleanup();
    return false;
  }
  AuditCudaEventRecord(events[3], stream);
  if (!topology.poses.empty()) {
    ++result->runtime.schur_rhs_calls;
    LayerCRhsKernel<<<topology.poses.size(), 6, 0, stream>>>(
        d_pose_meta, d_pose_edges, d_edges, d_inverse_gradient, d_rhs,
        topology.poses.size());
  }
  AuditCudaEventRecord(events[4], stream);
  cuda_status = cudaGetLastError();
  result->runtime.cuda_launch_status = static_cast<int>(cuda_status);
  if (cuda_status != cudaSuccess) {
    *error = std::string("Layer C Schur kernel launch failed: ") +
             CudaErrorText(cuda_status);
    result->error = *error;
    cleanup();
    return false;
  }
  const uint64_t d2d_bytes =
      static_cast<uint64_t>(schur_elements * sizeof(double));
  CudaTransferBatchAudit d2d_batch(stream, CUDA_TIMING_PHASE(d2d_memcpy));
  if (!d2d_batch.Begin(error)) {
    result->error = *error;
    cleanup();
    return false;
  }
  {
    HostPhaseScope d2d_api(CUDA_TIMING_PHASE(d2d_memcpy), d2d_bytes);
    cuda_status = cudaMemcpyAsync(d_factor, d_schur, d2d_bytes,
                                  cudaMemcpyDeviceToDevice, stream);
  }
  if (cuda_status != cudaSuccess) {
    *error = "Layer C Schur preservation copy failed";
    result->error = *error;
    cleanup();
    return false;
  }
  if (!d2d_batch.End(error)) {
    result->error = *error;
    cleanup();
    return false;
  }

  cusolverStatus_t solver_status = AcquireCudaSolver(&solver);
  result->runtime.cusolver_create_status = static_cast<int>(solver_status);
  if (solver_status == CUSOLVER_STATUS_SUCCESS)
    solver_status = cusolverDnSetStream(solver, stream);
  result->runtime.cusolver_set_stream_status = static_cast<int>(solver_status);
  cublasStatus_t blas_status = AcquireCudaBlas(&blas);
  result->runtime.cublas_create_status = static_cast<int>(blas_status);
  if (blas_status == CUBLAS_STATUS_SUCCESS)
    blas_status = cublasSetStream(blas, stream);
  result->runtime.cublas_set_stream_status = static_cast<int>(blas_status);
  if (solver_status != CUSOLVER_STATUS_SUCCESS ||
      blas_status != CUBLAS_STATUS_SUCCESS) {
    *error = "Layer C cuSOLVER/cuBLAS handle initialization failed";
    result->error = *error;
    cleanup();
    return false;
  }
  int workspace_count = 0;
  solver_status = cusolverDnDpotrf_bufferSize(
      solver, CUBLAS_FILL_MODE_LOWER, topology.pose_dimension, d_factor,
      topology.pose_dimension, &workspace_count);
  result->runtime.cusolver_buffer_size_status =
      static_cast<int>(solver_status);
  result->runtime.cusolver_workspace_bytes =
      static_cast<uint64_t>(workspace_count) * sizeof(double);
  result->runtime.predicted_additional_bytes +=
      result->runtime.cusolver_workspace_bytes;
  result->runtime.predicted_peak_bytes = SaturatingAdd(
      result->runtime.predicted_peak_bytes,
      result->runtime.cusolver_workspace_bytes);
  size_t free_after_core = 0;
  size_t total_after_core = 0;
  cuda_status = cudaMemGetInfo(&free_after_core, &total_after_core);
  if (options.fault_injection ==
          CudaFaultInjection::kForceWorkspaceAllocationFailure ||
      options.layer_b.fault_injection ==
          CudaFaultInjection::kForceWorkspaceAllocationFailure ||
      solver_status != CUSOLVER_STATUS_SUCCESS ||
      cuda_status != cudaSuccess ||
      !HasCudaMemoryHeadroom(free_after_core,
                             result->runtime.cusolver_workspace_bytes,
                             reserve) ||
      !Allocate(&d_workspace, static_cast<size_t>(workspace_count),
                memory_mode, error)) {
    if (solver_status != CUSOLVER_STATUS_SUCCESS)
      *error = "cusolverDnDpotrf_bufferSize failed";
    else if (options.fault_injection ==
                 CudaFaultInjection::kForceWorkspaceAllocationFailure ||
             options.layer_b.fault_injection ==
                 CudaFaultInjection::kForceWorkspaceAllocationFailure)
      *error = "INSUFFICIENT_GPU_MEMORY for cuSOLVER workspace (fault injection)";
    else if (cuda_status != cudaSuccess ||
             free_after_core <
                 result->runtime.cusolver_workspace_bytes + reserve)
      *error = "INSUFFICIENT_GPU_MEMORY for cuSOLVER workspace";
    result->error = *error;
    cleanup();
    return false;
  }
  result->runtime.active_bytes = CudaActiveBytesForDevice(device);
  result->runtime.cached_bytes = CudaCachedBytesForDevice(device);
  result->runtime.resident_bytes =
      result->runtime.active_bytes + result->runtime.cached_bytes;
  result->runtime.predicted_peak_bytes = std::max(
      result->runtime.predicted_peak_bytes, result->runtime.resident_bytes);
  blas_status = cublasDcopy(blas, topology.pose_dimension, d_rhs, 1,
                            d_camera_delta, 1);
  result->runtime.cublas_copy_status = static_cast<int>(blas_status);
  solver_status = cusolverDnDpotrf(
      solver, CUBLAS_FILL_MODE_LOWER, topology.pose_dimension, d_factor,
      topology.pose_dimension, d_workspace, workspace_count, d_solver_info);
  ++result->runtime.factorization_calls;
  result->runtime.cusolver_potrf_status = static_cast<int>(solver_status);
  if (solver_status == CUSOLVER_STATUS_SUCCESS) {
    solver_status = cusolverDnDpotrs(
        solver, CUBLAS_FILL_MODE_LOWER, topology.pose_dimension, 1, d_factor,
        topology.pose_dimension, d_camera_delta, topology.pose_dimension,
        d_solver_info);
  }
  result->runtime.cusolver_potrs_status = static_cast<int>(solver_status);
  AuditCudaEventRecord(events[5], stream);
  std::vector<int> solver_info(1, 0);
  CudaTransferBatchAudit solver_info_d2h(
      stream, CUDA_TIMING_PHASE(d2h_memcpy));
  if (!solver_info_d2h.Begin(error)) {
    result->error = *error;
    cleanup();
    return false;
  }
  if (!CopyFromDevice(d_solver_info, &solver_info, memory_mode, stream,
                      error) ||
      !solver_info_d2h.End(error)) {
    result->error = *error;
    cleanup();
    return false;
  }
  const auto solver_synchronization_start = std::chrono::steady_clock::now();
  cuda_status = TimedCudaStreamSynchronize(stream, CudaSyncSite::kLayerCSolver);
  result->runtime.synchronization_milliseconds +=
      std::chrono::duration<double, std::milli>(
          std::chrono::steady_clock::now() - solver_synchronization_start)
          .count();
  if (!d2d_batch.CompleteAfterExistingSync(error) ||
      !solver_info_d2h.CompleteAfterExistingSync(error)) {
    result->error = *error;
    cleanup();
    return false;
  }
  result->runtime.cusolver_dev_info = solver_info[0];
  if (cuda_status != cudaSuccess || blas_status != CUBLAS_STATUS_SUCCESS ||
      solver_status != CUSOLVER_STATUS_SUCCESS || solver_info[0] != 0) {
    *error = "Layer C dense Schur factorization/solve failed";
    result->error = *error;
    cleanup();
    return false;
  }

  if (!topology.points.empty()) {
    const int blocks = static_cast<int>(
        (topology.points.size() + static_cast<size_t>(block_size) - 1) /
        static_cast<size_t>(block_size));
    LayerCBackSubstitutionKernel<<<blocks, block_size, 0, stream>>>(
        d_point_meta, d_point_edges, d_pose_meta, d_edges, d_points,
        d_point_inverse, d_camera_delta, d_point_delta,
        topology.points.size());
  }
  AuditCudaEventRecord(events[6], stream);
  result->schur.resize(schur_elements);
  result->factor.resize(schur_elements);
  result->rhs.resize(topology.pose_dimension);
  result->camera_delta.resize(topology.pose_dimension);
  result->point_delta.resize(topology.points.size() * 3);
  const auto copy_start = std::chrono::steady_clock::now();
  CudaTransferBatchAudit final_d2h(stream, CUDA_TIMING_PHASE(d2h_memcpy));
  if (!final_d2h.Begin(error)) {
    result->error = *error;
    cleanup();
    return false;
  }
  if (!CopyFromDevice(d_schur, &result->schur, memory_mode, stream, error) ||
      !CopyFromDevice(d_factor, &result->factor, memory_mode, stream, error) ||
      !CopyFromDevice(d_rhs, &result->rhs, memory_mode, stream, error) ||
      !CopyFromDevice(d_camera_delta, &result->camera_delta, memory_mode,
                      stream, error) ||
      !CopyFromDevice(d_point_delta, &result->point_delta, memory_mode,
                      stream, error) ||
      !final_d2h.End(error)) {
    result->error = *error;
    cleanup();
    return false;
  }
  result->runtime.copy_milliseconds +=
      std::chrono::duration<double, std::milli>(
          std::chrono::steady_clock::now() - copy_start).count();
  const auto final_synchronization_start = std::chrono::steady_clock::now();
  cuda_status = TimedCudaStreamSynchronize(stream, CudaSyncSite::kLayerCFinal);
  result->runtime.synchronization_milliseconds +=
      std::chrono::duration<double, std::milli>(
          std::chrono::steady_clock::now() - final_synchronization_start)
          .count();
  result->runtime.cuda_synchronize_status = static_cast<int>(cuda_status);
  if (cuda_status != cudaSuccess) {
    *error = std::string("Layer C final synchronization failed: ") +
             CudaErrorText(cuda_status);
    result->error = *error;
    cleanup();
    return false;
  }
  if (!final_d2h.CompleteAfterExistingSync(error)) {
    result->error = *error;
    cleanup();
    return false;
  }
  auto elapsed = [](cudaEvent_t begin, cudaEvent_t end) {
    float value = 0.0f;
    AuditCudaEventElapsedTime(&value, begin, end);
    return static_cast<double>(value);
  };
  result->runtime.point_kernel_milliseconds = elapsed(events[0], events[1]);
  result->runtime.schur_kernel_milliseconds = elapsed(events[2], events[3]);
  const double rhs_kernel_milliseconds = elapsed(events[3], events[4]);
  result->runtime.factorization_milliseconds = elapsed(events[4], events[5]);
  result->runtime.back_substitution_milliseconds =
      elapsed(events[5], events[6]);
  RecordCudaEvent(CUDA_TIMING_PHASE(layer_c_point_factor),
                  result->runtime.point_kernel_milliseconds);
  RecordCudaEvent(CUDA_TIMING_PHASE(schur),
                  result->runtime.schur_kernel_milliseconds);
  RecordCudaEvent(CUDA_TIMING_PHASE(rhs), rhs_kernel_milliseconds);
  RecordCudaEvent(CUDA_TIMING_PHASE(cusolver),
                  result->runtime.factorization_milliseconds);
  RecordCudaEvent(CUDA_TIMING_PHASE(back_substitution),
                  result->runtime.back_substitution_milliseconds);
  if (!h2d_batch.Close(error) || !point_status_d2h.Close(error) ||
      !d2d_batch.Close(error) || !solver_info_d2h.Close(error) ||
      !final_d2h.Close(error) || !cleanup()) {
    result->error = *error;
    return false;
  }

  {
    HostPhaseScope host_back_substitution(
        CUDA_TIMING_PHASE(back_substitution_host_self));
    result->symmetry_error = 0.0;
    for (size_t row = 0; row < topology.pose_dimension; ++row) {
      for (size_t col = 0; col < topology.pose_dimension; ++col) {
        result->symmetry_error = std::max(
            result->symmetry_error,
            std::abs(result->schur[row * topology.pose_dimension + col] -
                     result->schur[col * topology.pose_dimension + row]));
      }
    }
  }
  if (!ComputeLayerCDiagnostics(layer_b, topology, options.lambda,
                                result->camera_delta, result->point_delta,
                                &result->backward_error,
                                &result->predicted_reduction, error) ||
      !ApplyLayerCStep(snapshot, layer_b, topology, result->camera_delta,
                       result->point_delta, &result->trial_state, error)) {
    result->error = *error;
    return false;
  }
  CudaLayerAResult trial_layer_a;
  const PackedLayerAState* trial_packed = nullptr;
  if (!context->AcquirePackedState(result->trial_state, false, &trial_packed,
                                   error) ||
      !RunCudaLayerA(trial_packed->visual, trial_packed->lidar,
                     options.layer_b.layer_a, &trial_layer_a)) {
    if (error->empty()) *error = trial_layer_a.error;
    result->error = *error;
    return false;
  }
  const LayerAOutputView trial_view = context->MakeLayerAView(trial_layer_a);
  if (!context->ValidateLayerAView(trial_view, error) ||
      !ComputeCudaCost(context->cost_layout(), trial_view,
                       context->loss_mode(), context->loss_scale(),
                       options.layer_b,
                       &result->trial_cost,
                       &result->runtime.trial_cost_kernel_milliseconds,
                       error)) {
    result->error = *error;
    return false;
  }
  result->runtime.host_wall_milliseconds =
      std::chrono::duration<double, std::milli>(
          std::chrono::steady_clock::now() - host_start)
          .count();
  result->success = true;
  return true;
}

UndampedCurrentLinearization UndampedCurrentLinearization::Adopt(
    const CudaLinearizationIdentity& identity,
    CudaLayerBResult&& layer_b,
    const CudaDeviceLinearizationToken& device_token) noexcept {
  UndampedCurrentLinearization result;
  result.valid_ = layer_b.success;
  result.identity_ = identity;
  result.device_token_ = device_token;
  result.layer_b_ = std::move(layer_b);
  return result;
}

void UndampedCurrentLinearization::Swap(
    UndampedCurrentLinearization& other) noexcept {
  using std::swap;
  swap(valid_, other.valid_);
  swap(identity_, other.identity_);
  swap(device_token_, other.device_token_);
  swap(layer_b_, other.layer_b_);
}

static_assert(!std::is_copy_constructible<UndampedCurrentLinearization>::value,
              "current linearization must remain move-only");
static_assert(!std::is_copy_assignable<UndampedCurrentLinearization>::value,
              "current linearization must remain move-only");
static_assert(
    std::is_nothrow_move_constructible<CudaLayerBResult>::value &&
        std::is_nothrow_move_assignable<CudaLayerBResult>::value,
    "CudaLayerBResult must support no-fail ownership transfer");
static_assert(
    std::is_nothrow_move_constructible<UndampedCurrentLinearization>::value &&
        std::is_nothrow_move_assignable<UndampedCurrentLinearization>::value,
    "UndampedCurrentLinearization must support no-fail ownership transfer");

static bool RunCudaSnapshotLayerCFromLinearization(
    GpuBaSolveContext* context,
    const Snapshot& snapshot,
    const CudaLayerCOptions& options,
    const UndampedCurrentLinearization& linearization,
    CudaLayerCStepResult* result,
    std::string* error) {
  if (!linearization.valid()) {
    if (error != nullptr) *error = "borrowed current linearization is invalid";
    if (result != nullptr) {
      *result = CudaLayerCStepResult();
      result->error = error == nullptr ? "invalid linearization" : *error;
    }
    return false;
  }
  return RunCudaLayerCFromContext(context, snapshot, options,
                                  linearization.layer_b(),
                                  &linearization.identity(),
                                  &linearization.device_token(), result,
                                  error);
}

static bool RunCudaNativeLayerCFromContext(
    GpuBaSolveContext* context,
    const CudaLayerCOptions& options,
    const CudaLayerBResult& layer_b,
    const CudaLinearizationIdentity& identity,
    const CudaDeviceLinearizationToken& token,
    CudaLayerCStepResult* result,
    std::string* error) {
  if (context == nullptr || result == nullptr || error == nullptr ||
      !context->device_control_enabled() || context->audit_mirror_enabled() ||
      !std::isfinite(options.lambda) || options.lambda < 0.0 || !token.valid) {
    if (error != nullptr) *error = "native Layer C invocation is invalid";
    return false;
  }
  *result = CudaLayerCStepResult();
  InclusiveCallScope inclusive_call(CUDA_TIMING_PHASE(layer_c_call));
  if (g_cuda_solve_call_counters != nullptr)
    ++g_cuda_solve_call_counters->layer_c;
  if (g_cuda_timing_sink != nullptr) ++g_cuda_timing_sink->layer_c_calls;
  const LayerBTopology& layer_b_topology = context->BorrowLayerBTopology();
  const LayerCTopology& layer_c_topology = context->BorrowLayerCTopology();
  result->pose_dimension = layer_c_topology.pose_dimension;
  result->point_dimension = layer_c_topology.points.size() * 3;
  if (layer_c_topology.pose_dimension == 0) {
    *error = "native Layer C requires at least one variable pose";
    result->error = *error;
    return false;
  }
  if (!context->persistent_device()->RunLayerCLinearSolve(
          layer_b_topology, layer_c_topology, options, identity, token, layer_b,
          result, error) ||
      !context->persistent_device()->BuildNativeDeviceTrialState(
          identity, options.layer_b.layer_a.block_size, error)) {
    context->DiscardDeviceTrialState();
    result->error = *error;
    return false;
  }
  CudaLinearizationIdentity trial_identity = identity;
  ++trial_identity.state_epoch;
  if (!context->persistent_device()->RunDeviceTrialCost(
          options.layer_b, trial_identity, context->loss_mode(),
          context->loss_scale(), &result->trial_cost,
          &result->runtime.trial_cost_kernel_milliseconds, error) ||
      !context->persistent_device()->RunDeviceDiagnostics(
          identity, token, options.lambda, result, error)) {
    context->DiscardDeviceTrialState();
    result->error = *error;
    return false;
  }
  result->success = true;
  return true;
}

bool RunCudaSnapshotLayerC(const Snapshot& snapshot,
                           const CudaLayerCOptions& options,
                           CudaLayerCResult* result,
                           std::string* error) {
  if (result == nullptr || error == nullptr) return false;
  *result = CudaLayerCResult();
  if (!CudaStandaloneEntryAllowed(error)) {
    result->error = *error;
    return false;
  }
  CudaSchurContributionBackend contribution_backend =
      CudaSchurContributionBackend::kDirectTransformed;
  std::string contribution_requested;
  if (!ResolveSchurContributionBackend(options.schur_contribution_backend,
                                       &contribution_backend,
                                       &contribution_requested, error)) {
    result->error = *error;
    return false;
  }
  GpuBaSolveContext context;
  if (!context.Initialize(snapshot, options.layer_b,
                          options.pair_chunk_limit_bytes_for_testing, 1, true,
                          CudaDeviceContextBackend::kLegacy,
                          HotKernelImplementation::kReference,
                          contribution_backend,
                          options.schur_segment_size_for_testing,
                          CudaExecutionProfile::kBaseline, false, nullptr,
                          error)) {
    result->error = *error;
    return false;
  }
  CudaLayerBResult layer_b;
  if (!RunCudaLayerBFromContext(
          &context, snapshot, options.layer_b, nullptr,
          CudaFaultLogicalSite::kInitialLinearization, &layer_b, nullptr,
          error)) {
    result->error = *error;
    return false;
  }
  CudaLayerCStepResult step;
  const bool success = RunCudaLayerCFromContext(
      &context, snapshot, options, layer_b, nullptr, nullptr, &step, error);
  result->success = step.success;
  result->error = std::move(step.error);
  result->pose_dimension = step.pose_dimension;
  result->point_dimension = step.point_dimension;
  result->schur = std::move(step.schur);
  result->factor = std::move(step.factor);
  result->rhs = std::move(step.rhs);
  result->camera_delta = std::move(step.camera_delta);
  result->point_delta = std::move(step.point_delta);
  result->symmetry_error = step.symmetry_error;
  result->backward_error = step.backward_error;
  result->predicted_reduction = step.predicted_reduction;
  result->trial_cost = step.trial_cost;
  result->trial_state = std::move(step.trial_state);
  result->runtime = std::move(step.runtime);
  result->layer_b = std::move(layer_b);
  return success;
}

namespace {

bool SameLinearizationIdentity(const CudaLinearizationIdentity& lhs,
                               const CudaLinearizationIdentity& rhs) {
  return lhs.solve_generation == rhs.solve_generation &&
         lhs.state_epoch == rhs.state_epoch &&
         lhs.topology_generation == rhs.topology_generation &&
         lhs.config_generation == rhs.config_generation;
}

uint64_t NonzeroGeneration(const uint64_t value) {
  return value == 0 ? 1 : value;
}

std::atomic<uint64_t> g_cuda_next_mathematical_generation{1};

uint64_t NextMathematicalGeneration() noexcept {
  uint64_t value = ++g_cuda_next_mathematical_generation;
  if (value == 0) value = ++g_cuda_next_mathematical_generation;
  return value;
}

uint64_t ComputeTopologyGeneration(const Snapshot& snapshot) {
  uint64_t state = 1469598103934665603ull;
  HashTag(&state, 0x544f504f4c4f4759ull);
  HashWord(&state, snapshot.images.size());
  for (const ImageSnapshot& image : snapshot.images) {
    HashWord(&state, image.image_id);
    HashWord(&state, image.camera_id);
    HashWord(&state, image.pose_constant ? 1 : 0);
    HashWord(&state, image.constant_tvec_mask);
  }
  HashWord(&state, snapshot.points.size());
  for (const PointSnapshot& point : snapshot.points) {
    HashWord(&state, point.point3D_id);
    HashWord(&state, point.constant ? 1 : 0);
  }
  HashWord(&state, snapshot.source_insertion_order.size());
  for (const OrderEntrySnapshot& entry : snapshot.source_insertion_order) {
    HashWord(&state, entry.source_index);
    HashWord(&state, static_cast<uint64_t>(entry.residual_kind));
    HashWord(&state, entry.image_id);
    HashWord(&state, entry.point2D_idx);
    HashWord(&state, entry.point3D_id);
  }
  return NonzeroGeneration(state);
}

uint64_t ComputeConfigGeneration(const Snapshot& snapshot,
                                 const CudaLayerBOptions& options) {
  uint64_t state = 1469598103934665603ull;
  HashTag(&state, 0x434f4e4649475f31ull);
  HashWord(&state, static_cast<uint64_t>(options.layer_a.residual_order));
  HashWord(&state, static_cast<uint64_t>(options.loss_mode));
  HashDouble(&state, options.loss_scale);
  HashDouble(&state, options.min_lm_diagonal);
  HashDouble(&state, options.max_lm_diagonal);
  HashWord(&state, static_cast<uint64_t>(options.reduction_mode));
  HashWord(&state, options.cost_reduction_threads);
  for (const ImageSnapshot& image : snapshot.images) {
    HashWord(&state, image.image_id);
    HashWord(&state, image.pose_constant ? 1 : 0);
    HashWord(&state, image.constant_tvec_mask);
  }
  for (const PointSnapshot& point : snapshot.points) {
    HashWord(&state, point.point3D_id);
    HashWord(&state, point.constant ? 1 : 0);
  }
  for (const CameraSnapshot& camera : snapshot.cameras) {
    HashWord(&state, camera.camera_id);
    HashWord(&state, camera.constant ? 1 : 0);
  }
  HashWord(&state, options.frozen_pose_jacobi_scaling.size());
  for (double value : options.frozen_pose_jacobi_scaling)
    HashDouble(&state, value);
  HashWord(&state, options.frozen_point_jacobi_scaling.size());
  for (double value : options.frozen_point_jacobi_scaling)
    HashDouble(&state, value);
  return NonzeroGeneration(state);
}

int DiagnosticPriority(const CudaSolveErrorClass value) noexcept {
  switch (value) {
    case CudaSolveErrorClass::kResourceCleanup:
      return 4;
    case CudaSolveErrorClass::kCudaTiming:
      return 3;
    case CudaSolveErrorClass::kAuditCapacity:
      return 2;
    default:
      return 1;
  }
}

void RecordDiagnosticOverflow(CudaFullLmRuntimeInfo* runtime) noexcept {
  CudaDiagnosticStructureV2& diagnostics =
      runtime->diagnostic_structure_v2;
  ++diagnostics.diagnostic_overflow_count;
  diagnostics.overflow_sentinel_set = true;
  diagnostics.overflow_sentinel.error_classification =
      CudaSolveErrorClass::kAuditCapacity;
  diagnostics.overflow_sentinel.failure_site =
      CudaFailureSite::kAuditRuntimeOverflow;
  diagnostics.overflow_sentinel.status_domain = CudaStatusDomain::kInternal;
  diagnostics.overflow_sentinel.raw_status_code =
      static_cast<int64_t>(diagnostics.diagnostic_overflow_count);
}

void AppendSecondaryDiagnostic(CudaFullLmRuntimeInfo* runtime,
                               const CudaStableDiagnosticV2& value) noexcept {
  CudaDiagnosticStructureV2& diagnostics =
      runtime->diagnostic_structure_v2;
  const uint64_t capacity = std::min<uint64_t>(
      runtime->secondary_diagnostic_capacity, diagnostics.secondary.size());
  if (diagnostics.secondary_count >= capacity) {
    RecordDiagnosticOverflow(runtime);
    return;
  }
  diagnostics.secondary[static_cast<size_t>(diagnostics.secondary_count++)] =
      value;
}

void RecordDiagnostic(CudaFullLmRuntimeInfo* runtime,
                      const CudaStableDiagnosticV2& value) noexcept {
  CudaDiagnosticStructureV2& diagnostics =
      runtime->diagnostic_structure_v2;
  if (!diagnostics.has_primary) {
    diagnostics.has_primary = true;
    diagnostics.primary = value;
    return;
  }
  if (DiagnosticPriority(value.error_classification) >
      DiagnosticPriority(diagnostics.primary.error_classification)) {
    const CudaStableDiagnosticV2 old_primary = diagnostics.primary;
    diagnostics.primary = value;
    AppendSecondaryDiagnostic(runtime, old_primary);
    return;
  }
  AppendSecondaryDiagnostic(runtime, value);
}

CudaStableDiagnosticV2 MakeDiagnostic(
    const CudaSolveErrorClass error_classification,
    const CudaFailureSite failure_site,
    const CudaStatusDomain status_domain,
    const int64_t raw_status_code) noexcept {
  CudaStableDiagnosticV2 value;
  value.error_classification = error_classification;
  value.failure_site = failure_site;
  value.status_domain = status_domain;
  value.raw_status_code = raw_status_code;
  return value;
}

void FinalizeProductionAuditInvariants(
    const CudaAuditProfile profile,
    CudaFullLmRuntimeInfo* runtime) {
  if (runtime == nullptr || profile != CudaAuditProfile::kProduction) return;
  runtime->production_audit_invariants_checked = true;
  runtime->production_audit_invariants_pass = true;
  const auto check = [runtime](const bool condition, const char* name) {
    if (condition) return;
    runtime->production_audit_invariants_pass = false;
    ++runtime->production_audit_violation_count;
    if (runtime->first_production_audit_violation.empty()) {
      runtime->first_production_audit_violation = name;
    }
  };
  const CudaPersistentDeviceRuntimeInfo& device = runtime->persistent_device;
  check(!runtime->instrumentation_effective, "instrumentation_enabled");
  check(!runtime->capture_state_trace_effective, "state_trace_enabled");
  check(runtime->initial_state_hash.empty() && runtime->final_state_hash.empty(),
        "state_hash_materialized");
  check(runtime->state_hash_audit.layout_builds == 0 &&
            runtime->state_hash_audit.current.computations == 0 &&
            runtime->state_hash_audit.trial.computations == 0,
        "state_hash_computed");
  check(runtime->topology_fingerprint_computations == 0,
        "topology_fingerprint_computed");
  check(device.audit_mirror_b_calls == 0 &&
            device.audit_mirror_b_bytes == 0,
        "layer_b_audit_mirror");
  check(device.audit_mirror_state_calls == 0 &&
            device.audit_mirror_state_bytes == 0,
        "state_audit_mirror");
  check(device.audit_mirror_schur_calls == 0 &&
            device.audit_mirror_schur_bytes == 0,
        "schur_audit_mirror");
  check(device.audit_mirror_delta_calls == 0 &&
            device.audit_mirror_delta_bytes == 0,
        "delta_audit_mirror");
  check(device.host_diagnostics_d2h_calls == 0 &&
            device.host_diagnostics_d2h_bytes == 0,
        "host_diagnostics_d2h");
  check(device.bootstrap_scaling_mirror_calls == 0 &&
            device.bootstrap_scaling_mirror_bytes == 0,
        "bootstrap_scaling_mirror");
  check(device.steady_full_b_d2h_calls == 0 &&
            device.steady_full_b_d2h_bytes == 0 &&
            device.steady_schur_d2h_calls == 0 &&
            device.steady_schur_d2h_bytes == 0 &&
            device.steady_delta_d2h_calls == 0 &&
            device.steady_delta_d2h_bytes == 0 &&
            device.steady_trial_state_d2h_calls == 0 &&
            device.steady_trial_state_d2h_bytes == 0,
        "steady_full_array_d2h");
  check(device.mixed_full_array_d2h_bytes == 0,
        "mixed_full_array_d2h");
  check(device.mixed_double_edge_materialization_calls == 0 &&
            device.mixed_double_edge_materialization_bytes == 0,
        "mixed_double_edge_materialization");
}

class RuntimeAuditFinalizer {
 public:
  RuntimeAuditFinalizer(CudaFullLmResult* result,
                        std::string* error,
                        const bool instrumentation_enabled) noexcept
      : result_(result),
        runtime_(&result->runtime),
        error_(error),
        instrumentation_enabled_(instrumentation_enabled) {}

  ~RuntimeAuditFinalizer() noexcept { Finalize(); }

  void Finalize() noexcept {
    if (finalized_) return;
    finalized_ = true;
    runtime_->solve_generation_nonzero =
        runtime_->solve_generation_nonzero_checks == 1 &&
        runtime_->solve_generation_nonzero_violations == 0;
    runtime_->solve_generation_consistent =
        runtime_->solve_generation_consistency_checks > 0 &&
        runtime_->solve_generation_consistency_violations == 0;
    runtime_->linearization_identity_consistent =
        runtime_->linearization_identity_checks > 0 &&
        runtime_->linearization_identity_violations == 0;
    runtime_->topology_context_generation_consistent =
        runtime_->topology_context_generation_checks > 0 &&
        runtime_->topology_context_generation_violations == 0;
    CudaTimingStructureV2& timing = runtime_->timing_structure_v2;
    if (!instrumentation_enabled_) {
      timing = CudaTimingStructureV2();
      timing.timing_status = CudaTimingStatus::kDisabled;
    } else if (timing.event_attempts ==
                   timing.event_completions + timing.event_failures &&
               timing.intervals_started ==
                   timing.intervals_completed + timing.intervals_abandoned &&
               timing.event_failures == 0 &&
               timing.intervals_abandoned == 0 &&
               timing.open_intervals_at_finalize == 0) {
      timing.timing_status = CudaTimingStatus::kComplete;
    } else {
      timing.timing_status = CudaTimingStatus::kIncomplete;
    }
    runtime_->resource_cleanup_complete = g_cuda_taint_cleanup_complete;
    if (timing.timing_status == CudaTimingStatus::kIncomplete) {
      const CudaFailureSite site = timing.has_first_incomplete_site
          ? timing.first_incomplete_site
          : CudaFailureSite::kTimingElapsedQuery;
      RecordDiagnostic(
          runtime_,
          MakeDiagnostic(CudaSolveErrorClass::kCudaTiming, site,
                         CudaStatusDomain::kCudaRuntime, 1));
    }
    if (!runtime_->resource_cleanup_complete) {
      const CudaStableDiagnosticV2 diagnostic =
          runtime_->has_first_cleanup_failure
              ? runtime_->first_cleanup_failure
              : MakeDiagnostic(CudaSolveErrorClass::kResourceCleanup,
                               CudaFailureSite::kDestroyAllocation,
                               CudaStatusDomain::kCudaRuntime, 1);
      RecordDiagnostic(runtime_, diagnostic);
    }
    if (runtime_->audit_overflow_count > 0) {
      RecordDiagnostic(
          runtime_,
          MakeDiagnostic(CudaSolveErrorClass::kAuditCapacity,
                         CudaFailureSite::kAuditRuntimeOverflow,
                         CudaStatusDomain::kInternal,
                         static_cast<int64_t>(runtime_->audit_overflow_count)));
    }
    if (runtime_->diagnostic_structure_v2.has_primary &&
        DiagnosticPriority(
            runtime_->diagnostic_structure_v2.primary.error_classification) >=
            DiagnosticPriority(result_->error_classification)) {
      result_->error_classification =
          runtime_->diagnostic_structure_v2.primary.error_classification;
      result_->termination_type = CudaTerminationType::kFailure;
      switch (result_->error_classification) {
        case CudaSolveErrorClass::kResourceCleanup:
          result_->termination_reason = "resource_cleanup_failed";
          result_->error = "ResourceCleanup: CUDA resource cleanup failed";
          break;
        case CudaSolveErrorClass::kCudaTiming:
          result_->termination_reason = "cuda_timing_incomplete";
          result_->error = "CudaTiming: CUDA timing audit incomplete";
          break;
        case CudaSolveErrorClass::kAuditCapacity:
          result_->termination_reason = "audit_capacity_exceeded";
          result_->error = "AuditCapacity: fixed audit capacity exceeded";
          break;
        default:
          break;
      }
      *error_ = result_->error;
      result_->success = false;
    }
  }

 private:
  CudaFullLmResult* result_ = nullptr;
  CudaFullLmRuntimeInfo* runtime_ = nullptr;
  std::string* error_ = nullptr;
  bool instrumentation_enabled_ = false;
  bool finalized_ = false;
};

class LogicalFaultController {
 public:
  LogicalFaultController(const CudaFaultTrigger& trigger,
                         CudaFullLmRuntimeInfo* runtime)
      : trigger_(trigger), runtime_(runtime) {}

  CudaFaultInjection Consume(const CudaFaultLogicalSite site,
                             const CudaFaultTriggerPhase phase,
                             const uint16_t operation,
                             const uint64_t state_epoch) noexcept {
    if (site == CudaFaultLogicalSite::kNone) return CudaFaultInjection::kNone;
    if (trigger_.fault_kind == CudaFaultInjection::kNone) {
      return CudaFaultInjection::kNone;
    }
    uint64_t occurrence = 1;
    for (uint64_t i = 0; i < runtime_->fault_consumption_count; ++i) {
      const CudaFaultConsumptionV2& previous =
          runtime_->fault_consumptions[static_cast<size_t>(i)];
      if (previous.logical_site == site && previous.trigger_phase == phase &&
          previous.operation == operation && previous.epoch == state_epoch) {
        occurrence = std::max(occurrence, previous.occurrence + 1);
      }
    }
    const bool phase_matches =
        trigger_.trigger_phase == CudaFaultTriggerPhase::kNone ||
        trigger_.trigger_phase == phase;
    const bool operation_matches =
        trigger_.operation == 0 || trigger_.operation == operation;
    const bool triggered = trigger_.logical_site == site && phase_matches &&
                           operation_matches &&
                           trigger_.target_state_epoch == state_epoch &&
                           trigger_.occurrence_within_site == occurrence;
    if (runtime_->fault_consumption_count >= runtime_->fault_record_capacity ||
        runtime_->fault_consumption_count >=
            runtime_->fault_consumptions.size()) {
      ++runtime_->audit_overflow_count;
      if (!runtime_->has_first_audit_overflow_site) {
        runtime_->has_first_audit_overflow_site = true;
        runtime_->first_audit_overflow_site =
            CudaFailureSite::kAuditRuntimeOverflow;
      }
      overflowed_ = true;
      return CudaFaultInjection::kNone;
    }
    CudaFaultConsumptionV2& record = runtime_->fault_consumptions[
        static_cast<size_t>(runtime_->fault_consumption_count++)];
    record.logical_site = site;
    record.trigger_phase = phase;
    record.operation = operation;
    record.configured_fault_kind = trigger_.fault_kind;
    record.epoch = state_epoch;
    record.occurrence = occurrence;
    record.triggered = triggered;
    return triggered ? trigger_.fault_kind : CudaFaultInjection::kNone;
  }

  bool overflowed() const noexcept { return overflowed_; }

  bool has_explicit_phase() const noexcept {
    return trigger_.trigger_phase != CudaFaultTriggerPhase::kNone;
  }

  bool force_resource_teardown_failure() const {
    return trigger_.force_resource_teardown_failure ||
           trigger_.fault_kind ==
               CudaFaultInjection::kForceResourceTeardownFailure;
  }

 private:
  CudaFaultTrigger trigger_;
  CudaFullLmRuntimeInfo* runtime_ = nullptr;
  bool overflowed_ = false;
};

class CurrentLinearizationController {
 public:
  CurrentLinearizationController(
      const CudaCurrentLinearizationCacheMode mode,
      GpuBaSolveContext* context,
      CudaFullLmRuntimeInfo* runtime,
      LogicalFaultController* faults,
      const uint64_t solve_generation,
      const uint64_t topology_generation)
      : cache_enabled_(mode == CudaCurrentLinearizationCacheMode::kEnabled),
        context_(context),
        runtime_(runtime),
        faults_(faults),
        solve_generation_(solve_generation),
        topology_generation_(topology_generation) {
    runtime_->current_linearization_cache_requested = cache_enabled_;
    runtime_->current_linearization_cache_effective = cache_enabled_;
  }

  bool Build(const Snapshot& snapshot,
             const CudaLinearizationIdentity& identity,
             const CudaLayerBOptions& options,
             const CudaFaultLogicalSite site,
             UndampedCurrentLinearization* output,
             std::string* error) {
    if (!ValidateIdentity(identity)) {
      *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
      return false;
    }
    ++runtime_->current_linearization_logical_requests;
    const CudaFaultInjection before_lookup = faults_->Consume(
        site, CudaFaultTriggerPhase::kBeforeCacheLookup, 0,
        identity.state_epoch);
    if (before_lookup == CudaFaultInjection::kForceIdentityMismatch ||
        (before_lookup != CudaFaultInjection::kNone &&
         faults_->has_explicit_phase())) {
      ++runtime_->current_linearization_lookup_aborts;
      *error = "CURRENT_LINEARIZATION_LOOKUP_ABORTED";
      return false;
    }
    ++runtime_->current_linearization_cache_lookups;
    ++runtime_->current_linearization_cache_misses;
    ++runtime_->current_linearization_build_attempts;
    const CudaFaultInjection after_miss = faults_->Consume(
        site, CudaFaultTriggerPhase::kAfterCacheMiss, 0,
        identity.state_epoch);
    try {
      const CudaLayerBOptions* selected_options = &options;
      CudaLayerBOptions injected_options;
      if (after_miss == CudaFaultInjection::kForceIdentityMismatch ||
          (after_miss == CudaFaultInjection::kForceLinearizationFailure &&
           faults_->has_explicit_phase())) {
        ++runtime_->current_linearization_build_failures;
        *error = "CURRENT_LINEARIZATION_BUILD_ABORTED_AFTER_CACHE_MISS";
        return false;
      }
      if (after_miss == CudaFaultInjection::kForceInsufficientMemory) {
        injected_options = options;
        injected_options.fault_injection = after_miss;
        selected_options = &injected_options;
      }
      CudaLayerBResult layer_b;
      CudaDeviceLinearizationToken device_token;
      if (!RunCudaLayerBFromContext(context_, snapshot, *selected_options,
                                    &identity, site, &layer_b, &device_token,
                                    error)) {
        ++runtime_->current_linearization_build_failures;
        return false;
      }
      const CudaFaultInjection after_refresh = faults_->Consume(
          site, CudaFaultTriggerPhase::kAfterTopologyRefreshBeforePublish, 0,
          identity.state_epoch);
      // Legacy phase-less triggers retain the Phase 7.1a late-failure point.
      const bool legacy_late_fault =
          !faults_->has_explicit_phase() &&
          (after_miss == CudaFaultInjection::kForceLinearizationFailure ||
           after_miss ==
               CudaFaultInjection::kForceResourceTeardownFailure);
      if (legacy_late_fault ||
          (after_refresh != CudaFaultInjection::kNone &&
           faults_->has_explicit_phase())) {
        context_->DiscardPersistentBuild(site);
        ++runtime_->current_linearization_build_failures;
        *error = "ACCEPTED_PENDING_LINEARIZATION_FAILED: injected after "
                 "topology refresh and before publish";
        return false;
      }
      if (!layer_b.success || !std::isfinite(layer_b.cost) ||
          !std::isfinite(layer_b.projected_gradient_max_norm) ||
          !std::isfinite(layer_b.scaled_gradient_max_norm)) {
        ++runtime_->current_linearization_build_failures;
        *error = "current linearization validation failed";
        return false;
      }
      if (identity.state_epoch >=
          runtime_->current_linearization_builds_by_state_epoch.size()) {
        ++runtime_->current_linearization_build_failures;
        *error = "current linearization state epoch exceeds reserved audit "
                 "storage";
        return false;
      }
      ++runtime_->current_linearization_build_successes;
      ++runtime_->current_linearization_builds_by_state_epoch[
          identity.state_epoch];
      *output = UndampedCurrentLinearization::Adopt(
          identity, std::move(layer_b), device_token);
      return true;
    } catch (const std::exception& exception) {
      ++runtime_->current_linearization_build_failures;
      *error = std::string("current linearization preparation threw: ") +
               exception.what();
      return false;
    }
  }

  bool BuildNative(const CudaLinearizationIdentity& identity,
                   const CudaLayerBOptions& options,
                   const CudaFaultLogicalSite site,
                   UndampedCurrentLinearization* output,
                   std::string* error) {
    if (!ValidateIdentity(identity)) {
      *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
      return false;
    }
    ++runtime_->current_linearization_logical_requests;
    const CudaFaultInjection before_lookup = faults_->Consume(
        site, CudaFaultTriggerPhase::kBeforeCacheLookup, 0,
        identity.state_epoch);
    if (before_lookup != CudaFaultInjection::kNone) {
      ++runtime_->current_linearization_lookup_aborts;
      *error = "CURRENT_LINEARIZATION_LOOKUP_ABORTED";
      return false;
    }
    ++runtime_->current_linearization_cache_lookups;
    ++runtime_->current_linearization_cache_misses;
    ++runtime_->current_linearization_build_attempts;
    const CudaFaultInjection after_miss = faults_->Consume(
        site, CudaFaultTriggerPhase::kAfterCacheMiss, 0,
        identity.state_epoch);
    if (after_miss != CudaFaultInjection::kNone) {
      ++runtime_->current_linearization_build_failures;
      *error = "CURRENT_LINEARIZATION_BUILD_ABORTED_AFTER_CACHE_MISS";
      return false;
    }
    CudaLayerBResult layer_b;
    CudaDeviceLinearizationToken device_token;
    if (!RunCudaNativeLayerBFromContext(context_, options, identity, site,
                                        &layer_b, &device_token, error)) {
      ++runtime_->current_linearization_build_failures;
      return false;
    }
    const CudaFaultInjection before_publish = faults_->Consume(
        site, CudaFaultTriggerPhase::kAfterTopologyRefreshBeforePublish, 0,
        identity.state_epoch);
    if (before_publish != CudaFaultInjection::kNone) {
      context_->DiscardPersistentBuild(site);
      ++runtime_->current_linearization_build_failures;
      *error = "ACCEPTED_PENDING_LINEARIZATION_FAILED";
      return false;
    }
    if (!layer_b.success || !std::isfinite(layer_b.cost) ||
        !std::isfinite(layer_b.projected_gradient_max_norm) ||
        !std::isfinite(layer_b.scaled_gradient_max_norm) ||
        identity.state_epoch >=
            runtime_->current_linearization_builds_by_state_epoch.size()) {
      ++runtime_->current_linearization_build_failures;
      *error = "native current linearization validation failed";
      return false;
    }
    ++runtime_->current_linearization_build_successes;
    ++runtime_->current_linearization_builds_by_state_epoch[
        identity.state_epoch];
    *output = UndampedCurrentLinearization::Adopt(
        identity, std::move(layer_b), device_token);
    return true;
  }

  void PublishInitial(UndampedCurrentLinearization&& value) noexcept {
    current_ = std::move(value);
    has_current_ = true;
    ++runtime_->current_linearization_publishes;
  }

  bool Resolve(const Snapshot& snapshot,
               const CudaLinearizationIdentity& identity,
               const CudaLayerBOptions& options,
               UndampedCurrentLinearization* temporary,
               const UndampedCurrentLinearization** borrowed,
               std::string* error) {
    if (cache_enabled_) {
      if (!ValidateIdentity(identity)) {
        *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
        return false;
      }
      ++runtime_->current_linearization_logical_requests;
      const CudaFaultInjection before_lookup = faults_->Consume(
          CudaFaultLogicalSite::kCurrentTrialRecompute,
          CudaFaultTriggerPhase::kBeforeCacheLookup, 0,
          identity.state_epoch);
      if (before_lookup == CudaFaultInjection::kForceIdentityMismatch ||
          (before_lookup != CudaFaultInjection::kNone &&
           faults_->has_explicit_phase())) {
        ++runtime_->current_linearization_lookup_aborts;
        *error = "CURRENT_LINEARIZATION_LOOKUP_ABORTED";
        return false;
      }
      ++runtime_->current_linearization_cache_lookups;
      if (!has_current_ || !current_.valid() ||
          !SameLinearizationIdentity(current_.identity(), identity)) {
        ++runtime_->linearization_identity_violations;
        ++runtime_->current_linearization_cache_misses;
        ++runtime_->current_linearization_invalidations;
        *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
        return false;
      }
      ++runtime_->current_linearization_cache_hits;
      ++runtime_->current_linearization_borrows;
      runtime_->last_borrowed_layer_b_address = reinterpret_cast<uintptr_t>(
          current_.borrowed_layer_b_address());
      *borrowed = &current_;
      return true;
    }
    if (!Build(snapshot, identity, options,
               CudaFaultLogicalSite::kCurrentTrialRecompute, temporary,
               error)) {
      return false;
    }
    ++runtime_->current_linearization_temporary_builds;
    ++runtime_->current_linearization_borrows;
    runtime_->last_borrowed_layer_b_address = reinterpret_cast<uintptr_t>(
        temporary->borrowed_layer_b_address());
    *borrowed = temporary;
    return true;
  }

  bool ResolveNative(const CudaLinearizationIdentity& identity,
                     const CudaLayerBOptions& options,
                     UndampedCurrentLinearization* temporary,
                     const UndampedCurrentLinearization** borrowed,
                     std::string* error) {
    if (cache_enabled_) {
      if (!ValidateIdentity(identity)) {
        *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
        return false;
      }
      ++runtime_->current_linearization_logical_requests;
      ++runtime_->current_linearization_cache_lookups;
      if (!has_current_ || !current_.valid() ||
          !SameLinearizationIdentity(current_.identity(), identity)) {
        ++runtime_->current_linearization_cache_misses;
        ++runtime_->current_linearization_invalidations;
        *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
        return false;
      }
      ++runtime_->current_linearization_cache_hits;
      ++runtime_->current_linearization_borrows;
      runtime_->last_borrowed_layer_b_address = reinterpret_cast<uintptr_t>(
          current_.borrowed_layer_b_address());
      *borrowed = &current_;
      return true;
    }
    if (!BuildNative(identity, options,
                     CudaFaultLogicalSite::kCurrentTrialRecompute, temporary,
                     error)) {
      return false;
    }
    ++runtime_->current_linearization_temporary_builds;
    ++runtime_->current_linearization_borrows;
    runtime_->last_borrowed_layer_b_address = reinterpret_cast<uintptr_t>(
        temporary->borrowed_layer_b_address());
    *borrowed = temporary;
    return true;
  }

  void CommitPending(UndampedCurrentLinearization&& pending) noexcept {
    current_.Swap(pending);
    has_current_ = true;
    ++runtime_->current_linearization_publishes;
    ++runtime_->current_linearization_replacements;
    ++runtime_->current_linearization_invalidations;
  }

  const UndampedCurrentLinearization& current() const noexcept {
    return current_;
  }

  void Teardown() noexcept {
    current_ = UndampedCurrentLinearization();
    has_current_ = false;
    ++runtime_->current_linearization_teardowns;
  }

  bool ValidateLayerCConsume(
      const CudaLinearizationIdentity& expected,
      const UndampedCurrentLinearization& value) noexcept {
    ++runtime_->linearization_identity_checks;
    ++runtime_->solve_generation_consistency_checks;
    ++runtime_->topology_context_generation_checks;
    const bool identity_match = value.valid() &&
        SameLinearizationIdentity(expected, value.identity());
    const bool solve_match =
        value.identity().solve_generation == solve_generation_;
    const bool topology_match =
        value.identity().topology_generation == topology_generation_;
    if (!identity_match) ++runtime_->linearization_identity_violations;
    if (!solve_match) ++runtime_->solve_generation_consistency_violations;
    if (!topology_match)
      ++runtime_->topology_context_generation_violations;
    return identity_match && solve_match && topology_match;
  }

  bool ValidatePendingPublish(
      const CudaLinearizationIdentity& expected,
      const UndampedCurrentLinearization& value) noexcept {
    return ValidateLayerCConsume(expected, value);
  }

 private:
  bool ValidateIdentity(const CudaLinearizationIdentity& identity) noexcept {
    ++runtime_->linearization_identity_checks;
    ++runtime_->solve_generation_consistency_checks;
    ++runtime_->topology_context_generation_checks;
    const bool solve_match = identity.solve_generation == solve_generation_;
    const bool topology_match =
        identity.topology_generation == topology_generation_;
    if (!solve_match) {
      ++runtime_->solve_generation_consistency_violations;
      ++runtime_->linearization_identity_violations;
    }
    if (!topology_match) {
      ++runtime_->topology_context_generation_violations;
      ++runtime_->linearization_identity_violations;
    }
    return solve_match && topology_match;
  }

  bool cache_enabled_ = false;
  bool has_current_ = false;
  GpuBaSolveContext* context_ = nullptr;
  CudaFullLmRuntimeInfo* runtime_ = nullptr;
  LogicalFaultController* faults_ = nullptr;
  uint64_t solve_generation_ = 0;
  uint64_t topology_generation_ = 0;
  UndampedCurrentLinearization current_;
};

struct PendingAcceptedState {
  Snapshot next_state;
  bool has_host_state = true;
  UndampedCurrentLinearization next_linearization;
  DeviceCommitToken device_commit_token;
  std::string next_current_hash;
  CudaLmIteration prepared_iteration_trace;
  Snapshot accepted_state_trace_copy;
  bool has_accepted_state_trace_copy = false;
  double prepared_radius = 0.0;
  double prepared_decrease_factor = 2.0;
  uint64_t prepared_internal_state_epoch = 0;
  uint64_t prepared_legacy_state_epoch = 0;
  uint64_t prepared_linearization_id = 0;
  std::string prepared_linearization_reason;
};

static_assert(std::is_nothrow_move_constructible<Snapshot>::value &&
                  std::is_nothrow_move_assignable<Snapshot>::value,
              "Snapshot must support no-fail accepted-state transfer");
static_assert(std::is_nothrow_move_constructible<CudaLmIteration>::value &&
                  std::is_nothrow_move_assignable<CudaLmIteration>::value,
              "iteration trace must support no-fail transfer");
static_assert(
    std::is_nothrow_move_constructible<PendingAcceptedState>::value &&
        std::is_nothrow_move_assignable<PendingAcceptedState>::value,
    "PendingAcceptedState must support no-fail transfer");

void CommitAcceptedState(PendingAcceptedState&& pending,
                         const bool capture_state_trace,
                         StateHashController* state_hash,
                         GpuBaSolveContext* solve_context,
                         CurrentLinearizationController* linearizations,
                         CudaFullLmResult* result,
                         uint64_t* internal_state_epoch,
                         uint64_t* legacy_state_epoch,
                         CudaLinearizationIdentity* current_identity,
                         uint64_t* last_linearization_state_epoch,
                         bool* has_linearization,
                         uint64_t* linearization_id,
                         std::string* linearization_reason,
                         double* radius,
                         double* decrease_factor) noexcept {
  using std::swap;
  const CudaLinearizationIdentity committed_identity =
      pending.next_linearization.identity();
  if (pending.has_host_state) swap(result->final_state, pending.next_state);
  solve_context->CommitPersistentPending(
      std::move(pending.device_commit_token));
  linearizations->CommitPending(std::move(pending.next_linearization));
  state_hash->PromoteTrial(std::move(pending.next_current_hash));
  *internal_state_epoch = pending.prepared_internal_state_epoch;
  *legacy_state_epoch = pending.prepared_legacy_state_epoch;
  *current_identity = committed_identity;
  *last_linearization_state_epoch = pending.prepared_legacy_state_epoch;
  *has_linearization = true;
  *linearization_id = pending.prepared_linearization_id;
  linearization_reason->swap(pending.prepared_linearization_reason);
  *radius = pending.prepared_radius;
  *decrease_factor = pending.prepared_decrease_factor;
  ++result->accepted_steps;
  ++result->accepted_commits;
  if (capture_state_trace) {
    result->accepted_state_trace.push_back(
        std::move(pending.accepted_state_trace_copy));
  }
  result->trace.push_back(std::move(pending.prepared_iteration_trace));
}

void CommitAcceptedNativeState(
    PendingAcceptedState&& pending,
    GpuBaSolveContext* solve_context,
    CurrentLinearizationController* linearizations,
    CudaFullLmResult* result,
    uint64_t* internal_state_epoch,
    uint64_t* legacy_state_epoch,
    CudaLinearizationIdentity* current_identity,
    uint64_t* last_linearization_state_epoch,
    bool* has_linearization,
    uint64_t* linearization_id,
    std::string* linearization_reason,
    double* radius,
    double* decrease_factor) noexcept {
  const CudaLinearizationIdentity committed_identity =
      pending.next_linearization.identity();
  solve_context->CommitPersistentPending(std::move(pending.device_commit_token));
  linearizations->CommitPending(std::move(pending.next_linearization));
  *internal_state_epoch = pending.prepared_internal_state_epoch;
  *legacy_state_epoch = pending.prepared_legacy_state_epoch;
  *current_identity = committed_identity;
  *last_linearization_state_epoch = pending.prepared_legacy_state_epoch;
  *has_linearization = true;
  *linearization_id = pending.prepared_linearization_id;
  linearization_reason->swap(pending.prepared_linearization_reason);
  *radius = pending.prepared_radius;
  *decrease_factor = pending.prepared_decrease_factor;
  ++result->accepted_steps;
  ++result->accepted_commits;
  result->trace.push_back(std::move(pending.prepared_iteration_trace));
}

}  // namespace

bool RunCustomCudaSolveCore(const CudaSolveProblem* problem,
                            const Snapshot* legacy_snapshot,
                            const NativeCudaSolveRequest* native_request,
                            LegacyKernelInputBundle::Impl* native_bundle,
                            BaSolveResult* native_result,
                            const CudaFullLmOptions& options,
                            CudaFullLmResult* result,
                            std::string* error) {
  CudaCacheCallScope cache_scope;
  const bool native_mode = native_request != nullptr;
  if (result == nullptr || error == nullptr ||
      native_mode != (native_bundle != nullptr) ||
      native_mode != (native_result != nullptr) ||
      native_mode == (problem != nullptr) ||
      (native_mode && (native_request->view == nullptr ||
                       native_request->initial_state == nullptr))) {
    if (error != nullptr) *error = "custom CUDA controller source is invalid";
    return false;
  }
  *result = CudaFullLmResult();
  if (options.prepared_host_view != nullptr) {
    result->runtime.host_problem_store =
        options.prepared_host_view->runtime_info();
  }
  CudaArithmeticPrecision arithmetic_precision =
      CudaArithmeticPrecision::kFp64;
  if (!ResolveArithmeticPrecision(options.arithmetic_precision,
                                  &arithmetic_precision, error)) {
    result->error = *error;
    result->termination_reason = "invalid_arithmetic_precision";
    result->error_classification = CudaSolveErrorClass::kInvalidOptions;
    result->runtime.persistent_device.arithmetic_precision_requested =
        ArithmeticPrecisionName(options.arithmetic_precision);
    result->runtime.persistent_device.arithmetic_precision_effective =
        "invalid";
    return false;
  }
  if (native_mode && arithmetic_precision !=
                         native_request->view->config.arithmetic_precision) {
    *error = "native arithmetic precision identity mismatch";
    result->error = *error;
    return false;
  }
  if (arithmetic_precision != CudaArithmeticPrecision::kFp64 &&
      arithmetic_precision != CudaArithmeticPrecision::kFp32MixedStable) {
    result->runtime.audit_profile_requested =
        AuditProfileName(options.audit_profile);
    if (options.audit_profile != CudaAuditProfile::kCompatibilityDefault) {
      *error =
          "typed CUDA audit profiles require the fp64 or fp32_mixed main "
          "controller; legacy FP32 experiment paths are audit-unmanaged";
      result->runtime.audit_profile_effective = "unsupported";
      result->error = *error;
      result->termination_reason = "audit_unmanaged_precision_path";
      result->error_classification = CudaSolveErrorClass::kInvalidOptions;
      return false;
    }
    if (legacy_snapshot == nullptr || native_mode) {
      *error = "legacy FP32 experiment precision requires a legacy Snapshot";
      result->error = *error;
      result->termination_reason = "active_spec_legacy_fp32_unsupported";
      result->error_classification = CudaSolveErrorClass::kInvalidOptions;
      return false;
    }
    return RunCustomCudaFp32Experimental(*legacy_snapshot, options,
                                         arithmetic_precision, result, error);
  }
  const bool mixed_precision =
      arithmetic_precision == CudaArithmeticPrecision::kFp32MixedStable;
  result->runtime.persistent_device.arithmetic_precision_requested =
      ArithmeticPrecisionName(options.arithmetic_precision);
  result->runtime.persistent_device.arithmetic_precision_effective =
      mixed_precision ? "fp32_mixed" : "fp64";
  result->runtime.persistent_device.state_storage_precision = "fp64";
  result->runtime.persistent_device.residual_jacobian_precision =
      mixed_precision ? "fp64_geometry_fp32_records" : "fp64";
  result->runtime.persistent_device.hessian_schur_precision =
      mixed_precision
          ? "fp32_hessian_fp32_products_fp64_dense_schur"
          : "fp64";
  result->runtime.persistent_device.factorization_routine =
      "cusolverDnDpotrf/Dpotrs";
  result->runtime.persistent_device.delta_precision = "fp64";
  result->runtime.persistent_device.quaternion_plus_precision = "fp64";
  result->runtime.persistent_device.cost_precision = "fp64";
  result->runtime.persistent_device.controller_precision = "fp64";
  result->runtime.persistent_device.hessian_precision =
      mixed_precision ? "fp32" : "fp64";
  result->runtime.persistent_device.residual_jacobian_operand_source =
      mixed_precision ? "fp64_geometry_cast" : "fp64_native";
  result->runtime.persistent_device.gradient_operand_precision = "fp64";
  result->runtime.persistent_device.gradient_accumulation_precision = "fp64";
  result->runtime.persistent_device.point_inverse_precision = "fp64";
  result->runtime.persistent_device.schur_contribution_precision =
      mixed_precision ? "fp32_products_fp32_partials_fp64_merge" : "fp64";
  result->runtime.persistent_device.dense_factorization_precision = "fp64";
  CudaAuditProfile audit_profile = CudaAuditProfile::kCompatibilityDefault;
  bool capture_state_trace = false;
  bool instrumentation_enabled = false;
  bool audit_mirror_enabled = false;
  result->runtime.audit_profile_requested =
      AuditProfileName(options.audit_profile);
  if (!ResolveAuditProfile(options, &audit_profile, &capture_state_trace,
                           &instrumentation_enabled, &audit_mirror_enabled,
                           error)) {
    result->runtime.audit_profile_effective = "invalid";
    result->error = *error;
    result->termination_reason = "invalid_audit_profile";
    result->error_classification = CudaSolveErrorClass::kInvalidOptions;
    return false;
  }
  if (native_mode &&
      (audit_profile != CudaAuditProfile::kProduction ||
       capture_state_trace || instrumentation_enabled || audit_mirror_enabled ||
       options.fault_injection != CudaFaultInjection::kNone ||
       options.fault_trigger.fault_kind != CudaFaultInjection::kNone)) {
    *error = "native CUDA vertical slice requires production audit without faults";
    result->error = *error;
    result->termination_reason = "native_audit_configuration_unsupported";
    return false;
  }
  result->runtime.audit_profile_effective = AuditProfileName(audit_profile);
  result->runtime.capture_state_trace_effective = capture_state_trace;
  RuntimeAuditFinalizer runtime_audit_finalizer(
      result, error, instrumentation_enabled);
  CudaAuditRuntimeScope audit_runtime_scope(&result->runtime,
                                             options.fault_trigger);
  InstrumentationControlScope instrumentation_scope(instrumentation_enabled);
  TimingLedgerScope timing_scope(&result->runtime.timing);
  CudaSolveCallCounters solve_call_counters;
  SolveCallCounterScope call_counter_scope(&solve_call_counters);
  GpuBaSolveContext solve_context;
  solve_context.SetArithmeticPrecisionForSolve(arithmetic_precision);
  if (native_mode && (options.prepared_host_view != nullptr ||
                      options.indexed_active_solve != nullptr ||
                      options.indexed_catalog_tables != nullptr)) {
    *error = "native request cannot bind legacy prepared/indexed inputs";
    result->error = *error;
    return false;
  }
  if (options.prepared_host_view != nullptr &&
      options.indexed_active_solve != nullptr) {
    *error = "prepared host view and indexed active solve are mutually exclusive";
    result->error = *error;
    result->termination_reason = "conflicting_problem_sources";
    result->error_classification = CudaSolveErrorClass::kInvalidOptions;
    return false;
  }
  std::string device_context_backend;
  if (options.device_context_mode ==
      CudaDeviceContextMode::kCompatibilityDefault) {
    const char* device_context_environment =
        std::getenv("COLMAP_PCD_GPU_BA_DEVICE_CONTEXT");
    device_context_backend =
        device_context_environment == nullptr ? "legacy"
                                              : device_context_environment;
  } else {
    switch (options.device_context_mode) {
      case CudaDeviceContextMode::kLegacy:
        device_context_backend = "legacy";
        break;
      case CudaDeviceContextMode::kPersistent:
        device_context_backend = "persistent";
        break;
      case CudaDeviceContextMode::kDeviceState:
        device_context_backend = "device_state";
        break;
      case CudaDeviceContextMode::kDeviceControl:
        device_context_backend = "device_control";
        break;
      case CudaDeviceContextMode::kCompatibilityDefault:
        break;
    }
  }
  CudaDeviceContextBackend device_backend = CudaDeviceContextBackend::kLegacy;
  if (device_context_backend == "persistent") {
    device_backend = CudaDeviceContextBackend::kPersistent;
  } else if (device_context_backend == "device_state") {
    device_backend = CudaDeviceContextBackend::kDeviceState;
  } else if (device_context_backend == "device_control") {
    device_backend = CudaDeviceContextBackend::kDeviceControl;
  }
  const bool persistent_device =
      device_backend != CudaDeviceContextBackend::kLegacy;
  if (native_mode && device_backend != CudaDeviceContextBackend::kDeviceControl) {
    *error = "native CUDA vertical slice requires device_control";
    result->error = *error;
    return false;
  }
  HotKernelImplementation hot_kernel_implementation =
      HotKernelImplementation::kReference;
  if (!ResolveHotKernelImplementation(
          options.hot_kernel_mode,
          device_backend == CudaDeviceContextBackend::kDeviceControl, false,
          &hot_kernel_implementation, error)) {
    result->error = *error;
    result->termination_reason = "invalid_hot_kernel_implementation";
    result->error_classification = CudaSolveErrorClass::kInvalidOptions;
    return false;
  }
  CudaSchurContributionBackend schur_contribution_backend =
      CudaSchurContributionBackend::kDirectTransformed;
  std::string schur_contribution_requested;
  if (!ResolveSchurContributionBackend(
          options.layer_c.schur_contribution_backend,
          &schur_contribution_backend, &schur_contribution_requested,
          error)) {
    result->error = *error;
    result->termination_reason = "invalid_schur_contribution_backend";
    result->error_classification = CudaSolveErrorClass::kInvalidOptions;
    return false;
  }
  result->runtime.persistent_device.schur_contribution_backend_requested =
      schur_contribution_requested;
  result->runtime.persistent_device.schur_contribution_backend_effective =
      SchurContributionBackendName(schur_contribution_backend);
  if (schur_contribution_backend ==
          CudaSchurContributionBackend::kSegmentedTransformed &&
      hot_kernel_implementation != HotKernelImplementation::kTransformed) {
    *error = "segmented Schur contribution requires transformed hot kernels";
    result->error = *error;
    result->termination_reason = "invalid_schur_contribution_backend";
    result->error_classification = CudaSolveErrorClass::kInvalidOptions;
    return false;
  }
  if (native_mode) {
    const NativeCudaResolvedConfig& config = native_request->view->config;
    CudaReductionMode effective_reduction =
        options.layer_c.layer_b.reduction_mode;
    int32_t effective_cost_reduction_threads =
        options.layer_c.layer_b.cost_reduction_threads;
    if (options.performance_mode) {
      effective_reduction = CudaReductionMode::kParallelDeterministic;
      if (effective_cost_reduction_threads <= 1)
        effective_cost_reduction_threads = 128;
    }
    CudaHessianAssemblyBackend resolved_hessian =
        CudaHessianAssemblyBackend::kCompatibilityDefault;
    std::string hessian_requested;
    if (!config.resolved || config.config_generation == 0 ||
        !ResolveHessianAssemblyBackend(
            options.layer_c.layer_b.hessian_assembly_backend,
            hot_kernel_implementation, &resolved_hessian, &hessian_requested,
            error) ||
        options.performance_mode != config.performance_mode ||
        resolved_hessian != config.hessian_backend ||
        schur_contribution_backend != config.schur_backend ||
        options.hot_kernel_mode != config.hot_kernel ||
        options.execution_profile != config.execution_profile ||
        options.device_context_mode != config.device_context ||
        options.layer_c.layer_b.layer_a.memory_mode != config.memory_mode ||
        options.layer_c.layer_b.layer_a.device != config.device ||
        options.layer_c.layer_b.layer_a.block_size != config.block_size ||
        effective_reduction != config.reduction_mode ||
        effective_cost_reduction_threads !=
            config.cost_reduction_threads ||
        options.layer_c.layer_b.layer_a.residual_order !=
            config.residual_order ||
        options.layer_c.layer_b.loss_mode != config.loss_mode ||
        (config.loss_mode != CudaLossMode::kTrivial &&
         options.layer_c.layer_b.loss_scale != config.loss_scale) ||
        options.layer_c.layer_b.min_lm_diagonal != config.min_lm_diagonal ||
        options.layer_c.layer_b.max_lm_diagonal != config.max_lm_diagonal ||
        options.pair_chunk_limit_bytes_for_testing !=
            config.pair_chunk_limit_bytes ||
        options.layer_c.layer_b.hessian_segment_size_for_testing !=
            config.hessian_segment_size ||
        options.layer_c.schur_segment_size_for_testing !=
            config.schur_segment_size ||
        options.current_linearization_cache_mode !=
            config.linearization_cache ||
        options.audit_profile != config.audit_profile ||
        (options.max_num_iterations >= 0 &&
         options.max_num_iterations != config.max_num_iterations) ||
        (options.max_num_consecutive_invalid_steps >= 0 &&
         options.max_num_consecutive_invalid_steps !=
             config.max_consecutive_invalid_steps) ||
        (options.function_tolerance >= 0.0 &&
         options.function_tolerance != config.function_tolerance) ||
        (options.gradient_tolerance >= 0.0 &&
         options.gradient_tolerance != config.gradient_tolerance) ||
        (options.parameter_tolerance >= 0.0 &&
         options.parameter_tolerance != config.parameter_tolerance) ||
        options.max_solver_time_in_seconds !=
            config.max_solver_time_in_seconds ||
        options.initial_trust_region_radius !=
            config.initial_trust_region_radius ||
        options.min_trust_region_radius != config.min_trust_region_radius ||
        options.max_trust_region_radius != config.max_trust_region_radius ||
        options.min_relative_decrease != config.min_relative_decrease) {
      if (error->empty()) *error = "native resolved configuration mismatch";
      result->error = *error;
      result->termination_reason = "native_resolved_configuration_mismatch";
      result->error_classification = CudaSolveErrorClass::kInvalidOptions;
      return false;
    }
    if (!ProfileAtLeast(config.execution_profile,
                        CudaExecutionProfile::kCompactControl)) {
      *error = "native CUDA vertical slice requires compact_control";
      result->error = *error;
      return false;
    }
  }
  if (!native_mode && options.indexed_active_solve != nullptr) {
    CudaHessianAssemblyBackend indexed_hessian_backend =
        CudaHessianAssemblyBackend::kCompatibilityDefault;
    std::string indexed_hessian_requested;
    CudaLossMode indexed_loss_mode = CudaLossMode::kFromSnapshot;
    double indexed_loss_scale = 0.0;
    CudaHotKernelMode indexed_hot_kernel =
        CudaHotKernelMode::kCompatibilityDefault;
    switch (hot_kernel_implementation) {
      case HotKernelImplementation::kReference:
        indexed_hot_kernel = CudaHotKernelMode::kReference;
        break;
      case HotKernelImplementation::kOptimized:
        indexed_hot_kernel = CudaHotKernelMode::kOptimized;
        break;
      case HotKernelImplementation::kTransformed:
        indexed_hot_kernel = CudaHotKernelMode::kTransformed;
        break;
    }
    if (!ResolveHessianAssemblyBackend(
            options.layer_c.layer_b.hessian_assembly_backend,
            hot_kernel_implementation, &indexed_hessian_backend,
            &indexed_hessian_requested, error) ||
        !ResolveCudaLoss(*problem, options.layer_c.layer_b,
                         &indexed_loss_mode, &indexed_loss_scale, error) ||
        !solve_context.SetIndexedCatalogForSolve(
            options.indexed_catalog_tables, options.indexed_active_solve,
            arithmetic_precision, indexed_hessian_backend,
            schur_contribution_backend, indexed_hot_kernel,
            options.execution_profile, indexed_loss_mode, indexed_loss_scale,
            error)) {
      result->error = *error;
      result->termination_reason = "invalid_indexed_catalog_binding";
      result->error_classification = CudaSolveErrorClass::kInvalidOptions;
      return false;
    }
  } else if (!native_mode && !solve_context.SetIndexedCatalogForSolve(
                 options.indexed_catalog_tables, nullptr,
                 arithmetic_precision,
                 CudaHessianAssemblyBackend::kCompatibilityDefault,
                 schur_contribution_backend,
                 CudaHotKernelMode::kCompatibilityDefault,
                 options.execution_profile, CudaLossMode::kFromSnapshot, 0.0,
                 error)) {
    result->error = *error;
    result->termination_reason = "invalid_indexed_catalog_binding";
    result->error_classification = CudaSolveErrorClass::kInvalidOptions;
    return false;
  }
  result->runtime.device_context_backend = device_context_backend;
  result->runtime.persistent_device.requested = persistent_device;
  result->runtime.instrumentation_effective = instrumentation_enabled;
  result->runtime.performance_mode_requested = options.performance_mode;
  result->runtime.fault_record_capacity =
      options.audit_fault_record_capacity_for_testing == 0
          ? kCudaFaultRecordCapacity
          : options.audit_fault_record_capacity_for_testing;
  result->runtime.secondary_diagnostic_capacity =
      options.audit_secondary_capacity_for_testing == 0
          ? kCudaSecondaryDiagnosticCapacity
          : options.audit_secondary_capacity_for_testing;
  result->runtime.resource_registry_capacity =
      options.audit_resource_registry_capacity_for_testing == 0
          ? kCudaResourceRegistryCapacity
          : options.audit_resource_registry_capacity_for_testing;
  result->runtime.max_open_timing_interval_capacity =
      options.audit_timing_interval_capacity_for_testing == 0
          ? kCudaMaxOpenTimingIntervalCapacity
          : options.audit_timing_interval_capacity_for_testing;
  error->clear();
  const auto host_start = std::chrono::steady_clock::now();
  StateHashController state_hash(instrumentation_enabled,
                                 &result->runtime.state_hash_audit);
  uint64_t last_linearization_state_epoch = 0;
  bool has_linearization = false;
  uint64_t state_epoch = 0;  // Legacy instrumentation-dependent epoch.
  uint64_t internal_state_epoch = 0;
  uint64_t linearization_id = 0;
  std::string linearization_reason;
  const auto observe_linearization = [&](const uint64_t epoch) {
    if (!instrumentation_enabled) return;
    if (!has_linearization) {
      linearization_id = 1;
      linearization_reason = "initial";
      has_linearization = true;
    } else if (last_linearization_state_epoch == epoch) {
      linearization_reason = "same_state_recompute";
    } else {
      ++linearization_id;
      linearization_reason = "new_state_relinearization";
    }
    last_linearization_state_epoch = epoch;
  };

  const int32_t max_iterations =
      options.max_num_iterations < 0
          ? (native_mode ? native_request->view->config.max_num_iterations
                         : problem->metadata.max_num_iterations)
          : options.max_num_iterations;
  const int32_t invalid_limit =
      options.max_num_consecutive_invalid_steps < 0
          ? (native_mode
                 ? native_request->view->config.max_consecutive_invalid_steps
                 : (problem->metadata.max_consecutive_invalid_steps > 0
                        ? problem->metadata.max_consecutive_invalid_steps
                        : 10))
          : options.max_num_consecutive_invalid_steps;
  const double function_tolerance =
      options.function_tolerance < 0.0
          ? (native_mode ? native_request->view->config.function_tolerance
                         : problem->metadata.function_tolerance)
          : options.function_tolerance;
  const double gradient_tolerance =
      options.gradient_tolerance < 0.0
          ? (native_mode ? native_request->view->config.gradient_tolerance
                         : problem->metadata.gradient_tolerance)
          : options.gradient_tolerance;
  const double parameter_tolerance =
      options.parameter_tolerance < 0.0
          ? (native_mode ? native_request->view->config.parameter_tolerance
                         : problem->metadata.parameter_tolerance)
          : options.parameter_tolerance;
  if (max_iterations < 0 || invalid_limit <= 0 ||
      (device_context_backend != "legacy" &&
       device_context_backend != "persistent" &&
       device_context_backend != "device_state" &&
       device_context_backend != "device_control") ||
      !std::isfinite(function_tolerance) || function_tolerance < 0.0 ||
      !std::isfinite(gradient_tolerance) || gradient_tolerance < 0.0 ||
      !std::isfinite(parameter_tolerance) || parameter_tolerance < 0.0 ||
      !std::isfinite(options.initial_trust_region_radius) ||
      !std::isfinite(options.min_trust_region_radius) ||
      !std::isfinite(options.max_trust_region_radius) ||
      options.initial_trust_region_radius <= 0.0 ||
      options.min_trust_region_radius < 0.0 ||
      options.max_trust_region_radius <= 0.0 ||
      options.min_trust_region_radius > options.initial_trust_region_radius ||
      options.initial_trust_region_radius > options.max_trust_region_radius ||
      !std::isfinite(options.max_solver_time_in_seconds) ||
      options.max_solver_time_in_seconds <= 0.0 ||
      !std::isfinite(options.min_relative_decrease) ||
      options.min_relative_decrease < 0.0) {
    *error = (device_context_backend != "legacy" &&
              device_context_backend != "persistent" &&
              device_context_backend != "device_state" &&
              device_context_backend != "device_control")
                 ? "COLMAP_PCD_GPU_BA_DEVICE_CONTEXT must be legacy, persistent, device_state, or device_control"
                 : "custom_cuda full-LM options are invalid";
    result->error_classification = CudaSolveErrorClass::kInvalidOptions;
    result->error = *error;
    return false;
  }
  constexpr int32_t kMaximumReservedIterations = 1000000;
  if (max_iterations > kMaximumReservedIterations) {
    *error = "custom_cuda max_num_iterations exceeds bounded trace capacity";
    result->error_classification = CudaSolveErrorClass::kInvalidOptions;
    result->error = *error;
    return false;
  }
  const size_t trace_capacity = static_cast<size_t>(max_iterations) + 1;
  if (trace_capacity < static_cast<size_t>(max_iterations) ||
      trace_capacity > result->trace.max_size() ||
      (capture_state_trace &&
       trace_capacity > result->accepted_state_trace.max_size())) {
    *error = "custom_cuda trace reserve size overflow";
    result->error_classification = CudaSolveErrorClass::kInvalidOptions;
    result->error = *error;
    return false;
  }
  std::string prepared_cleanup_error;
  try {
    result->trace.reserve(trace_capacity);
    if (capture_state_trace)
      result->accepted_state_trace.reserve(trace_capacity);
    result->runtime.current_linearization_builds_by_state_epoch.assign(
        trace_capacity, 0);
    result->error.reserve(512);
    result->termination_reason.reserve(128);
    error->reserve(512);
    prepared_cleanup_error.reserve(512);
  } catch (const std::exception& exception) {
    *error = std::string("custom_cuda audit reserve failed: ") +
             exception.what();
    result->error_classification = CudaSolveErrorClass::kInvalidOptions;
    result->error = *error;
    return false;
  }

  uint64_t required_fault_records = 0;
  if (options.fault_trigger.fault_kind != CudaFaultInjection::kNone) {
    if (trace_capacity >
        (std::numeric_limits<uint64_t>::max() - 4) / 12) {
      required_fault_records = std::numeric_limits<uint64_t>::max();
    } else {
      // Every accepted trial may check current lookup, three Layer C sites,
      // pending preparation, and all three pending-build phases. The 12x
      // bound also covers initial-build checks and failure-path retries.
      required_fault_records =
          12 * static_cast<uint64_t>(trace_capacity) + 4;
    }
  }
  uint64_t required_resource_registry_capacity = 0;
  if (trace_capacity >
      std::numeric_limits<uint64_t>::max() / 256u - 1u) {
    required_resource_registry_capacity =
        std::numeric_limits<uint64_t>::max();
  } else {
    // One trial currently creates fewer than 64 ownership records with
    // instrumentation disabled. The 4x bound also covers all timing events,
    // partial-failure cleanup, and initial/final linearizations without
    // relying on allocator growth after CUDA resources exist.
    required_resource_registry_capacity =
        256u * (static_cast<uint64_t>(trace_capacity) + 1u);
  }
  constexpr uint64_t kRequiredOpenTimingIntervals = 8;
  const bool audit_capacity_valid =
      result->runtime.fault_record_capacity <=
          result->runtime.fault_consumptions.size() &&
      result->runtime.secondary_diagnostic_capacity <=
          result->runtime.diagnostic_structure_v2.secondary.size() &&
      result->runtime.resource_registry_capacity <=
          kCudaResourceRegistryCapacity &&
      result->runtime.max_open_timing_interval_capacity <=
          kCudaMaxOpenTimingIntervalCapacity &&
      result->runtime.fault_record_capacity >= required_fault_records &&
      result->runtime.secondary_diagnostic_capacity >= 1 &&
      result->runtime.resource_registry_capacity >=
          required_resource_registry_capacity &&
      result->runtime.max_open_timing_interval_capacity >=
          kRequiredOpenTimingIntervals;
  if (!audit_capacity_valid) {
    result->error_classification = CudaSolveErrorClass::kAuditCapacity;
    result->termination_type = CudaTerminationType::kFailure;
    result->termination_reason = "audit_capacity_preflight_failed";
    result->error = "AUDIT_CAPACITY: preflight capacity is insufficient";
    *error = result->error;
    RecordDiagnostic(
        &result->runtime,
        MakeDiagnostic(CudaSolveErrorClass::kAuditCapacity,
                       CudaFailureSite::kAuditPreflightCapacity,
                       CudaStatusDomain::kInternal, 1));
    return false;
  }
  result->runtime.audit_capacity_preflight_pass = true;

  try {
    if (!native_mode) {
      static_cast<CudaSolveProblem&>(result->final_state) = *problem;
    }
    if (!native_mode && legacy_snapshot != nullptr) {
      result->final_state.tracks = legacy_snapshot->tracks;
      result->final_state.parameter_blocks_canonical_order =
          legacy_snapshot->parameter_blocks_canonical_order;
    }
    if (!native_mode &&
        (!state_hash.Initialize(result->final_state, error) ||
         !state_hash.Current(result->final_state,
                            &result->runtime.initial_state_hash, error))) {
      result->error_classification = CudaSolveErrorClass::kFinalStateHash;
      result->error = *error;
      return false;
    }
    g_cuda_buffer_cache.reserve(
        static_cast<size_t>(result->runtime.resource_registry_capacity));
    g_cuda_live_allocations.reserve(
        static_cast<size_t>(result->runtime.resource_registry_capacity));
    g_cached_streams.reserve(16);
    g_cached_events.reserve(32);
    g_cached_solvers.reserve(8);
    g_cached_blases.reserve(8);
  } catch (const std::exception&) {
    result->error_classification = CudaSolveErrorClass::kAuditCapacity;
    result->termination_type = CudaTerminationType::kFailure;
    result->termination_reason = "audit_preflight_allocation_failed";
    result->error = "AUDIT_CAPACITY: preflight allocation failed";
    *error = result->error;
    RecordDiagnostic(
        &result->runtime,
        MakeDiagnostic(CudaSolveErrorClass::kAuditCapacity,
                       CudaFailureSite::kAuditPreflightCapacity,
                       CudaStatusDomain::kCxxException, 2));
    return false;
  }

  const bool runtime_pool_enabled =
      ProfileAtLeast(options.execution_profile,
                     CudaExecutionProfile::kRuntimePool) &&
      persistent_device;
  // A healthy idle RuntimePool entry may coexist with a baseline persistent
  // solve in the same process. Only runtime_pool_enabled controls lease use;
  // registry retention merely prevents the baseline generation from
  // misclassifying another profile's idle runtime resources as a leak.
  if (!BeginCudaResourceGeneration(&result->runtime, persistent_device,
                                   error)) {
    result->error_classification = CudaSolveErrorClass::kResourceCleanup;
    result->error = *error;
    result->termination_reason = *error;
    RecordDiagnostic(
        &result->runtime,
        MakeDiagnostic(CudaSolveErrorClass::kResourceCleanup,
                       CudaFailureSite::kCleanupGetDevice,
                       CudaStatusDomain::kInternal, 1));
    return false;
  }
  if (options.fault_trigger.fault_kind ==
      CudaFaultInjection::kForceResourceDoubleAdvance) {
    if (BeginCudaResourceGeneration(&result->runtime, persistent_device,
                                    error)) {
      result->error_classification = CudaSolveErrorClass::kResourceCleanup;
      result->termination_type = CudaTerminationType::kFailure;
      result->termination_reason = "resource_generation_double_advance";
      result->error = "resource generation double advance was not rejected";
      *error = result->error;
      return false;
    }
    prepared_cleanup_error.clear();
    TaintAndClearCudaResources(false, &result->runtime,
                               &prepared_cleanup_error);
    result->error_classification = CudaSolveErrorClass::kResourceCleanup;
    result->termination_type = CudaTerminationType::kFailure;
    result->termination_reason = "resource_generation_double_advance";
    result->error = "CUDA_RESOURCE_GENERATION_DOUBLE_ADVANCE";
    *error = result->error;
    RecordDiagnostic(
        &result->runtime,
        MakeDiagnostic(CudaSolveErrorClass::kResourceCleanup,
                       CudaFailureSite::kResourceGenerationDoubleAdvance,
                       CudaStatusDomain::kInternal, 1));
    return false;
  }
  HostPhaseScope controller_self(CUDA_TIMING_PHASE(controller_self));
  CudaBufferReuseScope buffer_reuse_scope(
      options.performance_mode && !persistent_device);
  if (!buffer_reuse_scope.acquired()) {
    *error = buffer_reuse_scope.error();
    result->error = *error;
    return false;
  }

  CudaLayerCOptions step_options = options.layer_c;
  step_options.pair_chunk_limit_bytes_for_testing =
      options.pair_chunk_limit_bytes_for_testing;
  step_options.layer_b.layer_a.residual_order = native_mode
      ? native_request->view->config.residual_order
      : CudaResidualOrder::kSourceInsertion;
  if (options.performance_mode) {
    step_options.layer_b.reduction_mode =
        CudaReductionMode::kParallelDeterministic;
    if (step_options.layer_b.cost_reduction_threads <= 1)
      step_options.layer_b.cost_reduction_threads = 128;
  }
  result->runtime.effective_reduction_mode =
      step_options.layer_b.reduction_mode;
  if (options.fault_injection ==
      CudaFaultInjection::kForcePointFactorizationFailure) {
    step_options.fault_injection =
        CudaFaultInjection::kForcePointFactorizationFailure;
  }
  const bool device_control_audit_mirror =
      device_backend == CudaDeviceContextBackend::kDeviceControl &&
      audit_mirror_enabled;
  const auto solve_context_initialization_start =
      std::chrono::steady_clock::now();
  const PreparedHostSolveViewData* prepared_host_data =
      options.prepared_host_view == nullptr
          ? nullptr
          : options.prepared_host_view->data_for_internal_use();
  if (options.prepared_host_view != nullptr && prepared_host_data == nullptr) {
    *error = "prepared host solve view is invalid";
    result->error_classification = CudaSolveErrorClass::kInitialLinearization;
    result->error = *error;
    return false;
  }
  const bool context_initialized = native_mode
      ? solve_context.InitializeNative(
            *native_request->view, *native_request->initial_state,
            *native_bundle, step_options.layer_b,
            result->runtime.resource_generation, hot_kernel_implementation,
            &result->runtime, error)
      : prepared_host_data == nullptr
      ? solve_context.Initialize(
            result->final_state, step_options.layer_b,
            step_options.pair_chunk_limit_bytes_for_testing,
            result->runtime.resource_generation, true, device_backend,
            hot_kernel_implementation, schur_contribution_backend,
            step_options.schur_segment_size_for_testing,
            options.execution_profile, device_control_audit_mirror,
            &result->runtime, error)
      : solve_context.InitializeFromPreparedHostView(
            result->final_state, step_options.layer_b,
            step_options.pair_chunk_limit_bytes_for_testing,
            result->runtime.resource_generation, device_backend,
            hot_kernel_implementation, schur_contribution_backend,
            step_options.schur_segment_size_for_testing,
            options.execution_profile, device_control_audit_mirror,
            &result->runtime, *prepared_host_data, error);
  if (!context_initialized) {
    result->error_classification = CudaSolveErrorClass::kInitialLinearization;
    result->error = *error;
    return false;
  }
  result->runtime.persistent_device
      .solve_context_initialization_wall_milliseconds +=
      std::chrono::duration<double, std::milli>(
          std::chrono::steady_clock::now() -
          solve_context_initialization_start)
          .count();
  LogicalFaultController logical_faults(options.fault_trigger,
                                         &result->runtime);
  CudaLinearizationIdentity current_identity;
  current_identity.solve_generation = solve_context.solve_generation();
  current_identity.state_epoch = 0;
  current_identity.topology_generation = solve_context.topology_generation();
  current_identity.config_generation = 0;
  result->runtime.final_solve_generation = current_identity.solve_generation;
  result->runtime.final_topology_generation =
      current_identity.topology_generation;
  ++result->runtime.solve_generation_nonzero_checks;
  if (current_identity.solve_generation == 0) {
    ++result->runtime.solve_generation_nonzero_violations;
  }
  CurrentLinearizationController linearizations(
      options.current_linearization_cache_mode, &solve_context,
      &result->runtime,
      &logical_faults, current_identity.solve_generation,
      current_identity.topology_generation);
  observe_linearization(state_epoch);
  UndampedCurrentLinearization initial_linearization;
  const bool initial_linearization_built = native_mode
      ? linearizations.BuildNative(
            current_identity, step_options.layer_b,
            CudaFaultLogicalSite::kInitialLinearization,
            &initial_linearization, error)
      : linearizations.Build(
            result->final_state, current_identity, step_options.layer_b,
            CudaFaultLogicalSite::kInitialLinearization,
            &initial_linearization, error);
  if (!initial_linearization_built) {
    result->error_classification = CudaSolveErrorClass::kInitialLinearization;
    result->error = *error;
    return false;
  }
  result->runtime.cross_solve_cache_hits = 0;
  const bool device_scaling_profile = ProfileAtLeast(
      options.execution_profile, CudaExecutionProfile::kDeviceScaling) &&
      device_backend == CudaDeviceContextBackend::kDeviceControl;
  if (device_scaling_profile) {
    if (!solve_context.PublishPersistentFrozenScalingFromInitial(
            initial_linearization.device_token(), current_identity, error)) {
      result->error_classification =
          CudaSolveErrorClass::kInitialLinearization;
      result->error = *error;
      return false;
    }
    step_options.layer_b.device_frozen_jacobi_scaling = true;
    current_identity.config_generation = NextMathematicalGeneration();
  } else {
    CaptureFrozenJacobiScaling(initial_linearization.layer_b(),
                               &step_options.layer_b);
    current_identity.config_generation = native_mode
        ? native_request->view->identity.config_generation
        : ComputeConfigGeneration(result->final_state, step_options.layer_b);
  }
  if (!solve_context.FinalizeResolvedConfig(
          current_identity.config_generation, error)) {
    result->error_classification = CudaSolveErrorClass::kInitialLinearization;
    result->error = *error;
    return false;
  }
  if (!device_scaling_profile &&
      !solve_context.UploadPersistentFrozenScaling(step_options.layer_b,
                                                    error)) {
    result->error_classification = CudaSolveErrorClass::kInitialLinearization;
    result->error = *error;
    return false;
  }
  initial_linearization.RebindIdentityForBootstrap(current_identity);
  if (!linearizations.ValidatePendingPublish(current_identity,
                                              initial_linearization) ||
      !solve_context.ValidateDeviceLinearizationBinding(
          initial_linearization, error)) {
    result->error_classification = CudaSolveErrorClass::kInitialLinearization;
    result->termination_type = CudaTerminationType::kFailure;
    result->termination_reason = "initial_linearization_identity_mismatch";
    result->error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
    *error = result->error;
    return false;
  }
  AccumulateLayerBRuntime(initial_linearization.layer_b(), &result->runtime);
  linearizations.PublishInitial(std::move(initial_linearization));
  solve_context.PublishPersistentInitial(current_identity);
  const CudaLayerBResult* current = &linearizations.current().layer_b();

  double radius = options.initial_trust_region_radius;
  double decrease_factor = 2.0;
  int32_t consecutive_invalid_steps = 0;
  result->initial_cost = current->cost;
  result->initial_projected_gradient_max_norm =
      current->projected_gradient_max_norm;
  result->initial_scaled_gradient_norm = current->scaled_gradient_max_norm;
  result->accepted_steps = 1;  // Ceres summary includes iteration 0.

  CudaLmIteration iteration_zero;
  iteration_zero.iteration = 0;
  iteration_zero.cost_before = current->cost;
  iteration_zero.trial_cost = current->cost;
  iteration_zero.cost_after = current->cost;
  iteration_zero.projected_gradient_max_norm =
      current->projected_gradient_max_norm;
  iteration_zero.scaled_gradient_norm = current->scaled_gradient_max_norm;
  iteration_zero.radius_before = radius;
  iteration_zero.radius_after = radius;
  iteration_zero.lambda_before = 1.0 / radius;
  iteration_zero.lambda_after = 1.0 / radius;
  iteration_zero.factorization_success = true;
  iteration_zero.step_valid = true;
  iteration_zero.trial_finite = true;
  iteration_zero.accepted_decision = true;
  iteration_zero.accepted_commit_success = true;
  iteration_zero.accepted = true;
  if (!native_mode &&
      !state_hash.Current(result->final_state,
                          &iteration_zero.current_state_hash, error)) {
    result->error = *error;
    return false;
  }
  iteration_zero.trial_state_hash = iteration_zero.current_state_hash;
  iteration_zero.state_epoch = state_epoch;
  iteration_zero.linearization_id = linearization_id;
  iteration_zero.linearization_reason = linearization_reason;
  const LifecycleCounters initial_counters =
      ReadLifecycleCounters(result->runtime.timing);
  iteration_zero.cumulative_layer_a_calls = initial_counters.layer_a;
  iteration_zero.cumulative_layer_b_calls = initial_counters.layer_b;
  iteration_zero.cumulative_layer_c_calls = initial_counters.layer_c;
  iteration_zero.cumulative_cost_calls = initial_counters.cost;
  iteration_zero.cumulative_topology_builds = initial_counters.topology_build;
  iteration_zero.cumulative_topology_refreshes =
      initial_counters.topology_refresh;
  iteration_zero.cumulative_cache_hits = initial_counters.cache_hit;
  result->trace.push_back(iteration_zero);
  if (!native_mode && capture_state_trace) {
    result->accepted_state_trace.push_back(result->final_state);
  }

  const auto elapsed_seconds = [&]() {
    return std::chrono::duration<double>(std::chrono::steady_clock::now() -
                                         host_start)
        .count();
  };
  if (elapsed_seconds() >= options.max_solver_time_in_seconds) {
    result->termination_type = CudaTerminationType::kNoConvergence;
    result->termination_reason = "maximum_solver_time_at_iteration_0";
  } else if (max_iterations == 0) {
    result->termination_type = CudaTerminationType::kNoConvergence;
    result->termination_reason = "maximum_trial_iterations_at_iteration_0";
  } else if (current->projected_gradient_max_norm <= gradient_tolerance) {
    result->termination_type = CudaTerminationType::kConvergence;
    result->termination_reason = "gradient_tolerance_at_iteration_0";
  } else if (radius <= options.min_trust_region_radius) {
    result->termination_type = CudaTerminationType::kConvergence;
    result->termination_reason =
        "minimum_trust_region_radius_at_iteration_0";
  }

  while (result->termination_reason.empty()) {
    CudaLmIteration iteration;
    const LifecycleCounters counters_before =
        ReadLifecycleCounters(result->runtime.timing);
    std::string current_state_hash;
    if (!native_mode &&
        !state_hash.Current(result->final_state, &current_state_hash, error)) {
      result->termination_type = CudaTerminationType::kFailure;
      result->termination_reason = "current_state_hash_failed";
      result->error = *error;
      break;
    }
    UndampedCurrentLinearization temporary_linearization;
    const UndampedCurrentLinearization* borrowed_linearization = nullptr;
    const bool current_linearization_resolved = native_mode
        ? linearizations.ResolveNative(
              current_identity, step_options.layer_b,
              &temporary_linearization, &borrowed_linearization, error)
        : linearizations.Resolve(
              result->final_state, current_identity, step_options.layer_b,
              &temporary_linearization, &borrowed_linearization, error);
    if (!current_linearization_resolved) {
      result->termination_type = CudaTerminationType::kFailure;
      result->termination_reason = "current_linearization_failed";
      result->error_classification =
          CudaSolveErrorClass::kCurrentLinearization;
      result->error = *error;
      break;
    }
    if (options.current_linearization_cache_mode ==
        CudaCurrentLinearizationCacheMode::kDisabled) {
      observe_linearization(state_epoch);
      AccumulateLayerBRuntime(borrowed_linearization->layer_b(),
                              &result->runtime);
    }
    const CudaLayerBResult& iteration_current =
        borrowed_linearization->layer_b();
    iteration.iteration = result->trial_iterations + 1;
    iteration.cost_before = iteration_current.cost;
    iteration.cost_after = iteration_current.cost;
    iteration.trial_cost = iteration_current.cost;
    iteration.projected_gradient_max_norm =
        iteration_current.projected_gradient_max_norm;
    iteration.scaled_gradient_norm = iteration_current.scaled_gradient_max_norm;
    iteration.radius_before = radius;
    iteration.radius_after = radius;
    iteration.lambda_before = 1.0 / radius;
    iteration.lambda_after = iteration.lambda_before;
    iteration.current_state_hash = current_state_hash;
    iteration.state_epoch = state_epoch;
    iteration.linearization_id = linearization_id;
    iteration.linearization_reason = linearization_reason;
    ComputeLmDiagonalRange(iteration_current, radius,
                           &iteration.lm_diagonal_min,
                           &iteration.lm_diagonal_max);
    const auto finalize_iteration_counters = [&]() {
      const LifecycleCounters after =
          ReadLifecycleCounters(result->runtime.timing);
      iteration.delta_layer_a_calls =
          CounterDelta(after.layer_a, counters_before.layer_a);
      iteration.delta_layer_b_calls =
          CounterDelta(after.layer_b, counters_before.layer_b);
      iteration.delta_layer_c_calls =
          CounterDelta(after.layer_c, counters_before.layer_c);
      iteration.delta_cost_calls =
          CounterDelta(after.cost, counters_before.cost);
      iteration.delta_topology_builds = CounterDelta(
          after.topology_build, counters_before.topology_build);
      iteration.delta_topology_refreshes = CounterDelta(
          after.topology_refresh, counters_before.topology_refresh);
      iteration.delta_cache_hits =
          CounterDelta(after.cache_hit, counters_before.cache_hit);
      iteration.delta_cache_lookups =
          CounterDelta(after.cache_lookup, counters_before.cache_lookup);
      iteration.delta_cache_misses =
          CounterDelta(after.cache_miss, counters_before.cache_miss);
      iteration.delta_cache_invalidations = CounterDelta(
          after.cache_invalidation, counters_before.cache_invalidation);
      iteration.cumulative_layer_a_calls = after.layer_a;
      iteration.cumulative_layer_b_calls = after.layer_b;
      iteration.cumulative_layer_c_calls = after.layer_c;
      iteration.cumulative_cost_calls = after.cost;
      iteration.cumulative_topology_builds = after.topology_build;
      iteration.cumulative_topology_refreshes = after.topology_refresh;
      iteration.cumulative_cache_hits = after.cache_hit;
    };

    CudaLayerCOptions trial_options = step_options;
    trial_options.lambda = iteration.lambda_before;
    const CudaFaultInjection point_fault = logical_faults.Consume(
        CudaFaultLogicalSite::kLayerCPointFactor,
        CudaFaultTriggerPhase::kLayerCOperation, 1, internal_state_epoch);
    const CudaFaultInjection workspace_fault = logical_faults.Consume(
        CudaFaultLogicalSite::kLayerCWorkspace,
        CudaFaultTriggerPhase::kLayerCOperation, 2, internal_state_epoch);
    const CudaFaultInjection trial_cost_fault = logical_faults.Consume(
        CudaFaultLogicalSite::kTrialCost,
        CudaFaultTriggerPhase::kLayerCOperation, 3, internal_state_epoch);
    if (point_fault == CudaFaultInjection::kForcePointFactorizationFailure)
      trial_options.fault_injection = point_fault;
    if (workspace_fault ==
        CudaFaultInjection::kForceWorkspaceAllocationFailure)
      trial_options.fault_injection = workspace_fault;
    CudaLayerCStepResult step;
    std::string step_error;
    if (!linearizations.ValidateLayerCConsume(current_identity,
                                              *borrowed_linearization)) {
      result->termination_type = CudaTerminationType::kFailure;
      result->termination_reason = "linearization_identity_mismatch";
      result->error_classification =
          CudaSolveErrorClass::kCurrentLinearization;
      result->error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
      *error = result->error;
      break;
    }
    const bool solved = native_mode
        ? RunCudaNativeLayerCFromContext(
              &solve_context, trial_options,
              borrowed_linearization->layer_b(), current_identity,
              borrowed_linearization->device_token(), &step, &step_error)
        : RunCudaSnapshotLayerCFromLinearization(
              &solve_context, result->final_state, trial_options,
              *borrowed_linearization, &step, &step_error);
    ++result->trial_iterations;
    iteration.factorization_success = solved;
    if ((options.fault_injection ==
             CudaFaultInjection::kForceNonfiniteTrial ||
         trial_cost_fault == CudaFaultInjection::kForceNonfiniteTrial) &&
        solved) {
      step.trial_cost = std::numeric_limits<double>::quiet_NaN();
    }
    if (!solved) {
      const bool factorization_failure =
          IsRecoverableFactorizationFailure(step_error);
      const bool nonfinite_trial_state =
          IsRecoverableNonfiniteTrialState(step_error);
      if (!factorization_failure && !nonfinite_trial_state) {
        result->termination_type = CudaTerminationType::kFailure;
        result->termination_reason = "cuda_step_failed: " + step_error;
        result->error_classification = CudaSolveErrorClass::kCudaStep;
        result->error = result->termination_reason;
        *error = result->error;
        iteration.trial_state_hash = current_state_hash;
        finalize_iteration_counters();
        result->trace.push_back(iteration);
        break;
      }
      if (factorization_failure) {
        ++result->factorization_failures;
      } else {
        // The dense solve completed, but applying its step overflowed the
        // trial state. Treat this like an invalid LM trial: retain the current
        // state and retry with stronger damping. Mapping errors remain fatal.
        iteration.factorization_success = true;
      }
      ++result->invalid_steps;
      ++consecutive_invalid_steps;
      iteration.invalid = true;
      iteration.accepted_decision = false;
      iteration.accepted_commit_success = false;
      iteration.trial_state_hash = current_state_hash;
      radius /= decrease_factor;
      decrease_factor *= 2.0;
      iteration.radius_after = radius;
      iteration.lambda_after = 1.0 / radius;
      finalize_iteration_counters();
      result->trace.push_back(iteration);
      if (consecutive_invalid_steps >= invalid_limit) {
        result->termination_type = CudaTerminationType::kFailure;
        result->termination_reason =
            "maximum_consecutive_invalid_steps: " + step_error;
        result->error = result->termination_reason;
        *error = result->error;
      } else if (elapsed_seconds() >= options.max_solver_time_in_seconds) {
        result->termination_type = CudaTerminationType::kNoConvergence;
        result->termination_reason = "maximum_solver_time";
      } else if (result->trial_iterations >= max_iterations) {
        result->termination_type = CudaTerminationType::kNoConvergence;
        result->termination_reason = "maximum_trial_iterations";
      } else if (radius <= options.min_trust_region_radius) {
        result->termination_type = CudaTerminationType::kConvergence;
        result->termination_reason = "minimum_trust_region_radius";
      }
      continue;
    }
    AccumulateLayerCRuntime(step, &result->runtime);
    consecutive_invalid_steps = 0;
    iteration.predicted_reduction = step.predicted_reduction;
    iteration.backward_error = step.backward_error;
    iteration.step_valid = std::isfinite(step.predicted_reduction) &&
                           step.predicted_reduction > 0.0;
    iteration.trial_cost = step.trial_cost;
    iteration.trial_finite = std::isfinite(step.trial_cost);
    if (!native_mode &&
        !state_hash.Trial(step.trial_state, &iteration.trial_state_hash,
                          error)) {
      solve_context.DiscardDeviceTrialState();
      result->termination_type = CudaTerminationType::kFailure;
      result->termination_reason = "trial_state_hash_failed";
      result->error_classification = CudaSolveErrorClass::kTrialStateHash;
      result->error = *error;
      finalize_iteration_counters();
      result->trace.push_back(iteration);
      break;
    }
    if (!iteration.step_valid || !iteration.trial_finite) {
      solve_context.DiscardDeviceTrialState();
      result->termination_type = CudaTerminationType::kFailure;
      result->termination_reason =
          "cuda_step_produced_nonfinite_or_nonpositive_model";
      result->error_classification = CudaSolveErrorClass::kNonfiniteModel;
      result->error = result->termination_reason;
      *error = result->error;
      finalize_iteration_counters();
      result->trace.push_back(iteration);
      break;
    }
    iteration.actual_reduction = iteration_current.cost - step.trial_cost;
    iteration.rho =
        iteration.actual_reduction / iteration.predicted_reduction;
    double state_norm = step.state_norm;
    if (!solve_context.device_control_enabled() ||
        solve_context.audit_mirror_enabled()) {
      if (!AmbientStateAndDifferenceNorm(result->final_state,
                                         &step.trial_state, iteration_current,
                                         &state_norm, &iteration.step_norm,
                                         error)) {
        solve_context.DiscardDeviceTrialState();
        result->termination_type = CudaTerminationType::kFailure;
        result->termination_reason = "cuda_step_norm_failed";
        result->error = *error;
        finalize_iteration_counters();
        result->trace.push_back(iteration);
        break;
      }
    } else {
      iteration.step_norm = step.step_norm;
    }
    if (!std::isfinite(state_norm) || !std::isfinite(iteration.step_norm)) {
      solve_context.DiscardDeviceTrialState();
      result->termination_type = CudaTerminationType::kFailure;
      result->termination_reason = "cuda_step_norm_failed";
      result->error = "device-control norm is non-finite";
      *error = result->error;
      finalize_iteration_counters();
      result->trace.push_back(iteration);
      break;
    }
    iteration.parameter_metric =
        iteration.step_norm / (state_norm + parameter_tolerance);
    iteration.function_metric =
        std::abs(iteration.actual_reduction) /
        std::max(iteration_current.cost, 1e-300);

    const double parameter_threshold =
        parameter_tolerance * (state_norm + parameter_tolerance);
    if (iteration.step_norm <= parameter_threshold) {
      solve_context.DiscardDeviceTrialState();
      result->termination_type = CudaTerminationType::kConvergence;
      result->termination_reason = "parameter_tolerance";
      finalize_iteration_counters();
      result->trace.push_back(iteration);
      break;
    }
    const double function_threshold =
        function_tolerance * iteration_current.cost;
    if (std::abs(iteration.actual_reduction) <= function_threshold) {
      solve_context.DiscardDeviceTrialState();
      result->termination_type = CudaTerminationType::kConvergence;
      result->termination_reason = "function_tolerance";
      finalize_iteration_counters();
      result->trace.push_back(iteration);
      break;
    }

    {
      HostPhaseScope lm_decision_timing(CUDA_TIMING_PHASE(lm_decision));
      iteration.accepted_decision = std::isfinite(iteration.rho) &&
                                    iteration.rho >
                                        options.min_relative_decrease;
      iteration.accepted = iteration.accepted_decision;
    }
    bool accepted_commit = false;
    if (iteration.accepted_decision) {
      ++result->accepted_decisions;
      PendingAcceptedState pending;
      const CudaFaultInjection preparation_fault = logical_faults.Consume(
          CudaFaultLogicalSite::kAcceptedPendingLinearization,
          CudaFaultTriggerPhase::kAcceptedPendingPreparation, 0,
          internal_state_epoch + 1);
      if (preparation_fault ==
          CudaFaultInjection::kForcePendingPreparationFailure) {
        solve_context.DiscardDeviceTrialState();
        ++result->accepted_pending_preparation_failures;
        result->termination_type = CudaTerminationType::kFailure;
        result->termination_reason =
            "accepted_state_pending_preparation_failed";
        result->error_classification =
            CudaSolveErrorClass::kAcceptedPendingPreparation;
        result->error = "pending accepted-state preparation failed";
        *error = result->error;
        RecordDiagnostic(
            &result->runtime,
            MakeDiagnostic(CudaSolveErrorClass::kAcceptedPendingPreparation,
                           CudaFailureSite::kPendingPreparation,
                           CudaStatusDomain::kInjected, 1));
        finalize_iteration_counters();
        result->trace.push_back(std::move(iteration));
        break;
      }
      try {
        // All deep copies, strings, hashes, and radius arithmetic are prepared
        // before the no-fail mathematical commit.
        pending.has_host_state = !solve_context.device_control_enabled() ||
                                 solve_context.audit_mirror_enabled();
        if (pending.has_host_state) pending.next_state = step.trial_state;
        pending.next_current_hash = iteration.trial_state_hash;
        pending.prepared_iteration_trace = iteration;
        pending.has_accepted_state_trace_copy = capture_state_trace;
        if (capture_state_trace)
          pending.accepted_state_trace_copy = pending.next_state;
        const double radius_update =
            std::max(1.0 / 3.0,
                     1.0 - std::pow(2.0 * iteration.rho - 1.0, 3.0));
        pending.prepared_radius = std::min(
            options.max_trust_region_radius, radius / radius_update);
        pending.prepared_decrease_factor = 2.0;
        pending.prepared_internal_state_epoch = internal_state_epoch + 1;
        pending.prepared_legacy_state_epoch =
            instrumentation_enabled ? state_epoch + 1 : 0;
        pending.prepared_linearization_id =
            instrumentation_enabled ? linearization_id + 1 : 0;
        pending.prepared_linearization_reason =
            instrumentation_enabled ? "new_state_relinearization" : "";
      } catch (const std::exception& exception) {
        solve_context.DiscardDeviceTrialState();
        ++result->accepted_pending_preparation_failures;
        result->termination_type = CudaTerminationType::kFailure;
        result->termination_reason =
            "accepted_state_pending_preparation_failed";
        result->error_classification =
            CudaSolveErrorClass::kAcceptedPendingPreparation;
        result->error = std::string("pending accepted-state allocation failed: ") +
                        exception.what();
        *error = result->error;
        RecordDiagnostic(
            &result->runtime,
            MakeDiagnostic(CudaSolveErrorClass::kAcceptedPendingPreparation,
                           CudaFailureSite::kPendingPreparation,
                           CudaStatusDomain::kCxxException, 1));
        finalize_iteration_counters();
        result->trace.push_back(std::move(iteration));
        break;
      }

      CudaLinearizationIdentity next_identity = current_identity;
      next_identity.state_epoch = internal_state_epoch + 1;
      const uint64_t pending_layer_b_calls_before =
          solve_call_counters.layer_b;
      const bool pending_linearization_built = native_mode
          ? linearizations.BuildNative(
                next_identity, step_options.layer_b,
                CudaFaultLogicalSite::kAcceptedPendingLinearization,
                &pending.next_linearization, error)
          : linearizations.Build(
                pending.has_host_state ? pending.next_state
                                       : result->final_state,
                next_identity, step_options.layer_b,
                CudaFaultLogicalSite::kAcceptedPendingLinearization,
                &pending.next_linearization, error);
      const bool pending_identity_valid =
          pending_linearization_built && linearizations.ValidatePendingPublish(
              next_identity, pending.next_linearization) &&
          solve_context.ValidateDeviceLinearizationBinding(
              pending.next_linearization, error);
      const bool commit_token_prepared =
          pending_identity_valid && solve_context.PreparePersistentCommit(
              next_identity, &pending.device_commit_token, error);
      if (!pending_linearization_built || !pending_identity_valid ||
          !commit_token_prepared) {
        solve_context.DiscardDeviceTrialState();
        if (pending_linearization_built &&
            (!pending_identity_valid || !commit_token_prepared))
          *error = "CURRENT_LINEARIZATION_IDENTITY_MISMATCH";
        ++result->accepted_pending_linearization_failures;
        result->termination_type = CudaTerminationType::kFailure;
        result->termination_reason =
            "accepted_state_pending_linearization_failed";
        result->error_classification =
            CudaSolveErrorClass::kAcceptedPendingLinearization;
        RecordDiagnostic(
            &result->runtime,
            MakeDiagnostic(CudaSolveErrorClass::kAcceptedPendingLinearization,
                           CudaFailureSite::kAcceptedPendingLinearization,
                           CudaStatusDomain::kInjected, 1));
        const bool pending_touched_cuda =
            solve_call_counters.layer_b != pending_layer_b_calls_before;
        if (pending_touched_cuda ||
            logical_faults.force_resource_teardown_failure()) {
          prepared_cleanup_error.clear();
          if (!TaintAndClearCudaResources(
                  logical_faults.force_resource_teardown_failure(),
                  &result->runtime, &prepared_cleanup_error)) {
            result->error_classification =
                CudaSolveErrorClass::kResourceCleanup;
            *error = prepared_cleanup_error;
            RecordDiagnostic(
                &result->runtime,
                MakeDiagnostic(CudaSolveErrorClass::kResourceCleanup,
                               CudaFailureSite::kDestroyAllocation,
                               CudaStatusDomain::kInjected, 1));
          }
        }
        result->error = *error;
        iteration.accepted_commit_success = false;
        finalize_iteration_counters();
        result->trace.push_back(std::move(iteration));
        break;
      }
      AccumulateLayerBRuntime(pending.next_linearization.layer_b(),
                              &result->runtime);
      iteration.cost_after = step.trial_cost;
      iteration.projected_gradient_max_norm =
          pending.next_linearization.layer_b().projected_gradient_max_norm;
      iteration.scaled_gradient_norm =
          pending.next_linearization.layer_b().scaled_gradient_max_norm;
      iteration.radius_after = pending.prepared_radius;
      iteration.lambda_after = 1.0 / pending.prepared_radius;
      iteration.accepted_commit_success = true;
      finalize_iteration_counters();
      pending.prepared_iteration_trace = std::move(iteration);
      if (native_mode) {
        CommitAcceptedNativeState(
            std::move(pending), &solve_context, &linearizations, result,
            &internal_state_epoch, &state_epoch, &current_identity,
            &last_linearization_state_epoch, &has_linearization,
            &linearization_id, &linearization_reason, &radius,
            &decrease_factor);
      } else {
        CommitAcceptedState(
            std::move(pending), capture_state_trace, &state_hash,
            &solve_context, &linearizations, result, &internal_state_epoch,
            &state_epoch, &current_identity, &last_linearization_state_epoch,
            &has_linearization, &linearization_id, &linearization_reason,
            &radius, &decrease_factor);
      }
      current = &linearizations.current().layer_b();
      accepted_commit = true;
    } else {
      solve_context.DiscardDeviceTrialState();
      ++result->rejected_steps;
      radius /= decrease_factor;
      decrease_factor *= 2.0;
      // Match the custom_cpu/Ceres trace convention for an ordinary reject.
      iteration.projected_gradient_max_norm = 0.0;
      iteration.accepted_commit_success = false;
      iteration.radius_after = radius;
      iteration.lambda_after = 1.0 / radius;
      finalize_iteration_counters();
      result->trace.push_back(std::move(iteration));
    }

    if (elapsed_seconds() >= options.max_solver_time_in_seconds) {
      result->termination_type = CudaTerminationType::kNoConvergence;
      result->termination_reason = "maximum_solver_time";
    } else if (result->trial_iterations >= max_iterations) {
      result->termination_type = CudaTerminationType::kNoConvergence;
      result->termination_reason = "maximum_trial_iterations";
    } else if (accepted_commit &&
               current->projected_gradient_max_norm <= gradient_tolerance) {
      result->termination_type = CudaTerminationType::kConvergence;
      result->termination_reason = "gradient_tolerance";
    } else if (radius <= options.min_trust_region_radius) {
      result->termination_type = CudaTerminationType::kConvergence;
      result->termination_reason = "minimum_trust_region_radius";
    }
  }

  if (solve_context.device_state_enabled() &&
      result->termination_type != CudaTerminationType::kFailure) {
    bool materialized = false;
    if (native_mode) {
      materialized = solve_context.persistent_device()->DownloadCurrentNativeState(
          *native_request->view, *native_request->initial_state,
          current_identity, &native_result->final_state, error);
      if (materialized)
        ++native_result->runtime.dense_active_state_device_download_calls;
    } else {
      Snapshot materialized_final;
      materialized = solve_context.persistent_device()->MaterializeCurrentState(
          result->final_state, &materialized_final, true, error);
      if (materialized) {
        using std::swap;
        swap(result->final_state, materialized_final);
      }
    }
    if (!materialized) {
      result->termination_type = CudaTerminationType::kFailure;
      result->termination_reason = "device_state_final_materialization_failed";
      result->error_classification = CudaSolveErrorClass::kCudaStep;
      result->error = *error;
    }
  }

  if (!result->trace.empty()) {
    result->trace.back().termination_reason = result->termination_reason;
  }
  result->final_cost = current->cost;
  result->final_projected_gradient_max_norm =
      current->projected_gradient_max_norm;
  result->final_scaled_gradient_norm = current->scaled_gradient_max_norm;
  result->final_radius = radius;
  result->final_lambda = 1.0 / radius;
  result->runtime.host_wall_milliseconds =
      std::chrono::duration<double, std::milli>(
          std::chrono::steady_clock::now() - host_start)
          .count();
  if (!native_mode &&
      !state_hash.Current(result->final_state,
                          &result->runtime.final_state_hash, error)) {
    result->termination_type = CudaTerminationType::kFailure;
    result->termination_reason = "final_state_hash_failed";
    result->error_classification = CudaSolveErrorClass::kFinalStateHash;
    result->error = *error;
  }
  result->runtime.final_state_epoch =
      instrumentation_enabled ? state_epoch : 0;
  result->runtime.final_internal_state_epoch = internal_state_epoch;
  result->runtime.final_linearization_id =
      instrumentation_enabled ? linearization_id : 0;
  result->runtime.final_linearization_reason =
      instrumentation_enabled ? linearization_reason : std::string();
  result->runtime.layer_a_calls = solve_call_counters.layer_a;
  result->runtime.layer_b_calls = solve_call_counters.layer_b;
  result->runtime.layer_c_calls = solve_call_counters.layer_c;
  result->runtime.cost_calls = solve_call_counters.cost;
  result->runtime.topology_build_count =
      result->runtime.timing.topology_build_count;
  result->runtime.topology_refresh_count =
      instrumentation_enabled ? solve_context.topology_refresh_count() : 0;
  result->runtime.cache_lookup_count = result->runtime.timing.cache_lookup_count;
  result->runtime.cache_hit_count = result->runtime.timing.cache_hit_count;
  result->runtime.cache_miss_count = result->runtime.timing.cache_miss_count;
  result->runtime.cache_invalidation_count =
      result->runtime.timing.cache_invalidation_count;
  result->runtime.build_cuda_layer_a_inputs_count =
      solve_call_counters.build_cuda_layer_a_inputs;
  result->runtime.build_cost_order_count =
      solve_call_counters.build_cost_order;
  result->runtime.topology_epoch = result->runtime.timing.topology_epoch;
  result->runtime.topology_fingerprint =
      instrumentation_enabled ? solve_context.topology_fingerprint()
                              : std::string();
  result->runtime.topology_fingerprint_computations =
      result->runtime.timing.topology_fingerprint_computations;
  result->runtime.topology_generation =
      instrumentation_enabled ? solve_context.topology_generation() : 0;
  result->runtime.accepted_trials =
      result->accepted_commits;
  result->runtime.persistent_device.dpotrf_calls =
      result->runtime.persistent_device.factorization_calls;
  result->runtime.persistent_device.dpotrs_calls =
      result->runtime.persistent_device.factorization_calls;
  result->runtime.rejected_trials = result->rejected_steps;
  result->runtime.actual_trials = result->trial_iterations;
  result->runtime.buffer_reuse_hits = buffer_reuse_scope.hits();
  result->runtime.buffers_reused_across_iterations =
      options.performance_mode && result->runtime.buffer_reuse_hits > 0;
  result->runtime.topology_reuse_hits = solve_context.topology_reuse_hits();
  result->runtime.topology_reused_across_iterations =
      options.performance_mode && result->runtime.topology_reuse_hits > 0;
  result->runtime.stream_reuse_hits = CudaStreamReuseHits();
  result->runtime.event_reuse_hits = CudaEventReuseHits();
  result->runtime.solver_handle_reuse_hits = CudaSolverReuseHits();
  result->runtime.blas_handle_reuse_hits = CudaBlasReuseHits();
  result->runtime.cache_access_serialized = true;
  result->runtime.cache_context_isolated = true;
  result->runtime.final_config_generation =
      solve_context.config_generation();
  result->runtime.final_topology_generation =
      current_identity.topology_generation;
  result->runtime.final_solve_generation = current_identity.solve_generation;
  result->runtime.resource_lookup_blocked_count =
      g_cuda_resource_lookup_blocked_count;
  const bool accepted_counter_identity =
      result->accepted_decisions ==
      result->accepted_commits +
          result->accepted_pending_preparation_failures +
          result->accepted_pending_linearization_failures;
  const bool cache_counter_identity =
      result->runtime.current_linearization_logical_requests ==
          result->runtime.current_linearization_lookup_aborts +
              result->runtime.current_linearization_cache_hits +
              result->runtime.current_linearization_cache_misses &&
      result->runtime.current_linearization_cache_lookups ==
          result->runtime.current_linearization_cache_hits +
              result->runtime.current_linearization_cache_misses &&
      result->runtime.current_linearization_build_attempts ==
          result->runtime.current_linearization_build_successes +
              result->runtime.current_linearization_build_failures &&
      result->runtime.current_linearization_build_successes ==
          result->runtime.current_linearization_temporary_builds +
              result->runtime.current_linearization_publishes;
  if (!accepted_counter_identity || !cache_counter_identity ||
      logical_faults.overflowed()) {
    result->termination_type = CudaTerminationType::kFailure;
    result->termination_reason = "audit_runtime_invariant_failed";
    result->error_classification = CudaSolveErrorClass::kAuditCapacity;
    result->error = "AUDIT_CAPACITY: runtime audit invariant failed";
    *error = result->error;
    RecordDiagnostic(
        &result->runtime,
        MakeDiagnostic(CudaSolveErrorClass::kAuditCapacity,
                       CudaFailureSite::kAuditRuntimeOverflow,
                       CudaStatusDomain::kInternal, 1));
  }
  result->success =
      result->termination_type != CudaTerminationType::kFailure;
  // Close solve-owned CUDA resources while the audit sink is still active.
  // The legacy runtime above intentionally retains its Phase 6.3 boundary;
  // the audit interval below includes final hashing/report preparation and
  // explicit cache teardown. The caller wall additionally includes remaining
  // C++ RAII destruction after this function returns.
  linearizations.Teardown();
  std::string persistent_close_error;
  if (!solve_context.ClosePersistent(&persistent_close_error)) {
    result->success = false;
    result->termination_type = CudaTerminationType::kFailure;
    result->termination_reason = "persistent_device_context_close_failed";
    result->error_classification = CudaSolveErrorClass::kResourceCleanup;
    result->error = persistent_close_error;
    *error = result->error;
  }
  buffer_reuse_scope.Close();
  result->runtime.final_resource_health = g_cuda_resource_health;
  FinalizeProductionAuditInvariants(audit_profile, &result->runtime);
  if (result->success && result->runtime.production_audit_invariants_checked &&
      !result->runtime.production_audit_invariants_pass) {
    result->success = false;
    result->termination_type = CudaTerminationType::kFailure;
    result->termination_reason = "production_audit_invariant_failed";
    result->error_classification = CudaSolveErrorClass::kInvalidOptions;
    result->error = "production CUDA profile executed optional audit work: " +
                    result->runtime.first_production_audit_violation;
    *error = result->error;
  }
  controller_self.Stop();
  if (instrumentation_enabled) {
    const double audit_interval_milliseconds =
        std::chrono::duration<double, std::milli>(
            std::chrono::steady_clock::now() - host_start)
            .count();
    FinalizeTimingLedger(&result->runtime.timing,
                         audit_interval_milliseconds);
  }
  runtime_audit_finalizer.Finalize();
  if (native_mode) {
    native_result->success = result->success;
    native_result->error = result->error;
    native_result->termination_reason = result->termination_reason;
    native_result->initial_cost = result->initial_cost;
    native_result->final_cost = result->final_cost;
    native_result->trial_iterations = result->trial_iterations;
    native_result->accepted_steps = result->accepted_steps;
    native_result->accepted_commits = result->accepted_commits;
    native_result->rejected_steps = result->rejected_steps;
    native_result->invalid_steps = result->invalid_steps;
    native_result->final_internal_state_epoch =
        result->runtime.final_internal_state_epoch;
    native_result->runtime.legacy_kernel_input_bundle_calls =
        native_bundle->runtime.legacy_kernel_input_bundle_calls;
    native_result->runtime.build_cuda_layer_a_inputs_calls =
        native_bundle->runtime.build_cuda_layer_a_inputs_calls;
    native_result->runtime.build_static_layout_calls =
        native_bundle->runtime.build_static_layout_calls;
    native_result->runtime.build_cost_layout_calls =
        native_bundle->runtime.build_cost_layout_calls;
    native_result->runtime.build_layer_b_topology_calls =
        native_bundle->runtime.build_layer_b_topology_calls;
    native_result->runtime.build_layer_c_topology_calls =
        native_bundle->runtime.build_layer_c_topology_calls;
    native_result->runtime.temporary_visual_input_bytes =
        native_bundle->runtime.temporary_visual_input_bytes;
    native_result->runtime.temporary_lidar_input_bytes =
        native_bundle->runtime.temporary_lidar_input_bytes;
    native_result->runtime.temporary_legacy_kernel_abi = true;
    native_result->runtime.native_lm_controller_handoff_complete = true;
    native_result->runtime.real_cost_layout_entries =
        native_bundle->runtime.real_cost_layout_entries;
    native_result->runtime.real_pose_adjacency_entries =
        native_bundle->runtime.real_pose_adjacency_entries;
    native_result->runtime.real_point_adjacency_entries =
        native_bundle->runtime.real_point_adjacency_entries;
    native_result->runtime.real_edge_adjacency_entries =
        native_bundle->runtime.real_edge_adjacency_entries;
    native_result->runtime.real_schur_pair_contributions =
        native_bundle->runtime.real_schur_pair_contributions;
  }
  return result->success;
}

bool RunCustomCudaSolve(const Snapshot& snapshot,
                        const CudaFullLmOptions& options,
                        CudaFullLmResult* result,
                        std::string* error) {
  return RunCustomCudaSolveCore(&snapshot, &snapshot, nullptr, nullptr, nullptr,
                                options, result, error);
}

bool RunCustomCudaSolve(const CudaSolveProblem& problem,
                        const CudaFullLmOptions& options,
                        CudaFullLmResult* result,
                        std::string* error) {
  return RunCustomCudaSolveCore(&problem, nullptr, nullptr, nullptr, nullptr,
                                options, result, error);
}

bool RunCustomCudaSolve(const NativeCudaSolveRequest& request,
                        BaSolveResult* result,
                        std::string* error) {
  if (result == nullptr || error == nullptr || request.view == nullptr ||
      request.initial_state == nullptr || request.options == nullptr) {
    if (error != nullptr) *error = "native CUDA solve request is incomplete";
    return false;
  }
  *result = BaSolveResult();
  error->clear();
  LegacyKernelInputBundle bundle;
  if (!BuildLegacyKernelInputBundle(*request.view, *request.initial_state,
                                    &bundle, error)) {
    result->error = *error;
    return false;
  }
  CudaFullLmResult controller_result;
  const bool success = RunCustomCudaSolveCore(
      nullptr, nullptr, &request, bundle.impl_.get(), result,
      *request.options, &controller_result, error);
  if (!success && result->error.empty()) result->error = *error;
  return success;
}

bool RunCustomCudaSolveWithStateUpdateStatusForTesting(
    const Snapshot& snapshot,
    const CudaFullLmOptions& options,
    const uint32_t status,
    CudaFullLmResult* result,
    std::string* error) {
  if (status == 0 || (status & ~15u) != 0 || result == nullptr ||
      error == nullptr || g_state_update_status_override_for_testing != 0) {
    if (error != nullptr)
      *error = "state-update status test override is invalid";
    return false;
  }
  ScopedStateUpdateStatusOverrideForTesting override(status);
  return RunCustomCudaSolve(snapshot, options, result, error);
}

bool RunCudaPersistentHandleSelfTest(const Snapshot& snapshot,
                                     std::string* error) {
  CudaCacheCallScope cache_scope;
  if (error == nullptr) return false;
  error->clear();
  CudaFullLmRuntimeInfo runtime;
  CudaFaultTrigger fault;
  CudaAuditRuntimeScope audit_scope(&runtime, fault);
  if (!BeginCudaResourceGeneration(&runtime, false, error)) return false;
  CudaLayerBOptions options;
  options.layer_a.residual_order = CudaResidualOrder::kCanonical;
  GpuBaSolveContext context;
  if (!context.Initialize(snapshot, options, 0, runtime.resource_generation,
                          true,
                          CudaDeviceContextBackend::kPersistent,
                          HotKernelImplementation::kReference,
                          CudaSchurContributionBackend::kDirectTransformed, 0,
                          CudaExecutionProfile::kBaseline, false,
                          &runtime, error)) {
    return false;
  }
  const PackedLayerAState* packed = nullptr;
  if (!context.AcquirePackedState(snapshot, true, &packed, error) ||
      !context.persistent_device()->StaleHandleSelfTest(
          *packed, options.layer_a, error)) {
    context.ClosePersistent(nullptr);
    return false;
  }
  return context.ClosePersistent(error);
}

bool RunCudaDeviceStateHandleSelfTest(const Snapshot& snapshot,
                                      std::string* error) {
  CudaCacheCallScope cache_scope;
  if (error == nullptr) return false;
  error->clear();
  CudaFullLmRuntimeInfo runtime;
  CudaFaultTrigger fault;
  CudaAuditRuntimeScope audit_scope(&runtime, fault);
  if (!BeginCudaResourceGeneration(&runtime, false, error)) return false;
  CudaLayerBOptions options;
  options.layer_a.residual_order = CudaResidualOrder::kCanonical;
  GpuBaSolveContext context;
  if (!context.Initialize(snapshot, options, 0, runtime.resource_generation,
                          true,
                          CudaDeviceContextBackend::kDeviceState,
                          HotKernelImplementation::kReference,
                          CudaSchurContributionBackend::kDirectTransformed, 0,
                          CudaExecutionProfile::kBaseline, false,
                          &runtime, error) ||
      !context.FinalizeResolvedConfig(1, error) ||
      !context.persistent_device()->DeviceStateHandleSelfTest(
          snapshot, options, error)) {
    context.ClosePersistent(nullptr);
    return false;
  }
  return context.ClosePersistent(error);
}

bool RunCudaQuaternionPlusForTesting(
    const std::array<double, 4>& quaternion,
    const std::array<double, 3>& delta,
    std::array<double, 4>* result,
    uint32_t* status,
    std::string* error) {
  if (result == nullptr || status == nullptr || error == nullptr) return false;
  error->clear();
  double* d_quaternion = nullptr;
  double* d_delta = nullptr;
  double* d_result = nullptr;
  uint32_t* d_status = nullptr;
  const auto cleanup = [&]() {
    if (d_status != nullptr) cudaFree(d_status);
    if (d_result != nullptr) cudaFree(d_result);
    if (d_delta != nullptr) cudaFree(d_delta);
    if (d_quaternion != nullptr) cudaFree(d_quaternion);
  };
  cudaError_t cuda_status = cudaMalloc(&d_quaternion, 4 * sizeof(double));
  if (cuda_status == cudaSuccess)
    cuda_status = cudaMalloc(&d_delta, 3 * sizeof(double));
  if (cuda_status == cudaSuccess)
    cuda_status = cudaMalloc(&d_result, 4 * sizeof(double));
  if (cuda_status == cudaSuccess)
    cuda_status = cudaMalloc(&d_status, sizeof(uint32_t));
  if (cuda_status == cudaSuccess)
    cuda_status = cudaMemcpy(d_quaternion, quaternion.data(),
                             4 * sizeof(double), cudaMemcpyHostToDevice);
  if (cuda_status == cudaSuccess)
    cuda_status = cudaMemcpy(d_delta, delta.data(), 3 * sizeof(double),
                             cudaMemcpyHostToDevice);
  if (cuda_status == cudaSuccess) {
    QuaternionPlusTestKernel<<<1, 1>>>(d_quaternion, d_delta, d_result,
                                       d_status);
    cuda_status = cudaGetLastError();
  }
  if (cuda_status == cudaSuccess)
    cuda_status = cudaMemcpy(result->data(), d_result, 4 * sizeof(double),
                             cudaMemcpyDeviceToHost);
  if (cuda_status == cudaSuccess)
    cuda_status = cudaMemcpy(status, d_status, sizeof(uint32_t),
                             cudaMemcpyDeviceToHost);
  cleanup();
  if (cuda_status != cudaSuccess) {
    *error = std::string("device QuaternionPlus test failed: ") +
             CudaErrorText(cuda_status);
    return false;
  }
  return true;
}

bool RunCudaLayerCPairChunkingHostSelfTest(
    CudaLayerCPairChunkingTestSummary* summary,
    std::string* error) {
  if (summary == nullptr || error == nullptr) return false;
  *summary = CudaLayerCPairChunkingTestSummary();
  error->clear();
  summary->production_limit_bytes = kLayerCPairChunkProductionLimitBytes;

  const auto make_ranges = [](const std::vector<uint64_t>& counts,
                              std::vector<LayerCPairContributionRange>* ranges,
                              uint64_t* total) {
    ranges->clear();
    *total = 0;
    for (const uint64_t count : counts) {
      if (count > std::numeric_limits<uint64_t>::max() - *total) return false;
      const uint64_t begin = *total;
      *total += count;
      ranges->push_back({begin, *total});
    }
    return true;
  };
  const auto partition = [&](const std::vector<uint64_t>& counts,
                             const uint64_t limit,
                             std::vector<LayerCPairChunk>* chunks,
                             uint64_t* max_bytes,
                             std::string* local_error) {
    std::vector<LayerCPairContributionRange> ranges;
    uint64_t total = 0;
    return make_ranges(counts, &ranges, &total) &&
           BuildLayerCPairChunks(ranges, total, limit, chunks, max_bytes,
                                 local_error);
  };
  const auto fail = [&](const std::string& reason) {
    *error = "Layer C pair chunk host self-test failed: " + reason;
    return false;
  };

  std::vector<LayerCPairChunk> chunks;
  uint64_t max_bytes = 0;
  std::string local_error;
  if (!partition({}, 0, &chunks, &max_bytes, &local_error) ||
      !chunks.empty() || max_bytes != 0) {
    return fail("empty topology");
  }
  if (!partition({1}, 24, &chunks, &max_bytes, &local_error) ||
      chunks.size() != 1 || max_bytes != sizeof(DevicePairContribution)) {
    return fail("single pair below limit");
  }
  if (!partition({10}, 10 * sizeof(DevicePairContribution), &chunks,
                 &max_bytes, &local_error) ||
      chunks.size() != 1 ||
      max_bytes != 10 * sizeof(DevicePairContribution)) {
    return fail("single pair exactly at limit");
  }
  if (!partition({3, 4, 5}, 7 * sizeof(DevicePairContribution), &chunks,
                 &max_bytes, &local_error) ||
      chunks.size() != 2 || chunks[0].pair_begin != 0 ||
      chunks[0].pair_end != 2 || chunks[1].pair_begin != 2 ||
      chunks[1].pair_end != 3) {
    return fail("greedy boundary crossing");
  }
  const std::vector<uint64_t> non_power_counts{1, 3, 2, 5, 1};
  std::vector<LayerCPairChunk> first;
  std::vector<LayerCPairChunk> second;
  uint64_t first_max = 0;
  uint64_t second_max = 0;
  if (!partition(non_power_counts, 6 * sizeof(DevicePairContribution), &first,
                 &first_max, &local_error) ||
      !partition(non_power_counts, 6 * sizeof(DevicePairContribution), &second,
                 &second_max, &local_error) ||
      first.size() != second.size() || first_max != second_max) {
    return fail("non-power-of-two deterministic partition");
  }
  for (size_t i = 0; i < first.size(); ++i) {
    if (first[i].pair_begin != second[i].pair_begin ||
        first[i].pair_end != second[i].pair_end ||
        first[i].contribution_begin != second[i].contribution_begin ||
        first[i].contribution_end != second[i].contribution_end) {
      return fail("repeated partition differs");
    }
  }
  local_error.clear();
  if (partition({11}, 10 * sizeof(DevicePairContribution), &chunks,
                &max_bytes, &local_error) ||
      local_error.find("Layer C single pair adjacency exceeds chunk limit") !=
          0) {
    return fail("single-pair overflow classification");
  }
  std::vector<LayerCPairContributionRange> invalid_ranges{{0, 1}};
  local_error.clear();
  if (BuildLayerCPairChunks(
          invalid_ranges,
          static_cast<uint64_t>(std::numeric_limits<uint32_t>::max()) + 1,
          0, &chunks, &max_bytes, &local_error) || local_error.empty()) {
    return fail("uint32 contribution overflow");
  }
  invalid_ranges = {{1, 2}};
  local_error.clear();
  if (BuildLayerCPairChunks(invalid_ranges, 2, 0, &chunks, &max_bytes,
                            &local_error) ||
      local_error.empty()) {
    return fail("range contiguity validation");
  }

  const auto make_segment_topology = [&](const std::vector<uint64_t>& counts,
                                         const uint64_t chunk_limit,
                                         LayerCTopology* topology) {
    std::vector<LayerCPairContributionRange> ranges;
    uint64_t total = 0;
    if (!make_ranges(counts, &ranges, &total) ||
        total > std::numeric_limits<uint32_t>::max()) {
      return false;
    }
    topology->pairs.resize(counts.size());
    topology->pair_contributions.resize(static_cast<size_t>(total));
    for (size_t i = 0; i < ranges.size(); ++i) {
      topology->pairs[i].adjacency_begin =
          static_cast<uint32_t>(ranges[i].begin);
      topology->pairs[i].adjacency_end =
          static_cast<uint32_t>(ranges[i].end);
    }
    return BuildLayerCPairChunks(
        ranges, total, chunk_limit, &topology->pair_chunks,
        &topology->pair_chunk_max_bytes, &local_error);
  };
  LayerCTopology empty_segment_topology;
  if (!BuildLayerCSegmentPlan(16, &empty_segment_topology, &local_error) ||
      !empty_segment_topology.segments.empty() ||
      !empty_segment_topology.segment_chunks.empty()) {
    return fail("empty segment topology");
  }
  LayerCTopology segment_topology;
  local_error.clear();
  if (!make_segment_topology({1, 16, 17, 33, 2}, 0,
                             &segment_topology) ||
      !BuildLayerCSegmentPlan(16, &segment_topology, &local_error) ||
      segment_topology.segment_direct_pair_indices !=
          std::vector<uint32_t>({0, 1, 4}) ||
      segment_topology.segments.size() != 5 ||
      segment_topology.segment_pair_ranges[2].segment_end -
              segment_topology.segment_pair_ranges[2].segment_begin != 2 ||
      segment_topology.segment_pair_ranges[3].segment_end -
              segment_topology.segment_pair_ranges[3].segment_begin != 3) {
    return fail("segment boundary/hybrid partition");
  }
  LayerCTopology repeated_segment_topology;
  local_error.clear();
  if (!make_segment_topology({1, 16, 17, 33, 2}, 0,
                             &repeated_segment_topology) ||
      !BuildLayerCSegmentPlan(16, &repeated_segment_topology, &local_error) ||
      repeated_segment_topology.segment_direct_pair_indices !=
          segment_topology.segment_direct_pair_indices ||
      repeated_segment_topology.segments.size() !=
          segment_topology.segments.size()) {
    return fail("segment plan determinism");
  }
  for (size_t i = 0; i < segment_topology.segments.size(); ++i) {
    const DeviceSchurSegment& lhs = segment_topology.segments[i];
    const DeviceSchurSegment& rhs = repeated_segment_topology.segments[i];
    if (lhs.pair_index != rhs.pair_index ||
        lhs.contribution_begin != rhs.contribution_begin ||
        lhs.contribution_end != rhs.contribution_end) {
      return fail("repeated segment descriptor differs");
    }
  }
  LayerCTopology multi_chunk_segments;
  local_error.clear();
  if (!make_segment_topology(
          {8, 40, 8, 40}, 48 * sizeof(DevicePairContribution),
          &multi_chunk_segments) ||
      multi_chunk_segments.pair_chunks.size() != 2 ||
      !BuildLayerCSegmentPlan(16, &multi_chunk_segments, &local_error) ||
      multi_chunk_segments.segment_chunks.size() != 2) {
    return fail("multi-chunk multi-segment partition");
  }
  for (size_t chunk_index = 0;
       chunk_index < multi_chunk_segments.segment_chunks.size();
       ++chunk_index) {
    const LayerCSegmentChunk& segment_chunk =
        multi_chunk_segments.segment_chunks[chunk_index];
    for (uint64_t segment_index = segment_chunk.segment_begin;
         segment_index < segment_chunk.segment_end; ++segment_index) {
      const DeviceSchurSegment& segment =
          multi_chunk_segments.segments[segment_index];
      if (segment.pair_index < segment_chunk.pair_begin ||
          segment.pair_index >= segment_chunk.pair_end) {
        return fail("segment crosses a whole-pair chunk");
      }
    }
  }
  LayerCTopology invalid_segment_topology;
  invalid_segment_topology.pairs.resize(1);
  invalid_segment_topology.pairs[0].adjacency_end = 1;
  invalid_segment_topology.pair_chunks.push_back({0, 1, 0, 1});
  local_error.clear();
  if (BuildLayerCSegmentPlan(16, &invalid_segment_topology, &local_error) ||
      local_error.empty()) {
    return fail("segment adjacency overflow");
  }

  summary->stress_pose_count = 229;
  summary->stress_pair_count =
      summary->stress_pose_count * (summary->stress_pose_count + 1) / 2;
  const uint64_t contributions_per_pair = 256;
  std::vector<uint64_t> stress_counts(
      static_cast<size_t>(summary->stress_pair_count), contributions_per_pair);
  summary->stress_contribution_count =
      summary->stress_pair_count * contributions_per_pair;
  if (!CheckedMultiply(summary->stress_contribution_count,
                       sizeof(DevicePairContribution),
                       &summary->stress_contribution_bytes) ||
      summary->stress_contribution_bytes <=
          kLayerCPairChunkProductionLimitBytes ||
      !partition(stress_counts, 0, &chunks, &max_bytes, &local_error) ||
      chunks.size() <= 1 ||
      max_bytes > kLayerCPairChunkProductionLimitBytes) {
    return fail("call505-scale partition");
  }
  summary->stress_chunk_count = chunks.size();
  summary->stress_max_chunk_bytes = max_bytes;
  return true;
}

bool BuildCudaSchurContributionHistogramForTesting(
    const Snapshot& snapshot,
    CudaSchurContributionHistogram* histogram,
    std::string* error) {
  if (histogram == nullptr || error == nullptr) return false;
  *histogram = CudaSchurContributionHistogram();
  error->clear();
  CudaLayerBOptions options;
  options.layer_a.residual_order = CudaResidualOrder::kSourceInsertion;
  GpuBaSolveContext context;
  if (!context.Initialize(
          snapshot, options, 0, 1, true,
          CudaDeviceContextBackend::kLegacy,
          HotKernelImplementation::kReference,
          CudaSchurContributionBackend::kDirectTransformed, 0,
          CudaExecutionProfile::kBaseline, false, nullptr, error)) {
    return false;
  }
  const LayerCTopology& topology = context.BorrowLayerCTopology();
  histogram->pose_count = topology.poses.size();
  histogram->pair_count = topology.pairs.size();
  histogram->contribution_count = topology.pair_contributions.size();
  histogram->whole_pair_chunk_count = topology.pair_chunks.size();
  std::vector<uint64_t> counts;
  counts.reserve(topology.pairs.size());
  for (const DevicePairMeta& pair : topology.pairs) {
    const uint64_t count = pair.adjacency_end - pair.adjacency_begin;
    counts.push_back(count);
    if (count == 0) ++histogram->empty_pair_count;
    if (count == 1) ++histogram->single_contribution_pair_count;
  }
  std::sort(counts.begin(), counts.end());
  const auto percentile = [&counts](double p) -> uint64_t {
    if (counts.empty()) return 0;
    const size_t index = static_cast<size_t>(
        std::ceil(p * static_cast<double>(counts.size()))) - 1;
    return counts[std::min(index, counts.size() - 1)];
  };
  if (!counts.empty()) {
    histogram->minimum = counts.front();
    histogram->p50 = percentile(0.50);
    histogram->p90 = percentile(0.90);
    histogram->p95 = percentile(0.95);
    histogram->p99 = percentile(0.99);
    histogram->maximum = counts.back();
  }
  for (const LayerCPairChunk& chunk : topology.pair_chunks) {
    histogram->chunk_pair_begin.push_back(chunk.pair_begin);
    histogram->chunk_pair_end.push_back(chunk.pair_end);
    histogram->chunk_contribution_begin.push_back(chunk.contribution_begin);
    histogram->chunk_contribution_end.push_back(chunk.contribution_end);
  }
  return true;
}

namespace {

struct MixedStableComponentCapture {
  CudaLayerBResult layer_b;
  CudaLayerCStepResult layer_c;
  CudaFullLmRuntimeInfo runtime;
  LayerCTopology layer_c_topology;
  std::vector<double> layer_a_reference;
  std::vector<double> layer_a_candidate;
  std::vector<double> scale_reference;
  std::vector<double> scale_candidate;
  std::vector<double> point_inverse;
  std::vector<double> inverse_gradient;
  std::vector<double> transformed_edge;
  double complete_milliseconds = 0.0;
};

CudaPrecisionErrorStatistics MixedStableErrorStatistics(
    const std::vector<double>& reference,
    const std::vector<double>& candidate,
    const char* kind) {
  CudaPrecisionErrorStatistics result;
  result.worst_entity_kind = kind == nullptr ? "value" : kind;
  if (reference.size() != candidate.size()) return result;
  result.count = reference.size();
  std::vector<double> absolute;
  std::vector<double> relative;
  absolute.reserve(reference.size());
  relative.reserve(reference.size());
  long double absolute_sum = 0.0L;
  long double squared_sum = 0.0L;
  long double reference_squared = 0.0L;
  for (size_t index = 0; index < reference.size(); ++index) {
    const double lhs = reference[index];
    const double rhs = candidate[index];
    if (!std::isfinite(lhs) || !std::isfinite(rhs)) continue;
    ++result.finite_count;
    result.reference_max_magnitude =
        std::max(result.reference_max_magnitude, std::abs(lhs));
    result.candidate_max_magnitude =
        std::max(result.candidate_max_magnitude, std::abs(rhs));
    reference_squared += static_cast<long double>(lhs) * lhs;
  }
  const double relative_floor =
      1e-12 * std::max(1.0, result.reference_max_magnitude);
  for (size_t index = 0; index < reference.size(); ++index) {
    const double lhs = reference[index];
    const double rhs = candidate[index];
    if (!std::isfinite(lhs) || !std::isfinite(rhs)) continue;
    const double difference = std::abs(rhs - lhs);
    const double relative_error =
        difference / std::max(std::abs(lhs), relative_floor);
    absolute.push_back(difference);
    relative.push_back(relative_error);
    absolute_sum += difference;
    squared_sum += static_cast<long double>(difference) * difference;
    if (difference > result.max_abs_error) {
      result.max_abs_error = difference;
      result.worst_index = index;
      result.worst_reference = lhs;
      result.worst_candidate = rhs;
    }
    result.max_relative_error =
        std::max(result.max_relative_error, relative_error);
  }
  if (!absolute.empty()) {
    std::sort(absolute.begin(), absolute.end());
    std::sort(relative.begin(), relative.end());
    const auto percentile = [](const std::vector<double>& values,
                               const double p) {
      if (values.empty()) return 0.0;
      const size_t index = std::min(
          values.size() - 1,
          static_cast<size_t>(std::ceil(
              p * static_cast<double>(values.size()))) - 1);
      return values[index];
    };
    result.mean_abs_error =
        static_cast<double>(absolute_sum / absolute.size());
    result.rms_abs_error =
        std::sqrt(static_cast<double>(squared_sum / absolute.size()));
    result.p50_abs_error = percentile(absolute, 0.50);
    result.p95_abs_error = percentile(absolute, 0.95);
    result.p99_abs_error = percentile(absolute, 0.99);
    result.p50_relative_error = percentile(relative, 0.50);
    result.p95_relative_error = percentile(relative, 0.95);
    result.p99_relative_error = percentile(relative, 0.99);
  }
  result.normalized_max_error =
      result.max_abs_error / std::max(1.0, result.reference_max_magnitude);
  result.normalized_frobenius_error = static_cast<double>(
      std::sqrt(squared_sum) /
      std::max<long double>(1.0L, std::sqrt(reference_squared)));
  return result;
}

void FlattenMixedStableLayerB(
    const CudaLayerBResult& layer_b,
    std::vector<double>* pose_hessian,
    std::vector<double>* pose_gradient,
    std::vector<double>* point_hessian,
    std::vector<double>* point_gradient,
    std::vector<double>* edges,
    std::vector<double>* jacobi_damping) {
  for (const CudaPoseBlockOutput& pose : layer_b.poses) {
    for (uint32_t row = 0; row < pose.dimension; ++row) {
      for (uint32_t column = 0; column < pose.dimension; ++column) {
        pose_hessian->push_back(
            pose.hessian[row * pose.dimension + column]);
      }
      pose_gradient->push_back(pose.gradient[row]);
      jacobi_damping->push_back(pose.jacobi_scaling[row]);
      jacobi_damping->push_back(pose.damping[row]);
    }
  }
  for (const CudaPointBlockOutput& point : layer_b.points) {
    point_hessian->insert(point_hessian->end(), point.hessian,
                          point.hessian + 9);
    point_gradient->insert(point_gradient->end(), point.gradient,
                           point.gradient + 3);
    for (uint32_t row = 0; row < 3; ++row) {
      jacobi_damping->push_back(point.jacobi_scaling[row]);
      jacobi_damping->push_back(point.damping[row]);
    }
  }
  for (const CudaEdgeBlockOutput& edge : layer_b.edges) {
    edges->insert(edges->end(), edge.value,
                  edge.value + edge.pose_dimension * 3);
  }
}

std::vector<double> FlattenMixedStableState(const Snapshot& snapshot) {
  std::vector<double> result;
  result.reserve(snapshot.images.size() * 7 + snapshot.points.size() * 3);
  for (const ImageSnapshot& image : snapshot.images) {
    result.insert(result.end(), image.qvec.begin(), image.qvec.end());
    result.insert(result.end(), image.tvec.begin(), image.tvec.end());
  }
  for (const PointSnapshot& point : snapshot.points) {
    result.insert(result.end(), point.xyz.begin(), point.xyz.end());
  }
  return result;
}

bool RunMixedStableComponentPath(
    const Snapshot& snapshot,
    const double lambda,
    const CudaArithmeticPrecision precision,
    MixedStableComponentCapture* capture,
    std::string* error) {
  if (capture == nullptr || error == nullptr || !std::isfinite(lambda) ||
      lambda < 0.0 ||
      (precision != CudaArithmeticPrecision::kFp64 &&
       precision != CudaArithmeticPrecision::kFp32MixedStable)) {
    if (error != nullptr) *error = "mixed component path options are invalid";
    return false;
  }
  *capture = MixedStableComponentCapture();
  CudaFaultTrigger fault;
  CudaAuditRuntimeScope audit_scope(&capture->runtime, fault);
  if (!BeginCudaResourceGeneration(&capture->runtime, true, error)) {
    return false;
  }
  CudaLayerBOptions layer_b_options;
  layer_b_options.layer_a.residual_order =
      CudaResidualOrder::kSourceInsertion;
  layer_b_options.reduction_mode =
      CudaReductionMode::kParallelDeterministic;
  layer_b_options.cost_reduction_threads = 128;
  layer_b_options.hessian_assembly_backend =
      CudaHessianAssemblyBackend::kObservationSegmented;
  layer_b_options.hessian_segment_size_for_testing = 64;
  GpuBaSolveContext context;
  context.SetArithmeticPrecisionForSolve(precision);
  const auto begin = std::chrono::steady_clock::now();
  if (!context.Initialize(
          snapshot, layer_b_options, 0, capture->runtime.resource_generation,
          true, CudaDeviceContextBackend::kDeviceControl,
          HotKernelImplementation::kTransformed,
          CudaSchurContributionBackend::kSegmentedTransformed, 64,
          CudaExecutionProfile::kCompactControl, true, &capture->runtime,
          error)) {
    context.ClosePersistent(nullptr);
    return false;
  }
  CudaLinearizationIdentity identity;
  identity.solve_generation = capture->runtime.resource_generation;
  identity.state_epoch = 0;
  identity.topology_generation = context.topology_generation();
  identity.config_generation = 0;
  CudaDeviceLinearizationToken token;
  if (!RunCudaLayerBFromContext(
          &context, snapshot, layer_b_options, &identity,
          CudaFaultLogicalSite::kInitialLinearization, &capture->layer_b,
          &token, error)) {
    context.ClosePersistent(nullptr);
    return false;
  }
  if (precision == CudaArithmeticPrecision::kFp32MixedStable &&
      !context.persistent_device()->CaptureMixedLayerAForTesting(
          context.loss_mode(), context.loss_scale(),
          &capture->layer_a_reference, &capture->layer_a_candidate,
          &capture->scale_reference, &capture->scale_candidate, error)) {
    context.ClosePersistent(nullptr);
    return false;
  }
  if (!context.PublishPersistentFrozenScalingFromInitial(token, identity,
                                                          error)) {
    context.ClosePersistent(nullptr);
    return false;
  }
  layer_b_options.device_frozen_jacobi_scaling = true;
  identity.config_generation = NextMathematicalGeneration();
  if (!context.FinalizeResolvedConfig(identity.config_generation, error)) {
    context.ClosePersistent(nullptr);
    return false;
  }
  UndampedCurrentLinearization linearization =
      UndampedCurrentLinearization::Adopt(
          CudaLinearizationIdentity{identity.solve_generation,
                                    identity.state_epoch,
                                    identity.topology_generation, 0},
          std::move(capture->layer_b), token);
  linearization.RebindIdentityForBootstrap(identity);
  context.PublishPersistentInitial(identity);
  CudaLayerCOptions layer_c_options;
  layer_c_options.layer_b = layer_b_options;
  layer_c_options.lambda = lambda;
  layer_c_options.schur_contribution_backend =
      CudaSchurContributionBackend::kSegmentedTransformed;
  layer_c_options.schur_segment_size_for_testing = 64;
  if (!RunCudaSnapshotLayerCFromLinearization(
          &context, snapshot, layer_c_options, linearization,
          &capture->layer_c, error) ||
      !context.persistent_device()->CaptureLayerCWorkspaceForTesting(
          &capture->point_inverse, &capture->inverse_gradient,
          &capture->transformed_edge, &capture->layer_c.rhs, error)) {
    context.ClosePersistent(nullptr);
    return false;
  }
  capture->layer_c_topology = context.BorrowLayerCTopology();
  capture->layer_b = CudaLayerBResult();
  capture->layer_b.cost = linearization.layer_b().cost;
  capture->layer_b.projected_gradient_max_norm =
      linearization.layer_b().projected_gradient_max_norm;
  capture->layer_b.raw_tangent_gradient_max_norm =
      linearization.layer_b().raw_tangent_gradient_max_norm;
  capture->layer_b.scaled_gradient_max_norm =
      linearization.layer_b().scaled_gradient_max_norm;
  capture->layer_b.poses = linearization.layer_b().poses;
  capture->layer_b.points = linearization.layer_b().points;
  capture->layer_b.edges = linearization.layer_b().edges;
  capture->complete_milliseconds =
      std::chrono::duration<double, std::milli>(
          std::chrono::steady_clock::now() - begin)
          .count();
  if (!context.ClosePersistent(error)) return false;
  return true;
}

bool BenchmarkMixedSchurCandidates(
    const MixedStableComponentCapture& capture,
    const double lambda,
    const size_t paired_samples,
    std::vector<double>* promoted_milliseconds,
    std::vector<double>* float_milliseconds,
    std::vector<double>* float_schur,
    std::string* error) {
  if (promoted_milliseconds == nullptr || float_milliseconds == nullptr ||
      float_schur == nullptr || error == nullptr || paired_samples == 0 ||
      !std::isfinite(lambda) || lambda < 0.0) {
    if (error != nullptr) *error = "mixed Schur benchmark options are invalid";
    return false;
  }
  const LayerCTopology& topology = capture.layer_c_topology;
  const CudaLayerBResult& layer_b = capture.layer_b;
  const size_t point_count = layer_b.points.size();
  const size_t edge_count = layer_b.edges.size();
  const size_t pose_count = topology.poses.size();
  const size_t dimension = topology.pose_dimension;
  if (dimension == 0 || dimension > std::numeric_limits<int>::max() ||
      dimension > std::numeric_limits<size_t>::max() / dimension) {
    *error = "mixed Schur benchmark dimension is invalid";
    return false;
  }
  const size_t schur_elements = dimension * dimension;
  std::vector<MixedPoseBlockOutput> mixed_poses(layer_b.poses.size());
  std::vector<MixedPointBlockOutput> mixed_points(layer_b.points.size());
  std::vector<MixedEdgeBlockOutput> mixed_edges(layer_b.edges.size());
  for (size_t index = 0; index < layer_b.poses.size(); ++index) {
    const CudaPoseBlockOutput& source = layer_b.poses[index];
    MixedPoseBlockOutput& destination = mixed_poses[index];
    destination.image_id = source.image_id;
    destination.dimension = source.dimension;
    for (size_t i = 0; i < 3; ++i)
      destination.free_translation_indices[i] =
          source.free_translation_indices[i];
    for (size_t i = 0; i < 36; ++i)
      destination.hessian[i] = static_cast<float>(source.hessian[i]);
    for (size_t i = 0; i < 6; ++i) {
      destination.gradient[i] = source.gradient[i];
      destination.jacobi_scaling[i] =
          static_cast<float>(source.jacobi_scaling[i]);
      destination.damping[i] = static_cast<float>(source.damping[i]);
    }
  }
  for (size_t index = 0; index < layer_b.points.size(); ++index) {
    const CudaPointBlockOutput& source = layer_b.points[index];
    MixedPointBlockOutput& destination = mixed_points[index];
    destination.point3D_id = source.point3D_id;
    for (size_t i = 0; i < 9; ++i)
      destination.hessian[i] = static_cast<float>(source.hessian[i]);
    for (size_t i = 0; i < 3; ++i) {
      destination.gradient[i] = source.gradient[i];
      destination.jacobi_scaling[i] =
          static_cast<float>(source.jacobi_scaling[i]);
      destination.damping[i] = static_cast<float>(source.damping[i]);
    }
  }
  for (size_t index = 0; index < layer_b.edges.size(); ++index) {
    const CudaEdgeBlockOutput& source = layer_b.edges[index];
    MixedEdgeBlockOutput& destination = mixed_edges[index];
    destination.pose_index = source.pose_index;
    destination.point_index = source.point_index;
    destination.pose_dimension = source.pose_dimension;
    for (size_t i = 0; i < 18; ++i)
      destination.value[i] = static_cast<float>(source.value[i]);
  }
  cudaStream_t stream = nullptr;
  cudaEvent_t begin = nullptr;
  cudaEvent_t end = nullptr;
  std::vector<void*> allocations;
  cudaError_t status = cudaSetDevice(0);
  const auto cleanup = [&]() {
    if (end != nullptr) cudaEventDestroy(end);
    if (begin != nullptr) cudaEventDestroy(begin);
    for (auto it = allocations.rbegin(); it != allocations.rend(); ++it) {
      cudaFree(*it);
    }
    if (stream != nullptr) cudaStreamDestroy(stream);
  };
  const auto fail = [&](const char* message) {
    *error = std::string(message) + ": " + CudaErrorText(status);
    cleanup();
    return false;
  };
  if (status != cudaSuccess ||
      (status = cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking)) !=
          cudaSuccess ||
      (status = cudaEventCreate(&begin)) != cudaSuccess ||
      (status = cudaEventCreate(&end)) != cudaSuccess) {
    return fail("mixed Schur benchmark resource creation failed");
  }
  const auto allocate = [&](auto** pointer, const size_t count) {
    using Pointer = typename std::remove_reference<decltype(*pointer)>::type;
    using Value = typename std::remove_pointer<Pointer>::type;
    *pointer = nullptr;
    if (count == 0) return true;
    if (count > std::numeric_limits<size_t>::max() / sizeof(Value)) {
      status = cudaErrorInvalidValue;
      return false;
    }
    status = cudaMalloc(reinterpret_cast<void**>(pointer),
                        count * sizeof(Value));
    if (status == cudaSuccess) allocations.push_back(*pointer);
    return status == cudaSuccess;
  };
  const auto upload = [&](auto* destination, const auto& source) {
    if (source.empty()) return true;
    status = cudaMemcpyAsync(destination, source.data(),
                             source.size() * sizeof(source[0]),
                             cudaMemcpyHostToDevice, stream);
    return status == cudaSuccess;
  };
  DeviceSolvePoseMeta* d_pose_meta = nullptr;
  DevicePairMeta* d_pairs = nullptr;
  DevicePairContribution* d_contributions = nullptr;
  uint32_t* d_direct_indices = nullptr;
  DeviceSchurSegment* d_segments = nullptr;
  DeviceSchurPairSegmentRange* d_ranges = nullptr;
  CudaPoseBlockOutput* d_poses = nullptr;
  CudaPointBlockOutput* d_points = nullptr;
  CudaEdgeBlockOutput* d_edges = nullptr;
  MixedPoseBlockOutput* d_mixed_poses = nullptr;
  MixedPointBlockOutput* d_mixed_points = nullptr;
  MixedEdgeBlockOutput* d_mixed_edges = nullptr;
  double* d_point_inverse = nullptr;
  double* d_inverse_gradient = nullptr;
  uint8_t* d_point_status = nullptr;
  double* d_transformed = nullptr;
  double* d_partials = nullptr;
  double* d_schur = nullptr;
  double* d_rhs = nullptr;
  float* d_float_transformed = nullptr;
  float* d_float_point_inverse = nullptr;
  float* d_float_partials = nullptr;
  double* d_candidate_schur = nullptr;
  if (!allocate(&d_pose_meta, topology.poses.size()) ||
      !allocate(&d_pairs, topology.pairs.size()) ||
      !allocate(&d_contributions, topology.pair_contributions.size()) ||
      !allocate(&d_direct_indices,
                topology.segment_direct_pair_indices.size()) ||
      !allocate(&d_segments, topology.segments.size()) ||
      !allocate(&d_ranges, topology.segment_pair_ranges.size()) ||
      !allocate(&d_poses, layer_b.poses.size()) ||
      !allocate(&d_points, layer_b.points.size()) ||
      !allocate(&d_edges, layer_b.edges.size()) ||
      !allocate(&d_mixed_poses, mixed_poses.size()) ||
      !allocate(&d_mixed_points, mixed_points.size()) ||
      !allocate(&d_mixed_edges, mixed_edges.size()) ||
      !allocate(&d_point_inverse, point_count * 9) ||
      !allocate(&d_inverse_gradient, point_count * 3) ||
      !allocate(&d_point_status, point_count) ||
      !allocate(&d_transformed, edge_count * kTransformedEdgeStride) ||
      !allocate(&d_partials,
                topology.segments.size() * kSchurSegmentStoredScalars) ||
      !allocate(&d_schur, schur_elements) || !allocate(&d_rhs, dimension) ||
      !allocate(&d_float_transformed,
                edge_count * kTransformedEdgeStride) ||
      !allocate(&d_float_point_inverse, point_count * 9) ||
      !allocate(&d_float_partials,
                topology.segments.size() * kSchurSegmentStoredScalars) ||
      !allocate(&d_candidate_schur, schur_elements) ||
      !upload(d_pose_meta, topology.poses) ||
      !upload(d_pairs, topology.pairs) ||
      !upload(d_contributions, topology.pair_contributions) ||
      !upload(d_direct_indices, topology.segment_direct_pair_indices) ||
      !upload(d_segments, topology.segments) ||
      !upload(d_ranges, topology.segment_pair_ranges) ||
      !upload(d_poses, layer_b.poses) || !upload(d_points, layer_b.points) ||
      !upload(d_edges, layer_b.edges) || !upload(d_mixed_poses, mixed_poses) ||
      !upload(d_mixed_points, mixed_points) ||
      !upload(d_mixed_edges, mixed_edges) ||
      (status = cudaStreamSynchronize(stream)) != cudaSuccess) {
    return fail("mixed Schur benchmark allocation/upload failed");
  }
  constexpr int kBlockSize = 128;
  const auto point_blocks = static_cast<int>(
      (point_count + static_cast<size_t>(kBlockSize) - 1) / kBlockSize);
  const auto launch_point_factor = [&]() {
    if (point_count != 0) {
      LayerCPointFactorKernel<<<point_blocks, kBlockSize, 0, stream>>>(
          d_points, lambda, d_point_inverse, d_inverse_gradient,
          d_point_status, point_count);
    }
  };
  const auto launch_promoted = [&]() {
    launch_point_factor();
    if (edge_count != 0) {
      LayerCTransformEdgeKernel<<<edge_count, kTransformedEdgeThreads, 0,
                                  stream>>>(
          d_edges, d_point_inverse, d_transformed, edge_count);
    }
    LayerCZeroSchurKernel<<<
        static_cast<int>((std::max(schur_elements, dimension) + kBlockSize - 1) /
                         kBlockSize),
        kBlockSize, 0, stream>>>(d_schur, d_rhs, dimension);
    if (pose_count != 0) {
      LayerCInitializePoseKernel<<<pose_count, 36, 0, stream>>>(
          d_pose_meta, d_poses, lambda, d_schur, d_rhs, dimension,
          pose_count);
    }
    CudaLayerCRuntimeInfo runtime;
    std::string launch_error;
    if (!LaunchLayerCSegmentedSchurPairChunks(
            topology, 0, d_pairs, d_direct_indices, d_segments, d_ranges,
            d_contributions, d_pose_meta, d_edges, d_transformed, d_partials,
            d_schur, dimension, stream, &runtime, nullptr, &launch_error)) {
      *error = launch_error;
      status = cudaErrorLaunchFailure;
      return false;
    }
    return cudaPeekAtLastError() == cudaSuccess;
  };
  const auto launch_float = [&]() {
    if (point_count != 0) {
      LayerCMixedPointFactorKernel<<<point_blocks, kBlockSize, 0, stream>>>(
          d_mixed_points, lambda, d_point_inverse, d_inverse_gradient,
          d_point_status, point_count);
      LayerCMixedPointInverseToFloatKernel<<<
          static_cast<int>((point_count * 9 + kBlockSize - 1) / kBlockSize),
          kBlockSize, 0, stream>>>(
          d_point_inverse, d_float_point_inverse, point_count * 9);
    }
    if (edge_count != 0) {
      MixedFloatTransformEdgeKernel<<<edge_count, kTransformedEdgeThreads, 0,
                                      stream>>>(
          d_mixed_edges, d_float_point_inverse, d_float_transformed,
          edge_count);
    }
    LayerCZeroSchurKernel<<<
        static_cast<int>((std::max(schur_elements, dimension) + kBlockSize - 1) /
                         kBlockSize),
        kBlockSize, 0, stream>>>(d_candidate_schur, d_rhs, dimension);
    if (pose_count != 0) {
      MixedInitializeDoubleSchurKernel<<<pose_count, 36, 0, stream>>>(
          d_pose_meta, d_mixed_poses, lambda, d_candidate_schur, d_rhs,
          dimension, pose_count);
    }
    if (!topology.segment_direct_pair_indices.empty()) {
      MixedFloatSchurPairIndexedToDoubleKernel<<<
          topology.segment_direct_pair_indices.size(),
          kSchurPairTransformedThreads, 0, stream>>>(
          d_pairs, d_direct_indices, d_contributions, d_pose_meta,
          d_mixed_edges, d_float_transformed, d_candidate_schur, dimension,
          topology.segment_direct_pair_indices.size());
    }
    if (!topology.segments.empty()) {
      MixedFloatSchurSegmentPartialKernel<<<
          topology.segments.size(), kSchurPairTransformedThreads, 0, stream>>>(
          d_pairs, d_segments, d_contributions, d_pose_meta, d_mixed_edges,
          d_float_transformed, d_float_partials, 0,
          topology.segments.size());
    }
    if (!topology.pairs.empty()) {
      MixedFloatSchurSegmentMergeToDoubleKernel<<<
          topology.pairs.size(), kSchurPairTransformedThreads, 0, stream>>>(
          d_pairs, d_ranges, d_pose_meta, d_float_partials, d_candidate_schur,
          dimension, 0, topology.pairs.size());
    }
    return cudaPeekAtLastError() == cudaSuccess;
  };
  const auto sample = [&](const bool promoted, double* milliseconds) {
    if ((status = cudaEventRecord(begin, stream)) != cudaSuccess) return false;
    if (!(promoted ? launch_promoted() : launch_float())) return false;
    if ((status = cudaEventRecord(end, stream)) != cudaSuccess ||
        (status = cudaEventSynchronize(end)) != cudaSuccess) return false;
    float elapsed = 0.0f;
    if ((status = cudaEventElapsedTime(&elapsed, begin, end)) != cudaSuccess)
      return false;
    *milliseconds = elapsed;
    return true;
  };
  double ignored = 0.0;
  if (!sample(true, &ignored) || !sample(false, &ignored)) {
    return fail("mixed Schur benchmark warm-up failed");
  }
  promoted_milliseconds->clear();
  float_milliseconds->clear();
  promoted_milliseconds->reserve(paired_samples);
  float_milliseconds->reserve(paired_samples);
  for (size_t pair = 0; pair < paired_samples; ++pair) {
    double promoted = 0.0;
    double candidate = 0.0;
    const bool candidate_first = pair % 2 != 0;
    if (candidate_first) {
      if (!sample(false, &candidate) || !sample(true, &promoted)) {
        return fail("mixed Schur benchmark paired sample failed");
      }
    } else if (!sample(true, &promoted) || !sample(false, &candidate)) {
      return fail("mixed Schur benchmark paired sample failed");
    }
    promoted_milliseconds->push_back(promoted);
    float_milliseconds->push_back(candidate);
  }
  float_schur->resize(schur_elements);
  status = cudaMemcpyAsync(float_schur->data(), d_candidate_schur,
                           schur_elements * sizeof(double),
                           cudaMemcpyDeviceToHost, stream);
  if (status != cudaSuccess ||
      (status = cudaStreamSynchronize(stream)) != cudaSuccess) {
    return fail("mixed Schur benchmark result download failed");
  }
  cleanup();
  return true;
}

}  // namespace

bool RunCudaMixedGradientCancellationForTesting(
    CudaMixedGradientCancellationTestResult* result,
    std::string* error) {
  if (result == nullptr || error == nullptr) return false;
  *result = CudaMixedGradientCancellationTestResult();
  error->clear();
  DevicePoseMeta* pose = nullptr;
  uint32_t* adjacency = nullptr;
  CudaCompactVisualOutput* fp64_records = nullptr;
  MixedVisualOutput* fp32_records = nullptr;
  MixedPoseBlockOutput* fp64_output = nullptr;
  MixedPoseBlockOutput* fp32_output = nullptr;
  cudaStream_t stream = nullptr;
  const auto cleanup = [&]() {
    if (stream != nullptr) cudaStreamDestroy(stream);
    cudaFree(fp32_output);
    cudaFree(fp64_output);
    cudaFree(fp32_records);
    cudaFree(fp64_records);
    cudaFree(adjacency);
    cudaFree(pose);
  };
  cudaError_t status = cudaSetDevice(0);
  const auto allocate = [&](auto** pointer, const size_t count) {
    using Pointer = typename std::remove_reference<decltype(*pointer)>::type;
    using Value = typename std::remove_pointer<Pointer>::type;
    return cudaMallocManaged(reinterpret_cast<void**>(pointer),
                             count * sizeof(Value)) == cudaSuccess;
  };
  if (status != cudaSuccess || !allocate(&pose, 1) ||
      !allocate(&adjacency, 2) || !allocate(&fp64_records, 2) ||
      !allocate(&fp32_records, 2) || !allocate(&fp64_output, 1) ||
      !allocate(&fp32_output, 1) ||
      (status = cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking)) !=
          cudaSuccess) {
    *error = "mixed gradient cancellation test allocation failed";
    cleanup();
    return false;
  }
  *pose = DevicePoseMeta{};
  pose->image_id = 1;
  pose->dimension = 3;
  pose->adjacency_end = 2;
  adjacency[0] = 0;
  adjacency[1] = 1;
  for (size_t index = 0; index < 2; ++index) {
    fp64_records[index] = CudaCompactVisualOutput{};
    fp32_records[index] = MixedVisualOutput{};
    fp64_records[index].status = 1;
    fp32_records[index].finite = 1;
    fp64_records[index].pose_jacobian[0] = 1.0;
    fp32_records[index].pose_jacobian[0] = 1.0f;
  }
  fp64_records[0].residual[0] = 100000001.0;
  fp64_records[1].residual[0] = -100000000.0;
  fp32_records[0].residual[0] =
      static_cast<float>(fp64_records[0].residual[0]);
  fp32_records[1].residual[0] =
      static_cast<float>(fp64_records[1].residual[0]);
  *fp64_output = MixedPoseBlockOutput{};
  *fp32_output = MixedPoseBlockOutput{};
  LayerBMixedPoseGradientFromFp32ForTestingKernel<<<1, 1, 0, stream>>>(
      pose, adjacency, fp32_records, fp32_output);
  LayerBMixedPoseGradientFromFp64Kernel<<<
      1, kLayerBPoseOptimizedThreads, 0, stream>>>(
      pose, adjacency, fp64_records, true,
      static_cast<uint8_t>(CudaLossMode::kTrivial), 1.0, fp64_output, 1);
  status = cudaGetLastError();
  if (status == cudaSuccess) status = cudaStreamSynchronize(stream);
  if (status != cudaSuccess) {
    *error = std::string("mixed gradient cancellation CUDA launch failed: ") +
             CudaErrorText(status);
    cleanup();
    return false;
  }
  result->fp32_record_gradient = fp32_output->gradient[0];
  result->fp64_record_gradient = fp64_output->gradient[0];
  result->fp32_record_path_calls = 1;
  result->fp64_record_path_calls = 1;
  cleanup();
  return true;
}

bool RunCudaMixedPoseDampingForTesting(
    CudaMixedPoseDampingTestResult* result,
    std::string* error) {
  if (result == nullptr || error == nullptr) return false;
  *result = CudaMixedPoseDampingTestResult();
  error->clear();
  DeviceSolvePoseMeta* metadata = nullptr;
  MixedPoseBlockOutput* pose = nullptr;
  double* double_schur = nullptr;
  cudaStream_t stream = nullptr;
  const auto cleanup = [&]() {
    if (stream != nullptr) cudaStreamDestroy(stream);
    cudaFree(double_schur);
    cudaFree(pose);
    cudaFree(metadata);
  };
  const auto allocate = [&](auto** pointer) {
    using Pointer = typename std::remove_reference<decltype(*pointer)>::type;
    using Value = typename std::remove_pointer<Pointer>::type;
    return cudaMallocManaged(reinterpret_cast<void**>(pointer),
                             sizeof(Value)) == cudaSuccess;
  };
  cudaError_t status = cudaSetDevice(0);
  if (status == cudaSuccess &&
      (!allocate(&metadata) || !allocate(&pose) || !allocate(&double_schur))) {
    status = cudaErrorMemoryAllocation;
  }
  if (status == cudaSuccess) {
    status = cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking);
  }
  if (status != cudaSuccess) {
    *error = "mixed pose damping test allocation failed";
    cleanup();
    return false;
  }
  *metadata = DeviceSolvePoseMeta{};
  metadata->dimension = 1;
  *pose = MixedPoseBlockOutput{};
  pose->dimension = 1;
  pose->hessian[0] = 228277288960.0f;
  pose->damping[0] = 100000000000.0f;
  const double lambda = 4.0432053555022774e-8;
  MixedInitializeDoubleSchurKernel<<<1, 1, 0, stream>>>(
      metadata, pose, lambda, double_schur, nullptr, 1, 1);
  status = cudaGetLastError();
  if (status == cudaSuccess) status = cudaStreamSynchronize(stream);
  if (status != cudaSuccess) {
    *error = std::string("mixed pose damping CUDA launch failed: ") +
             CudaErrorText(status);
    cleanup();
    return false;
  }
  result->undamped_float_diagonal = pose->hessian[0];
  result->legacy_float_damped_diagonal =
      pose->hessian[0] + static_cast<float>(lambda) * pose->damping[0];
  result->fp64_damped_diagonal = *double_schur;
  result->expected_fp64_damped_diagonal =
      static_cast<double>(pose->hessian[0]) +
      lambda * static_cast<double>(pose->damping[0]);
  result->lambda = lambda;
  result->damping = pose->damping[0];
  cleanup();
  return true;
}

bool RunCudaMixedLayerACastCompatibilityForTesting(std::string* error) {
  if (error == nullptr) return false;
  error->clear();
  CudaVisualOutput* full = nullptr;
  CudaCompactVisualOutput* compact = nullptr;
  MixedVisualOutput* from_full = nullptr;
  MixedVisualOutput* from_compact = nullptr;
  cudaStream_t stream = nullptr;
  const auto cleanup = [&]() {
    if (stream != nullptr) cudaStreamDestroy(stream);
    cudaFree(from_compact);
    cudaFree(from_full);
    cudaFree(compact);
    cudaFree(full);
  };
  const auto allocate = [&](auto** pointer) {
    using Pointer = typename std::remove_reference<decltype(*pointer)>::type;
    using Value = typename std::remove_pointer<Pointer>::type;
    return cudaMallocManaged(reinterpret_cast<void**>(pointer),
                             sizeof(Value)) == cudaSuccess;
  };
  cudaError_t status = cudaSetDevice(0);
  if (status == cudaSuccess &&
      (!allocate(&full) || !allocate(&compact) || !allocate(&from_full) ||
       !allocate(&from_compact))) {
    status = cudaErrorMemoryAllocation;
  }
  if (status == cudaSuccess) {
    status = cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking);
  }
  if (status != cudaSuccess) {
    *error = "mixed Layer A cast compatibility allocation failed";
    cleanup();
    return false;
  }
  *full = CudaVisualOutput{};
  full->finite = 1;
  for (uint32_t row = 0; row < 2; ++row) {
    full->residual[row] = 0.125 + row * 0.25;
    for (uint32_t i = 0; i < 3; ++i) {
      full->local_rotation_jacobian[row * 3 + i] =
          10.0 * row + i + 0.125;
      full->translation_jacobian[row * 3 + i] =
          20.0 * row + i + 0.25;
      full->point_jacobian[row * 3 + i] =
          30.0 * row + i + 0.5;
    }
  }
  *compact = CudaCompactVisualOutput{};
  compact->status = 1;
  for (uint32_t row = 0; row < 2; ++row) {
    compact->residual[row] = full->residual[row];
    for (uint32_t i = 0; i < 3; ++i) {
      compact->pose_jacobian[row * 6 + i] =
          full->local_rotation_jacobian[row * 3 + i];
      compact->pose_jacobian[row * 6 + 3 + i] =
          full->translation_jacobian[row * 3 + i];
      compact->point_jacobian[row * 3 + i] =
          full->point_jacobian[row * 3 + i];
    }
  }
  LayerAVisualMixedFromFullKernel<<<1, 1, 0, stream>>>(
      full, from_full, 1);
  LayerAVisualMixedFromCompactKernel<<<1, 1, 0, stream>>>(
      compact, from_compact, 1);
  status = cudaGetLastError();
  if (status == cudaSuccess) status = cudaStreamSynchronize(stream);
  if (status != cudaSuccess ||
      std::memcmp(from_full, from_compact, sizeof(MixedVisualOutput)) != 0) {
    *error = status == cudaSuccess
        ? "mixed full/compact Layer A casts differ"
        : std::string("mixed Layer A cast compatibility launch failed: ") +
              CudaErrorText(status);
    cleanup();
    return false;
  }
  cleanup();
  return true;
}

bool RunCudaSchurSolveBackwardErrorZeroDimensionForTesting(
    double* value,
    std::string* error) {
  if (value == nullptr || error == nullptr) return false;
  double* device_value = nullptr;
  cudaStream_t stream = nullptr;
  cudaError_t status = cudaMallocManaged(
      reinterpret_cast<void**>(&device_value), sizeof(double));
  if (status == cudaSuccess) {
    *device_value = 17.0;
    status = cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking);
  }
  if (status == cudaSuccess) {
    status = cudaMemsetAsync(device_value, 0, sizeof(double), stream);
  }
  if (status == cudaSuccess) status = cudaStreamSynchronize(stream);
  if (status == cudaSuccess) *value = *device_value;
  if (stream != nullptr) cudaStreamDestroy(stream);
  cudaFree(device_value);
  if (status != cudaSuccess) {
    *error = std::string("zero-dimension Schur residual test failed: ") +
             CudaErrorText(status);
    return false;
  }
  return true;
}

bool RunCudaMixedStableComponentForTesting(
    const Snapshot& snapshot,
    const double lambda,
    const size_t repeats,
    CudaMixedStableComponentResult* result,
    std::string* error) {
  if (result == nullptr || error == nullptr || repeats == 0 ||
      !std::isfinite(lambda) || lambda < 0.0) {
    if (error != nullptr) *error = "mixed component options are invalid";
    return false;
  }
  *result = CudaMixedStableComponentResult();
  error->clear();
  MixedStableComponentCapture reference;
  if (!RunMixedStableComponentPath(snapshot, lambda,
                                   CudaArithmeticPrecision::kFp64,
                                   &reference, error)) {
    result->error = *error;
    return false;
  }
  std::vector<double> mixed_times;
  MixedStableComponentCapture candidate;
  for (size_t repeat = 0; repeat < repeats; ++repeat) {
    MixedStableComponentCapture current;
    if (!RunMixedStableComponentPath(
            snapshot, lambda, CudaArithmeticPrecision::kFp32MixedStable,
            &current, error)) {
      result->error = *error;
      return false;
    }
    mixed_times.push_back(current.complete_milliseconds);
    if (repeat == 0) candidate = std::move(current);
  }
  std::sort(mixed_times.begin(), mixed_times.end());
  result->fp64_complete_milliseconds = reference.complete_milliseconds;
  result->mixed_complete_milliseconds =
      mixed_times[mixed_times.size() / 2];
  result->residual_jacobian = MixedStableErrorStatistics(
      candidate.layer_a_reference, candidate.layer_a_candidate,
      "residual_jacobian");
  result->robust_scale = MixedStableErrorStatistics(
      candidate.scale_reference, candidate.scale_candidate, "robust_scale");
  std::vector<double> reference_pose_hessian;
  std::vector<double> reference_pose_gradient;
  std::vector<double> reference_point_hessian;
  std::vector<double> reference_point_gradient;
  std::vector<double> reference_edges;
  std::vector<double> reference_jacobi;
  std::vector<double> candidate_pose_hessian;
  std::vector<double> candidate_pose_gradient;
  std::vector<double> candidate_point_hessian;
  std::vector<double> candidate_point_gradient;
  std::vector<double> candidate_edges;
  std::vector<double> candidate_jacobi;
  FlattenMixedStableLayerB(
      reference.layer_b, &reference_pose_hessian,
      &reference_pose_gradient, &reference_point_hessian,
      &reference_point_gradient, &reference_edges, &reference_jacobi);
  FlattenMixedStableLayerB(
      candidate.layer_b, &candidate_pose_hessian,
      &candidate_pose_gradient, &candidate_point_hessian,
      &candidate_point_gradient, &candidate_edges, &candidate_jacobi);
  result->pose_hessian = MixedStableErrorStatistics(
      reference_pose_hessian, candidate_pose_hessian, "pose_hessian");
  result->pose_gradient = MixedStableErrorStatistics(
      reference_pose_gradient, candidate_pose_gradient, "pose_gradient");
  result->point_hessian = MixedStableErrorStatistics(
      reference_point_hessian, candidate_point_hessian, "point_hessian");
  result->point_gradient = MixedStableErrorStatistics(
      reference_point_gradient, candidate_point_gradient, "point_gradient");
  result->edge_blocks = MixedStableErrorStatistics(
      reference_edges, candidate_edges, "edge_blocks");
  result->jacobi_damping = MixedStableErrorStatistics(
      reference_jacobi, candidate_jacobi, "jacobi_damping");
  result->point_inverse = MixedStableErrorStatistics(
      reference.point_inverse, candidate.point_inverse, "point_inverse");
  result->inverse_gradient = MixedStableErrorStatistics(
      reference.inverse_gradient, candidate.inverse_gradient,
      "inverse_gradient");
  std::vector<double> reference_transformed;
  std::vector<double> candidate_transformed;
  size_t transformed_offset = 0;
  for (const CudaEdgeBlockOutput& edge : reference.layer_b.edges) {
    const size_t count = edge.pose_dimension * 3;
    if (transformed_offset + count > reference.transformed_edge.size() ||
        transformed_offset + count > candidate.transformed_edge.size()) {
      *error = "mixed transformed edge capture bounds mismatch";
      result->error = *error;
      return false;
    }
    reference_transformed.insert(
        reference_transformed.end(),
        reference.transformed_edge.begin() + transformed_offset,
        reference.transformed_edge.begin() + transformed_offset + count);
    candidate_transformed.insert(
        candidate_transformed.end(),
        candidate.transformed_edge.begin() + transformed_offset,
        candidate.transformed_edge.begin() + transformed_offset + count);
    transformed_offset += 18;
  }
  result->transformed_edge = MixedStableErrorStatistics(
      reference_transformed, candidate_transformed, "transformed_edge");
  result->schur = MixedStableErrorStatistics(
      reference.layer_c.schur, candidate.layer_c.schur, "schur");
  std::vector<double> float_schur;
  if (!BenchmarkMixedSchurCandidates(
          candidate, lambda, repeats,
          &result->promoted_double_schur_complete_milliseconds,
          &result->f32_schur_then_cast_complete_milliseconds, &float_schur,
          error)) {
    result->error = *error;
    return false;
  }
  result->f32_schur_then_cast = MixedStableErrorStatistics(
      candidate.layer_c.schur, float_schur,
      "fp32_products_fp64_dense_accum");
  result->rhs = MixedStableErrorStatistics(
      reference.layer_c.rhs, candidate.layer_c.rhs, "rhs");
  result->camera_delta = MixedStableErrorStatistics(
      reference.layer_c.camera_delta, candidate.layer_c.camera_delta,
      "camera_delta");
  result->point_delta = MixedStableErrorStatistics(
      reference.layer_c.point_delta, candidate.layer_c.point_delta,
      "point_delta");
  result->trial_state = MixedStableErrorStatistics(
      FlattenMixedStableState(reference.layer_c.trial_state),
      FlattenMixedStableState(candidate.layer_c.trial_state), "trial_state");
  result->fp64_predicted_reduction = reference.layer_c.predicted_reduction;
  result->mixed_predicted_reduction = candidate.layer_c.predicted_reduction;
  result->fp64_backward_error = reference.layer_c.backward_error;
  result->mixed_backward_error = candidate.layer_c.backward_error;
  result->fp64_schur_solve_backward_error =
      reference.layer_c.schur_solve_backward_error;
  result->mixed_schur_solve_backward_error =
      candidate.layer_c.schur_solve_backward_error;
  result->fp64_trial_cost = reference.layer_c.trial_cost;
  result->mixed_trial_cost = candidate.layer_c.trial_cost;
  result->fp64_solver_info = reference.layer_c.runtime.cusolver_dev_info;
  result->mixed_solver_info = candidate.layer_c.runtime.cusolver_dev_info;
  const CudaPersistentDeviceRuntimeInfo& audit =
      candidate.runtime.persistent_device;
  result->mixed_dpotrf_calls = audit.dpotrf_calls;
  result->mixed_dpotrs_calls = audit.dpotrs_calls;
  result->mixed_spotrf_calls = audit.spotrf_calls;
  result->mixed_spotrs_calls = audit.spotrs_calls;
  result->mixed_serial_full_scan_kernel_count =
      audit.mixed_serial_full_scan_kernel_count;
  result->mixed_full_array_d2h_bytes = audit.mixed_full_array_d2h_bytes;
  result->mixed_post_initialize_allocation_calls =
      audit.post_initialize_allocation_calls;
  // Arena growth is permitted only during context Initialize. The component
  // capture has no post-ready grow call site.
  result->mixed_post_ready_arena_grow_calls = 0;
  result->mixed_float_buffer_bytes = audit.mixed_float_buffer_bytes;
  result->mixed_double_buffer_bytes = audit.mixed_double_buffer_bytes;
  result->mixed_schur_math_effective = audit.mixed_schur_math_effective;
  result->mixed_residual_jacobian_milliseconds =
      audit.mixed_residual_jacobian_milliseconds;
  result->mixed_hessian_milliseconds = audit.mixed_hessian_milliseconds;
  result->mixed_gradient_milliseconds = audit.mixed_gradient_milliseconds;
  result->mixed_point_inverse_milliseconds =
      audit.mixed_point_inverse_milliseconds;
  result->mixed_schur_milliseconds = audit.mixed_schur_milliseconds;
  result->mixed_rhs_milliseconds = audit.mixed_rhs_milliseconds;
  result->mixed_factorization_milliseconds =
      audit.schur_factorization_milliseconds;
  result->mixed_back_substitution_milliseconds =
      audit.mixed_back_substitution_milliseconds;
  result->mixed_diagnostics_milliseconds = audit.mixed_diagnostics_milliseconds;
  result->success = true;
  return true;
}

bool RunCudaHessianAssemblyComponentForTesting(
    const Snapshot& snapshot,
    const uint32_t segment_size,
    const size_t paired_samples,
    CudaHessianAssemblyComponentResult* result,
    std::string* error) {
  if (result == nullptr || error == nullptr || paired_samples == 0 ||
      (segment_size != 16 && segment_size != 32 && segment_size != 64)) {
    if (error != nullptr)
      *error = "fixed Hessian assembly component options are invalid";
    return false;
  }
  *result = CudaHessianAssemblyComponentResult();
  error->clear();
  CudaLayerBOptions options;
  options.layer_a.residual_order = CudaResidualOrder::kCanonical;
  options.reduction_mode = CudaReductionMode::kParallelDeterministic;
  options.cost_reduction_threads = 128;
  options.hessian_assembly_backend =
      CudaHessianAssemblyBackend::kPoseOwnedOptimizedReference;
  CudaLossMode component_loss_mode = CudaLossMode::kTrivial;
  double component_loss_scale = 1.0;
  if (!ResolveCudaLoss(snapshot, options, &component_loss_mode,
                       &component_loss_scale, error)) {
    return false;
  }
  GpuBaSolveContext context;
  if (!context.Initialize(snapshot, options, 0, 1, false,
                          CudaDeviceContextBackend::kLegacy,
                          HotKernelImplementation::kTransformed,
                          CudaSchurContributionBackend::kDirectTransformed, 0,
                          CudaExecutionProfile::kBaseline, false, nullptr,
                          error)) {
    return false;
  }
  CudaLayerBResult bootstrap;
  if (!RunCudaLayerBFromContext(
          &context, snapshot, options, nullptr,
          CudaFaultLogicalSite::kInitialLinearization, &bootstrap, nullptr,
          error)) {
    return false;
  }
  const LayerBTopology& base = context.BorrowLayerBTopology();
  std::vector<CudaVisualInput> visual_input;
  std::vector<CudaLidarInput> lidar_input;
  if (!BuildCudaLayerAInputs(snapshot, CudaResidualOrder::kCanonical,
                             &visual_input, &lidar_input, error)) {
    return false;
  }
  LayerBTopology atomic_topology = base;
  LayerBTopology segmented_topology = base;
  if (!BuildLayerBObservationExecutionPlan(
          visual_input, lidar_input,
          CudaHessianAssemblyBackend::kObservationAtomic, 0,
          &atomic_topology, error) ||
      !BuildLayerBObservationExecutionPlan(
          visual_input, lidar_input,
          CudaHessianAssemblyBackend::kObservationSegmented, segment_size,
          &segmented_topology, error)) {
    return false;
  }
  std::vector<CudaCompactVisualOutput> compact(bootstrap.layer_a.visual.size());
  for (size_t index = 0; index < compact.size(); ++index) {
    const CudaVisualOutput& source = bootstrap.layer_a.visual[index];
    CudaCompactVisualOutput& value = compact[index];
    value.residual[0] = source.residual[0];
    value.residual[1] = source.residual[1];
    for (size_t row = 0; row < 2; ++row) {
      for (size_t column = 0; column < 3; ++column) {
        value.pose_jacobian[row * 6 + column] =
            source.local_rotation_jacobian[row * 3 + column];
        value.pose_jacobian[row * 6 + 3 + column] =
            source.translation_jacobian[row * 3 + column];
        value.point_jacobian[row * 3 + column] =
            source.point_jacobian[row * 3 + column];
      }
    }
    value.status = source.finite ? 1u : 0u;
  }
  std::unordered_map<uint32_t, const ImageSnapshot*> images;
  for (const ImageSnapshot& image : snapshot.images)
    images.emplace(image.image_id, &image);
  std::vector<DevicePoseState> pose_state(base.poses.size());
  for (size_t i = 0; i < base.poses.size(); ++i) {
    const auto image = images.find(base.poses[i].image_id);
    if (image == images.end()) {
      *error = "fixed Hessian component pose state is missing";
      return false;
    }
    for (size_t j = 0; j < 4; ++j)
      pose_state[i].quaternion[j] = image->second->qvec[j];
  }

  result->visual_count = compact.size();
  result->lidar_count = bootstrap.layer_a.lidar.size();
  result->pose_count = base.poses.size();
  result->point_count = base.points.size();
  result->edge_count = base.edges.size();
  result->pose_segment_count = segmented_topology.pose_segments.size();
  result->point_segment_count = segmented_topology.point_segments.size();
  result->point_direct_count =
      segmented_topology.point_direct_indices.size();
  result->segment_size = segment_size;
  result->partial_workspace_bytes =
      segmented_topology.pose_segments.size() *
          kPoseAssemblyPartialScalars * sizeof(double) +
      segmented_topology.point_segments.size() *
          kPointAssemblyPartialScalars * sizeof(double);
  for (const DeviceVisualAssemblyBinding& binding :
       atomic_topology.atomic_visual_bindings) {
    if (binding.pose_index != kInvalidAssemblyTarget) {
      const uint64_t d = base.poses[binding.pose_index].dimension;
      result->atomic_pose_add_estimate += 2 * (d * d + d);
    }
    if (binding.point_index != kInvalidAssemblyTarget)
      result->atomic_point_add_estimate += 24;
    if (binding.edge_index != kInvalidAssemblyTarget) {
      const DeviceEdgeMeta& edge = base.edges[binding.edge_index];
      if (edge.adjacency_end - edge.adjacency_begin > 1)
        result->atomic_edge_add_estimate += 6 * edge.pose_dimension;
    }
  }
  for (const DeviceLidarAssemblyBinding& binding :
       atomic_topology.atomic_lidar_bindings) {
    if (binding.point_index != kInvalidAssemblyTarget)
      result->atomic_point_add_estimate += 12;
  }

  cudaError_t status = cudaSetDevice(options.layer_a.device);
  cudaStream_t stream = nullptr;
  cudaEvent_t begin = nullptr;
  cudaEvent_t end = nullptr;
  std::vector<void*> allocations;
  const auto cleanup = [&]() noexcept {
    if (end != nullptr) cudaEventDestroy(end);
    if (begin != nullptr) cudaEventDestroy(begin);
    for (auto it = allocations.rbegin(); it != allocations.rend(); ++it)
      cudaFree(*it);
    if (stream != nullptr) cudaStreamDestroy(stream);
  };
  const auto fail = [&](const std::string& message) {
    *error = message + ": " + CudaErrorText(status);
    cleanup();
    return false;
  };
  if (status != cudaSuccess ||
      (status = cudaStreamCreate(&stream)) != cudaSuccess ||
      (status = cudaEventCreate(&begin)) != cudaSuccess ||
      (status = cudaEventCreate(&end)) != cudaSuccess) {
    return fail("fixed Hessian component resource creation failed");
  }
  const auto allocate = [&](auto** pointer, const uint64_t count) {
    using Pointer = typename std::remove_reference<decltype(*pointer)>::type;
    using Value = typename std::remove_pointer<Pointer>::type;
    *pointer = nullptr;
    if (count == 0) return true;
    if (count > std::numeric_limits<size_t>::max() / sizeof(Value)) {
      status = cudaErrorInvalidValue;
      return false;
    }
    status = cudaMalloc(reinterpret_cast<void**>(pointer),
                        static_cast<size_t>(count) * sizeof(Value));
    if (status == cudaSuccess) allocations.push_back(*pointer);
    return status == cudaSuccess;
  };
  const auto upload = [&](auto* destination, const auto& source) {
    if (source.empty()) return true;
    status = cudaMemcpyAsync(destination, source.data(),
                             source.size() * sizeof(source[0]),
                             cudaMemcpyHostToDevice, stream);
    return status == cudaSuccess;
  };
  struct Outputs {
    CudaPoseBlockOutput* poses = nullptr;
    CudaPointBlockOutput* points = nullptr;
    CudaEdgeBlockOutput* edges = nullptr;
    double* gradient = nullptr;
    double* gradient_partials = nullptr;
    DeviceGradientMaxReduction* reduce_a = nullptr;
    DeviceGradientMaxReduction* reduce_b = nullptr;
  } reference, atomic, segmented;
  DevicePoseMeta* d_pose_meta = nullptr;
  DevicePointMeta* d_point_meta = nullptr;
  DeviceEdgeMeta* d_edge_meta = nullptr;
  uint32_t* d_pose_adjacency = nullptr;
  DevicePointAdjacency* d_point_adjacency = nullptr;
  uint32_t* d_edge_adjacency = nullptr;
  DevicePoseState* d_pose_state = nullptr;
  CudaCompactVisualOutput* d_visual = nullptr;
  CudaLidarOutput* d_lidar = nullptr;
  DeviceVisualAssemblyBinding* d_atomic_visual = nullptr;
  DeviceLidarAssemblyBinding* d_atomic_lidar = nullptr;
  DeviceAssemblySegment* d_pose_segments = nullptr;
  DeviceAssemblySegment* d_point_segments = nullptr;
  DeviceAssemblyTargetRange* d_pose_ranges = nullptr;
  DeviceAssemblyTargetRange* d_point_ranges = nullptr;
  uint32_t* d_point_direct = nullptr;
  double* d_pose_partials = nullptr;
  double* d_point_partials = nullptr;
  const size_t gradient_slots = base.poses.size() + base.points.size();
  const auto allocate_outputs = [&](Outputs* output) {
    return allocate(&output->poses, base.poses.size()) &&
           allocate(&output->points, base.points.size()) &&
           allocate(&output->edges, base.edges.size()) &&
           allocate(&output->gradient, 3) &&
           allocate(&output->gradient_partials, gradient_slots * 3) &&
           allocate(&output->reduce_a, std::max<size_t>(1, gradient_slots)) &&
           allocate(&output->reduce_b, std::max<size_t>(1, gradient_slots));
  };
  if (!allocate(&d_pose_meta, base.poses.size()) ||
      !allocate(&d_point_meta, base.points.size()) ||
      !allocate(&d_edge_meta, base.edges.size()) ||
      !allocate(&d_pose_adjacency, base.pose_adjacency.size()) ||
      !allocate(&d_point_adjacency, base.point_adjacency.size()) ||
      !allocate(&d_edge_adjacency, base.edge_adjacency.size()) ||
      !allocate(&d_pose_state, pose_state.size()) ||
      !allocate(&d_visual, compact.size()) ||
      !allocate(&d_lidar, bootstrap.layer_a.lidar.size()) ||
      !allocate(&d_atomic_visual,
                atomic_topology.atomic_visual_bindings.size()) ||
      !allocate(&d_atomic_lidar,
                atomic_topology.atomic_lidar_bindings.size()) ||
      !allocate(&d_pose_segments,
                segmented_topology.pose_segments.size()) ||
      !allocate(&d_point_segments,
                segmented_topology.point_segments.size()) ||
      !allocate(&d_pose_ranges,
                segmented_topology.pose_segment_ranges.size()) ||
      !allocate(&d_point_ranges,
                segmented_topology.point_segment_ranges.size()) ||
      !allocate(&d_point_direct,
                segmented_topology.point_direct_indices.size()) ||
      !allocate(&d_pose_partials,
                segmented_topology.pose_segments.size() *
                    kPoseAssemblyPartialScalars) ||
      !allocate(&d_point_partials,
                segmented_topology.point_segments.size() *
                    kPointAssemblyPartialScalars) ||
      !allocate_outputs(&reference) || !allocate_outputs(&atomic) ||
      !allocate_outputs(&segmented) ||
      !upload(d_pose_meta, base.poses) ||
      !upload(d_point_meta, base.points) ||
      !upload(d_edge_meta, base.edges) ||
      !upload(d_pose_adjacency, base.pose_adjacency) ||
      !upload(d_point_adjacency, base.point_adjacency) ||
      !upload(d_edge_adjacency, base.edge_adjacency) ||
      !upload(d_pose_state, pose_state) || !upload(d_visual, compact) ||
      !upload(d_lidar, bootstrap.layer_a.lidar) ||
      !upload(d_atomic_visual, atomic_topology.atomic_visual_bindings) ||
      !upload(d_atomic_lidar, atomic_topology.atomic_lidar_bindings) ||
      !upload(d_pose_segments, segmented_topology.pose_segments) ||
      !upload(d_point_segments, segmented_topology.point_segments) ||
      !upload(d_pose_ranges, segmented_topology.pose_segment_ranges) ||
      !upload(d_point_ranges, segmented_topology.point_segment_ranges) ||
      !upload(d_point_direct, segmented_topology.point_direct_indices) ||
      (status = cudaStreamSynchronize(stream)) != cudaSuccess) {
    return fail("fixed Hessian component allocation/upload failed");
  }
  constexpr int kBlockSize = 128;
  const auto blocks_for = [](const size_t count) {
    return static_cast<int>((count + kBlockSize - 1) / kBlockSize);
  };
  const auto gradient_summary = [&](Outputs& output) {
    if (gradient_slots == 0) {
      return cudaMemsetAsync(output.gradient, 0, 3 * sizeof(double), stream) ==
             cudaSuccess;
    }
    LayerBGradientNormPartialKernel<<<blocks_for(gradient_slots), kBlockSize,
                                      0, stream>>>(
        d_pose_meta, d_pose_state, output.poses, base.poses.size(),
        output.points, base.points.size(), output.gradient_partials);
    LaunchLayerBGradientMaxReduction(
        output.gradient_partials, gradient_slots, output.reduce_a,
        output.reduce_b, output.gradient, stream);
    return true;
  };
  enum class Backend { kReference, kAtomic, kSegmented };
  const auto run = [&](const Backend backend, double* milliseconds) {
    Outputs* output = backend == Backend::kReference
        ? &reference : (backend == Backend::kAtomic ? &atomic : &segmented);
    if ((status = cudaEventRecord(begin, stream)) != cudaSuccess) return false;
    if (backend == Backend::kReference) {
      if (!base.poses.empty()) {
        LayerBPoseOptimizedKernel<<<base.poses.size(),
            kLayerBPoseOptimizedThreads, 0, stream>>>(
            d_pose_meta, d_pose_adjacency, d_visual, true,
            static_cast<uint8_t>(component_loss_mode), component_loss_scale,
            nullptr,
            options.min_lm_diagonal, options.max_lm_diagonal,
            output->poses, base.poses.size());
      }
      if (!base.points.empty()) {
        LayerBPointKernel<<<blocks_for(base.points.size()), kBlockSize, 0,
                            stream>>>(
            d_point_meta, nullptr, d_point_adjacency, d_visual, true, d_lidar,
            static_cast<uint8_t>(component_loss_mode), component_loss_scale,
            nullptr,
            options.min_lm_diagonal, options.max_lm_diagonal,
            output->points, base.points.size());
      }
      if (!base.edges.empty()) {
        LayerBEdgeKernel<<<blocks_for(base.edges.size()), kBlockSize, 0,
                           stream>>>(
            d_edge_meta, d_edge_adjacency, d_pose_meta, d_visual, true,
            static_cast<uint8_t>(component_loss_mode), component_loss_scale,
            output->edges, base.edges.size());
      }
    } else if (backend == Backend::kAtomic) {
      if (!base.poses.empty())
        status = cudaMemsetAsync(output->poses, 0,
            base.poses.size() * sizeof(CudaPoseBlockOutput), stream);
      if (status == cudaSuccess && !base.points.empty())
        status = cudaMemsetAsync(output->points, 0,
            base.points.size() * sizeof(CudaPointBlockOutput), stream);
      if (status == cudaSuccess && !base.edges.empty())
        status = cudaMemsetAsync(output->edges, 0,
            base.edges.size() * sizeof(CudaEdgeBlockOutput), stream);
      if (status != cudaSuccess) return false;
      if (!compact.empty()) {
        LayerBObservationVisualAtomicKernel<<<blocks_for(compact.size()),
            kBlockSize, 0, stream>>>(
            d_atomic_visual, d_pose_meta, d_edge_meta, d_visual, true,
            static_cast<uint8_t>(component_loss_mode), component_loss_scale,
            output->poses, output->points, output->edges, compact.size());
      }
      if (!bootstrap.layer_a.lidar.empty()) {
        LayerBObservationLidarAtomicKernel<<<
            blocks_for(bootstrap.layer_a.lidar.size()), kBlockSize, 0,
            stream>>>(d_atomic_lidar, d_lidar,
                      static_cast<uint8_t>(component_loss_mode),
                      component_loss_scale,
                      output->points, bootstrap.layer_a.lidar.size());
      }
      if (!base.poses.empty())
        LayerBFinalizePoseKernel<<<blocks_for(base.poses.size()), kBlockSize,
                                   0, stream>>>(
            d_pose_meta, nullptr, options.min_lm_diagonal,
            options.max_lm_diagonal, output->poses, base.poses.size());
      if (!base.points.empty())
        LayerBFinalizePointKernel<<<blocks_for(base.points.size()), kBlockSize,
                                    0, stream>>>(
            d_point_meta, nullptr, options.min_lm_diagonal,
            options.max_lm_diagonal, output->points, base.points.size());
      if (!base.edges.empty())
        LayerBFinalizeEdgeKernel<<<blocks_for(base.edges.size()), kBlockSize,
                                   0, stream>>>(
            d_edge_meta, output->edges, base.edges.size());
    } else {
      if (!segmented_topology.point_direct_indices.empty()) {
        LayerBPointKernel<<<blocks_for(
            segmented_topology.point_direct_indices.size()), kBlockSize, 0,
            stream>>>(
            d_point_meta, d_point_direct, d_point_adjacency, d_visual, true,
            d_lidar, static_cast<uint8_t>(component_loss_mode),
            component_loss_scale,
            nullptr, options.min_lm_diagonal, options.max_lm_diagonal,
            output->points,
            segmented_topology.point_direct_indices.size());
      }
      if (!segmented_topology.pose_segments.empty())
        LayerBPoseSegmentPartialKernel<<<
            segmented_topology.pose_segments.size(),
            kObservationSegmentThreads, 0, stream>>>(
            d_pose_segments, d_pose_adjacency, d_pose_meta, d_visual, true,
            static_cast<uint8_t>(component_loss_mode), component_loss_scale,
            d_pose_partials, segmented_topology.pose_segments.size());
      if (!segmented_topology.point_segments.empty())
        LayerBPointSegmentPartialKernel<<<
            segmented_topology.point_segments.size(),
            kObservationSegmentThreads, 0, stream>>>(
            d_point_segments, d_point_adjacency, d_visual, true, d_lidar,
            static_cast<uint8_t>(component_loss_mode), component_loss_scale,
            d_point_partials, segmented_topology.point_segments.size());
      if (!base.edges.empty())
        LayerBEdgeKernel<<<blocks_for(base.edges.size()), kBlockSize, 0,
                           stream>>>(
            d_edge_meta, d_edge_adjacency, d_pose_meta, d_visual, true,
            static_cast<uint8_t>(component_loss_mode), component_loss_scale,
            output->edges, base.edges.size());
      if (!base.poses.empty())
        LayerBPoseSegmentMergeKernel<<<base.poses.size(),
            kObservationSegmentThreads, 0, stream>>>(
            d_pose_meta, d_pose_ranges, d_pose_partials,
            nullptr, options.min_lm_diagonal, options.max_lm_diagonal,
            output->poses, base.poses.size());
      if (!base.poses.empty())
        LayerBPoseGradientCompatibilityKernel<<<
            base.poses.size(), kLayerBPoseOptimizedThreads, 0, stream>>>(
            d_pose_meta, d_pose_adjacency, d_visual, true,
            static_cast<uint8_t>(component_loss_mode), component_loss_scale,
            output->poses, base.poses.size());
      if (!base.points.empty())
        LayerBPointSegmentMergeKernel<<<base.points.size(),
            kObservationSegmentThreads, 0, stream>>>(
            d_point_meta, d_point_ranges, d_point_partials, nullptr,
            options.min_lm_diagonal, options.max_lm_diagonal,
            output->points, base.points.size());
    }
    if (!gradient_summary(*output) ||
        (status = cudaGetLastError()) != cudaSuccess ||
        (status = cudaEventRecord(end, stream)) != cudaSuccess ||
        (status = cudaEventSynchronize(end)) != cudaSuccess) {
      return false;
    }
    float elapsed = 0.0f;
    if ((status = cudaEventElapsedTime(&elapsed, begin, end)) != cudaSuccess)
      return false;
    *milliseconds = elapsed;
    return true;
  };
  double ignored = 0.0;
  if (!run(Backend::kReference, &ignored) ||
      !run(Backend::kAtomic, &ignored) ||
      !run(Backend::kSegmented, &ignored)) {
    return fail("fixed Hessian component warm-up failed");
  }
  result->pose_owned_complete_milliseconds.reserve(paired_samples);
  result->atomic_complete_milliseconds.reserve(paired_samples);
  result->segmented_complete_milliseconds.reserve(paired_samples);
  for (size_t sample = 0; sample < paired_samples; ++sample) {
    double reference_ms = 0.0;
    double atomic_ms = 0.0;
    double segmented_ms = 0.0;
    const bool candidate_first = (sample % 2) != 0;
    if ((candidate_first &&
         (!run(Backend::kSegmented, &segmented_ms) ||
          !run(Backend::kAtomic, &atomic_ms) ||
          !run(Backend::kReference, &reference_ms))) ||
        (!candidate_first &&
         (!run(Backend::kReference, &reference_ms) ||
          !run(Backend::kAtomic, &atomic_ms) ||
          !run(Backend::kSegmented, &segmented_ms)))) {
      return fail("fixed Hessian component sample execution failed");
    }
    result->pose_owned_complete_milliseconds.push_back(reference_ms);
    result->atomic_complete_milliseconds.push_back(atomic_ms);
    result->segmented_complete_milliseconds.push_back(segmented_ms);
  }
  struct HostOutputs {
    std::vector<CudaPoseBlockOutput> poses;
    std::vector<CudaPointBlockOutput> points;
    std::vector<CudaEdgeBlockOutput> edges;
    std::array<double, 3> gradient{{0.0, 0.0, 0.0}};
  } host_reference, host_atomic, host_segmented;
  const auto download = [&](const Outputs& source, HostOutputs* destination) {
    destination->poses.resize(base.poses.size());
    destination->points.resize(base.points.size());
    destination->edges.resize(base.edges.size());
    return (destination->poses.empty() ||
            cudaMemcpy(destination->poses.data(), source.poses,
                       destination->poses.size() * sizeof(CudaPoseBlockOutput),
                       cudaMemcpyDeviceToHost) == cudaSuccess) &&
           (destination->points.empty() ||
            cudaMemcpy(destination->points.data(), source.points,
                       destination->points.size() * sizeof(CudaPointBlockOutput),
                       cudaMemcpyDeviceToHost) == cudaSuccess) &&
           (destination->edges.empty() ||
            cudaMemcpy(destination->edges.data(), source.edges,
                       destination->edges.size() * sizeof(CudaEdgeBlockOutput),
                       cudaMemcpyDeviceToHost) == cudaSuccess) &&
           cudaMemcpy(destination->gradient.data(), source.gradient,
                      3 * sizeof(double), cudaMemcpyDeviceToHost) ==
               cudaSuccess;
  };
  if (!download(reference, &host_reference) ||
      !download(atomic, &host_atomic) ||
      !download(segmented, &host_segmented)) {
    status = cudaErrorUnknown;
    return fail("fixed Hessian component result copy failed");
  }
  const auto flatten = [&](const HostOutputs& source,
                           std::vector<double>* values,
                           uint64_t* metadata_violations) {
    values->clear();
    for (size_t index = 0; index < source.poses.size(); ++index) {
      const CudaPoseBlockOutput& pose = source.poses[index];
      if (pose.image_id != base.poses[index].image_id ||
          pose.dimension != base.poses[index].dimension) {
        ++*metadata_violations;
      }
      for (uint32_t i = 0; i < pose.dimension * pose.dimension; ++i)
        values->push_back(pose.hessian[i]);
      for (uint32_t i = 0; i < pose.dimension; ++i) {
        values->push_back(pose.gradient[i]);
        values->push_back(pose.jacobi_scaling[i]);
        values->push_back(pose.damping[i]);
      }
    }
    for (size_t index = 0; index < source.points.size(); ++index) {
      const CudaPointBlockOutput& point = source.points[index];
      if (point.point3D_id != base.points[index].point3D_id)
        ++*metadata_violations;
      for (double value : point.hessian) values->push_back(value);
      for (double value : point.gradient) values->push_back(value);
      for (double value : point.jacobi_scaling) values->push_back(value);
      for (double value : point.damping) values->push_back(value);
    }
    for (size_t index = 0; index < source.edges.size(); ++index) {
      const CudaEdgeBlockOutput& edge = source.edges[index];
      if (edge.pose_index != base.edges[index].pose_index ||
          edge.point_index != base.edges[index].point_index ||
          edge.pose_dimension != base.edges[index].pose_dimension) {
        ++*metadata_violations;
      }
      for (uint32_t i = 0; i < edge.pose_dimension * 3; ++i)
        values->push_back(edge.value[i]);
    }
    for (double value : source.gradient) values->push_back(value);
  };
  std::vector<double> reference_values;
  std::vector<double> atomic_values;
  std::vector<double> segmented_values;
  uint64_t atomic_violations = 0;
  uint64_t segmented_violations = 0;
  uint64_t ignored_metadata = 0;
  flatten(host_reference, &reference_values, &ignored_metadata);
  flatten(host_atomic, &atomic_values, &atomic_violations);
  flatten(host_segmented, &segmented_values, &segmented_violations);
  const auto compare = [&](const std::vector<double>& candidate,
                           uint64_t* violations,
                           double* max_abs,
                           double* normalized_max,
                           double* normalized_frobenius,
                           uint64_t* first_index,
                           double* first_reference,
                           double* first_candidate) {
    long double reference_squared = 0.0L;
    long double difference_squared = 0.0L;
    double scale = 0.0;
    if (candidate.size() != reference_values.size()) {
      ++*violations;
      return;
    }
    for (size_t i = 0; i < reference_values.size(); ++i) {
      const double reference_value = reference_values[i];
      const double candidate_value = candidate[i];
      if (!std::isfinite(reference_value) || !std::isfinite(candidate_value)) {
        ++*violations;
        continue;
      }
      const double difference = std::abs(candidate_value - reference_value);
      if (difference > 1e-9 + 1e-9 *
              std::max(std::abs(reference_value),
                       std::abs(candidate_value))) {
        if (*violations == 0) {
          *first_index = i;
          *first_reference = reference_value;
          *first_candidate = candidate_value;
        }
        ++*violations;
      }
      *max_abs = std::max(*max_abs, difference);
      scale = std::max(scale, std::abs(reference_value));
      reference_squared += static_cast<long double>(reference_value) *
                           reference_value;
      difference_squared += static_cast<long double>(difference) * difference;
    }
    *normalized_max = *max_abs / std::max(1.0, scale);
    *normalized_frobenius = static_cast<double>(
        std::sqrt(difference_squared) /
        std::max<long double>(1.0L, std::sqrt(reference_squared)));
  };
  compare(atomic_values, &atomic_violations, &result->atomic_max_abs_error,
          &result->atomic_normalized_max_error,
          &result->atomic_normalized_frobenius_error,
          &result->atomic_first_violation_index,
          &result->atomic_first_violation_reference,
          &result->atomic_first_violation_candidate);
  compare(segmented_values, &segmented_violations,
          &result->segmented_max_abs_error,
          &result->segmented_normalized_max_error,
          &result->segmented_normalized_frobenius_error,
          &result->segmented_first_violation_index,
          &result->segmented_first_violation_reference,
          &result->segmented_first_violation_candidate);
  const std::vector<double> first_atomic_values = atomic_values;
  const std::vector<double> first_segmented_values = segmented_values;
  for (size_t repetition = 0; repetition < 10; ++repetition) {
    double repetition_ms = 0.0;
    HostOutputs repeated_atomic;
    HostOutputs repeated_segmented;
    if (!run(Backend::kAtomic, &repetition_ms) ||
        !run(Backend::kSegmented, &repetition_ms) ||
        !download(atomic, &repeated_atomic) ||
        !download(segmented, &repeated_segmented)) {
      status = cudaErrorUnknown;
      return fail("fixed Hessian component repeatability run failed");
    }
    std::vector<double> repeated_atomic_values;
    std::vector<double> repeated_segmented_values;
    uint64_t repeated_metadata = 0;
    flatten(repeated_atomic, &repeated_atomic_values, &repeated_metadata);
    flatten(repeated_segmented, &repeated_segmented_values,
            &repeated_metadata);
    if (repeated_atomic_values.size() != first_atomic_values.size() ||
        repeated_segmented_values.size() != first_segmented_values.size()) {
      status = cudaErrorUnknown;
      return fail("fixed Hessian component repeatability shape mismatch");
    }
    for (size_t i = 0; i < first_atomic_values.size(); ++i) {
      result->atomic_repeated_max_abs_error = std::max(
          result->atomic_repeated_max_abs_error,
          std::abs(repeated_atomic_values[i] - first_atomic_values[i]));
    }
    for (size_t i = 0; i < first_segmented_values.size(); ++i) {
      result->segmented_repeated_max_abs_error = std::max(
          result->segmented_repeated_max_abs_error,
          std::abs(repeated_segmented_values[i] -
                   first_segmented_values[i]));
    }
  }
  result->element_contract_violations_atomic = atomic_violations;
  result->element_contract_violations_segmented = segmented_violations;
  cleanup();
  return true;
}

bool RunCudaSchurContributionComponentForTesting(
    const Snapshot& snapshot,
    const uint32_t segment_size,
    const size_t paired_samples,
    CudaSchurContributionComponentResult* result,
    std::string* error) {
  if (result == nullptr || error == nullptr || paired_samples == 0 ||
      !ValidSchurSegmentSize(segment_size)) {
    if (error != nullptr)
      *error = "fixed Schur contribution component options are invalid";
    return false;
  }
  *result = CudaSchurContributionComponentResult();
  error->clear();
  CudaLayerBOptions options;
  options.layer_a.residual_order = CudaResidualOrder::kCanonical;
  options.reduction_mode = CudaReductionMode::kParallelDeterministic;
  options.cost_reduction_threads = 128;
  GpuBaSolveContext context;
  if (!context.Initialize(
          snapshot, options, 0, 1, true, CudaDeviceContextBackend::kLegacy,
          HotKernelImplementation::kReference,
          CudaSchurContributionBackend::kSegmentedTransformed, segment_size,
          CudaExecutionProfile::kBaseline, false, nullptr, error)) {
    return false;
  }
  CudaLayerBResult layer_b;
  if (!RunCudaLayerBFromContext(
          &context, snapshot, options, nullptr,
          CudaFaultLogicalSite::kInitialLinearization, &layer_b, nullptr,
          error)) {
    return false;
  }
  const LayerCTopology& topology = context.BorrowLayerCTopology();
  const size_t dimension = topology.pose_dimension;
  if (dimension == 0 || topology.segment_chunks.size() !=
                            topology.pair_chunks.size()) {
    *error = "fixed Schur contribution component topology is invalid";
    return false;
  }
  result->pose_dimension = dimension;
  result->pair_count = topology.pairs.size();
  result->contribution_count = topology.pair_contributions.size();
  result->direct_pair_count = topology.segment_direct_pair_indices.size();
  result->segmented_pair_count = topology.pairs.size() -
                                 topology.segment_direct_pair_indices.size();
  result->segment_count = topology.segments.size();
  result->max_segments_per_pair = topology.max_segments_per_pair;
  result->segment_size = topology.segment_size;
  result->partial_workspace_bytes =
      topology.segment_partial_workspace_bytes;

  const int device = options.layer_a.device;
  cudaError_t status = cudaSetDevice(device);
  if (status != cudaSuccess) {
    *error = "fixed Schur contribution component device selection failed";
    return false;
  }
  cudaStream_t stream = nullptr;
  cudaEvent_t begin = nullptr;
  cudaEvent_t end = nullptr;
  std::array<cudaEvent_t, 6> profile_event_storage{{
      nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}};
  SchurSegmentProfileEvents profile_events;
  std::vector<void*> allocations;
  const auto cleanup = [&]() noexcept {
    for (cudaEvent_t event : profile_event_storage) {
      if (event != nullptr) cudaEventDestroy(event);
    }
    if (end != nullptr) cudaEventDestroy(end);
    if (begin != nullptr) cudaEventDestroy(begin);
    for (auto it = allocations.rbegin(); it != allocations.rend(); ++it)
      cudaFree(*it);
    if (stream != nullptr) cudaStreamDestroy(stream);
  };
  const auto fail = [&](const std::string& message) {
    *error = message + ": " + CudaErrorText(status);
    cleanup();
    return false;
  };
  if ((status = cudaStreamCreate(&stream)) != cudaSuccess ||
      (status = cudaEventCreate(&begin)) != cudaSuccess ||
      (status = cudaEventCreate(&end)) != cudaSuccess) {
    return fail("fixed Schur contribution component resource creation failed");
  }
  if (topology.segment_chunks.size() == 1) {
    for (cudaEvent_t& event : profile_event_storage) {
      if ((status = cudaEventCreate(&event)) != cudaSuccess)
        return fail(
            "fixed Schur contribution profile event creation failed");
    }
    profile_events.short_direct_begin = profile_event_storage[0];
    profile_events.short_direct_end = profile_event_storage[1];
    profile_events.partial_begin = profile_event_storage[2];
    profile_events.partial_end = profile_event_storage[3];
    profile_events.merge_begin = profile_event_storage[4];
    profile_events.merge_end = profile_event_storage[5];
  }
  const auto allocate = [&](auto** pointer, const uint64_t count) {
    using Pointer = typename std::remove_reference<decltype(*pointer)>::type;
    using Value = typename std::remove_pointer<Pointer>::type;
    *pointer = nullptr;
    if (count == 0) return true;
    if (count > std::numeric_limits<size_t>::max() / sizeof(Value)) {
      status = cudaErrorInvalidValue;
      return false;
    }
    status = cudaMalloc(reinterpret_cast<void**>(pointer),
                        static_cast<size_t>(count) * sizeof(Value));
    if (status == cudaSuccess) allocations.push_back(*pointer);
    return status == cudaSuccess;
  };
  const auto upload = [&](auto* destination, const auto& source) {
    if (source.empty()) return true;
    status = cudaMemcpyAsync(destination, source.data(),
                             source.size() * sizeof(source[0]),
                             cudaMemcpyHostToDevice, stream);
    return status == cudaSuccess;
  };

  DeviceSolvePoseMeta* d_pose_meta = nullptr;
  DevicePairMeta* d_pairs = nullptr;
  DevicePairContribution* d_contributions = nullptr;
  uint32_t* d_direct_indices = nullptr;
  DeviceSchurSegment* d_segments = nullptr;
  DeviceSchurPairSegmentRange* d_pair_ranges = nullptr;
  CudaPoseBlockOutput* d_poses = nullptr;
  CudaPointBlockOutput* d_points = nullptr;
  CudaEdgeBlockOutput* d_edges = nullptr;
  double* d_point_inverse = nullptr;
  double* d_inverse_gradient = nullptr;
  uint8_t* d_point_status = nullptr;
  double* d_transformed_edges = nullptr;
  double* d_initial_schur = nullptr;
  double* d_direct_schur = nullptr;
  double* d_segmented_schur = nullptr;
  double* d_rhs = nullptr;
  double* d_partials = nullptr;
  const size_t matrix_count = dimension * dimension;
  const size_t partial_count = topology.segment_partial_workspace_bytes /
                               sizeof(double);
  if (!allocate(&d_pose_meta, topology.poses.size()) ||
      !allocate(&d_pairs, topology.pairs.size()) ||
      !allocate(&d_contributions, topology.pair_contributions.size()) ||
      !allocate(&d_direct_indices,
                topology.segment_direct_pair_indices.size()) ||
      !allocate(&d_segments, topology.segments.size()) ||
      !allocate(&d_pair_ranges, topology.segment_pair_ranges.size()) ||
      !allocate(&d_poses, layer_b.poses.size()) ||
      !allocate(&d_points, layer_b.points.size()) ||
      !allocate(&d_edges, layer_b.edges.size()) ||
      !allocate(&d_point_inverse, layer_b.points.size() * 9) ||
      !allocate(&d_inverse_gradient, layer_b.points.size() * 3) ||
      !allocate(&d_point_status, layer_b.points.size()) ||
      !allocate(&d_transformed_edges,
                layer_b.edges.size() * kTransformedEdgeStride) ||
      !allocate(&d_initial_schur, matrix_count) ||
      !allocate(&d_direct_schur, matrix_count) ||
      !allocate(&d_segmented_schur, matrix_count) ||
      !allocate(&d_rhs, dimension) || !allocate(&d_partials, partial_count) ||
      !upload(d_pose_meta, topology.poses) || !upload(d_pairs, topology.pairs) ||
      !upload(d_contributions, topology.pair_contributions) ||
      !upload(d_direct_indices, topology.segment_direct_pair_indices) ||
      !upload(d_segments, topology.segments) ||
      !upload(d_pair_ranges, topology.segment_pair_ranges) ||
      !upload(d_poses, layer_b.poses) || !upload(d_points, layer_b.points) ||
      !upload(d_edges, layer_b.edges)) {
    return fail("fixed Schur contribution component allocation/upload failed");
  }

  constexpr int block_size = 128;
  const auto blocks_for = [](const size_t count) {
    return static_cast<int>((count + block_size - 1) / block_size);
  };
  if (!layer_b.points.empty()) {
    LayerCPointFactorKernel<<<blocks_for(layer_b.points.size()), block_size, 0,
                              stream>>>(
        d_points, 1e-4, d_point_inverse, d_inverse_gradient, d_point_status,
        layer_b.points.size());
  }
  if (!layer_b.edges.empty()) {
    LayerCTransformEdgeKernel<<<layer_b.edges.size(), kTransformedEdgeThreads,
                                0, stream>>>(
        d_edges, d_point_inverse, d_transformed_edges, layer_b.edges.size());
  }
  const size_t zero_count = std::max(matrix_count, dimension);
  LayerCZeroSchurKernel<<<blocks_for(zero_count), block_size, 0, stream>>>(
      d_initial_schur, d_rhs, dimension);
  if (!topology.poses.empty()) {
    LayerCInitializePoseKernel<<<topology.poses.size(), 36, 0, stream>>>(
        d_pose_meta, d_poses, 1e-4, d_initial_schur, d_rhs, dimension,
        topology.poses.size());
  }
  std::vector<uint8_t> point_status(layer_b.points.size());
  if (!point_status.empty()) {
    status = cudaMemcpyAsync(point_status.data(), d_point_status,
                             point_status.size(), cudaMemcpyDeviceToHost,
                             stream);
  }
  if (status != cudaSuccess ||
      (status = cudaStreamSynchronize(stream)) != cudaSuccess) {
    return fail("fixed Schur contribution component bootstrap failed");
  }
  if (std::find(point_status.begin(), point_status.end(), uint8_t{1}) !=
      point_status.end()) {
    status = cudaErrorUnknown;
    return fail("fixed Schur contribution point factorization failed");
  }

  CudaLayerCRuntimeInfo direct_runtime;
  CudaLayerCRuntimeInfo segmented_runtime;
  std::vector<double> first_segmented;
  std::vector<double> direct_schur(matrix_count);
  std::vector<double> segmented_schur(matrix_count);
  const auto run_one = [&](const bool segmented, double* milliseconds) {
    double* output = segmented ? d_segmented_schur : d_direct_schur;
    status = cudaMemcpyAsync(output, d_initial_schur,
                             matrix_count * sizeof(double),
                             cudaMemcpyDeviceToDevice, stream);
    if (status != cudaSuccess ||
        (status = cudaEventRecord(begin, stream)) != cudaSuccess) {
      return false;
    }
    std::string launch_error;
    const bool launched = segmented
        ? LaunchLayerCSegmentedSchurPairChunks(
              topology, device, d_pairs, d_direct_indices, d_segments,
              d_pair_ranges, d_contributions, d_pose_meta, d_edges,
              d_transformed_edges, d_partials, output, dimension, stream,
              &segmented_runtime, nullptr, &launch_error,
              topology.segment_chunks.size() == 1 ? &profile_events : nullptr)
        : LaunchLayerCSchurPairChunks(
              topology, HotKernelImplementation::kTransformed, device,
              d_pairs, d_contributions, d_pose_meta, d_edges,
              d_point_inverse, d_transformed_edges, output, dimension, stream,
              &direct_runtime, nullptr, &launch_error);
    if (!launched) {
      *error = launch_error;
      status = cudaErrorLaunchFailure;
      return false;
    }
    if ((status = cudaEventRecord(end, stream)) != cudaSuccess ||
        (status = cudaEventSynchronize(end)) != cudaSuccess) {
      return false;
    }
    float elapsed = 0.0f;
    if ((status = cudaEventElapsedTime(&elapsed, begin, end)) != cudaSuccess)
      return false;
    *milliseconds = elapsed;
    if (segmented && topology.segment_chunks.size() == 1) {
      float short_direct = 0.0f;
      float partial = 0.0f;
      float merge = 0.0f;
      if ((status = cudaEventElapsedTime(
               &short_direct, profile_events.short_direct_begin,
               profile_events.short_direct_end)) != cudaSuccess ||
          (status = cudaEventElapsedTime(
               &partial, profile_events.partial_begin,
               profile_events.partial_end)) != cudaSuccess ||
          (status = cudaEventElapsedTime(
               &merge, profile_events.merge_begin,
               profile_events.merge_end)) != cudaSuccess) {
        return false;
      }
      result->segmented_short_direct_milliseconds.push_back(short_direct);
      result->segmented_partial_milliseconds.push_back(partial);
      result->segmented_merge_milliseconds.push_back(merge);
    }
    return true;
  };

  result->direct_complete_milliseconds.reserve(paired_samples);
  result->segmented_complete_milliseconds.reserve(paired_samples);
  for (size_t sample = 0; sample < paired_samples; ++sample) {
    double direct_ms = 0.0;
    double segmented_ms = 0.0;
    const bool candidate_first = (sample % 2) != 0;
    if ((candidate_first &&
         (!run_one(true, &segmented_ms) || !run_one(false, &direct_ms))) ||
        (!candidate_first &&
         (!run_one(false, &direct_ms) || !run_one(true, &segmented_ms)))) {
      if (error->empty())
        *error = std::string(
                     "fixed Schur contribution component execution failed: ") +
                 CudaErrorText(status);
      cleanup();
      return false;
    }
    result->direct_complete_milliseconds.push_back(direct_ms);
    result->segmented_complete_milliseconds.push_back(segmented_ms);
    if (sample == 0) {
      status = cudaMemcpy(direct_schur.data(), d_direct_schur,
                          matrix_count * sizeof(double),
                          cudaMemcpyDeviceToHost);
      if (status == cudaSuccess) {
        status = cudaMemcpy(segmented_schur.data(), d_segmented_schur,
                            matrix_count * sizeof(double),
                            cudaMemcpyDeviceToHost);
      }
      first_segmented = segmented_schur;
    } else {
      std::vector<double> repeated(matrix_count);
      status = cudaMemcpy(repeated.data(), d_segmented_schur,
                          matrix_count * sizeof(double),
                          cudaMemcpyDeviceToHost);
      if (status == cudaSuccess) {
        for (size_t i = 0; i < repeated.size(); ++i) {
          result->repeated_candidate_max_abs_error = std::max(
              result->repeated_candidate_max_abs_error,
              std::abs(repeated[i] - first_segmented[i]));
        }
      }
    }
    if (status != cudaSuccess) {
      return fail("fixed Schur contribution component result copy failed");
    }
  }

  long double reference_squared = 0.0L;
  long double difference_squared = 0.0L;
  double reference_max = 0.0;
  for (size_t i = 0; i < matrix_count; ++i) {
    if (!std::isfinite(direct_schur[i]) ||
        !std::isfinite(segmented_schur[i])) {
      status = cudaErrorUnknown;
      return fail("fixed Schur contribution produced a nonfinite value");
    }
    const double difference = std::abs(segmented_schur[i] - direct_schur[i]);
    const double element_limit =
        1e-10 + 5e-11 * std::max(std::abs(direct_schur[i]),
                                  std::abs(segmented_schur[i]));
    if (difference > element_limit) ++result->element_contract_violations;
    result->max_abs_error = std::max(result->max_abs_error, difference);
    reference_max = std::max(reference_max, std::abs(direct_schur[i]));
    reference_squared += static_cast<long double>(direct_schur[i]) *
                         static_cast<long double>(direct_schur[i]);
    difference_squared += static_cast<long double>(difference) *
                          static_cast<long double>(difference);
  }
  result->normalized_max_error =
      result->max_abs_error / std::max(1.0, reference_max);
  result->normalized_frobenius_error = static_cast<double>(
      std::sqrt(difference_squared) /
      std::max<long double>(1.0L, std::sqrt(reference_squared)));
  result->coverage_violations = segmented_runtime.coverage_violations;
  cleanup();
  return true;
}

bool RunCudaDiagnosticReductionForTesting(
    const std::vector<uint8_t>& status,
    const std::vector<std::array<double, 2>>& norm_partials,
    const std::vector<double>& maxima,
    CudaDiagnosticReductionTestResult* result,
    std::string* error) {
  if (result == nullptr || error == nullptr) return false;
  *result = CudaDiagnosticReductionTestResult();
  error->clear();
  cudaStream_t stream = nullptr;
  uint8_t* d_status = nullptr;
  double* d_norm = nullptr;
  DeviceMaxReduction* d_maxima = nullptr;
  CudaPointBlockOutput* d_diagonal_points = nullptr;
  DeviceLmScalarPacket* d_packet = nullptr;
  DeviceStatusReduction* d_status_a = nullptr;
  DeviceStatusReduction* d_status_b = nullptr;
  DeviceSum2Reduction* d_sum_a = nullptr;
  DeviceSum2Reduction* d_sum_b = nullptr;
  DeviceMaxReduction* d_max_a = nullptr;
  DeviceMaxReduction* d_max_b = nullptr;
  DeviceMinMaxReduction* d_minmax_a = nullptr;
  DeviceMinMaxReduction* d_minmax_b = nullptr;
  const size_t status_capacity = std::max<size_t>(
      1, DiagnosticReductionBlockCount(status.size()));
  const size_t norm_capacity = std::max<size_t>(
      1, DiagnosticReductionBlockCount(norm_partials.size()));
  const size_t max_capacity = std::max<size_t>(
      1, DiagnosticReductionBlockCount(maxima.size()));
  const size_t diagonal_point_count = (maxima.size() + 2) / 3;
  const size_t minmax_capacity = std::max<size_t>(
      1, DiagnosticReductionBlockCount(diagonal_point_count * 3));
  std::vector<DeviceMaxReduction> host_maxima(maxima.size());
  for (size_t i = 0; i < maxima.size(); ++i) {
    host_maxima[i].maximum = maxima[i];
    host_maxima[i].finite = std::isfinite(maxima[i]) ? 1 : 0;
  }
  std::vector<CudaPointBlockOutput> host_diagonal_points(
      diagonal_point_count);
  for (size_t point = 0; point < diagonal_point_count; ++point) {
    for (size_t diagonal = 0; diagonal < 3; ++diagonal) {
      const size_t index = point * 3 + diagonal;
      const double source = index < maxima.size()
                                ? maxima[index]
                                : maxima.back();
      host_diagonal_points[point].damping[diagonal] = source * source;
      host_diagonal_points[point].jacobi_scaling[diagonal] = 1.0;
    }
  }
  const auto cleanup = [&]() {
    if (d_minmax_b != nullptr) cudaFree(d_minmax_b);
    if (d_minmax_a != nullptr) cudaFree(d_minmax_a);
    if (d_max_b != nullptr) cudaFree(d_max_b);
    if (d_max_a != nullptr) cudaFree(d_max_a);
    if (d_sum_b != nullptr) cudaFree(d_sum_b);
    if (d_sum_a != nullptr) cudaFree(d_sum_a);
    if (d_status_b != nullptr) cudaFree(d_status_b);
    if (d_status_a != nullptr) cudaFree(d_status_a);
    if (d_packet != nullptr) cudaFree(d_packet);
    if (d_diagonal_points != nullptr) cudaFree(d_diagonal_points);
    if (d_maxima != nullptr) cudaFree(d_maxima);
    if (d_norm != nullptr) cudaFree(d_norm);
    if (d_status != nullptr) cudaFree(d_status);
    if (stream != nullptr) cudaStreamDestroy(stream);
  };
  cudaError_t cuda_status = cudaStreamCreateWithFlags(
      &stream, cudaStreamNonBlocking);
  const auto allocate = [&](void** pointer, const size_t bytes) {
    if (cuda_status == cudaSuccess)
      cuda_status = cudaMalloc(pointer, std::max<size_t>(1, bytes));
  };
  allocate(reinterpret_cast<void**>(&d_status), status.size());
  allocate(reinterpret_cast<void**>(&d_norm),
           norm_partials.size() * 2 * sizeof(double));
  allocate(reinterpret_cast<void**>(&d_maxima),
           host_maxima.size() * sizeof(DeviceMaxReduction));
  allocate(reinterpret_cast<void**>(&d_diagonal_points),
           host_diagonal_points.size() * sizeof(CudaPointBlockOutput));
  allocate(reinterpret_cast<void**>(&d_packet), sizeof(DeviceLmScalarPacket));
  allocate(reinterpret_cast<void**>(&d_status_a),
           status_capacity * sizeof(DeviceStatusReduction));
  allocate(reinterpret_cast<void**>(&d_status_b),
           status_capacity * sizeof(DeviceStatusReduction));
  allocate(reinterpret_cast<void**>(&d_sum_a),
           norm_capacity * sizeof(DeviceSum2Reduction));
  allocate(reinterpret_cast<void**>(&d_sum_b),
           norm_capacity * sizeof(DeviceSum2Reduction));
  allocate(reinterpret_cast<void**>(&d_max_a),
           max_capacity * sizeof(DeviceMaxReduction));
  allocate(reinterpret_cast<void**>(&d_max_b),
           max_capacity * sizeof(DeviceMaxReduction));
  allocate(reinterpret_cast<void**>(&d_minmax_a),
           minmax_capacity * sizeof(DeviceMinMaxReduction));
  allocate(reinterpret_cast<void**>(&d_minmax_b),
           minmax_capacity * sizeof(DeviceMinMaxReduction));
  if (cuda_status == cudaSuccess && !status.empty()) {
    cuda_status = cudaMemcpyAsync(d_status, status.data(), status.size(),
                                  cudaMemcpyHostToDevice, stream);
  }
  if (cuda_status == cudaSuccess && !norm_partials.empty()) {
    cuda_status = cudaMemcpyAsync(
        d_norm, norm_partials.data(),
        norm_partials.size() * 2 * sizeof(double), cudaMemcpyHostToDevice,
        stream);
  }
  if (cuda_status == cudaSuccess && !host_maxima.empty()) {
    cuda_status = cudaMemcpyAsync(
        d_maxima, host_maxima.data(),
        host_maxima.size() * sizeof(DeviceMaxReduction),
        cudaMemcpyHostToDevice, stream);
  }
  if (cuda_status == cudaSuccess && !host_diagonal_points.empty()) {
    cuda_status = cudaMemcpyAsync(
        d_diagonal_points, host_diagonal_points.data(),
        host_diagonal_points.size() * sizeof(CudaPointBlockOutput),
        cudaMemcpyHostToDevice, stream);
  }
  uint64_t ignored_calls = 0;
  if (cuda_status == cudaSuccess) {
    CudaLinearizationIdentity identity;
    DeviceLmPacketResetKernel<<<1, 1, 0, stream>>>(
        d_packet, 1, identity, 1, 1, 1);
    LaunchPointStatusReduction(d_status, status.size(), d_status_a, d_status_b,
                               d_packet, stream, &ignored_calls);
    LaunchStateNormReduction(d_norm, norm_partials.size(), d_sum_a, d_sum_b,
                             d_packet, stream, &ignored_calls);
    LaunchMaxReduction(d_maxima, maxima.size(), d_max_a, d_max_b, d_packet,
                       stream, &ignored_calls);
    LaunchLmDiagonalReduction(
        nullptr, 0, d_diagonal_points, diagonal_point_count, d_minmax_a,
        d_minmax_b, d_packet, stream, &ignored_calls);
    cuda_status = cudaGetLastError();
  }
  DeviceLmScalarPacket packet{};
  if (cuda_status == cudaSuccess) {
    cuda_status = cudaMemcpyAsync(&packet, d_packet, sizeof(packet),
                                  cudaMemcpyDeviceToHost, stream);
  }
  if (cuda_status == cudaSuccess) cuda_status = cudaStreamSynchronize(stream);
  cleanup();
  if (cuda_status != cudaSuccess) {
    *error = std::string("diagnostic reduction self-test failed: ") +
             CudaErrorText(cuda_status);
    return false;
  }
  result->status_count = packet.point_failure_count;
  result->first_status_index = packet.first_point_failure;
  result->first_norm = packet.state_norm;
  result->second_norm = packet.step_norm;
  result->maximum = packet.symmetry_error;
  result->diagonal_minimum = packet.lm_diagonal_base_min;
  result->diagonal_maximum = packet.lm_diagonal_base_max;
  result->finite_flags = packet.finite_flags;
  result->reduction_status = packet.reduction_status;
  return true;
}

bool ComputeCudaStateHashForTesting(const Snapshot& snapshot,
                                    const bool legacy,
                                    std::string* digest,
                                    CudaStateHashAudit* audit,
                                    std::string* error) {
  if (digest == nullptr || audit == nullptr || error == nullptr) return false;
  *audit = CudaStateHashAudit();
  digest->clear();
  error->clear();
  if (legacy) {
    *digest = LegacyStateHash(snapshot);
    return true;
  }
  StateHashLayout layout;
  if (!BuildStateHashLayout(snapshot, &layout, audit, error)) return false;
  ++audit->current.requests;
  return LinearStateHash(snapshot, layout, &audit->current, digest, error);
}

namespace {

void AppendAuditU64(std::string* data, const uint64_t value) {
  for (int shift = 0; shift < 64; shift += 8) {
    data->push_back(static_cast<char>((value >> shift) & 0xffu));
  }
}

void AppendAuditU32(std::string* data, const uint32_t value) {
  for (int shift = 0; shift < 32; shift += 8) {
    data->push_back(static_cast<char>((value >> shift) & 0xffu));
  }
}

void AppendAuditI32(std::string* data, const int32_t value) {
  AppendAuditU32(data, static_cast<uint32_t>(value));
}

void AppendAuditU8(std::string* data, const uint8_t value) {
  data->push_back(static_cast<char>(value));
}

void AppendAuditBool(std::string* data, const bool value) {
  AppendAuditU8(data, value ? 1u : 0u);
}

void AppendAuditDouble(std::string* data, const double value) {
  uint64_t bits = 0;
  std::memcpy(&bits, &value, sizeof(bits));
  AppendAuditU64(data, bits);
}

void AppendAuditString(std::string* data, const std::string& value) {
  AppendAuditU64(data, value.size());
  data->append(value);
}

bool SameDoubleBits(const double lhs, const double rhs) {
  uint64_t lhs_bits = 0;
  uint64_t rhs_bits = 0;
  std::memcpy(&lhs_bits, &lhs, sizeof(lhs_bits));
  std::memcpy(&rhs_bits, &rhs, sizeof(rhs_bits));
  return lhs_bits == rhs_bits;
}

template <typename T, typename Id>
std::vector<const T*> SortedById(const std::vector<T>& values, Id id) {
  std::vector<const T*> sorted;
  sorted.reserve(values.size());
  for (const T& value : values) sorted.push_back(&value);
  std::sort(sorted.begin(), sorted.end(), [&](const T* lhs, const T* rhs) {
    return id(*lhs) < id(*rhs);
  });
  return sorted;
}

void AppendSnapshotParameters(const Snapshot& snapshot, std::string* data) {
  const auto cameras = SortedById(
      snapshot.cameras,
      [](const CameraSnapshot& value) { return value.camera_id; });
  AppendAuditU64(data, cameras.size());
  for (const CameraSnapshot* camera : cameras) {
    AppendAuditU32(data, camera->camera_id);
    AppendAuditU64(data, camera->params.size());
    for (double value : camera->params) AppendAuditDouble(data, value);
  }
  const auto images = SortedById(
      snapshot.images,
      [](const ImageSnapshot& value) { return value.image_id; });
  AppendAuditU64(data, images.size());
  for (const ImageSnapshot* image : images) {
    AppendAuditU32(data, image->image_id);
    AppendAuditU32(data, image->camera_id);
    for (double value : image->qvec) AppendAuditDouble(data, value);
    for (double value : image->tvec) AppendAuditDouble(data, value);
  }
  const auto points = SortedById(
      snapshot.points,
      [](const PointSnapshot& value) { return value.point3D_id; });
  AppendAuditU64(data, points.size());
  for (const PointSnapshot* point : points) {
    AppendAuditU64(data, point->point3D_id);
    for (double value : point->xyz) AppendAuditDouble(data, value);
  }
}

void AppendOrderEntry(const OrderEntrySnapshot& entry, std::string* data) {
  AppendAuditU64(data, entry.source_index);
  AppendAuditU8(data, static_cast<uint8_t>(entry.residual_kind));
  AppendAuditU32(data, entry.image_id);
  AppendAuditU32(data, entry.point2D_idx);
  AppendAuditU64(data, entry.point3D_id);
}

void AppendSnapshotTopology(const Snapshot& snapshot, std::string* data) {
  AppendAuditU64(data, snapshot.cameras.size());
  for (const CameraSnapshot& camera : snapshot.cameras) {
    AppendAuditU32(data, camera.camera_id);
    AppendAuditI32(data, camera.model_id);
    AppendAuditU64(data, camera.width);
    AppendAuditU64(data, camera.height);
    AppendAuditBool(data, camera.constant);
    AppendAuditU64(data, camera.params.size());
  }
  AppendAuditU64(data, snapshot.images.size());
  for (const ImageSnapshot& image : snapshot.images) {
    AppendAuditU32(data, image.image_id);
    AppendAuditU32(data, image.camera_id);
    AppendAuditBool(data, image.selected);
    AppendAuditBool(data, image.pose_constant);
    AppendAuditBool(data, image.has_pose_parameter_blocks);
    AppendAuditU8(data, image.constant_tvec_mask);
  }
  AppendAuditU64(data, snapshot.points.size());
  for (const PointSnapshot& point : snapshot.points) {
    AppendAuditU64(data, point.point3D_id);
    AppendAuditBool(data, point.constant);
    AppendAuditU8(data, point.config_role);
    AppendAuditBool(data, point.has_search_range);
    AppendAuditDouble(data, point.search_range);
  }
  AppendAuditU64(data, snapshot.observations.size());
  for (const ObservationSnapshot& observation : snapshot.observations) {
    AppendAuditU64(data, observation.source_index);
    AppendAuditU32(data, observation.image_id);
    AppendAuditU32(data, observation.point2D_idx);
    AppendAuditU64(data, observation.point3D_id);
    AppendAuditBool(data, observation.pose_constant);
    for (double value : observation.xy) AppendAuditDouble(data, value);
  }
  AppendAuditU64(data, snapshot.tracks.size());
  for (const TrackElementSnapshot& track : snapshot.tracks) {
    AppendAuditU64(data, track.point3D_id);
    AppendAuditU32(data, track.image_id);
    AppendAuditU32(data, track.point2D_idx);
  }
  AppendAuditU64(data, snapshot.lidar.size());
  for (const LidarSnapshot& lidar : snapshot.lidar) {
    AppendAuditU64(data, lidar.source_index);
    AppendAuditU64(data, lidar.point3D_id);
    AppendAuditU8(data, lidar.lidar_type);
    AppendAuditBool(data, lidar.has_search_range);
    AppendAuditDouble(data, lidar.search_range);
    AppendAuditDouble(data, lidar.weight);
    for (double value : lidar.lidar_xyz) AppendAuditDouble(data, value);
    for (double value : lidar.plane) AppendAuditDouble(data, value);
  }
  AppendAuditU64(data, snapshot.parameter_blocks_source_order.size());
  for (const ParameterBlockSnapshot& block :
       snapshot.parameter_blocks_source_order) {
    AppendAuditU64(data, block.source_index);
    AppendAuditU8(data, static_cast<uint8_t>(block.kind));
    AppendAuditU64(data, block.entity_id);
    AppendAuditU32(data, block.ambient_size);
    AppendAuditU32(data, block.tangent_size);
    AppendAuditBool(data, block.constant);
  }
  AppendAuditU64(data, snapshot.parameter_blocks_canonical_order.size());
  for (uint64_t value : snapshot.parameter_blocks_canonical_order)
    AppendAuditU64(data, value);
  AppendAuditU64(data, snapshot.source_insertion_order.size());
  for (const OrderEntrySnapshot& entry : snapshot.source_insertion_order)
    AppendOrderEntry(entry, data);
  AppendAuditU64(data, snapshot.canonical_order.size());
  for (const OrderEntrySnapshot& entry : snapshot.canonical_order)
    AppendOrderEntry(entry, data);
}

void AppendLmIterationDecision(const CudaLmIteration& iteration,
                               std::string* data) {
  AppendAuditI32(data, iteration.iteration);
  AppendAuditDouble(data, iteration.cost_before);
  AppendAuditDouble(data, iteration.trial_cost);
  AppendAuditDouble(data, iteration.cost_after);
  AppendAuditDouble(data, iteration.projected_gradient_max_norm);
  AppendAuditDouble(data, iteration.scaled_gradient_norm);
  AppendAuditDouble(data, iteration.radius_before);
  AppendAuditDouble(data, iteration.radius_after);
  AppendAuditDouble(data, iteration.lambda_before);
  AppendAuditDouble(data, iteration.lambda_after);
  AppendAuditDouble(data, iteration.lm_diagonal_min);
  AppendAuditDouble(data, iteration.lm_diagonal_max);
  AppendAuditDouble(data, iteration.predicted_reduction);
  AppendAuditDouble(data, iteration.actual_reduction);
  AppendAuditDouble(data, iteration.rho);
  AppendAuditDouble(data, iteration.function_metric);
  AppendAuditDouble(data, iteration.parameter_metric);
  AppendAuditDouble(data, iteration.step_norm);
  AppendAuditDouble(data, iteration.backward_error);
  AppendAuditBool(data, iteration.factorization_success);
  AppendAuditBool(data, iteration.step_valid);
  AppendAuditBool(data, iteration.trial_finite);
  AppendAuditBool(data, iteration.accepted);
  AppendAuditBool(data, iteration.invalid);
  AppendAuditString(data, iteration.termination_reason);
}

std::string DecisionBitwiseData(const CudaFullLmResult& result) {
  std::string data;
  AppendAuditBool(&data, result.success);
  AppendAuditString(&data, result.error);
  AppendAuditU8(&data, static_cast<uint8_t>(result.termination_type));
  AppendAuditString(&data, result.termination_reason);
  AppendAuditDouble(&data, result.initial_cost);
  AppendAuditDouble(&data, result.final_cost);
  AppendAuditDouble(&data, result.initial_projected_gradient_max_norm);
  AppendAuditDouble(&data, result.final_projected_gradient_max_norm);
  AppendAuditDouble(&data, result.initial_scaled_gradient_norm);
  AppendAuditDouble(&data, result.final_scaled_gradient_norm);
  AppendAuditDouble(&data, result.final_radius);
  AppendAuditDouble(&data, result.final_lambda);
  AppendAuditI32(&data, result.trial_iterations);
  AppendAuditI32(&data, result.accepted_steps);
  AppendAuditI32(&data, result.rejected_steps);
  AppendAuditI32(&data, result.invalid_steps);
  AppendAuditI32(&data, result.factorization_failures);
  AppendAuditU64(&data, result.trace.size());
  for (const CudaLmIteration& iteration : result.trace)
    AppendLmIterationDecision(iteration, &data);
  AppendAuditU64(&data, result.runtime.layer_a_calls);
  AppendAuditU64(&data, result.runtime.layer_b_calls);
  AppendAuditU64(&data, result.runtime.layer_c_calls);
  AppendAuditU64(&data, result.runtime.cost_calls);
  AppendAuditU64(&data, result.runtime.actual_trials);
  AppendAuditU64(&data, result.runtime.accepted_trials);
  AppendAuditU64(&data, result.runtime.rejected_trials);
  AppendAuditU64(&data, result.accepted_state_trace.size());
  for (const Snapshot& state : result.accepted_state_trace) {
    AppendAuditString(&data, CudaFinalParametersBitwiseSha256(state));
    AppendAuditString(&data, CudaFinalTopologyBitwiseSha256(state));
  }
  return data;
}

std::string SemanticBitwiseDataV1(const CudaFullLmResult& result) {
  std::string data;
  AppendAuditString(&data, "CudaFullLmSemanticV1");
  AppendAuditBool(&data, result.success);
  AppendAuditU8(
      &data,
      static_cast<uint8_t>(CudaLegacyV1ErrorClassification(result)));
  AppendAuditU8(&data, static_cast<uint8_t>(result.termination_type));
  AppendAuditString(&data, result.termination_reason);
  AppendAuditDouble(&data, result.initial_cost);
  AppendAuditDouble(&data, result.final_cost);
  AppendAuditDouble(&data, result.initial_projected_gradient_max_norm);
  AppendAuditDouble(&data, result.final_projected_gradient_max_norm);
  AppendAuditDouble(&data, result.initial_scaled_gradient_norm);
  AppendAuditDouble(&data, result.final_scaled_gradient_norm);
  AppendAuditDouble(&data, result.final_radius);
  AppendAuditDouble(&data, result.final_lambda);
  AppendAuditI32(&data, result.trial_iterations);
  AppendAuditI32(&data, result.accepted_steps);
  AppendAuditI32(&data, result.rejected_steps);
  AppendAuditI32(&data, result.invalid_steps);
  AppendAuditI32(&data, result.factorization_failures);
  AppendAuditI32(&data, result.accepted_decisions);
  AppendAuditI32(&data, result.accepted_commits);
  AppendAuditI32(&data, result.accepted_pending_preparation_failures +
                            result.accepted_pending_linearization_failures);
  AppendAuditU64(&data, result.runtime.actual_trials);
  AppendAuditU64(&data, result.runtime.accepted_trials);
  AppendAuditU64(&data, result.runtime.rejected_trials);
  AppendAuditU64(&data, result.runtime.final_internal_state_epoch);
  AppendAuditU64(&data, result.trace.size());
  for (const CudaLmIteration& iteration : result.trace) {
    AppendLmIterationDecision(iteration, &data);
    AppendAuditBool(&data, iteration.accepted_decision);
    AppendAuditBool(&data, iteration.accepted_commit_success);
  }
  AppendAuditString(&data,
                    CudaFinalParametersBitwiseSha256(result.final_state));
  AppendAuditString(&data,
                    CudaFinalTopologyBitwiseSha256(result.final_state));
  AppendAuditU64(&data, result.accepted_state_trace.size());
  for (const Snapshot& state : result.accepted_state_trace) {
    AppendAuditString(&data, CudaFinalParametersBitwiseSha256(state));
    AppendAuditString(&data, CudaFinalTopologyBitwiseSha256(state));
  }
  return data;
}

void AppendTransferStructure(const CudaPhaseTiming& phase,
                             std::string* data) {
  AppendAuditU64(data, phase.calls);
  AppendAuditU64(data, phase.bytes);
}

std::string ExecutionStructureDataV1(const CudaFullLmResult& result) {
  const CudaFullLmRuntimeInfo& runtime = result.runtime;
  std::string data;
  AppendAuditString(&data, "CudaFullLmExecutionStructureV1");
  AppendAuditBool(&data, runtime.performance_mode_requested);
  AppendAuditU8(&data, static_cast<uint8_t>(runtime.effective_reduction_mode));
  AppendAuditBool(&data, runtime.instrumentation_effective);
  AppendAuditBool(&data, runtime.current_linearization_cache_requested);
  AppendAuditBool(&data, runtime.current_linearization_cache_effective);
  AppendAuditU64(&data, runtime.layer_a_calls);
  AppendAuditU64(&data, runtime.layer_b_calls);
  AppendAuditU64(&data, runtime.layer_c_calls);
  AppendAuditU64(&data, runtime.cost_calls);
  AppendAuditU64(&data, runtime.build_cuda_layer_a_inputs_count);
  AppendAuditU64(&data, runtime.build_cost_order_count);
  AppendAuditU64(&data, runtime.current_linearization_cache_hits +
                            runtime.current_linearization_cache_misses);
  AppendAuditU64(&data, runtime.current_linearization_cache_hits);
  AppendAuditU64(&data, runtime.current_linearization_cache_misses);
  AppendAuditU64(&data, runtime.current_linearization_build_attempts);
  AppendAuditU64(&data, runtime.current_linearization_build_successes);
  AppendAuditU64(&data, runtime.current_linearization_build_failures);
  AppendAuditU64(&data, runtime.current_linearization_temporary_builds);
  AppendAuditU64(&data, runtime.current_linearization_publishes);
  AppendAuditU64(&data, runtime.current_linearization_replacements);
  AppendAuditU64(&data, runtime.current_linearization_invalidations);
  AppendAuditU64(&data, result.accepted_pending_preparation_failures +
                            result.accepted_pending_linearization_failures);
  AppendAuditU64(&data, runtime.current_linearization_borrows);
  AppendAuditU64(&data, runtime.current_linearization_copies);
  AppendAuditU64(&data, runtime.current_linearization_teardowns);
  AppendAuditU64(&data,
                 runtime.current_linearization_builds_by_state_epoch.size());
  for (uint64_t value : runtime.current_linearization_builds_by_state_epoch)
    AppendAuditU64(&data, value);
  AppendTransferStructure(runtime.timing.h2d_memcpy, &data);
  AppendTransferStructure(runtime.timing.d2h_memcpy, &data);
  AppendTransferStructure(runtime.timing.d2d_memcpy, &data);
  AppendTransferStructure(runtime.timing.managed_prefetch, &data);
  AppendAuditU64(&data, runtime.final_config_generation);
  AppendAuditU64(&data, runtime.final_topology_generation);
  return data;
}

bool SetFirstDifference(const std::string& field,
                        std::string* first_difference) {
  if (first_difference != nullptr) *first_difference = field;
  return false;
}

}  // namespace

bool CudaLegacyV1ComparisonAvailable(const CudaFullLmResult& result) {
  if (result.error_classification == CudaSolveErrorClass::kAuditCapacity) {
    return false;
  }
  const CudaDiagnosticStructureV2& diagnostics =
      result.runtime.diagnostic_structure_v2;
  if (!diagnostics.has_primary) return true;
  switch (diagnostics.primary.failure_site) {
    case CudaFailureSite::kTimingEventAcquire:
    case CudaFailureSite::kTimingEventRecord:
    case CudaFailureSite::kTimingElapsedQuery:
    case CudaFailureSite::kAuditPreflightCapacity:
    case CudaFailureSite::kAuditRuntimeOverflow:
    case CudaFailureSite::kResourceGenerationDoubleAdvance:
      return false;
    default:
      return true;
  }
}

CudaSolveErrorClass CudaLegacyV1ErrorClassification(
    const CudaFullLmResult& result) {
  if (result.error_classification ==
      CudaSolveErrorClass::kAcceptedPendingPreparation) {
    return CudaSolveErrorClass::kAcceptedPendingLinearization;
  }
  if (result.error_classification != CudaSolveErrorClass::kCudaTiming ||
      !result.runtime.diagnostic_structure_v2.has_primary) {
    return result.error_classification;
  }
  switch (result.runtime.diagnostic_structure_v2.primary.failure_site) {
    case CudaFailureSite::kInitialLinearization:
      return CudaSolveErrorClass::kInitialLinearization;
    case CudaFailureSite::kCurrentLinearization:
      return CudaSolveErrorClass::kCurrentLinearization;
    case CudaFailureSite::kAcceptedPendingLinearization:
      return CudaSolveErrorClass::kAcceptedPendingLinearization;
    case CudaFailureSite::kLayerCPointFactor:
    case CudaFailureSite::kLayerCWorkspace:
    case CudaFailureSite::kTrialCost:
      return CudaSolveErrorClass::kCudaStep;
    default:
      return result.error_classification;
  }
}

std::string CudaLegacyV1TerminationReason(
    const CudaFullLmResult& result) {
  return result.termination_reason;
}

std::string CudaFullLmDecisionBitwiseSha256(
    const CudaFullLmResult& result) {
  return Sha256Hex(DecisionBitwiseData(result));
}

std::string CudaFullLmSemanticBitwiseSha256V1(
    const CudaFullLmResult& result) {
  return Sha256Hex(SemanticBitwiseDataV1(result));
}

std::string CudaFullLmExecutionStructureSha256V1(
    const CudaFullLmResult& result) {
  return Sha256Hex(ExecutionStructureDataV1(result));
}

std::string CudaFinalParametersBitwiseSha256(const Snapshot& snapshot) {
  std::string data;
  AppendSnapshotParameters(snapshot, &data);
  return Sha256Hex(data);
}

std::string CudaFinalTopologyBitwiseSha256(const Snapshot& snapshot) {
  std::string data;
  AppendSnapshotTopology(snapshot, &data);
  return Sha256Hex(data);
}

bool CompareCudaFullLmResultsBitwise(const CudaFullLmResult& reference,
                                     const CudaFullLmResult& candidate,
                                     std::string* first_difference) {
  if (first_difference != nullptr) first_difference->clear();
#define COMPARE_FIELD(name)                                                   \
  if (reference.name != candidate.name)                                      \
    return SetFirstDifference(#name, first_difference)
#define COMPARE_DOUBLE_FIELD(name)                                            \
  if (!SameDoubleBits(reference.name, candidate.name))                        \
    return SetFirstDifference(#name, first_difference)
  COMPARE_FIELD(success);
  COMPARE_FIELD(error);
  COMPARE_FIELD(termination_type);
  COMPARE_FIELD(termination_reason);
  COMPARE_DOUBLE_FIELD(initial_cost);
  COMPARE_DOUBLE_FIELD(final_cost);
  COMPARE_DOUBLE_FIELD(initial_projected_gradient_max_norm);
  COMPARE_DOUBLE_FIELD(final_projected_gradient_max_norm);
  COMPARE_DOUBLE_FIELD(initial_scaled_gradient_norm);
  COMPARE_DOUBLE_FIELD(final_scaled_gradient_norm);
  COMPARE_DOUBLE_FIELD(final_radius);
  COMPARE_DOUBLE_FIELD(final_lambda);
  COMPARE_FIELD(trial_iterations);
  COMPARE_FIELD(accepted_steps);
  COMPARE_FIELD(rejected_steps);
  COMPARE_FIELD(invalid_steps);
  COMPARE_FIELD(factorization_failures);
#undef COMPARE_DOUBLE_FIELD
#undef COMPARE_FIELD
  if (reference.trace.size() != candidate.trace.size())
    return SetFirstDifference("trace.size", first_difference);
  for (size_t i = 0; i < reference.trace.size(); ++i) {
    const CudaLmIteration& lhs = reference.trace[i];
    const CudaLmIteration& rhs = candidate.trace[i];
    const std::string prefix = "trace[" + std::to_string(i) + "].";
#define COMPARE_ITER_FIELD(name)                                              \
    if (lhs.name != rhs.name)                                                 \
      return SetFirstDifference(prefix + #name, first_difference)
#define COMPARE_ITER_DOUBLE(name)                                             \
    if (!SameDoubleBits(lhs.name, rhs.name))                                  \
      return SetFirstDifference(prefix + #name, first_difference)
    COMPARE_ITER_FIELD(iteration);
    COMPARE_ITER_DOUBLE(cost_before);
    COMPARE_ITER_DOUBLE(trial_cost);
    COMPARE_ITER_DOUBLE(cost_after);
    COMPARE_ITER_DOUBLE(projected_gradient_max_norm);
    COMPARE_ITER_DOUBLE(scaled_gradient_norm);
    COMPARE_ITER_DOUBLE(radius_before);
    COMPARE_ITER_DOUBLE(radius_after);
    COMPARE_ITER_DOUBLE(lambda_before);
    COMPARE_ITER_DOUBLE(lambda_after);
    COMPARE_ITER_DOUBLE(lm_diagonal_min);
    COMPARE_ITER_DOUBLE(lm_diagonal_max);
    COMPARE_ITER_DOUBLE(predicted_reduction);
    COMPARE_ITER_DOUBLE(actual_reduction);
    COMPARE_ITER_DOUBLE(rho);
    COMPARE_ITER_DOUBLE(function_metric);
    COMPARE_ITER_DOUBLE(parameter_metric);
    COMPARE_ITER_DOUBLE(step_norm);
    COMPARE_ITER_DOUBLE(backward_error);
    COMPARE_ITER_FIELD(factorization_success);
    COMPARE_ITER_FIELD(step_valid);
    COMPARE_ITER_FIELD(trial_finite);
    COMPARE_ITER_FIELD(accepted);
    COMPARE_ITER_FIELD(invalid);
    COMPARE_ITER_FIELD(termination_reason);
#undef COMPARE_ITER_DOUBLE
#undef COMPARE_ITER_FIELD
  }
  if (reference.runtime.layer_a_calls != candidate.runtime.layer_a_calls)
    return SetFirstDifference("runtime.layer_a_calls", first_difference);
  if (reference.runtime.layer_b_calls != candidate.runtime.layer_b_calls)
    return SetFirstDifference("runtime.layer_b_calls", first_difference);
  if (reference.runtime.layer_c_calls != candidate.runtime.layer_c_calls)
    return SetFirstDifference("runtime.layer_c_calls", first_difference);
  if (reference.runtime.cost_calls != candidate.runtime.cost_calls)
    return SetFirstDifference("runtime.cost_calls", first_difference);
  if (reference.runtime.actual_trials != candidate.runtime.actual_trials)
    return SetFirstDifference("runtime.actual_trials", first_difference);
  if (reference.runtime.accepted_trials != candidate.runtime.accepted_trials)
    return SetFirstDifference("runtime.accepted_trials", first_difference);
  if (reference.runtime.rejected_trials != candidate.runtime.rejected_trials)
    return SetFirstDifference("runtime.rejected_trials", first_difference);
  if (reference.accepted_state_trace.size() !=
      candidate.accepted_state_trace.size()) {
    return SetFirstDifference("accepted_state_trace.size", first_difference);
  }
  for (size_t i = 0; i < reference.accepted_state_trace.size(); ++i) {
    if (CudaFinalParametersBitwiseSha256(reference.accepted_state_trace[i]) !=
        CudaFinalParametersBitwiseSha256(candidate.accepted_state_trace[i])) {
      return SetFirstDifference("accepted_state_trace[" + std::to_string(i) +
                                    "].parameters",
                                first_difference);
    }
    if (CudaFinalTopologyBitwiseSha256(reference.accepted_state_trace[i]) !=
        CudaFinalTopologyBitwiseSha256(candidate.accepted_state_trace[i])) {
      return SetFirstDifference("accepted_state_trace[" + std::to_string(i) +
                                    "].topology",
                                first_difference);
    }
  }
  if (CudaFinalParametersBitwiseSha256(reference.final_state) !=
      CudaFinalParametersBitwiseSha256(candidate.final_state)) {
    return SetFirstDifference("final_state.parameters", first_difference);
  }
  if (CudaFinalTopologyBitwiseSha256(reference.final_state) !=
      CudaFinalTopologyBitwiseSha256(candidate.final_state)) {
    return SetFirstDifference("final_state.topology", first_difference);
  }
  if (CudaFullLmDecisionBitwiseSha256(reference) !=
      CudaFullLmDecisionBitwiseSha256(candidate)) {
    return SetFirstDifference("decision_signature", first_difference);
  }
  return true;
}

bool RunCudaCacheSafetySelfTest(std::string* error) {
  if (error == nullptr) return false;
  error->clear();
  int device_count = 0;
  if (cudaGetDeviceCount(&device_count) != cudaSuccess || device_count <= 0) {
    *error = "CUDA cache safety self-test requires one CUDA device";
    return false;
  }
  int original_device = 0;
  cudaGetDevice(&original_device);
  CudaCacheKey current;
  if (!CurrentCudaCacheKey(&current) || current.device < 0) {
    *error = "unable to obtain current CUDA cache key";
    return false;
  }
  CudaCacheKey wrong_device = current;
  wrong_device.device = current.device + 1;
  if (SameCudaCacheKey(current, wrong_device)) {
    *error = "cache key incorrectly matches a different device";
    return false;
  }
  CudaCacheKey wrong_context = current;
  wrong_context.context ^= static_cast<uintptr_t>(0x1);
  if (current.valid && SameCudaCacheKey(current, wrong_context)) {
    *error = "cache key incorrectly matches a different context";
    return false;
  }
  {
    std::lock_guard<std::recursive_mutex> lock(g_cuda_cache_mutex);
    const auto fake_stream = reinterpret_cast<cudaStream_t>(0x1);
    const auto fake_event = reinterpret_cast<cudaEvent_t>(0x2);
    const auto fake_solver = reinterpret_cast<cusolverDnHandle_t>(0x3);
    const auto fake_blas = reinterpret_cast<cublasHandle_t>(0x4);
    g_cached_streams.push_back({fake_stream, current});
    g_cached_events.push_back({fake_event, current});
    g_cached_solvers.push_back({fake_solver, current});
    g_cached_blases.push_back({fake_blas, current});
    const bool stream_isolated = std::none_of(
        g_cached_streams.begin(), g_cached_streams.end(),
        [&](const CachedCudaStream& cached) {
          return SameCudaCacheKey(cached.key, wrong_device);
        });
    const bool event_isolated = std::none_of(
        g_cached_events.begin(), g_cached_events.end(),
        [&](const CachedCudaEvent& cached) {
          return SameCudaCacheKey(cached.key, wrong_device);
        });
    const bool solver_isolated = std::none_of(
        g_cached_solvers.begin(), g_cached_solvers.end(),
        [&](const CachedCudaSolver& cached) {
          return SameCudaCacheKey(cached.key, wrong_device);
        });
    const bool blas_isolated = std::none_of(
        g_cached_blases.begin(), g_cached_blases.end(),
        [&](const CachedCudaBlas& cached) {
          return SameCudaCacheKey(cached.key, wrong_device);
        });
    g_cached_streams.clear();
    g_cached_events.clear();
    g_cached_solvers.clear();
    g_cached_blases.clear();
    if (!stream_isolated || !event_isolated || !solver_isolated ||
        !blas_isolated) {
      *error = "device/context cache isolation probe failed";
      return false;
    }
  }

  std::atomic<int> successes{0};
  std::string first_error;
  std::mutex error_mutex;
  auto worker = [&]() {
    CudaLayerAOptions options;
    options.device = original_device;
    CudaLayerAResult result;
    if (RunCudaLayerA({}, {}, options, &result) && result.success) {
      ++successes;
    } else {
      std::lock_guard<std::mutex> lock(error_mutex);
      if (first_error.empty()) first_error = result.error;
    }
  };
  std::thread first(worker);
  std::thread second(worker);
  first.join();
  second.join();
  cudaSetDevice(original_device);
  if (successes != 2) {
    *error = "concurrent CUDA API serialization probe failed";
    if (!first_error.empty()) *error += ": " + first_error;
    return false;
  }
  return true;
}

bool RunCudaMemoryAccountingSelfTest(std::string* error) {
  if (error == nullptr) return false;
  error->clear();
  constexpr uint64_t kMiB = 1024ull * 1024ull;
  const uint64_t active_bytes = 128 * kMiB;
  const uint64_t cached_bytes = 1024 * kMiB;
  const uint64_t additional_bytes = 64 * kMiB;
  const uint64_t reserve_bytes = 512 * kMiB;
  const uint64_t expected_peak = 1216 * kMiB;
  if (ResidentPeakBytes(active_bytes, cached_bytes, additional_bytes) !=
      expected_peak) {
    *error = "resident peak does not combine same-time active/cache/additional bytes";
    return false;
  }
  if (!HasCudaMemoryHeadroom(576 * kMiB, additional_bytes, reserve_bytes)) {
    *error = "cached bytes were counted against cudaMemGetInfo free bytes twice";
    return false;
  }
  if (HasCudaMemoryHeadroom(576 * kMiB - 1, additional_bytes,
                            reserve_bytes)) {
    *error = "near-budget allocation was not rejected";
    return false;
  }
  if (ResidentPeakBytes(std::numeric_limits<uint64_t>::max(), 1, 1) !=
      std::numeric_limits<uint64_t>::max()) {
    *error = "resident peak overflow was not saturated";
    return false;
  }
  return true;
}

bool RunCudaCleanupFailureSelfTest(const CudaTeardownType teardown_type,
                                   CudaFullLmResult* result,
                                   std::string* error) {
  CudaCacheCallScope cache_scope;
  if (result == nullptr || error == nullptr) return false;
  *result = CudaFullLmResult();
  error->clear();
  int device_count = 0;
  if (cudaGetDeviceCount(&device_count) != cudaSuccess || device_count <= 0 ||
      cudaSetDevice(0) != cudaSuccess) {
    *error = "CUDA cleanup failure self-test requires CUDA device 0";
    return false;
  }
  if (g_cuda_resource_health != CudaResourceHealth::kClean ||
      !g_cuda_taint_cleanup_complete) {
    *error = "cleanup failure self-test did not start from a clean process";
    return false;
  }

  CudaAuditRuntimeScope audit_scope(&result->runtime, CudaFaultTrigger());
  cudaStream_t stream = nullptr;
  cudaEvent_t event = nullptr;
  cusolverDnHandle_t solver = nullptr;
  cublasHandle_t blas = nullptr;
  uint8_t* allocation = nullptr;
  bool initialized = true;
  switch (teardown_type) {
    case CudaTeardownType::kGetDevice:
    case CudaTeardownType::kSetDevice:
      break;
    case CudaTeardownType::kSolver:
      initialized = AcquireCudaSolver(&solver) == CUSOLVER_STATUS_SUCCESS;
      break;
    case CudaTeardownType::kBlas:
      initialized = AcquireCudaBlas(&blas) == CUBLAS_STATUS_SUCCESS;
      break;
    case CudaTeardownType::kEvent:
      initialized = AcquireCudaEvent(&event) == cudaSuccess;
      break;
    case CudaTeardownType::kStream:
      initialized = AcquireCudaStream(&stream) == cudaSuccess;
      break;
    case CudaTeardownType::kAllocation:
      initialized = Allocate(&allocation, 1,
                             CudaMemoryMode::kExplicitDeviceCopy, error);
      break;
  }
  if (!initialized) {
    if (error->empty()) *error = "failed to initialize teardown test resource";
    return false;
  }

  g_cuda_cleanup_test_injection_active = true;
  g_cuda_cleanup_test_injection_type = teardown_type;
  g_cuda_cleanup_test_injection_consumed = false;
  bool cleanup_failed = false;
  switch (teardown_type) {
    case CudaTeardownType::kGetDevice: {
      int device = -1;
      cleanup_failed = CleanupCudaGetDevice(&device) != cudaSuccess;
      break;
    }
    case CudaTeardownType::kSetDevice:
      cleanup_failed = CleanupCudaSetDevice(0) != cudaSuccess;
      break;
    case CudaTeardownType::kSolver:
      cleanup_failed =
          CleanupCudaSolverDestroy(solver, 0) != CUSOLVER_STATUS_SUCCESS;
      break;
    case CudaTeardownType::kBlas:
      cleanup_failed =
          CleanupCudaBlasDestroy(blas, 0) != CUBLAS_STATUS_SUCCESS;
      break;
    case CudaTeardownType::kEvent:
      cleanup_failed = CleanupCudaEventDestroy(event, 0) != cudaSuccess;
      break;
    case CudaTeardownType::kStream:
      cleanup_failed = CleanupCudaStreamDestroy(stream, 0) != cudaSuccess;
      break;
    case CudaTeardownType::kAllocation:
      cleanup_failed = CleanupCudaFree(allocation, 0) != cudaSuccess;
      break;
  }
  g_cuda_cleanup_test_injection_active = false;
  if (!cleanup_failed || !g_cuda_cleanup_test_injection_consumed ||
      g_cuda_resource_health != CudaResourceHealth::kTainted ||
      g_cuda_taint_cleanup_complete) {
    *error = "teardown failure did not taint and quarantine the resource";
    return false;
  }

  result->success = false;
  result->termination_type = CudaTerminationType::kFailure;
  result->error_classification = CudaSolveErrorClass::kResourceCleanup;
  result->termination_reason = "resource_cleanup_failed";
  result->error = "ResourceCleanup: injected teardown wrapper failure";
  result->runtime.final_resource_health = CudaResourceHealth::kTainted;
  result->runtime.resource_cleanup_complete = false;
  result->runtime.resource_cleanup_attempts = 1;
  result->runtime.resource_cleanup_failures = 1;
  const CudaStableDiagnosticV2 diagnostic =
      result->runtime.has_first_cleanup_failure
          ? result->runtime.first_cleanup_failure
          : MakeDiagnostic(CudaSolveErrorClass::kResourceCleanup,
                           CleanupFailureSite(teardown_type),
                           teardown_type == CudaTeardownType::kSolver
                               ? CudaStatusDomain::kCusolver
                               : teardown_type == CudaTeardownType::kBlas
                                     ? CudaStatusDomain::kCublas
                                     : CudaStatusDomain::kCudaRuntime,
                           1);
  RecordDiagnostic(&result->runtime, diagnostic);

  CudaFullLmRuntimeInfo blocked_runtime;
  std::string blocked_error;
  const bool next_generation_started =
      BeginCudaResourceGeneration(&blocked_runtime, false, &blocked_error);
  result->runtime.resource_generation_advance_events =
      blocked_runtime.resource_generation_advance_events;
  result->runtime.resource_generation_advance_violations =
      blocked_runtime.resource_generation_advance_violations;
  result->runtime.resource_generation_advanced_by_this_solve =
      blocked_runtime.resource_generation_advanced_by_this_solve;
  if (next_generation_started ||
      blocked_error.find("CUDA_RESOURCE_CLEANUP_FAILED") == std::string::npos ||
      blocked_runtime.resource_generation_advance_events != 0) {
    *error = "tainted resource generation did not block the next solve";
    return false;
  }
  *error = result->error;
  return true;
}

bool RunCudaAuditStorageSelfTest(std::string* error) {
  if (error == nullptr) return false;
  error->clear();
  CudaFullLmRuntimeInfo runtime;
  runtime.secondary_diagnostic_capacity = 2;
  RecordDiagnostic(
      &runtime,
      MakeDiagnostic(CudaSolveErrorClass::kCurrentLinearization,
                     CudaFailureSite::kCurrentLinearization,
                     CudaStatusDomain::kInjected, 1));
  RecordDiagnostic(
      &runtime,
      MakeDiagnostic(CudaSolveErrorClass::kInitialLinearization,
                     CudaFailureSite::kInitialLinearization,
                     CudaStatusDomain::kInjected, 2));
  RecordDiagnostic(
      &runtime,
      MakeDiagnostic(CudaSolveErrorClass::kAuditCapacity,
                     CudaFailureSite::kAuditRuntimeOverflow,
                     CudaStatusDomain::kInternal, 3));
  RecordDiagnostic(
      &runtime,
      MakeDiagnostic(CudaSolveErrorClass::kResourceCleanup,
                     CudaFailureSite::kDestroyAllocation,
                     CudaStatusDomain::kCudaRuntime, 4));
  RecordDiagnostic(
      &runtime,
      MakeDiagnostic(CudaSolveErrorClass::kCudaTiming,
                     CudaFailureSite::kTimingElapsedQuery,
                     CudaStatusDomain::kCudaRuntime, 5));
  const CudaDiagnosticStructureV2& diagnostics =
      runtime.diagnostic_structure_v2;
  if (!diagnostics.has_primary ||
      diagnostics.primary.error_classification !=
          CudaSolveErrorClass::kResourceCleanup ||
      diagnostics.secondary_count != 2 ||
      !diagnostics.overflow_sentinel_set ||
      diagnostics.diagnostic_overflow_count != 2 ||
      diagnostics.overflow_sentinel.error_classification !=
          CudaSolveErrorClass::kAuditCapacity ||
      diagnostics.overflow_sentinel.failure_site !=
          CudaFailureSite::kAuditRuntimeOverflow) {
    *error = "fixed diagnostic storage priority/overflow invariant failed";
    return false;
  }
  return true;
}

bool TrimIdleCudaRuntimePoolForTesting(std::string* error) {
  if (error == nullptr) return false;
  error->clear();
  std::vector<std::unique_ptr<CudaRuntimePoolEntry>> idle;
  {
    std::lock_guard<std::mutex> lock(g_cuda_runtime_pool_mutex);
    for (auto& item : g_cuda_runtime_pool_idle)
      idle.push_back(std::move(item.second));
    g_cuda_runtime_pool_idle.clear();
  }
  bool success = true;
  for (auto& entry : idle) {
    if (!DestroyRuntimePoolEntry(entry.get())) {
      success = false;
      std::lock_guard<std::mutex> lock(g_cuda_runtime_pool_mutex);
      g_cuda_runtime_pool_poisoned_devices.insert(entry->device);
    }
  }
  if (!success)
    *error = "ResourceCleanup: RuntimePool idle trim failed";
  return success;
}

bool ShutdownCudaRuntimePool(std::string* error,
                             CudaRuntimePoolShutdownInfo* info) {
  if (error == nullptr) return false;
  error->clear();
  if (info != nullptr) *info = CudaRuntimePoolShutdownInfo();
  CudaRuntimePoolShutdownInfo prepared;
  {
    std::lock_guard<std::mutex> lock(g_cuda_runtime_pool_mutex);
    if (!g_cuda_runtime_pool_active.empty()) {
      for (CudaRuntimePoolEntry* entry : g_cuda_runtime_pool_active) {
        if (entry != nullptr)
          g_cuda_runtime_pool_poisoned_devices.insert(entry->device);
      }
      *error = "ResourceCleanup: RuntimePool shutdown has active leases";
      return false;
    }
    prepared.idle_entries_destroyed = g_cuda_runtime_pool_idle.size();
    for (const auto& item : g_cuda_runtime_pool_idle) {
      const CudaRuntimePoolEntry& entry = *item.second;
      prepared.streams_destroyed += entry.stream == nullptr ? 0 : 1;
      for (const cudaEvent_t event : entry.events)
        prepared.events_destroyed += event == nullptr ? 0 : 1;
      prepared.solvers_destroyed += entry.solver == nullptr ? 0 : 1;
      prepared.blases_destroyed += entry.blas == nullptr ? 0 : 1;
      prepared.arenas_destroyed += entry.arena == nullptr ? 0 : 1;
      prepared.arena_bytes_released = SaturatingAdd(
          prepared.arena_bytes_released, entry.arena_capacity);
    }
  }
  const bool success = TrimIdleCudaRuntimePoolForTesting(error);
  if (success && info != nullptr) *info = prepared;
  return success;
}

bool ResetCudaRuntimePoolForTesting(std::string* error) {
  if (!ShutdownCudaRuntimePool(error)) return false;
  std::lock_guard<std::mutex> lock(g_cuda_runtime_pool_mutex);
  g_cuda_runtime_pool_poisoned_devices.clear();
  g_cuda_runtime_pool_clearing_devices.clear();
  g_cuda_runtime_pool_active_by_device.clear();
  return true;
}

bool ResetCudaResourceStateForTesting(std::string* error) {
  CudaCacheCallScope cache_scope;
  if (error == nullptr) return false;
  error->clear();
  g_cuda_cleanup_test_injection_active = false;
  g_cuda_cleanup_test_injection_consumed = false;
  g_cuda_resource_health = CudaResourceHealth::kClearing;
  g_cuda_taint_cleanup_complete = true;
  EnableCudaBufferReuse(false);
  BeginRuntimePoolGlobalClear();
  ClearCudaAllResourceCaches();
  bool active_ownership = false;
  for (uint64_t i = 0; i < g_cuda_resource_registry_count; ++i) {
    active_ownership = active_ownership ||
        g_cuda_resource_registry[static_cast<size_t>(i)].active;
  }
  const bool empty = g_cached_solvers.empty() && g_cached_blases.empty() &&
      g_cached_events.empty() && g_cached_streams.empty() &&
      g_live_solvers.empty() && g_live_blases.empty() &&
      g_live_events.empty() && g_live_streams.empty() &&
      g_cuda_buffer_cache.empty() && g_cuda_live_allocations.empty() &&
      !active_ownership && g_cuda_taint_cleanup_complete;
  if (!empty) {
    g_cuda_resource_health = CudaResourceHealth::kTainted;
    g_cuda_taint_cleanup_complete = false;
    FinishRuntimePoolGlobalClear(false);
    *error = "ResourceCleanup: test reset could not clear quarantined CUDA "
             "resources";
    return false;
  }
  FinishRuntimePoolGlobalClear(true);
  g_cuda_cache_owner_active = false;
  g_cuda_resource_registry_count = 0;
  for (CudaResourceOwnershipEntry& entry : g_cuda_resource_registry)
    entry = CudaResourceOwnershipEntry();
  ++g_cuda_resource_generation;
  g_cuda_resource_lookup_blocked_count = 0;
  g_cuda_active_bytes = 0;
  g_cuda_cached_bytes = 0;
  g_cuda_taint_cleanup_complete = true;
  g_cuda_resource_health = CudaResourceHealth::kClean;
  {
    std::lock_guard<std::mutex> lock(g_cuda_runtime_pool_mutex);
    g_cuda_runtime_pool_poisoned_devices.clear();
    g_cuda_runtime_pool_clearing_devices.clear();
    g_cuda_runtime_pool_active_by_device.clear();
  }
  return true;
}

